local P = LoreForeverPacks.Begin("LoreForever_Lang_ruRU")
P.entries["topic:druid"] = {n="Друид",s="Друиды — стражи мира природы, черпающие силу непосредственно у диких духов, небесных тел и Изумрудного Сна. Мастера превращений, они принимают облик первобытных зверей, чтобы защищать землю или исцелять тяжелые раны. Этим путем идут в основном ночные эльфы, а недавно он возродился и среди тауренов; друиды ставят сохранение природы выше любых смертных союзов.",h="Друиды — стражи мира природы, черпающие силу непосредственно у диких духов, небесных тел и Изумрудного Сна.",kw={"bear form","cat form","cenarion circle","cenarius","druid","emerald dream","hamuul","malfurion","moonglade","shapeshifter","облик медведя","облик кошки","круг кенария","кенарий","друид","изумрудный сон","хамуул","малфурион","лунная поляна","оборотень"},ang={["class:Druid"]="Как защитник равновесия, друид идет по тонкой грани между звериной яростью, исцеляющей магией жизни и небесным разрушением, черпая мудрость непосредственно у Кенария и в Изумрудном Сне.",["race:NightElf"]="Десять тысячелетий друиды-кальдораи были тихими спящими стражами Калимдора, поддерживая равновесие природы под руководством Малфуриона Ярость Бури и полубога Кенария.",["race:Tauren"]="Под руководством верховного друида Хамуула Рунического Тотема таурены возродили древнюю связь с природой, вступив в Круг Кенария в священной Лунной поляне, чтобы идти путем Матери-Земли."},sec={{t="Стражи дикой природы",b="Друидизм — гораздо больше, чем боевое искусство: это древний образ жизни, уходящий корнями в глубокое единение с природой и полубогом Кенарием. Друиды владеют необузданными силами природы: повелевают корнями, опутывающими врагов, направляют небесное сияние луны и звезд и призывают целительную флору, чтобы срастить кости и плоть. Их долг — хранить космическое равновесие и защищать нетронутую природу от эксплуатации и порчи."},{t="Дар превращений",b="Отличительная черта друида — сверхъестественное искусство превращений. Благодаря духовной преданности друиды направляют первобытные начала зверей Азерота. Они обретают толстую шкуру медведя, чтобы выдержать сокрушительные удары, принимают гибкий облик хищной кошки, чтобы нападать из тени, или водные и птичьи формы, чтобы пересекать моря и небеса. В превращении их звериные пасти редко способны произносить слова смертных, но физическая мощь сравнима с главными хищниками дикой природы."},{t="Круг Кенария",b="Десять тысяч лет назад Кенарий впервые обучил друидизму Малфуриона Ярость Бури, а позднее смертный друидизм оформился в Круг Кенария. Круг, чья штаб-квартира находится в священной Лунной поляне, надзирает за друидическими практиками по всему Калимдору, оставаясь независимым от смертных фракций и политических дрязг. Долгое время в нем доминировали только ночные эльфы-мужчины, веками дремавшие в Изумрудном Сне, но после Третьей войны в него приняли и ночных эльфиек, и тауренов."}},faq={{q="Кто был первым смертным друидом?",a="Малфурион Ярость Бури был первым смертным, освоившим искусства друидов под непосредственным руководством полубога Кенария примерно десять тысяч лет назад, до Войны Древних.",al={"first druid","who founded druidism","malfurion first druid","первый друид","кто основал друидизм","малфурион первый друид"}},{q="Как таурены могут стать друидами?",a="После Третьей войны предводитель тауренов Хамуул Рунический Тотем подружился с Малфурионом Ярость Бури и изучил пути природы, став первым тауреном-друидом почти за двадцать поколений. Несмотря на протесты Фэндрала Оленьего Шлема, Хранитель Ремулос принял тауренов в Круг Кенария.",al={"tauren druid lore","why are tauren druids","hamuul runetotem druid","предания о друидах тауренах","почему таурены друиды","хамуул рунический тотем друид"}},{q="Что такое Круг Кенария?",a="Круг Кенария — орден друидов Азерота, основанный, чтобы упорядочить дикие практики и защищать природу. Он действует независимо как от Альянса, так и от Орды; его члены подчиняются верховным друидам Круга и мирно собираются в священной Лунной поляне.",al={"cenarion circle lore","what is moonglade order","предания о круге кенария","что за орден лунной поляны"}},{q="Могут ли друиды говорить в звериной форме?",a="Как правило, нет. В облике зверя голосовой аппарат друида соответствует животному, поэтому обычная речь смертных невозможна, хотя немногие редкие, исключительно могущественные друиды нашли магические способы обойти это ограничение.",al={"can druids talk in bear form","shapeshift talking lore","могут ли друиды говорить в облике медведя","речь в звериной форме"}},{q="Что такое Изумрудный Сон?",a="Изумрудный Сон — цветущий нетронутый мир, отражающий Азерот таким, словно цивилизация никогда его не касалась. Друиды-ночные эльфы надолго погружались в многовековую спячку, чтобы бродить по его тропам и общаться с духами природы.",al={"emerald dream lore","where do druids sleep","изумрудный сон","где спят друиды"}},{q="Почему друиды изначально спали веками?",a="После благословения Мирового Древа Нордрассила друиды-ночные эльфы уходили в Берлоги и веками бродили по Изумрудному Сну, помогая зеленому драконьему роду Изеры взращивать духовную экосистему Азерота, пока Третья война не заставила их пробудиться.",al={"druid hibernation","barrow dens sleeping","long slumber","спячка друидов","сон в берлогах","долгий сон"}}},fp="5,382,20.432.0,25.508.0,19.487.0,31.183.0,29.291.0,28.270.0,38.242.0,26.232.0,50.252.0"}
P.entries["topic:druids-of-the-fang"] = {n="Друиды Клыка",s="Друиды Клыка — отколовшаяся секта друидов-ночных эльфов, поддавшихся порче в глубинах Пещер Стенаний. Изначально они были учениками дальновидного верховного друида Наралекса, но покинули Круг Кенария, когда связь их наставника с Изумрудным Сном превратилась в отвратительный кошмар. Теперь под началом самопровозглашенного лорда Серпентиса они принимают змееподобные облики и стремятся превратить Степи в свой собственный извращенный рай.",h="Друиды Клыка — отколовшаяся секта друидов-ночных эльфов, поддавшихся порче в глубинах Пещер Стенаний.",kw={"barrens","druids of the fang","emerald dream","hamuul runetotem","naralex","nightmare","serpentis","snake form","wailing caverns","степи","друиды клыка","изумрудный сон","хамуул рунический тотем","наралекс","кошмар","серпентис","змеиный облик","пещеры стенаний"},ang={["class:Druid"]="Друиды Клыка воплощают страшную угрозу порчи Изумрудного Сна и показывают, что бывает, когда друид отказывается от гармонии Кенария ради извращенных, неортодоксальных звериных обликов.",["race:NightElf"]="Видеть, как братья-кальдораи вырождаются в одичавший, терзаемый кошмарами змеиный культ в сердце Калимдора, — горькая печаль и позор для традиций ночных эльфов.",["race:Tauren"]="Верховный друид Хамуул Рунический Тотем и друиды-таурены Громового Утеса всерьез стремятся покончить с угрозой Клыка, считая осквернение вод Степей оскорблением Матери-Земли."},sec={{t="Благородная мечта, ставшая ядом",b="Степи не всегда были засушливой пустошью, и верховный друид Наралекс стремился вернуть им облик цветущего зеленого убежища, каким они были когда-то. Наралекс повел преданный орден молодых друидов в подземные глубины Пещер Стенаний, использовав природные подземные трещины и источники. Погрузившись в наведенный сон, Наралекс надеялся направить живую энергию Изумрудного Сна в водные потоки и вернуть к жизни выжженную саванну наверху."},{t="Падение в кошмар",b="Во время транса Наралекса что-то пошло ужасно не так. Вместо безмятежной чистоты Изумрудного Сна в его дрему проник злобный, извивающийся кошмар. Эта тьма просочилась по пещерам, быстро искажая обитавших там животных и отравляя подземные источники. Вместо того чтобы бежать за помощью к Кругу Кенария, ученики Наралекса были сломлены влиянием кошмара, а их разум и дух изменялись вместе с подземной экосистемой."},{t="Возвышение Клыка",b="Лучший ученик Наралекса, прежде усердный, отбросил первоначальные наставления учителя и принял порчу, назвавшись лордом Серпентисом. Сплотив павших учеников в Друидов Клыка, Серпентис перенял первобытные ядовитые облики гадюк и змей вместо привычных обликов медведя и кошки, одобренных Кенарием. Культ фактически заточил своего спящего верховного друида, намереваясь питаться его кошмаром, чтобы жестоко переделать Степи в собственный рай под властью змей."}},faq={{q="Кто такие Друиды Клыка?",a="Это оскверненный орден друидов-ночных эльфов, вошедший в Пещеры Стенаний вместе с верховным друидом Наралексом. Вместо исцеления Степей они сошли с ума, когда транс Наралекса затронул темный кошмар, и превратились в фанатичных отступников, поклоняющихся змеям.",al={"druids of the fang lore","who are the fang druids","wailing caverns druids","друиды клыка предания","кто такие друиды клыка","друиды пещер стенаний"}},{q="Зачем они изначально вошли в Пещеры Стенаний?",a="Наралекс и его ученики хотели использовать богатые подземные источники пещер. Направив живительную силу Изумрудного Сна в водную систему, они надеялись превратить засушливые Степи обратно в цветущий зеленый лес.",al={"why are they in wailing caverns","naralex goal","why heal the barrens","зачем они в пещерах стенаний","цель наралекса","зачем исцелять степи"}},{q="Кто возглавляет Друидов Клыка?",a="Их возглавляет лорд Серпентис. Некогда первый и самый способный ученик верховного друида Наралекса, Серпентис полностью впал в безумие, когда ударил кошмар, и объявил себя главой новообразованных Друидов Клыка.",al={"leader of the fang","lord serpentis lore","who leads them","глава клыка","лорд серпентис предания","кто ими руководит"}},{q="Какие звериные облики они принимают?",a="В отличие от обычных друидов Круга Кенария, принимающих облик медведей, кошек или воронов бури, Друиды Клыка обращаются к ядовитым змеям и гадюкам, используя змеиную магию и свирепые превращения в змей.",al={"snake form druids","fang druid shapeshift","serpent form","друиды змеи","превращение друидов клыка","облик змеи"}},{q="Как Круг Кенария относится к ним?",a="Круг Кенария считает Друидов Клыка опасным отклонением и культом. Такие лидеры, как верховный друид Хамуул Рунический Тотем, и оставшиеся верными соратники Наралекса спешно стараются уничтожить предводителей Клыка и очистить землю от порчи, пока она не уничтожила ее.",al={"cenarion circle opinion","are they part of the cenarion circle","hamuul on the fang","мнение круга кенария","входят ли они в круг кенария","хамуул о клыке"}},{q="Что случилось с Наралексом?",a="Наралекс остается в плену глубокого мучительного сна в сердце Пещер Стенаний. Ученики держат его взаперти, используя его непрекращающийся кошмар как источник силы, чтобы искажать пещеры и собственную магию.",al={"is naralex dead","naralex status","where is naralex","наралекс мертв","судьба наралекса","где наралекс"}}},fp="18,438,31.478.0,22.515.1,18.522.1,31.269.0,50.231.0,33.224.0,31.222.0,39.267.0,25.215.0"}
P.entries["topic:dwarf"] = {n="Дворф",s="Дворфы — коренастая выносливая раса, происходящая от рожденных из живого камня древних земельников, созданных титанами, и ныне населяющая заснеженные горные королевства Каз Модана и другие земли. Известные мастерством в обработке камня, металлургии и сокрушительном бое в первых рядах, они — одна из самых грозных и надежных опор Альянса. Под властью короля Магни Бронзоборода их огромная подземная столица Стальгорн служит сердцем общества дворфов.",h="Дворфы — коренастая выносливая раса, происходящая от рожденных из живого камня древних земельников, созданных...",kw={"bronzebeard","dark iron","dun morogh","dwarf","dwarves","earthen","ironforge","khaz modan","magni","uldaman","wildhammer","бронзобород","черное железо","дун морог","дворф","дворфы","земельники","стальгорн","каз модан","магни","ульдаман","громовой молот"},ang={["class:Paladin"]="Паладины-дворфы несут Свет с твердостью горной породы, сочетая человеческое богословие с несокрушимой воинской дисциплиной Каз Модана.",["faction:Alliance"]="Огромные минеральные богатства Стальгорна, непревзойденная осадная инженерия и стойкая пехота образуют северный оплот Альянса.",["profession:Blacksmithing"]="Дворфы славятся как лучшие кузнецы Азерота и используют вулканический жар Великой кузни, чтобы закалять легендарное оружие и доспехи.",["profession:Mining"]="Рожденные из живого камня, дворфы обладают врожденным чутьем на жилы богатой руды и древние самоцветы, скрытые в подземных глубинах.",["race:Dwarf"]="Каждый дворф несет груз наследия рожденных камнем, пробираясь через древние кровные распри кланов и раскапывая тайны титанов, определяющие само ваше существование.",["race:Gnome"]="Дворфы — ваши старейшие и вернейшие союзники: они помогли возвести первые каменные постройки Гномрегана, а теперь предлагают вашему народу убежище в Городе механиков."},sec={{t="Сыны горы",b="Давным-давно подземные земельники, созданные титанами, пробудились от многовекового сна в хранилищах Ульдамана, превратившись под действием Проклятия плоти в существ из крови и костей. Назвавшись дворфами, они заняли высокие кряжи Каз Модана, названного в честь титана Каз'горота, и высекли величественную подземную твердыню Стальгорн под вершинами Дун Морога. Наделенные невероятной выносливостью, острым глазом на камень и руду, любовью к жарким очагам и крепкому элю, дворфы с одинаковым упорством относятся и к ремеслу, и к войне."},{t="Война трех молотов",b="Единство дворфов рухнуло несколько веков назад после смерти верховного короля Модимуса Старой Наковальни. В Стальгорне вспыхнула гражданская война между тремя враждующими сторонами: кланом Бронзобородов, кланом Громового Молота и кланом Черного Железа. После того как Бронзобороды захватили гору и изгнали сородичей, чародей-тан Тауриссан из дворфов Черного Железа начал губительную войну мести против обоих соперников. Доведенный до отчаяния под Красногорьем, Тауриссан случайно призвал Рагнароса Повелителя Огня, который испепелил его собственные владения, обратив их в вулканические пустоши Тлеющего ущелья и Пылающих степей. Выжившие дворфы Черного Железа были порабощены под Черной горой, а разбитые Громовые Молоты ушли на север, в Заоблачный Пик во Внутренних землях."},{t="Неколебимый щит Альянса",b="Когда орочья Орда хлынула через континент во время Второй войны, король Магни Бронзобород запер ворота Стальгорна против жестоких осад, а войска дворфов взялись за оружие вместе с Альянсом Лордерона. Прославленные тяжелыми латными доспехами, смертоносными мушкетами и бесстрашными наездниками на грифонах, воины-дворфы сыграли важную роль в разгроме Орды. Сегодня королевство Стальгорн остается одним из самых стойких защитников Альянса, принимая в своих залах изгнанных сородичей-гномов и деятельно раскапывая руины титанов Каз Модана, чтобы разгадать тайны своего древнего происхождения."}},faq={{q="Откуда изначально произошли дворфы?",a="Дворфы происходят от земельников — древней расы существ из живого камня, созданных хранителями-титанами. Запечатанные в подземных хранилищах Ульдамана, земельники на протяжении тысячелетий поддались Проклятию плоти и пробудились смертными дворфами, которые затем отправились заселять горы Каз Модана.",al={"dwarf origin","dwarf lore","how were dwarves made","earthen","происхождение дворфов","предания о дворфах","как появились дворфы","земельники"}},{q="Кто сейчас правит дворфами?",a="Король Магни Бронзобород правит королевством Стальгорн и кланом Бронзобородов из Великой кузни. Он провел свой народ через Вторую и Третью войны и остается одним из главных столпов-основателей Великого Альянса.",al={"who is dwarf king","dwarf leader","king of ironforge","magni bronzebeard","кто король дворфов","вождь дворфов","король стальгорна","магни бронзобород"}},{q="Каковы три главных клана дворфов?",a="Три главных клана — Бронзобороды, правящие Стальгорном и Дун Морогом; Громовые Молоты, живущие под открытым небом Внутренних земель и летающие на грифонах; и дворфы Черного Железа, обитающие глубоко под Черной горой во власти огненного владычества Рагнароса.",al={"dwarf clans","three hammers","bronzebeard wildhammer dark iron","clans of ironforge","кланы дворфов","три молота","бронзобород громовой молот черное железо","кланы стальгорна"}},{q="Почему дворфы Черного Железа — враги?",a="Во время Войны трех молотов дворфы Черного Железа пытались уничтожить кланы Бронзобородов и Громового Молота. Перед лицом поражения их чародей-тан призвал Рагнароса Повелителя Огня, который разрушил их родину и обрек клан на рабство у стихийного огня и тени под Черной горой.",al={"why are dark irons evil","dark iron clan lore","shadowforge city dwarves","почему дворфы черного железа злые","предания клана черного железа","дворфы города горнила теней"}},{q="Почему гномы живут в Стальгорне?",a="Дворфов и гномов связывает тесная дружба с их первой встречи много веков назад: они обменивались секретами обработки камня на механическую инженерию. Когда Гномреган пал из-за вторжения троггов и токсичного излучения, король Магни предоставил главному механику Гелбину Меггакруту и его беженцам убежище в Городе механиков.",al={"why are gnomes in ironforge","ironforge gnomes","what happened to gnomeregan","почему гномы в стальгорне","гномы стальгорна","что случилось с гномреганом"}},{q="Поклоняются ли дворфы Свету?",a="Да. Первые экспедиции людей из Араторской империи принесли дворфам учение о Свете много веков назад. Дворфы приняли его всей душой, создав ордены паладинов и священников, чья преданность не уступает Лордерону и Штормграду.",al={"dwarf religion","dwarves holy light","do dwarves believe in the light","религия дворфов","дворфы свет","верят ли дворфы в свет"}}},fp="5,471,20.582.0,28.742.0,32.603.0,43.312.0,32.224.0,38.259.0,38.306.0,39.297.0,34.261.0"}
P.entries["topic:earth-mother"] = {n="Мать-Земля",s="Мать-Земля — верховное милосердное божество-создательница, которому поклоняются таурены; они почитают ее как живое воплощение и зодчего земель и стихий Азерота. По мифам тауренов, она создала горы, равнины и времена года, а затем принесла в жертву свое физическое тело, чтобы защитить смертных детей от темного шепота, поднимавшегося из глубин земли. Ее присутствие пронизывает повседневную культуру тауренов: оно направляет их почтение к природе, долг перед стихиями и надежды на загробную жизнь.",h="Мать-Земля — верховное милосердное божество-создательница, которому поклоняются таурены; они почитают ее как...",kw={"an'she","creation","earth mother","earthmother","lo'sho","mu'sha","mulgore","shu'halo","tauren","ан'ше","сотворение","мать-земля","ло'шо","му'ша","мулгор","шу'хало","таурены"},ang={["class:Druid"]="Друиды-таурены видят свою священную связь с природой как прямое единение с живым телом Матери-Земли, отвечая на ее древний зов хранить равновесие земель.",["class:Shaman"]="Шаманы-таурены чтят Мать-Землю наряду с духами стихий, помня, что ветер, вода, огонь и камень были ее первыми спутниками.",["faction:Horde"]="Благодаря союзу с Мулгором орки и тролли джунглей познакомились с почитанием Матери-Земли у тауренов и часто призывают ее имя как почтительное благословение.",["race:Tauren"]="Каждая сторона общества шу'хало — от уважения кочевника к добыче до совета вождей — коренится в законе, жертве и неугасающей любви Матери-Земли."},sec={{t="Заря творения",b="Мифы тауренов о сотворении гласят, что еще до появления дня и ночи Мать-Земля в одиночестве противостояла пустоте, и ее не касался шепчущий мрак Древних, заточенных под поверхностью. Чтобы создать безопасное пристанище для будущих детей, она занялась созданием Азерота. Когда она провела ногтями по только что поднятым горам, вспыхнули первые в мире огни, а ее руки вырезали русла рек и океанские впадины. Ее смех дал дыхание ветру, а подняв первобытные туманы в небо, она создала первые дожди, из-за которых из почвы пробились трава, леса и злаки."},{t="Солнце, луна и шу'хало",b="При помощи дружественных стихий Мать-Земля произвела на свет близнецов: Ан'ше, солнце, и Му'ша, луну. Чтобы отдохнуть и при этом уберечь их, она поместила сияющих близнецов в свои глаза, и, когда она открывала и закрывала каждое веко, возникали день, ночь и смена времен года. Позже она прижала сердце к плодородной земле и вдохнула в нее песнь жизни, создав шу'хало, первых тауренов. Близнецам и стихиям она поручила научить юных смертных охотиться, строить, танцевать и жить в согласии с дикой природой."},{t="Великая скорбь и жертва",b="Пока Мать-Земля спала, теневые Древние проникли в сердца некоторых тауренов и научили их ненависти, насилию и войне. Опустошенная порчей своих детей, она проронила единственную слезу, ставшую Ло'шо, Синим Дитятей. Опасаясь, что однажды сама падет во тьму, она вырвала Ан'ше и Му'ша из своих глаз, чтобы их никогда не коснулась скверна, и забросила их в небо, чтобы они присматривали за землей. Затем она распростерлась по миру, вросла своей сутью в почву, чтобы навеки удержать тени в плену, и пожертвовала подвижностью, чтобы шу'хало могли выжить."},{t="Живое наследие",b="Хотя Мать-Земля отказалась от физического присутствия, таурены верят, что ее дух по-прежнему оберегает Азерот. Ее слух настроен на ветры, и она слышит молитвы своих детей, а ее сердце бьется в глубине камня. Охотники, шаманы и друиды-таурены обращают благодарность к ней за каждую добычу и каждый урожай, веря, что вся жизнь происходит из ее объятий и что дух каждого таурена после смерти возвращается в ее землю."}},faq={{q="Кто такая Мать-Земля?",a="Мать-Земля — милосердное божество-создательница, находящееся в центре религии тауренов. Согласно их мифам, она создала физический облик земель Азерота, родила солнце и луну и сотворила народ тауренов из почвы.",al={"what is the earth mother","earthmother lore","tauren god","что такое мать-земля","предания о матери-земле","бог тауренов"}},{q="Что за глаза у нее на небе?",a="Ее правый глаз — Ан'ше, солнце, несущее миру свет и тепло. Ее левый глаз — Му'ша, Белая Госпожа луна, несущая мир и сон. Миф тауренов гласит, что она вырвала их со лба и поместила на небеса, чтобы защитить от порчи.",al={"anshe and musha","tauren sun and moon","earth mother eyes","ан'ше и му'ша","солнце и луна тауренов","глаза матери-земли"}},{q="Что такое Синее Дитя в мифах тауренов?",a="Синее Дитя, известное как Ло'шо, — меньшее небесное тело Азерота. Мифология тауренов гласит, что оно родилось из единственной сияющей слезы, которую Мать-Земля проронила, увидев, как ее дети поддаются оскверняющему шепоту Древних богов.",al={"losho","blue moon tauren","earth mother tear","ло'шо","синяя луна тауренов","слеза матери-земли"}},{q="Реальна ли Мать-Земля как живое существо?",a="Для тауренов она — деятельная, любящая духовная реальность, чья суть пронизывает мир природы, камень и ветры. Шаманы и друиды направляют природных и стихийных духов через ее благословения, хотя была ли она первобытным великаном, душой мира или аллегорией, остается вопросом веры.",al={"is earth mother real","does earth mother exist","who is the earthmother","существует ли мать-земля","реальна ли мать-земля","кто такая мать-земля"}},{q="Поклоняются ли Матери-Земле другие расы?",a="Хотя таурены — ее главные почитатели, ее признают и другие народы, общающиеся с землей. Некоторые шаманы-орки и кентавры с уважением призывают ее имя, а ее благословения часто звучат по всей Орде.",al={"orcs earth mother","who worships earth mother","do trolls believe in earth mother","орки мать-земля","кто поклоняется матери-земле","верят ли тролли в мать-землю"}},{q="Во что верят таурены о том, что происходит после смерти?",a="Таурены верят, что, поскольку все живое родилось от любящего прикосновения Матери-Земли, каждая душа после смерти возвращается к ней. Традиционные обряды предают умерших земле в надежде, что их духи упокоятся в ее вечных объятиях.",al={"tauren afterlife","tauren burial beliefs","returning to the earth mother","загробная жизнь тауренов","погребальные верования тауренов","возвращение к матери-земле"}}},fp="12,477,20.561.0,27.543.0,30.582.0,13.424.0,24.227.0,29.261.0,38.237.0,44.296.0,40.226.0,43.253.0"}
P.entries["topic:elemental-plane"] = {n="Элементальный План",s="Элементальный План — взаимосвязанное карманное измерение, созданное порожденными титанами Хранителями, чтобы заточить хаотичных элементалей Азерота. Он разделен на четыре области — Небесную высь, Подземную твердь, Бездонную пучину и Огненные Просторы — и удерживает первичных духов вдали от мира смертных. Хотя он был запечатан давно, трещины в его границах допускают яростные вторжения элементалей и катастрофические призывы в Азерот.",h="Элементальный План — взаимосвязанное карманное измерение, созданное порожденными титанами Хранителями, чтобы...",ang={["class:Mage"]="Призыв элементальных помощников требует доступа к периферийной энергии этих далеких миров и строгого контроля, чтобы не разорвать более широкие бреши в материальный мир.",["class:Shaman"]="Шаманы ищут гармонии с духами, чьи древние правители остаются заточенными за завесой. Понимание разделения между Азеротом и Элементальным Планом — ключ к тому, почему хаотичные стихии обрушиваются на призвавших.",["race:Dwarf"]="Мрачная история клана Черного Железа служит суровым предостережением о том, что бывает, когда смертное честолюбие прорывает Элементальный План, чтобы призвать таких существ, как Рагнарос.",["race:Skyborne"]="Остров Зефрис парит в огромных просторах Небесной выси, служа убежищем в ветреной области Элементального Плана."},sec={{t="Тюрьма для первозданного хаоса",b="In the ancient days following the fall of the Old Gods, the titan-forged Keepers faced a dilemma: Azeroth's chaotic elementals could not truly be destroyed, as their essences were fundamentally tied to the world. Highkeeper Ra and the sorceress Helya devised an enduring solution by weaving an isolated pocket dimension known as the Elemental Plane. Within it, they crafted four interlinked domains tailored to each primal force: Skywall for air, Deepholm for earth, the Abyssal Maw for water, and the Firelands for fire. The elemental lords and their myriad servants were banished into this realm, and powerful wards were set to sever the prison from the material world, allowing Azeroth's surface to finally know peace."},{t="Бесконечная борьба",b="Изгнание не усмирило ярость элементалей. Запертые в своих карманных измерениях, первичные силы вели друг с другом бесконечные войны. Самый страшный конфликт, Раскол стихий, столкнул области огня и воздуха в войне, бушевавшей тысячелетиями в сердце их тюрьмы. Тем временем горстка элементалей, оставшихся в Азероте, со временем утратила свою огненную буйность, и их облик смягчился, превратившись в существ из плоти и крови."},{t="Прорыв защитных чар",b="Преграды, отделяющие Азерот от Элементального Плана, прочны, но не нерушимы. Две сотни лет назад, в отчаянной кульминации Войны трех молотов, чародей-тан Тауриссан прорвал завесу и призвал Рагнароса Повелителя Огня из Огненных Просторов — апокалиптическое событие, расколовшее Красногорье и создавшее Черную гору. В последнее время по всему Калимдору открылись нестабильные трещины. Межмировые разломы раз за разом появляются в Силитусе, Кратере Ун'Горо, Азшаре и Зимних Ключах, изрыгая волны враждебных элементалей, жаждущих испытать оборону мира смертных."}},faq={{q="Что такое Элементальный План?",a="Элементальный План — искусственное карманное измерение, созданное порожденными титанами, чтобы удерживать хаотичных элементалей Азерота. Он состоит из четырех областей, соответствующих четырем основным стихиям: Небесная высь для воздуха, Подземная твердь для земли, Бездонная пучина для воды и Огненные Просторы для огня.",al={"what is elemental plane","elemental plane explained","elemental realms","что такое элементальный план","элементальный план простыми словами","миры стихий"}},{q="Кто создал Элементальный План и зачем?",a="Highkeeper Ra and the sorceress Helya crafted the Elemental Plane after the war with the Old Gods. Because the elementals were bound directly to Azeroth and would simply reform if slain, the Keepers imprisoned them within this separate dimension so nature on the surface could flourish in peace.",al={"who made elemental plane","why was elemental plane made","how was elemental plane made","кто создал элементальный план","зачем создан элементальный план","как создан элементальный план"}},{q="Каковы четыре области Элементального Плана?",a="Четыре связанные области — Небесная высь (царство воздуха), Подземная твердь (царство земли), Бездонная пучина (царство воды) и Огненные Просторы (царство огня). Каждая область создана как идеальный дом и тюрьма для своих духов стихий.",al={"four elemental planes","elemental domains","names of elemental realms","четыре элементальных плана","области стихий","названия миров стихий"}},{q="Могут ли существа путешествовать между Азеротом и Элементальным Планом?",a="Путь между мирами строго закрыт древними защитными чарами, но могущественное колдовство и нестабильность измерений могут создавать бреши. Смертные чародеи призывали существ сквозь завесу, как Тауриссан призвал Рагнароса, а нестабильные разломы периодически раскрываются в отдаленных областях Калимдора.",al={"portal to elemental plane","visiting elemental plane","how to get to elemental plane","портал в элементальный план","посещение элементального плана","как попасть в элементальный план"}},{q="Почему элементали вторгаются в Калимдор сейчас?",a="Периодические вторжения начали вспыхивать в Силитусе, Кратере Ун'Горо, Азшаре и Зимних Ключах. Порталы, разрывающие завесу, позволяют волнам захватчиков из Элементального Плана проникать на территорию смертных, пока их не отбросят защитники Орды и Альянса.",al={"elemental invasions","why are elementals attacking","elemental rifts kalimdor","вторжения элементалей","почему элементали нападают","разломы элементалей калимдор"}},{q="Как Черная гора была создана Элементальным Планом?",a="Во время Войны трех молотов чародей-тан Тауриссан попытался призвать огненную силу, чтобы спасти свой клан. Он случайно открыл врата в Огненные Просторы и выдернул Рагнароса в Азерот. Взрывное появление Повелителя огня разрушило окрестные горы и образовало Пылающие степи, Тлеющее ущелье и Черную гору.",al={"thaurissan ragnaros","creation of blackrock mountain","how did ragnaros get here","тауриссан рагнарос","создание черной горы","как рагнарос попал сюда"}}},fp="15,413,29.721.0,14.499.0,19.599.0,28.303.0,40.295.0,42.255.0,61.300.0,47.273.0,48.347.0"}
P.entries["topic:elune"] = {n="Элуна",s="Элуна — почитаемая богиня луны Азерота, которой поклоняются главным образом ночные эльфы как своей милосердной защитнице и матери полубога леса Кенария. Она связана с большей из лун, Белой Госпожой, и управляет покоем, исцелением и лунным гневом по всему миру. В мифах таурен ее чтят как Му'ша, мягкий левый глаз Матери-Земли.",h="Элуна — почитаемая богиня луны Азерота, которой поклоняются главным образом ночные эльфы как своей...",kw={"cenarius","elune","mother moon","mu'sha","night warrior","sisterhood of elune","tyrande","white lady","кенарий","элуна","мать луна","му'ша","ночная воительница","сестринство элуны","тиранда","белая госпожа"},ang={["class:Druid"]="Как божественная мать повелителя Кенария, небесное влияние Элуны напрямую вплетено в ваши астральные силы и древнее родство с живой природой.",["class:Priest"]="Жрецы ночных эльфов черпают божественные заклинания и небесную ярость прямо из наставлений Элуны, владея сияющим лунным светом, а не священным светом, которому поклоняются в восточных королевствах.",["race:NightElf"]="Каждая черта цивилизации кальдораев — от правящего Сестринства до лунного света, озаряющего ваши лесные поселения, — проистекает из вашей вечной преданности Матери Луне.",["race:Tauren"]="Луна на ночном небе — это Му'ша, левый глаз Матери-Земли, которую в ваших древних мифах славят за то, что она оберегает племена и существ тьмы."},sec={{t="Белая Госпожа",b="Элуна — одно из немногих истинных божеств, признаваемых по всему Азероту, неразрывно связанное с ночным небом и большей из двух лун мира, Белой Госпожой. Хотя она никогда не являлась в мире во плоти, ночные эльфы-мастера изображают ее в облике кальдорай неземной грации, окутанной сиянием, с алебастровой кожей, серебряными волосами и глазами из чистого лунного света. Древние предания кальдораев гласят, что днем она покоилась в глубинах Источника Вечности, шепча мудрость первым ночным эльфам и обучая их языку мира."},{t="Сестры и лес",b="Духовная и гражданская жизнь ночных эльфов основана на преданности Элуне через Сестринство Элуны — древнее матриархальное жречество во главе с верховной жрицей Тирандой Шелест Ветра. Сестры призывают милость Элуны, чтобы исцелять смертельные раны, но могут и направить ее сияющий гнев, обрушивая на врагов жгучий звездный свет. Ее божественный союз с Великим Белым Оленем Мал'орном породил Кенария и напрямую связал небесные тайны Элуны с друидическими традициями, оберегающими дикие земли Калимдора."},{t="Ипостаси и имена",b="Хотя Элуна славится миролюбием, гармонией и безмятежным исцелением, она не кроткая пацифистка. Как Ночная Воительница, она — свирепая покровительница битвы: собирает духов павших героев с поля боя и помещает их на небеса, где они мчатся по ночному небу звездами. Помимо кальдораев, кочевые таурены знают ее как Му'ша, сияющий левый глаз Матери-Земли, который озаряет ночь и направляет странствующих охотников вместе со своим огненным братом-близнецом Ан'ше, солнцем."}},faq={{q="Кто такая Элуна?",a="Элуна — главное божество ночных эльфов, богиня луны, связанная с исцелением, природой, миром и Белой Госпожой — большей луной Азерота. Ее широко почитают как одно из немногих истинных божественных существ мира.",al={"what is elune","elune lore","who is the moon goddess","кто такая элуна","предания об элуне","кто богиня луны"}},{q="Являлась ли Элуна лично?",a="Элуну никогда не видели во плоти на Азероте. Мастера-кальдораи изображают ее сияющей юной ночной эльфийкой в платиновой короне, с длинными серебряными волосами и глазами, светящимися лунным светом, но ее истинный космический облик остается тайной.",al={"has elune taken physical form","what does elune look like","приняла ли элуна физический облик","как выглядит элуна"}},{q="Кто такая Ночная Воительница?",a="Ночная Воительница — самая свирепая ипостась Элуны. Вместо мягкого мира и исцеления это воплощение представляет ее праведный гнев в бою: она возносит духов доблестных павших воинов на ночное небо, чтобы они мчались среди звезд.",al={"elune night warrior","wrath of elune","элуна ночная воительница","гнев элуны"}},{q="Как Элуна связана с Кенарием?",a="Элуна зачала Кенария от дикого оленя-полубога Мал'орна. Благодаря этому союзу Кенарий унаследовал от матери глубокую любовь к живым существам Азерота, а от отца — тесную связь с дикой природой и Изумрудным Сном.",al={"is elune cenarius mother","cenarius parents","мать кенария элуна","родители кенария"}},{q="Поклоняются ли таурены Элуне?",a="Да, но под другим именем. В мифах таурен ее называют Му'ша, мягкий левый глаз Матери-Земли, который охраняет мир ночью вместе со своим солнечным братом Ан'ше.",al={"musha","tauren moon goddess","who is musha","муша","богиня луны таурен","кто такая муша"}},{q="Кто возглавляет поклонение Элуне в Калимдоре?",a="Сестринство Элуны возглавляет верховная жрица Тиранда Шелест Ветра из Храма Луны в Дарнассе. Сестринство служит главной духовной и гражданской властью среди ночных эльфов.",al={"priestesses of elune leader","sisters of elune","предводительница жриц элуны","сестры элуны"}}},fp="5,351,14.575.0,26.509.0,17.482.0,13.218.0,34.233.0,26.247.0,33.238.0,28.183.0,43.200.0"}
P.entries["topic:emerald-dream"] = {n="Изумрудный Сон",s="Изумрудный Сон — обширный, вечно меняющийся мир духов, представляющий Азерот в первозданном состоянии, совершенно не тронутом цивилизацией. Его охраняет Аспект драконов Изера и ее зеленый драконий род; он служит духовным образцом природы и священной областью, где друиды общаются с круговоротом жизни.",h="Изумрудный Сон — обширный, вечно меняющийся мир духов, представляющий Азерот в первозданном состоянии...",kw={"cenarius","dreaming","druid slumber","emerald dream","ghanir","green dragonflight","wild gods","ysera","кенарий","грезы","сон друидов","изумрудный сон","г'ханир","зеленый драконий род","дикие боги","изера"},ang={["class:Druid"]="Изумрудный Сон — священный источник вашей силы, где ваш орден общается с Дикими богами и изучает хрупкое равновесие Великого Круговорота.",["race:NightElf"]="Десять тысяч лет ваши друиды-мужчины спали в священных курганах, чтобы бродить по Сну рядом с Изерой, оставляя Часовых и жриц охранять бодрствующий мир.",["race:Tauren"]="Ваши друиды бродят по миру грез, чтобы общаться с духами земли, видя в нем неукрощенную колыбель творения Матери-Земли."},sec={{t="Зеркало первозданного Азерота",b="Изумрудный Сон существует вне физического мира, но связан с его пульсом и отражает то, каким был бы Азерот, если бы разумные существа никогда не вырубали его леса и не строили города на его камне. Созданный при древнем упорядочении мира, он представляет собой вечно меняющуюся пустошь из нетронутых лесов, бескрайних равнин и первозданных рек. Время и расстояние в Сне почти ничего не значат: дни физического мира могут казаться десятилетиями в мире духов, а ориентиры меняют форму, как туман перед глазами смертных."},{t="Царство Сновидицы",b="После упорядочения мира титаны доверили эту зеленеющую область Изере Дремлющей, великому Аспекту зеленого драконьего рода. Изера, призванная направлять развитие и природный ритм Азерота, пребывает в нескончаемом трансе и смотрит сквозь зачарованное сновидческое зрение, видящее и бодрствующий мир, и его зеркальную духовную область. Зеленые драконы охраняют редкие природные порталы, соединяющие физический мир со Сном, и несут вечную стражу на границе между сном и явью."},{t="Друиды и Грезы",b="Для смертных друидов Изумрудный Сон — источник их искусства. Направляя магию природы, друиды могут проецировать свои духи в Сон, оставляя телесные оболочки безопасно покоиться в берлогах-курганах годами и даже веками. В этой неукрощенной области они общаются с древними духами природы и Дикими богами, обретая глубокое понимание Великого Круговорота жизни и смерти. Опытные странники Сна учатся преступать физические законы в своих сновидческих обликах, преодолевая огромные расстояния и проходя сквозь твердые преграды по своей воле."}},faq={{q="Что такое Изумрудный Сон?",a="Изумрудный Сон — эфирное, духовное отражение Азерота. Он хранит первозданный, неукрощенный образец мира таким, каким тот был до того, как цивилизованные расы изменили ландшафт, и служит убежищем для духов природы и зеленого драконьего рода.",al={"what is emerald dream","emerald dream lore","the dream explained","что такое изумрудный сон","предания об изумрудном сне","объяснение сна"}},{q="Кто правит Изумрудным Сном?",a="Аспект драконов Изера наблюдает за Сном вместе с зеленым драконьим родом. Однако она не обладает над ним абсолютной властью. Дикая, глубинная структура Сна живет по собственному древнему ритму, направляя управление Изеры, а не подчиняясь ее воле.",al={"who controls emerald dream","emerald dream ruler","ysera dream","кто управляет изумрудным сном","правитель изумрудного сна","изера сон"}},{q="Как смертные попадают в Изумрудный Сон?",a="Большинство смертных попадают туда через глубокий друидический сон, проецируя дух в сновидческий облик, пока физические тела остаются под защитой в курганах. По всему Азероту также существуют редкие физические порталы, охраняемые зеленым драконьим родом, однако пройти через них опасно.",al={"visiting emerald dream","how to enter the dream","dreamform","посещение изумрудного сна","как попасть в сон","сновидческий облик"}},{q="Можно ли изменять что-либо внутри Сна?",a="Сновидцы могут временно формировать и изменять окружающую среду мыслью и магией, но эти изменения никогда не длятся. Первозданный образец Сна неизбежно вновь берет верх, стирая любой постоянный след смертных.",al={"changing emerald dream","can you alter the dream","изменение изумрудного сна","можно ли изменить сон"}},{q="Почему друиды спят веками?",a="Друиды погружаются в долгую спячку, чтобы бродить по Изумрудному Сну, общаться с духами природы, учиться у Диких богов и помогать зеленому драконьему роду поддерживать равновесие природных циклов Азерота на протяжении поколений.",al={"why druids hibernate","druid slumber","barrow dens sleeping","почему друиды впадают в спячку","сон друидов","сон в берлогах-курганах"}},{q="Куда уходят духи животных после смерти?",a="Духи многих зверей, Диких богов и существ природы после смерти уходят в Изумрудный Сон. Такие места, как Г'ханир, Древо-Мать, служат небесными убежищами, где дикие духи обретают покой в Великом Круговороте.",al={"animal afterlife","wild god spirits","beast spirits","загробная жизнь животных","духи диких богов","духи зверей"}}},fp="13,315,30.527.0,24.513.0,23.543.0,26.252.0,28.262.0,39.274.0,39.223.0,34.227.0,41.219.0"}
P.entries["topic:explorers-league"] = {n="Лига исследователей",s="Лига исследователей — известная дворфийская археологическая гильдия со штаб-квартирой в Зале Исследователей Стальгорна. Основанная при короле Магни Бронзобороде и возглавляемая его странствующим братом Бранном, Лига стремится раскрыть забытое происхождение дворфов. Ее обширные раскопки раскинулись по всему Азероту: они обнаруживают древние руины титанов и нередко разжигают региональные конфликты.",h="Лига исследователей — известная дворфийская археологическая гильдия со штаб-квартирой в Зале Исследователей...",kw={"archaeology","brann bronzebeard","excavation","explorers guild","explorers' league","hall of explorers","magni bronzebeard","muninn magellas","prospector","uldaman","археология","бранн бронзобород","раскопки","гильдия исследователей","лига исследователей","зал исследователей","магни бронзобород","мунин магеллас","старатель","ульдаман"},ang={["faction:Alliance"]="Помимо научного любопытства, Лига служит неофициальным органом сбора разведданных в отдаленных землях и тайно передает зашифрованные находки ШРУ в Штормграде.",["profession:Mining"]="Дворфийские старатели во многом опираются на традиции горного дела: они укрепляют туннели, изучают пласты и извлекают хрупкие механизмы титанов из сплошной породы.",["race:Dwarf"]="Каждое место раскопок и каждый артефакт титанов приближают дворфов к пониманию их древних корней как творений и их ухода от камня.",["race:Tauren"]="Неосторожное применение динамита Лигой в Калимдоре осквернило исконные земли Каменного Копья, доказав, что неустанные раскопки часто ведутся в ущерб земле."},sec={{t="Смена цели дворфов",b="Веками дворфы Каз Модана направляли свои огромные силы на добычу руды, каменную кладку и инженерное дело. Все изменилось, когда были обнаружены древние руины, намекавшие на забытую связь дворфов с мифическими титанами-создателями. Стремясь разгадать тайну происхождения своего народа, король Магни Бронзобород повелел круто повернуть дворфийскую промышленность в сторону археологии. Магни вместе с братом Бранном основал Гильдию исследователей, ныне известную как Лига исследователей, чтобы разыскивать по всему миру реликвии, забытые города и следы древних предков."},{t="Зал и раскопки",b="Деятельностью Лиги руководят из просторного Зала Исследователей в Стальгорне. Повседневным управлением занимается верховный исследователь Мунин Магеллас, пока Бранн Бронзобород исследует дальние края. По всему Каз Модану и за его пределами старатели управляют обширными местами раскопок. Такие места, как Раскопки Сталекрута в Лок Модане и раскопки Вельгара в Болотине, дают огромное количество окаменелостей и образцов древней архитектуры. Однако старателям часто приходится обороняться от изгнанных из своих мест животных, троггов и соперничающих группировок, интересующихся подземными реликвиями."},{t="Столкновения на границах",b="Напористые экспедиции Лиги вызвали яростное сопротивление за пределами дворфийских земель. В Калимдоре раскопки Лиги, такие как Бейл Модан на юге Степей, вытеснили коренных тауренов Каменного Копья с помощью мощных взрывов, вызвав жажду мести и гнев местных духов земли. В засушливых Бесплодных землях старатели Лиги открыто сражаются с кланом Черного Железа за обширные хранилища титанов в Ульдамане. Агенты Лиги также тайно делятся сведениями с секретной сетью ШРУ из Штормграда, и это показывает, что их раскопки по всему миру нередко пересекаются с большой политикой Альянса."}},faq={{q="Что такое Лига исследователей?",a="Лига исследователей — организация со штаб-квартирой в Стальгорне, занимающаяся разведкой, археологией и изучением происхождения дворфов. Она поддерживает места раскопок в Восточных королевствах и Калимдоре, чтобы находить реликвии древнего мира.",al={"explorers guild","dwarf explorers","who are the explorers league","league of explorers","гильдия исследователей","дворфы-исследователи","кто такая лига исследователей","лига исследователей"}},{q="Кто возглавляет Лигу исследователей?",a="Король Магни Бронзобород помогал основать гильдию, но ее официальный глава — его младший брат, известный странник Бранн Бронзобород. Пока Бранн часто путешествует по миру, делами из Зала Исследователей в Стальгорне заведует верховный исследователь Мунин Магеллас.",al={"leader of explorers league","brann bronzebeard role","muninn magellas","глава лиги исследователей","роль бранна бронзоборода","мунин магеллас"}},{q="Почему король Магни основал Лигу?",a="Когда странные подземные руины показали, что дворфы появились не просто из обычной горной породы, король Магни направил значительную часть дворфийской промышленности на археологию, чтобы узнать истинное, мифическое наследие своего народа.",al={"why do dwarves dig","dwarven origins","why archaeology","зачем дворфы копают","происхождение дворфов","зачем археология"}},{q="Могут ли в Лигу вступить не дворфы?",a="Да. Хотя в составе, руководстве и стиле Лиги преобладают дворфы, в нее вступают и представители других рас Альянса, в том числе отважные гномы вроде Клоппера Бацбаха, а также надежные полевые помощники на разных континентах.",al={"gnomes in explorers league","other races in league","who can join","гномы в лиге исследователей","другие расы в лиге","кто может вступить"}},{q="Почему таурены воюют с Лигой исследователей?",a="Спеша раскопать Калимдор, дворфийские старатели в Бейл Модане применили мощную взрывчатку и вытеснили коренное племя тауренов Каменного Копья, разрушив их поселение и разгневав местных духов земли бессмысленным уничтожением священной земли.",al={"bael modan tauren","dwarves vs tauren","stonespire feud","таурены бейл модана","дворфы против тауренов","вражда с каменным копьем"}},{q="Что такое Ульдаман и почему он важен для Лиги?",a="Ульдаман — огромное подземное сооружение титанов, погребенное под Бесплодными землями. Лига считает его жемчужиной своих исследований и полагает, что в его запечатанных залах хранятся неопровержимые доказательства превращения и древнего создания дворфов.",al={"uldaman excavation","league badlands","titan ruins uldaman","раскопки ульдамана","лига в бесплодных землях","руины титанов ульдаман"}}},fp="17,379,26.600.0,21.569.0,16.607.0,30.254.0,32.280.0,36.246.0,32.248.0,50.252.0,54.257.0"}
P.entries["topic:first-war"] = {n="Первая война",s="Первая война — разрушительный пятилетний конфликт, в котором Орочья Орда вышла из Темного портала и полностью уничтожила человеческое Королевство Штормград. Война, срежиссированная за кулисами одержимым демоном Стражем Медивом и чернокнижником Гул'даном, завершилась убийством короля Ллейна Ринна I и бегством уцелевших людей на север, в Лордерон.",h="Первая война — разрушительный пятилетний конфликт, в котором Орочья Орда вышла из Темного портала и полностью...",kw={"anduin lothar","black morass","blackhand","dark portal","first war","gul'dan","llane wrynn","medivh","northshire abbey","orgrim doomhammer","андуин лотар","черная топь","чернорук","темный портал","первая война","гул'дан","ллейн ринн","медив","аббатство североземья","оргрим молот рока"},ang={["class:Paladin"]="Гибель клириков Аббатства Североземья в этом конфликте показала, что одной святой веры недостаточно для выживания в жестоком ближнем бою, что напрямую вдохновило создание Рыцарей Серебряной Длани.",["class:Warlock"]="Гул'дан и его Совет Теней направляли завоевания Орды с помощью магии Скверны, показав, какое огромное, сокрушающее миры разрушение могут вызвать союзы с демонами.",["faction:Alliance"]="Полное уничтожение Штормграда стало мрачным предостережением, убедившим северные государства отказаться от изоляции и объединиться в Альянс Лордерона.",["race:Human"]="Первая война стала самым мрачным часом в истории Штормграда: королевство пало, его король был убит, а уцелевшие бежали за море нищими беженцами.",["race:Orc"]="Для орков Первая война стала первым кровавым завоеванием в Азероте, отмеченным проклятием крови Маннорота и тайными кознями Совета Теней Гул'дана."},sec={{t="Открытие портала",b="До войны Королевство Штормград долгие годы жило в мире после войны с гноллами под защитой своих рыцарей и клириков Аббатства Североземья. Эта стабильность рухнула, когда Страж Медив, тайно одержимый повелителем демонов Саргерасом, связался с орком-чернокнижником Гул'даном на Дреноре. Вместе они создали Темный портал в болотистой Черной топи. Подгоняемая демонической кровью и медленной гибелью родного мира, Орочья Орда массово вошла в Азерот. Сначала ходили слухи, что захватчики — мстительные духи или странные ответвления троллей, но разведывательные отряды сэра Андуина Лотара быстро подтвердили появление дисциплинированной кровожадной армии."},{t="Война за Штормград",b="Орда под открытым руководством вождя Чернорука и под тайным управлением Совета Теней Гул'дана захватила южные земли королевства. Попытка орков продвинуться в Тернистую долину против троллей Гурубаши провалилась, но их кампания на человеческих землях оказалась катастрофической. Орда завоевывала земли, пока под контролем людей не остался лишь Элвиннский лес. Чернорук предпринял первый прямой штурм Штормграда, но сэр Андуин Лотар отразил вторжение блестящей неожиданной фланговой контратакой с моря, временно спасши столицу от уничтожения."},{t="Предательство и падение",b="Ход войны изменился, когда Лотар и молодой маг Кадгар раскрыли предательство Медива, проникли в Каражан и убили Стража. Гибель Медива ввергла Гул'дана в беспамятство, и у Оргрима Молота Рока появилась возможность вызвать Чернорука на поединок мак'гора и убить его. Взяв всю власть, Молот Рока разгромил Совет Теней и двинулся на Штормград для второй осады. Во время штурма полуорк-убийца Гарона убила короля Ллейна Ринна I в его замке. Штормград был разграблен и сожжен дотла, и Лотару пришлось собрать уцелевших жителей и бежать на север через Великое море в Лордерон."}},faq={{q="Как орки вообще попали в Азерот?",a="Чернокнижник Гул'дан на Дреноре и Страж Медив в Азероте совместно использовали темную магию Скверны, чтобы пробить границу между мирами, и возвели Темный портал в Черной топи.",al={"how did orcs get here","dark portal origin","first war start","как орки попали сюда","происхождение темного портала","начало первой войны"}},{q="Почему другие человеческие королевства не помогли Штормграду?",a="Штормград остался один, потому что далекие северные королевства считали слухи о зеленокожих захватчиках нелепыми преувеличениями или местными склоками. Лишь после падения Штормграда, когда Лотар прибыл в Лордерон с кораблями, полными беженцев, северные короли объединились.",al={"why no alliance","did lordaeron help","reinforcements for stormwind","почему не было альянса","помог ли лордерон","подкрепление для штормграда"}},{q="Кто убил короля Ллейна?",a="Король Ллейн Ринн I был убит в собственном замке Гароной Полуорчихой — посланницей, которой король доверял. Это нанесло смертельный удар по духу людей во время последней осады.",al={"who murdered llane","king llane death","garona killed king","кто убил ллейна","смерть короля ллейна","гарона убила короля"}},{q="Сражались ли орки в Первой войне с кем-то, кроме людей?",a="Да. В начале конфликта Орда двинулась на юг, в Тернистую долину, но была отброшена в яростной схватке с джунглевыми троллями Гурубаши.",al={"did orcs fight trolls","gurubashi in first war","other races first war","сражались ли орки с троллями","гурубаши в первой войне","другие расы первой войны"}},{q="Кто победил в Первой войне?",a="Орочья Орда одержала полную победу. Королевство Штормград было стерто с лица земли, король Ллейн убит, а уцелевшие люди были вынуждены массово эвакуироваться по морю на север, в Лордерон.",al={"first war victor","who won wc1","outcome of first war","победитель первой войны","кто выиграл в варкрафт 1","итог первой войны"}},{q="Что случилось с вождем Черноруком?",a="Когда Гул'дан после смерти Медива потерял сознание, Оргрим Молот Рока вызвал Чернорука на мак'гора — поединок чести, — убил его и захватил власть над Ордой.",al={"how did blackhand die","orgrim doomhammer challenge","warchief killed","как умер чернорук","вызов оргрима молота рока","убийство вождя"}}},fp="9,374,21.668.0,21.602.0,22.608.1,51.194.0,51.273.0,22.177.0,58.154.0,22.191.0,36.173.0"}
P.entries["topic:forsaken"] = {n="Отрекшиеся",s="Отрекшиеся — свободная фракция разумной нежити, порвавшая с Плетью после Третьей войны. Их возглавляет Королева банши леди Сильвана Ветрокрылая. Они обитают в подземном Подгороде, раскинувшемся под руинами столицы Лордерона. Хотя по всему Азероту им глубоко не доверяют, они поддерживают с Ордой хрупкий союз по расчету.",h="Отрекшиеся — свободная фракция разумной нежити, порвавшая с Плетью после Третьей войны.",kw={"apothecary","forsaken","lordaeron","plaguelands","sylvanas","tirisfal","undead","undercity","апотекарий","отрекшиеся","лордерон","чумные земли","сильвана","тирисфаль","нежить","подгород"},ang={["faction:Alliance"]="Для Альянса Отрекшиеся — кошмарные пародии на павших друзей и близких из Лордерона: они удерживают бывшие имперские земли и отвечают на предложения ядом и сталью.",["faction:Horde"]="Тралл заключил с Подгородом союз по расчету ради территории на востоке, но многие орки и тролли с глубоким подозрением относятся к мрачным опытам апотекариев и некромантической культуре Отрекшихся.",["race:Tauren"]="Ваши старейшины, особенно верховный друид Хамуул Рунический Тотем, из сочувствия поддержали вступление Отрекшихся в Орду, надеясь, что ваши шаманские и друидические обряды однажды смягчат или исцелят их трагическое состояние.",["race:Undead"]="Это ваш народ: проклятый бродить по земле в гниющей плоти, отвергнутый прежними родичами, но объединенный Темной Госпожой, чтобы создать собственную империю."},sec={{t="Разорванные оковы",b="Когда после Третьей войны власть Короля-лича над его северными армиями ослабла, тысячи нежити в оскверненных руинах Лордерона внезапно обрели разум и память. Ужаснувшись бойне, которую их заставляли творить в рабстве у его воли, бывшие жители оказались презираемы и гонимы живыми. Леди Сильвана Ветрокрылая, павший рейнджер-генерал Кель'Таласа, превращенная в нечестивую банши, собрала эти неприкаянные души, заняла катакомбы под Столицей и назвала свое новое государство Отрекшимися."},{t="Союз по расчету",b="Окруженная неумолимыми врагами, главные из которых — фанатичный Алый орден и Плеть, Сильвана разослала посланников на поиски союзников. Те, кого отправили в Штормград, были убиты, не дойдя до ворот. Однако за Великим морем, в Калимдоре, верховный друид Хамуул Рунический Тотем и старейшины-таурены призвали к состраданию, веря, что проклятый народ еще может обрести искупление или исцеление через землю. Несмотря на серьезные опасения вождя Тралла и Кэрна Кровавого Копыта, Орда приняла Отрекшихся и получила важный северный плацдарм в Восточных королевствах."},{t="Темные лаборатории",b="Изображая перед союзниками из Калимдора сотрудничество, Отрекшиеся добиваются собственного мрачного выживания. Под Подгородом, в Апотекариуме, Королевское фармацевтическое общество неустанно трудится над «Новой чумой», достаточно сильной, чтобы уничтожить и Плеть, и живых врагов. Тем временем чемпионы Отрекшихся, такие как Натанос Гнилостень, ведут жестокие войны в Чумных землях, Предгорьях Хилсбрада и Монастыре Алого ордена, обеспечивая безопасность суверенных границ."}},faq={{q="Входят ли Отрекшиеся в состав Плети?",a="Нет. Отрекшиеся освободились от власти Короля-лича над их разумом после Третьей войны. Они ненавидят Плеть и считают Короля-лича Артаса своим смертельным врагом, яростно сражаясь с его приспешниками по всем Чумным землям.",al={"scourge difference","are forsaken scourge","are undead evil","отличие от плети","отрекшиеся плеть","нежить зло"}},{q="Где находится столица Отрекшихся?",a="Их столица — Подгород, огромный подземный лабиринт под руинами Столицы в Тирисфальских лесах. Силы Сильваны расширили королевские склепы и канализацию, превратив их в укрепленное убежище, защищенное от света и внешних угроз.",al={"undead capital","forsaken city","where do undead live","столица нежити","город отрекшихся","где живет нежить"}},{q="Почему Орда позволила Отрекшимся присоединиться?",a="Верховный друид Хамуул Рунический Тотем и таурены горячо ратовали за них, видя возможность искупления и надеясь, что силы земли исцелят их недуг. Союз поддержала и Магата Зловещий Тотем. Вождь Тралл согласился, потому что Орде срочно требовался стратегический военный плацдарм в Восточных королевствах.",al={"why are undead horde","how did forsaken join horde","thrall forsaken alliance","почему нежить в орде","как отрекшиеся вступили в орду","тралл и отрекшиеся"}},{q="Кто правит Отрекшимися?",a="Леди Сильвана Ветрокрылая, Королева банши. Прежде — высшая эльфийка, рейнджер-генерал, павшая при защите Луносвета, — она освободила разумную нежить и правит из Подгорода вместе со своим советником-повелителем ужаса Вариматрасом.",al={"undead leader","forsaken queen","who leads forsaken","лидер нежити","королева отрекшихся","кто возглавляет отрекшихся"}},{q="Все ли Отрекшиеся — бывшие люди?",a="Подавляющее большинство — бывшие люди павшего королевства Лордерон, убитые и поднятые во время вторжения Плети. Однако среди их руководства есть и бывшие эльфы, как Сильвана, а любой, кто склонит колено перед Темной Госпожой, будет принят в их ряды.",al={"undead races","are forsaken only humans","what race are forsaken","расы нежити","отрекшиеся только люди","какой расы отрекшиеся"}},{q="Почему Алый орден так сильно ненавидит Отрекшихся?",a="Алый орден не делает никакой разницы между разумными Отрекшимися и безмозглой Плетью. Его фанатики считают всю нежить мерзостью, которую нужно очистить огнем и священным гневом, независимо от свободной воли и союзов.",al={"scarlet crusade undead","crusade vs forsaken","why scarlet crusade attacks","алый орден нежить","орден против отрекшихся","почему алый орден нападает"}}},fp="8,367,15.572.0,26.566.0,17.474.1,37.240.0,30.241.0,40.318.0,23.222.0,35.267.0,55.226.0"}
P.entries["topic:frostmane-tribe"] = {n="Племя Мерзлогривов",s="Племя Мерзлогривов — свирепые ледяные тролли, коренные обитатели холодных вершин Дун Морога. Века назад дворфы Стальгорна загнали их в пещеры и на отдаленные хребты, и теперь они ведут неустанную партизанскую войну, чтобы вернуть родные земли.",h="Племя Мерзлогривов — свирепые ледяные тролли, коренные обитатели холодных вершин Дун Морога.",kw={"battok","coldridge valley","dun morogh","frostmane","frostmane hold","grik'nir","ice troll","shimmer ridge","батток","холодная долина","дун морог","мерзлогрив","форт мерзлогривов","грик'нир","ледяной тролль","мерцающий хребет"},ang={["profession:Cooking"]="Скальные кабаны и звери, которых держат у лагерей Мерзлогривов, дают грубое дичное мясо для очажных пайков среди кусачих снегов Дун Морога.",["race:Dwarf"]="Для дворфов Мерзлогривы — постоянное напоминание о древних кровных распрях. Сама королева Эймир пала от засады троллей Мерзлогривов, поэтому оборона Дун Морога для горцев — дело глубоко личное.",["race:Troll"]="Хотя тролли Черного Копья разделяют общее наследие троллей, обособленные Мерзлогривы — дикие ледяные тролли, не интересующиеся родством и считающие гостей из Орды захватчиками своих священных вершин."},sec={{t="Изгнанники высоких утесов",b="Задолго до того, как клан Бронзобородов объединился под Стальгорном, тролли Мерзлогривы властвовали над заснеженными просторами Дун Морога. Возвышение и рост королевства дворфов сокрушили их владения и вынудили уцелевших ледяных троллей отступить на замерзшие хребты и утесы. Это унизительное поражение породило горькую ненависть, которая передается из поколения в поколение до сих пор. Мерзлогривы считают каждого горца, путника и поселение вторгшимся врагом, которого нужно изгнать или перебить."},{t="Использованная возможность",b="Десятилетиями Сенат Стальгорна считал Мерзлогривов лишь назойливой помехой, затаившейся в холмах. Однако внезапное появление угрозы троггов в глубинах Дун Морога привело оборону дворфов в смятение. Почувствовав удобный момент, пока горцы заняты, а силы дворфов сражаются на войнах Альянса вдали от дома, Мерзлогривы возобновили жестокие набеги из таких оплотов, как Форт Мерзлогривов и Мерцающий хребет, чтобы вернуть свои древние земли."},{t="Налетчики долин",b="Сенат Стальгорна в конце концов заметил растущую угрозу и отправил разобраться с ней Грелина Белоборода и его брата Сенира. Из пещер Форта Мерзлогривов и с высот Мерцающего хребта тролли нападают на дворфов, а в Холодной долине предводители вроде Грик'нира Холодного руководят агрессивными вылазками против горцев."}},faq={{q="Кто такие тролли Мерзлогривы?",a="Это племя ледяных троллей, обитающих на заснеженных утесах Дун Морога. Века назад они правили этим краем, пока армии дворфов не разбили их и не вытеснили на высокие хребты.",al={"frostmane lore","what are frostmane","dun morogh trolls","предания мерзлогривов","кто такие мерзлогривы","тролли дун морога"}},{q="Почему Мерзлогривы нападают на дворфов сейчас?",a="Поскольку дворфы-горцы связаны вторжениями троггов и военными обязательствами по всему Альянсу, Мерзлогривы видят возможность вернуть родные охотничьи угодья и отомстить Стальгорну.",al={"why do frostmane attack","frostmane uprising","troll attacks dun morogh","почему мерзлогривы нападают","восстание мерзлогривов","нападения троллей дун морог"}},{q="Кто возглавляет племя Мерзлогривов?",a="Племя совершает набеги из Форта Мерзлогривов и с Мерцающего хребта, а его отряды возглавляют агрессивные предводители вроде Грик'нира Холодного, который досаждает дворфам Холодной долины.",al={"frostmane leader","chief of frostmane","who runs the frostmane","лидер мерзлогривов","вождь мерзлогривов","кто управляет мерзлогривами"}},{q="Что случилось с Фортом Мерзлогривов?",a="Форт Мерзлогривов остается оплотом племени — пещерой в холмах Дун Морога, занятой троллями, откуда Мерзлогривы начинают набеги. Сенат Стальгорна отправил Грелина Белоборода и его брата Сенира разобраться с угрозой.",al={"frostmane hold troggs","what happened to troll cave","why did trolls leave hold","форт мерзлогривов трогги","что случилось с пещерой троллей","почему тролли покинули форт"}},{q="Что такое звездолист и зачем тролли его собирают?",a="Звездолист — выносливое растение, растущее на горьких ветрах Мерцающего хребта. Мерзлогривы выращивают и собирают его для священных племенных обрядов, а дворфы-пивовары ценят его как ингредиент для крепкого стаута.",al={"shimmerweed","frostmane shimmerweed","what is shimmerweed used for","звездолист","звездолист мерзлогривов","для чего нужен звездолист"}},{q="Союзны ли Мерзлогривы Орде?",a="Нет. Мерзлогривы — независимые ледяные тролли, питающие лютую ненависть ко всем чужакам и нападающие на путников и исследователей независимо от фракции.",al={"are frostmane horde","frostmane faction","frostmane friendly to horde","мерзлогривы орда","фракция мерзлогривов","мерзлогривы дружелюбны к орде"}}},fp="15,246,24.488.0,20.499.0,22.347.1,29.182.0,48.202.0,30.171.0,32.230.0,53.217.0,41.148.0"}
P.entries["topic:furbolg"] = {n="Фурболг",s="Фурболги — рослая нелюдимая раса медведеподобных существ, коренные жители северного Калимдора, которые тысячелетиями жили в согласии с природой и ночными эльфами. После Третьей войны демоническая порча и остатки магии Скверны довели почти все племена до неистового безумия. Сегодня бывшие друзья стали свирепыми хищниками, защищающими свою территорию, и лишь несколько племен сохранили рассудок.",h="Фурболги — рослая нелюдимая раса медведеподобных существ, коренные жители северного Калимдора, которые...",kw={"ashenvale","corruption","deadwood","foulweald","furbolg","gnarlpine","thistlefur","timbermaw","ursoc","winterfall","ясеневый лес","порча","мертвый лес","гиблая чаща","фурболг","скрюченные сосны","колючий мех","древобрюх","урсок","зимняя спячка"},ang={["class:Druid"]="Друиды скорбят о медведеподобных существах как о родственных духах Урсока, чья связь с природой стала оружием в руках скверны, поэтому племенные волнения — прямой признак общей болезни земли.",["faction:Horde"]="Орда видит во враждебных племенах Ясеневого леса территориальные преграды и уничтожает агрессивные стаи, такие как Гиблая Чаща и Колючий Мех, чтобы обезопасить пути снабжения и форпосты на краю леса.",["race:NightElf"]="Для ночных эльфов падение фурболгов — душераздирающая трагедия. Племена, десять тысяч лет бывшие надежными союзниками в лесах, стали дикими хищниками, угрожающими Астранаару и священным курганам Тельдрассила."},sec={{t="Древнее родство",b="Фурболги ведут свой род от джалгаров древнего Калимдора и издавна почитают дикого бога Урсока. Во время Войны Древних десять тысяч лет назад племенные стаи объединились под началом вождя Унг Ака и вместе с ночными эльфами и таурен сражались против первого вторжения демонов. После Великого Раскола они предпочли уединение в глубине северных лесов, сохраняя мирные связи с друидами и лесными стражами ночных эльфов и живя в простом согласии с дикой природой."},{t="Бич безумия",b="Третья война разрушила мирную жизнь фурболгов. Путь Пылающего Легиона через Калимдор оставил стойкую скверну в почве и кронах Ясеневого леса и Оскверненного леса. Простодушные медведеподобные существа, глубоко связанные с землей, впитали эту порчу напрямую. Их мудрых шаманов свергли или заставили замолчать кровожадные зажигатели, которые использовали оскверненный мох, темные талисманы и порочную алхимию. Мирные собиратели превратились в бешеных налетчиков, которые теперь нападают на путников и поселения ночных эльфов без разбора."},{t="Непреклонный оплот",b="По всему северному Калимдору пали почти все крупные племена: Скрюченные Сосны в Тельдрассиле, Чернолесье на Темных берегах, Колючий Мех и Гиблая Чаща в Ясеневом лесу, а также Мертвый Лес и Зимняя Спячка на северном нагорье. И все же некоторые держатся. В укрепленных туннелях, соединяющих Оскверненный лес, Зимние Ключи и Лунную поляну, племя Древобрюхов яростно оберегает свой рассудок. Настороженные и изолированные, Древобрюхи защищают свою крепость от обезумевших северных сородичей, отчаянно стремясь сохранить остатки своей неоскверненной культуры."}},faq={{q="Почему фурболги нападают на всех?",a="После Третьей войны в северных лесах Калимдора осталась стойкая демоническая порча. Поскольку фурболги глубоко связаны с природой, эта скверна проникла в их разум и ввергла племена в параноидальное, яростное безумие, а мирных старейшин сменили агрессивные вожди.",al={"why are furbolgs hostile","furbolg madness","why furbolgs went crazy","почему фурболги враждебны","безумие фурболгов","почему фурболги сошли с ума"}},{q="Всегда ли фурболги были врагами ночных эльфов?",a="Нет. Тысячи лет фурболги и ночные эльфы были мирными соседями и близкими союзниками. Они плечом к плечу сражались с Пылающим Легионом в Войне Древних, а друиды ночных эльфов поддерживали добрые отношения с племенными поселениями, пока не началась недавняя волна безумия.",al={"furbolg night elf history","did furbolgs like night elves","история фурболгов и ночных эльфов","дружили ли фурболги с ночными эльфами"}},{q="Остались ли фурболги, которые все еще дружелюбны?",a="Да. Племя Древобрюхов сохраняет неоскверненное убежище в Крепости Древобрюхов — системе туннелей на пересечении путей между Оскверненным лесом, Лунной поляной и Зимними Ключами. Хотя они крайне недоверчивы к чужакам, они терпят путников, доказавших свою вражду к оскверненным племенам Мертвого Леса и Зимней Спячки.",al={"friendly furbolgs","good furbolg tribe","uncorrupted furbolgs","дружелюбные фурболги","хорошее племя фурболгов","неоскверненные фурболги"}},{q="Что случилось с фурболгами в Тельдрассиле?",a="Племя Скрюченных Сосен в Тельдрассиле попало под власть оскверненного мха — коварной порчи, распространяющейся по ветвям мирового древа. Под началом вождя Урсала Изверга оскверненные Скрюченные Сосны покинули свои исконные деревни и захватили священные места, такие как Обитель Бен'этиль и Деревня Звездного Ветра.",al={"teldrassil furbolgs","gnarlpine corruption","фурболги тельдрассила","порча скрюченных сосен"}},{q="Кто стоит за порчей Зимней Спячки в Зимних Ключах?",a="Зимней Спячкой тайно управляет сатир по имени Ксандивий, затаившийся в логове их вождя. Неистовство племени поддерживает Огненная вода Зимней Спячки, которую варят из оскверненных материалов в Котловане Мертвого Леса в Оскверненном лесу и переправляют на север через горные перевалы.",al={"winterfall tribe lore","who corrupted winterfall","winterfall firewater origin","предания о племени зимней спячки","кто осквернил зимнюю спячку","происхождение огненной воды зимней спячки"}},{q="Можно ли излечить оскверненных фурболгов?",a="Часовые и друиды ночных эльфов пытались очистить отдельные племена водой лунных колодцев и священными реликвиями, но массовое исцеление оказалось почти невозможным. Поскольку сатиры и темные реликвии продолжают углублять порчу, защитникам часто приходится истреблять враждебные стаи ради защиты поселений.",al={"cure furbolgs","can furbolgs be saved","излечить фурболгов","можно ли спасти фурболгов"}}},fp="7,401,15.484.0,22.530.0,17.535.0,40.302.0,48.303.0,46.297.0,46.313.0,63.277.1,37.313.0"}
P.entries["topic:gnoll"] = {n="Гнолл",s="Гноллы — свирепая раса гиеноподобных гуманоидов, падальщиков и налетчиков, разбросанная по Восточным королевствам и Калимдору. Известные жестокими междоусобицами, зверской силой и звериной хитростью, они выживают грабежом поселений, истреблением дичи и засадами на неосторожных путников. Если их не сдерживать, их разросшиеся стаи и военачальники постоянно угрожают пограничным деревушкам и торговым дорогам.",h="Гноллы — свирепая раса гиеноподобных гуманоидов, падальщиков и налетчиков, разбросанная по Восточным...",kw={"garfang","gnoll","hogger","mosshide","mudsnout","palemane","riverpaw","rot hide","shadowhide","woodpaw","гарфанг","гнолл","дробитель","мохошкур","грязная морда","бледногрив","речная лапа","гнилошкуры","темношкуры","лесная лапа"},ang={["faction:Alliance"]="Маршалы Альянса в Элвиннском лесу, Западном Крае, Красногорье и Болотине в значительной мере полагаются на вольных героев, чтобы сокращать численность наступающих гноллов.",["race:Human"]="Для людей Штормграда гноллы — древний враг, некогда сжегший сердце королевства. Сегодня стаи вроде Речной Лапы и Темношкуров угрожают уязвимым пограничным дорогам королевства.",["race:Tauren"]="Племя Бледногривов в Мулгоре обращается с землей с беспечной жестокостью, и молодым воинам-таурен приходится отгонять их, чтобы сохранить равновесие равнин.",["race:Undead"]="Отрекшиеся видят в гноллах либо досаду, либо ресурс: Грязные Морды выращивают целебные грибы в Хилсбраде, а Сильвана ранее порабощала северные стаи с помощью одержимости банши."},sec={{t="Гиены дикой глуши",b="Гноллы чуть ниже обычного человека, но обладают взрывной физической мощью. Это двуногие родичи гиен с острыми зубами, густой шерстью и характерным лающим смехом. Хотя они вполне способны ходить прямо, они часто опускаются на четвереньки, чтобы быстро скакать по зарослям или выслеживать добычу по запаху. В культуре гноллов превыше всего ценится грубое физическое превосходство. Они объединяются в склочные стаи под предводительством сильнейшего и жесточайшего вожака и подчиняются, лишь когда превосходящая сила сломит их."},{t="Война с гноллами",b="Хотя гноллов обычно раздирают мелкие склоки, объединившись, они однажды поставили королевство Штормград на колени. За десятилетия до Первой войны вожак стаи по имени Гарфанг подчинил племена Красногорья и начал согласованные нападения на Штормград. Пока защитники города были скованы боем, налетчики-гноллы опустошали фермы Западного Края. Кризис закончился, лишь когда король Баратен Вринн возглавил дерзкий поход в Красногорье и отсек Гарфангу голову. Лишенные предводителя, гноллы обратились друг против друга в кровавых распрях, и их великий союз распался навсегда."},{t="Налетчики южных королевств",b="На юге стаи гноллов свирепствуют без полной военной мощи Штормграда. В Элвиннском лесу и Западном Крае стая Речной Лапы, которой управляет небезызвестный Дробитель, грабит усадьбы и заставляет покоренных кобольдов рыть золото, тайно сговорившись с Братством Справедливости. Дальше на восток, в Красногорье, стая Красногорья угоняет лошадей у Приозерья и срывает починку мостов, а клан Темношкуров в Долине Галарделл служит темной воле мага-отступника Морганта."},{t="Мор и территория",b="Угроза гноллов не ограничивается людским югом. На севере Лордерона некромант Плети Тул Коготь Ворона поднимает нежить — гноллов Гнилошкуров, которые выкапывают трупы в Тирисфальских лесах и Серебряном бору. Возле Хилсбрада Грязные Морды собирают гнилые ядовитые цветы среди разрушенных ферм. За Великим морем, в Калимдоре, стая Бледногривов истребляет дичь по всему Мулгору, несмотря на попытки таурен заключить мир, а Лесные Лапы Фераласа ведут отчаянную, яростную войну против наступающих роев силитидов."}},faq={{q="Кто такие гноллы?",a="Гноллы — гиеноподобные гуманоиды-хищники, известные жестоким нравом, физической выносливостью и примитивной хитростью. Они живут в кочевых или полупостоянных лагерях и выживают в основном грабежом, охотой и падалью.",al={"what are gnolls","gnoll race","are gnolls hyenas","кто такие гноллы","раса гноллов","гноллы гиены"}},{q="Почему гноллы не создают настоящее королевство?",a="Гноллы яростно воинственны и подчиняются лишь сиюминутной иерархии. Без незаурядного и тираничного военачальника, держащего их в строю, стаи неизбежно распадаются на кровавые территориальные распри, что мешает долгосрочной организации и развитию общества.",al={"why are gnolls scattered","gnoll empire","gnoll unity","почему гноллы разрознены","империя гноллов","единство гноллов"}},{q="Что такое Война с гноллами?",a="Примерно за семьдесят пять лет до Первой войны вожак стаи Гарфанг объединил гноллов Красногорья и осадил Штормград, сжигая при этом Западный Край. Король Баратен Вринн отправился в горы и лично убил Гарфанга, что вызвало самоубийственные междоусобицы и сломило орду гноллов.",al={"king barathen gnoll war","garfang invasion","stormwind gnoll war","король баратен война с гноллами","вторжение гарфанга","война гноллов со штормградом"}},{q="Почему гноллы работают с Братством Справедливости?",a="Стая Речной Лапы в Западном Крае и Элвиннском лесу сотрудничает с Братством Справедливости в обмен на оружие, согласованность действий и общую добычу. Бандиты используют гноллов как грубую силу, чтобы захватывать фермерские земли и отвлекать редеющие гарнизоны Штормграда.",al={"defias gnoll alliance","riverpaw defias","hogger defias","гноллы и братство справедливости","речная лапа и братство","дробитель и братство"}},{q="Живы ли гноллы Гнилошкуры?",a="Нет. Гноллы Гнилошкуры, бродящие по Тирисфальским лесам и Серебряному бору, — порабощенная нежить. Они подчиняются Тулу Когтю Ворона, изгнанному человеку-некроманту, который использует Остров Фенриса как оплот для сбора трупов для Плети.",al={"rot hide undead","silverpine gnolls","fenris isle gnolls","гнилошкуры нежить","гноллы серебряного бора","гноллы острова фенриса"}},{q="Почему таурены сражаются с гноллами Бледногривами?",a="Когда таурены поселились в Мулгоре, они пытались ужиться и наладить общение с коренной стаей Бледногривов. Гноллы отвергли все мирные жесты, безудержно истребляя дичь равнин и угрожая деревням таурен.",al={"palemane mulgore","tauren and gnolls","why kill palemane","бледногривы мулгор","таурены и гноллы","почему убивать бледногривов"}}},fp="5,419,19.509.0,13.584.0,32.506.1,24.489.0,24.207.0,39.246.0,23.274.0,51.246.1,30.216.0,40.236.0"}
P.entries["topic:gnome"] = {n="Гном",s="Гномы — миниатюрная, эксцентричная и поразительно умная раса, известная по всему Азероту изобретательной инженерией и владением тайной магией. Несмотря на жизнерадостный нрав, недавно они пережили катастрофическую трагедию: вторжение подземных троггов и провальный план обороны привели к радиоактивному заражению их столицы, Гномрегана. Теперь гномы живут беженцами в Городе механиков в Стальгорне и остаются верными союзниками Альянса, борясь за возвращение утраченного дома.",h="Гномы — миниатюрная, эксцентричная и поразительно умная раса, известная по всему Азероту изобретательной...",kw={"deeprun tram","gnomanity","gnome","gnomeregan","gnomes","high tinker","mechagnome","mekkatorque","tinker town","trogg","подземный поезд","гномы","гном","гномреган","главный механик","механогном","меггакрут","город механиков","трогг"},ang={["class:Mage"]="Несмотря на малый рост, гномы — исключительно одаренные магистры тайных искусств, с древности служившие учеными и членами советов Даларана.",["faction:Alliance"]="Альянс обязан гномам огромной стратегической мобильностью и осадными технологиями: гномы преданно снабжают его машинами и поддерживают Подземный поезд, несмотря на собственное изгнание.",["profession:Engineering"]="Гномья инженерия известна всему миру хитроумными устройствами, лучевыми приборами и поразительной точностью, ценящей тщательный замысел выше нестабильных гоблинских взрывов.",["race:Dwarf"]="Гномы — ваши древнейшие и самые близкие соседи по горам; открыть ворота Стальгорна для их уцелевших в Городе механиков было легким решением после поколений братской дружбы.",["race:Gnome"]="Ваш народ с тихой решимостью несет трагическую утрату Гномрегана и, находясь в изгнании в Городе механиков, борется за отнятый дом с помощью таланта, оптимизма и взрывной огневой мощи."},sec={{t="Изобретательность и оптимизм",b="Малые ростом, но великие умом, гномы подходят к миру с безграничным любопытством и научными амбициями. Пока другие расы записывают историю и хранят традиции, гномы неустанно смотрят вперед и посвящают жизнь механике, изучению тайной магии и технологическим новшествам. Их изобретения — от заводных устройств и летающих машин до сложных подземных поездов — изменили современный мир. Даже после тяжелейших бедствий гномы сохраняют неукротимую жизнерадостность и непоколебимое стремление отстроить заново и решить невозможное."},{t="Рожденные в горах",b="Тысячелетия назад древние предки гномов вышли из хранилищ титанов в Ульдамане, пораженные Проклятием плоти. За поколения забыв о своем происхождении от титанов, они поселились в промерзших скалах Дун Морога. Когда спустя века пришли дворфы, два народа сразу почувствовали родство. Дворфийская мощь и гномья изобретательность объединились, и в западном Дун Мороге вырос чудесный подземный технический город Гномреган. Четыре века назад, когда ушел их последний король, гномы отказались от наследственной монархии и стали избирать дальновидных вождей, которых называют главными механиками."},{t="Падение Гномрегана",b="Во время Третьей войны гномы отправили в Лордерон вооружение, но не прислали войск, чем озадачили союзников. На деле на пороге их дома разразилась чудовищная катастрофа: орды свирепых троггов, потревоженных раскопками близ Ульдамана, хлынули в нижние районы Гномрегана. Желая избавиться от захватчиков и не обременять осажденный Альянс, главный механик Гелбин Меггакрут последовал совету главного советника и спустил радиоактивные отходы в нижний город. Ядовитая уловка полностью провалилась. Троггов это не убило — они мутировали и пришли в неистовство, а почти восемьдесят процентов гномов погибли."},{t="Изгнание в Город механиков",b="Уцелевшие гномы бежали из отравленного дома и нашли приют у родичей-дворфов в Стальгорне. Главный механик Меггакрут и его народ основали шумный анклав в Городе механиков в Стальгорне, продолжая поддерживать Альянс и управлять Подземным поездом, который связывает Стальгорн со Штормградом. Из этого приемного квартала гномьи коммандос и отважные добровольцы постоянно отправляются в экспедиции в зараженные глубины Гномрегана, чтобы истребить троггов, разобраться с механическими чудовищами и однажды вернуть свой великий город."}},faq={{q="Почему гномы живут в Стальгорне, а не в собственном городе?",a="Сейчас гномы — беженцы, живущие в Городе механиков в Стальгорне. Их родовой дом, Гномреган, был захвачен внезапным нашествием подземных троггов. Во время кризиса отчаянная попытка облучить троггов пошла не так: город залило смертоносными осадками, и подавляющее большинство жителей погибло. Король Магни Бронзобород предложил уцелевшим приют в дворфийской столице.",al={"why in ironforge","where do gnomes live","gnome refugee city","почему в стальгорне","где живут гномы","город беженцев гномов"}},{q="Кто возглавляет гномов?",a="Гномов возглавляет главный механик Гелбин Меггакрут. Вместо наследственной королевской династии гномы выбирают вождей по заслугам, инженерному мастерству и дальновидности. На Меггакруте лежит тяжкое бремя приказа облучить Гномреган, чтобы остановить троггов, и теперь он руководит войной за возвращение дома.",al={"gnome leader","gnome king","who rules gnomes","high tinker","лидер гномов","король гномов","кто правит гномами","главный механик"}},{q="Почему гномы не помогли сражаться с Плетью в Лордероне?",a="Хотя гномы поставляли Альянсу Лордерона осадные орудия и технологии, они не могли выделить солдат, потому что Гномреган в то же время боролся за выживание с троггами. Гномы решили не просить союзников о помощи, полагая, что Альянсу и так хватает забот с нежитью из Плети.",al={"gnomes in third war","why gnomes skipped third war","gnomes third war help","гномы в третьей войне","почему гномы пропустили третью войну","помощь гномов в третьей войне"}},{q="Что такое Подземный поезд?",a="Подземный поезд — необыкновенная подземная железная дорога, спроектированная главным механиком Гелбином Меггакрутом и построенная гномьими инженерами. Она напрямую соединяет Город механиков в Стальгорне с дворфийским кварталом Штормграда и позволяет быстро перевозить войска, припасы и путешественников между двумя союзными столицами.",al={"who built the tram","stormwind ironforge train","deeprun tram origin","кто построил поезд","поезд штормград стальгорн","происхождение подземного поезда"}},{q="В чем соперничество гномов и гоблинов?",a="Гномы и гоблины яростно соперничают в культуре и технологиях, и это соперничество вспыхнуло во время Второй войны. Гномья инженерия делает ставку на точность, устойчивость и сложные безопасные механизмы. Гоблинская же ценит грубую взрывную мощь, дешевое производство и быстрый результат, не считаясь с нестабильностью. Обе расы постоянно пытаются превзойти друг друга в изобретениях и высмеять соперника.",al={"gnomes vs goblins","gnome goblin engineering","why do gnomes hate goblins","гномы против гоблинов","инженерия гномов и гоблинов","почему гномы ненавидят гоблинов"}}},fp="5,472,22.600.0,23.601.0,22.619.1,20.539.0,61.397.0,21.351.0,58.325.0,25.314.0,47.385.0"}
P.entries["topic:goblin"] = {n="Гоблин",s="Гоблины — миниатюрные хитрые гуманоиды с острова Кезан, известные по всему Азероту неутомимой погоней за прибылью, взрывной инженерией и напористыми торговыми картелями. Хотя большинство соблюдает строгий нейтралитет, чтобы извлекать максимум выгоды из торговли с Альянсом и Ордой, наемные и беспощадные объединения, такие как Торговая Компания и Картель Хитрая Шестеренка, оставили неизгладимый след в каждом уголке мира.",h="Гоблины — миниатюрные хитрые гуманоиды с острова Кезан, известные по всему Азероту неутомимой погоней за...",kw={"booty bay","cartel","deadmines","engineering","gadgetzan","goblin","kaja'mite","kezan","steamwheedle","venture company","пиратская бухта","картель","мертвые копи","инженерия","прибамбасск","гоблин","каджамит","кезан","хитрая шестеренка","торговая компания"},ang={["faction:Alliance"]="Власти Альянса глубоко не доверяют нейтралитету гоблинов, хорошо помня о том, как те за плату поставляли военные корабли и саперов Старой Орде во время Второй войны.",["faction:Horde"]="Хотя Орда Тралла пользуется услугами гоблинов-механиков и торгует в нейтральных центрах, еще свежа память о наемных контрактах, заключенных между Оргримом Молотом Рока и торговым принцем Хитрой Шестеренкой.",["profession:Engineering"]="Гоблинская инженерия ставит во главу угла предельную взрывную силу, наступательные устройства и рискованные механизмы, резко контрастируя с точными оборонительными разработками, которые предпочитают гномы.",["profession:Mining"]="Путь гоблинов от первобытных островитян до промышленных первопроходцев был обусловлен добычей каджамита, и современные картели ревностно охраняют ценные рудные участки в Калимдоре и Восточных королевствах."},sec={{t="Каджамит и торговые войны",b="Давным-давно на острове Кезан первобытных гоблинов поработили зандаларские тролли и заставили добывать залежи мощного минерала, расширяющего сознание, — каджамита. Вдыхание подземной рудной пыли резко повышало их интеллект. Втайне создав мощное огнестрельное оружие, взрывчатку и ловушки, гоблины внезапным восстанием свергли троллей-хозяев. Обретя свободу, их общество раскололось на соперничающие экономические объединения — картели. Когда жилы каджамита истощились, а вдохновенный гений стал переменчивым и нестабильным, гоблинские вожди направили свои амбиции на беспощадную торговлю и мировое промышленное господство."},{t="Наемники и меркантилизм",b="Во время Второй войны торговый принц Хитрая Шестеренка заключил союз между своим картелем и Ордой Оргрима Молота Рока, поставляя карты, осадные машины и опыт строительства флота в обмен на захваченную добычу Штормграда. После поражения Орды картели поняли, что открытая верность стоила им выгодных рынков. В наши дни крупные картели объявляют официальный нейтралитет и держат оживленные торговые гавани, такие как Пиратская бухта в Тернистой долине и Прибамбасск в пустыне Танарис. Там путешественники из Альянса и Орды встречаются без обнаженных клинков — пока портовые громилы поддерживают порядок."},{t="Наемные руки и промышленность",b="Главная верность гоблина принадлежит золоту, и многие работают вне нейтральных картелей — наемными специалистами или безжалостными корпоративными баронами. Торговая Компания беспрепятственно вырубает леса и истощает ресурсы на разных континентах, не заботясь о местных жителях. В других местах искусные мастера продают свои таланты напрямую преступным предприятиям: в глубине Мертвых копей гоблинские инженеры, такие как Снид, Гилнид и капитан Зеленямс, руководят плавильнями и корабелами, строящими для Братства Справедливости огромный броненосный колосс."}},faq={{q="Гоблины на стороне Альянса или Орды?",a="Ни тех, ни других. Главные торговые объединения, включая Картель Хитрая Шестеренка, строго соблюдают нейтралитет, чтобы свободно торговать с обеими сторонами. Отдельные гоблины и частные предприятия охотно предлагают свои услуги Орде, Альянсу или третьим сторонам, например Братству Справедливости, за подходящую цену.",al={"are goblins horde","goblin faction","who do goblins fight for","гоблины это орда","фракция гоблинов","за кого сражаются гоблины"}},{q="Почему гоблинские изобретения так часто взрываются?",a="Их внезапный технологический скачок был вызван вдыханием пыли каджамитовой руды. Поскольку запасы минерала на Кезане за поколения истощились, гоблинский разум стал более переменчивым, и в инженерии возобладал подход, ставящий грубую мощь, спешку и сильный взрыв выше прочности конструкции.",al={"goblin engineering dangerous","why do goblin machines blow up","goblin vs gnome tech","опасная гоблинская инженерия","почему взрываются гоблинские машины","гоблинская и гномья техника"}},{q="Что такое Картель Хитрая Шестеренка?",a="Картель Хитрая Шестеренка — самый влиятельный торговый картель на материке. Он управляет важными нейтральными портами и межконтинентальными транспортными узлами, включая Пиратскую бухту на юге Тернистой долины и Прибамбасск в пустыне Танарис.",al={"steamwheedle cartel","who rules booty bay","goblin ports","картель хитрая шестеренка","кто правит пиратской бухтой","порты гоблинов"}},{q="Что такое Торговая Компания?",a="Торговая Компания — безжалостный промышленный конгломерат под управлением гоблинов, известный агрессивной вырубкой лесов, открытой добычей полезных ископаемых и добычей нефти. В отличие от Картеля Хитрая Шестеренка, она действует, мало считаясь с местными законами и экологическим равновесием, и нередко вступает в жестокие столкновения с коренным населением.",al={"venture co","who are venture company","what is venture co","торговая компания","кто такая торговая компания","что такое торговая компания"}},{q="Почему гоблины работают с Братством Справедливости в Мертвых копях?",a="У Братства Справедливости было много награбленных денег и сырой руды из шахт Луноречья, что позволило нанять лучших гоблинских специалистов. Мастеров, таких как Снид, Гилнид и капитан Зеленямс, наняли руководить тяжелой плавкой и строить броненосный колосс Эдвина ван Клифа.",al={"deadmines goblins","why are goblins in deadmines","gilnid sneed deadmines","гоблины мертвые копи","почему гоблины в мертвых копях","гилнид снид мертвые копи"}},{q="Где находится родина гоблинов?",a="Гоблины родом с тропического острова Кезан в Южных морях. Именно там тролли поработили их, они нашли каджамит, сбросили оковы и построили империю торговли и промышленного смога.",al={"where do goblins come from","goblin home island","kezan","откуда родом гоблины","родной остров гоблинов","кезан"}}},fp="6,432,28.671.0,28.594.0,24.537.1,51.303.0,48.293.0,32.251.0,28.296.0,63.282.1,29.209.0"}
P.entries["topic:grimtotem-tribe"] = {n="Племя Зловещего Тотема",s="Племя Зловещего Тотема — агрессивный, яростно приверженный традициям клан тауренов, отказывающийся формально присягнуть Орде Тралла. Его воины отличаются темной шкурой и грозной боевой раскраской; они стремятся изгнать чужие расы из Калимдора и вернуть земли предков любой ценой. Хотя их матриарх, Мудрая старуха Магата Зловещий Тотем, живет на вершине Громового Утеса и занимается региональной политикой, ее соплеменники активно нападают на поселения по всему Калимдору.",h="Племя Зловещего Тотема — агрессивный, яростно приверженный традициям клан тауренов, отказывающийся формально...",kw={"darkcloud pinnacle","elder crone","freewind post","grimtotem","magatha","tauren tribe","thunder bluff","пик темного облака","мудрая старуха","застава вольного ветра","зловещий тотем","магата","племя тауренов","громовой утес"},ang={["faction:Alliance"]="Зловещий Тотем презирает всех, кто вторгся в Калимдор, и без разбора нападает на торговцев Альянса и поселения ночных эльфов.",["faction:Horde"]="Не принимайте их черные шкуры за признак союзников: в степях, горах и болотах Калимдора воины Зловещего Тотема нападают из засады на разведчиков Орды, едва завидев их.",["race:Tauren"]="Зловещий Тотем — открытый позор для Кровавого Копыта и других племен; хотя Кэрн дает им приют в Громовом Утесе во имя единства тауренов, их воинственность грозит разрушить это единство.",["race:Undead"]="Магата Зловещий Тотем — одна из немногих предводительниц тауренов в Громовом Утесе, кто открыто заигрывает с Отрекшимися, организуя исследования редких чум вместе со специалистами Королевского фармацевтического общества."},sec={{t="Племя особого пути",b="В отличие от своих миролюбивых сородичей, почитающих Мать-Землю, Зловещий Тотем считает, что Калимдор принадлежит исключительно тауренам. С юных лет их обучают не терпеливой гармонии Великой охоты, а безжалостности, скрытности и смертельному бою. Они питают глубокое презрение к другим расам, поселившимся на их древних землях. Хотя Кэрн Кровавое Копыто принял их в Громовом Утесе, стремясь объединить всех тауренов, клан Зловещего Тотема остается единственным крупным племенем, которое так и не вступило формально в Орду Тралла, преследуя собственные замкнутые и жестокие цели."},{t="Агрессоры диких земель",b="В глуши, вдали от бдительных глаз Громового Утеса, враждебность Зловещего Тотема открыто перерастает в насилие. В Когтистых горах они истребляют местные поселения и угрожают снабженческим форпостам Орды. На высоких плато Тысячи Игл, вокруг Пика Темного Облака, они постоянно досаждают Заставе Вольного Ветра и замышляют захватить каньон. Не менее опасны встречи в Фераласе: Зловещий Тотем без колебаний нападает на путников Орды, караваны Альянса и даже на собратьев-тауренов. Гарнизоны Орды в Приюте у Солнечного Камня и Лагере Мохаче регулярно назначают награды за их головы и посылают воинов, чтобы расправиться с этими жестокими изгоями."},{t="Тени и фармацевты",b="За маской духовного наставничества Магаты скрывается сложная паутина интриг. Мудрая старуха — ярая сторонница спорных связей тауренов с Отрекшимися: публично она заявляет, что хочет исцелить нежить, а втайне ищет смертоносные чумы и артефакты высокорожденных. В Тысяче Игл разведчики Заставы Вольного Ветра перехватывают тайную переписку между закутанными в плащи гонцами и вождями Зловещего Тотема на Пике Темного Облака."}},faq={{q="Почему Зловещий Тотем враждебен, если его предводительница живет в Громовом Утесе?",a="Племя Зловещего Тотема никогда формально не вступало в Орду. Хотя Кэрн Кровавое Копыто терпит Магату Зловещий Тотем на высоких плато Громового Утеса, надеясь сохранить мир среди всех тауренов, бродячие воины племени отвергают любую внешнюю дипломатию. В Когтистых горах, Тысяче Игл и Фераласе они нападают на всякого, кто вторгается на земли предков, в том числе на других тауренов.",al={"why grimtotem red","why do grimtotem attack horde","are grimtotem friendly","почему зловещий тотем враждебен","почему зловещий тотем нападает на орду","дружелюбны ли зловещий тотем"}},{q="Как отличить тауренов Зловещего Тотема от остальных тауренов?",a="Тауренов Зловещего Тотема почти всегда отличает смоляно-черная шерсть. Они также известны тем, что рисуют на теле и лице характерную резкую боевую раскраску ярко-белого, темно-красного или синего цвета.",al={"grimtotem appearance","grimtotem fur color","внешность зловещего тотема","цвет шерсти зловещего тотема"}},{q="Кто возглавляет племя Зловещего Тотема?",a="Племенем правит Мудрая старуха Магата Зловещий Тотем, могущественная шаманка, живущая на Вершине Старейшин в Громовом Утесе. Она получила власть, выйдя замуж за прежнего вождя, который вскоре после этого погиб при необъяснимом несчастном случае во время восхождения.",al={"grimtotem leader","elder crone","предводитель зловещего тотема","мудрая старуха"}},{q="Какова цель племени Зловещего Тотема?",a="Зловещий Тотем стремится очистить Калимдор от чужих рас, которые считает низшими, — орков, людей и ночных эльфов, — и вернуть все исконные земли тауренов. В отличие от народа Кэрна, они считают, что эти земли нужно захватить силой, обманом и властью над стихиями.",al={"what do grimtotem want","grimtotem motive","чего хочет зловещий тотем","мотивы зловещего тотема"}},{q="Почему Магата Зловещий Тотем сотрудничает с Отрекшимися?",a="Публично Магата заявляет, что поддерживает Отрекшихся, потому что шаманизм тауренов и мудрость земли могут излечить их недуг и вернуть им человечность. Втайне же она ищет их познания в смертельных ядах, гнили и темной магии, чтобы уничтожить своих врагов и укрепить власть над Калимдором.",al={"magatha and undead","grimtotem forsaken","магата и нежить","зловещий тотем отрекшиеся"}}},fp="15,454,13.612.0,19.624.0,24.439.1,69.362.0,53.184.0,24.239.0,27.288.0,50.293.1"}
P.entries["topic:grommash-hellscream"] = {n="Громмаш Адский Крик",s="Громмаш Адский Крик был легендарным вождем клана Песни Войны, близким соратником вождя Тралла и первым орком, отведавшим крови Маннорота. Хотя его жажда битвы когда-то привязала его народ к Пылающему Легиону, он искупил вину орков, убив повелителя демонов в Ясеневом лесу ценой собственной жизни.",h="Громмаш Адский Крик был легендарным вождем клана Песни Войны, близким соратником вождя Тралла и первым орком...",kw={"ashenvale","blood curse","cenarius","gorehowl","grom","grommash","hellscream","mannoroth","thrall","warsong","ясеневый лес","проклятие крови","кенарий","убийца","гром","громмаш","адский крик","маннорот","тралл","песнь войны"},ang={["class:Warrior"]="Воины изучают боевое мастерство Грома и владение Убийцей как вершину воинственной агрессии, видя в нем и ужасную цену неукрощенной ярости, и огромную силу несгибаемого боевого духа.",["faction:Horde"]="Для Орды Гром воплощает трагический путь ее основания: свирепый воин, чей безрассудный нрав ввергнул ее во тьму, но чья несгибаемая отвага купила ей выживание и свободу в Калимдоре.",["race:NightElf"]="Ночные эльфы вспоминают Грома с неугасающей горечью: как обезумевшего от демонов захватчика, осквернившего священные рощи Ясеневого леса и убившего полубога Кенария.",["race:Orc"]="Орки чтят Громмаша как своего величайшего спасителя. Его жертва в Ясеневом лесу разорвала демоническое Проклятие крови, державшее народ в рабстве поколениями, и позволила Новой Орде идти с гордостью и свободной волей."},sec={{t="Первый глоток и железная воля",b="Еще до того, как Темный портал соединил миры, Гром Адский Крик с неукротимой яростью возглавлял клан Песни Войны; его выделяли иссиня-черная татуировка на челюсти и смертоносные взмахи двуручного топора Убийца. Когда Гул'дан и Совет Теней предложили на Дреноре чашу демонической силы, Гром первым из вождей выпил крови властителя преисподней Маннорота. Этот роковой глоток обрек орков на демоническое рабство и пылающую жажду крови. Но в отличие от многих вождей, погибших или полностью покорившихся, Гром обладал железной волей, сохранившей его яростный дух: он пережил ужасы старой Орды, втайне тоскуя о том, чем пожертвовал его народ."},{t="Братство в глуши",b="Оставшись на Дреноре во время Второй войны, Гром позже прошел через Темный портал, но оказался в ловушке, когда портал был разрушен. Почти пятнадцать лет Гром и его уцелевшие воины Песни Войны скрывались от Альянса Лордерона, терпя вялость и отчаяние, охватившие орков после того, как демоническая кровь утратила силу. Надежда вспыхнула вновь, когда молодой беглец по имени Тралл разыскал его в глуши. Распознав в Тралле силу и благородное сердце, Гром наставлял его в гордом наследии их народа. Вместе с Оргримом Молотом Рока они сплотили разрозненные кланы, разрушили лагеря для интернированных орков и положили начало Новой Орде."},{t="Падение и последнее искупление",b="Прибыв в Калимдор во время Третьей войны, Гром в древних чащах Ясеневого леса вновь поддался неутоленной агрессии. Теснимый ночными эльфами и полубогом Кенарием, Гром снова не устоял и выпил из оскверненного источника, пропитанного кровью Маннорота, чтобы спасти свой клан. Повторно порабощенный повелителем демонов, Гром обратился против своего народа, пока Тралл и Джайна Праудмур не пленили его и не очистили его оскверненный дух древними шаманскими и тайными обрядами. Вернув рассудок и терзаясь глубокой виной, Гром преследовал Маннорота до Каньона Гибели Демона. В отчаянном последнем ударе он вонзил Убийцу в грудь повелителя демонов, навсегда разрушив демоническое проклятие, и адское пламя унесло его жизнь."}},faq={{q="Кем был Громмаш Адский Крик?",a="Громмаш «Гром» Адский Крик был вождем клана Песни Войны и доверенным помощником Тралла. Он прославился острым как бритва топором Убийца и стал печально известен как первый орк, принявший демонический договор, выпив крови Маннорота. Позже он искупил свое наследие, убив Маннорота в Калимдоре и освободив весь народ орков от Проклятия крови.",al={"who is grom","who was hellscream","grom hellscream backstory","кто такой гром","кем был адский крик","история грома адский крик"}},{q="Как погиб Гром?",a="Гром погиб в Каньоне Гибели Демона в Ясеневом лесу рядом с Траллом. Столкнувшись с властителем преисподней Манноротом, Гром взмыл в воздух и рассек грудь демона Убийцей. Смертельный удар разбил сердце демона, но последовавшая вспышка демонического адского пламени смертельно ранила Грома, и он умер, провозгласив, что наконец освободил себя и свой народ.",al={"grom death","how did grom hellscream die","who killed grom","смерть грома","как погиб громмаш адский крик","кто убил грома"}},{q="Как Гром связан с Траллом?",a="Когда Тралл бежал из лагеря для интернированных в Дарнхольде, Гром был первым вождем клана, кого он встретил. Гром взял молодого орка под свое крыло, обучая его традициям, языку и культуре орков. Тралл стал считать Грома старшим братом и духовным наставником, а Гром видел в Тралле провидца, способного вернуть их надломленный народ к чести.",al={"thrall and grom","how did thrall know grom","were thrall and grom friends","тралл и гром","откуда тралл знал грома","были ли тралл и гром друзьями"}},{q="Почему челюсть Грома была вытатуирована черным?",a="Став вождем клана Песни Войны на Дреноре, Гром ритуально покрыл нижнюю челюсть татуировкой иссиня-черного цвета. Она стала отличительным знаком его власти и железной воли на всю жизнь, и его яростные боевые кличи мгновенно узнавали на поле боя.",al={"grom black jaw","why is groms jaw black","grom tattooed lower jaw","черная челюсть грома","почему у грома черная челюсть","татуировка на челюсти грома"}},{q="Почему Гром выпил демонической крови во второй раз?",a="Когда клан Грома заготавливал лес в Ясеневом лесу, его почти уничтожили ночные эльфы и полубог Кенарий, чья божественная природа делала его почти неуязвимым для смертного оружия. Отчаянно стремясь спасти свой клан, Гром обнаружил водоем, оскверненный кровью Маннорота. Зная о страшной цене, он выпил из него, чтобы обрести демоническую ярость, необходимую для победы над Кенарием.",al={"why did grom drink again","grom chaos orcs","grom drank blood twice","почему гром выпил снова","гром орки хаоса","гром выпил кровь дважды"}},{q="Где похоронен Громмаш?",a="Гром покоится в Каньоне Гибели Демона на юго-востоке Ясеневого леса, на том самом месте, где он сразил Маннорота. Над его могилой стоит каменный памятник с эпитафией, написанной Траллом в честь его мужества и последней жертвы ради Орды.",al={"grom grave","grom monument","where is groms tomb","могила грома","памятник грома","где гробница грома"}}},fp="19,333,33.698.0,26.659.0,25.718.0,28.350.0,17.360.0,36.354.0,34.287.0,45.383.0,25.260.0"}
P.entries["topic:harpy"] = {n="Гарпия",s="Гарпии — хищные птицеподобные гуманоиды, похожие на крылатых ночных эльфов. Они обитают в зловонных гнездовьях по всему Калимдору и в высокогорных перевалах Альтерака. Известные пронзительными криками и бурной стихийной магией, они нападают на неосторожных путников и портят земли, где живут. Хотя фольклор ночных эльфов связывает их с проклятыми предательницами королевы Азшары, ученые возводят их происхождение к пернатому дикому богу Авиане.",h="Гарпии — хищные птицеподобные гуманоиды, похожие на крылатых ночных эльфов.",kw={"aviana","bloodfeather","dustwind","harpy","kalimdor","stonetalon","talons","windfury","witchwing","авиана","кровоперая","пыльный ветер","гарпия","калимдор","когтистые горы","когти","ярость ветра","ведьмино крыло"},ang={["class:Druid"]="Друиды испытывают к гарпиям особую скорбь и гнев, видя в них павших, хаотичных потомков Авианы, которые отказались от священного равновесия и загрязняют природу магией бури.",["race:NightElf"]="Хотя гарпии удивительно похожи на женщин-ночных эльфов, они воплощают извращение естественных небес: оскверняют священные ветви вокруг Поляны Оракула в Тельдрассиле и глумятся над памятью древней богини Авианы.",["race:Orc"]="Гарпии Пыльного Ветра, гнездящиеся в Сухой лощине и Каньоне Колючего Ветра, постоянно угрожают путям снабжения между Деревней Сен'джин, Колючим Холмом и Оргриммаром, что требует постоянных вооруженных патрулей.",["race:Tauren"]="Гарпии Ярости Ветра из Мулгора и выводок Визжащих из Тысячи Игл поколениями донимают караваны тауренов и разоряют равнины, поэтому племена ненавидят их как врагов."},sec={{t="Крылатая напасть Калимдора",b="У гарпий верхняя часть тела и голова как у женщин-ночных эльфов, а к ним добавлены широкие оперенные крылья и злобные когти. Несмотря на изящное эльфийское лицо, которое, как ни странно, с возрастом становится только выразительнее, их натура совершенно дика. Первоначально они гнездились среди скал Когтистых гор, но агрессивно расселились по Калимдору, терроризируя засушливые каньоны Дуротара, священные ветви Тельдрассила и возвышенности Мулгора. В отличие от диких существ, на которых они охотятся, гарпии не живут в гармонии с природой: они разоряют окрестную флору и фауну, превращая места гнездовий в мерзкие зловонные свалки, усеянные дочиста обглоданными костями жертв."},{t="Пернатый род и темная природа",b="Мифы ночных эльфов часто утверждают, что гарпии были вероломными служанками, проклятыми королевой Азшарой до Великого Раскола. Однако более глубокие изыскания в древней истории показывают, что это заблудшее потомство Авианы, древнего пернатого дикого бога. После гибели Авианы в Войне Древних и сожжения Матери-Древа Г'Ханир многие из ее пернатых детей поддались хаосу и горькому одиночеству и отказались от священной опеки над небом. За тысячелетия это отчаяние превратилось в чистую злобу. Сегодня гарпии живут безжалостными матриархатами, где желающие стать королевами должны предавать, убивать и мучить соперниц, чтобы удержать власть."},{t="Магия бури и злые повадки",b="Помимо того, что гарпии рвут плоть острыми как бритва когтями, они повелевают опасной магией ветра и молний, обрушивая сверху завывающие шквалы. Это очень хитрые охотники, способные говорить: порой они обменивают подобранные диковинки с подземными существами, например кобольдами, на яркие самоцветы и блестящие безделушки. Неосторожных исследователей иногда завлекает их эльфийский облик, но физический контакт опасен: поцелуй гарпии ядовит и быстро вызывает яростную изнуряющую лихорадку у тех, кто глупо потерял бдительность."}},faq={{q="Откуда гарпии родом?",a="Гарпии родом с зазубренных пиков Когтистых гор в центре Калимдора. С этих родовых высот их популяции быстро расселились, обосновавшись в Тельдрассиле, Степях, Дуротаре, Мулгоре, Фераласе, Тысяче Игл и даже за Великим морем, на снежных утесах Альтеракской долины.",al={"harpy origins","harpy homeland","where do harpies live","происхождение гарпий","родина гарпий","где живут гарпии"}},{q="Родственны ли гарпии ночным эльфам?",a="Фольклор Калимдора гласит, что они когда-то были женщинами-ночными эльфами, проклятыми за предательство королевы Азшары, но исследования дворфов и древние предания устанавливают, что гарпии на самом деле происходят от Авианы, древней богини птиц, погибшей в Войне Древних.",al={"are harpies night elves","harpy night elf connection","curse of azshara","гарпии ночные эльфы","связь гарпий с ночными эльфами","проклятие азшары"}},{q="Почему гнезда гарпий так печально известны?",a="В отличие от диких птиц, гарпии оскверняют землю вокруг себя. Их гнезда — грязные, зловонные свалки из вытоптанной растительности, ядовитых отходов, костей и останков неосторожных путников и зверей, которых они утаскивают с ближайших троп.",al={"harpy smell","what are harpy nests like","harpy roosts","запах гарпий","какие гнезда у гарпий","гнездовья гарпий"}},{q="Как стаи гарпий выбирают предводительниц?",a="За власть у гарпий идет жестокая борьба. Чтобы получить и удержать титул королевы или матриарха, гарпия должна доказать, что она гораздо безжалостнее своих сородичей, прибегая к предательству, убийствам и неустанной жестокости против врагов и соперниц.",al={"harpy matriarch","harpy queen","who leads harpies","матриарх гарпий","королева гарпий","кто правит гарпиями"}},{q="Какие силы и боевые тактики используют гарпии?",a="Обычные гарпии пикируют сверху, используя грубое оружие или острые как бритва когти. Их заклинательницы же владеют бурной магией шторма и поражают врагов трескучими молниями, вихрями ветра и пронзительными дезориентирующими криками.",al={"harpy abilities","harpy magic","how do harpies fight","способности гарпий","магия гарпий","как сражаются гарпии"}},{q="Правда ли, что поцелуй гарпии опасен?",a="Да. Помимо когтей и магии бури, гарпии несут ядовитый поцелуй. Путники, которых эльфийские черты заманили подпустить гарпию близко, рискуют отравиться сильным ядом, вызывающим внезапную изнуряющую лихорадку.",al={"harpy kiss","harpy poison","harpy fever","поцелуй гарпии","яд гарпий","лихорадка гарпий"}}},fp="5,429,26.681.0,29.656.0,31.567.0,38.326.0,44.256.0,32.244.0,41.242.0,46.228.0,44.218.0"}
P.entries["topic:highborne"] = {n="высокорожденные",s="Высокорожденные, или кель'дорай, были аристократической кастой чародеев древней империи кальдораев и служили королеве Азшаре. Их безрассудное обращение с Источником Вечности привело Пылающий Легион в Азерот, что вызвало разрушительную Войну Древних и Великий Раскол.",h="Высокорожденные, или кель'дорай, были аристократической кастой чародеев древней империи кальдораев и служили...",kw={"azshara","dath'remar","dire maul","eldre'thalas","highborne","quel'dorei","sargeras","shen'dralar","well of eternity","zin-azshari","азшара","дат'ремар","забытый город","эльдре'талас","высокорожденные","кель'дорай","саргерас","шен'дралар","источник вечности","зин-азшари"},ang={["class:Druid"]="Друидизм возник как естественная философия, противостоявшая безрассудной эксплуатации Источника Вечности высокорожденными, и дал основу для исцеления Калимдора после падения империи.",["class:Mage"]="Высокорожденные были первыми смертными на Азероте, овладевшими тайной магией, и их захватывающие достижения и катастрофические ошибки установили опасные правила современного колдовства.",["class:Warlock"]="Высокорожденные были первыми смертными на Азероте, кто вел дела с Пылающим Легионом, выменивая космические тайны и демонические договоры, проложившие путь современным изучениям магии Скверны.",["race:NightElf"]="Память о касте высокорожденных остается глубоким шрамом в культуре ночных эльфов и единственной причиной, по которой тайная магия запрещена по всему Калимдору под страхом изгнания или смерти."},sec={{t="Аристократы Источника",b="До Раскола высокорожденные возвысились как привилегированный высший класс вокруг королевы Азшары. Считая себя выше простых кальдораев из-за отборных родословных, ума и пышных привилегий, они строго контролировали доступ к Источнику Вечности. Они научились черпать и направлять его изначальную тайную энергию, возводя великолепные города по всему древнему Калимдору. Их ненасытная жажда большего колдовства заставляла их черпать из Источника все глубже, и его спокойные воды стали бурными и темными."},{t="Предательство и Раскол",b="Волны тайной силы, порожденные колдовством высокорожденных, привлекли внимание темного титана Саргераса и Пылающего Легиона. Убежденные Азшарой и ее советником Ксавиусом, что демоны переделают мир в нетронутый рай, высокорожденные открыли огромные врата прямо в Источнике. Это развязало катастрофическую Войну Древних. Пока демонические орды истребляли население, силы повстанцев под предводительством Малфуриона Ярость Бури пытались закрыть портал, из-за чего Источник Вечности схлопнулся и разорвал суперконтинент."},{t="Рассеянные наследники и остатки",b="Судьба высокорожденных раскололась после Раскола. Те, кого утянуло под волны вместе с Азшарой, превратились в змеевидных наг, другие поддались демоническим проклятиям и стали сатирами. Фракция под началом Дат'Ремара Солнечного Скитальца помогла сопротивлению, но отказалась оставить тайную магию и в итоге была изгнана за море, где основала королевство высших эльфов Кель'Талас. Сегодня обособленные общины, такие как Шен'дралар, остаются замкнутыми в Эльдре'Таласе — отвергнутые реликты империи, едва не уничтожившей Азерот."}},faq={{q="Что означает «высокорожденные»?",a="На дарнасском они зовутся кель'дорай, что буквально переводится как «дети благородного рождения». Они выбрали это имя, чтобы отличить свои аристократические родословные и магические способности от остального общества кальдораев.",al={"queldorei meaning","what does queldorei mean","highborne translation","значение кель'дорай","что значит кель'дорай","перевод высокорожденные"}},{q="Связаны ли современные ночные эльфы с высокорожденными?",a="Да. Высокорожденные были лишь благородной правящей кастой древних ночных эльфов, владевшей магией. Если не считать чуть более бледной кожи и склонности к вычурной одежде, физически это была та же раса. После Раскола современное общество ночных эльфов запретило тайную магию и полностью упразднило касту.",al={"are night elves highborne","difference between night elves and highborne","highborne night elf connection","ночные эльфы высокорожденные","разница между ночными эльфами и высокорожденными","связь высокорожденных с ночными эльфами"}},{q="Как высокорожденные вызвали Войну Древних?",a="Их чрезмерное и бесконтрольное использование Источника Вечности пустило магическую рябь по космосу и привлекло Пылающий Легион. Соблазненные обещаниями Саргераса о несравненной власти и идеальном мире, Азшара и ее знать направили силу Источника на создание портала и впустили демоническую армию прямо в Калимдор.",al={"why did burning legion come","how did highborne summon demons","highborne war of ancients role","зачем пришел пылающий легион","как высокорожденные призвали демонов","роль высокорожденных в войне древних"}},{q="Все ли высокорожденные встали на сторону королевы Азшары?",a="Нет. Несколько групп откололись, увидев демоническое разорение. Чародеи под началом Дат'Ремара Солнечного Скитальца перешли на сторону Сопротивления кальдораев Малфуриона, а такие группы, как Шен'дралар в Эльдре'Таласе, сосредоточились на выживании и защите собственных владений.",al={"good highborne","did any highborne fight azshara","highborne resistance","хорошие высокорожденные","сражались ли высокорожденные с азшарой","сопротивление высокорожденных"}},{q="Что стало с выжившими высокорожденными после войны?",a="Их род рассеялся по нескольким судьбам. Многие из тех, кто затонул вместе с Зин-Азшари, стали нагами, другие превратились в сатиров, а последовавшие за Дат'Ремаром были изгнаны в Восточные королевства и стали высшими эльфами. Немногие, как Шен'дралар в Забытом Городе, остались замкнутыми в древних руинах.",al={"what became of the highborne","where are the highborne now","highborne descendants","что стало с высокорожденными","где сейчас высокорожденные","потомки высокорожденных"}},{q="Кто такие Шен'дралар?",a="Шен'дралар — древняя секта ученых и магов из числа высокорожденных, успешно защитившая южный город Эльдре'Талас во время Великого Раскола. Отрезанные от королевы Азшары и основного общества кальдораев, они укрылись в городе, ныне называемом Забытым Городом, и полагаются на темное колдовство, чтобы сохранить бессмертие.",al={"dire maul highborne","eldre thalas elves","who lives in dire maul","высокорожденные забытый город","эльфы эльдре'талас","кто живет в забытом городе"}}},fp="9,286,23.503.0,30.551.0,28.516.0,27.225.0,48.296.0,52.312.0,42.273.0,55.307.0,24.330.0"}
P.entries["topic:horde"] = {n="Орда",s="Орда — союз изгнанных народов, объединившихся под началом вождя Тралла ради общего выживания и свободы. Основой фракции служит шаманская связь орков, троллей племени Черного Копья и таурен Калимдора; кроме того, Орда поддерживает шаткий союз по расчету с Отрекшимися в Лордероне. Из-за исторических обид и враждебных соседей Орда ценит силу, действие и честь выше политических интриг.",h="Орда — союз изгнанных народов, объединившихся под началом вождя Тралла ради общего выживания и свободы.",kw={"cairne bloodhoof","darkspear","durotar","forsaken","horde","kalimdor","new horde","orgrimmar","tauren","thrall","vol'jin","warchief","кэрн кровавое копыто","черное копье","дуротар","отрекшиеся","орда","калимдор","новая орда","оргриммар","таурены","тралл","вол'джин","вождь"},ang={["faction:Alliance"]="В глазах людей, дворфов и эльфов Орда остается сборищем чудовищных дикарей и вероломных мертвецов, которым нельзя доверять соблюдение какого бы то ни было мира.",["race:Orc"]="Новая Орда — путь вашего народа к искуплению: отринув наследие демонической крови, вы возвращаете шаманскую честь предков под знаменем Тралла.",["race:Tauren"]="Встав плечом к плечу с орками в войнах с кентаврами, племена сохранили свои священные земли в Мулгоре и обрели верных духовных братьев.",["race:Troll"]="Спасенное флотом Тралла от гибели на родном острове, племя Черного Копья поклялось отдать свои копья и тени ради выживания Орды.",["race:Undead"]="Членство Отрекшихся в Орде — важный щит от живых, которые хотели бы очистить Лордерон, хотя многие в Калимдоре с тихой опаской относятся к вашим методам."},sec={{t="Возрожденный союз",b="Нынешняя Орда мало похожа на демоническое войско, прошедшее через Темный портал в Первой и Второй войнах. Разорвав хватку Пылающего Легиона на своем народе, вождь Тралл повел орков через Великое море в Калимдор, чтобы создать духовную родину, основанную на традициях предков и чести. По пути Тралл заключил прочные союзы с изгнанными троллями племени Черного Копья Вол'джина и племенами таурен Кэрна Кровавого Копыта: плечом к плечу они отражали набеги кентавров и демонов в Третьей войне."},{t="Основа Орды в Калимдоре",b="В Калимдоре орки основали государство в Дуротаре и построили крепость-столицу Оргриммар, предоставив племени Черного Копья убежище на близлежащих Островах Эха. К югу, на зеленых равнинах Мулгора, кочевые таурены объединились вокруг Громового Утеса под началом верховного вождя Кэрна Кровавого Копыта. Эти три народа разделяют шаманское почитание, глубокую связь с природой и нужду в выживании, и видят друг в друге не тактических союзников, а вечную семью, скрепленную пролитой кровью и духовным уважением."},{t="Союз по расчету",b="За морем, в разоренных землях Лордерона, леди Сильвана Ветрокрылая вывела свободных Отрекшихся из-под власти Плети. Отчаянно нуждаясь в союзниках против уцелевших человеческих фракций и остатков Плети, Сильвана отправила посланников и в Штормград, и к Орде. Люди прогнали ее гонцов, а верховный друид Хамуул Рунический Тотем доказывал, что нежить можно спасти духовно. Убежденный Кэрном Кровавым Копытом, Тралл принял Отрекшихся в Орду, получив важный военный оплот в Восточных королевствах, несмотря на стойкие сомнения в рядах Калимдора."},{t="Холодная война",b="Несмотря на надежды Тралла на прочный мир с Альянсом, наследие Старой Орды отбрасывает неизбежную тень. В глазах людей и дворфов орки остаются кровожадными захватчиками, а нежити нельзя доверять. Столкновения из-за ценной древесины в Ясеневом лесу и стычки на границах ввергли обе фракции в напряженную, хрупкую холодную войну. Тралл активно направляет походы против демонических культов, таких как Пылающий Клинок, чтобы доказать, что Орда порвала связи с Легионом, но застарелая ненависть грозит вновь разжечь полномасштабную войну от любой искры."}},faq={{q="Чем Старая Орда отличается от Новой Орды?",a="Старая Орда была одержимым жаждой крови войском завоевателей, которым манипулировал Пылающий Легион, заставив вторгнуться в Азерот в Первой и Второй войнах. Новая Орда, основанная вождем Траллом, отвергла демоническую порчу, вернулась к шаманизму предков и преобразовалась в оборонительный союз изгнанников, ищущих выживания, земли и духовного возрождения.",al={"old horde vs new horde","how is this horde different","is this the same horde","старая орда и новая орда","чем эта орда отличается","та же ли это орда"}},{q="Кто возглавляет Орду?",a="Фракцию возглавляет вождь Тралл, чья резиденция находится в Аллее Мудрости в Оргриммаре. Тралл руководит военными и дипломатическими делами всей Орды, но опирается на советы и руководство Верховного вождя таурен Кэрна Кровавого Копыта, Охотника-призрака Вол'джина из племени Черного Копья и леди Сильваны Ветрокрылой из Отрекшихся.",al={"who is the horde leader","horde warchief","who rules the horde","кто лидер орды","вождь орды","кто правит ордой"}},{q="Почему Отрекшиеся входят в Орду?",a="Окруженная враждебными остатками Альянса и Плетью в Лордероне, Сильвана Ветрокрылая отправила послов на поиски союзников для выживания. Верховный друид Хамуул Рунический Тотем считал, что Отрекшихся можно исцелить духовно, и призвал Кэрна Кровавого Копыта ходатайствовать за них. Кэрн убедил неохотного Тралла принять их, и Орда получила важный оборонительный плацдарм в Восточных королевствах.",al={"why are undead in horde","how did forsaken join horde","tauren helped undead join","почему нежить в орде","как отрекшиеся вступили в орду","таурены помогли нежити вступить"}},{q="Где находится столица Орды?",a="Укрепленный город Оргриммар, встроенный в скалы северного Дуротара в Калимдоре, служит административным и военным центром Орды. В нем находится трон Тралла, а также кварталы для делегатов троллей, таурен и Отрекшихся.",al={"horde capital","what is the horde main city","where does thrall rule","столица орды","главный город орды","где правит тралл"}},{q="Находятся ли Орда и Альянс сейчас в состоянии войны?",a="Формально фракции пребывают в шатком перемирии, заключенном после битвы на горе Хиджал. Однако пограничные конфликты из-за древесины в Ясеневом лесу, территориальные трения в Альтеракских горах и застарелая историческая ненависть удерживают обе стороны в тлеющей холодной войне с локальными стычками.",al={"are we at war with alliance","horde alliance war classic","is it peace or war","мы воюем с альянсом","война орды и альянса классик","мир или война"}},{q="Все ли тролли принадлежат к Орде?",a="Нет. Племя Черного Копья — основное троллье племя Орды, приплывшее в Калимдор вместе с Траллом. Большинство других племен троллей в Азероте враждебны, хотя некоторые группы, например племя Хищного Бивня во Внутренних землях, поддерживают отдельный договор о дружбе и взаимной защите, не вступая в Орду официально.",al={"which trolls are horde","are forest trolls horde","trolls in horde","какие тролли в орде","лесные тролли в орде","тролли в орде"}}},fp="5,427,14.534.0,17.497.0,26.598.0,10.560.0,63.341.0,20.348.0,39.389.0,34.233.0,53.310.0,34.308.0"}
P.entries["topic:house-of-nobles"] = {n="Дом знати",s="Дом знати — наследственный аристократический совет, помогающий управлять королевством Штормград из Крепости Штормграда. Обладая огромным влиянием на земли, налоги и торговлю региона, он отказался платить рабочим отстроенного города, что вызвало кровавые бунты, породившие Братство Справедливости.",h="Дом знати — наследственный аристократический совет, помогающий управлять королевством Штормград из Крепости...",kw={"baurles wishock","defias","erlgadin","gregor lescovar","house of nobles","katrana prestor","nobles","stonemasons guild","tiffin wrynn","vancleef","борлс вишлок","братство справедливости","эрлгадин","грегор лесковар","дом знати","катрана престор","дворяне","гильдия каменщиков","тиффин ринн","ван клиф"},ang={["class:Rogue"]="Злобные склоки знати, продажные сделки и грязные тайны дают много работы посредникам, карманникам и мастеру-сыровару Иллингу Триасу.",["class:Warlock"]="Служители темных искусств Штормграда под «Забитым ягненком» сталкиваются с нежеланными расспросами влиятельных дворян.",["faction:Alliance"]="Хотя Дом знати силен при дворе Штормграда, на весь Великий Альянс его влияние невелико, однако его скупость постоянно угрожает стабильности южных человеческих земель.",["race:Human"]="Для людей Западного Края и Сумеречного леса Дом знати олицетворяет высокомерных аристократов, уютно сидящих в мраморных дворцах, пока простой люд истекает кровью, защищая свои усадьбы от бандитов и чудовищ."},sec={{t="Аристократы королевства",b="Дом знати, состоящий из самых могущественных патрицианских родов Штормграда, служит главным совещательным органом при Короне. Поскольку аристократия владеет большей частью пахотных земель в Элвиннском лесу, Западном Крае и Сумеречном лесу, она обладает огромной властью над торговлей, местными судьями и королевскими указами. Хотя официально королевством правят юный король Андуин Ринн и верховный лорд Болвар Фордрагон, совет регулярно связывает трону руки бюрократией, присваивая себе право затягивать суды, блокировать казни и вмешиваться в управление провинциями."},{t="Бунт рабочих",b="После Второй войны Дом знати нанял гильдмастера Эдвина ван Клифа и Гильдию каменщиков, чтобы отстроить Штормград из пепла. Однако знать одновременно залезла в огромные долги, расширяя военные рубежи королевства на юг, в Тернистую долину. Когда сияющая столица была готова, дворяне отказались от счета и не выплатили рабочим полную плату. Разъяренные предательством, каменщики устроили бунт на улицах. Брошенный в суматохе камень попал в королеву Тиффин Ринн и убил ее, после чего знать изгнала гильдию, и разоренные рабочие отправились в Западный Край, где создали Братство Справедливости."},{t="Бюрократический паралич",b="Пока король Вариан пропал, дворяне в основном бросили окраины королевства на произвол судьбы, используя королевскую власть для мелких склок. Чиновники Темнолесья негодуют: Дом знати отменил их смертный приговор расхитителю могил Декстрену Варду, приказав сохранить ему жизнь и перевести в Тюрьму Штормграда. Точно так же казнь вождя орков Черной горы Таргорра Ужасного бесконечно откладывается лишь потому, что один интриган хочет использовать чудовище как политическую пешку, а местные стражи наблюдают, как Штормград гниет изнутри."},{t="Шепот об измене",b="Упрямство совета далеко не простая жадность. На деле леди Катрана Престор — втайне черная драконица Ониксия — систематически манипулировала Домом знати, чтобы парализовать королевство. Подогревая высокомерие аристократии на переговорах с каменщиками и побуждая копить королевскую казну, она устроила и внутренний крах державы, и похищение короля. Высокопоставленные аристократы, такие как лорд Грегор Лесковар, открыто сговариваются с Братством Справедливости в тени трона, не давая имперским войскам выступить на спасение окраинных городов."}},faq={{q="Что такое Дом знати?",a="Дом знати — правящее аристократическое собрание Штормграда, состоящее из видных землевладельческих семей, чьи титулы и места передаются по наследству. Они служат советниками монарха и контролируют значительную часть внутренней политики, налогов и трудового законодательства королевства.",al={"what is the house of nobles","who are the nobles in stormwind","house of nobles lore","что такое дом знати","кто такие дворяне в штормграде","предания дома знати"}},{q="Почему Дом знати отказался платить каменщикам?",a="Знать сильно истощила казну Штормграда, финансируя дорогостоящие военные походы на юг, в Элвиннский лес и Тернистую долину. Когда Эдвин ван Клиф представил счет за восстановление Штормграда, дворяне не смогли заплатить, предложили лишь долю обещанного и в итоге приказали распустить гильдию.",al={"why didn't stonemasons get paid","why did nobles stiff vancleef","defias unpaid","почему каменщикам не заплатили","почему дворяне обманули ван клифа","братство справедливости неоплата"}},{q="Кто убил королеву Тиффин Ринн?",a="Во время бунта каменщиков, вызванного отказом Дома знати платить, неизвестный бунтовщик швырнул в толпу булыжник. Он попал королеве Тиффин Ринн в голову и убил ее на месте, навсегда сорвав любые мирные переговоры между короной и рабочими.",al={"how did tiffin die","queen tiffin death","who threw the rock at the queen","как умерла тиффин","смерть королевы тиффин","кто бросил камень в королеву"}},{q="Почему Штормград не посылает войска на помощь Западному Краю или Сумеречному лесу?",a="Дом знати контролирует кошелек королевства и административные разрешения. Знать постоянно блокирует финансирование, переброску войск и городскую помощь окраинам, оставляя местные ополчения, такие как Народное ополчение и Ночной Дозор, в полной изоляции.",al={"why no help for duskwood","why does stormwind ignore westfall","why won't stormwind send army","почему нет помощи сумеречному лесу","почему штормград игнорирует западный край","почему штормград не шлет армию"}},{q="Кто такой лорд Борлс К. Вишлок?",a="Лорд Борлс К. Вишлок — влиятельный дворянин, добивающийся расследования деятельности чернокнижников под «Забитым ягненком». Последствия его расследования раскрываются в цепочке заданий чернокнижника.",al={"lord wishock","baurles wishock","noble murdered by warlocks","лорд вишлок","борлс вишлок","дворянин убит чернокнижниками"}},{q="Все ли дворяне обернулись против каменщиков?",a="Нет. Королева Тиффин Ринн изначально поддерживала каменщиков, как и граф С. Дж. Эрлгадин, яростно добивавшийся повышения их платы и улучшения условий труда. Эрлгадин так возмутился предательством гильдии со стороны равных себе, что полностью отказался от титула и места и, покинув общество, присоединился к экспедиции Хеминга Эрнестуэя в Тернистой долине.",al={"did any nobles help stonemasons","count erlgadin","nobles who supported masons","помогали ли дворяне каменщикам","граф эрлгадин","дворяне поддержавшие каменщиков"}}},fp="15,309,24.565.0,16.656.0,22.612.1,19.582.1,28.278.0,58.318.0,30.286.0,61.284.1,32.197.1,48.334.0"}
P.entries["topic:human"] = {n="Человек",s="Люди — приспособляемая и стойкая смертная раса, во многом определившая историю Восточных королевств. Некогда объединенная под властью древней Араторской империи, их цивилизация распалась на Семь королевств, и теперь Штормград остается главным уцелевшим оплотом человечества в составе Альянса.",h="Люди — приспособляемая и стойкая смертная раса, во многом определившая историю Восточных королевств.",kw={"alliance","arathor","human","lordaeron","mankind","stormwind","thoradin","troll wars","wrynn","альянс","аратор","человек","люди","лордерон","человечество","штормград","торадин","тролльи войны","ринн"},ang={["class:Mage"]="Магия людей восходит к Тролльим войнам, когда высшие эльфы обучили первую сотню человеческих магов, что в итоге привело к основанию Даларана.",["class:Paladin"]="Рыцари Серебряной Длани были основаны человеческими священниками и рыцарями в Лордероне для борьбы с ужасами Второй войны.",["faction:Alliance"]="Дипломатия и решимость людей создали Альянс Лордерона, а Штормград остается политическим и военным сердцем фракции.",["faction:Horde"]="Люди были первыми врагами, с которыми столкнулись орки, пройдя через Темный портал, что положило начало трем жестоким войнам за выживание на Азероте.",["race:Human"]="Как человек, вы несете наследие павшего Аратора и разрушенного Лордерона; защита и выживание королевств смертных лежат прежде всего на плечах Штормграда."},sec={{t="Араторская империя",b="Тысячелетия назад первые люди жили разрозненными кочевыми племенами, которым постоянно угрожали лесные тролли Амани. Понимая, что разобщенность означает гибель, полководец Торадин из племени Арати объединил разрозненные кланы дипломатией и завоеваниями и основал Араторскую империю со столицей-крепостью Стром. Во время Тролльих войн осажденные высшие эльфы Кель'Таласа заключили союз с Аратором и обучили сто человек тайным искусствам магии. Вместе они разгромили армии троллей, обеспечив людям господство на центральных континентах и заложив основу будущих союзов смертных."},{t="Распад на Семь королевств",b="Когда Аратор окреп и разбогател, его отдаленные поселения превратились в могущественные самодостаточные города-государства. Со временем централизованная империя раскололась на семь отдельных держав: Гилнеас, Альтерак, Даларан, Лордерон, Кул Тирас, Штормград и Стромгард (первоначальный дом Строма). Эти государства активно торговали с дворфами, гномами и эльфами, но мир был хрупким. Территориальные споры, приграничные стычки — например, непрекращающиеся горные распри между Альтераком и Стромгардом — и придворные интриги разъедали королевства, порождая глубокую вражду, которая сохранялась, пока внешние катастрофы не заставили их действовать."},{t="Вторжение и разорение",b="Появление орочьей Орды через Темный портал положило конец внутренним склокам людей. Штормград был разрушен в Первую войну, а его беженцы бежали на север, чтобы предупредить другие королевства. В ответ король Теренас Менетил II помог создать Альянс Лордерона, объединивший силы людей, дворфов, гномов и высших эльфов, чтобы победить Орду во Второй войне. Хотя Штормград был кропотливо отстроен заново, трагедия случилась вновь: чума Плети опустошила Лордерон, а Даларан пал в Третью войну, оставив северные человеческие королевства в дымящихся руинах."},{t="Шаткое настоящее",b="Сегодня Штормград — сильнейшее из уцелевших человеческих королевств и опора великого Альянса. Однако мира по-прежнему нет. Король Вариан Ринн загадочно исчез по пути на дипломатическую встречу, и на трон возведен его десятилетний сын Андуин Ринн, а верховный лорд Болвар Фордрагон служит регентом. На севере выжившие жители Лордерона рассеяны или мертвы, а Гилнеас прячется за своей исполинской Стеной Седогрива, и бремя защиты человечества ложится на Штормград."}},faq={{q="Каковы были Семь королевств людей?",a="Семь королевств возникли, когда древняя Араторская империя распалась на независимые города-государства: Лордерон, Штормград, Стромгард, Даларан, Кул Тирас, Гилнеас и Альтерак. Каждое развило собственную культуру — от мореходных флотов Кул Тираса до магических колледжей Даларана.",al={"seven human kingdoms","human nations","arathor kingdoms","семь королевств людей","человеческие государства","королевства аратора"}},{q="Откуда изначально пришли люди?",a="Люди появились тысячи лет назад как кочевые племена, бродившие по лесам и нагорьям севера Восточных королевств, особенно вокруг Тирисфальских лесов, а затем объединились в первое человеческое государство под предводительством полководца Торадина.",al={"human origin","ancient humans","human ancestors","происхождение людей","древние люди","предки людей"}},{q="Что случилось с королевством Лордерон?",a="Лордерон был опустошен в Третью войну чумой нежити, распространенной Плетью, и предан собственным принцем, Артасом Менетилом. Сегодня его разрушенная столица и окрестные земли оспариваются нежитью — Отрекшимися и Плетью, а также остатками прежних сил, такими как Алый орден.",al={"why is lordaeron destroyed","fall of lordaeron","fate of lordaeron","почему разрушен лордерон","падение лордерона","судьба лордерона"}},{q="Кто сейчас правит человечеством и Штормградом?",a="Поскольку король Вариан Ринн пропал при подозрительных обстоятельствах, на троне как номинальный правитель сидит его юный сын Андуин Ринн, а верховный лорд Болвар Фордрагон правит как регент вместе с королевским советником леди Катраной Престор.",al={"who leads stormwind","king of stormwind","stormwind ruler","кто правит штормградом","король штормграда","правитель штормграда"}},{q="Почему высшие эльфы обучили людей магии?",a="Во время древних Тролльих войн высшим эльфам Кель'Таласа грозило полное уничтожение от троллей Амани. Отчаянно нуждаясь в военной поддержке, они заключили договор с Торадином, правителем Аратора, согласившись обучить сто человек тайной магии в обмен на людские армии.",al={"elves taught humans magic","first human mages","troll wars magic","эльфы научили людей магии","первые маги людей","магия тролльих войн"}},{q="Какую роль сыграли люди в создании Альянса?",a="После падения Штормграда под натиском орков в Первой войне беженцы-люди сплотили северные королевства. Под началом короля Теренаса Лордеронского и лорда Лотара из Штормграда человеческие державы объединились с дворфами Стальгорна, гномами и высшими эльфами, создав Альянс Лордерона.",al={"formation of alliance","alliance of lordaeron origin","how did alliance start","создание альянса","происхождение альянса лордерона","как начался альянс"}}},fp="5,297,21.619.0,28.619.0,17.572.0,20.504.0,41.281.0,38.227.0,42.272.0,43.221.0,42.269.0,50.266.0"}
P.entries["topic:hunter"] = {n="Охотник",s="Охотники — мастера выживания в дикой природе и смертоносной стрельбы — странствуют по нетронутым уголкам Азерота вместе со свирепыми питомцами. Вооруженные луками, ружьями или арбалетами, они превосходно изводят врагов на расстоянии, используя хитроумные ловушки и первобытные дары-аспекты, чтобы управлять ходом боя. Выслеживают ли они неуловимую добычу среди заснеженных вершин или крадутся за жертвой в густых лесах, они полагаются на смекалку и связь с природой.",h="Охотники — мастера выживания в дикой природе и смертоносной стрельбы — странствуют по нетронутым уголкам...",kw={"archery","aspects","beasts","hunter","marksmanship","pet","rifle","survival","tracking","traps","стрельба из лука","аспекты","звери","охотник","меткость","питомец","ружье","выживание","выслеживание","ловушки"},ang={["class:Hunter"]="Ваша сила — в связи с дикой природой и вашим питомцем. Овладейте своим арсеналом дальнего боя, держите дистанцию и позвольте питомцу удерживать внимание врага.",["race:Dwarf"]="Дворфы-стрелки славятся меткостью с тяжелыми ружьями: они проходят коварные горные перевалы Каз Модана вместе со свирепыми белыми медведями.",["race:NightElf"]="Тысячелетиями Часовые кальдораи патрулируют древние леса с луками и верными саблями, защищая священные рощи от внешней порчи.",["race:Orc"]="Орки-повелители зверей чтят родовые традиции выживания, выкованные в суровых мирах, и создают нерушимые боевые узы с верными волками и кабанами.",["race:Tauren"]="Для таурена охота — священное духовное испытание выносливости и почтения: он чтит Мать-Землю, уважая каждого зверя, который кормит и одевает племя."},sec={{t="Родство с дикой природой",b="В основе каждого охотника лежит инстинктивное сопереживание первозданному миру. В отличие от тех, кто эксплуатирует природу или замыкается в каменных крепостях, охотники полностью погружаются в дикие земли. Они изучают повадки, движения и силу хищных зверей, завоевывая их уважение, а не ломая их дух. Терпеливо налаживая связь, охотник приручает опасных существ — свирепых хищных кошек, упрямых горных медведей и зорких ящеров-хищников — и превращает диких животных в верных союзников, готовых защищать его до смерти."},{t="Мастера стрельбы и следопыты",b="На поле боя охотники диктуют условия схватки с безопасного расстояния. Вооруженные луками, тяжелыми арбалетами или точными ружьями, они выпускают смертоносные залпы, пробивающие тяжелые доспехи прежде, чем противник успеет приблизиться. Их отточенные чувства делают их непревзойденными следопытами, способными уловить малейшие следы, запахи и приметы, оставленные добычей. Когда враги пытаются сократить дистанцию, охотники применяют ледяные и огненные ловушки, сбивающие с толку засады или ловкие маневры уклонения, удерживая противников там, где им нужно."},{t="Традиции разных культур",b="Путь охотника по-разному проявляется в культурах Азерота. Часовые-ночные эльфы воплощают древнее искусство стрельбы и скрытности под сенью Ясеневого леса, используя луки и теневое мастерство в тихом согласии с дикой природой. Дворфы-стрелки с ружьями отваживаются на ледяные скалы Дун Морога вместе с выносливыми медведями, постигая инженерное дело пороха. По всему Калимдору следопыты-таурены и орки чтят древние кочевые обычаи, преследуя добычу со священным почтением и призывая духов зверей направлять их выстрелы."}},faq={{q="Какое оружие используют охотники?",a="Охотники специализируются на оружии дальнего боя, включая луки, арбалеты и ружья. В ближнем бою они также умело владеют оружием ближнего боя, таким как древковое оружие, посохи, топоры и кинжалы, часто сражаясь с двумя клинками или используя ловушки, чтобы создать дистанцию и вновь стрелять издалека.",al={"hunter weapons","what do hunters equip","hunter bows rifles","оружие охотников","что носят охотники","луки и ружья охотника"}},{q="Как охотники приручают зверей?",a="Охотники полагаются на врожденное сопереживание и глубокое понимание диких существ. Наблюдая за их поведением, приближаясь без злого умысла и показывая силу и уважение, они усмиряют опасных хищников и создают пожизненную связь, обучая их сражаться рядом с собой.",al={"how to tame pets","beast taming","tame animal","как приручить питомца","приручение зверей","приручить животное"}},{q="Какие доспехи носят охотники?",a="Охотники начинают путь в легких гибких кожаных доспехах, чтобы сохранять ловкость на пересеченной местности. По мере роста опыта и встречи с более опасными угрозами они учатся носить прочные кольчужные доспехи, дающие лучшую защиту без серьезного ущерба для подвижности.",al={"hunter armor type","can hunters wear mail","hunter gear","тип доспехов охотника","могут ли охотники носить кольчугу","экипировка охотника"}},{q="Что такое аспекты охотника?",a="Аспекты — это первобытные приемы, в которых охотник настраивает свои чувства и рефлексы на природные силы диких существ. Призывая эти аспекты, охотник может бегать с быстротой гепарда, фокусировать прицел, как ястреб, или обретать защитную стойкость обезьяны.",al={"hunter aspects","aspect of the cheetah","hunter animal aspects","аспекты охотника","аспект гепарда","звериные аспекты охотника"}},{q="Что происходит, если враг подбирается к охотнику слишком близко?",a="Охотники сильно уязвимы на близкой дистанции, где стрельба из оружия дальнего боя затруднена. Чтобы выжить, они используют ледяные и обжигающие ловушки, контузящие средства и удары в ближнем бою, чтобы замедлить, ранить или дезориентировать нападающих, пока они или их питомцы отходят и восстанавливают дистанцию.",al={"hunter deadzone","close combat hunter","hunter melee","мертвая зона охотника","ближний бой охотника","охотник в ближнем бою"}},{q="Какие расы следуют путем охотника?",a="Охота распространена почти во всех культурах, хотя принимает разные формы. В Альянсе ночные эльфы и дворфы берутся за лук и ружье. В Орде орки, таурены и тролли чтят выслеживание и власть над зверями как важнейшие родовые традиции выживания.",al={"who can be a hunter","hunter races","playable hunter races","кто может быть охотником","расы охотников","игровые расы охотника"}}},fp="6,447,21.552.0,28.548.0,26.535.0,28.286.0,27.282.0,27.289.0,24.283.0,52.290.0,44.266.0"}
P.entries["topic:juggernaught"] = {n="Джаггернаут",s="Джаггернаут — огромный тяжелобронированный боевой корабль, ощетинившийся тяжелыми корабельными пушками. Изначально огры создали эти плавучие крепости как стальное ядро флота Старой Орды во время Второй войны: они предназначались для сокрушения прибрежных оплотов и торговых путей. Массивная железная обшивка и осадные бортовые залпы делают их легендарным орудием морской войны.",h="Джаггернаут — огромный тяжелобронированный боевой корабль, ощетинившийся тяжелыми корабельными пушками.",kw={"battleship","deadmines","defias","ironclad cove","juggernaught","juggernaut","ogre juggernaught","ship","stormwind","vancleef","линкор","мертвые копи","братство справедливости","потайная бухта","джаггернаут","огрский джаггернаут","корабль","штормград","ван клиф"},ang={["class:Rogue"]="Джаггернаут в Мертвых копях воплощает предельную дерзость Эдвина ван Клифа — строить главный линкор прямо под носом у ШРУ и стражи Штормграда.",["faction:Horde"]="Джаггернауты — яркая глава морского наследия Орды со времен Второй войны, доказавшая, что грубая инженерия способна оспорить господство Альянса на морях."},sec={{t="Ужас Второй войны",b="Орки традиционно не были мореходной культурой, поэтому, когда Орде во время Второй войны понадобился флот, способный пересечь Великое море и оспорить морское превосходство Альянса, она во многом положилась на изобретательность огров. Созданное ими судно — огрский джаггернаут — стало основой флота Орды. Хотя эти громадины были намного медленнее и неповоротливее быстрых тролльских эсминцев, они несли мощную обшивку и разрушительные бортовые батареи, способные разбивать корпуса кораблей Альянса и превращать прибрежные укрепления в груду обломков."},{t="Потайная бухта",b="Потайная бухта скрыта под холмами Западного Края, в глубине подземных пещер Мертвых копей. Там, вдали от посторонних глаз и королевских инспекторов, мастера Эдвина ван Клифа втайне трудились над постройкой полностью вооруженного джаггернаута. Собрав тяжелый боевой корабль в подземной пещере, напрямую соединенной с открытым морем, Братство Справедливости планировало обойти сухопутную оборону Штормграда и нанести внезапный морской удар прямо в сердце королевства."}},faq={{q="Что такое джаггернаут?",a="Джаггернаут — массивный тяжелобронированный боевой корабль, вооруженный тяжелыми осадными пушками. Первоначально его создала Орда при помощи огров во время Второй войны: это плавучая крепость, предназначенная для разгрома вражеских флотов и прибрежной обороны.",al={"juggernaut warcraft","orc battleship","ogre juggernaut","джаггернаут варкрафт","орочий линкор","огрский джаггернаут"}},{q="Почему в Мертвых копях стоит огромный корабль?",a="Edwin VanCleef and the Defias Brotherhood used the secluded cavern of Ironclad Cove inside the Deadmines as a hidden shipyard. Constructing the juggernaught underground kept it safe from Alliance patrols while they worked on the vessel.",al={"ship in deadmines","why boat in mines","deadmines ship","корабль в мертвых копях","почему лодка в копях","корабль мертвых копей"}},{q="Что Эдвин ван Клиф намеревался сделать с кораблем?",a="The ship is part of VanCleef's activities beneath Westfall. Investigating the Defias Brotherhood reveals what he intended for it.",al={"vancleef boat plan","why did defias build a ship","defias juggernaught purpose","план ван Клифа с кораблем","зачем братство справедливости построило корабль","цель джаггернаута братства справедливости"}},{q="Кто первоначально изобрел джаггернаут?",a="The Old Horde built juggernaughts with the help of ogres during the Second War. The orcs had little seafaring experience, and these massive warships became the heavy armament of their fleet.",al={"who made juggernauts","ogre ships lore","horde navy origin","кто создал джаггернауты","огрские корабли предания","происхождение флота орды"}},{q="Как корабль выходит из пещеры Мертвых копей?",a="Потайная бухта соединяется с открытыми водами Великого моря через скрытый прибрежный канал вдоль скалистых берегов Западного Края, позволяя готовому военному кораблю выйти прямо в океан.",al={"how does deadmines ship leave","ironclad cove exit","deadmines water exit","как корабль покидает мертвые копи","выход потайной бухты","водный выход мертвых копей"}},{q="Использует ли Орда джаггернауты до сих пор?",a="Orcish battleships were still known as juggernaughts during the Third War. Their role was to provide the heavy firepower of the Horde fleet; the current deployment of such vessels is uncertain.",al={"modern horde juggernauts","horde battleships","современные джаггернауты орды","линкоры орды"}}},fp="12,390,24.532.0,13.479.1,23.268.0,46.236.1,51.129.1,41.190.0,50.205.1,39.193.0"}
P.entries["topic:knights-of-the-silver-hand"] = {n="Рыцари Серебряной Длани",s="Рыцари Серебряной Длани — легендарный орден святых паладинов, основанный после Первой войны, чтобы сочетать воинское мастерство с исцеляющей и карающей силой Света. Хотя их северное отделение было разбито при падении Лордерона, уцелевшие рыцари продолжают хранить священные обеты в Штормграде и Стальгорне, а разрозненные остатки сражаются с нежитью в северных Чумных землях.",h="Рыцари Серебряной Длани — легендарный орден святых паладинов, основанный после Первой войны, чтобы сочетать...",kw={"alonsus faol","arthas","holy light","libram","paladin","silver hand","stratholme","tirion fordring","turalyon","uther","алонсус фаол","артас","свет","либрам","паладин","серебряная длань","стратхольм","тирион фордринг","туралион","утер"},ang={["class:Paladin"]="Каждый человек и дворф-паладин на службе Альянса возводит свои священные обеты, либрамы и воинскую традицию прямо к законам, установленным архиепископом Фаолом и Утером Светоносным.",["class:Priest"]="Серебряная Длань родилась из уязвимости священников в Первой войне, соединив божественное служение с тяжелой войной.",["faction:Alliance"]="Рыцари Серебряной Длани были идейной опорой Альянса Лордерона и вдохновляли солдат всех человеческих королевств стоять твердо против тьмы.",["race:Human"]="Люди видят в Серебряной Длани вершину добродетели, чести и мужества, скорбят о падении ее великих северных мастеров и чтят их память в Штормграде."},sec={{t="Создание паладинов",b="После разрушения Штормграда в Первой войне архиепископ Алонсус Фаол увидел серьезный изъян в обороне Альянса: клирики Североземья были преданными и умелыми целителями, но им недоставало боевой подготовки, и они легко гибли на передовой. Чтобы святые воины могли выдержать жестокие бои Второй войны, Фаол и его лучший ученик Утер Светоносный основали в Стратхольме орден Рыцарей Серебряной Длани. Вдохновившись легендой о серебряной руке Хранителя Тира как символе самоотверженной жертвы, Фаол набирал как закаленных в боях рыцарей, готовых научиться преданности Свету, так и набожных клириков, готовых носить латы и боевые молоты."},{t="Слава Второй войны",b="Первые пять паладинов — Утер Светоносный, Туралион, Сайдан Дератроан, Тирион Фордринг и Гавинрад Ужасный — сыграли решающую роль для Альянса Лордерона. Впервые вступив в бой в Битве за Хилсбрад, паладины поднимали дух усталых солдат и противостояли зловещему некромантству рыцарей смерти Орды. На протяжении войны Серебряная Длань подавляла крестьянские мятежи, отвоевала Каэр Дарроу и помогла защитить Столицу от осады орков. В последовавшие мирные годы паладины охраняли границы Лордерона, разрешали гражданские споры и служили блестящим образцом чести, смирения и справедливости."},{t="Падение и разрозненные остатки",b="Трагедия поразила орден изнутри во время Третьей войны. Принц Артас Менетил, прославленный рыцарь Серебряной Длани, жестоко поссорился со своим наставником Утером под Стратхольмом и незаконно отстранил паладинов от службы, когда Утер отказался истреблять зараженных жителей. Когда Артас позже поддался порче и повел Плеть на Лордерон, Утер и Гавинрад были убиты, и руководство ордена рухнуло. Уцелевшие рыцари на севере раскололись из-за разных доктрин, породив ревностный Алый орден и бдительный Серебряный Рассвет, тогда как уцелевшие отделения в Штормграде и Стальгорне продолжают обучать новых паладинов под классическим знаменем Серебряной Длани."}},faq={{q="Кто основал Рыцарей Серебряной Длани?",a="Орден создал архиепископ Алонсус Фаол в Стратхольме после Первой войны, а первым рыцарем стал Утер Светоносный.",al={"who made the silver hand","founder of paladins","who created paladins","кто создал серебряную длань","основатель паладинов","кто создал паладинов"}},{q="Кто были первые пять паладинов?",a="Первыми в орден были посвящены Утер Светоносный, Туралион, Сайдан Дератроан, Тирион Фордринг и Гавинрад Ужасный; каждый получил от архиепископа Фаола священный либрам.",al={"first paladins","original silver hand members","first five","первые паладины","первые члены серебряной длани","первая пятерка"}},{q="Почему орден называется Серебряной Дланью?",a="Название и эмблема восходят к древней легенде о серебряной руке Хранителя Тира, почитаемой как глубокий символ самоотверженной жертвы перед лицом зла.",al={"silver hand meaning","why silver hand name","silver hand origin","значение серебряной длани","почему серебряная длань","происхождение серебряной длани"}},{q="Существует ли Серебряная Длань до сих пор?",a="Да. Хотя ее северное верховное командование было уничтожено при разорении Лордерона Плетью, процветающие отделения продолжают служить Альянсу в Соборе Света Штормграда и в дворфийских залах Стальгорна.",al={"is silver hand alive","silver hand today","are paladins still around","жива ли серебряная длань","серебряная длань сегодня","остались ли паладины"}},{q="Как Алый орден и Серебряный Рассвет связаны с Серебряной Дланью?",a="После гибели Утера и верховного лорда Александроса Могрейна уцелевшие паладины Лордерона раскололись из-за идеологических разногласий. Непримиримые фанатики создали Алый орден, чтобы истребить всех чужаков, а более умеренные ветераны основали Серебряный Рассвет.",al={"scarlet crusade silver hand","argent dawn silver hand","how did the silver hand split","алый орден серебряная длань","серебряный рассвет серебряная длань","как раскололась серебряная длань"}},{q="Могут ли не-люди вступить в Рыцари Серебряной Длани?",a="Да. Хотя изначально орден состоял из людей — рыцарей и клириков Лордерона, — дворфийских жрецов и воинов Стальгорна принимали в него во время Второй войны и после нее, и они носили знаки и обряды Серебряной Длани.",al={"dwarf paladins silver hand","who can be a silver hand paladin","can dwarves be silver hand","дворфы паладины серебряная длань","кто может быть паладином серебряной длани","могут ли дворфы быть в серебряной длани"}}},fp="26,404,24.704.0,23.660.0,31.708.0,43.148.0,33.189.0,40.156.0,33.220.0,71.261.0,51.224.0"}
P.entries["topic:kobold"] = {n="Кобольд",s="Кобольды — мелкие крысоподобные подземные гуманоиды, снующие по шахтам и пещерам всего Азерота. Они известны одержимой преданностью сальным свечам, привязанным к их головам: поодиночке кобольды трусливы, но в стае опасны и яростно защищают свои раскопки от всех, кто угрожает их свету.",h="Кобольды — мелкие крысоподобные подземные гуманоиды, снующие по шахтам и пещерам всего Азерота.",kw={"candle","echo ridge","fargodeep","jasperlode","kobold","silver stream","trogg","tunnel rat","windshear","свеча","эхо-хребет","подземные глубины","яшмовая шахта","кобольд","серебряный ручеек","трогг","туннельная крыса","ветрорезы"},ang={["faction:Horde"]="Во время основания Оргриммара кобольдские норы под сухой землей вызвали хаос на ранних стройках, а племена вроде Гравийных Рыл по-прежнему досаждают пограничным аванпостам в Калимдоре.",["profession:Mining"]="Любой шахтер, работающий в землях людей или дворфов, неизбежно столкнется с нашествием кобольдов: они тянутся к богатым жилам меди, олова и серебра.",["race:Dwarf"]="Лига шахтеров регулярно нанимает искателей приключений, чтобы выгнать кобольдов племени Туннельных Крыс из горных выработок вроде Рудника у Серебряного ручейка в Лок Модане.",["race:Human"]="Для Королевства Штормград кобольды — постоянная экономическая головная боль: они захватили важные местные предприятия в Подземных Глубинах, на Яшмовой шахте и в Эхо-Хребте."},sec={{t="Шахтеры во тьме",b="Кобольды ростом едва в четыре фута — грязные подземные падальщики, всю жизнь роющие землю. Хотя они способны видеть при слабом свете, в самых глубоких штольнях царит кромешная тьма, поэтому каждый кобольд прикрепляет к голове грубую свечу. Загнанные в угол в одиночку, они трусливы, но размножаются огромными числами и работают неутомимо. В возбуждении их крысиные хвосты яростно хлещут, и они сокрушают незваных гостей беспорядочной толпой, забивая врагов тяжелыми железными кирками."},{t="Не трогай свечка!",b="Для кобольда свеча — не просто источник света, а защита самого существования. Они испытывают глубокий, первобытный ужас перед кромешно-темными туннелями и верят, что неосвещенная тьма будет пожирать их. Вождей нередко выбирают по длине свечи, которую те носят, а мастера собирают ушную серу и вытопленный жир, чтобы фитили не гасли. В кобольдском фольклоре солнце считается величайшим мифом: это «Бесфитильная свеча», огромное вечное пламя, подвешенное к необъятному синему своду пещеры."},{t="Подземные вредители королевств",b="В Восточных королевствах кобольды часто захватывают промышленные шахты. В Элвиннском лесу племя, изгнанное из Красногорья, заняло рудники Эхо-Хребта, Подземных Глубин и Яшмовую шахту; отчасти его вытеснили гноллы Речной Лапы и Братство Справедливости. В Лок Модане племя Туннельных Крыс захватило Рудник у Серебряного ручейка, принадлежавший дворфийской Лиге шахтеров. Даже в Калимдоре кобольды досаждают промышленным разработкам: они трудятся на Торговую Компанию в Когтистых горах или откапывают странные минералы в Тысяче Игл."}},faq={{q="Почему кобольды так дорожат своими свечами?",a="Кобольды панически боятся полной темноты. В их фольклоре тьма — живой хищник, который гасит жизнь и глотает шахтеров целиком. Пламя свечи — их единственная защита от сумрачных глубин, поэтому они одержимо оберегают свои фитили.",al={"why candles","kobold candles","you no take candle meaning","почему свечи","свечи кобольдов","значение не трогай свечка"}},{q="Откуда взялись кобольды?",a="По словам дворфа-исследователя Бранна Бронзоборода, кобольды изначально произошли от троггов. За поколения приспособления к жизни под землей они стали меньше, похожими на грызунов и научились пролезать в узкие лазы.",al={"kobold origins","where do kobolds come from","kobold evolution","происхождение кобольдов","откуда взялись кобольды","эволюция кобольдов"}},{q="Союзны ли кобольды Братству Справедливости?",a="Не по своей воле и не как равные партнеры. Кобольдов, заполонивших шахты Элвиннского леса и Западного Края, в основном притесняли и порабощали гноллы Речной Лапы, нанятые Братством Справедливости, чтобы нарушить добычу в регионе и завладеть минеральными богатствами.",al={"kobold defias","are kobolds working for defias","fargodeep defias","кобольды братство справедливости","кобольды работают на братство","рудник подземных глубин братство"}},{q="Как кобольды выбирают вождей?",a="За исключением далеких обособленных племен, кобольды обычно определяют главенство по размеру свечи. Землекоп с самой высокой и долго горящей свечой на голове признается племенем вождем.",al={"kobold leader","kobold boss","how do kobolds pick chiefs","вождь кобольдов","босс кобольдов","как кобольды выбирают вождей"}},{q="Встречаются ли кобольды в Калимдоре, а не только в Восточных королевствах?",a="Да. Кобольды населяли подземные пещеры под Оргриммаром во время основания города, работают на Руднике Ветрорезов Торговой Компании в Когтистых горах и роются по всей Тысяче Игл.",al={"kobolds in kalimdor","stonetalon kobolds","orgrimmar kobolds","кобольды в калимдоре","кобольды когтистых гор","кобольды оргриммара"}},{q="Что едят кобольды?",a="Кобольды живут тем, что удастся добыть из подземной живности. Они охотятся на крыс и разводят их, собирают пещерных личинок и светящиеся пещерные грибы, иногда прессуя грибы в грубые лепешки, которые едят с сиропом.",al={"kobold diet","what do kobolds eat","питание кобольдов","что едят кобольды"}}},fp="6,328,18.510.0,19.505.0,34.501.0,48.267.0,27.224.0,47.243.0,36.210.0,62.205.0,20.217.0"}
P.entries["topic:kolkar-clan"] = {n="племя Колкар",s="Колкары — агрессивное племя кентавров из центральной части Калимдора, ведущее род от легендарного первого хана, Колка. Их твердыни расположены в Пустошах и по всем Степям; они часто нападают на поселения Орды и сражаются со всеми, кто встанет на их пути.",h="Колкары — агрессивное племя кентавров из центральной части Калимдора, ведущее род от легендарного первого...",kw={"barrens","centaur","desolace","dezhepah","durotar","khan","kolk","kolkar","kolkar crag","lehprah","maraudon","oasis","степи","кентавр","пустоши","дез'хепа","дуротар","хан","колк","колкар","утес колкара","ле'пра","мародон","оазис"},ang={["class:Hunter"]="Отряды колкаров для набегов во многом полагаются на обученных полуприрученных гиен, которые выслеживают чужаков и охраняют границы вокруг водопоев.",["faction:Horde"]="Власть колкаров над тремя оазисами Степей перерезает важнейшие торговые пути и поставки воды между Дуротаром, Мулгором и Перекрестком.",["race:Orc"]="Ваш первый союз с тауренами был скреплен кровью в борьбе с мародерами-колкарами, а их разведчики на Утесе Колкара теперь угрожают Долине Испытаний, где взрослеют молодые орки.",["race:Tauren"]="Колкары охотились на ваш народ в Степях почти до полного истребления, пока не вмешались орки, и потому каждая встреча с ними — вопрос выживания предков."},sec={{t="Сыновья Колка",b="Колкары носят имя хана Колка, легендарного первого кентаврского хана, рожденного от союза Заетара и Терадрас. Движимые глубокой ненавистью к другим расам и к собратьям-кентаврам из других племен, колкары выделяются красными отметинами и полным отказом заключать союзы. Исторически они обитали в своей древней деревне на востоке Пустошей, а беспокойный дух хана Колка по-прежнему бродит в подземных глубинах их родовых земель."},{t="Бич Степей",b="Поколениями кочевые таурены терпели жестокие набеги колкаров, пересекая засушливые Степи. Когда во время Третьей войны орки прибыли в Калимдор, Тралл заключил союз с Кэрном Кровавым Копытом, чтобы отбросить мародерствующих кентавров и сопроводить тауренов в безопасный Мулгор. Поражение не сломило племя, а лишь разожгло затяжную кровную вражду. Колкары укрепились у всех трех важнейших источников воды в Степях: у Забытых прудов, Цветущего оазиса и Застывшего оазиса."},{t="Вторжение в Дуротар",b="Воодушевленные укрепленными позициями в саванне, колкары продвинулись на восток за реку Строптивую, в сам Дуротар. Из Утеса Колкара на юге их отряды замышляют нападения на Деревню Сен'джин, Долину Испытаний и дороги к Оргриммару. Пока высшее командование Орды занято более крупными угрозами в регионе, молодых рекрутов под руководством ветеранов вроде Лара Ночного Клыка посылают сдерживать наступление кентавров, прежде чем их отряды ударят по молодой столице орков."}},faq={{q="Кто такие кентавры племени Колкар?",a="Колкары — одно из пяти крупных кентаврских племен Калимдора. Они названы в честь своего основателя, хана Колка; это свирепое, враждебное чужакам племя, узнаваемое по красным доспехам. У них есть поселения в Пустошах, они контролируют главные водные оазисы Степей и устроили лагеря для набегов на юге Дуротара.",al={"kolkar clan","who are kolkar","kolkar lore","centaur in barrens","племя колкар","кто такие колкары","предания колкаров","кентавры в степях"}},{q="Почему колкары так ненавидят Орду?",a="Колкары поколениями охотились на тауренов и донимали их в Степях. Когда пришла Орда Тралла, орки присоединились к Кэрну Кровавому Копыту, чтобы отбросить кентавров и позволить тауренам поселиться в Мулгоре. Этот союз унизил ханов колкаров и превратил многовековую хищническую охоту в яростную войну против орков и тауренов.",al={"why do kolkar attack orcs","kolkar tauren feud","centaur vs horde","почему колкары нападают на орков","вражда колкаров и тауренов","кентавры против орды"}},{q="Почему колкары занимают оазисы Степей?",a="В засушливых Степях контроль над водой — это контроль над выживанием. Колкары заняли Забытые пруды, Цветущий оазис и Застывший оазис, поставив там командные шатры, племенные тотемы и стаи гиен, и закрыли эти драгоценные водопои для путников, торговцев и Орды.",al={"kolkar at oases","forgotten pools centaur","lushwater oasis centaur","колкары у оазисов","забытые пруды кентавры","цветущий оазис кентавры"}},{q="Кто возглавляет племя Колкар?",a="Первым правителем племени был хан Колк, чей дух по-прежнему пребывает в Мародоне. В последнее время во главе племени в Степях встал хан Дез'хепа и его помощники. В Пустошах традиционной твердыней племени управляет хан Ле'Пра, а местные отряды подчиняются региональным ханам, таким как павший хан Грагтор.",al={"kolkar leader","kolkar khan","who is the kolkar boss","предводитель колкаров","хан колкаров","кто главный у колкаров"}},{q="Что такое Утес Колкара?",a="Утес Колкара — аванпост в скалистом каньоне на юге Дуротара. Отряды кентавров устроили его как передовую базу, чтобы донимать новичков Орды в Долине Испытаний, угрожать Деревне Сен'джин и проверять оборону Оргриммара.",al={"where is kolkar crag","durotar centaur camp","kolkar in durotar","где утес колкара","лагерь кентавров в дуротаре","колкары в дуротаре"}},{q="Сотрудничают ли колкары с другими кентаврскими племенами?",a="Нет. Колкаров не связывают ни родство, ни договоры с остальными четырьмя кентаврскими племенами Пустошей. Общество кентавров жестоко раздроблено, и колкары воюют с другими племенами так же охотно, как с Ордой и Альянсом.",al={"centaur clans alliance","kolkar allies","do centaur cooperate","союз кентавров","союзники колкаров","сотрудничают ли кентавры"}}},fp="11,269,12.463.0,26.505.0,23.509.0,27.299.0,41.331.0,47.278.0,26.311.0,20.229.0,44.236.0"}
P.entries["topic:leper-gnome"] = {n="лепрогном",s="Лепрогномы — трагические мутировавшие выжившие после катастрофического облучения Гномрегана во время Третьей войны. Сведенные с ума токсичными осадками и ядовитыми испарениями, большинство из них присягнули узурпатору Сикко Термоштепселю и яростно защищают свой разрушенный город от всех чужаков.",h="Лепрогномы — трагические мутировавшие выжившие после катастрофического облучения Гномрегана во время Третьей...",kw={"dun morogh","gnomeregan","leper gnome","mekkatorque","radiation","recombobulation","thermaplugg","toxic","дун морог","гномреган","лепрогном","меггакрут","радиация","перенаправление","термоштепсель","токсичный"},ang={["profession:Engineering"]="Даже в состоянии полного безумия лепрогномы сохраняют удивительную способность к сборочным линиям, автоматическим оборонительным турелям и высоковольтным механизмам.",["race:Gnome"]="Каждый лепрогном — трагическое напоминание о падении Гномрегана и о тяжелой цене доверия Меггакрута к Термоштепселю. Изгнанные гномы в Городе механиков смотрят на них со смесью глубокой скорби и решимости найти лекарство.",["race:Undead"]="Отрекшиеся аптекари находят общий язык с этими облученными изгоями, глядя на их больные тела без отвращения, обычного для живых рас поверхности, и используя их механические навыки в лабораториях Подгорода."},sec={{t="Падение великого города",b="Когда трогги вторглись в Гномреган во время Третьей войны, меканик Сикко Термоштепсель посоветовал главному механику Гелбину Меггакруту затопить город радиоактивными токсинами. Термоштепсель утверждал, что яд истребит троггов, но пощадит гномов. Вместо этого катастрофа уничтожила восемьдесят процентов жителей города. Те, кто выжил на запечатанных нижних уровнях, были искажены разумом и телом токсичными осадками и превратились в бледных, покрытых нарывами несчастных, прозванных лепрогномами."},{t="Оплот Термоштепселя",b="Сам Термоштепсель поддался ядовитым осадкам, потеряв и цвет кожи, и рассудок. Назвав себя техноповелителем и королем Гномрегана, он собрал обезумевших выживших во Дворе Механиков. В своем расстроенном состоянии многие лепрогномы принимают всех жителей поверхности за троггов-захватчиков и с неистовой жестокостью нападают на возвращающиеся спасательные отряды. Они управляют найденными механизмами и собирают нестабильные боеприпасы, фанатично охраняя извращенное королевство Термоштепселя."},{t="Рассеянные по Азероту",b="Хотя большинство остается в ловушке зараженных коридоров Гномрегана, несколько лепрогномов выбрались в большой мир. Из отчаяния или темных амбиций они появлялись среди дворфов Черного Железа в Глубинах Черной горы, управляли машинами для Торговой Компании в Когтистых горах или поступали на службу лаборантами в Королевское фармацевтическое общество Отрекшихся в недрах Подгорода."},{t="Поиски лекарства",b="Ученые-гномы, изгнанные в Стальгорн, отказываются бросать своих облученных сородичей. В Дун Мороге инженеры и механики, такие как Оззи Триггервольт и Раззл Шустрец, неустанно трудятся над операцией «Перенаправление», пытаясь найти алхимические или механические способы обратить мутацию. Можно ли по-настоящему исцелить разум, сломленный токсичными осадками, остается мучительным вопросом без ответа."}},faq={{q="Что превратило гномов в лепрогномов?",a="Во время вторжения троггов в Гномреган Сикко Термоштепсель убедил главного механика Меггакрута открыть радиоактивные выпускные клапаны, чтобы очистить пещеры. Токсичные осадки не убили троггов, а облучили запертых гномов, изменив их кожу и уничтожив рассудок.",al={"why are leper gnomes green","how did they become leper gnomes","gnome radiation cause","почему лепрогномы зеленые","как они стали лепрогномами","причина радиации гномов"}},{q="Лепрогномы — нежить?",a="Нет. Лепрогномы — живые гномы, перенесшие тяжелое радиационное отравление и физическую мутацию. Хотя некоторые служат вместе с Отрекшимися в Лордероне из-за родства с порчей и ядами, их недуг порожден облученной гномьей инженерией, а не некромантией.",al={"are leper gnomes zombies","are they undead","leper gnome scourge","лепрогномы зомби","они нежить","лепрогномы плеть"}},{q="Можно ли вылечить лепрогномов?",a="Союзные гномы-изобретатели, такие как Оззи Триггервольт и Раззл Шустрец, активно испытывают методы лечения, например устройства перенаправления и алхимические обмывания. Хотя некоторые опытные устройства дают слабую надежду, надежного средства, способного обратить и телесное разложение, и глубокую деградацию разума, пока не существует.",al={"can leper gnomes be saved","leper gnome cure","operation recombobulation","можно ли спасти лепрогномов","лекарство от лепрогномов","операция перенаправление"}},{q="Кто возглавляет лепрогномов?",a="Меканик Сикко Термоштепсель правит ими как деспотичный техноповелитель. Мутировав от той самой радиации, которую сам настоял выпустить, он правит из Двора Механиков в Гномрегане, манипулируя расстроенным разумом выживших, чтобы сохранять абсолютную власть над руинами.",al={"leper gnome leader","king of gnomeregan","thermaplugg boss","предводитель лепрогномов","король гномрегана","термоштепсель босс"}},{q="Почему лепрогномы нападают на всех, кто входит в Гномреган?",a="Долгое воздействие радиоактивных газов разрушило их рассудок. В паранойе и бреду большинство лепрогномов считают любого чужака, даже нетронутого гнома с поверхности, троггом-захватчиком, желающим их уничтожить.",al={"why are leper gnomes hostile","why do they fight us","почему лепрогномы враждебны","почему они с нами сражаются"}},{q="Почему некоторые лепрогномы работают с Отрекшимися?",a="Несколько странствующих лепрогномов, например Ученик Криспин в Тирисфальских лесах, предложили свои услуги леди Сильване Ветрокрылой. Королевское фармацевтическое общество терпит их и нанимает помощниками в исследованиях, признавая общее восхищение чумой, оскверненной алхимией и выживанием вопреки тяжелой деградации тела.",al={"leper gnomes in undercity","forsaken leper gnomes","apprentice crispin","лепрогномы в подгороде","отрекшиеся лепрогномы","ученик криспин"}}},fp="11,273,26.504.0,21.519.0,24.436.0,21.389.1,41.286.0,24.276.0,26.308.0,27.265.0,56.230.0,52.319.0"}
P.entries["topic:lich-king"] = {n="Король-лич",s="Король-лич — повелитель и телепатический владыка нежити Плети, правящий с Ледяного Трона далеко на севере, в Ледяной Короне. Изначально созданный демоном Кил'джеденом из духа орка-шамана Нер'зула, он в конце концов заманил принца Артаса Менетила в пучину порока, и их роковое слияние произошло на ледяных вершинах Нордскола.",h="Король-лич — повелитель и телепатический владыка нежити Плети, правящий с Ледяного Трона далеко на севере, в...",kw={"arthas","cult of the damned","frostmourne","frozen throne","helm of domination","icecrown","kiljaeden","lich king","nerzhul","scourge","артас","культ проклятых","ледяная скорбь","ледяной трон","шлем господства","ледяная корона","кил'джеден","король-лич","нер'зул","плеть"},ang={["class:Paladin"]="Орден Серебряной Длани был разрушен оскверняющей силой Короля-лича, превратившей их величайшего защитника в рыцаря смерти, сразившего Утера Светоносного.",["class:Priest"]="Плеть — мрачное извращение святости Света, напоминающее служителям Света о страшной цене, заплаченной павшими приходами Лордерона.",["race:Human"]="Для людей Король-лич — высшая трагедия: принц Артас, наследник трона Лордерона и паладин Серебряной Длани, убил собственного отца и уничтожил свое королевство во имя этого существа.",["race:Undead"]="Отрекшиеся существуют лишь потому, что телепатическая хватка Короля-лича ослабла, а королева Сильвана ведет свой народ, пылая ненавистью к его бывшему господину в ледяных северных землях."},sec={{t="Рождение ледяного бога",b="Когда орк-шаман Нер'зул пытался бежать из умирающего мира Дренора, он попал прямо в лапы Кил'джедена Обманщика. Властелин демонов разорвал тело Нер'зула в клочья, но заключил его измученную душу в глыбу твердого как алмаз льда, извлеченную из Круговерти Пустоты. Заброшенная в Азерот, ледяная глыба упала на северные пустоши Нордскола и образовала Ледяной Трон. Кил'джеден хотел, чтобы Король-лич создал непобедимый авангард нежити, который уничтожит королевства смертных и не станет жертвой междоусобиц, погубивших Орочью Орду. Однако Нер'зул, обладавший огромной телепатической силой, сразу же начал замышлять собственное освобождение."},{t="Падение Лордерона",b="Повелители ужаса-наблюдатели неусыпно следили за пленником, поэтому Нер'зулу приходилось действовать тайно. Дотянувшись разумом, он подчинил изгнанного из Кирин-Тора архимага Кел'Тузада, который основал в Лордероне Культ Проклятых. Через котлы с зараженным зерном Плеть распространила Чуму нежизни по северным королевствам. Кризис вовлек принца Артаса Менетила: отчаянное желание спасти свой народ привело его к безжалостной жестокости, вершиной которой стала жуткая резня в Стратхольме. Ослепленный жаждой мести повелителю ужаса Мал'Ганису, Артас преследовал его до Нордскола, где проклятый рунный клинок Ледяная Скорбь ждал, чтобы похитить его душу и сделать его главным рыцарем смерти Плети."},{t="Предательство и возвышение",b="Хотя Королю-личу пришлось призвать Архимонда и передать Пылающему Легиону временное командование, он предвидел высокомерие демонов. Артас заставил охотника на демонов Иллидана Ярость Бури завладеть Черепом Гул'дана и убить Тихондрия, что в итоге способствовало гибели Архимонда у горы Хиджал. После этого отчаявшийся Кил'джеден поручил Иллидану уничтожить Ледяной Трон. Трещины в ледяном шпиле ослабили власть Нер'зула — это позволило Сильване Ветрокрылой и ее Отрекшимся освободиться, — и Король-лич призвал своего защитника домой. Артас вернулся в Нордскол, победил Иллидана у подножия Ледяной Короны, поднялся на шпиль и разбил лед, слившись с Нер'зулом в единое ужасное сознание."}},faq={{q="Кто сейчас Король-лич?",a="Король-лич — это слившееся воедино существо из принца Артаса Менетила и орка-шамана Нер'зула. Артас разбил ледяную темницу на вершине Ледяного Трона в Ледяной Короне и надел Шлем Господства, объединив свою смертную оболочку и темную душу с духом Нер'зула в единого абсолютного повелителя Плети.",al={"current lich king","who rules the scourge","is arthas the lich king","нынешний король-лич","кто правит плетью","артас король-лич"}},{q="Почему Пылающий Легион создал его?",a="Кил'джеден создал Короля-лича, чтобы ослабить защитников Азерота до полномасштабного вторжения демонов. Прошлое вторжение провалилось из-за междоусобиц в Орочьей Орде; армия мертвых под телепатическим контролем сулила полное повиновение и окончательное истощение армий смертных.",al={"why make lich king","kiljaeden purpose","legion scourge origin","зачем создали короля-лича","цель кил'джедена","происхождение плети"}},{q="Где находится Король-лич?",a="Он восседает на Ледяном Троне на ледяном леднике Ледяной Короны, в глубине далекого и холодного континента Нордскол, далеко за Великим морем к северу от Лордерона.",al={"where is frozen throne","lich king location","where does he live","где ледяной трон","где находится король-лич","где он живет"}},{q="Как Сильване удалось освободиться от его власти?",a="Когда Иллидан Ярость Бури атаковал Ледяной Трон мощной магией, волшебный лед треснул, и сила Короля-лича начала утекать. Его телепатическая хватка ослабла, и часть нежити вновь обрела свободную волю, сплотилась вокруг Сильваны Ветрокрылой и основала Отрекшихся.",al={"how did forsaken break free","why sylvanas free","scourge loss of control","как отрекшиеся освободились","почему сильвана свободна","потеря контроля плети"}},{q="Что такое Ледяная Скорбь?",a="Ледяная Скорбь — проклятый рунный клинок, крадущий души, отправленный с Ледяного Трона, чтобы заманить смертного защитника. Он заманил принца Артаса Менетила взять его в Нордсколе, поглотил душу принца и превратил его в главного рыцаря смерти Плети.",al={"what sword did arthas use","frostmourne lore","runeblade","каким мечом владел артас","ледяная скорбь предания","рунный клинок"}},{q="Кем был Нер'зул?",a="Нер'зул был старейшиной-шаманом орков Дренора. Когда он пытался бежать из умирающего родного мира через межпространственные разломы, его схватил демон Кил'джеден, содрал с него плоть и исказил его дух во всевидящее сознание, ставшее Королем-личом.",al={"nerzhul lore","who was nerzhul","original lich king","нер'зул предания","кем был нер'зул","первый король-лич"}}},fp="9,344,23.676.0,21.713.0,24.730.0,31.301.0,38.296.0,31.167.0,45.283.0,20.268.0,17.265.0"}
P.entries["topic:llane-wrynn-i"] = {n="Ллейн Ринн I",s="Король Ллейн Ринн I правил Штормградом во время катастрофической Первой войны; его правление закончилось падением королевства и его собственным трагическим убийством. Любимый и гордый монарх, он упорно отказывался верить, что его друг Медив предал человечество, и это в конечном счете погубило оборону столицы.",h="Король Ллейн Ринн I правил Штормградом во время катастрофической Первой войны; его правление закончилось...",kw={"barathen","first war","garona","gurubashi","kingslayers","llane","lothar","medivh","shadow council","stormwind","wrynn","баратен","первая война","гарона","гурубаши","убийцы королей","ллейн","лотар","медив","совет теней","штормград","ринн"},ang={["class:Rogue"]="Убийство короля Ллейна убийцей Гароной остается одним из самых известных и разрушительных ударов клинка в истории Азерота.",["class:Warrior"]="Король Ллейн сражался бок о бок со своим защитником Андуином Лотаром, лично руководя обороной Штормграда на передовой в крепости.",["faction:Alliance"]="Трагическое убийство короля Ллейна и падение Штормграда заставили уцелевших уйти на север и напрямую привели к созданию Великого Альянса Лордерона для борьбы с Ордой.",["race:Human"]="Для жителей Штормграда король Ллейн остается трагическим героем, чья жертва увековечена по всему восстановленному городу, в том числе в имени сына короля Вариана, Андуина Ллейна Ринна."},sec={{t="Принц безрассудной доблести",b="Принц Ллейн, сын короля Баратена Ринна, вырос вместе с Андуином Лотаром и Медивом. Когда тролли Гурубаши устраивали жестокие набеги на поселения Западного Края, Ллейн пошел против оборонительной политики отца и повел своих товарищей в джунгли Тернистой долины, чтобы убить военачальника Джок'нона. Этот смелый поступок привел к полномасштабному вторжению Гурубаши. Баратен погиб, возглавив отчаянную контратаку у городских ворот, а Медив вмешался и мощным колдовством уничтожил передовой отряд троллей. После этой дорогой ценой доставшейся победы Ллейн взошел на трон и стал королем Штормграда."},{t="Первая война",b="Когда из южных болот появились загадочные зеленокожие существа, король Ллейн отправил Лотара разведать Черную трясину. Мелкие стычки переросли в Первую войну: Орда захватила Светлую рощу, Западный Край и Красногорье. Гонцов, посланных в Лордерон и другие северные человеческие королевства, не стали слушать: их мольбы подорвали историческая изоляция Штормграда и аристократические интриги. Несмотря на эти трудности, Ллейн вместе с Лотаром организовал дерзкую контратаку, которая сорвала первую осаду Штормграда Ордой и нанесла захватчикам первое крупное поражение."},{t="Предательство в крепости",b="Твердость характера Ллейна в итоге ослепила его, и он не увидел настоящей опасности в своем ближнем кругу. Даже когда ученик Медива Кадгар и посланница Гарона рассказали, что Хранитель сам открыл Темный портал, Ллейн отказался признать предательство друга детства. Вскоре Оргрим Молот Рока объединил Орду и прорвал внешнюю оборону Штормграда. Пока Ллейн руководил обороной из Крепости Штормграда, Гарона, подчиненная магическому влиянию Совета Теней, убила короля в его собственном тронном зале, вырезав ему сердце и предрешив гибель города."}},faq={{q="Кто такой король Ллейн Ринн I?",a="Король Ллейн Ринн I правил Королевством Штормград во время Первой войны. Он был отцом короля Вариана Ринна и дедом юного принца Андуина Ллейна Ринна. Он погиб, защищая свой народ при первом падении Штормграда.",al={"who is llane","llane wrynn lore","king llane","кто такой ллейн","ллейн ринн предания","король ллейн"}},{q="Как погиб король Ллейн?",a="Ллейн был убит в Крепости Штормграда во время последней осады Первой войны. Его убила Гарона Полуорчиха, посланница-полуорк, которую он считал доверенным другом и наперсницей, но которая находилась под контролем разума со стороны Совета Теней.",al={"who killed king llane","llane death","how did llane die","кто убил короля ллейна","смерть ллейна","как умер ллейн"}},{q="В каких отношениях Ллейн был с Медивом и Лотаром?",a="Ллейн, Медив и Андуин Лотар были неразлучными друзьями детства и вместе странствовали по югу Азерота. Их связь на всю жизнь оказалась трагичной: Лотар стал величайшим защитником Ллейна, а полный отказ Ллейна поверить в предательство Медива привел монарха к гибели.",al={"llane medivh lothar","llane childhood friends","ллейн медив лотар","друзья детства ллейна"}},{q="Почему другие человеческие королевства не помогли Ллейну во время Первой войны?",a="Штормград давно проводил изоляционистскую внешнюю политику, которую северные государства считали высокомерной. Когда Ллейн прислал предупреждения о зеленокожих захватчиках, правители Лордерона сочли их преувеличенным рассказом о гражданском мятеже и оставили Штормград сражаться в одиночку.",al={"why didn't lordaeron help llane","alliance during first war","почему лордерон не помог ллейну","альянс во время первой войны"}},{q="Как Вариан спасся при падении Штормграда?",a="После убийства короля Ллейна и прорыва в Крепость Штормграда защитник Андуин Лотар собрал уцелевших горожан и юного сына Ллейна, принца Вариана Ринна. Лотар отвел их в гавань и бежал на север через Великое море в Лордерон.",al={"what happened to varian after llane died","varian escape stormwind","что стало с варианом после смерти ллейна","побег вариана из штормграда"}},{q="Что Медив подарил Ллейну при восшествии?",a="Когда Ллейн достиг совершеннолетия как принц Штормграда, Медив очнулся после долгой комы и преподнес ему зачарованные обсидиановые песочные часы. Песок в них сыпался бесконечно, а верхняя колба никогда не пустела, символизируя вечное процветание Штормграда.",al={"medivh gift to llane","llane hourglass","подарок медива ллейну","песочные часы ллейна"}}},fp="13,302,26.609.0,13.604.0,20.575.2,27.240.0,23.242.0,51.289.0,68.270.0,44.249.0,44.253.0"}
P.entries["topic:lordaeron"] = {n="Лордерон",s="Лордерон — огромный северный субконтинент Восточных королевств, некогда славное сердце человеческой цивилизации и Альянса. После разрушений Третьей войны его бывшие королевства лежат в руинах, и за них борются нежить Плети, Отрекшиеся Сильваны Ветрокрылой и отчаявшиеся остатки живых.",h="Лордерон — огромный северный субконтинент Восточных королевств, некогда славное сердце человеческой...",kw={"hillsbrad","lordaeron","lordain","menethil","plaguelands","scourge","silverpine","terenas","tirisfal","undercity","хилсбрад","лордерон","лордейн","менетил","чумные земли","плеть","серебряный бор","теренас","тирисфаль","подгород"},ang={["class:Paladin"]="Орден Серебряной Длани родился в Лордероне, в часовне Алонсуса Фаола. Каждая дорога и каждые руины этих северных земель пропитаны историей первых паладинов.",["faction:Alliance"]="Альянс когда-то получил свое имя от этого континента. Сегодня возвращение опорных пунктов в Хилсбраде и борьба с Плетью в Чумных землях — мучительный труд по возвращению человеческого наследия.",["faction:Horde"]="Через своих союзников Отрекшихся Орда удерживает важный и спорный плацдарм на севере Восточных королевств, окружая форпосты Альянса и противостоя остаткам Плети.",["race:Human"]="Для людей Альянса Лордерон — священная трагедия. Он был колыбелью Света и главой первого Альянса; видеть его залы захваченными нежитью — постоянный источник скорби и ярости.",["race:Undead"]="Когда-то это была ваша родина при жизни. Вы идете по разрушенным дворам Столицы не как приезжие путники, а как законные наследники Лордерона, берущие свое по праву под началом леди Сильваны."},sec={{t="Колыбель северного человечества",b="Лордерон получил имя в честь Лордейна, почитаемого генерала древней Араторской империи, пожертвовавшего жизнью во время Тролльих войн. Простираясь от суровых земель Нагорья Арати на юге через живописные леса и водные пути к Кель'Таласу на севере, этот край взрастил процветающие королевства: Лордерон, Даларан, Гилнеас и Альтерак. Он издавна славился плодородными полями Тирисфаля и Хилсбрада, горными крепостями и священной колыбелью Света."},{t="Плеть и падение",b="Во время Третьей войны Лордерон стал эпицентром вторжения Короля-лича. Через зараженное зерно Культ Проклятых превратил бесчисленных северян в безмозглую нежить. Принц Артас Менетил поддался тьме, вернулся из Нордскола, убил своего отца, короля Теренаса Менетила II, и устроил полную резню в Столице. Процветающее сердце страны быстро сгнило, превратившись в оскверненный кошмар, известный как Чумные земли."},{t="Спорная пустошь",b="Сегодня Лордерон — жестокое поле битвы, где царят разделенные верности. Под руинами Столицы леди Сильвана Ветрокрылая и Отрекшиеся создали Подгород, суверенное государство свободной нежити, союзное Орде. На востоке безмозглая Плеть Короля-лича цепляется за оскверненные замки и крепости. Тем временем человеческие фанатики Алого ордена, уцелевшие поселения Альянса в Хилсбраде и дикие лесные тролли беспощадно сражаются за то, что осталось."}},faq={{q="Что такое Лордерон?",a="Лордерон — это и весь северный субконтинент Восточных королевств, и конкретно бывшее человеческое королевство, правившее его центральными землями. Земля тянется от Моста Тандола на границе Арати на север к Кель'Таласу и включает горы, леса и внутренние озера.",al={"is lordaeron a continent","what does lordaeron mean","lordaeron geography","лордерон континент","что значит лордерон","география лордерона"}},{q="Кто контролирует Лордерон сейчас?",a="Ни одна сила не контролирует весь субконтинент. Сильвана Ветрокрылая и Отрекшиеся удерживают Тирисфальские леса и Серебряный бор из подземного Подгорода. Плеть сохраняет огромную мощь в Чумных землях под началом Кел'Тузада, а Алый орден, союзники Королевства Штормград в Хилсбраде и различные племена троллей контролируют отдельные пограничные области.",al={"who rules lordaeron","who owns lordaeron now","current ruler of lordaeron","кто правит лордероном","кому принадлежит лордерон","нынешний правитель лордерона"}},{q="Что случилось с живыми людьми Лордерона?",a="Большая часть населения Лордерона погибла во время Третьей войны, сраженная чумой нежити или армией Плети Артаса. Многие из погибших были подняты безмозглыми слугами, а позже обрели разум и стали Отрекшимися. Выжившие бежали на юг, в Штормград, уплыли в Калимдор с Джайной Праудмур или присоединились к воинственным общинам, таким как Алый орден.",al={"where did the people of lordaeron go","did lordaeron humans die","what happened to lordaeron","куда делись жители лордерона","погибли ли люди лордерона","что случилось с лордероном"}},{q="Почему субконтинент назвали Лордерон?",a="Он назван в память о Лордейне, генерале древней Араторской империи. Во время древних Тролльих войн между людьми, высшими эльфами и Империей Амани Лордейн пожертвовал собой вместе со своими воинами, чтобы защитить товарищей, навсегда вписав свое имя в северные предания.",al={"origin of name lordaeron","who is lordaeron named after","lordain name","происхождение названия лордерон","в честь кого назван лордерон","лордейн имя"}},{q="Где находится Столица Лордерона?",a="Столица Лордерона стоит на северном берегу Озера Лордамер в Тирисфальских лесах. Хотя ее улицы и дворцовые дворы лежат в безмолвных руинах, обширные катакомбы под ними Сильвана Ветрокрылая превратила в Подгород, столицу Отрекшихся.",al={"where was lordaeron city","capital of lordaeron","ruins of lordaeron location","где был город лордерон","столица лордерона","расположение руин лордерона"}},{q="Лордерон принадлежит Альянсу или Орде?",a="За него идет ожесточенная борьба. Исторически Королевство Лордерон основало и возглавило первый Альянс Лордерона. Однако сегодня Подгород — официальная столица Орды, поэтому западный Лордерон является оплотом Орды, а силы Альянса отчаянно пытаются удержать немногие оставшиеся форпосты в Хилсбраде и Арати.",al={"is lordaeron alliance or horde","who claims lordaeron","лордерон альянс или орда","кто претендует на лордерон"}}},fp="9,314,27.480.0,24.463.0,21.506.0,26.306.0,33.356.0,57.377.0,41.280.0,39.286.0,47.330.0"}
P.entries["topic:mage"] = {n="Маг",s="Маги — ученые заклинатели, которые изменяют ткань реальности с помощью изучения тайной магии: они обрушивают разрушительный огонь, повелевают льдом и чистой энергией тайной магии. Хотя маги физически хрупки и носят лишь тканевую одежду, их мастерство в телепортации, сотворении предметов и контроле над противниками на поле боя делает их грозными союзниками и страшными врагами. Это ремесло требует огромной умственной самоотдачи и баланса между колоссальным разрушительным потенциалом и опасной историей злоупотребления тайной магией.",h="Маги — ученые заклинатели, которые изменяют ткань реальности с помощью изучения тайной магии: они обрушивают...",kw={"arcane","conjuration","dalaran","fire","frost","kirin tor","mage","magus","mana","spellcaster","teleport","wizard","тайная магия","сотворение","даларан","огонь","лед","кирин-тор","маг","чародей","мана","заклинатель","телепорт","волшебник"},ang={["class:Mage"]="Ваше ремесло — это строгая интеллектуальная дисциплина: вы владеете огнем, льдом и силой тайной магии и оберегаете хрупкое равновесие реальности.",["class:Paladin"]="Пока вы сражаетесь бок о бок с магами, Рыцари Серебряной Длани давно относятся к их мирским методам тайной магии с глубокой осторожностью.",["class:Warlock"]="Многие чернокнижники начинали путь магами, прежде чем отказаться от академической сдержанности и строгих указов Даларана ради демонической силы.",["race:Human"]="Тайное наследие человечества восходит к сотне первых магов, обученных во время войн с троллями, а их потомки превратили Даларан в великий центр магической науки.",["race:NightElf"]="Общество кальдораев строго избегает тайной магии, слишком хорошо помня, как королева Азшара и ее высокорожденные маги принесли гибель древнему Калимдору."},sec={{t="Ученые тайной магии",b="Путь мага требует ума, сосредоточенности и многих лет упорных занятий. Маги не взывают к духам и не полагаются на божественную веру, а считают магию точной космической наукой. Черпая тайную энергию, чародей может создавать чистую разрушительную силу, вызывать обжигающие вспышки пламени или обращать окружающий воздух в твердый лед и ревущие метели. Тяжелые доспехи мешают тонким жестам и умственной сосредоточенности, необходимым для заклинаний, поэтому маги носят легкую тканевую одежду и защищаются с помощью оберегов, маназащиты и заклинаний уклонения."},{t="Наследие Даларана и Аратора",b="Магическое наследие людей началось почти три тысячи лет назад, во время войн с троллями, когда высокие эльфы-чародеи обучили сотню людей из Араторской империи, чтобы переломить ход войны против Амани. Когда число людей-магов возросло, напуганные обычные горожане вынудили многих магов основать магократию Даларан. Под управлением Кирин-Тора Даларан стал главным хранилищем магических знаний северных королевств и оформил традиции боевой магии, которые позже поддерживали Альянс Лордерона в Первой и Второй войнах."},{t="Подозрение и необходимость",b="Чародеи никогда не пользовались безоговорочным доверием. От древней катастрофы, вызванной высокорожденными, до гибельного падения Даларана в годы Третьей войны — переменчивая природа магии вызывает всеобщую настороженность. Церковь Священного Света исторически относилась к чародейству скептически, а консервативные рыцари нередко считали заклинателей тайной магии проклятыми душами или неизбежным злом на поле боя. Несмотря на это, гражданские и военные руководители признают, что умелый маг дает бесценное превосходство в бою, быстрое массовое перемещение и необходимую защиту от сверхъестественных угроз."}},faq={{q="Какими школами магии специализируются маги?",a="Маги сосредоточены на трех основных школах: тайной магии, огне и льде. Тайная магия изменяет время, пространство и реальность, позволяя превращать противников, телепортироваться и выпускать направленные потоки чистой силы. Заклинания огня наносят быстрый, сокрушительный урон от возгорания и испепеляют цели. Магия льда замедляет, сковывает и разбивает врагов, обеспечивая важный контроль над полем боя и не давая противникам подойти на дистанцию ближнего боя.",al={"mage specs","mage magic types","arcane fire frost","специализации мага","виды магии мага","тайная магия огонь лед"}},{q="Почему маги носят только тканевые доспехи?",a="Сложные заклинания требуют свободы движений, точных жестов рук и непрерывной сосредоточенности. Тяжелые материалы, такие как кожа, кольчуга или латы, мешают жестам заклинателя и потоку магической энергии. Чтобы компенсировать физическую уязвимость, маги используют магические барьеры, ледяные щиты и заклинания, удерживающие врагов на расстоянии.",al={"why cloth","mage armor type","can mages wear leather","почему ткань","тип доспехов мага","могут ли маги носить кожу"}},{q="Как люди впервые научились использовать тайную магию?",a="Во время древних войн с троллями, около 2800 лет назад, человеческая Араторская империя заключила союз с высшими эльфами Кель'Таласа против троллей Амани. В обмен на военную помощь эльфы-маги обучили сотню людей основам тайной магии. Эти первые сто пионеров показали себя в бою сокрушительно и положили начало человеческой магической традиции, из которой в итоге возник Даларан.",al={"first human mages","troll wars mages","human magic origin","первые маги-люди","маги войн с троллями","происхождение магии людей"}},{q="Каковы отношения между магами и Церковью Священного Света?",a="Отношения напряженные. Столетиями ортодоксальные члены Церкви Священного Света относились к изучению тайной магии и Кирин-Тору с подозрением, порой считая их еретическими. Паладины и набожные священники часто видят в чародействе непредсказуемую и морально сомнительную практику, которую, однако, терпят по необходимости из-за ее стратегической военной силы.",al={"church views on mages","paladins and mages","holy light arcane heresy","отношение церкви к магам","паладины и маги","священный свет тайная магия ересь"}},{q="Входят ли маги Штормграда в Кирин-Тор Даларана?",a="Исторически у Штормграда были собственные традиции, во главе которых стояли придворные чародеи, действовавшие в основном независимо от Даларана. Хотя Кирин-Тор Даларана был бесспорным центром магической науки на севере, южные чародеи создали собственные общины и роли королевских советников, однако связи и общие узы сохранялись в обоих королевствах.",al={"stormwind mages dalaran","conjurers of azeroth","stormwind wizards","маги штормграда даларан","чародеи азерота","волшебники штормграда"}},{q="Могут ли маги создавать еду и мгновенно перемещать людей?",a="Да. Помимо разрушительных заклинаний, у магов есть богатый набор вспомогательной магии. Они могут силой тайной магии создавать из воздуха свежую еду и воду, усиливать интеллект союзников и искривлять пространство, мгновенно открывая порталы между крупными городами мира.",al={"mage utility","mage portals","conjure water food","вспомогательная магия мага","порталы мага","создание воды и еды"}}},fp="4,472,22.574.0,33.567.0,23.632.0,45.398.0,35.380.0,48.389.0,72.354.0,50.349.0,53.257.0"}
P.entries["topic:medivh"] = {s="Медив был последним Хранителем Тирисфаля — древнего ордена, призванного защищать Азерот от демонической порчи. Еще до рождения он был связан духом Темного Титана Саргераса, открыл Темный портал и привел в мир орочью Орду, развязав десятилетия катастрофических войн.",h="Медив был последним Хранителем Тирисфаля — древнего ордена, призванного защищать Азерот от демонической порчи.",kw={"aegwynn","atiesh","dark portal","guardian","karazhan","khadgar","lothar","medivh","sargeras","tirisfal","эгвин","атиеш","темный портал","хранитель","каражан","кадгар","лотар","медив","саргерас","тирисфаль"},ang={["class:Mage"]="Медив воплощает и вершину, и высшую опасность владения тайной магией; каждый ученый Кирин-Тора изучает его катастрофическое падение как предостережение о неукрощенной силе.",["class:Warlock"]="Общение Медива с Гул'даном и его роль смертного проводника Саргераса остаются легендарным примером призыва скверны и манипуляций между мирами.",["faction:Alliance"]="Жители Штормграда вспоминают Медива с горькой печалью: он был любимым спутником королевской семьи, который в итоге впустил в их земли губительную Орду.",["faction:Horde"]="Для Орды Тралла Медив — человек-чародей, чья сделка с Гул'даном открыла Темный портал и впервые привела орков в этот мир."},sec={{t="Проклятое наследие",b="Медив родился у могущественной Хранительницы Эгвин и придворного чародея Ниласа Арана. За века до этого Эгвин сразилась в Нордсколе с павшим Титаном Саргерасом, не зная, что его темная сущность проникла в ее тело, ожидая наследника. Когда Медиву исполнилось четырнадцать лет, огромное магическое наследие матери проявилось в чудовищном взрыве силы, и мальчик на десять лет впал в кому под присмотром клириков Аббатства Североземья."},{t="Падение Каражана",b="Очнувшись от сна, Медив поселился в уединенной башне Каражана и стал придворным магом своего друга детства короля Ллейна Ринна из Штормграда. Но темный дух внутри него постепенно разрушал его рассудок. Стремясь к разрушению, Медив связался через звезды с орком-чернокнижником Гул'даном и Советом Теней. Вместе они направили колоссальную магию, чтобы разорвать Темный портал, обрушив Орду на Восточные королевства и положив начало Первой войне. В итоге Медива убили в его башне ближайший друг Андуин Лотар и ученик Кадгар."},{t="Искупление Пророка",b="Освобожденный от Саргераса смертью, Медив вернулся из-за грани смерти, чтобы искупить свои преступления. Во время Третьей войны он принял облик загадочного Пророка в плаще из вороньих перьев и шептал предупреждения о возвращении Пылающего Легиона королю Теренасу Менетилу и вождю Траллу. Хотя Лордерон проигнорировал его мольбы, он направил Орду Тралла и беженцев Джайны Праудмур через Великое море в Калимдор, объединив орков, людей и ночных эльфов для решающей битвы у Горы Хиджал, а затем скрылся в легендах."}},faq={{q="Кем был Медив?",a="Медив был последним человеческим Хранителем Тирисфаля, наделенным огромной тайной силой для защиты Азерота. Он был сыном Магны Эгвин и стоял за открытием Темного портала.",al={"who is medivh","medivh lore","the last guardian","кто такой медив","предания о медиве","последний хранитель"}},{q="Почему Медив открыл Темный портал?",a="Еще до рождения Медивом овладел дух Темного Титана Саргераса. Под этим злобным влиянием он заключил сделку с чернокнижником Гул'даном: предложил местонахождение Гробницы Саргераса в обмен на вторжение Орды в Азерот, чтобы принести гибель смертным королевствам.",al={"why did medivh betray stormwind","medivh dark portal","why bring orcs","почему медив предал штормград","медив темный портал","зачем привел орков"}},{q="Кто убил Медива?",a="Во время Первой войны Медива настигли в Каражане его близкий друг Андуин Лотар, ученик Кадгар и убийца-полуорк Гарона. Кадгар пронзил сердце Медива, а Лотар отсек ему голову, оборвав его жизнь и отправив дух Саргераса обратно в Пустоту.",al={"how did medivh die","who killed the guardian","medivh death","как умер медив","кто убил хранителя","смерть медива"}},{q="Какие отношения связывали Медива с королевским домом Штормграда?",a="Медив вырос вместе с принцем Ллейном Ринном и Андуином Лотаром при королевском дворе Штормграда. В юности трое сражались бок о бок против троллей Гурубаши, и король Ллейн полностью доверял Медиву, поэтому его предательство стало для королевства страшным ударом.",al={"medivh and llane","was medivh friends with lothar","медив и ллейн","дружил ли медив с лотаром"}},{q="Жив ли Медив до сих пор?",a="После того как Медив помог смертным расам одержать победу над Архимондом в битве у Горы Хиджал, он ушел, чтобы занять место среди легенд прошлого. Где он находится с тех пор, неизвестно.",al={"where is medivh now","is the prophet medivh","medivh status","где сейчас медив","пророк медив","судьба медива"}},{q="Что такое Каражан?",a="Каражан — это шпиль, возведенный на мощном пересечении силовых линий на Перевале Мертвого Ветра. Его основала Эгвин, а позже унаследовал Медив; после падения Хранителя башню исказили тайные и демонические энергии, и она остается руинами, населенными призраками.",al={"medivh tower","what happened to karazhan","башня медива","что случилось с каражаном"}}},fp="6,299,17.469.0,20.596.0,24.506.1,15.190.0,36.274.0,18.276.0,56.263.0,22.183.1,17.269.0"}
P.entries["topic:mor-ladim"] = {n="Мор'Ладим",s="Мор'Ладим — опасный мстительный скелет-воин, бродящий по Кладбищу Вороньего Холма в Сумеречном лесу. Некогда благородный рыцарь Морган Ладимор, он поддался глубокому горю и безумию, обнаружив гибель своей семьи, и восстал из мертвых, чтобы убивать всех, кто встретится на его пути.",h="Мор'Ладим — опасный мстительный скелет-воин, бродящий по Кладбищу Вороньего Холма в Сумеречном лесу.",kw={"althea ebonlocke","archeus","duskwood","grand hamlet","lys ladimore","mor'ladim","morgan ladimore","raven hill","алтея чернодрев","принцип","сумеречный лес","большая деревня","лис ладимор","мор'ладим","морган ладимор","вороний холм"},ang={["class:Paladin"]="Морган Ладимор был честным воином Света и сражался бок о бок с Утером Светоносным. Его падение показывает страшную опасность того, что скорбь и гнев могут затмить священные клятвы.",["faction:Alliance"]="Трагическая гибель Моргана Ладимора — мрачное напоминание о том, как глубоко Третья война потрясла южные королевства, такие как Штормград, оставив вернувшихся ветеранов перед разрушенными семьями."},sec={{t="Рыцарь Серебряной Длани",b="Прежде чем стать ужасом Вороньего Холма, Мор'Ладим жил как Морган Ладимор, преданный рыцарь и защитник беспомощных из Большой деревни — города, ныне известного как Темнолесье. В восемнадцать лет он женился на Лис, в мире вырастил троих детей, пока война не призвала его на север. Во время Третьей войны Морган вместе с Утером Светоносным отправился в Лордерон и стал свидетелем гибели Рыцарей Серебряной Длани, распространения чумы Кел'Тузада и трагической смерти самого Утера."},{t="Падение Моргана Ладимора",b="Вернувшись домой после войны, Морган обнаружил, что Сумеречный лес охвачен тьмой, а его усадьба разрушена. Он пришел на Кладбище Вороньего Холма и искал среди надгробий, пока не нашел могилы Лис и двоих их детей. Охваченный горем и яростью, Морган набросился на надгробия. Когда служители кладбища попытались его успокоить, рыцарь в слепом исступлении перебил их. Придя в себя и ужаснувшись своему злодеянию, Морган вонзил собственный клинок себе в сердце. Горожане в стыде похоронили его тело в безымянной могиле в дальнем углу кладбища."},{t="Плеть Вороньего Холма",b="Погребение не принесло Моргану покоя. Скованные тяжким чувством вины за невинную кровь и удушающим горем, его оскверненные останки поднялись из земли огромным скелетом, вернувшимся из мертвых. Путники и члены Ночного Дозора, называвшие его Мор'Ладимом, быстро научились страшиться этого имени. Вооруженное фамильным клинком Принцип, безмозглое видение обходит окутанные туманом могилы и убивает как зверей, так и неосторожных искателей приключений, подошедших слишком близко к его месту упокоения."}},faq={{q="Кем был Мор'Ладим при жизни?",a="Мор'Ладим изначально был Морганом Ладимором, благородным паладином и рыцарем из Большой деревни, сражавшимся бок о бок с Утером Светоносным во время Третьей войны в Лордероне.",al={"who is morladim","morladim backstory","morgan ladimore lore","who was morladim","кто такой морладим","предыстория морладима","морган ладимор предания","кем был морладим"}},{q="Почему Мор'Ладим враждебен?",a="Морган обезумел от горя, обнаружив могилы своей семьи. Убив невинных служителей кладбища и покончив с собой, он оказался пленен собственной виной и мукой, и его тело восстало как жаждущая убийств нежить.",al={"why does morladim attack","why is he angry","morladim madness","почему морладим нападает","почему он злится","безумие морладима"}},{q="Где бродит Мор'Ладим?",a="Он патрулирует широкие дорожки и мавзолеи Кладбища Вороньего Холма на западе Сумеречного леса и часто застает путников врасплох из-за своего обширного маршрута.",al={"morladim path","where to find morladim","morladim location","путь морладима","где найти морладима","местонахождение морладима"}},{q="Погибла ли вся семья Моргана Ладимора?",a="Нет. Жена Лис и двое детей погибли, но третий ребенок пережил упадок Сумеречного леса — эту подробность Морган совершенно упустил в слепом отчаянии на кладбище.",al={"did morgan ladimore family survive","morgan ladimore daughter","who survived in ladimore family","выжила ли семья моргана ладимора","дочь моргана ладимора","кто выжил в семье ладимор"}},{q="Какое оружие носит Мор'Ладим?",a="Мор'Ладим владеет клинком Принцип — прекрасным мечом, верно служившим ему при жизни рыцаря, а в нежизни ставшим орудием убийств.",al={"morladim sword","archeus sword","what sword does morladim use","меч морладима","меч принцип","каким мечом пользуется морладим"}},{q="Кто хочет уничтожить Мор'Ладима?",a="Командир Алтея Чернодрев и Ночной Дозор Темнолесья стремятся уничтожить его, чтобы защитить патрули и путников от его неустанных засад на западе Сумеречного леса.",al={"who wants morladim dead","night watch morladim","althea ebonlocke morladim","кто хочет смерти морладима","ночной дозор морладим","алтея чернодрев морладим"}}},fp="9,293,27.494.0,27.585.1,25.457.0,26.170.1,25.238.1,26.161.0,40.171.1,37.156.1,30.172.0"}
P.entries["topic:muradin-bronzebeard"] = {n="Мурадин Бронзобород",s="Мурадин Бронзобород был братом короля Магни Бронзоборода и Бранна Бронзоборода, а также прославленным воином, дипломатом и одним из основателей Лиги исследователей. Почитаемый и в Каз Модане, и в Лордероне, он, как считается, погиб в ледяных пустошах Нордскола, когда принц Артас Менетил завладел проклятым рунным клинком Ледяная Скорбь.",h="Мурадин Бронзобород был братом короля Магни Бронзоборода и Бранна Бронзоборода, а также прославленным воином...",kw={"arthas","bronzebeard","explorers league","frostmourne","ironforge","magni","muradin","northrend","артас","бронзобород","лига исследователей","ледяная скорбь","стальгорн","магни","мурадин","нордскол"},ang={["class:Warrior"]="Мурадин считался одним из лучших дворфийских дуэлянтов и мастеров оружия своей эпохи и сам обучал принца Артаса Менетила искусству владения клинком.",["faction:Alliance"]="Мурадин выковал узы товарищества между Стальгорном и северными человеческими королевствами, став одним из героев-основателей Альянса.",["race:Dwarf"]="Дворфы Стальгорна помнят Мурадина как образец своего народа — храброго, беззаветно преданного и движимого неутолимым любопытством к истории их создателей."},sec={{t="Брат и посол",b="Мурадин отличился во время Второй войны, став важным связующим звеном между горными чертогами Каз Модана и Альянсом Лордерона. Он помогал удерживать Стальгорн во время осады Орды и вместе с войсками Альянса дошел через Вершину Черной горы до Темного портала. В мирные годы Мурадин поселился в Столице как официальный посол Стальгорна. Весельчак, но грозный воин, он стал привычной фигурой во дворце, сблизился с королем Теренасом Менетилом, завоевал расположение королевских поваров и взялся обучать юного принца Артаса искусству фехтования и боя."},{t="Лига исследователей и Нордскол",b="Помимо политики и войны, Мурадина отличало неутомимое любопытство. Вместе с братьями он помог основать Лигу исследователей дворфов, посвятившую себя поискам утерянных реликвий титанов и описанию дальних уголков мира. Он полюбил пустынный, продуваемый ветрами континент Нордскол, часто отправлялся на север, чтобы зарисовывать древнюю архитектуру и описывать его свирепых обитателей. Именно суровые тайны Нордскола в итоге привлекли его в последнюю экспедицию в поисках преданий, реликвий и шепотом передаваемой легенды о забытом рунном клинке."},{t="Обретение Ледяной Скорби",b="Когда принц Артас прибыл в Нордскол, одержимый охотой на повелителя ужаса Мал'Ганиса, он встретился с Мурадином и привлек его дворфийскую экспедицию. Артас искал силу Ледяной Скорби, чтобы изменить ход войны, не обращая внимания на растущую тревогу Мурадина, пока принц предавал собственных наемников и отбрасывал всякую честь. У алтаря Ледяной Скорби Мурадин прочел предупреждение, высеченное на ледяном пьедестале, и умолял бывшего ученика повернуть назад. Артас отказался. Когда принц схватил рунный клинок, взрыв нечестивого льда сразил Мурадина, и тот остался лежать на полу пещеры, по всей видимости мертвым."}},faq={{q="Кем был Мурадин Бронзобород?",a="Мурадин Бронзобород был средним братом короля Магни Бронзоборода и исследователя Бранна. Он был героем-ветераном Второй войны, послом Стальгорна в Лордероне и одним из основателей Лиги исследователей.",al={"who is muradin","muradin lore","magni brother muradin","кто такой мурадин","предания о мурадине","брат магни мурадин"}},{q="Что случилось с Мурадином в Нордсколе?",a="Мурадин сопровождал принца Артаса в пещеру, где находилась Ледяная Скорбь. Когда Артас проигнорировал предостережения Мурадина и разбил ледяную темницу клинка, взорвавшийся осколок зачарованного льда поразил Мурадина, по-видимому убив его на месте. Артас бросил его тело и забрал клинок.",al={"how did muradin die","muradin death","did arthas kill muradin","как умер мурадин","смерть мурадина","убил ли артас мурадина"}},{q="Какие отношения были у Мурадина с принцем Артасом?",a="Служа послом Стальгорна в Столице, Мурадин взял Артаса под свое крыло. Он обучал юного принца бою на клинках и пережил с ним множество приключений, относясь к Артасу почти как к приемному сыну или любимому племяннику — до темного падения Артаса в Нордсколе.",al={"did muradin know arthas","muradin arthas teacher","muradin and arthas","знал ли мурадин артаса","мурадин учитель артаса","мурадин и артас"}},{q="Какую роль Мурадин сыграл во Второй войне?",a="Мурадин был связующим звеном Альянса между Лордероном и Каз Моданом. Он защищал Стальгорн во время осады Орды, а затем двинулся на юг с объединенной армией Альянса, чтобы сражаться у Вершины Черной горы и Темного портала.",al={"muradin second war","muradin battles","did muradin fight the horde","мурадин вторая война","битвы мурадина","сражался ли мурадин с ордой"}},{q="Почему Мурадин вообще отправился в Нордскол?",a="Как один из основателей Лиги исследователей, Мурадин был глубоко увлечен археологией и древними руинами Нордскола. Он вернулся туда в экспедиции, чтобы раскрыть забытую историю и найти реликвии, что в итоге привело его на след Ледяной Скорби.",al={"why was muradin in northrend","muradin expedition","what was muradin looking for","почему мурадин был в нордсколе","экспедиция мурадина","что искал мурадин"}},{q="Как король Магни отреагировал на смерть Мурадина?",a="Король Магни и весь клан Бронзобородов были убиты горем из-за потери Мурадина. Его предполагаемая гибель разорвала некогда теплую связь между Стальгорном и принцем Артасом, превратив скорбь в горькую ярость против Плети.",al={"magni muradin reaction","ironforge muradin grief","реакция магни на мурадина","стальгорн скорбь по мурадину"}}},fp="19,345,24.628.0,35.562.0,27.596.1,28.218.0,38.295.0,51.278.0,42.218.0,51.255.0,44.218.0"}
P.entries["topic:naga"] = {n="Нага",s="Нага — чудовищная змееподобная раса, обитающая в глубинах океана, которой правит их древняя императрица, королева Азшара. Некогда они были элитой высокорожденных Империи кальдораев, но во время Великого Раскола десять тысяч лет назад были превращены в земноводных чудовищ. Недавно вынырнув из темных вод, они захватили побережья Калимдора и Восточных королевств, чтобы вернуть свою забытую империю на суше.",h="Нага — чудовищная змееподобная раса, обитающая в глубинах океана, которой правит их древняя императрица...",kw={"azshara","highborne","naga","nazjatar","old gods","sea witch","sundering","vashj","азшара","высокорожденные","нага","назжатар","древние боги","морская ведьма","раскол","вайш"},ang={["faction:Alliance"]="Альянс помнит нага по руинам Даларана, где создания леди Вайш захватили уцелевших и вызвали раскол между кровавыми эльфами и силами верховного маршала Гаритоса.",["faction:Horde"]="Тралл и Орда отражали набеги нага от Острова Черного Копья до берегов Пылевых топей, где леди Темночешуйка убивала жителей человеческих поселений и нападала на окраины Дуротара.",["race:NightElf"]="Для ночных эльфов нага — отвратительное и мучительное напоминание о гордыне высокорожденных, расколовшей древний Калимдор. Вид бывшего двора Азшары, выползающего на побережье Темных берегов и в Ясеневый лес, — горький призыв истребить своих древних сородичей.",["race:Troll"]="Тролли Черного Копья питают лютую ненависть к нага с тех пор, как морская ведьма Зар'джира изгнала их с острова во время плавания по Великому морю — нападения, унесшего жизнь их старейшины и вождя Сен'джина."},sec={{t="Падение высокорожденных",b="Десять тысячелетий назад знать высокорожденных Империи кальдораев безраздельно правила из своей великой столицы Зин-Азшари. Одержимые жаждой тайной силы, королева Азшара и ее ближний двор использовали Источник Вечности, чтобы привлечь взор Темного Титана Саргераса, навлекая катастрофическое вторжение, известное как Война Древних. Когда Источник Вечности рухнул, вызвав Великий Раскол, дворец ушел в сокрушающую бездну. Перед лицом полного уничтожения Азшара заключила сделку со злобными Древними богами в глубинах. В обмен на спасение ее и ее приверженцев превратили в холодных, чешуйчатых змееподобных существ, привязанных к глубинам."},{t="Глубины Назжатара",b="На морском дне под бушующей яростью Водоворота выжившие возвели водную империю Назжатар. Питая десятитысячелетнюю обиду на поверхностный мир, нага сохранили высокомерие высокорожденных, одновременно мутируя в отдельные касты: громадных воинов-громил и многоруких морских ведьм, плетущих заклинания. Под непреклонным взором Азшары они довели до совершенства власть над морскими тварями, магию бурь и колдовство льда, медленно восстанавливая силы в ожидании возможности нанести ответный удар жителям суши."},{t="Возвращение на поверхность",b="Нага нарушили свое десятитысячелетнее молчание во время Третьей войны. Орда Тралла впервые столкнулась с морской ведьмой Зар'джирой в Великом море, а леди Вайш откликнулась на призыв Иллидана Ярость Бури, направив войска нага через руины Даларана. Сегодня по всему миру лагеря нага агрессивно наступают на побережья Азшары, Темных берегов, Ясеневого леса, Пустошей, Фераласа, Пылевых топей, Хилсбрада, Арати и Тернистой долины. Движимые древним презрением и шепотом Древних богов, они заключают тайные союзы с Сумеречным Молотом и свирепыми сатирами, чтобы вернуть то, что некогда принадлежало им."}},faq={{q="Кем были нага до превращения?",a="Нага некогда были высокорожденными, аристократической верхушкой древней империи ночных эльфов. Десять тысяч лет назад, во время Великого Раскола, уничтожившего Источник Вечности, королева Азшара и ее придворные утонули в схлопывающемся море. Древние боги предложили им спасение, превратив их тела в змееподобных водных чудовищ.",al={"what are naga","naga origin","who were the naga","кто такие нага","происхождение нага","кем были нага"}},{q="Кто правит нага?",a="Нагами безраздельно правит королева Азшара, бывшая императрица кальдораев. Из своего подводного города Назжатар под Водоворотом она направляет своих морских ведьм и воинов. Даже спустя тысячи лет чудовищного превращения нага почитают ее с фанатичной преданностью.",al={"naga leader","naga queen","who leads the naga","предводитель нага","королева нага","кто возглавляет нага"}},{q="Почему нага нападают на пляжи и побережья именно сейчас?",a="Скрывшись под волнами на десять тысячелетий, нага вновь поднялись на поверхность во время Третьей войны. Они считают, что весь древний Калимдор по праву принадлежит им как истинным наследникам Империи кальдораев. Действуя под руководством королевы Азшары и Древних богов, они стремятся подчинить прибрежные земли и покорить расы суши.",al={"why are naga on land","naga invasion","why did naga return","почему нага на суше","вторжение нага","почему нага вернулись"}},{q="Почему самцы и самки нага так сильно различаются?",a="Общество нага отличается резким половым диморфизмом. Самки нага сохраняют интеллект и магическую хитрость своих предков-высокорожденных, часто имеют четыре руки и огромный талант к тайной магии, магии льда и бурь. Самцы нага крупнее — громадные громилы, покрытые тяжелой чешуей и плавниками, созданные главным образом для рукопашной войны и грубого насилия.",al={"male vs female naga","naga differences","naga sea witches","самцы и самки нага","различия нага","морские ведьмы нага"}},{q="Какие отношения связывают нага и Иллидана Ярость Бури?",a="После Третьей войны Иллидан с помощью могущественной магии призвал союзников из морских глубин. Леди Вайш откликнулась на его зов с армией нага, чтя древние узы высокорожденных и исполняя тайную волю Древних богов, желавших потрясти поверхностный мир. Силы нага помогали Иллидану на Расколотых островах, в Лордероне и за их пределами.",al={"why did naga help illidan","illidan naga","lady vashj illidan","почему нага помогли иллидану","иллидан и нага","леди вайш иллидан"}},{q="Где сейчас можно встретить нага?",a="Нага удерживают плацдармы на многих побережьях. В Калимдоре они заполонили Азшару, Темные берега, Ясеневый лес, Пустоши, Фералас и Пылевые топи. В Восточных королевствах их рейдерские отряды и алтари можно найти на берегах Предгорий Хилсбрада, Нагорья Арати и Тернистой долины.",al={"naga locations","where to find naga","naga zones","где живут нага","где найти нага","зоны нага"}}},fp="4,418,21.669.0,18.551.0,15.600.0,48.346.0,19.289.0,50.333.0,46.348.0,64.323.0,40.311.0"}
P.entries["topic:new-horde"] = {n="Новая Орда",s="Новая Орда — современная коалиция, созданная под началом вождя Тралла как отказ от кровожадной, развращенной демонами Старой Орды времен Первой и Второй войн. Она основана на шаманских традициях, чести и взаимном выживании и объединяет освобожденных орков, троллей племени Черного Копья, племена таурен Калимдора и хрупкий союз с Отрекшимися в Лордероне.",h="Новая Орда — современная коалиция, созданная под началом вождя Тралла как отказ от кровожадной, развращенной...",kw={"darkspear","doomhammer","durotar","new horde","orgrimmar","shamanism","tauren","thrall","warchief","черное копье","молот рока","дуротар","новая орда","оргриммар","шаманизм","таурены","тралл","вождь"},ang={["class:Shaman"]="Шаманизм — духовная опора Новой Орды: он возродил древние традиции связи смертных со стихиями, которые чуть не были утрачены во время демонической порчи.",["faction:Alliance"]="Многие в Альянсе по-прежнему смотрят на Новую Орду сквозь залитые кровью воспоминания о Первой и Второй войнах и с трудом верят, что орки когда-либо откажутся от своего жестокого прошлого.",["faction:Horde"]="Новая Орда — убежище для изгоев. Членство дает взаимную защиту, сохранение культуры и общую клятву чести под началом вождя Тралла.",["race:Orc"]="Новая Орда — это искупление: шанс сбросить апатию лагерей для интернированных, почтить жертву Грома Адского Крика и жить как свободные шаманские воины."},sec={{t="Возрожденное наследие",b="Первоначальная Орда была оружием, созданным Пылающим Легионом и Советом Теней: он наполнил орков демонической жаждой крови и погнал их через Темный портал. После того как Вторая война закончилась разрухой, уцелевших орков согнали в лагеря для интернированных Альянса, где они впали в изматывающую душу апатию. Благодаря усилиям Оргрима Молота Рока, Громмаша Адского Крика и молодого шамана Тралла орки сбросили демонические оковы, вновь обрели шаманизм предков и пробились к свободе."},{t="Через Великое море",b="Следуя пророческим видениям загадочного Пророка, Тралл повел свой народ через Великое море на дикий континент Калимдор. По пути Орда приняла изгнанных троллей племени Черного Копья Сен'джина. Прибыв в Калимдор, Тралл заключил союз с Кэрном Кровавым Копытом и кочевыми таурен и помог отразить натиск враждебных племен кентавров. Вместе эти разные народы сражались бок о бок с людьми и ночными эльфами на горе Хиджал, сорвали вторжение Пылающего Легиона и обрели новый дом — Дуротар."},{t="Современная коалиция",b="Сегодня Новая Орда стремится выстроить прочное общество, опираясь на укрепленную столицу — Оргриммар. Хотя основой остается крепкая связь орков, троллей Черного Копья и таурен, ради выживания Тралл был вынужден принять нелегкие союзы, главный из которых — с Сильваной Ветрокрылой и Отрекшимися в руинах Лордерона. Тралл добивается хрупкого мира с Альянсом, но старая вражда, нехватка ресурсов и воинственные круги в обеих фракциях держат границы на грани войны."}},faq={{q="Чем Новая Орда отличается от Старой Орды?",a="Старой Ордой правили демоническая порча, темные чернокнижники и жестокие завоевания времен Первой и Второй войн. Новая Орда, основанная Траллом, открыто отвергла Пылающий Легион, возродила утраченные шаманские корни орков и ставит во главу угла честь, сохранение культуры и самоопределение.",al={"old horde vs new horde","how is this horde different","thrall horde difference","старая орда и новая орда","чем эта орда отличается","отличие орды тралла"}},{q="Кто возглавляет Новую Орду?",a="Тралл, сын Дуротана, является Вождем. Он правит из Аллеи Мудрости в Оргриммаре, тесно советуясь с верховным вождем Кэрном Кровавым Копытом из племени таурен и Темным охотником Вол'джином из троллей Черного Копья.",al={"warchief","who is the leader","thrall's role","вождь","кто лидер","роль тралла"}},{q="Какие расы входят в Новую Орду сейчас?",a="Основу Новой Орды составляют орки, тролли племени Черного Копья и таурен Мулгора. За морем, в Восточных королевствах, нежить Отрекшихся под началом леди Сильваны Ветрокрылой состоит в Орде на основе прагматичного военного союза.",al={"horde races","who is in the horde","horde members","расы орды","кто в орде","члены орды"}},{q="Почему Отрекшиеся присоединились к Новой Орде?",a="Окруженная Алым орденом, враждебными людьми и остатками Плети, Сильвана Ветрокрылая искала сильных союзников ради выживания. Таурен во главе с верховным друидом Хамуулом Руническим Тотемом выступили за них в Оргриммаре, веря, что Отрекшихся можно искупить, и убедили Тралла принять их во взаимный союз по расчету.",al={"undead in the horde","why forsaken horde","why are undead with thrall","нежить в орде","почему отрекшиеся в орде","почему нежить с траллом"}},{q="Заражены ли орки по-прежнему демонической кровью?",a="Нет. Когда Громмаш Адский Крик и Тралл схватились с повелителем ям Манноротом в Ясеневом лесу, Гром сразил демона ценой собственной жизни. Гибель Маннорота навсегда разрушила проклятие крови и освободила каждого орка от демонического рабства.",al={"demon blood","blood curse","are orcs still evil","демоническая кровь","проклятие крови","орки все еще злые"}},{q="Находится ли Новая Орда сейчас в состоянии войны с Альянсом?",a="Открытую полномасштабную войну официально сдерживает хрупкое перемирие между Траллом и леди Джайной Праудмур из Терамора. Однако ожесточенные стычки не стихают в Ясеневом лесу, Альтеракской долине и Низине Арати: недоверие и споры из-за ресурсов постоянно грозят перерасти в открытый конфликт.",al={"are horde and alliance at war","peace with alliance","horde alliance conflict","война орды и альянса","мир с альянсом","конфликт орды и альянса"}}},fp="9,351,15.518.0,22.511.0,20.493.0,54.293.0,24.221.0,46.251.0,40.319.0,44.253.0,52.303.0"}
P.entries["topic:night-elf"] = {n="ночной эльф",s="Ночные эльфы, или кальдораи, — древняя и замкнутая раса, обитающая в лесах северного Калимдора. Некогда они были повелителями обширной магической империи, но после катастрофической Войны Древних отказались от тайной магии и обратились к поклонению Элуне и пути друидизма. После Третьей войны, пожертвовав бессмертием ради победы над Пылающим Легионом, они вступили в Альянс, чтобы защитить земли предков от натиска Орды.",h="Ночные эльфы, или кальдораи, — древняя и замкнутая раса, обитающая в лесах северного Калимдора.",kw={"ashenvale","cenarius","darnassus","elune","kaldorei","night elf","nordrassil","sundering","teldrassil","well of eternity","ясеневый лес","кенарий","дарнасс","элуна","кальдораи","ночной эльф","нордрассил","раскол","тельдрассил","источник вечности"},ang={["class:Druid"]="Традиции ночных эльфов под руководством полубога Кенария сформировали современное друидство, связав стражей-кальдораев с Изумрудным Сном и защитой природного равновесия.",["faction:Horde"]="Агрессивная вырубка леса Ордой в Ясеневом лесу превратила свирепых Часовых и бдительных друидов кальдораев в одних из самых упорных и опасных ваших противников в Калимдоре.",["race:NightElf"]="Ваш народ несет мудрость и бремя десяти тысячелетий и осваивается в опасной новой реальности: смертность стала настоящей, леса предков в осаде, а древние традиции подвергаются испытанию.",["race:Troll"]="История троллей помнит кальдораев как чародеев-выскочек, разрушивших великие империи Амани и Гурубаши тысячи лет назад, что положило начало древнему и горькому соперничеству."},sec={{t="Дети звезд",b="Тысячелетия назад любознательное ночное племя поселилось на берегах Источника Вечности — огромного родника необузданной тайной энергии. Со сменой поколений космическая магия Источника преобразила их в высоких, долгоживущих существ с фиолетовой кожей, назвавших себя кальдораями — «дети звезд». Их раннее общество направляли богиня луны Элуна и лесной полубог Кенарий, который взращивал их глубокую связь с живой природой Калимдора."},{t="Империя и Раскол",b="С течением столетий правящая каста — высокорожденные во главе с королевой Азшарой — одержимо стремилась раскрыть бесконечные тайны Источника. Их безрассудное чародейство разрушило империи троллей и создало поразительные чудеса, но в итоге привлекло внимание Пылающего Легиона. Последовавшее демоническое вторжение завершилось Великим Расколом: Источник сжался и взорвался, расколов древний Калимдор на отдельные континенты и уничтожив державу Азшары. Потрясенные катастрофой, уцелевшие кальдораи строжайше запретили тайную магию под страхом смерти или изгнания."},{t="Долгое бдение и новая эпоха",b="Десять тысяч лет ночные эльфы жили в уединении. Друиды спали в Изумрудном Сне, исцеляя мир, а жрицы Элуны и Часовые охраняли леса Калимдора под Мировым Древом Нордрассил. Затворничеству пришел конец во время Третьей войны, когда Легион вернулся и напал на гору Хиджал. Кальдораи пожертвовали бессмертием, чтобы победить Архимонда. Теперь под предводительством верховной жрицы Тиранды Шелест Ветра и верховного друида Фэндрала Оленьего Шлема ночные эльфы живут на своем юном Мировом Древе — Тельдрассиле — и сражаются вместе с Альянсом, защищая Ясеневый лес."}},faq={{q="Что означает слово «кальдораи»?",a="На родном для них дарнасском языке «кальдораи» означает «дети звезд». Это имя приняли первые ночные эльфы, поселившись вокруг Источника Вечности и посвятив себя богине луны Элуне.",al={"kaldorei meaning","what is kaldorei","night elf native name","значение кальдораи","что такое кальдораи","собственное название ночных эльфов"}},{q="Откуда произошли ночные эльфы?",a="Примерно пятнадцать тысяч лет назад замкнутое племя темных троллей поселилось на сияющих берегах Источника Вечности. Из поколения в поколение под воздействием необузданной магической энергии озера их тела и разум изменились, превратив их в изящных долгоживущих кальдораев.",al={"night elf origins","where do night elves come from","are elves evolved trolls","происхождение ночных эльфов","откуда взялись ночные эльфы","эльфы произошли от троллей"}},{q="Почему ночные эльфы не используют тайную магию?",a="Десять тысяч лет назад королева Азшара и ее высокорожденные чародеи привлекли демонический Пылающий Легион в Азерот своим безрассудным обращением с Источником Вечности. Последовавшая война разрушила мир во время Великого Раскола. После этого ночные эльфы запретили тайную магию, чтобы демоны никогда больше не нашли Азерот.",al={"why no night elf mages","night elf arcane ban","why did night elves ban magic","почему нет ночных эльфов магов","запрет тайной магии","почему ночные эльфы запретили магию"}},{q="Остались ли ночные эльфы бессмертными?",a="Нет. Бессмертие и нестареющую природу ночные эльфы получили от Мирового Древа Нордрассил, благословленного Аспектами драконов. Во время битвы на горе Хиджал в Третьей войне кальдораи взорвали древнюю силу Нордрассила, чтобы уничтожить владыку демонов Архимонда, и тем самым лишились бессмертия.",al={"are night elves immortal","did night elves lose immortality","how long do night elves live","бессмертны ли ночные эльфы","потеряли ли ночные эльфы бессмертие","сколько живут ночные эльфы"}},{q="Где находится столица ночных эльфов?",a="Столица ночных эльфов — Дарнасс, построенный на огромной кроне Тельдрассила, исполинского Мирового Древа, посаженного у северо-западного побережья Калимдора после Третьей войны.",al={"night elf capital","where do night elves live","darnassus location","столица ночных эльфов","где живут ночные эльфы","расположение дарнасса"}},{q="Почему ночные эльфы вступили в Альянс?",a="После столетий изоляции кальдораи сражались бок о бок с людьми и дворфами против Пылающего Легиона на горе Хиджал. После войны Орда начала масштабную вырубку священных чащ Ясеневого леса ради древесины, и ночные эльфы заключили официальный союз с Восточными королевствами, чтобы защитить свои границы.",al={"why are night elves alliance","night elf alliance allegiance","why join alliance","почему ночные эльфы в альянсе","союз ночных эльфов с альянсом","зачем вступать в альянс"}}},fp="9,467,21.454.0,28.575.0,30.590.0,26.232.0,36.275.0,44.339.0,31.324.0,39.177.0,42.313.0"}
P.entries["topic:night-watch"] = {n="Ночной Дозор",s="Ночной Дозор — осажденное городское ополчение, отвечающее за защиту Темнолесья и мрачных дорог Сумеречного леса. Брошенные Домом знати в Штормграде, эти местные добровольцы в одиночку противостоят бродячей нежити, диким воргенам и затаившемуся некромантству. Во главе с командиром Алтеей Чернодрев, они во многом полагаются на приезжих искателей приключений, чтобы тьма не поглотила их дом.",h="Ночной Дозор — осажденное городское ополчение, отвечающее за защиту Темнолесья и мрачных дорог Сумеречного...",kw={"althea ebonlocke","darkshire","duskwood","militia","mor'ladim","night watch","raven hill","stormwind","worgen","алтея чернодрев","темнолесье","сумеречный лес","ополчение","мор'ладим","ночной дозор","вороний холм","штормград","воргены"},ang={["class:Paladin"]="Паладины видят в отчаянном бдении Ночного Дозора священный долг и приходят на помощь, защищая простых горожан священной магией от разгула некромантии.",["class:Warrior"]="Воины находят родственные души в суровых бойцах ополчения, которые стоят насмерть против вурдалаков, гигантских пауков и воргенов с простой сталью и упрямой решимостью.",["faction:Alliance"]="Герои Альянса, посещающие Темнолесье, находят там передовую общину, удерживающую границу против жутких сил без всякой официальной помощи верховного командования.",["race:Human"]="Для людей королевства беда Ночного Дозора обнажает гниль и безразличие знати Штормграда, бросившей сограждан умирать во тьме."},sec={{t="Брошены короной",b="Когда скверная магия охватила цветущую Большую деревню и превратила лес в Сумеречный лес, королевство Штормград отвернулось от нее. После исчезновения короля Вариана Ринна королевский гарнизон отвели в столицу. Лишившись официальных королевских войск и снабжения, жители создали собственное ополчение из добровольцев — Ночной Дозор — и поклялись удерживать границы Темнолесья от подступающих ужасов леса."},{t="Передовая в тумане",b="Дозорные действуют из своей штаб-квартиры в Темнолесье и патрулируют дороги, вечно окутанные неестественным туманом. Их противники беспощадны: алчные скелеты и упыри, выходящие с кладбищ Вороньего Холма и Тихих садов, а также жуткие дикие воргены, бродящие по Погибели Роланда и Светлой роще. Значительно уступая в численности и ресурсах, ополчение потеряло многих лучших защитников из-за таких безжалостных угроз, как бродячий скелет-воин Мор'Ладим."},{t="Бдение Командира Чернодрев",b="Командир Алтея Чернодрев, дочь главы Темнолесья, руководит обороной с мрачным практицизмом. Не имея подкреплений из ветеранов, она привлекает любого способного путника, прибывшего в город, чтобы проредить скелетов, перебить голодные волчьи стаи или расследовать загадочные местные убийства. Ночной Дозор считает себя последним оплотом человеческой жизни в этом краю: если его линии рухнут, Темнолесье целиком падет во тьму."}},faq={{q="Почему Штормград не присылает войска на помощь Ночному Дозору?",a="Пока король Вариан Ринн пропал, Дом знати Штормграда охвачен политическим тупиком. Заявив, что военные ресурсы должны оставаться вокруг столицы и в Элвиннском лесу, корона вывела свои гарнизоны, оставив жителей Сумеречного леса полностью на произвол судьбы.",al={"why no stormwind guards","where is stormwind army","why duskwood abandoned","почему нет стражи штормграда","где армия штормграда","почему сумеречный лес брошен"}},{q="Кто командует Ночным Дозором?",a="Командир Алтея Чернодрев руководит ополчением из управления Ночного Дозора в Темнолесье. Она дочь главы города, лорда Элло Чернодрева, и лично организует патрули на дорогах, награды за головы и оборонительные планы по всему Сумеречному лесу.",al={"who leads the night watch","night watch commander","who is in charge of darkshire watch","кто руководит ночным дозором","командир ночного дозора","кто главный в дозоре темнолесья"}},{q="С какими угрозами Ночной Дозор сталкивается чаще всего?",a="Чаще всего им противостоят восставшая нежить, выходящая с Безмятежного кладбища и Вороньего Холма, дикие волчьи стаи и загадочные волкоподобные существа — воргены, что бродят по Светлой роще и Погибели Роланда.",al={"duskwood enemies","what do watchers fight","night watch threats","враги сумеречного леса","с кем сражаются дозорные","угрозы ночного дозора"}},{q="Кто такой Мор'Ладим и почему Дозорные его боятся?",a="Мор'Ладим — бродячий, исключительно могущественный ужас из нежити, обитающий на Кладбище Вороньего Холма. Он перебил несколько сильнейших патрулей Ночного Дозора, став одним из самых смертоносных и внушающих страх существ в этих землях.",al={"mor'ladim lore","morladim night watch","cemetery boss duskwood","мор'ладим предание","мор'ладим ночной дозор","босс кладбища сумеречный лес"}},{q="Дозорные — профессиональные солдаты или добровольцы?",a="Это местные добровольцы — фермеры, охотники и горожане, взявшиеся за оружие ради выживания. Хотя их обучали местные ветераны, у них нет официальной военной поддержки, королевского снаряжения и регулярного жалованья.",al={"are watchers guards","night watch background","is night watch an army","дозорные это стража","история ночного дозора","ночной дозор это армия"}},{q="Где находится штаб-квартира Ночного Дозора?",a="Штаб-квартира расположена в сердце Темнолесья, где командир Алтея Чернодрев и ее офицеры планируют патрули и получают донесения разведчиков от часовых, стоящих на тропах.",al={"night watch building","where to find watchers","darkshire watch hall","здание ночного дозора","где найти дозорных","зал дозора темнолесья"}}},fp="11,384,22.431.0,23.499.0,32.439.0,59.280.0,29.224.0,51.213.0,51.222.0,53.211.0,46.191.0"}
P.entries["topic:nordrassil"] = {n="Нордрассил",s="Нордрассил, «Венец Небес», — первое Мировое Древо, посаженное на вершине Горы Хиджал для защиты второго Источника Вечности. Благословленное великими Аспектами драконов, оно даровало ночным эльфам нестареющее бессмертие и глубокую связь с Изумрудным Сном на десять тысяч лет. Его жертва в разгар Третьей войны сломила натиск Архимонда, но оставила древо израненным, а ночных эльфов — смертными.",h="Нордрассил, «Венец Небес», — первое Мировое Древо, посаженное на вершине Горы Хиджал для защиты второго...",kw={"alexstrasza","archimonde","hyjal","immortality","malfurion","nordrassil","nozdormu","teldrassil","well of eternity","world tree","ysera","алекстраза","архимонд","хиджал","бессмертие","малфурион","нордрассил","ноздорму","тельдрассил","источник вечности","мировое древо","изера"},ang={["class:Druid"]="Нордрассил, укорененный над вторым Источником Вечности, благодаря связи с Изерой позволял друидам без усилий переходить в Изумрудный Сон. Его шрамы остаются суровым напоминанием о цене защиты природы.",["faction:Alliance"]="Присутствие Альянса на Горе Хиджал выковало отчаянную коалицию, защитившую Нордрассил от Пылающего Легиона и обеспечившую спасение Калимдора.",["faction:Horde"]="Вождь Тралл привел Орду к склонам Горы Хиджал вместе с людьми и ночными эльфами, выиграв Малфуриону время, нужное для ловушки у подножия Нордрассила.",["race:NightElf"]="Нордрассил десять тысячелетий был колыбелью вашей цивилизации. Его жертва спасла мир от Архимонда, но впервые оставила вас бороться со старением, болезнями и неизбежностью смерти."},sec={{t="Венец Небес",b="Десять тысяч лет назад, в пепле Великого Раскола, Иллидан Ярость Бури вылил флаконы с водой изначального Источника Вечности в горное озеро на вершине Горы Хиджал, породив новый родник магической силы. Чтобы эта необузданная магия не осквернила мир и не привлекла вновь Пылающий Легион, Аспект драконов Алекстраза посадила прямо над водами желудь Матери-Древа, Г'Ханир. Из него вырос Нордрассил. Корни глубоко ушли под Азерот, запечатав неустойчивые энергии Источника и распространяя по континентам мягкую, животворную силу."},{t="Дары Аспектов",b="Нордрассил стал духовным и культурным сердцем цивилизации ночных эльфов благодаря благословениям трех великих Аспектов драконов. Алекстраза наделила древо несравненной силой, даровав кальдораям жизненную энергию. Изера связала древо с Изумрудным Сном, позволив друидам ночных эльфов без труда входить в ее дремлющее царство. И главное, Ноздорму Вневременный возложил свое благословение на его ветви: пока стоит исполинское древо, ночные эльфы не будут стареть и умирать от естественных болезней, и целая раса обрела непреходящее бессмертие."},{t="Падение на Горе Хиджал",b="Покой Нордрассила закончился с Третьей войной, когда повелитель демонов Архимонд двинулся на Гору Хиджал, чтобы разорвать древо и завладеть безграничной силой Источника. Когда защитники были доведены до предела, Малфурион Ярость Бури сделал высший выбор. Затрубив в Рог Кенария, он призвал тысячи духов природы и высвободил чары, хранившиеся в самом Нордрассиле. Последовавший катастрофический взрыв уничтожил Архимонда и истребил Легион. Хотя Нордрассил выжил и медленно исцеляется, его чары разрушились, лишив ночных эльфов их любимого бессмертия."}},faq={{q="Что означает Нордрассил?",a="На дарнасском Нордрассил переводится как «Венец Небес». Древо получило это имя за свою монументальную высоту: оно возвышается над вершиной священной Горы Хиджал.",al={"nordrassil translation","what does nordrassil mean in darnassian","nordrassil name meaning","перевод нордрассил","что значит нордрассил на дарнасском","значение имени нордрассил"}},{q="Где находится Нордрассил?",a="Нордрассил стоит на вершине Горы Хиджал на севере Калимдора, укоренившись прямо в водах второго Источника Вечности, созданного Иллиданом Ярость Бури.",al={"nordrassil location","where is the original world tree","where is nordrassil","местонахождение нордрассил","где первое мировое древо","где нордрассил"}},{q="Почему ночные эльфы потеряли бессмертие?",a="Чтобы победить повелителя демонов Архимонда в битве на Горе Хиджал, Малфурион Ярость Бури высвободил магические обереги и благословения, заключенные в Нордрассиле. Возникший взрыв уничтожил Архимонда, но выжег благословения Аспектов драконов, положив конец чарам вечной жизни, наложенным Ноздорму.",al={"why aren't night elves immortal anymore","night elf mortality","loss of immortality","почему ночные эльфы больше не бессмертны","смертность ночных эльфов","потеря бессмертия"}},{q="Как Нордрассил связан с Тельдрассилом?",a="Нордрассил — первое Мировое Древо на вершине Горы Хиджал. Тельдрассил — гораздо более молодое Мировое Древо, выращенное у берегов Калимдора верховным друидом Фэндралом Оленьим Шлемом и Кругом Древних в отчаянной попытке заменить Нордрассил и вернуть утраченное бессмертие.",al={"nordrassil vs teldrassil","difference between teldrassil and nordrassil","is teldrassil nordrassil","нордрассил и тельдрассил","разница между тельдрассилом и нордрассилом","тельдрассил это нордрассил"}},{q="Погиб ли Нордрассил, когда Архимонд был побежден?",a="Нет. Хотя взрыв сильно обжег и ранил Мировое Древо, корни Нордрассила уцелели. Древо по-прежнему стоит на вершине Горы Хиджал и со временем медленно залечивает раны, хотя древние благословения драконов развеялись.",al={"is nordrassil dead","did nordrassil survive","nordrassil destroyed","нордрассил мертв","нордрассил выжил","нордрассил уничтожен"}},{q="Какие драконы благословили Нордрассил?",a="Нордрассил благословили три Аспекта драконов: Алекстраза Хранительница Жизни, посадившая его и наделившая силой; Изера Дремлющая, связавшая его с Изумрудным Сном; и Ноздорму Вневременный, даровавший ночным эльфам вечную молодость.",al={"who blessed nordrassil","dragon blessings world tree","which aspects blessed nordrassil","кто благословил нордрассил","благословения драконов мировое древо","какие аспекты благословили нордрассил"}}},fp="10,411,20.560.0,18.565.0,23.600.0,26.167.0,28.163.0,47.294.0,40.274.0,48.232.0,33.242.0"}
P.entries["topic:old-god"] = {n="Древний бог",s="Древние боги — гигантские паразитические твари из плоти и безумия, упавшие с небес на заре времен Азерота. Хотя Титаны победили их и заточили глубоко под земной корой, их древний шепот по-прежнему разъедает умы смертных, искажает природу и толкает культистов конца света на поиски их темниц.",h="Древние боги — гигантские паразитические твари из плоти и безумия, упавшие с небес на заре времен Азерота.",kw={"ahn'qiraj","black empire","c'thun","n'zoth","old god","qiraji","silithus","twilight's hammer","void","y'shaarj","yogg-saron","ан'кираж","черная империя","к'тун","н'зот","древний бог","древние боги","киражи","силитус","сумеречный молот","бездна","йш'ардж","йогг-сарон"},ang={["class:Druid"]="Друиды несут священный долг очистить Изумрудный Кошмар — неестественную порчу, рожденную подземными щупальцами Древних богов, пронзившими Сон.",["class:Priest"]="Жрецы, постигающие магию Тьмы, часто соприкасаются с холодным, сводящим с ума шепотом Бездны — опасной силой, тесно связанной с древними ужасами, закованными под землей.",["class:Warlock"]="Хотя чернокнижники в основном черпают силу из магии Скверны и демонов Пылающего Легиона, некоторые безрассудно ищут запретные проклятия и жертвенные обряды, оставленные слугами Древних богов.",["race:NightElf"]="Кальдораи сражались с ордами приспешников киражей в Войне Зыбучих Песков и заперли Силитус за Стеной Скарабея, а их друиды теперь борются с порчей Древних богов, ползущей в Изумрудный Сон."},sec={{t="Черная империя",b="Задолго до начала летописей смертных Азеротом правила Черная империя — устрашающая цивилизация под властью Древних богов: Йш'арджа, К'Туна, Йогг-Сарона и Н'Зота. Эти колоссальные горы хаотической плоти вросли в земную кору планеты и повелевали армиями элементалей и роями насекомоподобных тварей. Когда явились Титаны, их армии вступили в апокалиптическую войну, чтобы вырвать богов с корнем. Однако когда Титан Аман'Тул исторг Йш'арджа с поверхности, в коре мира возникла чудовищная рана, и тайная жизненная сила планеты начала истекать. Поняв, что прямое убийство этих существ уничтожит сам Азерот, Титаны решили заточить уцелевших Древних богов в огромные подземные темницы, чтобы они навсегда оставались в дреме."},{t="Шепот из глубин",b="Даже скованные под милями камня и чарами защиты, Древние боги никогда по-настоящему не спали. Их психическая злоба непрестанно сочится в мир, развращая уязвимых. Именно их общая злоба постепенно свела с ума Нелтариона, Хранителя Земли, во время Войны Древних и превратила благородного дракона в Смертокрыла. Когда королева Азшара и ее высокорожденные утонули в бушующих водах Великого Раскола, один из Древних богов откликнулся на их отчаяние и превратил их в змеевидных наг. Кроме того, их коварная порча проникла в Изумрудный Сон и исказила обители друидов, породив ползучий ужас, известный как Изумрудный Кошмар."},{t="Движение в песках",b="В наше время цивилизации смертных считают Древних богов мифом, но их темницы трескаются. Почти тысячелетие назад насекомоподобные киражи хлынули из южной пустыни Силитуса в Войне Зыбучих Песков, служа своему повелителю К'Туну, пока кальдораи и драконы не заперли их за Стеной Скарабея. Сегодня зловещие культы вроде Сумеречного Молота собираются в темных углах Калимдора и Восточных королевств и творят мерзкие обряды, чтобы разрушить оковы Титанов и приблизить конец всей жизни смертных."}},faq={{q="Кто такие Древние боги?",a="Это древние потусторонние чудовища из плоти, щупалец и энергии Бездны, рухнувшие на Азерот много эпох назад. Они питаются хаосом и стремятся осквернить юный мир, толкая смертных и элементалей к безумию.",al={"what is an old god","old gods lore","who are the old gods","что такое древний бог","предания о древних богах","кто такие древние боги"}},{q="Сколько Древних богов было на Азероте?",a="Первобытным Азеротом правили четыре великих Древних бога: Йш'ардж, К'Тун, Йогг-Сарон и Н'Зот. Йш'арджа разорвали на части Титаны, а остальных троих заточили в подземных хранилищах по всему миру.",al={"how many old gods","list of old gods","names of old gods","сколько древних богов","список древних богов","имена древних богов"}},{q="Почему Титаны просто не убили их всех?",a="Древние боги так глубоко вросли в скалы Азерота, что вырвать их оказалось катастрофой. Когда Аман'Тул исторг Йш'арджа, в коре планеты появилась огромная кровоточащая рана. Опасаясь полного разрушения мира, Титаны построили темницы.",al={"why didn't titans kill old gods","why imprison old gods","why spare old gods","почему титаны не убили древних богов","почему заточили древних богов","почему пощадили древних богов"}},{q="Связаны ли Древние боги со Смертокрылом и нагами?",a="Да. Древние боги нашептывали Нелтариону, Хранителю Земли, пока он не сломался и не стал Смертокрылом. Когда королева Азшара и ее высокорожденные погрузились в пучину во время Великого Раскола, один из Древних богов откликнулся на их мольбы и превратил их в наг.",al={"did old gods make naga","old gods deathwing","who corrupted neltharion","древние боги создали наг","древние боги смертокрыл","кто развратил нелтариона"}},{q="Что представляет собой Сумеречный Молот?",a="Сумеречный Молот — нигилистический культ конца света, посвятивший себя служению Древним богам. Его члены стремятся освободить заточенных существ, выпустить повелителей стихий и ввергнуть мир в полную погибель.",al={"twilights hammer cult","who worships old gods","old god cultists","культ сумеречного молота","кто поклоняется древним богам","культисты древних богов"}},{q="Где заточены Древние боги?",a="Известные темницы разбросаны по миру и погребены глубоко под руинами Титанов. Например, К'Тун заперт под Ан'Киражем в Силитусе, а другие были заточены на дальнем севере и в глубоких подземных основаниях.",al={"where are old gods","old god locations","c'thun location","где древние боги","местонахождение древних богов","где находится к'тун"}}},fp="7,312,16.742.0,22.656.0,22.532.1,30.218.0,40.208.0,41.266.0,53.244.0,30.202.0,34.239.0"}
P.entries["topic:orc"] = {n="Орк",s="Изначально орки были шаманистским клановым народом с чужого мира Дренора. Демонический Пылающий Легион обманом превратил их в кровожадную завоевательную силу. После вторжения в Азерот, поражения и заключения в лагеря вождь Тралл сплотил их, чтобы вернуть духовное наследие. В новую эпоху орки возглавляют Орду из недавно основанного государства Дуротар, стремясь к чести и борясь с тенью своего демонического прошлого.",h="Изначально орки были шаманистским клановым народом с чужого мира Дренора.",kw={"bloodlust","draenor","durotar","fel","koshharg","mannoroth","orc","orcs","orgrimmar","shamanism","thrall","кровожадность","дренор","дуротар","скверна","кош'харг","маннорот","орк","орки","оргриммар","шаманизм","тралл"},ang={["class:Shaman"]="Для орков шаманизм — не просто магия, он означает возвращенную культурную душу и духовное искупление после десятилетий демонического рабства.",["faction:Alliance"]="Расы Альянса по-прежнему относятся к оркам с глубоким подозрением и застарелой обидой, помня резню Первой и Второй войн и разрушение Штормграда.",["faction:Horde"]="Орки составляют военную и идейную опору современной Орды, отстаивая честь и выживание вместе со своими союзниками — троллями, тауренами и Отрекшимися."},sec={{t="Дети Дренора",b="До своего падения орки жили как кочевые охотники и собиратели, духовные кланы, на суровых землях Дренора. Их культура строилась на почитании предков и глубоком единении со стихиями, и вели их прежде всего уважаемые шаманы. Разрозненные кланы — такие как Северные Волки, Песни Войны и Призрачной Луны — поддерживали хрупкий мир на собраниях дважды в год, известных как праздник Кош'харг. Хотя орки были могучи и очень горды, их традиционное общество определялось выживанием, честью и гармонией со стихиями, а не бездумными завоеваниями."},{t="Порча и Великие войны",b="Судьба орков раскололась, когда Кил'джеден и чернокнижник Гул'дан устроили их порабощение. Обманом заставленные выпить кровь демона Маннорота, орки были охвачены сверхъестественной жаждой крови, из-за которой их природная коричневая кожа стала болезненно-зеленой. Став первой Ордой, они почти истребили дренеев Дренора, а затем хлынули через Темный портал в Азерот. Первая и Вторая войны привели к падению человеческих королевств, а орочьи армии дошли до врат Лордерона, но внутреннее предательство и объединенный Альянс Лордерона в итоге сокрушили захватчиков, загнав уцелевших в жалкие лагеря для интернированных."},{t="Новое начало в Калимдоре",b="Заключение лишило орков демонического неистовства, оставив их вялыми и сломленными, пока Тралл, орк, выросший в человеческом плену, не бежал. Вернувшись к шаманизму, Тралл сплотил клан Северного Волка, освободил соплеменников из лагерей и создал обновленную Орду. Прислушавшись к пророческим предостережениям, он повел свой народ через Великое море в Калимдор. Там жертва Грома Адского Крика наконец навсегда разрушила проклятие крови Маннорота. Сегодня орки обосновались в засушливом краю Дуротара и построили город-крепость Оргриммар, стремясь сохранить завоеванную с трудом честь на фоне новой напряженности с Альянсом."}},faq={{q="Почему орки зеленые?",a="Изначально кожа у орков была коричневой. Зеленый цвет кожи — результат длительного воздействия магии Скверны и демонической порчи, начало которой положили чернокнижники Совета Теней, а закрепило то, что вожди выпили кровь властителя преисподней Маннорота.",al={"why is orc skin green","orc green skin origin","brown orcs vs green orcs","почему кожа орков зеленая","происхождение зеленой кожи орков","бурые орки и зеленые орки"}},{q="Откуда пришли орки?",a="Орки не уроженцы Азерота; они родом с чужого мира Дренора. Они пришли в Азерот через Темный портал, когда Гул'дан и одержимый демоном человек-чародей Медив открыли проход между мирами.",al={"orc homeworld","are orcs native to azeroth","where are orcs from","родной мир орков","орки коренные жители азерота","откуда орки"}},{q="Кто предводитель орков?",a="Орков возглавляет вождь Тралл, сын Дуротана. Выросший среди людей как раб-гладиатор, Тралл заново открыл древнее искусство шаманизма, освободил лагеря орков и привел новую Орду в Калимдор.",al={"orc warchief","orc faction leader","who leads the orcs","вождь орков","лидер фракции орков","кто возглавляет орков"}},{q="Что такое проклятие крови?",a="Проклятие крови — это демоническое порабощение орков, наложенное, когда они выпили кровь аннигилана Маннорота. Оно вселило неудержимую жажду крови, питавшую их войны, но было окончательно разрушено, когда Гром Адский Крик пожертвовал жизнью, убив Маннорота.",al={"blood of mannoroth","orc bloodlust curse","mannoroth blood","кровь маннорота","проклятие кровожадности орков"}},{q="Почему орки живут в Дуротаре?",a="После Третьей войны Тралл поселил орков в суровом, сухом прибрежном краю, который назвал Дуротаром в честь своего отца Дуротана. Его жестокая местность служит и искуплением былых грехов, и горнилом, закаляющим его народ.",al={"why is durotar a desert","why orgrimmar","why durotar","почему дуротар пустыня","почему оргриммар","почему дуротар"}},{q="Все ли орки входят в Орду Тралла?",a="Нет. Хотя Тралл возглавляет Новую Орду, остаются независимые кланы. Клан Драконьей Пасти все еще держится за порабощающие традиции в Болотине, а клан Черной горы под началом Ренда Чернорука продолжает войну из Черной горы, отвергая мир Тралла.",al={"evil orcs","hostile orcs","are all orcs friendly to horde","злые орки","враждебные орки","все ли орки дружат с ордой"}}},fp="3,493,19.589.0,29.626.0,27.625.0,19.248.0,29.218.0,30.217.0,24.275.0,32.242.0,36.254.0"}
P.entries["topic:paladin"] = {n="Паладин",s="Паладины — святые рыцари Альянса, сочетающие воинское мастерство с божественной магией. Облаченные в тяжелые латные доспехи, они владеют оружием, наделенным силой Света, чтобы защищать невинных, исцелять раненых и поражать злобных врагов.",h="Паладины — святые рыцари Альянса, сочетающие воинское мастерство с божественной магией.",kw={"alonsus faol","auras","blessings","cleric","crusader","holy light","paladin","plate","silver hand","uther","алонсус фаол","ауры","благословения","клирик","крестоносец","свет","паладин","латы","серебряная длань","утер"},ang={["class:Paladin"]="Каждый начинающий паладин идет по стопам Утера Светоносного и Алонсуса Фаола, связывая воинскую готовность с клятвой самоотверженного долга.",["class:Priest"]="Священников с паладинами связывает глубокое духовное родство, хотя они ведут паству проповедями и верой, а паладины защищают ее сталью.",["faction:Alliance"]="Паладины — нравственная опора Альянса: они воодушевляют войска священными аурами и дарят надежду на поле боя.",["race:Dwarf"]="Дворфы Стальгорна недавно приняли заветы Серебряной Длани, найдя, что дисциплина Света естественно созвучна их несгибаемому нраву.",["race:Human"]="Для людей паладины — непреходящая душа Альянса, продолжающая священный крестовый поход, рожденный в ужасах Второй войны."},sec={{t="Истоки в Лордероне",b="Паладины были основаны во время Второй войны архиепископом Алонсусом Фаолом. Увидев разорение, постигшее благочестивых клириков Североземья в Первой войне, Фаол понял, что одни целители не выдержат жестокости войны с орками. Он собрал доблестных рыцарей Лордерона и обучил уцелевших клириков воинскому искусству и божественной магии. Получив имя Рыцарей Серебряной Длани и возглавляемые Утером Светоносным, эти защитники несли человеческим королевствам и физическую защиту, и духовное обновление."},{t="Защитники Света",b="Если священники — голос Света, проповедующий веру и заботящийся о душах простого люда, то паладины — его воинская рука. Их глубокая убежденность дарует им чудесные силы: они излучают воодушевляющие ауры, накладывают на союзников освященные благословения и исцеляют смертельные раны. В битве с нечестивыми ужасами Свет пылает в их ударах, позволяя паладинам испепелять нежить и демонов праведной яростью."},{t="Наследие на юге",b="Падение Лордерона в Третьей войне рассеяло изначальный орден, но идеалы Серебряной Длани живы. Сегодня этот долг приняли люди Штормграда и стойкие дворфы Стальгорна. Действуя из таких обителей, как Собор Света и Зал Тайн, новые паладины клянутся мечами и щитами хранить справедливость и защищать Альянс от сгущающейся тьмы."}},faq={{q="Чем священник отличается от паладина?",a="Священники — голос Света: они служат верующим и дают пастырское наставление через молитву и обряд. Паладины — рука и молот Света: они облачаются в тяжелые латы и берутся за оружие, чтобы напрямую вершить божественную справедливость и защищать слабых на поле боя.",al={"paladin vs priest","difference between priest and paladin","how are paladins different from priests","паладин или священник","разница между священником и паладином","чем паладины отличаются от священников"}},{q="Кто создал первых паладинов?",a="Орден создал архиепископ Алонсус Фаол во время Второй войны. Увидев, как в Первой войне перебили клириков Североземья, он собрал набожных рыцарей и обучил уцелевших клириков, объединив воинскую дисциплину со священной магией под знаменем Рыцарей Серебряной Длани.",al={"who made paladins","founder of paladins","origin of the silver hand","кто создал паладинов","основатель паладинов","происхождение серебряной длани"}},{q="Какие расы могут быть паладинами?",a="Сейчас паладинами в Альянсе обучаются только люди и дворфы. Хотя изначально орден был только человеческим, дворфы Стальгорна приняли учение Света, и их приняли в Рыцари Серебряной Длани.",al={"can horde be paladins","who can be a paladin","paladin races","паладины орды","кто может быть паладином","расы паладинов"}},{q="Почему паладины эффективны против нежити?",a="Свет враждебен мертвенной порче и демонической энергии. Когда паладины направляют божественную силу, она очищает скверну и испепеляет нечестивых тварей, делая их главными защитниками против Плети и прочих мерзких существ.",al={"paladins vs undead","why does holy magic hurt undead","paladin scourge counter","паладины против нежити","почему священная магия вредит нежити","паладины против плети"}},{q="Что случилось с первыми Рыцарями Серебряной Длани?",a="Орден понес катастрофические потери в Третьей войне, когда чума опустошила Лордерон. Братство раскололось из-за внутреннего предательства и политических раздоров, хотя уцелевшие члены и новые посвященные в Штормграде и Стальгорне продолжают нести это звание и идеалы.",al={"what happened to silver hand","is silver hand gone","fall of the silver hand","что случилось с серебряной дланью","исчезла ли серебряная длань","падение серебряной длани"}},{q="Могут ли члены Орды стать паладинами?",a="Нет. Традиции паладинов Азерота глубоко уходят корнями в церковь и рыцарские ордена Альянса. Расы Орды обращаются к шаманам, знахарям и воинам, а не к рыцарскому пути Света.",al={"horde paladins","can orcs be paladins","why no horde paladin","паладины орды","могут ли орки быть паладинами","почему нет паладинов орды"}}},fp="7,232,20.572.0,27.459.0,21.421.0,54.301.0,31.291.0,28.244.0,46.234.0,57.285.0,41.223.0"}
P.entries["topic:pirate"] = {n="пират",s="Пираты и корсары — беззаконные морские грабители, действующие на просторах Великого моря и в прибрежных водах Азерота. Они нападают на торговые суда Альянса, Орды и нейтральных сторон, объединяясь под непрочными флагами, чтобы захватывать богатства и грузы и контролировать прибрежные бухты. Их жестокие набеги вызывают постоянные морские стычки — от вод Калимдора до берегов Восточных королевств.",h="Пираты и корсары — беззаконные морские грабители, действующие на просторах Великого моря и в прибрежных водах...",kw={"bloodsail","booty bay","buccaneer","corsair","freebooter","great sea","pirate","plunder","southsea","кровавый парус","пиратская бухта","корсар","буканьер","флибустьер","великое море","пират","добыча","южные моря"},ang={["class:Rogue"]="Жестокая тактика, ослепляющий порошок и быстрая работа клинком пиратских команд близки к практичным и смертоносным боевым приемам, которые предпочитают разбойники-наемники.",["faction:Alliance"]="Транспортным путям Альянса между Штормградом, Стальгорном и Терамором постоянно угрожают пираты, рыщущие вдоль прибрежных торговых маршрутов.",["faction:Horde"]="Флибустьеры Южных морей держат агрессивные лагеря на побережье Дуротара и Степей, нападая на караваны Орды и высадные отряды.",["race:Tauren"]="Хотя таурены по традиции жители равнин, некоторые из них, путешествуя по берегам Калимдора, оказались на пиратских судах — их либо насильно завербовали, либо они искали удачи."},sec={{t="Властелины открытого моря",b="Пираты, которых также называют корсарами, буканьерами или флибустьерами, — морские разбойники почти всех рас, живущие захватом кораблей и набегами на прибрежные поселения. Их деятельность не ограничивается простым грабежом: команды регулярно занимаются контрабандой, похищениями людей и службой наемниками у любого, кто платит. Хаос, оставшийся после Третьей войны и падения северных королевств, ослабил морской правопорядок, и пиратские фракции получили свободу создавать укрепленные опорные пункты на заброшенных островах и в прибрежных бухтах."},{t="Безжалостная жизнь",b="Хотя в рассказах жизнь пиратов выглядит романтическим приключением, на деле она на корабле корсаров тяжела и коротка. Команды терпят грязные трюмы, полные крыс, суровую дисциплину и постоянную угрозу цинги, с которой борются только запасами лаймов. Предательство — обычная опасность, а капитаны удерживают власть лишь силой и страхом наказания: от немедленной казни до высадки на необитаемый остров или скармливания акулам. После сражений пираты шумно празднуют за игрой в кости, песнями и крепким ромом."},{t="Фракции и убежища",b="Независимые команды бороздят все морские пути, но крупные организации располагают достаточным числом кораблей, чтобы бросить вызов флотам государств. Флибустьеры Южных морей досаждают судоходству в водах вокруг Калимдора, а печально известные Пираты Кровавого Паруса угрожают южным морям и ведут открытую войну с Картелем Хитрая Шестеренка в Пиратской бухте."}},faq={{q="Чем различаются пираты, корсары и флибустьеры?",a="На морских путях Азерота эти названия в основном используются как взаимозаменяемые. Одни группы предпочитают определенные знамена, например Флибустьеры Южных морей или Пираты Кровавого Паруса, но все они занимаются морскими набегами, грабежом, контрабандой и разорением побережий.",al={"buccaneer vs pirate","freebooter difference","pirate titles","корсар или пират","разница флибустьер","названия пиратов"}},{q="Где находятся главные пиратские базы?",a="Пиратские команды собираются в беззаконных гаванях и тайных бухтах по всему миру. Главные убежища — остров Добычи и прибрежные лагеря, разбросанные по берегам Танариса, Степей и Тернистой долины.",al={"pirate towns","where do pirates live","pirate ports","пиратские города","где живут пираты","пиратские порты"}},{q="На кого нападают пираты?",a="Большинство пиратских команд нападают без разбора. Они охотятся на торговые суда, гражданские транспорты и военные грузовые суда Альянса, Орды и нейтрального Картеля Хитрая Шестеренка. Любой корабль с золотом, древесиной или товарами — потенциальная цель.",al={"who do pirates target","are pirates alliance or horde","кого грабят пираты","пираты за альянс или орду"}},{q="Как пиратские команды набирают новых членов?",a="Пираты пополняют ряды, нанимая отчаявшихся головорезов и наемников в портовых городах, но также широко прибегают к насильственной вербовке. Захваченным морякам и путникам часто предлагают выбор: присягнуть команде или отправиться за борт.",al={"joining pirates","how do they get crew","вступить к пиратам","как набирают команду"}},{q="Как Кул Тирас борется с пиратами?",a="Закон Кул Тираса считает пиратство одним из самых гнусных преступлений моряка. Схваченных патрулями Кул Тираса ждет немедленная публичная казнь, хотя редким командам удавалось получить королевское помилование, выполнив опасные и важные поручения для адмиралтейства.",al={"kul tiras piracy","kul tiran pirate law","кул тирас пиратство","закон кул тираса о пиратах"}},{q="Бывают ли пираты других рас?",a="Да. Хотя команды из людей встречаются часто, пираты принимают любого, кто готов грабить и подчиняться приказам. В командах бывают орки, гоблины, тролли, дворфы и даже таурены, которых завербовали или насильно взяли на службу на берегах Калимдора.",al={"tauren pirates","orc pirates","goblin pirates","пираты-таурены","пираты-орки","пираты-гоблины"}}},fp="6,400,22.544.0,15.540.0,19.327.0,67.265.0,40.215.0,22.275.0,40.262.0,37.276.0,28.236.0"}
P.entries["topic:plague-of-undeath"] = {n="Чума нежизни",s="Чума нежизни — сверхъестественная зараза, созданная Королем-личом по указанию Пылающего Легиона, чтобы опустошить север Восточных королевств. Распространяясь через зараженное зерно, воздушные котлы и отравленные водоемы, болезнь быстро убивает живых и поднимает их как безвольных рабов Плети.",h="Чума нежизни — сверхъестественная зараза, созданная Королем-личом по указанию Пылающего Легиона, чтобы...",kw={"andorhal","blight","cauldrons","grain","kel'thuzad","mal'ganis","ner'zhul","plague","scourge","stratholme","undeath","андорал","порча","котлы","зерно","кел'тузад","мал'ганис","нер'зул","чума","плеть","стратхольм","нежизнь"},ang={["class:Paladin"]="Орден Серебряной Длани был разгромлен при попытке сдержать заразу, и паладинам остается полагаться лишь на Свет, чтобы очистить ее мерзкие остатки.",["class:Priest"]="Жрецы видят в чуме предельное осквернение тела и духа, и это побуждает их веру сжигать некротическую болезнь, пока она не загнила.",["faction:Alliance"]="Потеря северных королевств из-за чумы остается для Альянса незаживающей раной и движет его непрекращающимся походом за очищение Чумных земель.",["faction:Horde"]="Хотя орки и таурены считали северную болезнь человеческим проклятием, исследования Королевского фармацевтического общества принесли ужас опытов с чумой прямо в Орду.",["race:Human"]="Чума нежизни уничтожила Королевство Лордерон и разрушила семьи, став прямой причиной величайшей катастрофы в истории человечества.",["race:Undead"]="Многие Отрекшиеся носят физические шрамы от чумы: они пережили ее муки и умерли, а спустя годы освободились от психической власти Короля-лича."},sec={{t="Истоки во льдах",b="Чуму создал павший шаман Нер'зул после того, как Кил'джеден превратил его в Короля-лича. Со своего ледяного престола на Ледяном Троне в Нордсколе Нер'зул довел болезнь до совершенства как нечестивый авангард вторжения Пылающего Легиона. Испытывая силу на изолированных человеческих деревнях Нордскола, он обнаружил, что может угасить жизнь и мысленно повелевать трупами, восставшими вскоре после этого. Телепатический зов Нер'зула достиг через Великое море мага Кирин-Тора Кел'Тузада, который покинул Даларан, чтобы служить этому существу. Кел'Тузад основал тайный Культ Проклятых, чьи смертные лазутчики подготовили почву, чтобы отравить Лордерон изнутри."},{t="Зерно Андорала",b="Кел'Тузад и повелитель ужаса Мал'Ганис выбрали для распространения заразы земледельческое сердце Лордерона. Культ занял распределительные пункты вокруг Андорала и упаковал чуму в ящики с зерном, предназначенные для населенных центров севера, включая Брилл и Стратхольм. Ничего не подозревавшие селяне пекли хлеб из зараженных поставок и заболевали: суставы горели, появлялись гнойные язвы, глаза мутнели. Через три дня целые общины погибали и тут же восставали плотоядными зомби, подчиненными мысленному зову Короля-лича. Принц Артас Менетил поспешил перехватить поставки, и это привело к ужасной чистке жителей Стратхольма до того, как зараженный хлеб превратил бы их в армию Мал'Ганиса."},{t="Оскверненная земля",b="Поветрие распространяется далеко за пределы человечества. Хотя нелюдская фауна обычно страдает от мучительной лихорадки или гниения, а не восстает нежитью, сама земля несет на себе основной удар демонического и некромантического распада. По всем Чумным землям огромные чумные котлы выпускают алхимические и магические испарения прямо в воздух, оскверняя окрестные земли, где процветают падальные личинки и громадные грибы, забитые спорами. Серебряный Рассвет активно борется с этой воздушной порчей, саботируя котлы и обращая их каталитические смеси так, чтобы они жгли Плеть, а не питали ее. Тем временем в Подгороде Королевское фармацевтическое общество неустанно экспериментирует, совершенствуя Новую чуму, призванную убивать и живых врагов, и нежить."}},faq={{q="Как чума первоначально распространилась по Лордерону?",a="Культ Проклятых Кел'Тузада проник в распределительный узел Андорала. Культисты заразили запасы зерна чумой и отправили ящики в города по всему королевству, например в Стратхольм и Брилл. Когда местные жители съели зараженную муку, они поддались болезни и восстали нежитью.",al={"how did plague spread","infected grain","plagued grain distribution","grain of andorhal","как распространилась чума","зараженное зерно","распространение зерна с чумой","зерно андорала"}},{q="Что происходит с тем, кого заразила чума?",a="У жертв быстро развиваются слабость, тошнота, боль в суставах и жар. Кожа покрывается раздраженными нарывами и сочащимися желто-зелеными язвами, а глаза мутнеют. Вскоре начинается сильное кровотечение из ушей и глаз. Большинство смертных умирает в течение трех дней, а вскоре после этого восстает как оживленные слуги, ожидающие приказов Короля-лича.",al={"plague symptoms","what does the plague do","how fast does plague kill","симптомы чумы","что делает чума","как быстро убивает чума"}},{q="Почему чума действует на людей иначе, чем на другие расы?",a="Король-лич намеренно создал чуму так, чтобы она поражала людей и уничтожила Королевство Лордерон. Дикие животные и нелюдские расы, подвергшиеся чуме, часто страдают от ужасного гниения, бреда и лихорадки, но редко сами восстают как рабы Плети без дополнительных прямых некромантических заклинаний.",al={"why humans","does plague affect elves","are orcs immune to plague","почему люди","действует ли чума на эльфов","есть ли у орков иммунитет к чуме"}},{q="Можно ли излечить Чуму нежизни?",a="В нынешнюю эпоху установленного лекарства неизвестно. Природные снадобья не могут обратить чуму вспять; если жертва умерла и восстала, превращение уже нельзя отменить.",al={"is plague curable","cure for the plague","healing the plague","излечима ли чума","лекарство от чумы","исцеление от чумы"}},{q="Для чего нужны гигантские котлы в Чумных землях?",a="Плеть возвела огромные котлы на бывших фермерских землях, чтобы выпускать испаренную чуму прямо в воздух. Такое распространение по воздуху портит почву, затягивает небо тучами и заражает проходящих зверей. Серебряный Рассвет неустанно противодействует этим котлам, превращая их реагенты в священное или ядовитое оружие против Плети.",al={"plague cauldrons","what are cauldrons doing","why are cauldrons in fields","чумные котлы","что делают котлы","зачем котлы в полях"}},{q="Что такое Новая чума Отрекшихся?",a="Новая чума, созданная в глубинах Подгорода Королевским фармацевтическим обществом, — это особый химический и магический возбудитель. В отличие от версии Плети, Отрекшиеся разработали формулу так, чтобы она убивала и живых смертных, и нежить, подвластную Королю-личу.",al={"forsaken plague","royal apothecary society plague","new plague undercity","чума отрекшихся","чума фармацевтического общества","новая чума подгород"}}},fp="17,331,18.692.0,21.743.1,16.736.0,54.310.0,47.345.0,63.315.0,35.164.0,52.337.0,34.278.0"}
P.entries["topic:priest"] = {n="Жрец",s="Жрецы — духовные наставники и проводники огромной незримой силы, формирующие веру, исцеляющие плоть и охраняющие души. Направляя сияющую энергию веры или погружаясь в жуткие глубины Бездны, они становятся жизненно важным сердцем любого боевого отряда. По всему Азероту их традиции простираются от Церкви Священного Света до Сестринства Богини Луны и теневых культов Отрекшихся.",h="Жрецы — духовные наставники и проводники огромной незримой силы, формирующие веру, исцеляющие плоть и...",kw={"cathedral","cleric","cult","elune","healing","holy light","priest","shadow","sisterhood","void","собор","клирик","культ","элуна","исцеление","свет","жрец","тьма","сестринство","бездна"},ang={["class:Paladin"]="Паладины разделяют со священством святые философии: они возникли из потребности Церкви защитить облаченных в одеяния клириков после кровавых уроков Первой войны.",["class:Priest"]="Жрец идет по грани между чистым сиянием и разрушением разума, владея как исцеляющим милосердием молитвы, так и карающими ужасами Бездны.",["race:Human"]="Жрецы-люди наследуют стойкую традицию Клириков Североземья, служа духовной опорой Альянса через Церковь Священного Света.",["race:NightElf"]="Жрицы ночных эльфов чтят Сестринство Элуны, направляя свет звезд и лунную благодать под руководством верховной жрицы Тиранды Шелест Ветра.",["race:Undead"]="Жрецы Отрекшихся заново осмысляют свою разрушенную веру через Культ Забытой Тени, принимая равновесие темных энергий, когда прежние обеты принесли лишь гибель."},sec={{t="Сосуды веры и преданности",b="Жрецы направляют духовную судьбу своих общин. Если воины проверяют свою доблесть сталью, то жрецы черпают силу непосредственно из убеждения. Благодаря божественной связи они врачуют тяжкие раны, возвращают павших соратников с порога смерти и плетут таинственные щиты, отражающие удары. Их присутствие на поле боя нередко означает разницу между выживанием и гибелью."},{t="Свет и Тьма",b="Священство — не только орудие милосердия. Как жизнь вмещает и свет, и тьму, так и жрец идет по опасной грани между божественным исцелением и разрушением разума. Те, кто овладел священными искусствами, обрушивают испепеляющую праведную кару на врагов, а последователи магии Тьмы погружаются в Бездну, чтобы подчинять умы, искажать волю и причинять мучительную боль издалека."},{t="Многообразие вероучений",b="Ни одна вера не определяет жрецов Азерота. В землях людей и дворфов Церковь Священного Света облекает в строгую форму философию добродетели; после Первой войны она превратила своих хрупких Клириков Североземья в закаленный орден. В Калимдоре Сестринство Элуны ночных эльфов чтит Мать-Луну светом звезд и благодатью, а тролли-знахари взывают к изначальным лоа. Среди недавно восставших Отрекшихся многие отвернулись от прежних догм и обратились к Культу Забытой Тени, проповедующему, что тьма и свет должны существовать в хрупком равновесии."}},faq={{q="Чем жрец отличается от паладина?",a="Во время Первой войны человеческие клирики несли огромные потери на поле боя, потому что не имели боевой защиты. В ответ архиепископ Алонсус Фаол и Церковь основали Рыцарей Серебряной Длани, обучив облаченных в доспехи священных воинов, названных паладинами. Жрецы же остаются заклинателями в одеяниях, всецело преданными духовному служению, молитве и более глубокому постижению разума и тени.",al={"priest vs paladin","why play priest not paladin","paladin or priest lore","жрец или паладин","почему играть жрецом, а не паладином","предания паладин или жрец"}},{q="Могут ли жрецы использовать магию Тьмы, не утратив веры?",a="Да. Духовное равновесие требует, чтобы свет не существовал без тьмы. Многие жрецы изучают тень, чтобы понять опасности, угрожающие их пастве, а другие, например Культ Забытой Тени у Отрекшихся, сознательно принимают темные энергии как необходимость бытия, утверждая, что для подлинного владения собой нужно понимать обе силы.",al={"why do priests use shadow","shadow priest lore","shadow and holy balance","почему жрецы используют тьму","предания жрец тьмы","баланс тьмы и света"}},{q="Все ли играбельные расы поклоняются тому же, что и жрецы?",a="Нет. Люди и дворфы в основном следуют Церкви Священного Света — философии добродетели, а не поклонению божеству. Ночные эльфы почитают Элуну через ее Сестринство, тролли взывают к духам и лоа, а нежить среди Отрекшихся следует Культу Забытой Тени или пытается справиться с расколотой связью с прежней человеческой верой.",al={"priest religions","what gods do priests worship","elune vs holy light priest","религии жрецов","каким богам поклоняются жрецы","элуна или свет жрец"}},{q="Кто возглавляет человеческое священство в Штормграде?",a="Собор Света в Штормграде служит главной обителью человеческой церкви после падения Лордерона. Тамошнее духовенство вместе с уцелевшими клириками из Североземья руководит духовным восстановлением человечества и направляет души Альянса в эти неспокойные времена.",al={"who leads church of holy light","stormwind cathedral leader","priest leader stormwind","кто возглавляет церковь Священного Света","глава собора штормграда","главный жрец штормграда"}},{q="Почему у Отрекшихся все еще есть жрецы?",a="Многие мертвецы сохранили воспоминания и приемы из прежней жизни, посвященной вере в Лордероне. Столкнувшись с покинутостью смерти, одни примкнули к Культу Забытой Тени, управляя темными энергиями и изучая равновесие между тьмой и светом. Другие упрямо продолжают взывать к Свету, хотя это причиняет мучительную физическую боль их разлагающейся плоти.",al={"undead priests lore","can undead use the light","forsaken shadow priests","предания о жрецах нежити","может ли нежить использовать свет","жрецы тьмы отрекшихся"}},{q="Что такое Сестринство Элуны?",a="Сестринство Элуны — древний орден жриц ночных эльфов, основанный задолго до Войны Древних. Под предводительством верховной жрицы Тиранды Шелест Ветра они почитают богиню луны Элуну и служат целительницами, духовными наставницами и весьма способными лидерами в обществе ночных эльфов.",al={"night elf priests","priestesses of the moon","sisterhood of elune","жрецы ночных эльфов","жрицы луны","сестринство элуны"}}},fp="6,382,29.402.0,16.410.0,20.551.0,54.375.0,56.342.0,56.354.0,44.279.0,39.376.0,32.289.0"}
P.entries["topic:quilboar"] = {n="свинобраз",s="Свинобразы — агрессивные кабаноподобные гуманоиды, обитающие в центральном Калимдоре, известные острыми шипами на спине и неутомимой территориальной свирепостью. Они считают себя потомками павшего полубога Агамаггана и живут в густых лабиринтах острых как бритва зарослей терна в Дуротаре, Мулгоре и Степях. Их яростная борьба за воду, землю и священные места делает их постоянной угрозой для путников и поселений Орды.",h="Свинобразы — агрессивные кабаноподобные гуманоиды, обитающие в центральном Калимдоре, известные острыми...",kw={"agamaggan","barrens","blood shards","brambles","bristleback","charlga razorflank","geomancer","quilboar","quillboar","razorfen","razormane","агамагган","степи","кровавые осколки","терновник","дыбогрив","чарлга остробок","геомант","свинобраз","иглошкурые","иглогривые"},ang={["class:Shaman"]="Геомантия свинобразов — приземленное древнее ответвление шаманской традиции, хотя и искаженное в сторону территориальной жестокости и призыва свирепых духов вепрей.",["faction:Horde"]="Свинобразы представляют непосредственную угрозу снабжению в центральном Калимдоре, устраивая засады на важные караваны, идущие между Оргриммаром, Перекрестком и Громовым Утесом.",["race:Orc"]="Чтобы удержать Дуротар и Степи, необходимо сломить боевые отряды свинобразов, чьи набеги постоянно досаждают торговым повозкам Орды и дальним фермам.",["race:Tauren"]="Ваши предки сражались со свинобразами за водопои и пастбища задолго до того, как орки приплыли на запад. Их разрастающийся терновник душит природную землю, которую питает Мать-Земля."},sec={{t="Дети Великого Вепря",b="Свинобразы почитают Агамаггана — исполинского древнего вепря, погибшего в битве с Пылающим Легионом во время Войны Древних десять тысяч лет назад. Согласно их священным преданиям, свинобразы — его смертное потомство. Там, где Агамагган истекал кровью и умирал в центральном Калимдоре, из выжженной земли вырвались огромные колючие лозы, образовав раскинувшиеся корневые лабиринты, которые свинобразы считают священной землей. Его кристаллизованная кровь сохранилась в Степях в виде багровых Кровавых осколков, которые их геоманты выкапывают и почитают как могущественные талисманы."},{t="Терновые чащи и геомантия",b="Вместо обычных городов из камня или дерева свинобразы выращивают гигантский терновник, который душит окрестную растительность и делает землю вокруг бесплодной. Племена обычно возглавляют могущественные геоманты — приверженцы приземленного, грубого шаманизма, гадающие по камням и кристаллам, чтобы направлять клан. Эти мистики взывают к духу Агамаггана, чтобы призывать в бой призрачных вепрей. Поскольку в засушливых центральных равнинах мало оазисов, свинобразы видят в воде величайшее сокровище: когда выпадают редкие дожди, они устраивают пышные пиры, а источники защищают с жестокой стойкостью."},{t="Война за Степи",b="На протяжении поколений свинобразы жестоко враждовали с кочевыми тауренами и бродячими стаями кентавров. Когда Тралл привел Орочью Орду в Калимдор, орки быстро колонизировали Дуротар и проложили торговые пути через Степи, вынудив изгнанные племена к открытому мятежу. Отряды свинобразов устраивают засады на обозы, их подозревают в том, что они пугают долгоножек, загоняя их в караваны, и совершают набеги на такие форпосты, как Перекресток и Лагерь Таурахо. Два главных племени господствуют на открытых равнинах: Иглогривые и Дыбогривы, одновременно воюющие и с Ордой, и друг с другом."},{t="Тень над Иглошкурыми",b="Духовное сердце цивилизации свинобразов находится на южной окраине Степей, в Лабиринтах Иглошкурых и соседних Курганах Иглошкурых — запутанных лабиринтах, образованных непосредственно из гигантских останков Агамаггана. Честолюбивая старуха по имени Чарлга Остробок захватила власть над Лабиринтами, организуя яростные нападения на соперничающие кланы и земли Орды. Что еще хуже, традиционная столица свинобразов, Курганы Иглошкурых, попала под власть Плети. В союзе с личом Амненнаром Хладоносцем оскверненные свинобразы из племени Мертвой Головы стали нежитью, превратив родовую гробницу в оплот чумы."}},faq={{q="Почему свинобразы так ненавидят Орду?",a="Свинобразы занимали плодородные оазисы и тернистые овраги Дуротара и Степей задолго до прихода Орды. Когда орки Тралла высадились и заняли землю под постройку Оргриммара, они вытеснили местные логова свинобразов. К тому же Орда заключила союз с таурен, с которыми свинобразы враждовали поколениями. Теперь племена видят в каждом караване, форпосте и колодце украденную землю предков.",al={"why do quilboar attack orcs","quilboar horde conflict","why are quilboar hostile","почему свинобразы нападают на орков","конфликт свинобразов и орды","почему свинобразы враждебны"}},{q="Какова связь между свинобразами и Агамагганом?",a="Агамагган — исполинский полубог-вепрь, сражавшийся с Пылающим Легионом во время Войны Древних десять тысяч лет назад. Свинобразы называют себя его смертными потомками. Огромные заросли терна, в которых они живут, выросли там, где его кровь пропитала землю, а священные туннели Курганов Иглошкурых, как говорят, вырезаны из его останков.",al={"agamaggan quilboar god","who is agamaggan","quilboar demigod","агамагган свинобразы бог","кто такой агамагган","полубог свинобразов"}},{q="Что за красные камни носят свинобразы?",a="Эти багровые кристаллы — Кровавые осколки, образованные из окаменевшей крови Агамаггана. Свинобразы выкапывают их по всем Степям, веря, что в них заключены жизненная сила и мощь павшего предка. Геоманты используют эти камни как катализаторы в ритуалах земли и боевых зачарованиях.",al={"blood shards","red rocks quilboar","blood of agamaggan","кровавые осколки","красные камни свинобразов","кровь агамаггана"}},{q="Какую магию используют свинобразы?",a="Свинобразы практикуют геомантию — стихийное ремесло, сродни грубому шаманизму, посвященное камню, земле и шипам. Превыше всех мистических искусств они чтят гадание по камням и самоцветам. Племенные геоманты взывают к духам земли, призывают заросли терна, опутывающие врагов, и вызывают духов вепрей по образу Агамаггана.",al={"quilboar magic","quilboar geomancers","what is geomancy","магия свинобразов","геоманты свинобразов","что такое геомантия"}},{q="Почему свинобразы так оберегают воду?",a="Степи — засушливая пустошь, где природные источники и оазисы крайне редки. В культуре свинобразов вода означает выживание, богатство и духовное благословение. Они празднуют племенными пирами даже самые легкие пустынные дожди и яростно охраняют источники от наступающих караванов и стад.",al={"quilboar water","why quilboar hoard water","quilboar oases","вода свинобразов","почему свинобразы копят воду","оазисы свинобразов"}},{q="Чем отличаются Лабиринты Иглошкурых и Курганы Иглошкурых?",a="Оба места — огромные терновые лабиринты, выросшие из туши Агамаггана на юге Калимдора. Лабиринты Иглошкурых служат оплотом старухи Чарлги Остробок, собирающей живых свинобразов против всех чужаков. Курганы Иглошкурых были родовой столицей этого народа, но попали в руки лича Амненнара Хладоносца из Плети, который поднимает умерших свинобразов как нежить-прислужников.",al={"kraul vs downs","razorfen dungeons","where do quilboar live","лабиринты или курганы","подземелья иглошкурых","где живут свинобразы"}}},fp="8,419,26.543.0,28.581.0,23.582.0,24.632.1,39.401.0,56.327.0,39.289.0,35.305.0,40.300.0,65.385.1"}
P.entries["topic:ravenholdt"] = {n="Черный Ворон",s="Черный Ворон, также известный как Лига убийц, — элитная гильдия разбойников, воров и убийц, расположенная в уединенном горном поместье над Предгорьями Хилсбрада. Лига, которую возглавляет лорд Джорах Черный Ворон, сохраняет строгий нейтралитет в политике фракций и ведет нескончаемую теневую войну со своими заклятыми врагами — Синдикатом. Она испытывает и вербует по всему Азероту только самых хитроумных агентов, ценя превыше всего непревзойденную дисциплину, скрытность и смертоносную эффективность.",h="Черный Ворон, также известный как Лига убийц, — элитная гильдия разбойников, воров и убийц, расположенная в...",kw={"alterac","assassin","fahrad","hillsbrad","jorach","lockpicking","manor","poisons","ravenholdt","syndicate","альтерак","убийца","фарад","хилсбрад","джорах","взлом замков","поместье","яды","черный ворон","синдикат"},ang={["class:Rogue"]="Черный Ворон — ваше всемирное братство и место испытаний. Наставники, ядовары и мастера теней предлагают здесь испытания, редкие схемы оружия и признание, которых больше нигде в Азероте не добиться.",["faction:Alliance"]="Хотя Матиас Шоу и ШРУ порой согласовывают действия с Черным Вороном для подавления Синдиката, лорд Черный Ворон не обязан Штормграду верностью и без церемоний отклоняет важные просьбы Альянса.",["faction:Horde"]="Несмотря на благородный человеческий облик и расположение в северном нагорье, Черный Ворон судит агентов только по мастерству и принимает охотников Орды, доказавших свою доблесть."},sec={{t="Скрытая лига",b="Поместье Черного Ворона, спрятанное в скалистых горах между Хилсбрадом и Альтераком, служит нервным центром главного братства убийц Азерота. Организацией руководит лорд Джорах Черный Ворон, и действует она далеко за пределами власти королей и вождей. В его стенах мастера оттачивают все смертоносные искусства: мастер Канг обучает учеников ближнему бою и убийству, братья Громолесы варят редкие и смертельные яды, а гномы-мастера создают хитроумные замки для испытания новичков. Для тех, кто не является разбойником, вход в поместье — откровенная игра со смертью: неосторожный шаг легко заканчивается отравленным кинжалом под ребром."},{t="Теневая война с Синдикатом",b="Уже много лет Черный Ворон ведет все более ожесточенную вражду с Синдикатом — аристократическим преступным картелем, наводнившим Альтерак и Арати. Лига считает Синдикат неуклюжими высокомерными любителями, но их многочисленность делает невозможным уничтожить их простой резней. Поэтому Черный Ворон прибегает к психологическому и структурному подрыву: нанятые разбойники похищают печатки, которые носят главари Синдиката, а Лига рассчитывает, что из-за собственной паранойи и беспощадной иерархии Синдикат сам казнит опозорившихся членов."},{t="Независимая гильдия теней",b="Хотя Черный Ворон порой сотрудничает с другими разведывательными службами, например с ШРУ Штормграда, он не подчиняется никакой короне. Мастер Матиас Шоу иногда находит в Черном Вороне союзника в борьбе с Синдикатом, но Джорах Черный Ворон ревностно оберегает свою самостоятельность. Когда ШРУ понесло тяжелые потери, расследуя дело павшего следопыта Натаноса Марриса в Чумных землях, Черный Ворон наотрез отказал Шоу в просьбе вмешаться. Лига сама выбирает свои сражения, направляя ресурсы на поиск древних реликвий, совершенствование смертоносных искусств и на то, чтобы держать клинок у горла любого, кто имел глупость перейти ей дорогу."}},faq={{q="Что такое Черный Ворон?",a="Черный Ворон — древняя тайная гильдия воров, убийц и танцоров теней, которой управляет лорд Джорах Черный Ворон. Неофициально ее называют Лигой убийц. Она действует из секретного поместья в глубине гор над Предгорьями Хилсбрада, обучает перспективных разбойников и предлагает смертельные контракты.",al={"who are ravenholdt","what is the assassin's league","ravenholdt faction","кто такой черный ворон","что такое лига убийц","фракция черный ворон"}},{q="Почему они воюют с Синдикатом?",a="Синдикат и Черный Ворон борются за господство в руинах Альтерака и окрестном нагорье. Лига считает Синдикат недисциплинированными бесчестными разбойниками, чья неряшливая преступная деятельность угрожает тонкому балансу сил в регионе. Вместо того чтобы истреблять их измором, Черный Ворон методично подрывает их руководство, похищая знаки отличия.",al={"why syndicate vs ravenholdt","ravenholdt syndicate war","why do they hate the syndicate","почему синдикат против черного ворона","война черного ворона и синдиката","почему они ненавидят синдикат"}},{q="Могут ли посетить Поместье Черного Ворона те, кто не разбойник?",a="Добраться до поместья могут и не разбойники, но обитатели не рады чужакам. Стражи и убийцы с плохо скрытой угрозой говорят об отравленных напитках и кинжалах в спину всякому, кто забредет сюда без подтверждения мастерства теней или дел к лорду Черному Ворону.",al={"can other classes go to ravenholdt","warrior at ravenholdt manor","is ravenholdt rogues only","могут ли другие классы попасть в черный ворон","воин в поместье черного ворона","черный ворон только для разбойников"}},{q="Кто такой лорд Джорах Черный Ворон?",a="Лорд Джорах Черный Ворон — неуловимый глава Лиги убийц. Из своего горного поместья он руководит обширной сетью наставников-разбойников и осведомителей на всех континентах и посылает доверенных учеников добывать могущественные артефакты и устранять угрозы со стороны соперников.",al={"who leads ravenholdt","jorach ravenholdt","ravenholdt leader","кто возглавляет черный ворон","джорах черный ворон","глава черного ворона"}},{q="Что такое Обряд хитрости?",a="It is an introductory test for prospective disciples seeking Ravenholdt Manor. An initiate must use their ability to detect traps while passing through the mountain tunnel leading to the grounds; the danger is discovered during the rite.",al={"rite of cunning","ravenholdt rogue trial","ravenholdt tunnel test","обряд хитрости","испытание разбойника черного ворона","испытание в туннеле черного ворона"}},{q="Как Черный Ворон относится к Альянсу и Орде?",a="Черный Ворон полностью нейтрален в политике фракций и принимает умелых головорезов независимо от того, откуда они — из Оргриммара или Стальгорна. Хотя он поддерживает вежливую связь с организациями вроде ШРУ Штормграда, он отказывается быть пешкой в военных усилиях любого королевства.",al={"is ravenholdt alliance or horde","ravenholdt alignment","who does ravenholdt work for","черный ворон альянс или орда","позиция черного ворона","на кого работает черный ворон"}}},fp="10,487,17.655.0,29.572.0,31.605.1,19.312.0,36.399.0,38.271.0,30.286.0,28.237.0,52.301.0"}
P.entries["topic:razorfen"] = {n="Иглошкурые",s="Иглошкурые — собирательное название главного племени свинобразов юга Калимдора и их обширных поселений, заросших колючками. Высеченные в гигантских зарослях терний вдоль южной границы Степей и края Тысячи Игл, Иглошкурые объединяют твердыни: Лабиринты Иглошкурых и Курганы Иглошкурых. Это одновременно духовное сердце и главный оплот силы свинобразов.",h="Иглошкурые — собирательное название главного племени свинобразов юга Калимдора и их обширных поселений...",kw={"agamaggan","barrens","brambles","downs","kraul","quilboar","razorfen","thorns","агамагган","степи","заросли","курганы","лабиринты","свинобраз","иглошкурые","тернии"},ang={["class:Druid"]="Колючие заросли Иглошкурых проросли из жертвы Древнего Агамаггана; друиды с глубокой тревогой смотрят на осквернение и порчу столь священного места.",["class:Shaman"]="Геоманты Иглошкурых управляют духами земли и камня с помощью грубых обрядов стихий, и это требует внимания шаманов, стремящихся к равновесию.",["faction:Horde"]="Контроль над югом Степей важен для снабжения Орды, а агрессивные налетчики Иглошкурых постоянно досаждают караванам между Мулгором, Перекрестком и южным рубежом.",["race:Tauren"]="Свинобразы Иглошкурых из поколения в поколение яростно сражаются с охотничьими отрядами и поселениями таурен в Степях, поэтому их истребление для таурен — вопрос безопасности родной земли."},sec={{t="Тернии Агамаггана",b="Согласно легенде, гигантские колючие заросли Иглошкурых проросли десять тысяч лет назад во время Войны Древних. Когда исполинский Древний-вепрь Агамагган пал в битве с Пылающим Легионом, его кровь впиталась в землю там, где он истекал кровью и умирал. Из этой божественной жертвы выросли огромные лозы окаменевшего терновника с железными шипами, создав естественную крепость, где с тех пор живут его потомки — свинобразы."},{t="Племя Иглошкурых",b="Племя Иглошкурых — одно из самых агрессивных и укоренившихся среди всех свинобразов. Вместо того чтобы расселяться по открытым норам, они построили сложные лабиринтообразные поселения прямо в гигантских зарослях терний. Из этих крепостей племя яростно защищает свои исконные земли от соседних племен таурен, поселений Орды в Степях и любых чужаков, осмелившихся вторгнуться на их священную землю."},{t="Разделенная цитадель",b="Владения Иглошкурых разделены на два отдельных оплота. Лабиринты Иглошкурых — традиционная столица и военный лагерь свинобразов, который охраняют шаманы и охотницы. Южнее, у границы с Тысячей Игл, лежат Курганы Иглошкурых — священный родовой город и место захоронения старейшин свинобразов, ныне омраченный более глубокой некромантической порчей, угрожающей всем окрестным землям."}},faq={{q="Кто такие Иглошкурые?",a="Иглошкурые — это и известное племя свинобразов юга Степей, и их укрепленные поселения, вплетенные в громадные лабиринты терний: Лабиринты Иглошкурых и Курганы Иглошкурых.",al={"what is razorfen","razorfen meaning","razorfen lore","кто такие иглошкурые","значение иглошкурые","предания иглошкурых"}},{q="Откуда взялись гигантские тернии?",a="Тернии — окаменевшая кровь и останки дикого бога Агамаггана, Великого Вепря. Когда он пал в битве с Пылающим Легионом во время древней Войны Древних, огромные колючие побеги выросли везде, где его кровь коснулась земли.",al={"giant briars barrens","agamaggan thorns","why giant thorns","гигантские заросли степи","тернии агамаггана","почему гигантские тернии"}},{q="В чем разница между Лабиринтами Иглошкурых и Курганами Иглошкурых?",a="Лабиринты Иглошкурых — живой город и главная твердыня племени Иглошкурых, полная воинов и геомантов. Курганы Иглошкурых — родовое кладбище и священное место упокоения старейшин свинобразов, расположенное южнее, в сторону Тысячи Игл.",al={"kraul vs downs","difference between razorfen dungeons","лабиринты или курганы","разница между подземельями иглошкурых"}},{q="Почему свинобразы враждебны ко всем?",a="Свинобразы считают земли Степей и их великие заросли терний божественным правом по рождению, дарованным Агамагганом. Всех чужаков, особенно разрастающуюся Орду, они считают вороватыми захватчиками, вторгшимися на их священную землю.",al={"why do quilboar attack","quilboar lore","почему свинобразы нападают","предания свинобразов"}},{q="Где находятся Иглошкурые?",a="Огромные сплетения терний Иглошкурых лежат на дальнем юге Степей, прямо вдоль высоких утесов, спускающихся к соляным равнинам и речному каньону Тысячи Игл.",al={"razorfen map location","where is razorfen","иглошкурые на карте","где находятся иглошкурые"}},{q="Какую магию используют свинобразы Иглошкурых?",a="Традиционно свинобразы Иглошкурых практикуют магию земли и природы — геомантию, призывая силу камня и тернии. Однако недавние события в Курганах Иглошкурых указывают на тревожное проникновение темных некромантических искусств.",al={"quilboar magic","razorfen shamans","магия свинобразов","шаманы иглошкурых"}}},fp="8,403,23.461.0,18.421.0,17.412.1,17.180.0,37.239.0,65.258.0,41.229.0,26.180.0,48.224.0"}
P.entries["topic:refugee"] = {n="беженец",s="На протяжении жестокой истории Азерота непрерывные войны не раз гнали мирных жителей из их домов. От исхода из Штормграда во время Первой войны до трагического бегства из Лордерона в Третью войну беженцы остаются живым свидетельством разрушительной цены вторжений, чумы и предательства.",h="На протяжении жестокой истории Азерота непрерывные войны не раз гнали мирных жителей из их домов.",kw={"exodus","greymane wall","jaina proudmoore","lordaeron","lothar","refugee","silverpine","southshore","stormwind","исход","стена седогрива","джайна праудмур","лордерон","лотар","беженец","серебряный бор","южнобережье","штормград"},ang={["class:Priest"]="Свет велит священникам помогать обездоленным, следуя примеру верховного клирика леди Мары Фордрагон и опекунов, укрывавших раненых в разрушенных святилищах.",["faction:Alliance"]="Альянс Лордерона родился непосредственно из мольбы бездомных беженцев Штормграда, что доказывает: общее выживание и убежище — основа современного Альянса.",["race:Human"]="Почти каждая человеческая семья несет травму изгнания — будь то бегство из горящего Штормграда в Южнобережье поколение назад или спасение от кровавой работы Артаса в Лордероне.",["race:Undead"]="Многие из Отрекшихся когда-то были теми самыми беженцами из Лордерона, которые не смогли убежать от чумы и Плети, а теперь обитают в разрушенном королевстве, из которого тщетно пытались бежать."},sec={{t="Исход из Штормграда",b="Когда Орочья Орда прокатилась по королевству Штормград во время Первой войны, поселения вроде Златоземья, Луноречья и Большой деревни были сожжены. После убийства короля Ллейна Ринна сэр Андуин Лотар принял командование над остатками королевства. Он собрал уцелевших солдат и отчаявшихся мирных жителей и отвел их в гавань, пока город горел. Одни горожане прятались в катакомбах под Собором Света, а Лотар повел огромный флот через Великое море к северным берегам Лордерона. По прибытии в Южнобережье изгнанники, среди которых были юный принц Вариан Ринн и верховный клирик леди Мара Фордрагон, получили убежище от короля Теренаса Менетила II."},{t="Бегство от Плети",b="Спустя поколение после того, как Лордерон приютил изгнанников Штормграда, его собственный народ столкнулся с гибелью. Во время Третьей войны чума Плети и легионы нежити планомерно разрушали королевство. Принц Артас Менетил истреблял собственных подданных, проходя по стране, и оставлял выживших разрозненными и напуганными. Леди Джайна Праудмур сумела провести экспедицию беженцев через море в Калимдор и в итоге основала поселение Терамор. Однако бесчисленное множество людей осталось в Восточных королевствах, где их безжалостно преследовали Плеть, Отрекшиеся и чудовищные твари, появившиеся среди руин."},{t="От ворот поворот",b="Те, кто бежал от разорения Лордерона и не смог уплыть за море, отчаянно искали укрытие везде, где еще стояли стены. Многие отправились на юг к огромной Стене Седогрива, умоляя впустить их в изоляционистское королевство Гилнеас. Вместо убежища они нашли запертые ворота и вооруженное равнодушие. Оставшись нищими на границах Серебряного бора, изможденные беженцы жались в наспех устроенных лагерях. Их поддерживали лишь самоотверженные опекуны вроде Далина Искусника, а им грозили голод, набеги нежити и хищные воргены, бродящие возле Крепости Темного Клыка."}},faq={{q="Что случилось с людьми, бежавшими из Штормграда во время Первой войны?",a="Сэр Андуин Лотар вывез тысячи уцелевших на наспех собранном флоте через Великое море в северное королевство Лордерон. Они высадились в портовой деревне Южнобережье, и король Теренас Менетил II предоставил им убежище, пока Штормград не был отвоеван и отстроен заново.",al={"stormwind refugees first war","where did stormwind flee","exodus of stormwind","беженцы штормграда первая война","куда бежали жители штормграда","исход из штормграда"}},{q="Все ли жители Штормграда спаслись во время Первой войны?",a="Нет. Многие погибли на улицах, а другие прятались в обширных залах и катакомбах под Собором Света. Бесчисленные уцелевшие бесцельно бродили по дикой местности Азерота, где орочьи охотники безжалостно выслеживали и убивали их ради забавы.",al={"stormwind survivors","who stayed in stormwind","cathedral of light refugees","выжившие штормграда","кто остался в штормграде","беженцы собора света"}},{q="Куда ушли выжившие из Лордерона?",a="Многие сели на корабли леди Джайны Праудмур и поплыли на запад, в Калимдор, где в итоге заселили островной форпост Терамор. Другие рассеялись по Восточным королевствам в поисках убежища в таких местах, как Южнобережье и Внутренние земли, или тщетно молили у запертой Стены Седогрива.",al={"lordaeron refugees","where did lordaeron people go","survivors of the plague","беженцы лордерона","куда ушли жители лордерона","выжившие после чумы"}},{q="Почему Гилнеас не впустил беженцев из Лордерона?",a="Гилнеас избрал полный изоляционизм: он закрыл и запер огромную Стену Седогрива, чтобы отрезать себя от остального мира и избежать внешних войн. Когда отчаявшиеся, больные жертвы Плети подошли к воротам, их твердо прогнали, оставив без защиты в Серебряном бору.",al={"greymane wall refugees","gilneas closed gates","why did greymane lock out survivors","беженцы стена седогрива","гилнеас закрыл ворота","почему седогрив не впустил выживших"}},{q="Кто помогал беженцам, застрявшим за Стеной Седогрива?",a="Далин Искусник посвятил жизнь заботе об изможденных и больных беженцах, оказавшихся запертыми за воротами Гилнеаса: он лечил их недуги и утешал, как мог, в опасной глуши.",al={"dalin forgewright","who helped silverpine refugees","далин искусник","кто помогал беженцам серебряного бора"}},{q="Кто принял изгнанников Штормграда, когда они прибыли в Лордерон?",a="Маршал Маркус Редпат встретил измученные флоты, когда они высадились в Южнобережье. Он тотчас отправил гонца в Столицу, чтобы уведомить короля Теренаса Менетила II, который радушно приветствовал южных выживших.",al={"southshore landing","marcus redpath refugees","who greeted stormwind","высадка в южнобережье","маркус редпат беженцы","кто встретил жителей штормграда"}}},fp="7,318,23.694.0,23.639.0,23.574.1,68.287.0,53.243.0,40.282.0,54.292.0,59.208.0,61.225.0"}
P.entries["topic:riverpaw-pack"] = {n="стая Речной Лапы",s="Стая Речной Лапы — свирепый клан гноллов, обитающий в пограничных землях Элвиннского леса и Западного Края. Они известны жестокими набегами и беспощадной властью над местными кобольдами, а после Третьей войны стали более организованными и наглыми. Поскольку армия Штормграда растянута, их присутствие угрожает важным дорогам и поселениям по всему сердцу королевства.",h="Стая Речной Лапы — свирепый клан гноллов, обитающий в пограничных землях Элвиннского леса и Западного Края.",kw={"defias","dust plains","elwynn","forest's edge","gnolls","hogger","kobold slaves","riverpaw","westfall","братство справедливости","пыльные равнины","элвиннский лес","лесная опушка","гноллы","дробитель","рабы кобольды","речная лапа","западный край"},ang={["class:Rogue"]="Перехват посланников Речной Лапы показывает, что их дикое насилие направляют преступные синдикаты, и дает ценные сведения о сети Братства Справедливости.",["class:Warrior"]="Городские маршалы хорошо платят монетой и престижем воинам, готовым углубиться в заросли, чтобы сократить число громил Речной Лапы и сразиться с их военачальниками вроде Дробителя.",["faction:Alliance"]="Речные Лапы представляют собой непосредственный кризис безопасности для сердца Альянса: они перерезают торговые пути между Златоземьем, Западным Краем и Красногорьем, пока армии Штормграда отсутствуют.",["race:Human"]="Для фермеров и поселенцев Западного Края и Элвиннского леса Речные Лапы — кошмар на пороге: они убивают семьи, крадут скот и захватывают местные копи."},sec={{t="Бедствие в сердце королевства",b="Десятилетиями клан Речной Лапы бродил на окраинах человеческой цивилизации, но в последние годы его дерзость резко выросла. В Элвиннском лесе стаи под предводительством печально известного громилы Дробителя рыщут в южных лесах вокруг Лесной опушки и бродят по берегам Озера Каменных Столбов. В Западном Крае они бродят по Пыльным равнинам и вдоль побережья, устраивая засады на одиноких путников и грабя усадьбы. Заместитель судьи Рейнер в Гарнизоне у Западного ручья и капитан Данувин в Сторожевом холме во многом полагаются на клинки наемников, чтобы сократить их число, и постоянно назначают награды за раскрашенные повязки и отрубленные лапы."},{t="Беспощадные надсмотрщики",b="Помимо мелких засад, Речные Лапы проявляют необычную тягу к завоеваниям и принудительному труду. Они изгнали клан кобольдов из Красногорья и загнали их в золотые копи Элвиннского леса и Западного Края, где изматывают маленьких существ непрерывной работой по добыче руды. Эта жестокая тирания над копями говорит о том, что гноллы уже не простые падальщики, живущие впроголодь, а сила, копящая богатство и закрепляющая стратегические земли прямо под носом у короны."},{t="Тени и золото",b="Внезапный рост дисциплины, вооружения и магии у стаи Речной Лапы не случаен. Найденные бухгалтерские книги и документы указывают, что гноллы ведут финансовые сделки с Братством Справедливости. Хотя Армия Штормграда сначала отмахивалась от стаи как от звериной напасти, такие чиновники, как Вилли Черный и капитан Данувин, поняли, что Речные Лапы финансируются и направляются в рамках скоординированных усилий по подрыву королевства."}},faq={{q="Кто возглавляет гноллов Речной Лапы?",a="Самый известный предводитель стаи Речной Лапы — Дробитель, огромный и свирепый гнолл, который бродит по юго-западным чащам Элвиннского леса возле Лесной опушки. Власти Штормграда считают его серьезной угрозой и назначили большую награду за его голову.",al={"riverpaw leader","who leads the riverpaw","hogger riverpaw","вожак речной лапы","кто возглавляет речную лапу","дробитель речная лапа"}},{q="Где обитают гноллы Речной Лапы?",a="Стая Речной Лапы в основном заполонила юго-запад Элвиннского леса вокруг Лесной опушки и Озера Каменных Столбов, а также открытые просторы Западного Края, особенно Пыльные равнины и побережье.",al={"riverpaw locations","where to find riverpaws","riverpaw gnoll spawn","места речной лапы","где найти речную лапу","гноллы речной лапы"}},{q="Почему гноллы Речной Лапы работают с Братством Справедливости?",a="Документы, найденные у разведчиков Речной Лапы, показывают, что между кланом и Братством Справедливости идут платежи. Братство Справедливости финансирует и снаряжает Речных Лап, чтобы сеять хаос, грабить ресурсы и сковывать местное ополчение по всему Западному Краю и Элвиннскому лесу, ослабляя оборону Штормграда.",al={"riverpaw defias connection","defias paying gnolls","gnoll brotherhood connection","речная лапа братство справедливости","братство платит гноллам","связь гноллов с братством"}},{q="Почему кобольды работают в золотых копях рядом с Речной Лапой?",a="Гноллы Речной Лапы покорили клан кобольдов из Красногорья и поработили его, заставив трудиться в копях Элвиннского леса и Западного Края. Гноллы служат беспощадными надсмотрщиками и принуждают кобольдов добывать драгоценное золото для своих военных нужд.",al={"gnolls and kobolds","why do gnolls have kobold slaves","riverpaw kobolds","гноллы и кобольды","почему у гноллов рабы кобольды","кобольды речной лапы"}},{q="Почему Армия Штормграда не уничтожила стаю Речной Лапы?",a="Официальная армия королевства крайне перегружена, и в сельские гарнизоны вроде Сторожевого холма и Гарнизона у Западного ручья почти не присылают подкреплений. Местным маршалам приходится полагаться на проезжих искателей приключений и награды ополчения, чтобы популяция гноллов не захлестнула территорию полностью.",al={"why aren't guards fighting gnolls","stormwind gnoll response","почему стража не борется с гноллами","ответ штормграда на гноллов"}},{q="Каковы исторические отношения между Речными Лапами и Штормградом?",a="Речные Лапы сталкивались со Штормградом на протяжении поколений. За годы до Первой войны стая под предводительством матриарха Синешкуры дерзко попыталась похитить принца Ллейна Ринна, закрепив за собой репутацию наглой и неотступной угрозы королевству.",al={"riverpaw history","prince llane gnolls","matriarch bluepelt","история речной лапы","принц ллейн гноллы","матриарх синешкурая"}}},fp="13,370,25.579.0,21.485.0,16.473.1,30.258.0,32.212.0,64.283.1,60.250.0,58.281.0,72.246.0"}
P.entries["topic:rogue"] = {n="Разбойник",s="Разбойники — мастера скрытности, шпионажа и внезапного смертельного боя, которые диктуют условия схватки из тени. Облаченные в легкие кожаные доспехи, вооруженные парными клинками и приготовленными ядами, они наносят удар неожиданно и снова растворяются во тьме. По всему Азероту они служат разведчиками, убийцами, карманниками и агентами как фракций, так и тайных синдикатов.",h="Разбойники — мастера скрытности, шпионажа и внезапного смертельного боя, которые диктуют условия схватки из...",kw={"assassin","deathstalker","eviscerate","lockpicking","poisons","ravenholdt","rogue","shattered hand","si:7","stealth","убийца","страж смерти","потрошение","взлом замков","яды","черный ворон","разбойник","изувеченная длань","шру","скрытность"},ang={["class:Rogue"]="Для разбойника каждое задание — упражнение в расчете, терпении и смертельной точности, будь он агентом верховного командования или карманником в городских переулках.",["faction:Alliance"]="Тайная сила Альянса проходит через такие организации, как ШРУ Штормграда и Тайный круг Стальгорна, которые борются с внутренней подрывной деятельностью и внешними угрозами.",["faction:Horde"]="Орда полагается на шпионаж Изувеченной Длани в Оргриммаре и грозных Стражей смерти Сильваны Ветрокрылой в Подгороде, которые разведывают вражеские земли и тихо устраняют угрозы."},sec={{t="Удар из тени",b="Разбойники отвергают тяжелые латы и открытое столкновение, привычные воинам переднего края. Одетые в легкую кожу, чтобы оставаться совершенно бесшумными и подвижными, они выслеживают добычу незамеченными. Вступая в бой, они используют первые мгновения — точность и внезапность — и целятся в жизненно важные органы или незащищенные суставы. Благодаря постоянно восполняющейся энергии и быстрым сочетаниям приемов разбойник изматывает врага тщательно выстроенной чередой ударов, а затем обрушивает на него сокрушительный завершающий удар."},{t="Яды и уличная смекалка",b="Одного клинка редко хватает профессиональному вору или убийце. Разбойники — умелые алхимики смертоносных составов: они своими руками изготавливают ядовитые покрытия, которые парализуют конечности, замедляют бегство или быстро истощают силы цели. Вместе с отмычками, метательным оружием и отвлекающими уловками это позволяет им проскальзывать через укрепленные рубежи, обезвреживать ловушки и проникать в хранилища, перед которыми спасовал бы целый отряд солдат."},{t="Гильдии, короны и синдикаты",b="Хотя многие разбойники действуют в одиночку, как грабители с большой дороги или уличные головорезы, лучшие из них состоят в организованных разведывательных сетях и гильдиях убийц. Штормград полагается на тайных агентов ШРУ, Стальгорн укрывает скрытный Тайный круг, а Отрекшиеся используют неумолимых Стражей смерти. В Оргриммаре призрачные остатки Изувеченной Длани служат Вождю, а элитная нейтральная Лига убийц подчиняется лорду Джораху Черному Ворону."}},faq={{q="Какие доспехи и оружие используют разбойники?",a="Разбойники носят кожаные доспехи, чтобы двигаться бесшумно и быстро, не чувствуя стеснения. В бою они сражаются парным одноручным оружием, прежде всего кинжалами, мечами, булавами и кистевым оружием. Они также носят бесшумное оружие дальнего боя — метательные ножи, луки или арбалеты — для вспомогательных целей и для приманивания противников.",al={"rogue gear","what can rogues equip","rogue armor type","снаряжение разбойника","что могут надевать разбойники","тип доспехов разбойника"}},{q="Как работает скрытность у разбойника?",a="Скрытность — это дисциплинированное сочетание легкой поступи, использования теней и тонкого мистицизма. Она делает разбойника практически невидимым для далеких наблюдателей, хотя слишком близкое приближение к бдительному стражнику или врагу может выдать его присутствие. Войдя в скрытность, разбойники могут занять позицию позади добычи и нанести сокрушительные удары из засады, удушающие и выводящие из строя приемы.",al={"how does rogue stealth work","can rogues turn invisible","stealth lore","как работает скрытность разбойника","могут ли разбойники становиться невидимыми","предания о скрытности"}},{q="Что такое Лига Черного Ворона?",a="Лига убийц со штаб-квартирой в Поместье Черного Ворона в Альтеракских горах — древнее тайное братство, которым руководит лорд Джорах Черный Ворон. В отличие от разведывательных служб, привязанных к фракциям, Черный Ворон — гильдия, всецело посвященная дисциплине, чести и делу ремесла убийц; она берет заказы независимо от политических пристрастий.",al={"who are ravenholdt","assassins league","lord jorach ravenholdt","кто такие черный ворон","лига убийц","лорд джорах черный ворон"}},{q="Что такое ШРУ?",a="ШРУ — главное тайное разведывательное подразделение Королевства Штормград. Со штаб-квартирой в Штормграде, его полевые агенты, снайперы и воры занимаются шпионажем, громкими убийствами и разведкой на границах, защищая интересы Альянса по всему Азероту.",al={"stormwind si7","si7","stormwind intelligence","шру штормград","шру","разведка штормграда"}},{q="Как разбойники сражаются в затяжном бою?",a="Когда убийство не удается завершить первым ударом, разбойник использует ловкость и работу ног, чтобы уклоняться от ответных ударов. Он быстро наносит серии атак парным оружием, используя слабости противника, и создает тактические бреши, которые завершаются смертельными добивающими приемами, такими как «Рваная рана» или «Потрошение».",al={"rogue combat style","combo points lore","how do rogues fight","стиль боя разбойника","приемы с очками серии","как сражаются разбойники"}},{q="Используют ли разбойники магию?",a="Большинство разбойников полагаются прежде всего на физическую подготовку, боевое обучение, алхимические составы и обычную скрытность. Однако опытные мастера часто вплетают в свой арсенал толику мистицизма или магии тени, что помогает им скрывать облик, растворяться в тенях средь бела дня и мгновенно исчезать из виду.",al={"is rogue stealth magic","do rogues cast spells","магия ли скрытность разбойника","колдуют ли разбойники"}}},fp="5,366,23.491.0,25.434.0,30.473.0,37.308.0,34.363.0,30.351.0,13.283.0,40.307.0,20.326.0"}
P.entries["topic:royal-apothecary-society"] = {n="Королевское фармацевтическое общество",s="Королевское фармацевтическое общество — алхимическая гильдия, основанная при леди Сильване Ветрокрылой и расположенная в Апотекариуме под Подгородом. Оно состоит из исследователей-Отрекшихся, и его главная задача — создание смертоносной Новой чумы, способной истребить Плеть и отомстить живым. Хотя союзники из Орды верят, что общество ищет средство от нежизни, его исследователи по всему Азероту деятельно собирают яды, слизь и токсичные реагенты, чтобы довести до совершенства оружие массового уничтожения.",h="Королевское фармацевтическое общество — алхимическая гильдия, основанная при леди Сильване Ветрокрылой и...",kw={"alchemy","apothecarium","faranell","helbrim","lydon","new plague","royal apothecary society","sylvanas windrunner","undercity","zamah","алхимия","апотекариум","фаранелл","хелбрим","лидон","новая чума","королевское фармацевтическое общество","сильвана ветрокрылая","подгород","зама"},ang={["faction:Horde"]="Представители Отрекшихся утверждают, что их алхимические труды ищут противоядие, способное исцелить их проклятое состояние, хотя в уединенных котлах Апотекариума веет куда более смертоносными замыслами.",["profession:Herbalism"]="Общество придает огромное значение смертоносным растениям: ядовитые грибы, удавник и могильный мох собираются по всему Азероту, чтобы питать его губительные котлы.",["race:Tauren"]="Из жалости к проклятым мертвецам старейшины позволили аптекарю Заме войти в Пруды Видений, полагая, что Отрекшиеся искренне ищут очищающее средство от своего недуга.",["race:Undead"]="Общество воплощает научное могущество вашего народа, превращая ту самую чуму, что погубила Лордерон, в орудие мести Плети и всем, кто противостоит вам."},sec={{t="Месть через алхимию",b="Королевское фармацевтическое общество, основанное после освобождения Отрекшихся, служит научным и алхимическим крылом королевства леди Сильваны Ветрокрылой. В чанах и подземных лабораториях Апотекариума исследователи стремятся превратить в оружие ту самую силу, что их прокляла. Их главное начинание — создание «Новой чумы», состава, призванного истребить Плеть и уничтожить Короля-лича. В отличие от традиционной человеческой алхимии, где важнее эликсиры исцеления и трансмутации, Общество беспощадно экспериментирует с омерзительными возбудителями, едкими кислотами и некромантическими смесями: оно поднимает павших боевых коней как скелетных скакунов и варит все более смертоносные штаммы ядовитой порчи."},{t="Расчетливый обман",b="Внешнему миру Общество представляется непонятыми учеными. В общении с союзниками в Оргриммаре и Громовом Утесе представители Отрекшихся дают понять, что их алхимики неустанно трудятся над поиском лекарства от проклятия нежизни. На деле же исцеление недуга почти не интересует Мастера аптекаря Фаранелла и темный совет. Общество в полной тайне совершенствует токсины, не щадящие никого, и тайно проверяет их действие как на живых, так и на мертвых подопытных, чтобы обеспечить полное уничтожение врагов."},{t="Аванпосты по всему Азероту",b="Влияние Общества простирается далеко за пределы каналов Подгорода. Полевые аптекари направляются на отдаленные аванпосты по всему Лордерону и Калимдору. В Серебряном бору и Хилсбраде такие агенты, как аптекари Ренферрел и Лидон, собирают местную флору и перегоняют яды. В засушливых Степях аптекарь Хелбрим описывает странные пустынные растения и существ, а аптекарь Зама работает под Громовым Утесом в Прудах Видений. Везде, где есть природные токсины, переменчивая слизь или смертоносные организмы, Общество посылает служителей собирать образцы для котлов Апотекариума."}},faq={{q="Что такое Королевское фармацевтическое общество?",a="Королевское фармацевтическое общество — алхимическая организация Отрекшихся со штаб-квартирой в Апотекариуме в Подгороде. Созданное при королеве Сильване Ветрокрылой, оно изучает смертоносные возбудители, некромантию и токсичные реагенты, чтобы создавать химическое оружие для Отрекшихся.",al={"what is the ras","who are the apothecaries","forsaken alchemy guild","что такое кфо","кто такие аптекари","алхимическая гильдия отрекшихся"}},{q="Что за Новая чума, над которой они работают?",a="Новая чума — особый алхимический возбудитель, созданный Обществом по прямому приказу Сильваны. Ее конечная цель — обрести силу, способную истребить Плеть и Короля-лича, оставаясь смертоносной и для живых существ, которые угрожают Отрекшимся.",al={"new plague explained","what is the forsaken plague","why make a new plague","новая чума","чума отрекшихся","зачем создавать новую чуму"}},{q="Знает ли Орда, что на самом деле варит Общество?",a="No. The Forsaken maintain the facade that their research focuses on curing the affliction of undeath and finding a peaceful place for their kind. The Tauren and Orcs believe the apothecaries seek a medical remedy, unaware that the Society is engineering a lethal weapon of eradication.",al={"does thrall know about the plague","horde stance on apothecaries","do orcs know about the plague","знает ли тралл о чуме","отношение орды к аптекарям","знают ли орки о чуме"}},{q="Кто возглавляет Королевское фармацевтическое общество?",a="Хотя Общество в конечном счете подчиняется королеве Сильване Ветрокрылой, повседневной научной работой и исследованиями в Подгороде руководят старшие надзиратели, такие как Мастер аптекарь Фаранелл.",al={"leader of the apothecaries","ras leader","who runs the apothecarium","глава аптекарей","лидер кфо","кто управляет апотекариумом"}},{q="Почему аптекари размещены в таких местах, как Степи или Громовой Утес?",a="Полевые аптекари ищут редкие биологические агенты, экзотические яды, грибы и мутагенную слизь, которых нет в Лордероне. Такие агенты, как Хелбрим на Перекрестке и Зама в Громовом Утесе, изучают местную экологию и собирают опасные образцы, чтобы отправить их в лаборатории Подгорода.",al={"why are apothecaries in kalimdor","apothecaries outside tirisfal","apothecary zamah pools of vision","почему аптекари в калимдоре","аптекари вне тирисфаля","аптекарь зама пруды видений"}},{q="Как Общество создает скакунов Отрекшихся?",a="Вместо того чтобы позволить павшим боевым коням гнить, Королевское фармацевтическое общество сочетает темную алхимию и некромантию, чтобы оживлять погибших скакунов, поднимая их как скелетных ездовых животных, служащих всадникам Отрекшихся в бою.",al={"where do undead horses come from","forsaken mount lore","skeletal horse origin","откуда берутся лошади-нежить","ездовые отрекшихся","происхождение скелетной лошади"}}},fp="24,504,25.701.0,22.553.1,23.594.0,37.278.0,43.267.0,55.285.0,39.198.0,75.284.0,44.207.0"}
P.entries["topic:ruins-of-gilneas"] = {n="Руины Гилнеаса",s="Гилнеас — уединенное человеческое королевство на суровом, истрепанном штормами полуострове к югу от Серебряного бора. После Второй войны король Генн Седогрив разорвал связи с внешним миром и запер свою страну за огромной Стеной Седогрива, оставив соседние земли без защиты, а королевство погрузилось в полную изоляцию.",h="Гилнеас — уединенное человеческое королевство на суровом, истрепанном штормами полуострове к югу от...",kw={"ambermill","arugal","darius crowley","genn","gilneas","greymane","greymane wall","pyrewood","silverpine","worgen","янтарная мельница","аругал","дариус кроули","генн","гилнеас","седогрив","стена седогрива","погребальные костры","серебряный бор","воргены"},ang={["class:Mage"]="Трагическая история призыва верховного мага Аругала у Стены Седогрива — мрачное предостережение о том, что бывает, когда магию обращают в оружие без должной сдержанности.",["race:Human"]="Для людей Лордерона и Штормграда Гилнеас — горькое напоминание о том, как гордыня и изоляционизм разрушили единство Семи королевств перед Третьей войной.",["race:Undead"]="Отряды Отрекшихся, патрулирующие юг Серебряного бора, настороженно следят за огромными воротами, зная, что прямо у их границы нетронутым и враждебным стоит целое живое человеческое королевство."},sec={{t="Отгородившаяся страна",b="Гилнеас некогда был напористой морской державой среди человеческих королевств и вел свой род от древней Араторской империи. Король Генн Седогрив неохотно участвовал во Второй войне, полагая, что его королевство способно защитить себя без чужих союзов. Озлобленный потерями среди жителей Гилнеаса и не желая оплачивать лагеря для интернированных пленных орков, Седогрив порвал отношения с Альянсом Лордерона. Чтобы навсегда оградить свои земли от бед извне, он приказал возвести огромную каменную преграду вдоль северной границы королевства."},{t="Отрезанная граница",b="Возведение Стены Седогрива потребовало болезненных геополитических уступок. Естественные горные проходы, на которых держались укрепления, рассекли владения лорда Дариуса Кроули. В результате такие земли, как Янтарная мельница и Деревня Погребальных Костров, оказались отрезаны на северной стороне, за воротами. Когда во время Третьей войны Плеть захлестнула Лордерон, король Седогрив отверг просьбы о помощи и закрыл двери перед беженцами-людьми, оставив окрестные деревни один на один с чумой и нежитью."},{t="Надвигающаяся тень",b="Тьма сгущалась сразу за стеной. Во время Третьей войны верховный маг Даларана Аругал призвал диких воргенов, чтобы усилить Кирин-Тор в борьбе с Плетью. Звери перебили нежить, затем обратились против самих магов, осадили крепость барона Сребролена и разошлись по теням Серебряного бора. Сегодня Гилнеас остается за запертыми воротами и коварными морскими рифами — неприступная загадка, окутанная жуткими слухами и полным безмолвием."}},faq={{q="Могут ли игроки попасть в Гилнеас?",a="Нет. Королевство целиком лежит за Стеной Седогрива на южной границе Серебряного бора. Огромные железные ворота остаются наглухо закрытыми, а побережье полуострова защищено отвесными морскими утесами и коварными рифами, поэтому попасть туда невозможно.",al={"can you go past greymane wall","is gilneas open","get into gilneas","можно ли пройти за стену седогрива","открыт ли гилнеас","попасть в гилнеас"}},{q="Почему была построена Стена Седогрива?",a="Король Генн Седогрив считал Гилнеас самодостаточным и возмущался тратой ресурсов и солдат на помощь другим человеческим народам. Измученный долгами, лагерями для интернированных и чужими конфликтами после Второй войны, он возвел стену, чтобы навсегда отделить Гилнеас от остального Лордерона.",al={"why did gilneas isolate","greymane wall purpose","why closed off","почему гилнеас изолировался","зачем стена седогрива","почему закрыт"}},{q="Что случилось с Деревней Погребальных Костров и Янтарной мельницей?",a="Оба поселения входили во владения лорда Дариуса Кроули. Поскольку Стена Седогрива была построена по самым защищенным горным хребтам, Погребальные Костры и Янтарная мельница оказались снаружи, на севере, отрезанные от королевства, когда ворота закрылись.",al={"why is pyrewood outside wall","ambermill gilneas connection","crowley lands","почему погребальные костры за стеной","янтарная мельница и гилнеас","земли кроули"}},{q="Входит ли Гилнеас в Альянс?",a="Сейчас нет. Генн Седогрив официально вышел из Альянса Лордерона много лет назад. Гилнеас не поддерживает ни дипломатических отношений, ни военных договоров, ни торговли со Штормградом, Стальгорном или любой другой державой Альянса.",al={"gilneas faction","are gilneans in the alliance","gilneas alliance","фракция гилнеаса","жители гилнеаса в альянсе","гилнеас альянс"}},{q="Какая связь у Аругала с Гилнеасом?",a="Трагедия Аругала разыгралась сразу за Стеной Седогрива. Во время Третьей войны верховный маг Даларана призвал диких воргенов, чтобы усилить Кирин-Тор в борьбе с Плетью. Существа перебили нежить, но затем обратились против магов, захватили Крепость Темного Клыка и расселились по Серебряному бору, сведя Аругала с ума.",al={"arugal gilneas","how did arugal get worgen","аругал гилнеас","как аругал призвал воргенов"}},{q="Кто правит Гилнеасом?",a="Гилнеасом правит король Генн Седогрив, непреклонный монарх, яростно защищавший независимость своей страны ценой отказа от мира за пределами его ворот.",al={"gilneas leader","king of gilneas","правитель гилнеаса","король гилнеаса"}}},fp="16,331,18.580.0,20.535.0,16.454.1,26.270.0,32.299.0,48.267.0,32.215.0,44.315.0,18.168.0"}
P.entries["topic:sargeras"] = {n="Саргерас",s="Саргерас — падший титан и верховный создатель Пылающего Легиона, стремящийся стереть всю жизнь во вселенной. Некогда благородный защитник и воитель Пантеона, он впал в безумие, что привело к Великому Расколу древнего Азерота и почти ко всем демоническим бедствиям с тех пор.",h="Саргерас — падший титан и верховный создатель Пылающего Легиона, стремящийся стереть всю жизнь во вселенной.",kw={"aggramar","azshara","burning legion","dark titan","fel","mardum","pantheon","sargeras","sundering","агграмар","азшара","пылающий легион","темный титан","скверна","мардум","пантеон","саргерас","раскол"},ang={["class:Mage"]="Маги помнят Саргераса как предостерегающий ужас: он доказывает, что безудержное стремление к тайной магии неизбежно привлечет взгляд Пылающего Легиона из-за звезд.",["class:Warlock"]="Чернокнижники черпают те самые силы Скверны и демонов-слуг, что были объединены Темным Титаном, и владеют губительным колдовством, создавшим Легион.",["race:NightElf"]="Для кальдораев Саргерас — главный зодчий Великого Раскола, чьи соблазнительные шепоты развратили королеву Азшару и разрушили древний Калимдор десять тысячелетий назад.",["race:Orc"]="Трагическая история орочьих кланов — проклятие крови, безумие и вторжение в Азерот — напрямую восходит к козням Саргераса и его демонических приспешников."},sec={{t="Защитник Пантеона",b="До падения Саргерас был величайшим и благороднейшим воином среди титанов. Пантеон Порядка поручил ему охранять свои великие творения в Великой Темной Бездне, и он вел войну против хаотичных демонов, порожденных Круговертью Пустоты. Не способный помыслить о чистом зле, Саргерас заточил бесчисленных исчадий в тюремном мире Мардум. Но эпохи непрестанной войны с космическими ужасами постепенно подточили его бескорыстный дух."},{t="Отчаяние и Пылающий крестовый поход",b="Странствуя по космосу, Саргерас встретил мир, полностью оскверненный чудовищными Древними богами, и узнал о темных силах, таящихся в Пустоте. Ужаснувшись тому, что спящая душа мира титанов может полностью пасть во тьму, он решил, что творение изначально порочно. Полагая, что безжизненная вселенная лучше поглощенной Пустотой, он разрушил Мардум, окунулся в хаотичный огонь Скверны и собрал освобожденных демонов в неудержимый Пылающий Легион."},{t="Одержимость Азеротом",b="Десять тысяч лет назад безрассудная магия королевы Азшары и ее высокорожденных достигла звезд и сообщила Саргерасу о существовании Азерота. Нашептывая из глубин Источника Вечности, Темный Титан соблазнил Азшару открыть портал для его авангарда. Хотя то древнее вторжение завершилось катастрофическим Расколом, Саргерас никогда не прекращал замышлять поглощение Азерота — он подстроил открытие Темного портала и направлял демоническое развращение орков Орды."}},faq={{q="Кто такой Саргерас?",a="Саргерас — падший титан, некогда величайший воин Пантеона. Доведенный отчаянием из-за космической порчи, он предал свой род и создал Пылающий Легион, чтобы стереть всю жизнь во вселенной.",al={"sargeras backstory","who is the dark titan","creator of the burning legion","история саргераса","кто такой темный титан","создатель пылающего легиона"}},{q="Почему Саргерас хочет уничтожить вселенную?",a="Он узнал, что космические существа, известные как Владыки Пустоты, послали Древних богов заражать спящие души миров титанов. Опасаясь рождения неудержимого, оскверненного темного титана, он решил уничтожить все творение, лишь бы оно не досталось тьме.",al={"sargeras motive","why burning crusade","why does sargeras want to destroy everything","мотив саргераса","почему пылающий крестовый поход","зачем саргерас хочет все уничтожить"}},{q="Как Саргерас связан с королевой Азшарой?",a="Десять тысяч лет назад безрассудное использование королевой Азшарой Источника Вечности привлекло внимание Саргераса. Считая его богом, Азшара и ее высокорожденные попытались призвать Темного Титана через Источник, вызвав разрушительную Войну Древних и Великий Раскол.",al={"sargeras and azshara","well of eternity sargeras","ancient invasion azshara","саргерас и азшара","источник вечности саргерас","древнее вторжение азшара"}},{q="Создал ли Саргерас демонов?",a="Нет. Демоны изначально возникли естественным путем в хаотичной Круговерти Пустоты. Саргерас сражался с ними и держал их в плену веками, а затем решил разрушить их тюремный мир Мардум, объединив демонические расы под своим началом и создав Пылающий Легион.",al={"did sargeras make demons","where did the burning legion come from","создал ли саргерас демонов","откуда взялся пылающий легион"}},{q="Что случилось с другими титанами?",a="Когда Пантеон встретился с Саргерасом в Нихиламе, чтобы убедить его прекратить Пылающий крестовый поход, тот отказался повернуть назад. В последовавшей схватке падший титан одолел Пантеон хаотичной силой Скверны и уничтожил их физические тела.",al={"where are the other titans","pantheon fate","did sargeras kill the pantheon","где другие титаны","судьба пантеона","убил ли саргерас пантеон"}},{q="Как Саргерас был связан с открытием Темного портала?",a="Спустя долгое время после Раскола Саргерас продолжал вынашивать планы относительно Азерота издалека, подстраивая события, чтобы развратить орков Дренора, и используя Хранителя Медива, чтобы открыть Темный портал и вновь принести вторжение на смертные земли.",al={"sargeras orcs","sargeras dark portal","did sargeras bring orcs","саргерас орки","саргерас темный портал","привел ли саргерас орков"}}},fp="8,277,24.460.0,31.502.0,22.495.0,16.208.0,47.250.0,47.276.0,31.249.0,34.243.0,61.237.0"}
P.entries["topic:satyr"] = {n="сатир",s="Сатиры — искаженные козлоподобные демоны, рожденные из проклятия высокорожденного чародея Ксавиуса во время древней Войны Древних. Некогда они были ночными эльфами, но Саргерас превратил их в рогатых копытных чудовищ, призванных распространять скверну Скверны, мучить своих бывших сородичей и исполнять волю Пылающего Легиона. По диким землям Калимдора разбросаны секты сатиров: они оскверняют нетронутые леса, поганят лунные колодцы и подчиняют себе уязвимые культы смертных.",h="Сатиры — искаженные козлоподобные демоны, рожденные из проклятия высокорожденного чародея Ксавиуса во время...",kw={"corrupter","demon","fel","highborne","jadefire","sargeron","satyr","satyrnaar","xavian","xavius","осквернитель","демон","скверна","высокорожденные","нефритовое пламя","саргерон","сатир","сатирнаар","ксавиан","ксавиус"},ang={["class:Druid"]="Сатиры активно отравляют дикие земли, искажают фурболгов и оскверняют священные рощи, поэтому их уничтожение — насущная задача для Круга Кенария.",["class:Warlock"]="Будучи существами чистой энергии скверны и демонической злобы, сатиры демонстрируют губительное мастерство древних проклятий Пылающего Легиона.",["faction:Alliance"]="Часовые и искатели приключений Альянса постоянно сражаются, чтобы выжечь лагеря сатиров, подступающие к поселениям ночных эльфов в Ясеневом лесу и на Темных берегах.",["faction:Horde"]="Орда яростно сражается с сектами сатиров в Ясеневом лесу и Пустошах, искореняя их тайные союзы с Пылающим Клинком.",["race:NightElf"]="Сатиры воплощают предельное предательство наследия кальдораев и служат горьким напоминанием о высокомерии высокорожденных во время Войны Древних."},sec={{t="Истоки проклятия",b="Десять тысяч лет назад, во время Войны Древних, советник из высокорожденных Ксавиус не сумел удержать первые врата Пылающего Легиона от натиска Малфуриона Ярость Бури. Разгневанный этой ошибкой, Саргерас разорвал дух Ксавиуса и собрал его заново — как наказание и как орудие: торс сохранил эльфийские черты, но появились зловещие рога, когтистые лапы, львиный хвост и раздвоенное копытное тело козла. Отправленный обратно в Зин-Азшари, Ксавиус с радостью передал свой недуг скверны другим жадным до власти высокорожденным. Хотя Ксавиус был повержен, его демонические отпрыски выжили и постоянно стремились размножаться, развращая других."},{t="Война сатиров",b="После Великого Раскола уцелевшие демоны и сатиры перегруппировались и развязали Войну сатиров против разрушенной цивилизации ночных эльфов. Стремясь противостоять жестокой демонической магии сатиров, друиды-ночные эльфы выпустили на волю неукротимый облик стаи и случайно породили первых диких воргенов. Воргены прорвались сквозь полчища сатиров и разгромили их единую армию. Лишившись общего руководства, уцелевшие распались на разрозненные секты, которые обосновались в темных лесах и древних руинах, затаив глубокую ненависть к своим сородичам-кальдораям."},{t="Осквернители Калимдора",b="Ныне кланы сатиров населяют глухие лесные укрытия по всему Калимдору — от Темных берегов и Ясеневого леса до Оскверненного леса, Азшары и Фераласа. Они напрямую питаются чистой магией земли, высасывая и портя природу, пока их копыта не раздуются от поглощенной тайной энергии. Сатиры часто обращают мирные племена фурболгов к насилию, оскверняют древние лунные колодцы и служат тайными посредниками Совета Теней и Пылающего Клинка. Одни действуют вместе с культистами Сумеречного Молота, другие прячутся в древних руинах вроде Забытого Города, но все они остаются во власти тени Пылающего Легиона."}},faq={{q="Кто такие сатиры?",a="Сатир — демон, в которого ночной эльф превратился под действием древнего проклятия скверны. У него раздвоенные копыта, рога, острые когти и хвост; он сохраняет эльфийский торс, владея темным колдовством скверны и звериной жестокостью.",al={"what are satyrs","satyr race","satyr lore","кто такие сатиры","раса сатиров","предания о сатирах"}},{q="Кто был первым сатиром?",a="Первым сатиром стал лорд Ксавиус, чародей из высокорожденных и главный советник королевы Азшары. После того как Ксавиус не сумел защитить портал Пылающего Легиона во время Войны Древних, Саргерас переделал его тело в демоническое, рогатое — как наказание и как мрачный дар.",al={"first satyr","who created satyrs","xavius satyr","первый сатир","кто создал сатиров","ксавиус сатир"}},{q="Могут ли сатиры создавать новых сатиров?",a="Да. Существующие сатиры могут наложить свое преображающее проклятие на других существ, в первую очередь на ночных эльфов, однако за тысячелетия магия ослабла, и удачные превращения сегодня гораздо реже. Разрозненные культисты порой почитают Ксавиуса в надежде заслужить превращение.",al={"how are satyrs made","satyr curse spread","becoming a satyr","как появляются сатиры","распространение проклятия сатиров","стать сатиром"}},{q="Бывают ли сатиры-женщины?",a="Да, самки сатиров существуют, хотя посторонние ученые редко их видят и различают. Известный пример — падшая жрица Дриана, эльфийская жрица, поддавшаяся демоническому недугу.",al={"female satyrs","are all satyrs male","girl satyr","самки сатиров","все ли сатиры мужчины","девушка сатир"}},{q="Почему сатиры нападают на лунные колодцы и леса?",a="Сатиры питаются чистотой и природной тайной магией, высасывая ее прямо из нетронутых земель и лунных колодцев ночных эльфов. Украденную энергию они накапливают в копытах, которые распухают и перестают быть раздвоенными, когда впитывают огромную магическую силу.",al={"why do satyrs corrupt moonwells","satyr hooves lore","satyr magic","почему сатиры оскверняют лунные колодцы","копыта сатиров","магия сатиров"}},{q="Где сейчас можно встретить сатиров?",a="Сатиры рассеяны по разоренным и оскверненным землям Калимдора, включая Сатирнаар и Ксавиан в Ясеневом лесу, Башал'Аран в Темных берегах, Холм Нефритового Пламени в Оскверненном лесу, Саргерон в Пустошах, лагеря Халдарр и Легаш в Азшаре и Забытый Город в Фераласе.",al={"satyr locations","where do satyrs live","satyr zones","места обитания сатиров","где живут сатиры","зоны сатиров"}}},fp="5,449,20.638.0,20.555.0,22.564.0,24.217.0,24.271.0,27.281.0,24.199.0,43.232.0,33.267.0"}
P.entries["topic:scarlet-crusade"] = {n="Алый орден",s="Алый орден, возникший из разрозненных остатков Рыцарей Серебряной Длани, — фанатичный священный орден, одержимый идеей истребить нежить в Лордероне. Одержимые паранойей и радикальным фанатизмом, его члены считают переносчиками чумы всех, кто не входит в их ряды, и расстреливают чужаков на месте. Из крепостей по всем Тирисфальским лесам и Чумным землям багровые знамена ордена ведут беспощадную войну как против Плети, так и против живых.",h="Алый орден, возникший из разрозненных остатков Рыцарей Серебряной Длани, — фанатичный священный орден...",kw={"argent dawn","ashbringer","hearthglen","saidan dathrohan","sally whitemane","scarlet crusade","scarlet monastery","silver hand","tyr's hand","серебряный рассвет","пепелитель","дольный очаг","сайдан датрохан","салли вайтмейн","алый орден","монастырь алого ордена","серебряная длань","длань тира"},ang={["class:Paladin"]="Алый орден — самое мрачное извращение учения Серебряной Длани: он показывает, как праведная убежденность без смирения и сострадания может выродиться в тиранический фанатизм.",["class:Priest"]="Изучение ордена открывает пугающую силу веры, лишенной нравственных ограничений, когда священное писание оправдывает безжалостные инквизиции и расправы над деревнями.",["faction:Alliance"]="Хотя Алый орден носит доспехи и говорит на языке павшего Лордерона, он считает нынешний Альянс запятнанным и без колебаний казнит посланников Альянса.",["race:Undead"]="Алый орден — ближайший живой враг Отрекшихся: он оспаривает границы Тирисфальских лесов и активно охотится на любую нежить, вырвавшуюся из хватки Короля-лича."},sec={{t="Восстание из пепла",b="Когда принц Артас предал Лордерон и убил короля Теренаса Менетила II, Орден Серебряной Длани был сломлен. Уцелевшие паладины и жрецы сплотились под началом таких лидеров, как Александрос Могрейн, Сайдан Датрохан и генерал Аббендис, чтобы вернуть разоренную родину. Перестроив силы в Дольном Очаге и Длани Тира, они поклялись очистить землю от нежити священным огнем. Но война затягивалась, и в их рядах разрастались трагедия и подозрительность. Группа во главе с Аббендис стала крайне нетерпимой к нечеловеческим расам, настаивая, что судьба Лордерона — бремя одного лишь человечества. Отчаянное сопротивление вскоре переродилось в непреклонный, ксенофобский крестовый поход."},{t="Великий раскол",b="Когда догмы ордена ожесточились до религиозного безумия, умеренные командиры отшатнулись. Лорд Максвелл Тиросс и его последователи доказывали, что для возвращения севера нужны союзы по всему Азероту, и искали помощи у дворфов, гномов и ночных эльфов. Отвергнутые фанатиками, Тиросс и другие разочарованные рыцари покинули орден и основали Серебряный Рассвет, оставшись верными чистым и открытым заветам Света. Тем временем Алый орден захватил Монастырь Алого ордена в Тирисфальских лесах, сделав его оплотом своей власти, и стал истреблять путников и беженцев, истерично полагая, что каждый, кто ходит по Чумным землям, несет заразу Плети."},{t="Марионетка в багрянце",b="Крайняя жестокость ордена не была целиком его собственной виной. Во время штурма Стратхольма верховный крестоносец Сайдан Датрохан был отрезан от своих людей и тайно убит повелителем ужаса Балназзаром. Завладев телом Датрохана, демон взял под прямой контроль ряды Алого ордена. Балназзар исподволь подпитывал их паранойю и подстроил убийство верховного лорда Александроса Могрейна через ревность его сына Рено. За громкими речами о чистоте и праведной ярости крестоносцы служат неведающими марионетками той самой демонической тьмы, которую, по их убеждению, Свет призывает их уничтожить."}},faq={{q="Почему Алый орден враждебен ко всем?",a="После падения Лордерона орден поддался крайней паранойе. Его члены считают, что каждый, кто побывал на севере Лордерона и не был очищен орденом, — явный или скрытый носитель чумы нежити. Ради сохранения своего видения чистого человечества они казнят всех чужаков на месте.",al={"why are scarlets hostile","are scarlets bad guys","why does scarlet crusade attack me","почему алые враждебны","алые — злодеи","почему алый орден нападает на меня"}},{q="Откуда взялся Алый орден?",a="Он возник из уцелевших рыцарей и жрецов Рыцарей Серебряной Длани после падения Лордерона в Третьей войне. Собравшись в Дольном Очаге и Монастыре Алого ордена под началом таких лидеров, как Сайдан Датрохан и Александрос Могрейн, они поклялись истребить Плеть любой ценой.",al={"scarlet crusade origin","who founded scarlet crusade","scarlet crusade history","происхождение алого ордена","кто основал алый орден","история алого ордена"}},{q="Чем Алый орден отличается от Серебряного Рассвета?",a="Оба ордена откололись от изначальной Серебряной Длани, но Серебряный Рассвет принимает все расы и остается верен милосердным добродетелям Света, а Алый орден превратился в фанатичный культ превосходства людей, убивающий беженцев и путников под видом священного очищения.",al={"argent dawn vs scarlet crusade","difference between scarlet and argent dawn","серебряный рассвет или алый орден","разница между алыми и серебряным рассветом"}},{q="Где находятся главные базы Алого ордена?",a="Главный оплот ордена — Монастырь Алого ордена на северо-востоке Тирисфальских лесов. Он также контролирует укрепленный город Дольный Очаг в Западных Чумных землях, Длань Тира на востоке и Алый бастион в руинах Стратхольма, а также множество сторожевых башен в регионе.",al={"scarlet crusade bases","scarlet locations","where are scarlet crusaders","базы алого ордена","где находятся алые","где искать алых крестоносцев"}},{q="Кто на самом деле возглавляет Алый орден?",a="Внешне орденом из Стратхольма командует верховный крестоносец Сайдан Датрохан, а ему помогают верховный инквизитор Салли Вайтмейн и командир Могрейн из Алого ордена в Монастыре.",al={"who is leader of scarlet crusade","scarlet crusade grand crusader","кто глава алого ордена","верховный крестоносец алого ордена"}},{q="Могут ли алые крестоносцы пользоваться Светом, если они злы?",a="Да. Согласно космологии Света, для владения его силой нужна не моральная доброта, а абсолютная, непоколебимая убежденность и вера. Крестоносцы искренне считают свой жестокий поход чистым и справедливым, поэтому могут направлять священный гнев, несмотря на свою жестокость.",al={"why can scarlets use the light","scarlet crusade paladins light","do scarlets have the light","почему алые владеют светом","паладины алого ордена свет","есть ли у алых свет"}}},fp="15,435,19.692.0,16.656.0,19.616.2,47.315.0,40.301.0,58.293.0,51.289.0,39.174.2,68.264.0"}
P.entries["topic:scourge"] = {n="Плеть",s="Плеть — апокалиптическая армия нежити, состоящая из чудовищ, некромантов и порабощенных духов, подчиненных воле Короля-лича. Изначально Пылающий Легион создал ее, чтобы ослабить Азерот перед Третьей войной, но легион ходячих мертвецов вырвался из-под демонического контроля и разрушил королевства Лордерон и Кель'Талас. Сегодня Плеть ведет нескончаемую войну из своей ледяной цитадели в Нордсколе и через свое порочное владычество над Чумными землями.",h="Плеть — апокалиптическая армия нежити, состоящая из чудовищ, некромантов и порабощенных духов, подчиненных...",kw={"arthas","cult of the damned","frostmourne","frozen throne","kel'thuzad","lich king","lordaeron","plague","plaguelands","scourge","undead","артас","культ проклятых","ледяная скорбь","ледяной трон","кел'тузад","король-лич","лордерон","чума","чумные земли","плеть","нежить"},ang={["class:Paladin"]="Рыцари Серебряной Длани были разгромлены Плетью, когда принц Артас обратился против своих наставников и убил Утера Светоносного. Для любого паладина очищение мира от Плети с помощью Света — священный долг.",["faction:Alliance"]="Память о падении Лордерона остается для Альянса открытой раной и движет его постоянными военными усилиями по возвращению Чумных земель и отмщению павших.",["faction:Horde"]="Теперь, когда Отрекшиеся приняты в Орду, вся коалиция оказалась втянута в жестокую непрекращающуюся войну с остатками армий Короля-лича на севере.",["race:Human"]="Плеть уничтожила величайшее королевство людей, истребила род Менетилов и превратила сердце Лордерона в зараженную пустошь.",["race:Undead"]="Каждый Отрекшийся когда-то был порабощенным орудием Плети и был вынужден убивать друзей и родных, пока хватка Короля-лича не ослабла. Уничтожение Плети — не просто война за выживание, а кампания абсолютной личной мести."},sec={{t="Чума по демоническому замыслу",b="Плеть родилась как орудие разрушения, выкованное Пылающим Легионом. Лорды демонов приковали дух павшего орка-шамана Нер'зула к Ледяному Трону в далеком Нордсколе и превратили его в Короля-лича. Обладая устрашающей телепатической силой, он получил приказ подготовить Азерот к завоеванию. Король-лич обрушил Чуму нежизни на юг, на ничего не подозревавшее человеческое государство Лордерон, положившись на смертных предателей из Культа Проклятых, которые отравили запасы зерна. Погибшие вставали не покойниками, обретшими покой, а искаженными рабами, всецело подчиненными железной воле Короля-лича."},{t="Падение севера",b="Плеть добилась полного разорения, когда принц Артас Менетил поддался шепоту Короля-лича. Ища мести в Нордсколе, Артас завладел проклятым клинком Ледяная Скорбь и потерял душу, став главным рыцарем смерти Плети. Вернувшись домой, Артас убил своего отца, короля Теренаса, разорил Столицу и обрушил орду нежити на Лордерон. Плеть прошла по таким городам, как Дарроушир и Андорал, истребила паладинов Серебряной Длани, уничтожила Даларан, чтобы призвать Архимонда, и прорезала мертвый шрам через Кель'Талас, чтобы воскресить Кел'Тузада в облике лича."},{t="Предательство и раскол",b="Король-лич никогда не собирался служить Пылающему Легиону вечно. Через Артаса Нер'зул тайно подстроил поражение Легиона, подтолкнув Иллидана Ярость Бури убить повелителя ужаса Тихондрия в Оскверненном лесу. В ярости лорд демонов Кил'джеден позднее приказал Иллидану уничтожить Ледяной Трон. Нападение Иллидана раскололо ледяную темницу, и власть Короля-лича над разумом его слуг пошатнулась. Воспользовавшись ослаблением контроля, группа свободных нежити во главе с воскресшей банши Сильваной Ветрокрылой откололась, нарекла себя Отрекшимися и захватила руины Лордерона."},{t="Нынешняя угроза",b="Хотя Плеть ослаблена расколом Ледяного Трона и мятежом Отрекшихся, она остается самой смертоносной силой северных земель. Под командованием лича Кел'Тузада ее поганища, некрорахниды и некроманты господствуют над оскверненными Восточным и Западным Пределами, ныне известными как Чумные земли. Из мрачных бастионов и зараженных полей они непрерывно воюют с Отрекшимися Подгорода, фанатичными ревнителями Алого ордена и уцелевшими оплотами Альянса."}},faq={{q="Что такое Плеть?",a="Плеть — огромная империя рабов-нежити, некромантов и искаженных тварей, ментально подчиненных Королю-личу. Они существуют лишь для того, чтобы уничтожать все живое и превращать трупы павших в послушных слуг.",al={"what is the scourge","undead scourge","who are the scourge","что такое плеть","плеть нежити","кто такая плеть"}},{q="Кто возглавляет Плеть?",a="Плетью командует Король-лич с Ледяного Трона на далеком ледяном континенте Нордскол. В разоренных землях Лордерона его армиями на местах руководят могущественные помощники, например лич Кел'Тузад.",al={"who is the scourge leader","scourge master","who controls the scourge","кто лидер плети","повелитель плети","кто управляет плетью"}},{q="Чем Плеть отличается от Отрекшихся?",a="Плеть — это безмозглая или подчиненная нежить, порабощенная психической волей Короля-лича. Отрекшиеся — бывшие жертвы Плети, обретшие свободную волю, когда сила Короля-лича ослабла. Во главе с леди Сильваной Ветрокрылой Отрекшиеся презирают Плеть и яростно борются за ее уничтожение.",al={"scourge vs forsaken","are forsaken scourge","why are undead fighting each other","плеть и отрекшиеся","отрекшиеся — это плеть","почему нежить воюет между собой"}},{q="Почему Плеть напала на Лордерон?",a="Пылающий Легион приказал Королю-личу распространить Чуму нежизни по Лордерону, чтобы истребить его народ, ослабить Альянс и устранить всякое сопротивление до начала вторжения демонов в Азерот во время Третьей войны.",al={"why destroy lordaeron","scourging of lordaeron","why did scourge invade","зачем уничтожать лордерон","гибель лордерона","почему плеть вторглась"}},{q="Кто такой Культ Проклятых?",a="Культ Проклятых — организация смертных, основанная верховным магом Кел'Тузадом. Ее члены — живые люди, добровольно служащие Королю-личу; их привлекли обещания темной магической силы и вечной жизни в нежизни. Именно они распространили зараженное зерно, с которого началась чума.",al={"cult of the damned","scourge cultists","why do humans join scourge","культ проклятых","культисты плети","почему люди идут в плеть"}},{q="Как Плеть развратила принца Артаса?",a="Одержимый желанием спасти свое королевство от чумы, принц Артас преследовал повелителя ужаса Мал'Ганиса до Нордскола. В отчаянии Артас взял проклятый рунный клинок Ледяная Скорбь, который похитил его душу. Сломленный и искаженный шепотом Короля-лича, он вернулся как главный воин Плети и истребил собственную родину.",al={"how did arthas turn","arthas scourge","why did arthas betray his people","как артас стал плетью","артас плеть","почему артас предал свой народ"}}},fp="7,453,26.618.0,21.590.0,23.611.0,18.514.0,20.221.0,22.227.0,46.302.0,37.237.0,30.303.0,47.342.0"}
P.entries["topic:sentinels"] = {n="Часовые",s="Часовые — элитные вооруженные силы ночных эльфов, преимущественно женские, созданные десять тысяч лет назад после Войны Древних. Под руководством Сестринства Элуны и под командованием генерала Шандрисы Оперенной Луны они охраняют поселения кальдораев и защищают священные земли от Ясеневого леса до Фераласа. Сегодня они ведут ожесточенную войну против вырубки лесов Ордой и присматривают за своим новым домом — Тельдрассилом.",h="Часовые — элитные вооруженные силы ночных эльфов, преимущественно женские, созданные десять тысяч лет назад...",kw={"ashenvale","feathermoon","huntress","kaldorei","moonglaive","nightsaber","sentinels","shandris","silverwing","tyrande","ясеневый лес","оперенная луна","охотница","кальдораи","лунная глевия","ночной саблезуб","часовые","шандриса","среброкрылые","тиранда"},ang={["class:Hunter"]="Лучницы Часовых и охотницы верхом на зверях воплощают вершину ночной стрельбы и дружбы с животными на Калимдоре.",["class:Priest"]="Поскольку Часовые родились непосредственно из Сестринства Элуны, воинский долг и священная преданность Богине Луны остаются неразрывно связаны.",["faction:Horde"]="Часовые — смертоносные лесные застрельщики, наносящие удар без предупреждения из теней Ясеневого леса и яростно противодействующие лесозаготовкам Орды.",["race:NightElf"]="Каждая деревушка кальдораев обязана своим выживанием бдительному взору Часовых, и многие юные девушки мечтают заслужить место в армии Шандрисы и Тиранды."},sec={{t="Рожденные Расколом",b="До Великого Раскола армия древней империи кальдораев выродилась в декадентскую иерархию, где звание определялось знатным происхождением, а не воинским мастерством. Разрушения Войны Древних показали, что такая аристократическая структура совершенно непригодна для защиты Азерота. После этого верховная жрица Тиранда Шелест Ветра возглавила радикальные реформы в обществе ночных эльфов. Она обратилась к Сестринству Элуны — ордену, который уцелел и обладал большим опытом в тактике, бою и исцелении. Из его набожных рядов Тиранда создала Часовых: постоянную армию, призванную самоотверженно защищать зарождающееся общество независимо от знатности рода."},{t="Устройство и тактика",b="Хотя Тиранда Шелест Ветра остается духовной верховной главнокомандующей, непосредственное военное руководство принадлежит ее помощнице, генералу Шандрисе Оперенной Луне, действующей из Крепости Оперенной Луны в Фераласе. Часовые известны дисциплинированной стрельбой, смертоносными лунными глевиями и специализированными отрядами. Их силы состоят из элитных лучниц, охотниц на ночных саблезубах и разведчиц на гиппогрифах, господствующих в небе. За века до Третьей войны они сражались под началом верховного друида Фэндрала Оленьего Шлема в жестокой Войне Зыбучих Песков в Силитусе и остановили полчища киражей. Каждое поселение ночных эльфов — от Астранаара до раскидистых ветвей Дарнасса — полагается на гарнизоны Часовых."},{t="Защита священной земли",b="Во время Третьей войны Часовые отчаянно оборонялись и от демонов-захватчиков, и от первых вторжений Орды, понеся огромные потери, когда Кенарий пал в Ясеневом лесу. Пережив битву на горе Хиджал и преследуя Иллидана по Лордерону, они вернулись и обнаружили, что Калимдор изменился безвозвратно. Сегодня Часовые сталкиваются с опасностью на нескольких фронтах. В Тельдрассиле гарнизоны борются с оскверненными животными и разъяренными фурболгами. Южнее Среброкрылые Часовые непрестанно сражаются со Всадниками Песни Войны в Ущелье Песни Войны, решив изгнать Орду из Ясеневого леса и защитить древние леса от дальнейшей эксплуатации."}},faq={{q="Кто возглавляет Часовых?",a="Верховная жрица Тиранда Шелест Ветра руководит организацией в политическом и духовном смысле, создав ее из Сестринства Элуны. Практическое повседневное командование армией лежит на генерале Шандрисе Оперенной Луне, которая руководит операциями по всему Калимдору из Крепости Оперенной Луны.",al={"sentinel leader","who is in charge of sentinels","shandris or tyrande","лидер часовых","кто главный у часовых","шандриса или тиранда"}},{q="Почему большинство Часовых — женщины?",a="После Войны Древних традиционное общество ночных эльфов разделило обязанности на духовные и воинские: женщины составили жречество Элуны и сформировали армию Часовых, а мужчины в подавляющем большинстве вступали в Круг Кенария как друиды. Это строгое разделение определяло облик армии тысячелетиями, хотя после Третьей войны общество медленно начало меняться.",al={"why only female sentinels","women army night elf","can men be sentinels","почему только женщины часовые","женская армия ночных эльфов","могут ли мужчины быть часовыми"}},{q="Где находится главная база Часовых?",a="Помимо столицы ночных эльфов Дарнасса, их главная крепость — Крепость Оперенной Луны на острове у побережья Фераласа. Крупные гарнизоны также расположены по всему Ясеневому лесу, например в Астранааре и на Аванпосте Среброкрылых.",al={"sentinel base","sentinel headquarters","feathermoon stronghold","база часовых","штаб часовых","крепость оперенной луны"}},{q="На каком оружии специализируются Часовые?",a="Часовые — прославленные стрелки, использующие изогнутые луки, но их культурный символ — трехлезвийная лунная глевия. Охотницы владеют ими, сидя верхом на свирепых ночных саблезубах, а воздушные всадницы атакуют со спин бронированных гиппогрифов.",al={"sentinel weapons","moonglaive","what do sentinels use","оружие часовых","лунная глевия","чем пользуются часовые"}},{q="Почему Часовые сражаются в Ущелье Песни Войны?",a="Среброкрылые Часовые ведут территориальную войну против Всадников Песни Войны из Орды. Орки сильно вырубили Ясеневый лес ради поставок древесины, осквернив леса, священные для ночных эльфов, которые поклялись изгнать каждого захватчика.",al={"warsong gulch sentinels","silverwing sentinels","why ashenvale war","ущелье песни войны часовые","среброкрылые часовые","почему война в ясеневом лесу"}},{q="Участвовали ли Часовые в Третьей войне?",a="Да. Они были главной обороной на передовой, когда Пылающий Легион и Плеть двинулись на Калимдор. Под предводительством Тиранды они удерживали рубеж, пока не был заключен союз с беженцами-людьми и орками, что привело к решающей победе в битве на горе Хиджал.",al={"sentinels third war","sentinels hyjal","sentinels wc3","часовые третья война","часовые хиджал","часовые warcraft 3"}}},fp="9,417,23.714.0,21.720.0,21.656.0,24.291.0,30.386.0,48.247.0,44.257.0,48.270.0,41.269.0"}
P.entries["topic:shadow-council"] = {n="Совет Теней",s="Совет Теней — тайный заговор чернокнижников и некролитов, организовавший порчу Старой Орды на Дреноре и направлявший ее вторжение в Азерот. Основанный Гул'даном по указанию Пылающего Легиона, культ управлял вождями кланов из-за кулис, пока вождь Оргрим Молот Рока не разгромил их оплот в Черной горе.",h="Совет Теней — тайный заговор чернокнижников и некролитов, организовавший порчу Старой Орды на Дреноре и...",kw={"blackhand","blackrock mountain","burning legion","cho'gall","dark portal","death knight","fel magic","gul'dan","mannoroth","shadow council","teron gorefiend","чернорук","черная гора","пылающий легион","чо'гал","темный портал","рыцарь смерти","магия скверны","гул'дан","маннорот","совет теней","терон кровожад"},ang={["class:Warlock"]="Совет Теней узаконил изучение колдовства Скверны и сделок с демонами среди смертных; современные чернокнижники напрямую опираются на обряды призыва и методы собирания душ, которые он впервые применил.",["faction:Alliance"]="Королевство Штормград пало в основном из-за тайных операций Совета Теней — от открытия Темного портала до убийства короля Ллейна Ринна.",["faction:Horde"]="Жестокая расправа вождя Оргрима Молота Рока над Советом Теней стала поворотным моментом, когда Орда впервые попыталась освободиться от демонических кукловодов.",["race:Orc"]="Совет Теней устроил гибель Дренора и кровавый договор, проклявший орочью расу, оставив глубокий родовой стыд, от которого новая Орда Тралла упорно стремится очиститься."},sec={{t="Создатели проклятия крови",b="Перед переходом в Азерот Гул'дан собрал тайное собрание чернокнижников, некролитов и корыстных вождей, чтобы управлять орочьими кланами. Возвысив Чернорука Разрушителя как податливую марионетку, Совет Теней правил Старой Ордой из тени. Он распространял магию Скверны по Дренору, координировал завоевание Шаттрата и Храма Карабор и поил кланы кровью демона Маннорота, привязав орков к воле Пылающего Легиона."},{t="Переход и Черная гора",b="Когда Кил'джеден исчез, Совет Теней заключил союз с Медивом — Стражем, одержимым Саргерасом, — чтобы пробить преграду между мирами. Используя жизненные силы тысяч пленников для усиления Темного портала, Совет направил Орду в Королевство Штормград. Обеспечив себе Черную гору через шаткое соглашение, которое Чо'гал заключил с дворфами Черного Железа и огненными элементалями Рагнароса, чернокнижники руководили военными действиями из верхней части пика."},{t="Чистка Молота Рока и рыцари смерти",b="После смерти Медива Гул'дан впал в коматозный транс. Оргрим Молот Рока воспользовался моментом: он убил Чернорука, допросил Гарону, чтобы раскрыть внутреннее святилище Совета, и начал штурм, уничтоживший большинство чернокнижников. Очнувшись и обнаружив свой культ разгромленным, Гул'дан выторговал себе жизнь, предложив Молоту Рока ужасающий ответ человеческой магии. Вселив духи убитых чернокнижников Совета Теней в тела павших рыцарей-людей, Гул'дан создал первых рыцарей смерти."}},faq={{q="Кто основал Совет Теней?",a="Совет Теней основал орк-чернокнижник Гул'дан на Дреноре. Служа повелителю демонов Кил'джедену, Гул'дан собрал единомышленников — практиков магии Скверны, чтобы дергать за ниточки кланов, используя вождя Чернорука как невольную марионетку.",al={"who made shadow council","shadow council founder","guldan council","кто создал совет теней","основатель совета теней","гулдан совет"}},{q="Что случилось с Советом Теней во время Первой войны?",a="Когда Гул'дан оказался недееспособен после смерти Медива, Оргрим Молот Рока убил Чернорука и принял командование Ордой. Молот Рока пытал убийцу Гарону, чтобы узнать о тайном убежище Совета на Вершине Черной горы, и устроил чистку, уничтожившую почти всех его чернокнижников.",al={"how did shadow council fall","doomhammer shadow council","purge of the shadow council","как пал совет теней","молот рока совет теней","чистка совета теней"}},{q="Как первые рыцари смерти появились из Совета Теней?",a="После того как Молот Рока уничтожил Совет, Гул'дан выторговал пощаду, пообещав темное оружие против человеческих чародеев. Он взял оставшиеся души убитых чернокнижников, прежде всего Терона Кровожада, и вселил их в сохранившиеся тела павших рыцарей Штормграда, создав первое поколение рыцарей смерти.",al={"shadow council death knights","who became death knights","teron gorefiend council","рыцари смерти совета теней","кто стал рыцарем смерти","терон кровожад совет"}},{q="Все ли орки-чернокнижники входили в Совет Теней?",a="Нет. Хотя Совет Теней контролировал широкое распространение магии Скверны на Дреноре, несколько практиков отказались вступать. Такие известные фигуры, как Дрек'Тар из Северных Волков и Некрос Крушитель Черепов, изучили темные искусства, но остались безусловно верны своим кланам, а не клике Гул'дана.",al={"were all warlocks shadow council","drekthar shadow council","nekros shadow council","все ли чернокнижники совет теней","дрек'тар совет теней","некрос совет теней"}},{q="Какую роль Чо'гал играл в Совете?",a="Чо'гал был главным учеником и первым помощником Гул'дана. Он возглавлял клан Сумеречного Молота в сфере влияния Совета и, используя свои тайные связи с Древними богами, заключил перемирие с дворфами Черного Железа и огненными элементалями в Черной горе.",al={"chogall shadow council","chogall role","twilight hammer shadow council","чо'гал совет теней","роль чо'гала","сумеречный молот совет теней"}},{q="Существует ли Совет Теней до сих пор?",a="Первоначальный Совет был разгромлен Молотом Рока, а его остатки распались еще сильнее, когда Гул'дан погиб в Гробнице Саргераса. Однако разрозненные культисты, уцелевшие чернокнижники и демонические агенты, продолжающие дело Легиона в Азероте и среди руин Дренора, по-прежнему ведут свой род от организации Гул'дана.",al={"is shadow council around","shadow council today","shadow council present","существует ли совет теней","совет теней сегодня","совет теней сейчас"}}},fp="14,365,29.501.0,35.492.0,36.509.1,31.248.0,57.279.0,61.327.0,50.315.0,40.258.0,36.318.0"}
P.entries["topic:shaman"] = {n="Шаман",s="Шаманы — духовные посредники и проводники стихий Орды, общающиеся с изначальными силами земли, воздуха, огня и воды. Они поддерживают равновесие необузданной природы с помощью тотемов, молний и исцеления предков и составляют духовное ядро культуры орков, таурен и троллей под предводительством вождя Тралла.",h="Шаманы — духовные посредники и проводники стихий Орды, общающиеся с изначальными силами земли, воздуха, огня...",kw={"air","ancestors","drek'thar","earth","earthen ring","elements","fire","primal","shaman","thrall","totem","water","воздух","предки","дрек'тар","земля","служители земли","стихии","огонь","изначальный","шаман","тралл","тотем","вода"},ang={["class:Shaman"]="Ваши силы даны вам благодаря взаимному уважению с переменчивыми духами стихий и предками; поддерживать равновесие — ваш воинский долг и духовное бремя.",["faction:Alliance"]="Воины Альянса относятся к шаманам с опаской: на поле боя они встречают яростных бойцов, чьи тотемы повелевают молниями, сотрясают землю и дарят внезапное исцеление.",["faction:Horde"]="Шаманизм воплощает духовное возрождение Орды, давая путь чести и поклонения природе, который заменил демоническую порчу.",["race:Orc"]="Возвращение на путь шамана позволило оркам преодолеть оцепенение лагерей для интернированных и вернуть наследие предков.",["race:Tauren"]="Таурены занимаются шаманизмом многие поколения в рядах Служителей Земли, являясь терпеливой духовной опорой для более молодых культур Орды.",["race:Troll"]="Шаманы Черного Копья направляют изначальные стихии через свои племенные традиции, соединяя почитание духов природы и древних лоа."},sec={{t="Посредники стихий",b="В отличие от жрецов, почитающих божественное, или магов, подчиняющих тайную магию, шаманы взаимодействуют напрямую с изначальными силами природы. Стихии земли, воздуха, огня и воды по сути хаотичны и пребывают в вечном противостоянии. Шаман не порабощает эти силы, а обращается к ним с просьбами и договаривается с ними, храня равновесие между первобытной яростью и миром смертных. С помощью деревянных и каменных тотемов, установленных в землю, шаманы направляют эти стихийные договоры, чтобы защищать союзников, замедлять врагов или врачевать раненых очищающей водой."},{t="Утрата и возрождение у орков",b="Шаманизм когда-то был древней основой жизни орочьих кланов на Дреноре. Однако Кил'джеден и Совет Теней обманом заставили шаманов начать войну против дренеи, и духи стихий лишили их своей благосклонности. Лишившись даров, многие бывшие шаманы поддались демонической порче и стали чернокнижниками, почти полностью уничтожив эту традицию. Лишь после Второй войны Тралл под руководством Дрек'Тара из клана Северного Волка заново открыл древние обряды. Возвышение Тралла до Вождя возродило шаманизм и сделало его нравственным ориентиром Новой Орды."},{t="Традиции Орды",b="В Калимдоре шаманские традиции союзных народов Орды сильно различаются. Таурены-мистики, основавшие древних Служителей Земли более двух веков назад, считают общение с землей и духами священной основой своей культуры. Тролли Черного Копья подходят к этому искусству через почитание лоа и древних диких духов предков, сплетая вуду и обряды природы. У всех племен шаманы остаются важнейшими старейшинами общины, советниками и грозными защитниками на передовой."}},faq={{q="Какие расы могут стать шаманами?",a="Orcs, tauren, and trolls are the Horde's prominent shamanic peoples. Their traditions draw on elemental spirits, ancestors, and, among trolls, the loa.",al={"who can be shaman","shaman races","can alliance be shaman","кто может быть шаманом","расы шаманов","может ли альянс быть шаманами"}},{q="Откуда шаманы берут свою магию?",a="Шаманы черпают силу в общении с духами стихий земли, воздуха, огня и воды, а также с духами предков. Вместо того чтобы повелевать этими энергиями силой, шаман просит их о помощи и уравновешивает их хаотичную природу, часто закрепляя эту связь с помощью ритуальных тотемов.",al={"how does shaman magic work","shaman source of power","where do totems come from","как работает магия шаманов","источник силы шаманов","откуда берутся тотемы"}},{q="Почему орки утратили силы шаманов до Первой войны?",a="Повелитель демонов Кил'джеден выдавал себя за духов предков и обманом заставил орочьих шаманов напасть на мирных дренеи. Оскорбленные бессмысленной резней, духи стихий Дренора разорвали связь и перестали отвечать на призывы. Оставшись беззащитными, многие отчаявшиеся шаманы обратились к магии Скверны и стали чернокнижниками.",al={"why did orc shaman become warlocks","draenor shaman fall","kiljaeden trick shaman","почему орки-шаманы стали чернокнижниками","падение шаманов дренора","кил'джеден обманул шаманов"}},{q="Кто вернул оркам шаманизм?",a="Тралл, сын Дуротана, разыскал клан Северного Волка в Альтеракских горах. Под руководством старейшины-шамана Дрек'Тара Тралл постиг древние духовные связи, разрушил демоническое оцепенение, мучившее его народ, и вернул шаманизму место в сердце Новой Орды.",al={"who revived shamanism","thrall and drek'thar shaman","shaman return","кто возродил шаманизм","тралл и дрек'тар шаман","возвращение шаманов"}},{q="Что такое Служители Земли?",a="The Earthen Ring is an ancient organization of shaman founded centuries ago by the tauren. Its practitioners dedicate themselves to maintaining harmony among the volatile elemental spirits and healing regions afflicted by spiritual unrest.",al={"earthen ring lore","who are earthen ring","shaman faction","служители земли предания","кто такие служители земли","фракция шаманов"}},{q="Чем шаман отличается от друида?",a="Друиды общаются с Изумрудным Сном, растениями и духами животных, оберегая живой круговорот природы. Шаманы же уравновешивают неживые, изначальные стихии физического мира — землю, огонь, воду и ветер — вместе с духами умерших предков.",al={"druid vs shaman","difference between druid and shaman","shaman or druid","друид или шаман","разница между друидом и шаманом","шаман против друида"}}},fp="6,317,25.545.0,27.583.0,23.498.0,30.151.0,30.313.0,63.311.0,39.288.0,25.239.0,38.269.0"}
P.entries["topic:shan-do"] = {n="Шан'до",s="Шан'до — почитаемое дарнасское обращение, означающее «уважаемый учитель» или «почтенный наставник». Традиционно оно используется в обществе ночных эльфов и среди друидов и выражает глубокое почтение к наставнику, ведущему другого по пути мудрости и природной магии. Его прямая противоположность — теро'шан, «уважаемый ученик».",h="Шан'до — почитаемое дарнасское обращение, означающее «уважаемый учитель» или «почтенный наставник».",kw={"cenarius","darnassian","druid","honored teacher","malfurion","shan'do","shando","thero'shan","кенарий","дарнасский","друид","уважаемый учитель","малфурион","шан'до","теро'шан"},ang={["class:Druid"]="Каждый друид выводит свое учение через цепь наставников к Шан'до Ярость Бури и самому Кенарию; произнося этот титул, он чтит эту непрерывную цепь.",["race:NightElf"]="Для вас, на родном языке, шан'до — одно из самых торжественных обращений к старшему или учителю, несущее многовековой культурный вес.",["race:Tauren"]="Друиды-таурены, обучающиеся вместе с ночными эльфами на Лунной поляне, знают этот титул и почтительно используют его, обращаясь к наставникам вроде Малфуриона Ярость Бури."},sec={{t="Титул глубокого почтения",b="В дарнасском языке шан'до буквально переводится как «уважаемый учитель» или «почтенный наставник». Приставка «шан» означает честь, а суффикс «до» — власть, старшинство или мастерство; тот же корень есть в слове минн'до («мать»). Это далеко не просто название занятия: обращение к старшему или наставнику «шан'до» выражает торжественное смирение, сыновнюю преданность и неизменное уважение к его руководству."},{t="Преемственность друидов",b="Наиболее известна связь этого титула с историей Круга Кенария. Полубог Кенарий был первым шан'до для Малфуриона Ярость Бури и обучал его путям природы до Войны Древних. В свою очередь Малфурион стал шан'до для поколений смертных друидов, и «Шан'до Ярость Бури» — его привычное обращение среди ночных эльфов, хранителей лесов и почитающих его союзников по всему Калимдору."},{t="Наставники за пределами Круга",b="Хотя чаще всего это обращение встречается среди друидов Кенария — например, когда ученики обращаются к верховному друиду Наралексу или к спящему Малфуриону, — по сути оно дарнасское и не только религиозное. Во время Войны Древних Иллидан Ярость Бури ненадолго назвал человека-чародея Ронина шан'до, изучая его необычные тайные приемы. Титул отражает связь передачи знаний между учителем и учеником независимо от школы мысли."}},faq={{q="Что на самом деле означает слово шан'до?",a="На дарнасском шан'до переводится как «уважаемый учитель» или «почтенный наставник». Оно выражает глубокое почтение и благодарность наставнику.",al={"shando meaning","what does shando translate to","shando translation","darnassian shando","значение шан'до","как переводится шан'до","перевод шан'до","дарнасское шан'до"}},{q="Какое слово противоположно шан'до или обозначает ученика?",a="Дополняющее обращение — теро'шан, что переводится как «уважаемый ученик». Наставники называют учеников теро'шан, признавая их преданность и дисциплину.",al={"opposite of shando","student word in darnassian","theroshan meaning","what is thero'shan","противоположность шан'до","слово ученик на дарнасском","значение теро'шан","что такое теро'шан"}},{q="Кого чаще всего называют Шан'до?",a="Верховного друида Малфуриона Ярость Бури чаще всех называют Шан'до ночные эльфы и Круг Кенария. Кенария его первые ученики тоже называли шан'до, а другие видные лидеры, например Наралекс, получают это обращение от своих последователей.",al={"who is shando","shando stormrage","who has the title shando","кто такой шан'до","шан'до ярость бури","у кого титул шан'до"}},{q="Используется ли титул шан'до только друидами?",a="Нет. Хотя он глубоко укоренен в друидической традиции Кенария, шан'до — это дарнасская форма вежливости. Любого мастера ремесла, магии или мудрости ученик теоретически может назвать шан'до; например, Иллидан Ярость Бури однажды назвал человека-волшебника Ронина шан'до, изучая его чародейство.",al={"can non druids be shando","is shando only for druids","shando outside druidism","могут ли не друиды быть шан'до","только ли друиды шан'до","шан'до вне друидизма"}}},fp="7,329,25.444.0,25.421.0,25.456.0,41.144.0,51.175.0,36.268.0,41.310.0"}
P.entries["topic:skyborne"] = {n="Небожители",s="Небожители, или шен'дорей, — ответвление высших эльфов, потомки мятежников, бежавших из Эльдре'Таласа после того, как они выступили против демонических сделок принца Тортелдрина. Заключив отчаянную сделку с духами ветра, их предки покинули Азерот и поселились на парящем Острове Зефрис в Небесной выси. Сегодня, когда их стихийные покровители внезапно исчезли, парящее убежище страдает от внутренних расколов и физического разрушения.",h="Небожители, или шен'дорей, — ответвление высших эльфов, потомки мятежников, бежавших из Эльдре'Таласа после...",kw={"al'aketh","eldre'thalas","high order","shal'nan","shen'dorei","sky-touched","skyborne","skywall","windshapers","zephras isle","ал'акет","эльдре'талас","высший орден","шал'нан","шен'дорей","благословение небес","небожители","небесная высь","ваятели ветра","остров зефрис"},ang={["class:Mage"]="Высший орден Небожителей хранит древнее колдовство высокорожденных, вынесенное из Эльдре'Таласа, и стремится спасти рушащийся остров строгим владением тайной магией.",["class:Shaman"]="Ваятели ветра — эльфийский род, тесно связанный с духами ветра Небесной выси; они полагаются на общение со стихиями, а не на тайные традиции своих предков-высокорожденных.",["race:NightElf"]="Небожители состоят в прямом родстве с древними шен'дралар и северными ночными эльфами, хотя тысячелетия в Небесной выси превратили их в высших эльфов, среди которых все чаще встречается стихийная голубая кожа."},sec={{t="Бегство из Эльдре'Таласа",b="После Раскола шен'дралар Эльдре'Таласа чахли без Источника Вечности. Принц Тортелдрин придумал темное спасение: призвать демона Иммол'тара и вытянуть его силу. Ужаснувшиеся дворяне и горожане воспротивились, опасаясь нового вторжения Легиона. В ответ Тортелдрин устроил кровавую чистку, уничтожив десятки домов. Из уцелевших теней поднялось сопротивление, во главе которого встал человек в маске, известный лишь как Шал'нан («Сокрытый»). Когда отчаянный налет мятежников на ритуальное святилище Тортелдрина обернулся катастрофическим хаосом магии, Шал'нан собрал уцелевших и бежал на запад, в порт Эльдре'нарр, и они вышли в море, преследуемые флотом принца."},{t="Убежище в небесах",b="Загнанные в угол посреди открытого океана, изгнанники заключили союз с первичными духами ветра. Эти существа подняли Остров Зефрис прямо в небеса и надежно закрепили его в Небесной выси — Элементальном Плане воздуха. Освобожденный от безраздельной власти, Шал'нан сложил полномочия во время освящения Храма Четырех Ветров и передал управление избранному совету. За тысячелетия в этом чуждом мире изгнанники-ночные эльфы превратились в светлокожих стройных высших эльфов. В последних поколениях проявилось стихийное влияние, известное как Благословение небес: все больше детей рождается с бледно-голубой кожей."},{t="Сокрушительное затишье",b="Столетиями жизнь в Небесной выси процветала в изоляции. Духи ветра строго запрещали упоминать Повелителя Ветра Ал'акира, отмахиваясь от вопросов с жутковатой тревогой. Несколько веков назад грянула катастрофа: стихийные покровители исчезли без объяснений, а вместе с ними пропал и Шал'нан. Лишившись попечителей, магические пилоны, удерживавшие Остров Зефрис, начали отказывать. Дальние участки суши откалывались, беженцы наводнили то, что осталось, а отчаяние породило бандитов и Ал'акет — фанатичный культ, посвященный Ал'акиру. Сегодня общество расколото между Высшим орденом, который ищет спасение в возвращении древней магии Тайного, и Ваятелями ветра, которые держатся за стихийные обряды."}},faq={{q="Кто такие Небожители?",a="Небожители, или шен'дорей («скрытый народ»), — высшие эльфы, потомки древних ночных эльфов, восставших против принца Тортелдрина в Эльдре'Таласе. Чтобы спастись от его мстительного флота, они заключили союз с духами ветра, которые перенесли их остров, Остров Зефрис, в Элементальный План воздуха.",al={"what are skyborne","who are shen'dorei","shendorei","skyborne lore","кто такие небожители","кто такие шен'дорей","шен'дорей","предания о небожителях"}},{q="Почему у некоторых Небожителей голубая кожа?",a="Тысячелетия в Элементальном Плане воздуха незаметно изменили их природу. Недавнее явление, известное как Благословение небес, приводит к тому, что все большая доля детей — сейчас примерно трое из десяти — рождается с голубой кожей. Ученые предполагают, что черты их предков-ночных эльфов вскоре будут полностью вытеснены.",al={"sky-touched blessing","why are they blue","blue elves","sky touched","благословение небес","почему они голубые","голубые эльфы","отмеченные небом"}},{q="Кто такой Шал'нан?",a="Шал'нан, или «Сокрытый», был мужчиной в маске, возглавившим сопротивление демоническим призывам принца Торгельдрина в Эльдре'Таласе. Выведя уцелевших в безопасное место в Небесную высь, он отрекся от власти и учредил демократический совет, служа своему народу, пока не исчез при загадочных обстоятельствах много столетий назад вместе с их покровителями-элементалями.",al={"who is the veiled one","shalnan","the masked rebel","leader of skyborne","кто такой сокрытый","шал'нан","мятежник в маске","вождь небожителей"}},{q="Что происходит с Островом Зефрис?",a="Остров Зефрис удерживается в Небесной выси магическими пилонами, настроенными на силу стихий. Когда духи ветра, поддерживавшие их, внезапно исчезли столетия назад, пилоны начали отказывать. Части суши откололись и упали в пустоту, оставив выживших без крова и толкнув лишившихся жилья эльфов на путь разбоя.",al={"why is zephras isle crumbling","zephras falling","what happened to skywall island","почему рушится остров зефрис","падение зефриса","что случилось с островом небесной выси"}},{q="Что такое Высший орден и Ваятели ветра?",a="Это две основные культурные фракции Небожителей. Высший орден происходит от магистров высокорожденных и стремится восстановить рушащееся общество дисциплинированным владением тайной магией. Ваятели ветра ведут род от простых горожан-ночных эльфов и почитают стихийные и духовные обычаи, сложившиеся за время жизни в Небесной выси.",al={"skyborne factions","high order vs windshapers","windshaper lore","фракции небожителей","высший орден и ваятели ветра","предания о ваятелях ветра"}},{q="Кто такие Ал'акет?",a="Ал'акет — отчаявшийся культ Небожителей, поклоняющийся Повелителю Ветра Ал'акиру. Если стихийные покровители их предков боялись Ал'акира и избегали говорить о нем, то крушение Острова Зефрис привело бездомных и обездоленных беженцев к повелителю стихий в поисках спасения и силы.",al={"alaketh cult","cult of al'akir","skyborne cult","культ ал'акет","культ ал'акира","культ небожителей"}}},fp="8,417,24.687.0,20.628.0,17.716.1,21.300.0,36.317.0,21.348.0,34.318.0,44.342.0,21.290.0"}
P.entries["topic:skywall"] = {n="Небесная высь",s="Небесная высь — обширные, охваченные бурями владения воздушных элементалей в Элементальном Плане. Изгнанные сюда титанами в древние времена, существа ветра, облаков и молний живут под властью Повелителя Ветра Ал'акира.",h="Небесная высь — обширные, охваченные бурями владения воздушных элементалей в Элементальном Плане.",kw={"air elemental","al'akir","elemental plane","shen'dorei","skywall","stormwall","thunderaan","windlord","zephras isle","воздушный элементаль","ал'акир","элементальный план","шен'дорей","небесная высь","громораан","повелитель ветра","остров зефрис"},ang={["class:Mage"]="Заклинатели и знатоки тайной магии издавна стремились использовать безграничную энергию атмосферы Небесной выси, но попытки вытянуть бури Ал'акира часто заканчивались крахом.",["class:Shaman"]="Небесная высь — первичный источник необузданных яростных ветров и молний, которые шаманы почитают и к которым взывают, общаясь с духами воздуха."},sec={{t="Тюрьма в небесах",b="Когда титаны низвергли Древних богов в незапамятные времена, они создали Элементальный План как надежную измерную тюрьму для усмирения буйных духов стихий Азерота. Повелители стихий яростно сражались между собой и в итоге поделили земли на отдельные владения. Царство ветра и бурь стало известно как Небесная высь, им правит Повелитель Ветра Ал'акир. Хотя оно отрезано от поверхности мира, его бури по-прежнему вечно кружатся в изоляции."},{t="Война стихий",b="Изгнание не положило конец древней вражде между властителями стихий. Небесная высь давно ведет пограничные споры с соседними мирами, например с Огненными Просторами. Одной из самых печально известных стычек стал Раскол стихий, когда принц Громораан Искатель Ветра попал в засаду и был предан Гарром и бароном Геддоном, главными лейтенантами Рагнароса Повелителя Огня. Рагнарос поглотил сущность принца, а осколки связал в разбитый талисман."},{t="Острова в тумане",b="Небесная высь состоит не только из бушующих ураганов и цитаделей джиннов. Среди облачных громад дрейфует Остров Зефрис — убежище, где живут шен'дорей. Смертные Азерота редко проникают сквозь завесу в царство воздуха, хотя безрассудные чародеи и оружейники всех времен накликали на себя беду, пытаясь вытянуть силу живых бурь Повелителя Ветра."}},faq={{q="Что такое Небесная высь?",a="Небесная высь — владения воздушных элементалей в измерении Элементального Плана. Созданное титанами для заточения слуг Древних богов, это царство целиком состоит из бескрайних небес, бурь, облаков и молний.",al={"what is skywall","skywall lore","domain of air","что такое небесная высь","предания о небесной выси","царство воздуха"}},{q="Кто правит Небесной высью?",a="Небесной высью правит Повелитель Ветра Ал'акир, верховный Повелитель стихий воздуха. Из своего грозового королевства он властвует над джиннами, циклонами и живыми бурями.",al={"who leads skywall","skywall boss","ruler of air","кто управляет небесной высью","босс небесной выси","правитель воздуха"}},{q="Как была создана Небесная высь?",a="После победы над Древними богами в изначальном прошлом Азерота созданные титанами существа сотворили Элементальный План, чтобы запереть хаотичных элементалей. В этой измерной тюрьме воздушные элементали захватили собственную обширную территорию, ставшую Небесной высью.",al={"origin of skywall","how was skywall made","происхождение небесной выси","как создана небесная высь"}},{q="Что случилось с принцем Громорааном?",a="Во время Раскола стихий принц Громораан попал в засаду лейтенантов Рагнароса Повелителя Огня — Гарра и барона Геддона. Рагнарос поглотил сущность принца воздуха, а то, что осталось, заточил в разбитый талисман стихийного пленения.",al={"thunderaan lore","what happened to thunderaan","windseeker fate","предания о громораане","что случилось с громорааном","судьба искателя ветра"}},{q="Кто живет в Небесной выси?",a="Небесную высь населяют воздушные элементали, могущественные владыки джиннов, призраки молний и стихийные грозовые драконы. Здесь также находится Остров Зефрис — убежище, где живут шен'дорей.",al={"skywall inhabitants","skywall denizens","who is in skywall","обитатели небесной выси","жители небесной выси","кто живет в небесной выси"}},{q="Могут ли смертные попасть в Небесную высь?",a="Смертным непросто попасть в Небесную высь, ведь она существует в отдельной измерной тюрьме. Исторически ее небес касались лишь могущественные чародеи, управлявшие стихийными разломами, или те, кто искал уединенных шен'дорей на Острове Зефрис.",al={"how to get to skywall","travel to skywall","skywall portal","как попасть в небесную высь","путешествие в небесную высь","портал в небесную высь"}}},fp="7,225,23.443.0,19.453.0,17.357.0,16.232.0,18.176.0,24.248.0,35.243.0,21.183.0,26.231.0"}
P.entries["topic:stonefield-family"] = {n="семья Стоунфилдов",s="Семья Стоунфилдов — род людей-фермеров, живущих на Ферме Стоунфилдов в западной части Элвиннского леса. Известные своими давними сельскими корнями, они ведут хозяйство, будучи втянуты в затянувшееся соперничество с соседями, Маклюрами. Несмотря на вражду между двумя семьями, молодое поколение оказывается связано через разделяющую семьи границу.",h="Семья Стоунфилдов — род людей-фермеров, живущих на Ферме Стоунфилдов в западной части Элвиннского леса.",kw={"elwynn forest","gramma stonefield","maclure","mildred stonefield","stonefield","stonefield family","stonefield farm","stonefields","tommy joe","элвиннский лес","бабушка стоунфилд","маклюр","милдред стоунфилд","стоунфилд","семья стоунфилдов","ферма стоунфилдов","стоунфилды","томми джо"},ang={["faction:Alliance"]="Искатели приключений из Альянса, идущие в Западный Край, часто берутся за будничные дела и семейные ссоры Стоунфилдов, чтобы сохранить стабильность этой житницы Элвинна.",["race:Human"]="Для людей Штормграда Стоунфилды воплощают стойкую рабочую опору, поставляющую зерно и продукты для пропитания королевства."},sec={{t="Жизнь на ферме",b="Стоунфилды — типичные земледельцы Элвиннского леса, обрабатывающие землю к югу от дороги в Западный Край. Хозяйство держится на бабушке Милдред Стоунфилд, Мамаше Стоунфилд и юном Томми Джо Стоунфилде. Повседневная жизнь на ферме состоит из ухода за посевами и скотом, борьбы с местными вредителями и отражения набегов кобольдов, досаждающих шахтам и границам региона."},{t="Вражда с Маклюрами",b="Стоунфилды и их соседи Маклюры, которых отделяет лишь узкая полоса леса и пастбищ, питают друг к другу застарелую и упорную неприязнь. Между старшими поколениями обоих семей нет особой любви: мелкие ссоры и спор из-за границ владений омрачают любое общение. Несмотря на эту ожесточенную вражду между соседями, между юным Томми Джо Стоунфилдом и Мейбелл Маклюр расцвел тайный роман, и сочувствующим путникам приходится осторожно передавать их послания."}},faq={{q="Где живет семья Стоунфилдов?",a="Стоунфилды живут на Ферме Стоунфилдов на юго-западе Элвиннского леса, чуть южнее главной дороги к границе Западного Края.",al={"stonefield farm location","where are the stonefields","stonefield family location","где ферма стоунфилдов","где живут стоунфилды","расположение семьи стоунфилдов"}},{q="Кто известные члены семьи Стоунфилдов?",a="Среди заметных членов семьи — глава рода бабушка Милдред Стоунфилд, Мамаша Стоунфилд, Хомер Стоунфилд и юный Томми Джо Стоунфилд. В истории семьи также упоминаются другие родственники: Бернис Стоунфилд и покойный дядя Стоунфилд.",al={"who is in the stonefield family","stonefield members","stonefield family tree","кто в семье стоунфилдов","члены семьи стоунфилдов","семейное древо стоунфилдов"}},{q="Почему Стоунфилды ненавидят Маклюров?",a="Стоунфилды и Маклюры втянуты в классическую сельскую семейную вражду из-за старых земельных обид и соседского упрямства: обе семьи упорно отказываются мириться.",al={"stonefield maclure feud","why are stonefields fighting maclures","maclure rivalry","вражда стоунфилдов и маклюров","почему стоунфилды враждуют с маклюрами","соперничество с маклюрами"}},{q="Как вражда влияет на Томми Джо Стоунфилда?",a="Томми Джо Стоунфилд тайно влюблен в Мейбелл Маклюр с соседней фермы. Из-за открытой вражды между их родными паре приходится полагаться на осторожных посредников, чтобы обмениваться письмами и знаками привязанности.",al={"tommy joe maclure","tommy joe romance","who is tommy joe in love with","томми джо маклюр","роман томми джо","в кого влюблен томми джо"}},{q="Верна ли семья Штормграду?",a="Да. Как люди, живущие в Элвиннском лесу, они находятся под защитой Королевства Штормград и Альянса, хотя в основном заботятся о повседневном выживании своей фермы и местных угрозах.",al={"are stonefields alliance","stonefield loyalty","стоунфилды альянс","верность стоунфилдов"}},{q="Какие угрозы стоят перед семьей Стоунфилдов?",a="Помимо трений с семьей Маклюров, Стоунфилдам приходится бороться с наступающими кобольдами-вредителями, бродячими животными и общим отсутствием штормградской стражи, патрулирующей сельские земли.",al={"stonefield dangers","problems at stonefield farm","опасности стоунфилдов","проблемы на ферме стоунфилдов"}}},fp="17,382,21.402.0,16.479.1,38.149.0,51.237.0,41.209.0,46.227.0,37.221.0,45.198.0"}
P.entries["topic:stonemasons-guild"] = {n="Гильдия каменщиков",s="Гильдия каменщиков — объединение мастеров-строителей и ремесленников, восстановивших Штормград и Крепость Стражей Пустоты после Второй войны. После ожесточенного спора об оплате с Домом знати, закончившегося смертельными беспорядками, гильдию насильственно распустили, а ее членов вынудили уйти в изгнание, что привело к появлению Братства Справедливости.",h="Гильдия каменщиков — объединение мастеров-строителей и ремесленников, восстановивших Штормград и Крепость...",kw={"alexston","defias","nethergarde","nobles","stonemasons","stormwind","thredd","tiffin","vancleef","алекстон","братство справедливости","крепость стражей пустоты","знать","каменщики","штормград","тредд","тиффин","ван клиф"},ang={["class:Rogue"]="Превращение искусных мастеров в опасных разбойников, взломщиков и убийц показывает, как далеко простиралась тактическая хитрость ван Клифа.",["faction:Alliance"]="Распад гильдии оставил житницу Западного Края беззащитной и во власти преступников, что осложнило снабжение Альянса прямо у столицы.",["race:Dwarf"]="Дворфы-каменщики глубоко уважали Гильдию каменщиков, отмечая, что ее точность и громады укреплений соперничают с Королевским союзом каменотесов Стальгорна.",["race:Human"]="Прекрасный белый камень Штормграда служит горьким свидетельством величайшей внутренней трагедии королевства и напоминает путникам-людям о цене аристократической спеси."},sec={{t="Зодчие королевства",b="После разрушений Первой и Второй войн Альянс Лордерона поручил Гильдии каменщиков возвести Крепость Стражей Пустоты в Выжженных землях, чтобы наблюдать за разрушенным Темным порталом. Под руководством избранного главы гильдии Эдвина ван Клифа мастера показали такое искусство каменной кладки, что оно соперничало с Королевским союзом каменотесов дворфов. Впечатленный их трудом, Дом знати нанял гильдию для грандиозной задачи — отстроить Штормград из руин, доверив ей вернуть столице былое величие."},{t="Труд и предательство",b="Годами ван Клиф и армия ремесленников трудились по всему Элвиннскому лесу, возводя ввысь устремленные шпили Крепости Штормграда и огромные своды Собора Света. Однако королевская казна оказалась пуста из-за тяжелых военных долгов, накопленных в южных походах. Поддавшись аристократическим интригам, Дом знати отказался выплатить гильдии оговоренное жалованье и вознаграждение. Когда ван Клиф потребовал возмещения, знать в ответ в одностороннем порядке распустила гильдию, вызвав неистовую ярость у рабочих, проливавших кровь ради восстановления города."},{t="Кровь на улицах",b="Спор об оплате перерос в жестокие беспорядки по всему Штормграду. Во время отчаянной попытки примирить стороны королева Тиффин Ринн была сражена брошенным снарядом, что повергло короля Вариана в глубокую скорбь и жажду мести. Корона жестоко подавила волнения, схватив ключевых заговорщиков, например помощника ван Клифа Базиля Тредда, а ван Клиф и сотни разоренных каменщиков бежали в сельскую местность Западного Края. Изгнанные и заклейменные как предатели, отчаявшиеся ремесленники превратили свой профсоюз в воинственное Братство Справедливости."},{t="Скрытая рука",b="Противостояние знати и строителей было не просто делом опустевшей казны. За кулисами советница королевского двора леди Катрана Престор разжигала тлеющие угли раздора. Она убедила аристократов, что счета каменщиков грабительские, а работа некачественная, и в то же время подталкивала ремесленников к открытому мятежу. Парализовав Штормград внутренними распрями и отрезав снабжение Западного Края, черная драконица Ониксия успешно расколола королевство изнутри."}},faq={{q="Что такое Гильдия каменщиков?",a="Гильдия каменщиков — объединение людей-ремесленников, архитекторов и каменотесов под руководством главы гильдии Эдвина ван Клифа. Она прославилась восстановлением Штормграда и Крепости Стражей Пустоты после Второй войны.",al={"who were the stonemasons","stonemasons guild lore","what did the stonemasons do","кто такие каменщики","предания гильдии каменщиков","что делали каменщики"}},{q="Почему Гильдия каменщиков стала Братством Справедливости?",a="Когда восстановление Штормграда завершилось, Дом знати отказался платить жалованье гильдии из-за тяжелых долгов и придворных интриг. Начавшиеся протесты переросли в смертельные беспорядки, а изгнанные рабочие создали Братство Справедливости, чтобы силой вернуть отнятое богатство.",al={"why defias mad","why did stonemasons turn evil","origin of defias brotherhood","почему братство справедливости злится","почему каменщики стали злодеями","происхождение братства справедливости"}},{q="Кто был главой Гильдии каменщиков?",a="Эдвин ван Клиф был избранным главой гильдии. Под его руководством гильдия прославилась своей великолепной каменной кладкой, пока его не изгнали и он не основал Братство Справедливости.",al={"stonemasons guildmaster","vancleef guild","who led the stonemasons","глава гильдии каменщиков","гильдия ван Клифа","кто возглавлял каменщиков"}},{q="Какие значимые сооружения построили каменщики?",a="Гильдия построила Крепость Стражей Пустоты на краю Выжженных земель, чтобы наблюдать за Темным порталом, и полностью отстроила Штормград после Первой войны, включая Собор Света и Крепость Штормграда.",al={"what did stonemasons build","did stonemasons build stormwind","nethergarde keep builders","что построили каменщики","строили ли каменщики Штормград","строители крепости стражей пустоты"}},{q="Все ли каменщики присоединились к Братству Справедливости?",a="Присоединились не все. В частности, мастер Барос Алекстон порвал с Эдвином ван Клифом и остался в Штормграде, приняв должность городского архитектора, чем заслужил стойкую ненависть бывших соратников по гильдии.",al={"did all stonemasons become bandits","baros alexston stonemason","did any stonemasons stay in stormwind","все ли каменщики стали бандитами","барос алекстон каменщик","остались ли каменщики в штормграде"}},{q="Как погибла королева Тиффин Ринн?",a="Королева Тиффин была одной из немногих знатных особ, сочувствовавших рабочим, и пыталась успокоить собиравшиеся толпы во время беспорядков из-за жалованья. Брошенный из толпы снаряд поразил ее насмерть, навсегда лишив надежды на мирное примирение.",al={"tiffin wrynn death","how did varian's wife die","queen tiffin stone riot","смерть тиффин ринн","как умерла жена вариана","королева тиффин камень бунт"}},{q="Кем был Базиль Тредд в Гильдии каменщиков?",a="Базиль Тредд был доверенным помощником и главным лейтенантом Эдвина ван Клифа во времена гильдии. В отличие от ван Клифа, Тредда схватили после беспорядков, и он по сей день заперт в Тюрьме Штормграда.",al={"bazil thredd backstory","thredd stonemason","vancleef lieutenant","история базиля тредда","тредд каменщик","помощник ван Клифа"}}},fp="17,362,23.549.0,17.544.0,20.545.1,15.522.2,31.215.0,60.285.0,44.178.0,50.203.0,52.217.0,31.258.0,46.228.0"}
P.entries["topic:stormwind-guard"] = {n="Стража Штормграда",s="Стража Штормграда — это региональные гарнизоны и дозорные, которым поручено следить за соблюдением законов королевства и защищать окрестные земли. Из-за политического тупика и далеких военных кампаний сил катастрофически не хватает, и разбросанные по стране маршалы с трудом сдерживают гноллов, орков и бандитов в Элвиннском лесу и Красногорье.",h="Стража Штормграда — это региональные гарнизоны и дозорные, которым поручено следить за соблюдением законов...",kw={"garrison","goldshire","lakeshire","marshal dughan","marshal marris","marshal mcbride","stonewatch","stormwind guard","westbrook garrison","гарнизон","златоземье","приозерье","маршал дугхан","маршал маррис","маршал макбрайд","каменная стража","стража штормграда","гарнизон у западного ручья"},ang={["class:Warrior"]="От новобранцев Североземья до закаленных ветеранов Гарнизона у Западного ручья — люди-воины набираются опыта, выступая вместе с региональными маршалами против гноллов и бандитов.",["faction:Alliance"]="Стража Штормграда — передовая линия королевства, но то, что она бросила соседние поселения, обнажает глубокие политические трещины, угрожающие самому сердцу Альянса.",["profession:Blacksmithing"]="Гарнизон крепок настолько, насколько крепки его доспехи: в таких местах, как Приозерье, местные кузнецы расходуют все запасы железа лишь на то, чтобы клинки и щиты гарнизона оставались в исправности.",["race:Human"]="Для людей южных ферм синие табарды стражи когда-то означали полную безопасность, поэтому их внезапное исчезновение в Западном Крае и Сумеречном лесу кажется горьким предательством."},sec={{t="Щит Короны",b="Стража Штормграда, важная часть Армии Штормграда, патрулирует дороги, перекрестки и каменные сторожевые башни, которые скрепляют королевство. В отдаленных поселениях управление и оборона возложены на назначенных маршалов — таких как маршал Макбрайд в Долине Североземья, маршал Дугхан в Златоземье и маршал Маррис в Приозерье. Эти офицеры набирают рекрутов и поддерживают порядок, полагаясь на надежных бурых лошадей, известных выносливостью, чтобы преодолевать расстояния между укрепленными форпостами, например Гарнизоном у Западного ручья."},{t="Растянутая граница",b="Following the Third War, the Guard successfully kept Elwynn Forest safe and quiet, but recent years have brought crisis. With King Varian Wrynn vanished and the kingdom's standing army tied down abroad, regional garrisons have received little aid. At Westbrook Garrison, Deputy Rainer can barely hold the western border against Riverpaw gnolls and Defias thieves, forcing local commanders to outsource crucial security tasks and bounties to visiting adventurers."},{t="Покинутые земли",b="Настоящий кризис Стражи вызван решениями, принятыми в королевском дворе столицы. Под влиянием леди Катраны Престор королевство сочло содержание гарнизона в Западном Крае слишком дорогим, полностью вывело оттуда войска и позволило Братству Справедливости Эдвина ван Клифа захватить область. Сумеречный лес постигла та же участь: солдат вывели, к отчаянию Темнолесья, и брошенным жителям пришлось создать для самообороны разношерстный Ночной Дозор."},{t="Осада на востоке",b="Пока Сумеречный лес и Западный Край были брошены, корона сохраняла непрочное военное присутствие в Красногорье. И все же положение стражи отчаянное. Под натиском гноллов Темношкуров и орков Черной горы, спускавшихся из Пылающих степей, солдатам пришлось сдать Крепость Каменной Стражи. В Приозерье кузнец Вернер Осгуд расходует все железо лишь на снаряжение стражников, а измученные дозорные вглядываются в дорогу, ожидая 2-й батальон, который так и не приходит."}},faq={{q="Чем Стража Штормграда отличается от городской стражи?",a="Городская стража Штормграда охраняет порядок в столице за ее укрепленными стенами, а Стража Штормграда, часто организованная в региональные гарнизоны, отвечает за оборону внешних земель короны, патрулирование дорог и удержание сторожевых башен в Элвиннском лесу и Красногорье.",al={"stormwind guard vs city guard","are they the same guards","city guard","стража штормграда и городская стража","одна и та же стража","городская стража"}},{q="Почему в Западном Крае нет Стражи Штормграда?",a="Под влиянием советов леди Катраны Престор о государственных расходах королевский двор решил, что содержание слишком обременительно, и вывел все официальные гарнизоны. Полное отсутствие военной защиты позволило Братству Справедливости Эдвина ван Клифа быстро захватить фермы и дороги региона.",al={"why did guards leave westfall","westfall army","where are westfall guards","почему стража покинула западный край","армия западного края","где стража западного края"}},{q="Почему стража покинула Сумеречный лес?",a="Как и Западный Край, Сумеречный лес лишился королевских гарнизонов, отозванных в столицу из-за нехватки ресурсов. Оставшись без официальной защиты короны посреди растущей темной магии и ужасов, жителям Темнолесья пришлось создать собственное ополчение — Ночной Дозор, чтобы выжить.",al={"duskwood guards","why did stormwind abandon darkshire","darkshire garrison","стража сумеречного леса","почему штормград бросил темнолесье","гарнизон темнолесья"}},{q="Кто возглавляет местные гарнизоны?",a="Местной обороной управляют назначенные региональные маршалы. Маршал Макбрайд отвечает за Долину Североземья, маршал Дугхан командует силами, сосредоточенными в Златоземье, а маршал Маррис руководит отчаянной обороной Приозерья в Красногорье.",al={"who is in charge","guard leaders","marshals","кто главный","командиры стражи","маршалы"}},{q="Почему стражники в Приозерье в таком плохом состоянии?",a="Гарнизон Красногорья был выбит из Крепости Каменной Стражи вторгшимися орками Черной горы и местными гноллами. Оказавшись в ловушке в Приозерье, они остро нуждаются в снаряжении — кузнец Вернер Осгуд расходует почти все доступное железо лишь на перевооружение дозорных — и ждут обещанного подкрепления, которое королевские власти задерживают.",al={"redridge guards losing","what happened at stonewatch","lakeshire garrison trouble","стража красногорья проигрывает","что случилось в каменной страже","проблемы гарнизона приозерья"}},{q="Кто такой маршал Хаггард?",a="Маршал Хаггард — уважаемый командир в отставке, когда-то возглавлявший Стражу Штормграда в более спокойные дни, когда солдаты в свободное от службы время еще могли отправиться на юг и вместе выпить в Таверне «Алый ворон» в Темнолесье.",al={"marshal haggard lore","retired marshal","old guard marshal","предания о маршале хаггарде","маршал в отставке","старый маршал стражи"}}},fp="15,328,19.511.0,23.462.0,25.450.1,21.470.0,70.281.0,50.302.0,33.279.0,30.248.0,50.327.0,23.209.0"}
P.entries["topic:stormwind-kingdom"] = {n="Штормград (королевство)",s="Королевство Штормград — самое южное и ныне главное человеческое государство на Азероте, владеющее Элвиннским лесом, Западным Краем, Сумеречным лесом и Красногорьем. Разграбленное и разрушенное в Первую войну, оно было отстроено кровью и трудом после Второй и стало военным и культурным центром Альянса после трагической гибели Лордерона на севере. Сегодня королевство осаждено изнутри и снаружи: им правит десятилетний король Андуин Ринн под присмотром верховного лорда Болвара Фордрагона, пока коронованный монарх остается пропавшим.",h="Королевство Штормград — самое южное и ныне главное человеческое государство на Азероте, владеющее Элвиннским...",kw={"anduin","azeroth","bolvar","elwynn","first war","house of nobles","prestor","stonemasons","stormwind","varian","wrynn","андуин","азерот","болвар","элвиннский лес","первая война","дом знати","престор","каменщики","штормград","вариан","ринн"},ang={["class:Paladin"]="Королевство чтит древние священные традиции Церкви Священного Света и наследие Серебряной Длани, приютив освященные ордена в Соборе Света.",["class:Rogue"]="Ожесточенные внутренние распри Штормграда и тень восстания Братства Справедливости наполнили его закоулки, канализацию и сельскую местность хищными карманниками и политическими шпионами.",["faction:Alliance"]="Как главная военная и экономическая опора современного Альянса, Штормград предоставляет кров, руководство и ресурсы союзникам — дворфам, гномам и ночным эльфам.",["race:Human"]="Штормград — бьющееся сердце человечества и его последний суверенный оплот после гибели Лордерона, Альтерака и Даларана на севере."},sec={{t="Наследие непокорности",b="Штормград был основан более тысячи лет назад потомками древней Араторской империи, которые отправились на юг за скалы Каз Модана, в плодородные лесистые долины. Веками северные королевства считали Штормград глухой деревенской провинцией и даже игнорировали отчаянные мольбы о помощи во время войны с гноллами. Под началом короля Баратена Ринна королевство в одиночку победило гноллов, а позже и троллей Гурубаши, создав культуру, гордую своей самостоятельностью и верой в Свет."},{t="Пепел и возрождение",b="Эта независимость едва не была уничтожена, когда Орочья Орда хлынула через Темный портал. Штормград сгорел дотла в Первую войну, а король Ллейн был убит. Уцелевшие жители бежали на север через Великое море под началом сэра Андуина Лотара, объединив северные королевства в Альянс Лордерона. Когда орочья угроза была сокрушена во Вторую войну, беженцы вернулись домой и наняли Гильдию каменщиков, чтобы отстроить великолепную столицу из белого камня и синих знамен. Когда Плеть уничтожила Лордерон в Третью войну, Штормград стал величайшим уцелевшим оплотом человечества."},{t="Расколотое королевство",b="Под своими высокими башнями Штормград с трудом управляет обширными южными владениями. Хотя Элвиннский лес остается относительно безопасным, в соседних областях, таких как Западный Край, кишат разбойники, Красногорье постоянно страдает от набегов орков и гноллов, а темные чащи Сумеречного леса вышли из-под власти королевства. Ожесточенный спор между Домом знати и каменщиками привел к жестокому бунту Братства Справедливости, унесшему жизнь королевы Тиффин, и лишившиеся работы строители подняли открытый мятеж по всем провинциям."},{t="Пустой трон",b="Нестабильность королевства усугубилась внезапным и тихим исчезновением короля Вариана Ринна по пути на дипломатическую встречу с Ордой в Тераморе. Чтобы сохранить хрупкий порядок, корона была передана его десятилетнему сыну Андуину Ринну, а верховный лорд Болвар Фордрагон был назначен лордом-регентом. Однако королевская власть разделена и парализована: Дом знати, находящийся под сильным влиянием загадочной леди Катраны Престор, постоянно накладывает вето на отправку войск, оставляя местные города защищаться самостоятельно, пока в Крепости Штормграда множатся опасные тайны."}},faq={{q="Кто сейчас правит Штормградом?",a="Формально корона принадлежит королю Андуину Ринну, взошедшему на трон десятилетним ребенком. Поскольку он несовершеннолетний, реальная государственная власть принадлежит верховному лорду Болвару Фордрагону как лорду-регенту, при сильном влиянии и надзоре со стороны леди Катраны Престор и Дома знати.",al={"who is king of stormwind","current ruler","who runs stormwind","king of stormwind","кто король штормграда","нынешний правитель","кто управляет штормградом","король штормграда"}},{q="Что случилось с королем Варианом Ринном?",a="Король Вариан покинул Штормград в секретное дипломатическое плавание в Терамор, чтобы договориться о мирных отношениях с Ордой. По пути он загадочным образом исчез. Его судьба остается тщательно охраняемой государственной тайной, чтобы жители королевства и внешние соперники не погрузились в хаос.",al={"where is varian","varian missing","what happened to the king","varian wrynn backstory","где вариан","вариан пропал","что случилось с королем","предыстория вариана ринна"}},{q="Почему Штормград был разрушен в прошлом?",a="Штормград был первым человеческим государством, с которым столкнулась Орочья Орда, вторгшаяся через Темный портал в Первую войну. Несмотря на упорную оборону под началом короля Ллейна и сэра Андуина Лотара, город был взят, разграблен и сровнен с землей, и уцелевшим жителям пришлось эвакуироваться на север морем в Лордерон.",al={"first war stormwind","fall of stormwind","when did stormwind burn","stormwind destroyed","первая война штормград","падение штормграда","когда сгорел штормград","штормград разрушен"}},{q="Почему в Западном Крае, Красногорье и Сумеречном лесу нет королевских солдат?",a="Королевская армия растянута и парализована придворной политикой. Леди Катрана Престор и Дом знати часто блокируют просьбы о переброске гарнизонов за пределы Элвиннского леса, утверждая, что средства столицы и оборонительные силы нельзя тратить на охрану окраин, и ополчениям вроде Народного ополчения и Ночного Дозора приходится сражаться в одиночку.",al={"why no soldiers","why no army help","abandoned towns","outlying towns undefended","почему нет солдат","почему армия не помогает","брошенные города","беззащитные окраины"}},{q="Какие земли принадлежат Королевству Штормград?",a="Исторически Штормград правит южным континентом Азерота, включая Элвиннский лес, Красногорье, Западный Край и Сумеречный лес (прежде Светлую рощу). Раньше он также держал пограничные посты к югу, до северной части Тернистой долины.",al={"stormwind borders","stormwind lands","what lands are stormwind","границы штормграда","земли штормграда","какие земли принадлежат штормграду"}},{q="Почему каменщики выступили против Штормграда?",a="После того как Гильдия каменщиков превратила Штормград в шедевр из белого камня, она предъявила счет. Под влиянием придворных интриг Дом знати отказался платить полностью, а каменщики не пошли на компромисс. Начавшиеся в городе бунты стали смертельными: погибла королева Тиффин Ринн, а гильдия была изгнана и стала вне закона — Братством Справедливости.",al={"why defias mad","stonemasons riot","defias backstory","why did builders rebel","почему братство справедливости злится","бунт каменщиков","предыстория братства справедливости","почему строители восстали"}}},fp="19,600,20.493.0,21.598.0,17.522.1,17.558.2,34.297.0,35.304.0,40.302.0,64.350.0,51.256.0,47.362.0"}
P.entries["topic:syndicate"] = {n="Синдикат",s="Синдикат — широко распространенная преступная организация людей, основанная и возглавляемая лишенными владений дворянами павшего королевства Альтерак. Действуя из укрепленных оплотов в Альтеракских горах, Предгорьях Хилсбрада и среди руин Крепости Стромгард, они ведут бескомпромиссную войну и против Альянса, и против Орды, стремясь вернуть утраченную аристократию.",h="Синдикат — широко распространенная преступная организация людей, основанная и возглавляемая лишенными...",kw={"aliden perenolde","alterac","bandanas","durnholde keep","falconcrest","ravenholdt","strahnbrad","stromgarde","syndicate","uplands","алиден перенольд","альтерак","банданы","крепость дарнхольд","фалконкрест","черный ворон","странбрад","стромгард","синдикат","высокогорье"},ang={["class:Rogue"]="Гильдия Черного Ворона хорошо платит ворам, готовым пробраться за линию врага и красть эмблемы прямо у разбойников Синдиката, играя на их внутренней паранойе.",["faction:Alliance"]="Агенты Синдиката убили прежнего мирового судью Южнобережья и неуклонно толкают осажденное ополчение Стромгарда к полному истреблению на Нагорье Арати.",["faction:Horde"]="Вождь Тралл и леди Сильвана держат награды за голову Синдиката и посылают разведчиков уничтожать его лагеря и возвращать похищенные реликвии.",["race:Orc"]="Синдикат видит в вашем народе зверей, уготованных для цепей и лагерей, поэтому освобождение плененных собратьев в Странбраде и Дарнхольде — срочное дело чести."},sec={{t="Павшая знать",b="Когда королевство Альтерак бесславно пало из-за предательства короля Эйдена Перенольда во время Второй войны, его аристократия лишилась земель и титулов. Не желая мириться с изгнанием, уцелевшие альтеракские дворяне объединились под началом сына покойного короля, принца Алидена Перенольда. Надев характерные оранжевые банданы и пополнив ряды наемными головорезами, разбойниками с большой дороги и доморощенными чародеями, они создали Синдикат. Внешнему миру они кажутся обычными бандитами: грабят караваны, устраивают засады на путников и занимаются вымогательством. На деле их преступный промысел служит лишь тому, чтобы финансировать организованные попытки отвоевать родовые земли и подчинить окрестные края."},{t="Оплоты севера",b="Синдикат прочно закрепился на севере Лордерона. В заснеженных Альтеракских горах он укрепил разрушенный город Странбрад и разбил лагеря по всему Высокогорью и в Овчарне Дандреда. На юге он удерживает рушащиеся остатки Крепости Дарнхольд в Предгорьях Хилсбрада и использует ее как плацдарм для набегов на Южнобережье и нападений на пути снабжения. Дальше на восток, за Стеной Торадина, лорд Фалконкрест командует оккупационной армией Синдиката в исторических руинах Крепости Стромгард в Арати и ведет бои с потрепанным ополчением Стромгарда за власть над Нагорьем Арати."},{t="Враги на всех фронтах",b="В отличие от обычных преступников, Синдикат питает грандиозные идеологические амбиции, из-за которых его ненавидит почти каждая местная фракция. Альянс они считают смертельным врагом, укравшим их законное наследие, и часто выбирают целью должностных лиц Южнобережья, например Мирового судью Генри Малеба. К Орде их отношение откровенно расистское: следуя философии Аэделаса Блэкмура, они видят в орках лишь животных, годных для рабского труда, и стремятся восстановить систему лагерей для интернированных. Отрекшиеся Сильваны Ветрокрылой казнят захваченных членов Синдиката на месте, а тайная гильдия воров Черного Ворона ведет постоянную теневую войну против их неряшливых и высокомерных агентов."},{t="Марионетки Совета Теней",b="Хотя благородные главари Синдиката верят, что борются за превосходство людей и свое право по рождению, ими изнутри управляют более темные хозяева. Культисты Пробуждения Аргуса глубоко проникли в верхушку Синдиката и подтолкнули таких, как лорд Фалконкрест, к захвату Крепости Стромгард. Вместо того чтобы служить интересам людей, Пробуждение Аргуса подчиняется Совету Теней в Джеденаре в Оскверненном лесу и использует армии и захваченные земли Синдиката как смертный авангард, расчищающий путь Пылающему Легиону."}},faq={{q="Что представляет собой Синдикат?",a="Синдикат — большая преступная организация, состоящая из лишенных владений дворян, разбойников и наемников, выходцев из павшего королевства Альтерак. Ею руководят изгнанные аристократы, такие как принц Алиден Перенольд и лорд Фалконкрест; они прибегают к грабежам на дорогах, убийствам и военной оккупации, пытаясь восстановить Альтерак.",al={"what is the syndicate","syndicate background","who are these guys in orange","что такое синдикат","история синдиката","кто эти парни в оранжевом"}},{q="Почему Синдикат ненавидит Альянс?",a="Во время Второй войны Альтерак предал Альянс Лордерона. В наказание Альянс разделил королевство и лишил его дворян земель. Лидеры Синдиката считают Альянс смертельным врагом и активно вредят городам Альянса, торговым караванам и военным гарнизонам, таким как Крепость Стромгард.",al={"why does syndicate attack alliance","syndicate alliance relationship","alterac vs alliance","почему синдикат нападает на альянс","синдикат и альянс","альтерак против альянса"}},{q="Почему Синдикат захватывает орков и обращает их в рабство?",a="Синдикат разделяет жестокие взгляды бывшего коменданта Дарнхольда Аэделаса Блэкмура и видит в орках диких зверей, пригодных лишь для даровой работы. Принц Алиден Перенольд стремился восстановить систему лагерей Альянса и использовать плененных в Предгорьях Хилсбрада и Альтераке орков как рабочую силу.",al={"syndicate orc slaves","why are orcs in cages in strahnbrad","syndicate slavery","орки рабы синдиката","почему орки в клетках в странбраде","рабство синдиката"}},{q="Каковы отношения Синдиката с Черным Вороном?",a="Черный Ворон — престижная гильдия профессиональных убийц и воров в Альтеракских горах, считающая Синдикат любительской, недисциплинированной шайкой. Чтобы подорвать Синдикат, Черный Ворон нанимает разбойников красть у его членов эмблемы: потеряв их, опозоренные агенты Синдиката безжалостно уничтожаются собственным руководством.",al={"ravenholdt vs syndicate","why does ravenholdt hate syndicate","syndicate emblems","черный ворон и синдикат","почему черный ворон ненавидит синдикат","эмблемы синдиката"}},{q="Кто на самом деле дергает за ниточки Синдиката?",a="Хотя дворяне считают, что борются за свои утраченные титулы, организацией тайно управляет секта чернокнижников под названием «Пробуждение Аргуса». Ее возглавляют такие фигуры, как Нагаз и Марез Клобук, а сама секта служит Совету Теней в Джеденаре, используя территориальные успехи Синдиката, чтобы подготовить регион к приходу Пылающего Легиона.",al={"who leads the syndicate","argus wake syndicate","shadow council syndicate","кто руководит синдикатом","пробуждение аргуса синдикат","совет теней синдикат"}},{q="Где находятся главные оплоты Синдиката?",a="Синдикат широко действует в трех зонах: в Альтеракских горах (Странбрад и Овчарня Дандреда), в Предгорьях Хилсбрада (Крепость Дарнхольд) и на Нагорье Арати (Северное поместье), где он также занимает огромный квартал Крепости Стромгард под началом лорда Фалконкреста.",al={"where are syndicate bases","syndicate locations","where to find syndicate","где базы синдиката","места синдиката","где найти синдикат"}}},fp="9,361,15.710.0,24.623.0,21.687.0,29.543.2,22.328.0,41.322.0,48.330.0,53.345.0,55.327.2,46.279.0"}
P.entries["topic:tauren"] = {n="Таурен",s="Таурены, или шу'хало на их родном языке, — благородная раса кочевых быкоподобных гуманоидов, обитающая в центральном Калимдоре. Глубоко преданные Матери-Земле, шаманизму и миру природы, они были почти истреблены безжалостными кланами кентавров, прежде чем заключили союз с Новой Ордой Тралла. Ныне, объединившись под началом верховного вождя Кэрна Кровавого Копыта, они обосновались на зеленых равнинах Мулгора и высоких плато Громового Утеса.",h="Таурены, или шу'хало на их родном языке, — благородная раса кочевых быкоподобных гуманоидов, обитающая в...",kw={"barrens","cairne bloodhoof","centaur","earth mother","hamuul runetotem","kodo","magatha grimtotem","mulgore","shu'halo","tauren","thunder bluff","степи","кэрн кровавое копыто","кентавр","мать-земля","хамуул рунический тотем","кодо","магата зловещий тотем","мулгор","шу'хало","таурен","громовой утес"},ang={["class:Druid"]="Через верховного друида Хамуула Рунического Тотема друиды-таурены работают бок о бок с ночными эльфами Круга Кенария, отложив фракционные распри, чтобы исцелять землю и защищать Изумрудный Сон.",["class:Shaman"]="Шаманские традиции тауренов — одни из древнейших в Азероте, и их учения помогли оркам заново обрести священную связь со стихиями после демонической порчи прошлых войн.",["faction:Horde"]="Таурены дают Орде нравственный ориентир и глубокие духовные корни, умеряя агрессивные порывы орков и троллей древней мудростью и честью.",["race:Tauren"]="Вы, шу'хало, из древних кочевий пришли к процветающей родине в Мулгоре, обретенной благодаря нерушимому братству Кэрна и Тралла."},sec={{t="Кочевники Степей",b="Бесчисленные поколения таурены жили сезонными кочевниками на засушливых равнинах Степей, охотились на великих кодо и прислушивались к голосу Матери-Земли. Однако их мирные скитания омрачали века жестокого кровопролития. Свирепые племена кентавров, рожденные от трагического союза Заетара и принцессы Тередрас, вели против них безжалостную войну на истребление. Без укрепленной родины и не желая вести бесконечную войну, племена тауренов были доведены до грани уничтожения, и само их существование висело на волоске."},{t="Новая Орда и Громовой Утес",b="Спасение пришло из неожиданного союза за морем. Во время Третьей войны вождь Кэрн Кровавое Копыто встретил вождя Тралла и его недавно прибывших орков. Увидев родственный дух чести и тягу к шаманскому наследию, два лидера объединили силы. При помощи Орды таурены разгромили разорявших их кентавров и заняли тучные укрытые луга Мулгора. На его продуваемых ветрами мезах Кэрн возвел город Громовой Утес. Из благодарности за спасение таурены вместе с Ордой отправились к Горе Хиджал отражать Пылающий Легион."},{t="Духовные хранители и внутренние противоречия",b="В Орде таурены служат умиротворяющей, миролюбивой совестью. Их мастерство в обращении с природой и стихиями помогло возродить шаманизм орков, а верховный друид Хамуул Рунический Тотем поддерживает редкие дипломатические и духовные связи с друидами ночных эльфов, чтобы исследовать растущую порчу в Изумрудном Сне. Но единство остается хрупким. Хотя большинство племен чтит мудрость Кэрна, ксенофобское и безжалостное племя Зловещего Тотема во главе с коварной старейшиной Магатой живет в Громовом Утесе и тайно замышляет захватить власть и повести шу'хало к превосходству."}},faq={{q="Почему таурены присоединились к Орде?",a="Таурены были на грани истребления безжалостными кентаврами Степей. Вождь Тралл и его орки прибыли и сражались бок о бок с Кэрном Кровавым Копытом, отбросили кентавров и помогли тауренам закрепиться в Мулгоре. Связанный глубокой честью и общими духовными ценностями, Кэрн из благодарности поклялся, что его народ будет верен Новой Орде.",al={"why join horde","tauren horde alliance","why are tauren in horde","почему таурены в орде","таурены орда альянс","зачем таурены вступили в орду"}},{q="Кто возглавляет тауренов?",a="Тауренов возглавляет верховный вождь Кэрн Кровавое Копыто, мудрый и почтенный предводитель племени Кровавого Копыта. Уважаемый за силу и взвешенные решения, он объединяет разрозненные племена из своей резиденции на вершине Громового Утеса, а помогают ему верховный друид Хамуул Рунический Тотем и Мудрая старуха Магата Зловещий Тотем.",al={"tauren leader","tauren chieftain","who rules thunder bluff","лидер тауренов","вождь тауренов","кто правит громовым утесом"}},{q="Что такое Мать-Земля?",a="Мать-Земля — центральное божество верований тауренов. Шу'хало верят, что она создала мир, солнце и луну, и почитают ее образом жизни, глубоко созвучным природному равновесию, сезонным кочевьям, охоте и уважению к стихиям.",al={"earthmother","who is the earth mother","tauren religion","мать земля","кто такая мать-земля","религия тауренов"}},{q="Почему таурены ненавидят кентавров?",a="Кентавры охотились на тауренов ради забавы и веками воевали с ними по всему центральному Калимдору. Считая мирную духовность тауренов слабостью, кентавры гнали их с места на место и едва не привели шу'хало к полному вымиранию, пока не вмешались орки.",al={"tauren centaur war","centaur feud","война тауренов и кентавров","вражда с кентаврами"}},{q="Могут ли таурены быть друидами?",a="Да. Хотя друидизм угас в их культуре в долгих кочевых войнах с кентаврами, таурены изначально обучились магии природы у Кенария в древние времена. Недавно верховный друид Хамуул Рунический Тотем возродил эти учения с помощью ночных эльфов, и друиды-таурены стали одним из столпов Круга Кенария.",al={"tauren druid lore","how did tauren become druids","предания о друидах тауренах","как таурены стали друидами"}},{q="Все ли таурены преданы Кэрну Кровавому Копыту?",a="Большинство племен чтит Кэрна, но племя Зловещего Тотема остается ожесточенным исключением. Во главе с Магатой Зловещим Тотемом они считают тауренов выше всех других рас и презирают союз Кэрна с Ордой, тихо стремясь подорвать его мирное правление.",al={"grimtotem loyalty","tauren civil war","верность зловещего тотема","гражданская война тауренов"}}},fp="6,462,21.570.0,31.574.0,41.579.1,34.343.0,21.294.0,25.253.0,35.285.0,21.327.0,41.255.0"}
P.entries["topic:terenas-menethil-ii"] = {n="Теренас Менетил II",s="Король Теренас Менетил II был почтенным правителем Лордерона, который правил более пяти десятилетий и создал первый Альянс Лордерона во время Второй войны. Известный как мудрый и дипломатичный лидер, он защитил человечество от первого вторжения Орды и приютил юного принца Вариана Ринна. Его трагическое убийство руками собственного павшего сына, принца Артаса, прямо привело к гибели Лордерона от Плети.",h="Король Теренас Менетил II был почтенным правителем Лордерона, который правил более пяти десятилетий и создал...",kw={"alliance of lordaeron","arthas","capital city","frostmourne","lordaeron","menethil","second war","terenas","third war","uther","альянс лордерона","артас","столица","ледяная скорбь","лордерон","менетил","вторая война","теренас","третья война","утер"},ang={["class:Paladin"]="Теренас вместе с архиепископом Алонсусом Фаолом и Утером Светоносным создавал Рыцарей Серебряной Длани и направил в орден собственного сына.",["faction:Alliance"]="Нынешний Великий Альянс ведет свое происхождение от коалиции, созданной Теренасом и Андуином Лотаром для отражения Старой Орды во Второй войне.",["race:Human"]="Люди помнят короля Теренаса как легендарного патриарха, объединившего семь королевств вопреки невероятным трудностям, а потому его внезапное предательство и гибель от руки собственного сына остаются национальной трагедией.",["race:Undead"]="Для Отрекшихся, некогда живших в Столице, Теренас был последним живым государем, чье падение обрекло королевство на гибель от Плети."},sec={{t="Создатель Альянса",b="Когда беженцы из Штормграда во главе с сэром Андуином Лотаром прибыли на север, король Теренас Менетил II откликнулся на их призыв. Созвав монархов раздробленных человеческих королевств и посланников Стальгорна и Кель'Таласа, Теренас организовал создание Альянса Лордерона. Вместо того чтобы взять военное командование на себя, он мудро предложил назначить Лотара верховным командующим, впервые за тысячелетия объединив королевства людей ради победы над Старой Ордой."},{t="Тяготы победы",b="После Второй войны Теренас настоял на том, чтобы выживших орков поместили в лагеря для интернированных, а не казнили, полагая, что мир удастся сохранить, если их демоническая ярость утихнет. Это гуманное, но дорогостоящее решение обернулось огромными налогами для союзников Лордерона. Гилнеас укрылся за Стеной Седогрива, Стромгард отделился из-за политических споров, а высшие эльфы ушли совсем, оставив Теренаса нести бремя с распадающейся коалицией."},{t="Падение трона",b="На закате жизни Теренас столкнулся с растущими восстаниями орков под предводительством Тралла, слухами о северных культах смерти и таинственной чумой. Когда странствующий пророк предостерег короля, что нужно покинуть Лордерон и бежать за море в Калимдор, Теренас счел его безумцем. Вскоре принц Артас вернулся из северного похода как победитель. Во время королевских торжеств Артас преклонил колено перед отцом, обнажил рунный клинок Ледяная Скорбь и пронзил сердце Теренаса, навсегда разрушив королевство."}},faq={{q="Кем был король Теренас Менетил II?",a="Он был добрым и почитаемым правителем королевства Лордерон. Правя более пятидесяти лет, он стоял в центре северной политики, основал Альянс Лордерона для борьбы с Ордой во Второй войне и управлял из Столицы вплоть до своего убийства.",al={"who is terenas","terenas menethil","king of lordaeron","кто такой теренас","теренас менетил","король лордерона"}},{q="Как погиб Теренас?",a="Теренаса убил в его собственном тронном зале сын, принц Артас Менетил. Поддавшись безумию и порче из-за рунного клинка Ледяная Скорбь во время похода в Нордскол, Артас вернулся в Столицу под видом победителя и пронзил отца в сердце.",al={"how did terenas die","arthas kills dad","terenas death","как погиб теренас","артас убивает отца","смерть теренаса"}},{q="Каковы были отношения Теренаса со Штормградом?",a="Теренас сыграл ключевую роль в выживании Штормграда. Когда южное королевство пало в Первой войне, он дал приют его выжившим и воспитывал принца Вариана Ринна вместе с собственным сыном Артасом, относясь к юному Вариану как ко второму сыну, пока Штормград не удалось отвоевать и отстроить.",al={"terenas and stormwind","terenas and varian","did terenas help stormwind","теренас и штормград","теренас и вариан","помог ли теренас штормграду"}},{q="Почему Альянс Лордерона распался при его правлении?",a="После Второй войны Теренас решил не казнить пленных орков, а содержать их в лагерях для интернированных. Огромные финансовые затраты на эти лагеря вызвали резкое возмущение среди государств-членов альянса. Гилнеас построил Стену Седогрива, чтобы изолироваться, Стромгард вышел из союза из-за разногласий по вопросам политики, а эльфы Кель'Таласа отошли от него полностью.",al={"why did alliance break","why did kingdoms leave lordaeron","internment camp taxes","почему распался альянс","почему королевства покинули лордерон","налоги на лагеря"}},{q="Знал ли Теренас о Чуме нежизни?",a="Теренас знал о странных культах и распространяющейся болезни на севере, но недооценил угрозу. Даларан настаивал на строгом карантине северных городов, однако Теренас колебался, опасаясь новых страданий своего народа. Он отправил принца Артаса и Утера Светоносного на разведку, не подозревая о ловушке, которая их ждала.",al={"did terenas know about plague","terenas plague response","знал ли теренас о чуме","реакция теренаса на чуму"}},{q="Почему Теренас не послушал таинственного пророка?",a="Когда закутанный в плащ пророк явился в зал совета и умолял эвакуировать жителей Лордерона на запад, в Калимдор, Теренас счел его безумным фанатиком. Теренас верил, что его армии, паладины и крепкое королевство выдержат любые испытания, и тем самым предрешил гибель королевства.",al={"terenas and prophet","medivh and terenas","why didnt terenas flee","теренас и пророк","медив и теренас","почему теренас не бежал"}}},fp="19,422,25.480.0,22.476.0,22.519.2,33.271.0,20.303.0,47.287.0,61.347.0,45.352.0,52.296.0"}
P.entries["topic:third-war"] = {n="Третья война",s="Третья война — апокалиптический конфликт, всего несколько лет назад разрушивший прежний мировой порядок. Развязанная Пылающим Легионом и осуществленная через Чуму нежизни Короля-лича, она привела к падению Королевства Лордерон и почти полному уничтожению Кель'Таласа, а завершилась отчаянной общей битвой у горы Хиджал.",h="Третья война — апокалиптический конфликт, всего несколько лет назад разрушивший прежний мировой порядок.",kw={"archimonde","arthas","hyjal","mannoroth","medivh","nordrassil","scourge","stratholme","terenas","third war","архимонд","артас","хиджал","маннорот","медив","нордрассил","плеть","стратхольм","теренас","третья война"},ang={["class:Paladin"]="Рыцари Серебряной Длани были разрознены во время войны, когда Артас распустил их, убил Утера Светоносного и превратил их святые залы в склепы.",["faction:Alliance"]="Падение Лордерона сместило центр руководства Альянса на юг, в Штормград и Стальгорн, а выжившие смотрят на север с жгучим желанием вернуть родину.",["faction:Horde"]="Для Орды Тралла война стала горнилом искупления: Громмаш Адский Крик убил Маннорота, навсегда разорвав демоническое проклятие крови, что позволило оркам построить суверенное государство в Калимдоре.",["race:NightElf"]="Защита Нордрассила стоила кальдораям бессмертия и впервые за десять тысяч лет открыла их древние земли внешнему миру.",["race:Undead"]="Отрекшиеся — живые памятники ужасу войны: жители Лордерона, убитые чумой и вынужденные служить Плети, пока не освободились и не завладели Подгородом."},sec={{t="Чума и принц",b="Война началась незаметно на севере Лордерона, под видом смертоносной болезни, которую переносило зараженное зерно, распространяемое из Андорала. Отравленный урожай не просто убивал: он поднимал жертв голодными вурдалаками, подчиненными воле Короля-лича. Принц Артас Менетил бросился останавливать заразу вместе с чародейкой Кирин-Тора Джайной Праудмур. Ослепленный горем, яростью и манипуляциями повелителей ужаса, Артас уничтожил зараженных жителей Стратхольма, а затем преследовал врага в ледяных пустошах Нордскола. Там он взял проклятый рунный клинок Ледяная Скорбь, отказавшись от своей души. Он вернулся на юг лишь затем, чтобы убить отца, короля Теренаса, и отдать Лордерон в руки Плети."},{t="Вторжение Легиона",b="Обретя силу смерти, Артас разгромил эльфийское королевство Кель'Талас, чтобы воскресить некроманта Кел'Тузада у Солнечного Колодца. Затем армия нежити осадила Даларан и захватила книги заклинаний, необходимые для призыва властелина демонов Архимонда в Азерот. Когда командующий Пылающего Легиона ступил на землю смертных, Даларан был стерт с лица земли в арканном буйстве разрушения. Плеть сыграла свою роль авангарда, и Пылающий Легион обратил взор на вечную силу по ту сторону Великого моря."},{t="Бегство на запад и гора Хиджал",b="Следуя загадочным предостережениям таинственного Пророка, позже оказавшегося искупившим вину Хранителем Медивом, вождь Тралл повел Новую Орду через Великое море, а леди Джайна Праудмур эвакуировала уцелевших беженцев Альянса. В древнем Калимдоре пришельцы столкнулись с обособленными ночными эльфами, прежде чем все три стороны осознали нависшую над ними величайшую угрозу. Под Мировым Древом Нордрассил на вершине горы Хиджал смертные встали вместе против невероятных сил. Архимонд был уничтожен древними духами, когда достиг древа, что сокрушило авангард Легиона и положило конец войне."},{t="Израненный мир",b="Хотя Архимонд пал, мир 25 года после открытия Темного портала хрупок и омрачен потерями. Альянса Лордерона больше нет, и южный Альянс держится на королевствах Штормграда и Стальгорна, а Лордерон гниет, превратившись в Чумные земли. В Калимдоре Орда Тралла основала Дуротар, но напряженность с недавно примкнувшими ночными эльфами остается взрывоопасной. Плеть сохраняется в северных руинах, а освобожденная нежить — Отрекшиеся — теперь владеет катакомбами Столицы и ведет борьбу за выживание и против бывших хозяев, и против мстительных крестоносцев."}},faq={{q="Когда произошла Третья война?",a="Третья война началась в 20 году после открытия Темного портала со вспышки Чумы нежизни в Лордероне и завершилась в 21 году битвой у горы Хиджал. В нынешнем 25 году ее разрушения всего четыре года позади, поэтому руины еще свежи, а почти каждый взрослый сражался в ней или потерял в ней родных.",al={"when was the third war","how long ago was the war","third war dates","когда была третья война","как давно была война","даты третьей войны"}},{q="Чем Третья война отличалась от Первой и Второй?",a="Первая и Вторая войны были в основном борьбой Старой Орды и королевств Альянса. Третья война стала глобальным демоническим вторжением, разрушившим целые государства. Смертные сражались не только друг с другом, но и с космической угрозой Пылающего Легиона и его нежитью Плети на трех континентах, что вынудило заклятых врагов заключить отчаянное перемирие.",al={"difference between third war and second","why was third war different","horde vs alliance third war","разница между третьей и второй войной","чем отличалась третья война","орда против альянса третья война"}},{q="Что случилось с Королевством Лордерон?",a="Лордерон был уничтожен изнутри. Культ Проклятых заразил запасы зерна региона Чумой нежизни, убив население и подняв его чудовищами. Собственный наследный принц Артас поддался порче, убил отца, короля Теренаса II, и отдал сломленное королевство Плети.",al={"fate of lordaeron","why is lordaeron destroyed","what happened to terenas","судьба лордерона","почему лордерон уничтожен","что случилось с теренасом"}},{q="Кто был Пророк, призвавший всех отправиться в Калимдор?",a="Пророком был Медив, Последний Хранитель Тирисфаля. Возвращенный, чтобы искупить свою роль в открытии Темного портала, Медив странствовал в облике скитальца в вороньем плаще, предупреждая правителей, что Лордерон обречен, и призывая их объединиться на забытом континенте Калимдор.",al={"who was the prophet","raven prophet","medivh third war","кто был пророк","пророк-ворон","медив третья война"}},{q="Почему ночные эльфы теперь входят в Альянс?",a="Десять тысячелетий ночные эльфы жили в строгой изоляции. Третья война вернула Легион в их священные леса и заставила их пожертвовать бессмертием, чтобы убить Архимонда у Мирового Древа. Перед лицом резко изменившегося мира, растущих споров за ресурсы с Ордой Тралла и остатков порчи Плети они отказались от уединения и заключили союз с народами Восточных королевств.",al={"why did night elves join alliance","night elves third war","kaldorei joining alliance","почему ночные эльфы вступили в альянс","ночные эльфы третья война","кальдораи вступили в альянс"}},{q="Как Орда спаслась от войны в Лордероне?",a="Вождь Тралл поверил пророческим снам Медива. Он собрал освобожденные кланы из лагерей для интернированных, совершил набеги на человеческие порты, чтобы захватить парусные корабли, и бежал через Великое море, прежде чем Плеть или Легион полностью поглотили Лордерон.",al={"how did thrall leave lordaeron","orcs sailing west","horde kalimdor flight","как тралл покинул лордерон","орки плывут на запад","бегство орды в калимдор"}}},fp="9,351,25.705.0,26.524.0,31.600.0,15.552.0,30.312.0,63.357.0,42.324.0,59.287.0,49.417.0,46.249.0"}
P.entries["topic:titan"] = {n="Титан",s="Титаны — изначальная раса исполинских богоподобных существ, которые странствуют по космосу, наводя порядок и создавая миры. В глубокой древности они пришли на Азерот, чтобы победить хаотичных Древних богов, возвести огромные наземные сооружения и взрастить жизнь, а затем отправились обратно в Великую Тьму.",h="Титаны — изначальная раса исполинских богоподобных существ, которые странствуют по космосу, наводя порядок и...",kw={"aman'thul","earthen","eonar","khaz'goroth","makers","norgannon","order","pantheon","titan","аман'тул","земнорожденные","эонар","каз'горот","создатели","норганнон","порядок","пантеон","титан"},ang={["class:Mage"]="Тайная магия — основа жизненной силы титанов, и ее упорядоченные принципы напрямую восходят к структурным чарам, которыми Пантеон опутал мир.",["profession:Mining"]="Шахтеры копают глубоко в недрах земли и часто находят нетронутые жилы металла, выкованного титанами, и архитектурные основы, существовавшие еще до начала письменной истории.",["race:Dwarf"]="Титанов почитают как божественных Создателей. Раскрыть свое происхождение через титанические реликвии — главная задача Лиги исследователей и короля Магни Бронзоборода.",["race:Gnome"]="Гномы наследуют механическое наследие, восходящее к творениям титанов, чем объясняется их природная тяга к часовым механизмам и раскопкам."},sec={{t="Зодчие космоса",b="Титаны — космические великаны, созданные из изначальной материи и тайной магии, воплощение сил порядка и созидания. Во время странствий по Великой Тьме они искали спящие миры, чтобы взрастить их: поднимали континенты, усмиряли хаотичные силы стихий и создавали жизнь. Чтобы поддерживать равновесие, они создали могучих стражей из камня, железа и морской воды, которые присматривали за их творениями."},{t="Упорядочивание Азерота",b="Давным-давно Пантеон титанов обнаружил Азерот во власти хаотичных владык стихий и ужасных Древних богов. Титаны вступили в войну с этими паразитическими чудовищами: изгнали стихийных созданий в карманные измерения, а жутких Древних богов запечатали глубоко под земной корой. Обезопасив мир, они выточили великие биомы, создали хранилища вроде Ульдамана и доверили пятерым великим драконам — Аспектам драконов — защиту земли, магии, времени и самой жизни, после чего отправились обратно к звездам."},{t="Павший защитник",b="Не все титаны остались верны замыслу Пантеона о совершенном порядке. Саргерас, некогда величайший воин и защитник титанов, пал духом и впал в ужас от глубокой космической тьмы и демонической злобы, с которыми ему было поручено бороться. Отвергнув дело своих собратьев, Саргерас обратился к нигилизму и основал Пылающий Легион демонов, чтобы уничтожить все сущее, лишь бы оно не было осквернено."}},faq={{q="Живы ли еще титаны и находятся ли они на Азероте?",a="Сами титаны покинули Азерот много эонов назад и отправились в Великую Тьму, победив Древних богов и упорядочив мир. Они оставили после себя титанических стражей, создания из камня и железа и обширные погребенные хранилища, чтобы те присматривали за их замыслом.",al={"where are the titans","are titans on azeroth","titan locations","где титаны","есть ли титаны на азероте","места титанов"}},{q="Почему дворфы так интересуются титанами?",a="Дворфы происходят напрямую от земнорожденных — расы подземных каменных существ, созданных титанами, чтобы закладывать основы мира. Занимаясь археологией и раскапывая руины вроде Бейл Модана и Ульдамана, дворфы стремятся раскрыть собственное забытое происхождение.",al={"dwarf titan connection","why dwarves dig","dwarves and the creators","дворфы и титаны","зачем дворфы копают","дворфы и создатели"}},{q="Что такое Пантеон?",a="The Pantheon is the governing council of the titans, led by the Highfather Aman'Thul. Other members include Khaz'goroth the shaper of worlds, Eonar the life-binder, Norgannon the keeper of celestial magics, Golganneth the lord of skies, and Aggramar, the champion who replaced Sargeras.",al={"titan pantheon","who leads the titans","titan leaders","пантеон титанов","кто возглавляет титанов","лидеры титанов"}},{q="Создали ли титаны Аспектов драконов?",a="Да. Перед уходом с Азерота Пантеон направил свои силы через хранителей, чтобы благословить пятерых протодраконов. Алекстраза, Изера, Малигос, Ноздорму и Нелтарион получили огромную силу, чтобы оберегать жизнь, природу, магию, время и землю.",al={"titan dragons","aspect origins","who made the aspects","драконы титанов","происхождение аспектов","кто создал аспектов"}},{q="Саргерас — титан?",a="Саргерас был защитником Пантеона и оберегал космос от хаоса и демонов. Темнота, которую он увидел, довела его до отчаяния и безумия, и он отделился от собратьев, чтобы создать Пылающий Легион и посвятить себя сожжению упорядоченной вселенной.",al={"who is sargeras","is sargeras a god","sargeras origin","кто такой саргерас","саргерас бог","происхождение саргераса"}},{q="Пал ли титан в Силитусе?",a="Пророчества киражского Пророка Скерама гласят, что титан сразился с древним злом в южных пустынях Силитуса и пал. Однако ученые и исследователи спорят, был ли это настоящий титан или лишь одно из их титанических созданий.",al={"silithus titan","prophecy of c'thun titan","did c'thun kill a titan","титан в силитусе","пророчество ктуна о титане","убил ли ктун титана"}}},fp="5,297,24.406.0,23.537.0,19.414.0,42.246.0,49.271.0,21.286.0,41.249.0,20.271.0,29.256.0"}
P.entries["topic:trogg"] = {n="Трогг",s="Трогги — грубые подземные гуманоиды, потомки самых первых неудачных опытов титанов, запечатанных глубоко в земле. Недавно они выбрались на поверхность после того, как раскопки дворфов потревожили их древние хранилища, и эти неутомимые землекопы захватили каменоломни дворфов и изгнали гномов из любимой столицы — Гномрегана.",h="Трогги — грубые подземные гуманоиды, потомки самых первых неудачных опытов титанов, запечатанных глубоко в...",kw={"caverndeep","earthen","forge of wills","gnomeregan","grubbis","oggleflint","rockjaw","stonesplinter","trogg","uldaman","глубинная пещера","земнорожденные","кузня воли","гномреган","граббис","оггльфлинт","камнечелюст","каменная заноза","трогг","ульдаман"},ang={["faction:Alliance"]="Зачистка нашествий троггов в Дун Мороге, Лок Модане и Гномрегане остается важной оборонительной задачей для безопасности горного королевства и его беженцев.",["profession:Mining"]="Гнезда троггов часто занимают богатые рудные жилы и глубокие шахты вроде Гол'Болара, и шахтерам приходится защищать свои участки кирками и молотами.",["race:Dwarf"]="Этих диких родичей откопали ваши же кирки в поисках происхождения от титанов, поэтому их набеги по всему Каз Модану — прямое следствие дворфийской археологии.",["race:Gnome"]="Трогги — заклятый враг вашего народа: они разрушили ваш подземный дом и рассеяли выживших гномов, которые нашли приют в Городе механиков в Стальгорне."},sec={{t="Несовершенные предшественники",b="Задолго до того, как смертные расы начали вести летописи, созданные титанами хранители пытались создать слуг из камня с помощью Кузни Воли. Первый замысел пошел не так и породил каменнокожих громил с низким разумом и неукротимой дикостью. Огорченные неудачей, хранители усовершенствовали матрицу и создали расу земнорожденных, которые позже стали предками дворфов. Не желая уничтожать несовершенных троггов, великанша Иронайя запечатала их глубоко под землей в хранилище Ульдамана, чтобы они навечно остались в оцепенении."},{t="Разбуженные киркой",b="Бесчисленные тысячелетия трогги спали, пока Лига исследователей Стальгорна не вскрыла древние подземные комплексы Каз Модана. Проснувшись в незнакомую эпоху, полчища разъяренных троггов хлынули из глубин и с родовой яростью преследовали своих дальних родичей-дворфов. Найдя поверхность яркой и негостеприимной, они прорыли обширные сети туннелей под Дун Морогом, Лок Моданом и Бесплодными землями и быстро стали нападать на каменоломни, места раскопок и торговые форпосты."},{t="Катастрофа в Гномрегане",b="Ведомые подземными вибрациями и шумом, полчища троггов прорыли ход прямо в Гномреган. Гномы, отчаянно уступавшие в числе и дикой силе, вели жестокую войну в подземных коридорах. В отчаянной уловке, придуманной Сикко Термоштепселем, главный механик Гелбин Меггакрут выпустил радиоактивные выбросы, чтобы истребить нашествие. К несчастью, облученный газ убил около восьмидесяти процентов гномов, лишь разъярив троггов, и великий технологический город стал облученной крепостью троггов."}},faq={{q="Кто такие трогги?",a="Трогги — подземные гуманоиды, созданные хранителями, выкованными титанами, как первое, несовершенное поколение каменных слуг. Огорченные их грубой жестокостью, хранители не стали их уничтожать, а заперли в хранилищах вроде Ульдамана, пока тысячи лет спустя дворфы-шахтеры случайно не откопали их.",al={"trogg origins","what is a trogg","trogg lore","происхождение троггов","кто такие трогги","предания о троггах"}},{q="Родственны ли трогги дворфам?",a="Да. Обе расы происходят из Кузни Воли. Трогги — неотшлифованный первый черновик хранителей, а земнорожденные, позже поддавшиеся Проклятию плоти и ставшие дворфами, — совершенная вторая версия.",al={"are dwarves and troggs related","trogg dwarf connection","родственны ли дворфы и трогги","связь троггов и дворфов"}},{q="Как трогги захватили Гномреган?",a="Привлеченные вибрациями тяжелых механизмов, трогги прорыли ход в Гномреган снизу. Несмотря на оборонительные изобретения гномов, захватчики одолели защитников числом. Неудачная попытка вытравить их радиоактивным газом убила большинство гномов, и власть троггов над городом закрепилась.",al={"why are troggs in gnomeregan","gnomeregan trogg attack","почему трогги в гномрегане","нападение троггов на гномреган"}},{q="Способны ли трогги к речи или развитой культуре?",a="Разум троггов очень ограничен, они общаются в основном гортанным ворчанием и ревом. Они ценят грубую силу превыше всего и выбирают вождей племен насилием. Хотя некоторые владеют примитивным шаманским колдовством, их ремесло грубо и редко выходит за пределы дубин, каменных стрел и украденных реликвий.",al={"can troggs talk","trogg culture","trogg intelligence","могут ли трогги говорить","культура троггов","разум троггов"}},{q="Почему трогги собирают древние реликвии?",a="Исследователи полагают, что тяга накапливать древние реликвии титанов — инстинктивный отголосок их происхождения от титанов. Однако трогги редко понимают, что носят с собой, и используют бесценные артефакты как тупые дубины или примитивные талисманы удачи.",al={"why do troggs hoard artifacts","trogg treasure","почему трогги копят артефакты","сокровища троггов"}},{q="Есть ли трогги за пределами Каз Модана?",a="Да. Подземные кланы троггов устроили гнезда по всему Азероту, в том числе трогги Огненной пропасти, обитающие в ее глубинах под Оргриммаром, трогги племени Золотоносного Песка в Темных берегах и группы по всем Бесплодным землям и Альтераку.",al={"trogg locations","troggs in durotar","troggs in kalimdor","места троггов","трогги в дуротаре","трогги в калимдоре"}}},fp="5,360,23.569.0,23.493.0,29.546.1,24.314.0,30.231.0,34.317.0,49.346.0,37.246.0,39.229.0"}
P.entries["topic:troll"] = {n="Тролль",s="Тролли — одна из древнейших разумных рас, населяющих Азерот. Они возникли вокруг Источника Вечности задолго до Раскола. Тролли известны невероятной физической регенерацией, поклонением первобытным духам — лоа — и мастерством в вуду; их раздробленные империи когда-то правили огромными землями древнего мира. Сегодня древние королевства, такие как Гурубаши и Амани, по-прежнему крайне враждебны к чужакам, а племя Черного Копья обрело прочное убежище в Орде Тралла.",h="Тролли — одна из древнейших разумных рас, населяющих Азерот.",kw={"amani","aqir","darkspear","drakkari","gurubashi","loa","regeneration","troll","trolls","voodoo","zandalari","амани","акири","черное копье","драккари","гурубаши","лоа","регенерация","тролль","тролли","вуду","зандалары"},ang={["class:Priest"]="Жречество троллей неразрывно связано с лоа и охотой за тенью: они общаются напрямую с духами животных и первобытными темными силами, а не со Светом.",["faction:Horde"]="Хитрость, ловкость и духовная сила троллей Черного Копья дают под знамена вождя незаменимых разведчиков, охотников за тенью и шаманов.",["race:NightElf"]="История эльфов и древние мифы прослеживают застарелое соперничество до королевств троллей; религиозное вуду и жертвенные обряды троллей вызывают у них крайнюю настороженность.",["race:Troll"]="Ваше наследие уходит в прошлое глубже, чем у почти любой цивилизации Азерота. Пока ваши сородичи в Зул'Гурубе и Зул'Амане цепляются за горькую, замкнутую гордость, племя Черного Копья создает живое наследие силой Орды."},sec={{t="Дети дикой природы",b="Задолго до того, как Великий Раскол разрушил древний Калимдор, первобытные силы Источника Вечности способствовали возвышению троллей. Первые тролли были свирепыми и очень ловкими охотниками и собирателями. Их особое строение тела давало им поразительную способность к исцелению: они быстро оправлялись от тяжелых ран и со временем могли даже отращивать отсеченные конечности. Поселившись вокруг священных гор Зандалара, они обратили свое почитание к неуловимым диким богам Калимдора, которых называли лоа. Под духовным руководством охотников за тенью и знахарей эти обряды превратились в практику вуду и привели к строительству священных храмовых вершин, таких как Зулдазар."},{t="Война роя",b="Около шестнадцати тысяч лет назад любопытные тролли по неведению нарушили древнее табу и пробудили ужас К'Тракси — Кит'икса. Чудовище собрало рои акири из подземных нор и угрожало поглотить всю смертную жизнь. Перед угрозой полного уничтожения разрозненные племена объединились под началом зандаларов и создали империю Зул. Благодаря непрестанным партизанским засадам и призванной мощи лоа тролли отбросили рои. Стремясь истребить угрозу насекомоподобных, могучие племена разошлись по континенту: драккари заняли замерзший север, гурубаши громили акири на юго-западе, а свирепые амани убили самого Кит'икса и основали свой город Зул'Аман на костях чудовища."},{t="Расколотое наследие",b="Когда рои насекомых были разбиты и сдержаны, единство империи Зул распалось. Каждая великая ветвь ушла в собственную суверенную империю и развила особую культуру, физические черты и племенную иерархию, приспособленные к лесам, джунглям и ледяным пустошам. За тысячелетия разделения, соперничества и территориальных войн с более молодыми расами власть троллей медленно пришла в упадок и замкнулась в себе. Большинство уцелевших королевств троллей относится ко всем другим расам с яростной, непреклонной враждебностью и с горечью цепляется за руины былого величия. Лишь изгнанники, тролли джунглей из племени Черного Копья, избрали новый путь и вступили в Орду вместе с орками и тауренами."}},faq={{q="Правда ли, что тролли могут отращивать утраченные конечности?",a="Да. Тролли обладают необычайной способностью к регенерации и оправляются от телесных повреждений быстрее большинства других смертных рас. Со временем тролль может отрастить даже утраченные пальцы и целые конечности, что делает его исключительно выносливым в бою.",al={"troll healing","troll limb regrowth","how do trolls heal","исцеление троллей","отращивание конечностей у троллей","как лечатся тролли"}},{q="Кто такие лоа?",a="Лоа — первобытные божества, которым поклоняются тролли почти всех племен. На деле это неуловимые дикие боги Азерота — могущественные духи животных, которых тролли чтят жертвоприношениями, медитацией и ритуальной магией. Жрецы и охотники за тенью призывают лоа, чтобы получить благословения, наставления и разрушительную силу в бою.",al={"who are loa","troll gods","what do trolls worship","кто такие лоа","боги троллей","чему поклоняются тролли"}},{q="Что представляла собой империя Зул?",a="Империя Зул была великим союзом всех племен троллей, созданным около шестнадцати тысяч лет назад под руководством зандаларов. Она объединила расу для борьбы с бушующими роями насекомых акири. После того как акири были оттеснены на окраины континента, союз естественным образом распался, а племена основали собственные независимые королевства.",al={"first troll empire","ancient troll kingdom","history of zul","первая империя троллей","древнее королевство троллей","история зула"}},{q="Почему большинство троллей враждебны к игрокам?",a="У большинства племен троллей, например у лесных троллей Амани или джунглевых троллей Гурубаши, древняя замкнутая культура и глубокая ненависть к чужакам. Века конфликтов с наступающими расами сделали их яростными защитниками родовых земель: нарушителей они атакуют сразу.",al={"why are trolls bad","hostile trolls","evil trolls","почему тролли злые","враждебные тролли","злые тролли"}},{q="Как племя Черного Копья вступило в Орду?",a="Джунглевые тролли Черного Копья были изгнаны с родных земель и оказались в ловушке на острове, осажденном мурлоками и морскими ведьмами. Вождь Тралл и его орочий флот вмешались и спасли племя от гибели. Из благодарности и общей нужды их предводитель принес клятву верности племени только что образованной Орде.",al={"why are trolls horde","darkspear horde origin","thrall and trolls","почему тролли в орде","происхождение черного копья в орде","тралл и тролли"}},{q="Что такое вуду?",a="Вуду — древняя школа духовной и темной магии, которую практикуют тролли-знахари, охотники за тенью и жрецы. Она соединяет общение с предками, поклонение лоа, проклятия, порчу и сильные травяные настои, чтобы вредить врагам и усиливать союзников.",al={"troll voodoo","how does voodoo work","witch doctor magic","вуду троллей","как работает вуду","магия знахаря"}}},fp="5,479,21.693.0,20.728.0,18.667.0,40.271.0,13.334.0,27.340.0,39.313.0,37.323.0,15.249.0"}
P.entries["topic:twilight-s-hammer"] = {n="Сумеречный Молот",s="Сумеречный Молот — нигилистический апокалиптический культ, стремящийся пробудить Древних богов и привести Азерот к концу. Изначально это был орочий клан под началом огра-мага Чо'галла, но он превратился в тайный многорасовый орден, который проводит темные ритуалы по всему Калимдору и Восточным королевствам.",h="Сумеречный Молот — нигилистический апокалиптический культ, стремящийся пробудить Древних богов и привести...",kw={"aku'mai","blackfathom deeps","cho'gall","hour of twilight","kelris","master's glaive","old gods","silithus","twilight's hammer","void","аку'май","непроглядная пучина","чо'галл","час сумерек","келрис","меч властителя","древние боги","силитус","сумеречный молот","пустота"},ang={["class:Priest"]="Сумеречный Молот управляет той же магией Бездны и Тьмы, к которой обращаются жрецы тьмы, и служит мрачным предостережением о том, что бывает, когда общение с шепотами подавляет рассудок смертных.",["class:Warlock"]="Хотя Сумеречный Молот первоначально был связан с Советом Теней Гул'дана, он отказался от демонической магии Скверны ради первобытного безумия Древних богов, поэтому стал непредсказуемым соперником, а не союзником.",["faction:Horde"]="Культ — постыдный пережиток самых темных дней Старой Орды. Новая Орда Тралла полностью отвергла их безумие и казнит всех фанатиков, пытающихся вновь соблазнить молодых орков нигилизмом.",["race:NightElf"]="Осквернение священных мест, таких как Непроглядная Пучина и Меч Властителя, чуждыми сектантами — прямое духовное и физическое нападение на священные земли северного Калимдора."},sec={{t="Истоки во тьме",b="Сумеречный Молот возник на Дреноре как изгнанный клан бледных орков, обитавший в пещерах Подбледья под Ошу'гуном. Общение с силами Пустоты заставило их принять мрачное пророчество: Час Сумерек — неизбежную космическую гибель, когда тень поглотит все сущее. Желая направить их жуткую магию Тени на службу войне Орды, Гул'дан отправил к ним возглавить клан двухголового огра-мага Чо'галла. Чо'галл убедил бледных, что Орда — лишь орудие разрушения, призванное приблизить их любимый апокалипсис. Связанный этим пророчеством, клан записал свои безумные учения в Сумеречный канон — страницы из содранной и исписанной кожи самих бледных."},{t="Прибытие в Азерот",b="Когда Сумеречный Молот прошел через Темный портал во время Первой войны, их апокалиптический фанатизм только усилился. В земле Азерота сектанты различили настоящий шепот Древних богов — древних ужасов, скованных под землей. Чернорук терпел их странное ритуальное поведение лишь потому, что Чо'галл сдерживал их кровожадность; их направляли вместе с кланом Кровавой Глазницы Килрогга Мертвый Глаз в первых штурмах Крепости Штормграда. Позже, во время Второй войны, клан действовал в глубине Грим Батола и руководил важными перерабатывающими мастерскими, пока предательство Гул'дана не раскололо Орду. Хотя Оргрим Молот Рока приказал перебить клан-предатель близ Гробницы Саргераса, Чо'галл и ядро фанатиков выжили и бежали на запад через Великое море."},{t="Растущая опухоль",b="Достигнув забытых берегов Калимдора, культ превратился из разбитого орочьего клана в тайный многорасовый заговор. Соблазняя разочарованных членов и Альянса, и Орды, Сумеречный Молот вербует любую душу, достаточно сломленную, чтобы желать забвения. На севере Калимдора под началом Повелителя сумрака Келриса сектанты закрепились в затопленных залах Непроглядной Пучины и приносят жертвы Аку'май, чудовищной питомице Древних богов. Севернее, на Темных берегах, их землекопы тревожат колоссальные окаменевшие останки у Меча Властителя. В южных пустынях Силитуса лагеря фанатиков в балахонах ухаживают за бездонными ветряными камнями и прислушиваются к пробуждению древних ужасов, погребенных под песками."}},faq={{q="Чего добивается Сумеречный Молот?",a="Они стремятся к Часу Сумерек — полному уничтожению всей жизни и порядка в Азероте. Культ не ищет ни завоеваний, ни богатства: он считает забвение священным даром и деятельно стремится освободить Древних богов, скованных под миром.",al={"what do cultists want","twilights hammer goal","twilight hammer purpose","чего хотят сектанты","цель сумеречного молота","зачем сумеречный молот"}},{q="Это орочий клан или культ?",a="Сначала это был орочий клан на Дреноре, состоявший из безумных бледных изгоев под началом Чо'галла. После бегства со Второй войны они отказались от клановых границ и стали тайным многорасовым культом, привлекая людей, ночных эльфов, дворфов и всех, кто готов поклоняться Пустоте.",al={"are they orcs","is twilights hammer a clan","twilights hammer races","они орки","сумеречный молот клан","расы сумеречного молота"}},{q="Кто возглавляет Сумеречный Молот?",a="Культ основал и возглавляет Чо'галл, хитрый двухголовый огр-маг и бывший ученик Гул'дана. Местные ячейки действуют под началом региональных командиров, например Повелителя сумрака Келриса в Непроглядной Пучине.",al={"who is twilight hammer boss","twilights hammer leader","cho'gall","кто главный в сумеречном молоте","лидер сумеречного молота","чо'галл"}},{q="Почему они находятся в Непроглядной Пучине?",a="Под началом Повелителя сумрака Келриса сектанты заняли затонувший храм ночных эльфов у Зорамского взморья, чтобы поклоняться Аку'май — первобытной трехглавой гидре, угодной Древним богам, — и приносить ей жертвы.",al={"blackfathom cultists","kelris bfd","what are they doing in ashenvale","сектанты непроглядной пучины","келрис","что они делают в ясеневом лесу"}},{q="Что они делают у Меча Властителя на Темных берегах?",a="Меч Властителя — это окаменевший труп Соггота Ползучего, колоссального древнего слуги Древних богов, убитого в мифических войнах Калимдора. Сектанты собираются там, чтобы общаться с его остаточной темной энергией и искать знамения пробуждения своих повелителей.",al={"masters glaive cultists","darkshore twilight hammer","soggoth","сектанты меча властителя","сумеречный молот темные берега","соггот"}},{q="Почему Оргрим Молот Рока пытался их истребить?",a="В разгар Второй войны Чо'галл и Гул'дан бросили поход Орды на Лордерон, чтобы обрести божественность в Гробнице Саргераса. Разъяренный предательством, стоившим Орде победы, вождь Молот Рока отправил верные войска перебить отколовшиеся кланы.",al={"doomhammer twilights hammer","second war betrayal","молот рока и сумеречный молот","предательство второй войны"}}},fp="17,313,17.690.0,18.767.0,18.753.0,48.251.0,31.278.0,32.212.0,34.212.0,56.275.0,47.275.0"}
P.entries["topic:venture-company"] = {n="Торговая Компания",s="Торговая Компания — печально известный безжалостный картель гоблинов, занимающийся агрессивной добычей ресурсов, тяжелой промышленной техникой и лесозаготовками. Не связанный с крупными гоблинскими портами вроде Пиратской бухты или Кабестана, картель разрабатывает недра и вырубает леса в Калимдоре и Восточных королевствах, не считаясь ни с местными жителями, ни с природой.",h="Торговая Компания — печально известный безжалостный картель гоблинов, занимающийся агрессивной добычей...",kw={"fizsprocket","gerenzo","puzik gallywix","razdunk","samophlange","shredder","sludge fen","super reaper","venture co","venture company","windshear crag","шумовик","геренцо","пузик галливикс","раздунк","самофланж","крошшер","нефтяное болото","супер-дровосек","торговая компания","утес ветрорезов"},ang={["class:Druid"]="Масштабные вырубки в Когтистых горах и промышленное загрязнение природных родников в Мулгоре и Степях — это вопиющее, ничем не сдерживаемое осквернение земли.",["class:Rogue"]="Изувеченная Длань и ШРУ внимательно следят за торговлей ядами со стороны картеля: они проникают в его башни и саботируют работу его старших бригадиров, чтобы добыть смертоносные химические смеси.",["profession:Engineering"]="Картель производит одни из лучших и самых совершенных крошшеров и механических регуляторов Азерота, и потому его чертежи — желанная цель корпоративных краж.",["race:Tauren"]="Торговая Компания без разрешения вторглась в священные холмы Мулгора, отравляя исконные колодцы и вырубая лес вопреки воле Матери-Земли."},sec={{t="Промышленный грабеж",b="Торговой Компанией издалека руководит магнат Раздунк, и действует она по простой корпоративной философии: все, что можно срубить, пробурить или взорвать в горе, будет использовано. Картель применяет одну из самых совершенных тяжелых машин Азерота, включая огромные лесозаготовительные измельчители, буровые установки и промышленные нефтеперерабатывающие заводы. В отличие от традиционных торговых домов, занятых перевозками или розницей, Торговая Компания специализируется на захвате сырья силой, игнорируя договоры, границы и суверенные права местных жителей."},{t="Вторжение в Калимдор",b="Стремительная экспансия картеля в Калимдор принесла ему всеобщую ненависть. В Мулгоре Бригадир Шумовик загнал буровые и добывающие установки в восточные кручи, хотя тауренские власти официально отказали ему в правах на недра, и загрязнил чистые колодцы по всей равнине. Севернее компания превратила Нефтяное болото в Степях в химическую клоаку для питания нефтяных насосов, заняв бывший Каменный карьер Орды и проводя мерзкие опыты с самофланжами и ядовитыми зельями. В Утесе Ветрорезов в Когтистых горах лесозаготовки под руководством безумного лепрогнома Геренцо Терминатрикса уничтожили целые рощи с помощью колоссальных машин Супер-дровосек 6000."},{t="Корпоративное соперничество и сомнительные сделки",b="Торговую Компанию презирают даже другие гоблины. Барон Ревилгаз из Пиратской бухты часто заказывает налеты на их лагерь и нефтяную вышку у Озера Назферити, желая и остановить их территориальную экспансию, и похитить новейшие регуляторы топлива для крошшеров. Союз механиков в Кабестане открыто ведет против них промышленный шпионаж, чтобы выкрасть инженерные чертежи. Хуже того, ШРУ и Изувеченная Длань обнаружили, что компания торгует опасными алхимическими составами: продает смертельные яды Занзила, изменяющие сознание, некромантам Братства Справедливости в Западном Крае и использует ядовитые испарения для выведения мутировавших рабочих-трутней."}},faq={{q="Кто возглавляет Торговую Компанию?",a="Президент картеля — магнат Раздунк, который издалека управляет общими корпоративными предприятиями организации. Повседневной работой участков по всему Азероту руководят региональные управляющие, бригадиры и наемные надсмотрщики, такие как Бригадир Шумовик в Мулгоре, Бригадир Зубовиззл в Нефтяном болоте и Геренцо Терминатрикс в Когтистых горах.",al={"venture co leader","venture company boss","who runs venture co","mogul razdunk","глава торговой компании","босс торговой компании","кто управляет торговой компанией","магнат раздунк"}},{q="Почему Орда ненавидит Торговую Компанию?",a="Картель ведет незаконную агрессивную добычу ресурсов на исконных землях Орды. В Мулгоре он без разрешения вторгся в восточные горы и осквернил священные колодцы тауренов. В Степях он захватил Каменный карьер Орды и превратил Нефтяное болото в зловонную нефтяную жижу.",al={"tauren venture co","why horde hate venture co","mulgore venture company","таурены торговая компания","почему орда ненавидит торговую компанию","мулгор торговая компания"}},{q="Связаны ли они с Картелем Хитрая Шестеренка или Пиратской бухтой?",a="Нет. Торговая Компания — отдельная хищническая организация. Она ярый корпоративный враг Картеля Хитрая Шестеренка: Барон Ревилгаз из Пиратской бухты часто нанимает наемников, чтобы срывать их лесозаготовки в Тернистой долине, а Пароклапан из Кабестана регулярно посылает лазутчиков саботировать их крошшеры и красть чертежи.",al={"are they steamwheedle","venture co booty bay","ratchet venture co","хитрая шестеренка ли они","торговая компания пиратская бухта","кабестан торговая компания"}},{q="Почему лепрогном руководит работами в Утесе Ветрорезов?",a="Gerenzo Wrenchwhistle was hired by the Venture Company for his ruthless mechanical genius, designing the massive Super Reaper 6000 logging machine. His hiring caused an uproar among the cartel's goblin engineers, such as Ziz Fizziks, and even angered the Trade Princes in Undermine, who disapproved of Razdunk consorting with the outcast gnome.",al={"gerenzo wrenchwhistle","gnome in stonetalon","why leper gnome venture","геренцо терминатрикс","гном в когтистых горах","почему лепрогном торговая компания"}},{q="Чем занимается Торговая Компания в Западном Крае?",a="Торговая Компания заключила тайное торговое соглашение с Братством Справедливости. Она приобрела яды Занзила и продала смесь агенту Братства Справедливости Клейвену Мортвейку в Западном Крае, который использовал ядовитые составы для создания безмозглых трутней Братства Справедливости, похожих на рабочих в предприятиях Торговой Компании.",al={"venture co westfall","klaven mortwake venture co","venture defias","торговая компания западный край","клейвен мортвейк торговая компания","торговая компания братство справедливости"}},{q="Что производят в Нефтяном болоте?",a="Картель возвел промышленную буровую установку прямо над тем, что раньше было чистым природным родником, откачивая и перерабатывая нефть и сбрасывая ядовитую жижу по всему северу Степей. Помимо нефти, тамошние исследователи испытывают сложные механические самофланжи и синтезируют ядовитые смеси.",al={"sludge fen oil","barrens venture co oil rig","samophlange sludge fen","нефть нефтяное болото","нефтяная вышка торговой компании степи","самофланж нефтяное болото"}}},fp="15,358,18.549.0,23.663.1,39.649.2,30.346.0,44.307.0,62.340.0,58.344.0,46.314.1,41.298.0"}
P.entries["topic:war-of-the-ancients"] = {n="Война Древних",s="Десять тысяч лет назад безрассудное колдовство королевы Азшары и ее высокорожденных пробило портал в Источнике Вечности и выпустило демонический Пылающий Легион на Азерот. Молодой друид Малфурион Ярость Бури, жрица Тиранда Шелест Ветра и командир Джерод Песнь Теней возглавили отчаянный союз смертных и древних лесных полубогов, который отразил захватчиков. Разрушение Источника вызвало Великий Раскол: древний континент Калимдор был жестоко расколот, а облик мира изменился навсегда.",h="Десять тысяч лет назад безрассудное колдовство королевы Азшары и ее высокорожденных пробило портал в...",kw={"azshara","burning legion","cenarius","highborne","jarod shadowsong","malfurion","ravencrest","sargeras","sundering","tyrande","war of the ancients","well of eternity","азшара","пылающий легион","кенарий","высокорожденные","джерод песнь теней","малфурион","вороний хребет","саргерас","раскол","тиранда","война древних","источник вечности"},ang={["class:Druid"]="Этот конфликт стал рождением смертного друидизма: Малфурион Ярость Бури научился у Кенария законам природы и доказал, что силы природы способны победить вселенскую гибель.",["class:Mage"]="Безрассудная гордыня высокорожденных во время войны служит для всего Азерота главным историческим предостережением о катастрофической опасности безудержного черпания арканной силы.",["class:Priest"]="Мастерство Тиранды Шелест Ветра в использовании милости Элуны во время войны возвело Жречество Луны в самое сердце военного и гражданского управления ночных эльфов.",["race:NightElf"]="Война сформировала все стороны современного общества кальдораев: объясняет их глубокое недоверие к арканной магии, почтение к Кенарию и неизменное лидерство Малфуриона и Тиранды.",["race:Tauren"]="Воины-таурены хранят гордую память о том, как десять тысячелетий назад стояли плечом к плечу с лесными богами и древними смертными, отбрасывая Легион."},sec={{t="Безрассудство высокорожденных",b="На вершине могущества древней империи кальдораев королева Азшара и ее элитная каста чародеев, высокорожденные, безостановочно черпали силу из безмерных арканных глубин Источника Вечности. Их безрассудные деяния породили огромные волны в Великой Темной Пустоте и привлекли внимание Саргераса, владыки Пылающего Легиона. Плененные обещаниями абсолютной власти и совершенства, Азшара и ее советник Ксавий открыли в Источнике межпространственный разлом. Легионы гончих Скверны, стражей Скверны, стражей рока и чудовищных командиров хлынули в столицу Зин-Азшари, истребляя всех, кто не был высокорожденным, и начиная поход по уничтожению жизни в мире."},{t="Сопротивление кальдораев",b="Ужаснувшись резне, ночные эльфы, не принадлежавшие к касте высокорожденных, сплотились вокруг опытного полководца лорда Кур'талоса Вороний Хребет. Сопротивление укрепили выдающиеся герои: первый смертный друид Малфурион Ярость Бури, набожная жрица Элуны Тиранда Шелест Ветра и одаренный брат Малфуриона, Иллидан. Когда имперские войска убили Вороний Хребет, а демонические армии усилили натиск, командование перешло к блестящему тактику Джероду Песнь Теней. Поняв, что эльфам не выстоять в одиночку, Джерод преодолел старые расовые границы и привлек земельников, фурболгов и горных таурен, создав единый фронт против натиска Легиона."},{t="Цена победы",b="Война приобрела масштабы, способные потрясти мир, когда полубог Кенарий призвал в бой древних диких богов и драконьи роды. Решив не дать самому Саргерасу ступить на Азерот, Малфурион и сопротивление отчаянно попытались обрушить портал над Источником Вечности. Эта отчаянная попытка удалась: демонические полчища были отброшены в Круговерть Пустоты, но напряжение оказалось слишком велико. Источник яростно сколлапсировал, вызвав Великий Раскол: Калимдор раскололся на отдельные континенты, центр мира был затоплен, возникло Великое море, и это навсегда оставило след в культуре кальдораев."}},faq={{q="Что стало причиной Войны Древних?",a="Королева Азшара и ее чародеи-высокорожденные безостановочно экспериментировали с арканной энергией Источника Вечности. Их заклинания породили волны по всему космосу, которые привлекли темного титана Саргераса. Он убедил высокорожденных открыть в Источнике врата, чтобы Пылающий Легион мог проникнуть на Азерот.",al={"why did the war start","who caused the war of the ancients","well of eternity portal","почему началась война","кто начал войну древних","портал источника вечности"}},{q="Что такое Великий Раскол?",a="Великий Раскол — катаклизм, положивший конец войне. Чтобы не дать Саргерасу войти в мир, сопротивление обрушило портал внутри Источника Вечности. Откат заставил Источник яростно сколлапсировать, разорвав единый суперконтинент Калимдор на отдельные части и образовав Великое море.",al={"what is the sundering","how did kalimdor break","well of eternity explosion","что такое раскол","как раскололся калимдор","взрыв источника вечности"}},{q="Кто возглавлял силы смертных против Легиона?",a="Сопротивление сначала сплотил лорд Кур'талос Вороний Хребет. После его гибели на поле боя верховное командование принял Джерод Песнь Теней, управлявший объединенными сухопутными силами вместе с ключевыми героями сражений, среди которых были Малфурион Ярость Бури и Тиранда Шелест Ветра.",al={"who led the resistance","kaldorei resistance leaders","кто возглавлял сопротивление","лидеры сопротивления кальдораев"}},{q="Сражались ли другие расы бок о бок с ночными эльфами?",a="Да. Преодолев давние эльфийские предрассудки, командир Джерод Песнь Теней принял помощь нескольких смертных рас: он объединил земельников, племена фурболгов и горных таурен против демонического вторжения вместе с лесным полубогом Кенарием и его дикими собратьями.",al={"tauren in war of the ancients","who helped the night elves","таурены в войне древних","кто помогал ночным эльфам"}},{q="Что случилось с королевой Азшарой во время войны?",a="Азшара оставалась в своем дворце в Зин-Азшари до горького конца, одержимая желанием привести Саргераса на Азерот. Когда Источник Вечности сколлапсировал и океаны поглотили столицу, королева и уцелевшие верные ей высокорожденные канули в бурлящие глубины.",al={"where is azshara","did queen azshara die","где азшара","умерла ли королева азшара"}},{q="Почему ночные эльфы сегодня не доверяют арканной магии?",a="Кальдораи на собственном опыте убедились, как безудержная жажда арканной магии у высокорожденных призвала Пылающий Легион и уничтожила древний Калимдор. После этого ночные эльфы строго запретили арканное колдовство и обратились к друидизму и вере в Элуну, чтобы защитить свои земли.",al={"why do night elves hate mages","kaldorei magic ban","почему ночные эльфы ненавидят магов","запрет магии у кальдораев"}}},fp="19,538,21.647.0,23.661.0,20.640.0,36.304.0,29.319.0,45.285.0,48.255.0,46.269.0,52.287.0"}
P.entries["topic:warrior"] = {n="Воин",s="Воины — классические бойцы первой линии Азерота: они владеют тяжелыми латными доспехами, щитами и почти любым видом боевого оружия. Подпитывая самые разрушительные удары чистой яростью боя, они бросаются в гущу сражения, чтобы защитить слабых союзников или прорубить путь сквозь ряды врагов. Воины есть среди всех рас и в каждой цивилизации: от стойких городских стражников и королевских защитников до странствующих наемников.",h="Воины — классические бойцы первой линии Азерота: они владеют тяжелыми латными доспехами, щитами и почти любым...",kw={"arms","berserker","fury","melee","plate","protection","rage","shield","vanguard","warrior","оружие","берсерк","неистовство","ближний бой","латы","защита","ярость","щит","авангард","воин"},ang={["class:Warrior"]="Каждая битва проверяет вашу выносливость и выдержку; превращая боль от получаемых ударов в чистую ярость, вы управляете передовой.",["faction:Alliance"]="Пехотинцы и рыцари Альянса образуют оборонительный авангард, защищающий человеческие королевства, горные твердыни дворфов и эльфийские леса.",["faction:Horde"]="Для Орды боевое мастерство — образ жизни: грунты-штурмовики и воины-таурены возглавляют каждое продвижение на новые земли.",["profession:Blacksmithing"]="Воины целиком зависят от кузнецов, которые выковывают тяжелые латные доспехи, прочные баклеры и острые клинки, необходимые, чтобы выжить в смертельном бою."},sec={{t="Мастера стали и щита",b="Воины полагаются не на божественные молитвы и не на тайные заклинания. Их сила целиком основана на физической выносливости, боевой дисциплине и глубоком владении оружием. Облаченные в тяжелейшие латные доспехи, они определяют ход боя на передовой. Одни сражаются за громадными щитами, выдерживая сокрушительные удары и отвлекая опасность от заклинателей и лучников. Другие выходят вперед с двуручными древковыми видами оружия, топорами и двуручными мечами или врываются в ближний бой с клинком в каждой руке, рассекая целые строи."},{t="Сила боевой ярости",b="В горниле битвы боль и кровь разжигают внутренний огонь воина. Этот ресурс называют просто яростью: она растет, когда воины наносят и получают удары. Вместо того чтобы поддаться усталости или кровоточащим ранам, закаленные бойцы обращают эту боевую ярость в костедробящие удары, смертоносные вихри стали и оглушительные боевые кличи, которые воодушевляют соратников и подрывают боевой дух врагов."},{t="Всеобщая традиция",b="В отличие от классов, связанных с определенными верованиями или стихиями, традиция воинов свойственна всем расам Азерота. Штормград полагается на дисциплинированных рыцарей-защитников Конного Братства, Стальгорн собирает своих стойких стражей Кузни, а Орда объединяется вокруг орочьих мастеров клинка, воинов-тауренов и Стражей смерти из числа Отрекшихся. Будь то честь, защита земель или холодный расчет, те, кто откликается на зов оружия, образуют несокрушимую опору любой армии."}},faq={{q="Что дает силу воину, если он не использует магию?",a="Воины полагаются на боевое мастерство, тактическую подготовку и ярость. Ярость накапливается прямо в схватке — как при ударах по врагам, так и при получении ударов. Этот прилив боевого адреналина питает их самые разрушительные приемы: размашистые удары оружием, оглушающие удары щитом и устрашающие крики.",al={"how do warriors fight","warrior resource","what is rage","как сражаются воины","ресурс воина","что такое ярость"}},{q="Какие расы могут быть воинами?",a="Воином может стать представитель любой играбельной расы Азерота. Потребность в тяжеловооруженных бойцах первой линии есть во всех смертных культурах: от стойких дворфийских защитников Каз Модана до свирепых орочьих штурмовиков Дуротара.",al={"who can be warrior","warrior races","can every race be warrior","кто может быть воином","расы воина","может ли любая раса быть воином"}},{q="Какую роль воины играют в боевой группе?",a="Обычно воины ведут группу за собой. Стойкие воины-защитники используют щиты и латные доспехи, чтобы принимать удары на себя и удерживать опасных врагов на себе. Воины, владеющие оружием и неистовством, напротив, берут сокрушительное двуручное оружие или парные клинки, чтобы одолеть врагов жестоким физическим уроном.",al={"warrior role","do warriors tank","arms vs fury vs prot","роль воина","танкуют ли воины","оружие против неистовства против защиты"}},{q="Каким оружием могут владеть воины?",a="Воины — мастера почти любого оружия, известного смертным в бою. Они могут владеть мечами, булавами, топорами, древковым оружием, кинжалами и посохами, как одноручными, так и двуручными, а также тяжелыми щитами и дальнобойным оружием: луками, ружьями и арбалетами.",al={"warrior weapons","can warriors use bows","what can warriors equip","оружие воина","могут ли воины использовать луки","что может носить воин"}},{q="Какие известные воины есть в истории Азерота?",a="Среди прославленных воинов — лорд Андуин Лотар, защитник Штормграда и верховный главнокомандующий Альянса Лордерона; Громмаш Адский Крик, вождь клана Песни Войны; и Кэрн Кровавое Копыто, верховный вождь объединенных племен тауренов.",al={"famous warriors","legendary warriors","who are warrior heroes","известные воины","легендарные воины","кто герои-воины"}},{q="Где новые воины проходят официальное обучение?",a="Воины тренируются везде, где собираются солдаты. Новобранцы-люди проходят подготовку в Аббатстве Североземья, дворфы и гномы учатся в Старой Наковальне в Холодной долине, ночные эльфы тренируются в Тенистой долине, орки и тролли практикуются в Долине Испытаний, а бойцы из числа Отрекшихся являются в казармы Могильника.",al={"warrior trainers","where do warriors learn","warrior trainer locations","наставники воинов","где учатся воины","где находятся наставники воинов"}}},fp="7,443,27.512.0,24.411.0,21.484.0,47.318.0,31.224.0,46.303.0,40.252.0,50.241.0,52.280.0"}
P.entries["topic:warsong-clan"] = {n="клан Песни Войны",s="Клан Песни Войны — одна из самых свирепых и легендарных боевых сил среди орков, которой прежде руководил почитаемый вождь Громмаш Адский Крик. Пережив изгнание, лагеря для интернированных и демоническую порчу, клан действует главным образом в Ясеневом лесу как Всадники Песни Войны, яростно добывая древесину для молодой Орды и непрерывно сражаясь с ночными эльфами.",h="Клан Песни Войны — одна из самых свирепых и легендарных боевых сил среди орков, которой прежде руководил...",kw={"ashenvale","cenarius","grommash","hellscream","mannoroth","outriders","splintertree","warsong","ясеневый лес","кенарий","громмаш","адский крик","маннорот","всадники","расщепленное дерево","песнь войны"},ang={["faction:Alliance"]="Клан Песни Войны воплощает неослабевающую агрессию орков и доказывает многим в Альянсе, что мир между двумя фракциями невозможен, пока их топоры рубят Ясеневый лес.",["faction:Horde"]="Без древесины, которую Всадники Песни Войны заготавливают в Ясеневом лесу, Новой Орде не хватило бы сырья для укрепления поселений и расширения владений в Калимдоре.",["race:NightElf"]="Ночные эльфы испытывают к клану Песни Войны жгучую ненависть — не только за вырубку священных чащ Ясеневого леса, но и за непростительное убийство полубога Кенария.",["race:Orc"]="Клан Песни Войны воплощает и величайший позор, и высшее искупление орочьего народа: он первым испил крови Маннорота, но это и клан, чей вождь погиб, чтобы разрушить власть демона над всеми орками."},sec={{t="Наследие непокорности",b="Задолго до перехода в Азерот клан Песни Войны завоевал репутацию на открытых равнинах Дренора благодаря подвижной тактике наездников на волках, сокрушая империи огров своей несгибаемой стойкостью. Его яростный нрав внушал такой страх, что вождь Чернорук оставил его в тылу во время Первой войны, чтобы избежать беспорядочных вспышек буйства. После Второй войны клан наконец прорвался через Темный портал под предводительством Громмаша Адского Крика, но оказался заперт в Азероте, когда Дренор распался. Пока другие орки томились в лагерях для интернированных Альянса, Песнь Войны избежала плена, скитаясь по глуши и сохраняя свой воинственный дух, пока Тралл не объединился с Адским Криком, чтобы создать Новую Орду."},{t="Кровь и искупление",b="Прибыв в Калимдор во время Третьей войны, Тралл приказал Адскому Крику и его клану отправиться в Ясеневый лес, чтобы заготавливать древесину и основать заставу. Вторжение разъярило ночных эльфов и лесного полубога Кенария. Доведенные до грани истребления, воины клана Песни Войны вновь поддались демонической крови полководца Преисподней Маннорота, чтобы одержать верх, и в исступлении порчи Скверны убили Кенария. Тралл и его союзники сумели избавить Адского Крика от проклятия, и в роковой схватке Гром отдал жизнь, уничтожив Маннорота. Его героическая жертва навсегда разрушила проклятие демонической крови и закрепила место клана Песни Войны в истории Орды."},{t="Война за Ясеневый лес",b="В наши дни клан продолжает дело Громмаша под знаменем Всадников Песни Войны. Из твердынь вроде Заставы Расщепленного Дерева и действующих лесозаготовительных лагерей воины добывают древесину, необходимую для строительства молодого государства Орды в засушливых пустошах Дуротара. Их присутствие вызвало ожесточенную борьбу за земли с ночными эльфами из Среброкрылых Часовых. Движимые наследственным рвением, воины клана Песни Войны не собираются отдавать Ущелье Песни Войны и врубаются все глубже в древний лес, несмотря на бесконечные засады."}},faq={{q="Кто сейчас возглавляет клан Песни Войны?",a="После гибели Громмаша Адского Крика в конце Третьей войны клан Песни Войны в основном влился в Новую Орду Тралла. Его боевые отряды в полевых условиях, в частности Всадники Песни Войны в Ясеневом лесу, подчиняются местным командирам и верховной власти вождя Тралла.",al={"warsong leader","who is warsong chief","current warsong chieftain","предводитель песни войны","кто вождь песни войны","нынешний вождь песни войны"}},{q="Почему клан Песни Войны вырубает леса в Ясеневом лесу?",a="Новая Орда обосновалась на засушливых равнинах Дуротара и в Степях — землях, лишенных сколько-нибудь значительных запасов древесины. Клан Песни Войны отправили в богатые чащи Ясеневого леса, чтобы добывать древесину, необходимую для строительства городов вроде Оргриммара, поддержания военных укреплений и обеспечения растущей Орды.",al={"why harvest ashenvale","warsong lumber","orcs cutting trees ashenvale","зачем рубить ясеневый лес","древесина песни войны","орки рубят деревья в ясеневом лесу"}},{q="Как клан Песни Войны убил Кенария?",a="Во время Третьей войны полубог Кенарий возглавил ночных эльфов в жестокой обороне Ясеневого леса, доведя клан Песни Войны до отчаяния. Воины клана испили из источника, оскверненного кровью полководца Преисподней Маннорота, и превратились в орков Скверны, чья усиленная ярость позволила одолеть и убить Кенария.",al={"cenarius death","who killed cenarius","warsong vs cenarius","смерть кенария","кто убил кенария","песнь войны против кенария"}},{q="Как клан Песни Войны избежал лагерей для интернированных после Второй войны?",a="В отличие от многих орочьих кланов, захваченных по окончании Второй войны, Громмаш Адский Крик и клан Песни Войны избежали плена Альянса, укрывшись в глухих местах Лордерона. Они вели партизанскую войну и сохраняли боевой дух, пока их не нашел Тралл.",al={"warsong internment camps","grom evasion","warsong escape","лагеря интернированных песни войны","побег грома","побег песни войны"}},{q="Что такое Ущелье Песни Войны?",a="Ущелье Песни Войны — долина-каньон на юге Ясеневого леса, где Всадники Песни Войны непосредственно сталкиваются с ночными эльфами из Среброкрылых Часовых. Всадники сражаются, чтобы защитить свои лесозаготовки, а Часовые стремятся полностью изгнать орков из своего священного леса.",al={"wsg lore","what is warsong gulch","warsong battlefield","предания ущелья песни войны","что такое ущелье песни войны","поле боя песни войны"}},{q="Кто такой Громмаш Адский Крик?",a="Громмаш «Гром» Адский Крик был легендарным вождем клана Песни Войны и наставником Тралла. Хотя он первым из орков испил демонической крови на Дреноре, в конце концов он искупил вину и освободил всех орков от демонического рабства, убив полководца Преисподней Маннорота и пожертвовав при этом жизнью.",al={"who is grom","grom hellscream","grommash","кто такой гром","гром адский крик","громмаш"}}},fp="12,388,20.671.0,20.640.0,21.514.0,37.296.0,41.302.0,34.309.0,69.267.0,22.281.0,28.303.0"}
P.entries["topic:westfall-brigade"] = {n="Народное ополчение",s="Народное ополчение — стихийные силы обороны, созданные Грианом Камнегривом для защиты жителей Западного Края от Братства Справедливости. Эти добровольцы действуют из Сторожевого холма и остались одни с тех пор, как Штормград вывел войска из Западного Края. Они полагаются на местных фермеров и приезжих искателей приключений, чтобы сдерживать разгул бандитизма.",h="Народное ополчение — стихийные силы обороны, созданные Грианом Камнегривом для защиты жителей Западного Края...",kw={"defias brotherhood","edwin vancleef","gryan stoutmantle","moonbrook","people's militia","sentinel hill","sentinel tower","westfall brigade","братство справедливости","эдвин ван клиф","гриан камнегрив","луноречье","народное ополчение","сторожевой холм","сторожевая башня","ополчение западного края"},ang={["class:Warrior"]="Гриан Камнегрив и его защитники воплощают практичное лидерство на передовой: с потертыми клинками и самодельными доспехами они сдерживают превосходящего врага.",["faction:Alliance"]="Кризис в Западном Крае показывает опасные трещины в королевстве и напоминает героям Альянса, что мир в центральных землях хрупок.",["race:Human"]="Ополчение демонстрирует стойкость и отчаяние сельских жителей Штормграда, вынужденных защищать свои очаги, пока королевский двор закрывает глаза."},sec={{t="Покинутый край",b="Западный Край когда-то был житницей Королевства Штормград, но Штормград вывел войска и оставил людей без защиты. В образовавшейся пустоте бандиты Братства Справедливости в масках захлестнули равнины: захватывали семейные усадьбы, отбирали железные рудники и вымогали деньги у местных фермеров. Столкнувшись с беззаконием и не видя признаков королевской помощи, воин-ветеран Гриан Камнегрив собрал местных жителей и отставных солдат и создал Народное ополчение."},{t="Оборона Сторожевого холма",b="Ополчение, расположенное в Сторожевой башне на вершине Сторожевого холма, удерживает хрупкую границу на главных дорогах края. Без профессионального снаряжения и стабильных поставок защитники патрулируют пыльные дороги, а Камнегрив направляет добровольцев против растущего числа разбойников, воров и мародеров Братства Справедливости. Когда соседние земли, например Красногорье, просят о взаимной помощи, ополчению приходится отказывать: даже горстка людей означала бы полную гибель Западного Края."},{t="Раскрытие заговора",b="Благодаря неустанной разведке и помощи извне ополчение узнает истинный масштаб угрозы Братства Справедливости. Это не простые деревенские разбойники: Братством руководит Эдвин ван Клиф, бывший глава гильдии каменщиков, отстроивших Штормград. Действуя из подземных глубин Мертвых копей под Луноречьем, Братство намерено свергнуть само королевство, и измученное ополчение остается единственной стеной между столицей и открытым мятежом."}},faq={{q="Почему Народное ополчение сражается в одиночку, без армии Штормграда?",a="Штормград вывел войска из Западного Края и оставил людей без защиты, и никто в глубинке не знает причин. После этого Гриан Камнегрив собрал Народное ополчение, чтобы спасти остатки края.",al={"why no stormwind guard","where is stormwind army","why westfall abandoned","почему нет стражи штормграда","где армия штормграда","почему брошен западный край"}},{q="Кто возглавляет Народное ополчение?",a="Гриан Камнегрив, опытный ветеран-человек, основал отряд и руководит им из Сторожевой башни на Сторожевом холме.",al={"who leads westfall brigade","militia leader","gryan stoutmantle role","кто возглавляет ополчение западного края","лидер ополчения","гриан камнегрив"}},{q="Где находится их штаб?",a="Они действуют из Сторожевого холма, в центре которого стоит высокая каменная сторожевая башня в сердце Западного Края.",al={"militia base","where is sentinel hill","westfall militia base","база ополчения","где сторожевой холм","база ополчения западного края"}},{q="Может ли ополчение помочь другим землям в беде, например Красногорью?",a="Нет. Когда Мировой судья Соломон из Приозерья запросил военные резервы, Камнегриву пришлось отказать: ополчение едва держится в борьбе с Братством Справедливости.",al={"why wont they help lakeshire","solomon request stoutmantle","почему не помогут приозерью","соломон просьба камнегрив"}},{q="Кто главный враг ополчения?",a="Главный противник — Братство Справедливости, обширный преступный синдикат из бывших каменщиков, разбойников и грабителей с большой дороги под началом Эдвина ван Клифа.",al={"who are they fighting","militia enemy","defias enemy","с кем они сражаются","враг ополчения","враг братства справедливости"}}},fp="16,356,18.467.0,21.498.0,25.469.1,68.244.0,31.112.0,36.102.0,58.173.0,41.140.1"}
P.entries["topic:wildhammer-clan"] = {n="клан Громового Молота",s="Клан Громового Молота — суровая ветвь дворфов, живущая в единстве с природой, известная приручением диких грифонов и грозовыми молотами. Много веков назад изгнанные из родовой крепости Грим Батол, они создали независимый дом среди лесистых вершин Внутренних земель. Хотя они замкнуты по натуре, они остаются верными друзьями Альянса и защищают небо, когда их призывают.",h="Клан Громового Молота — суровая ветвь дворфов, живущая в единстве с природой, известная приручением диких...",kw={"aerie peak","falstad","grim batol","gryphon","hinterlands","khardros","kurdran","stormhammer","wildhammer","заоблачный пик","фалстад","грим батол","грифон","внутренние земли","кардрос","курдран","грозовой молот","громовой молот"},ang={["class:Hunter"]="Связь, которую горцы Громового Молота делят с дикими грифонами, — вершина укрощения зверей, основанная на пожизненном товариществе, а не на простом господстве.",["class:Shaman"]="Традиция Громового Молота направляет необузданную энергию бури через мистические молоты и хранит связь со стихией молний и природы, гораздо более древнюю, чем современные церковные традиции Стальгорна.",["faction:Alliance"]="Альянс во многом обязан господством в воздухе Громовым Молотам: их всадники на грифонах, наполненные силой молний, переломили ход Второй войны против красных драконов Орды.",["race:Dwarf"]="Для дворфа из Стальгорна Громовые Молоты — родичи, связанные древними клятвами. Хотя они предпочитают ветреные утесы и открытое небо глубоким шахтам, их храбрость с грозовым молотом вызывает глубочайшее уважение."},sec={{t="Изгнание из Грим Батола",b="До Войны трех молотов Громовые Молоты жили в предгорьях вокруг Стальгорна. Когда умер верховный король Модимус Старая Наковальня, гражданская война расколола королевство дворфов, и победившие Бронзобороды завладели Стальгорном. Тан Кардрос повел свой клан на север и основал великолепный оплот в вершине Грим Батола. Но мир был недолгим: побежденные дворфы Черного Железа вскоре осадили крепость. Кардрос лично убил колдунью Черного Железа Модгуд, но ее предсмертное проклятие так глубоко поразило гору, что залы стали непригодны для жизни. Отказавшись вернуться под власть Бронзобородов, Громовые Молоты выбрали самостоятельность и ушли на север, в леса и скалы Внутренних земель."},{t="Всадники бури",b="В цветущем нагорье своих новых земель Громовые Молоты построили Заоблачный Пик. В отличие от подземных сородичей, эти дворфы полюбили открытое небо и живой камень и обрели глубокую духовную связь с местными грифонами. Выковывая зачарованные грозовые молоты в укромных вольерах, Громовые Молоты стали лучшей воздушной кавалерией Азерота. Во время Второй войны, когда вождь Оргрим Молот Рока двинул войска к Кель'Таласу и напал на Заоблачный Пик, Верховный командующий Андуин Лотар и Альянс пришли им на помощь. В благодарность верховный тан Курдран Громовой Молот отдал своих всадников на грифонах коалиции, и они сражались в воздушных боях с порабощенными красными драконами Орды в небесах Лордерона и над Великим морем."},{t="Верные до конца",b="Когда Темный портал открылся вновь, Курдран Громовой Молот повел своих всадников в Дренор с экспедицией Альянса, пожертвовав возвращением ради закрытия разлома; этот подвиг увековечен колоссальной статуей в Аллее Героев Штормграда. В Заоблачном Пике клан возглавил верховный тан Фалстад. Даже когда человеческие королевства в последующие годы враждовали и распадались, Громовые Молоты оставались неизменными союзниками короля Теренаса Менетила II. Когда Плеть захлестнула Лордерон в Третьей войне, летуны Громового Молота снова поднялись в небо, отчаянно защищая союзные земли и невинных беженцев от ходячих мертвецов."}},faq={{q="Где сейчас находится клан Громового Молота?",a="Их главный оплот — Заоблачный Пик, расположенный в горном лесу Внутренних земель, к северу от Болотины и Моста Тандола.",al={"wildhammer home","where do wildhammers live","wildhammer location","дом громовых молотов","где живут громовые молоты","местоположение громовых молотов"}},{q="Почему Громовые Молоты не живут в Стальгорне?",a="После смерти верховного короля Модимуса Старая Наковальня клан Громового Молота проиграл Бронзобородам гражданскую войну за Стальгорн. Тан Кардрос повел клан на север строить новую жизнь в Грим Батоле, не желая склоняться перед властью Бронзобородов.",al={"why did wildhammer leave ironforge","war of the three hammers wildhammer","почему громовые молоты покинули стальгорн","война трех молотов громовые молоты"}},{q="Что случилось с их крепостью в Грим Батоле?",a="Во время Войны трех молотов колдунья Черного Железа Модгуд осадила Грим Батол. Тан Кардрос убил ее, но ее темное колдовство наполнило залы мерзкой скверной, и гора стала совершенно непригодной для жизни, вынудив клан уйти во Внутренние земли.",al={"why is grim batol abandoned","grim batol curse","modgud grim batol","почему грим батол заброшен","проклятие грим батола","модгуд грим батол"}},{q="Кто возглавляет клан Громового Молота сегодня?",a="Верховный тан Фалстад Громовой Молот руководит кланом из Заоблачного Пика. Он принял командование после того, как его предшественник Курдран Громовой Молот отправился с экспедицией Альянса через Темный портал.",al={"wildhammer leader","high thane wildhammer","who rules aerie peak","вождь громовых молотов","верховный тан громового молота","кто правит заоблачным пиком"}},{q="Как Громовые Молоты вступили в Альянс?",a="Во время Второй войны Оргрим Молот Рока напал на Внутренние земли, двигаясь к Кель'Таласу. Верховный командующий Андуин Лотар повел Альянс на защиту Заоблачного Пика и прогнал Орду и лесных троллей. Под впечатлением от их храбрости Громовые Молоты вступили в Альянс Лордерона.",al={"why are wildhammers alliance","wildhammer alliance history","почему громовые молоты в альянсе","история громовых молотов и альянса"}},{q="Тесно ли дворфы Громового Молота связаны союзом со Стальгорном?",a="Да. Хотя два клана воевали в Войне трех молотов, они объединились, чтобы победить дворфов Черного Железа. В честь своей дружбы они воздвигли Долину Королей в Лок Модане и с тех пор сохраняют прочный союз.",al={"bronzebeard wildhammer relationship","do ironforge and wildhammer get along","отношения бронзобородов и громовых молотов","ладят ли стальгорн и громовые молоты"}}},fp="15,408,21.732.0,19.709.0,16.624.0,45.134.0,44.240.0,46.268.0,36.176.0,42.286.0,57.238.0"}
P.entries["topic:worgen"] = {n="Ворген",s="Ворген — свирепые волкоподобные гуманоиды, проклятые неукротимой первобытной яростью: они ходят на двух ногах, но охотятся со звериной быстротой. Когда-то их считали лишь кошмарами, созданными в иных мирах, а теперь эти дикие хищники из стаи наводят ужас на Серебряный бор, Ясеневый лес и Сумеречный лес.",h="Ворген — свирепые волкоподобные гуманоиды, проклятые неукротимой первобытной яростью: они ходят на двух...",kw={"arugal","druids of the pack","goldrinn","pyrewood","scythe of elune","shadowfang keep","silverpine","ur","velinde starsong","worgen","аругал","друиды стаи","голдринн","погребальный лес","коса элуны","крепость темного клыка","серебряный бор","ур","велинда песнь звезд","ворген"},ang={["class:Druid"]="Ворген — непреходящая поучительная история об облике волчьей стаи, показывающая смертельную опасность призыва неукротимого гнева Голдринна без равновесия, которое дает Круг Кенария.",["class:Mage"]="Кирин-Тор Даларана долго спорил об исследованиях в мистических трудах Ура; катастрофическое призывание Аругала подтвердило предостережения Ура, что этих кошмарных существ нельзя призывать.",["race:NightElf"]="Существование ворген остается тщательно скрытой главой древней истории кальдораев, прямо связанной с войной с сатирами и скорбью жрицы Белисры и Малфуриона Ярость Бури.",["race:Undead"]="В Серебряном бору Отрекшиеся сражаются со стаями диких ворген и извращенными культистами Аругала за власть над землями к югу от Руин Лордерона."},sec={{t="Дети Стаи",b="Задолго до недавнего появления в Лордероне и Калимдоре о людях-волках шептались в народных сказках и поучительных баснях. На деле их истоки уходят более чем на девять тысячелетий назад, во времена войны с сатирами. Желая обуздать дикую ярость волка, древнего Голдринна, радикальные друиды из ночных эльфов под предводительством Ралаара Огненного Клыка приняли запретный облик волчьей стаи. Когда к нему добавилась священная Коса Элуны, магия яростно обернулась против них и превратила друидов в свирепых волкоподобных чудовищ, одержимых жаждой крови. Не умея отличать друга от врага, они своим ядовитым укусом передавали недуг другим ночным эльфам. Чтобы положить конец кошмару, Малфурион Ярость Бури и Круг Кенария изгнали проклятых оборотней под священные ветви Дарал'нира, в вечный сон в Изумрудном Сне."},{t="Безрассудство Аругала",b="Во время Третьей войны, когда орды Плети захлестнули Лордерон и двинулись к Стене Седогрива, верховный маг Аругал искал оружие, способное спасти Гилнеас. Опираясь на запретные исследования даларанского волшебника Ура, Аругал прорвал завесу и призвал спящих чудовищ в Серебряный бор. Призванные ворген с дикой яростью уничтожали нежить, но верховный маг не смог обуздать их ярость. Звери обратились против гилнеасских солдат, распространяя проклятие укусами и когтями. Обезумев от вины и одержимости, Аругал принял чудовищ как своих детей: он захватил родовую цитадель барона Сребролена, ныне переименованную в Крепость Темного Клыка, и обрек жителей ближних деревень на жизнь чудовищных ночных слуг."},{t="Пробуждение Косы",b="За морем, в Калимдоре, другое призывание вновь освободило ворген. Стремясь очистить Оскверненный лес от остатков демонов Пылающего Легиона, часовая из ночных эльфов Велинда Песнь Звезд откопала Косу Элуны. Направив силу древней реликвии, она призвала людей-волков, чтобы разорвать демонических сатиров. Но по мере хода сражений Велинда поняла, что коса вышла из-под ее власти: звери начали появляться без ее согласия и уходить в темные чащи Ясеневого леса и дальше. Теперь ворген бродят дикими стаями и сеют ужас везде, куда падает тень их лунной охоты."}},faq={{q="Кто такие ворген?",a="Ворген — свирепые волкоподобные гуманоиды, ходящие на двух ногах, наделенные устрашающей силой, хищными чувствами и темной магией тени. Они обитают в основном в уединенных лесах и руинах и охотятся стаями, во власти неукротимой звериной ярости.",al={"what is a worgen","worgen lore","wolf men","кто такие ворген","предания о ворген","люди-волки"}},{q="Откуда изначально появились ворген?",a="Изначально это были друиды из ночных эльфов, известные как Друиды Стаи. Во время войны с сатирами они стремились овладеть неукротимым духом волка, древнего Голдринна, но ритуал с Косой Элуны превратил их в алчных чудовищ, и Малфурион Ярость Бури изгнал их в Изумрудный Сон.",al={"worgen origin","who made worgen","how were worgen created","происхождение ворген","кто создал ворген","как появились ворген"}},{q="Как ворген оказались в Серебряном бору?",a="Во время Третьей войны верховный маг Аругал пробудил их ото сна, используя тайные исследования покойного даларанского волшебника Ура. Аругал надеялся, что они отразят Плеть, осаждавшую Стену Седогрива, но освобожденные звери напали на всех.",al={"silverpine worgen","why are worgen in silverpine","who summoned worgen","ворген серебряного бора","почему ворген в серебряном бору","кто призвал ворген"}},{q="Как человек становится ворген?",a="Недуг распространяется как заразная сверхъестественная хворь. Укус или царапина активного ворген заражает гуманоидов, и в итоге жертвы поддаются диким позывам и превращаются в волкоподобных зверей, если их не сдерживает сильная воля или особое колдовство.",al={"worgen curse","can you turn into a worgen","worgen bite","проклятие ворген","можно ли стать ворген","укус ворген"}},{q="Что такое Коса Элуны?",a="Коса Элуны — могущественная реликвия, созданная во время войны с сатирами путем соединения клыка волка, древнего Голдринна, с посохом Элуны. Она обладает глубокой и неустойчивой властью над проклятием ворген и способна призывать и распалять их.",al={"scythe of elune","scythe elune lore","коса элуны","предания о косе элуны"}},{q="Кто такой верховный маг Аругал?",a="Аругал — верховный маг Даларана, служивший Гилнеасу. Призвав ворген для борьбы с Плетью, он впал в безумие, бросил Гилнеас и стал править призрачными руинами Крепости Темного Клыка вместе со своими чудовищными «детьми».",al={"arugal","who is arugal","аругал","кто такой аругал"}},{q="Почему ворген есть в Ясеневом лесу и Калимдоре?",a="Часовая из ночных эльфов Велинда Песнь Звезд с помощью найденной Косы Элуны призвала ворген против демонических захватчиков в Оскверненном лесу. Вскоре реликвия начала сама втягивать ворген в мир, и стаи вырвались на свободу в Ясеневый лес.",al={"ashenvale worgen","kalimdor worgen","terrowulf","ворген ясеневого леса","ворген калимдора","волки-оборотни"}}},fp="6,273,20.806.0,14.723.0,17.623.1,16.241.0,42.310.0,43.245.0,33.266.0,28.250.0,23.228.0,41.239.0"}
P.entries["zone:alterac"] = {n="Альтеракские горы",s="Альтеракские горы — холодное разрушенное нагорье в центральной части Лордерона, прежде бывшее домом вероломного человеческого королевства Альтерак и ученой магократии Даларана. Сегодня заснеженные скалы заполонили огры Раздробленного Хребта, аристократические бандиты Синдиката и остатки магических сил. Путешественники приходят из ближних поселений предгорий и из восстанавливаемого города Даларан.",h="Альтеракские горы — холодное разрушенное нагорье в центральной части Лордерона, прежде бывшее домом...",kw={"alterac","crushridge","dalaran","perenolde","ravenholdt","strahnbrad","syndicate","uplands","альтерак","раздробленный хребет","даларан","перенольд","черный ворон","странбрад","синдикат","высокогорье"},ang={["class:Mage"]="Восстанавливаемые улицы Даларана полны остаточных тайных потоков и занятых работой магов Кирин-Тора; для мага это торжественное паломничество в разрушенное сердце человеческого волшебства.",["class:Rogue"]="Скрытая долина Поместья Черного Ворона лежит в восточных скалах Альтерака и предлагает элитные заказы, уроки взлома замков и тайны гильдии под присмотром лорда Джораха Черного Ворона.",["faction:Alliance"]="Путешественники из Альянса сталкиваются с ограми Раздробленного Хребта и преступниками Синдиката, занявшими бывшее королевство.",["faction:Horde"]="Клан Северного Волка обосновался в уединенных горах, а агенты Отрекшихся из Мельницы Таррен противостоят ограм и преступникам Синдиката.",["profession:Herbalism"]="Замерзшие скалы Альтерака известны травникам как единственное естественное место произрастания Морозника — важного компонента сильных зелий для холодного климата."},sec={{t="Павшее королевство",b="Во время Второй войны Альтерак был одним из Семи королевств людей, но король Эйден Перенольд предал Альянс Лордерона и перешел на сторону Старой Орды, надеясь сохранить свое государство. Его предательство раскрыли и подавили, а страна распалась на спорные пограничные земли. После роспуска королевства и ужасов Третьей войны величественная каменная столица Альтерака превратилась в груду обломков. Сегодня Руины Альтерака заняты жестокими ограми Раздробленного Хребта под предводительством Муг'тола, а уцелевшая человеческая знать объединилась в Синдикат — безжалостную преступную организацию, которая силой пытается вернуть свои утраченные владения."},{t="Восстанавливаемый город",b="На западной окраине гор, на берегу Озера Лордамер, находятся остатки великого города-государства Кирин-Тора — Даларана. Когда Архимонд разрушил город во время Третьей войны, уцелевшие маги окружили руины огромным непрозрачным фиолетовым куполом защитной магии. В Forever щит уже снят, а город все еще восстанавливается. Кирин-Тор продолжает отстраивать свою обитель, а верховного мага Ансарема Руноплета можно найти в Аметистовой цитадели."},{t="Границы конфликта",b="Искатели приключений часто отправляются в горы из Южнобережья или Мельницы Таррен, которые служат им опорными пунктами. Помимо бродячих йети, горных львов и разбойников Синдиката, главный конфликт региона бушует ниже снеговой линии. В глубине горных перевалов лежит Альтеракская долина, где дворфы из Стражи Грозовой Вершины сражаются с замкнутым орочьим кланом Северного Волка за древние права на земли и добычу руды."}},faq={{q="Что случилось с королевством Альтерак?",a="Во время Второй войны король Эйден Перенольд предал Альянс и помог Орде. Лордерон и Стромгард подавили измену и заняли эти земли. Когда в Третью войну Плеть прошла через Лордерон, остатки Альтерака рухнули в анархию, а разрушенную столицу заняли огры Раздробленного Хребта.",al={"why is alterac destroyed","what happened to perenolde","alterac kingdom lore","почему разрушен альтерак","что случилось с перенольдом","история королевства альтерак"}},{q="Что представляет собой Синдикат?",a="Синдикат — организация изгоев, образованная из лишенной владений знати Альтерака. Ею руководят бывшие альтеракские аристократы, такие как лорд Алиден Перенольд. Они нанимают головорезов, разбойников с большой дороги и опальных лордов, чтобы терроризировать окрестные земли и изгонять соперников, отчаянно стремясь вернуть родовые владения.",al={"who is the syndicate","why are there human bandits in alterac","syndicate lore","кто такой синдикат","почему в альтераке люди-бандиты","история синдиката"}},{q="Что случилось со светящимся куполом Даларана?",a="После того как Архимонд опустошил Даларан во время Третьей войны, уцелевший Кирин-Тор возвел над руинами защитный магический щит. В Forever они сняли щит раньше срока, пока город еще восстанавливался. Верховный маг Ансарем Руноплет теперь находится в Аметистовой цитадели.",al={"purple dome alterac","what is the violet bubble","dalaran shield","фиолетовый купол альтерак","что за лиловый пузырь","щит даларана"}},{q="Где найти пункты полета или безопасные таверны в Альтераке?",a="Южнобережье и Мельница Таррен в Предгорьях Хилсбрада — обычные места сбора для экспедиций в заснеженные горы. Даларан на западной окраине доступен в Forever, пока Кирин-Тор его восстанавливает.",al={"alterac flight path","alterac inn","alterac quest hub","пункт полета альтерак","таверна альтерак","задания альтерак"}},{q="Что такое Альтеракская долина?",a="Альтеракская долина — уединенная заснеженная долина, за которую борются дворфы из Стражи Грозовой Вершины и орочий клан Северного Волка. Дворфы из Стражи Грозовой Вершины прибыли в составе археологической экспедиции, что вызвало настоящую войну за территорию с Северными Волками, мирно жившими в долине со времен изгнания в Первую войну.",al={"av entrance","frostwolf vs stormpike","where is alterac valley","вход в альтеракскую долину","северные волки против грозовой вершины","где альтеракская долина"}},{q="Что такое Поместье Черного Ворона?",a="В укромной горной складке к востоку от главной дороги скрывается Поместье Черного Ворона — тайная гильдия Лиги убийц. Под началом лорда Джораха Черного Ворона оно служит местом обучения и убежищем для умелых разбойников со всего Азерота.",al={"where is ravenholdt","assassins manor alterac","thieves guild alterac","где поместье черного ворона","поместье убийц альтерак","гильдия воров альтерак"}}},fp="17,388,18.642.0,19.516.0,21.407.0,40.308.0,22.320.0,40.276.0,54.206.0,23.309.0,25.249.0"}
P.entries["zone:arathi"] = {n="Нагорье Арати",s="Нагорье Арати — суровое плато на юго-востоке Лордерона, известное как древняя родина Араторской империи. Сегодня королевство Стромгард лежит в руинах, а скалистый край охвачен войной на несколько фронтов между остатками Стромгарда, Ордой, преступной знатью Синдиката и вторгшимися ограми.",h="Нагорье Арати — суровое плато на юго-востоке Лордерона, известное как древняя родина Араторской империи.",kw={"arathi","arathi highlands","arathor","boulderfist","galen trollbane","hammerfall","refuge pointe","stromgarde","syndicate","thandol span","thoradin's wall","арати","нагорье арати","араторская империя","тяжелый кулак","гален троллебой","павший молот","опорный пункт","стромгард","синдикат","мост тандола","стена торадина"},ang={["class:Warrior"]="Стромгард создал самую прославленную на Азероте традицию передового боя, и его суровые поля сражений стали почитаемым испытанием оружием.",["faction:Horde"]="Павший Молот для современной Орды — священная земля, памятник жертве Оргрима Молота Рока, освободившего порабощенный народ из заточения.",["profession:Mining"]="Скалистые гряды Арати богаты железом и мифрилом, а Теснина Сухоусов — единственный известный источник малой кровавой руды.",["race:Human"]="Все человеческие королевства ведут свое начало от Араторской империи; видеть, как центр человеческой цивилизации разрушен и захвачен ограми и ворами, — глубокая культурная трагедия."},sec={{t="Колыбель человечества",b="Тысячелетия назад король Торадин объединил разрозненные племена людей под знаменем Арати и построил величественную столицу Строму на этих сухих, удобных для обороны равнинах. Именно здесь во время войн с троллями люди заключили легендарный союз с высшими эльфами и овладели тайными искусствами, чтобы отбросить Амани. Со временем знатные рода переселились на север, в Лордерон, и на юг, к Штормграду, но имперская стража осталась и образовала воинственное королевство Стромгард. Веками Стромгард оставался оплотом стойких воинов, сдерживавших лесных троллей."},{t="Разбитое королевство",b="Стромгард сыграл важную роль в обороне Альянса во время Второй войны при короле Торасе Троллебое, но Третья война и ее последствия сокрушили государство. Хотя королевство избежало худших ужасов чумы Плети, загадочная смерть короля Тораса ввергла страну в смуту. Огры Тяжелого Кулака хлынули с холмов, а предатели — альтеракская знать Синдиката — захватили обширные кварталы Крепости Стромгард. Сегодня принц Гален Троллебой и его верные уцелевшие бойцы держатся за крошечный клочок города и свой оплот в Опорном пункте, ведя ожесточенную партизанскую войну почти без надежды на победу."},{t="Война за нагорье",b="Арати — ожесточенно оспариваемый перекресток. На северо-востоке Орда превратила заброшенный человеческий лагерь для интернированных в Павший Молот, названный в честь легендарного вождя Оргрима Молота Рока, и использует его как опору, чтобы защитить северные владения и союзников в Хилсбраде. Тем временем племя троллей Сухокожих жаждет мести своим древним человеческим гонителям, а «Пробуждение Аргуса» дергает за ниточки за спиной оккупации Синдиката. В центре плато находятся древние Круги Связывания, где связанные элементали сдерживают загадочную древнюю силу, погребенную под камнем."}},faq={{q="Что случилось с Крепостью Стромгард?",a="После смерти короля Тораса Троллебоя Стромгард поддался внутренним раздорам и мощным нападениям. Огры Тяжелого Кулака захватили внешние кварталы города, а оппортунистический Синдикат занял святилище, и принц Гален Троллебой с редеющим гарнизоном держится в одном укрепленном углу, ведя отчаянные бои в собственной столице.",al={"why is stromgarde ruined","who controls stromgarde","stromgarde status","почему стромгард разрушен","кто контролирует стромгард","состояние стромгарда"}},{q="Что такое Павший Молот?",a="Павший Молот — укрепленный форпост Орды, построенный на месте человеческого лагеря для интернированных, где держали орков после Второй войны. Он назван в честь бывшего вождя Оргрима Молота Рока, павшего во главе кампании по освобождению пленников из лагерей по всему Лордерону.",al={"horde base arathi","history of hammerfall","why is it called hammerfall","база орды арати","история павшего молота","почему павший молот"}},{q="Где действует Альянс в Арати?",a="Солдаты Альянса и защитники Стромгарда действуют из Опорного пункта — естественно укрепленного каньона в центре нагорья. Оттуда они совершают вылазки, чтобы вернуть Крепость Стромгард и отразить натиск огров и троллей.",al={"alliance base arathi","refuge pointe","where are the stromgarde humans","база альянса арати","опорный пункт","где люди стромгарда"}},{q="Что это за каменные круги на равнинах?",a="Круги Связывания — Внутренний, Внешний, Восточный и Западный — древние магические печати, которые поддерживают и охраняют мятежные элементали. Они удерживают в заточении неведомую первородную сущность, погребенную глубоко под нагорьем.",al={"circles of binding","elementals in arathi","stone circles","круги связывания","элементали в арати","каменные круги"}},{q="Как попасть в Нагорье Арати?",a="Путники с севера и запада проходят через брешь в Стене Торадина из Предгорий Хилсбрада. Те, кто прибывает с юга из Каз Модана, пересекают огромный дворфийский мост — Мост Тандола, перекинутый через ущелье между нагорьем и Болотиной.",al={"getting to arathi","how to get to arathi highlands","arathi entrance","как добраться до арати","как попасть в нагорье арати","вход в арати"}},{q="Чем занимается Синдикат в Арати?",a="Синдикат состоит из изгнанной альтеракской знати, стремящейся создать новые владения, грабя павшие королевства. В Арати они захватили значительную часть Крепости Стромгард и дальние фермы вроде Северного поместья, а тайно ими руководят темные культисты Пробуждения Аргуса.",al={"why is syndicate in arathi","syndicate stromgarde","who leads the syndicate here","почему синдикат в арати","синдикат стромгард","кто возглавляет синдикат здесь"}}},fp="16,328,18.594.0,19.625.0,25.593.1,33.371.0,19.278.0,42.251.0,45.213.0,38.274.0,38.271.1"}
P.entries["zone:ashenvale"] = {n="Ясеневый лес",s="Ясеневый лес — древний, пропитанный дождями лес предков ночных эльфов, священный и находящийся под защитой Часовых и полубога Кенария. Граничит со Степями на юге и Темными берегами на севере. Сейчас здесь идет ожесточенная война: Орда заготавливает древесину для строительства своего молодого государства. Древние деревья и тихие лунные колодцы соседствуют под одним пологом с остатками демонов, враждебными зверолюдами и очагами схваток на спорной границе.",h="Ясеневый лес — древний, пропитанный дождями лес предков ночных эльфов, священный и находящийся под защитой...",kw={"ashenvale","astranaar","bough shadow","cenarius","grommash","mannoroth","silverwing","splintertree","warsong","zoram","ясеневый лес","астранаар","тенистая крона","кенарий","громмаш","маннорот","среброкрылые","расщепленное дерево","песнь войны","зорам"},ang={["class:Druid"]="Равновесие природы здесь осаждено сразу с нескольких сторон. Из-за вырубок, оскверненных берлог фурболгов и портала в Тенистой Кроне, где бродят порождения Кошмара, Ясеневому лесу отчаянно необходимо восстановление силами Круга Кенария.",["profession:Herbalism"]="Питаемый древними магическими потоками и непрекращающимися дождями, Ясеневый лес — одна из самых богатых мест Калимдора для сбора остротерна, удавника, королевской крови и редкой Крови Грома у демонических шрамов.",["race:NightElf"]="Ясеневый лес — ваш духовный дом и наследие Кенария. Защищать его рощи от топоров Песни Войны и очищать лунные колодцы от порчи сатиров — дело изначальной чести кальдораев.",["race:Orc"]="Эта древесина идет на стены и осадные башни Оргриммара. Это также священная земля, где Громмаш Адский Крик пролил кровь, чтобы избавить орков от демонического рабства."},sec={{t="Шепчущий полог",b="Ясеневый лес раскинулся у подножия горы Хиджал и тысячелетиями находится под защитой ночных эльфов и детей Кенария. Огромные деревья сплетаются в густой полог, который превращает ежедневный дождь в легкую морось и погружает лесную подстилку в вечные сумерки. Сквозь мох проступают древние руины эльфийской цивилизации, которые охраняют ходячие древни и дриады. Тысячи лет ночные эльфы не строили здесь настоящих городов: они предпочитали охотиться бережно и сохранять дикие земли в первозданном равновесии."},{t="Война за леса",b="Мир был нарушен во время Третьей войны, когда Громмаш Адский Крик и клан Песни Войны вошли в лес за древесиной и убили Кенария, поддавшись демонической жажде крови. Сегодня, в 25 году по ЭТП, борьба превратилась в полномасштабную территориальную войну. С Заставы Расщепленного Дерева и южной Заставы Мор'шан Всадники Песни Войны направляют топоры и крошшеры в восточные леса, чтобы снабжать Оргриммар. Среброкрылые Часовые, чья база находится в городе-убежище Астранаар, поклялись изгнать из священной рощи всех орков-лесорубов до единого."},{t="Затянувшиеся тени",b="Война за древесину — далеко не единственная угроза Ясеневого леса. Пылающий Легион оставил изуродованные язвы на Холме Демонического Огня и в Каньоне Гибели Демона, где погиб Маннорот. Жестокие сатиры действуют из руин вроде Сатирнаара и Ксавиана, оскверняя воды и животных. Племена фурболгов, некогда друзей эльфов, в большинстве своем поддались темному безумию. Тем временем таинственные воргены бродят у северного святилища близ Оскверненного леса, а проклятые дракониды обходят Тенистую Крону, охраняя портал в тревожный Изумрудный Сон."}},faq={{q="Почему Орда и Альянс воюют в Ясеневом лесу?",a="В сухом краю орков Дуротара почти нет древесины, и она отчаянно нужна им из Ясеневого леса для строительства Оргриммара и развития молодого государства. Для ночных эльфов Ясеневый лес — священная родина предков, находящаяся под защитой божеств природы. Среброкрылые Часовые считают вырубку, которую ведет клан Песни Войны, невыносимым осквернением, что порождает постоянные стычки и жаркую борьбу в Ущелье Песни Войны.",al={"why horde cutting trees","ashenvale war reason","warsong vs silverwing","почему орда рубит деревья","причина войны в ясеневом лесу","песнь войны против среброкрылых"}},{q="Что случилось с Кенарием в этом лесу?",a="Во время Третьей войны Громмаш Адский Крик привел клан Песни Войны в Ясеневый лес за древесиной. Кенарий напал на орков, защищая священную рощу. Отчаявшись победить полубога, Громмаш и его клан испили из источника, оскверненного владыкой преисподней Манноротом, обрели демоническую ярость и убили Кенария. Хотя позже Гром снял проклятие, убив Маннорота в Каньоне Гибели Демона, эльфы не забыли убийство своего покровителя-полубога.",al={"how cenarius died","grom killed cenarius","cenarius fate","как умер кенарий","гром убил кенария","судьба кенария"}},{q="Что такое Непроглядная Пучина?",a="Непроглядная Пучина — затонувший храмовый комплекс под Зорамским взморьем на северо-западном побережье Ясеневого леса. Прежде это был древний храм кальдораев, посвященный Элуне, но во время Великого Раскола он рухнул в море. Теперь им владеют свирепые наги, культисты Сумеречного Молота и морские твари, почитающие древнюю гидру Аку'май.",al={"where is bfd","bfd lore","blackfathom deeps history","где бфд","бфд история","непроглядная пучина история"}},{q="Что такое Великое Древо в Тенистой Кроне?",a="В Тенистой Кроне находится одно из четырех Великих Древ, посаженных Кругом Кенария тысячи лет назад, чтобы закрепить проходы в Изумрудный Сон и сдерживать порчу саронита. Оно служит действующими вратами между Азеротом и Сном. Зеленые дракониды охраняют это место, хотя зловещая порча в Сне порой гонит через портал чудовищных драконов Кошмара.",al={"bough shadow tree","portal bough shadow","green dragons ashenvale","дерево тенистая крона","портал тенистая крона","зеленые драконы ясеневый лес"}},{q="Почему фурболги в Ясеневом лесу враждебны?",a="Хотя ночные эльфы веками поддерживали с фурболгами мирный союз, демоническая порча, оставленная вторжением Пылающего Легиона, разрушила их разум. Остаточная магия Скверны, исходящая из таких мест, как Оскверненный лес, Сатирнаар и Каньон Гибели Демона, ввергла племена вроде Колючего Меха в яростное безумие, и они стали враждебны и к чужакам, и к сородичам.",al={"crazy furbolgs ashenvale","thistlefur corrupt","why furbolgs attack","безумные фурболги ясеневый лес","колючий мех порча","почему фурболги нападают"}},{q="Кто похоронен в Каньоне Гибели Демона?",a="Каньон Гибели Демона — поле битвы, где Громмаш Адский Крик и Тралл сразились с владыкой преисподней Манноротом. Гром нанес повелителю демонов смертельный удар и освободил орков от демонического проклятия крови ценой собственной жизни. Разбитые доспехи Маннорота до сих пор установлены там на каменном монументе в память о жертве Адского Крика.",al={"mannoroth canyon","grommash grave ashenvale","monument demon fall","каньон маннорота","могила громмаша ясеневый лес","монумент гибели демона"}},{q="Как добраться через Ясеневый лес?",a="Путники Альянса обычно входят через северный горный перевал от Аубердина на Темных берегах и идут по дороге на восток к Астранаару. Искатели приключений Орды идут на север из Степей через укрепленную Заставу Мор'шан к Заставе Расщепленного Дерева или на запад к Форту Зорам'гар на Зорамском взморье. Обе фракции держат распорядителей полетов в своих главных крепостях.",al={"how to get to ashenvale","ashenvale travel","ashenvale flight paths","как добраться до ясеневого леса","путь в ясеневый лес","полеты ясеневый лес"}}},fp="9,447,21.513.0,17.529.0,17.498.0,53.418.0,41.449.0,26.349.0,39.381.0,42.356.0,35.350.0,34.371.0"}
P.entries["zone:azshara"] = {n="Азшара",s="Азшара — суровое, продуваемое ветрами побережье на северо-востоке Калимдора, покрытое яркой вечной осенней листвой. Когда-то она была частью великолепной столицы ночных эльфов, пока Великий Раскол не погрузил ее в море. Теперь это опасная глушь с древними руинами, мрачными нагами и отшельниками-чародеями. И Орда, и Альянс держат на ее границах ненадежные форпосты, опасаясь беспокойных призраков и морских ужасов.",h="Азшара — суровое, продуваемое ветрами побережье на северо-востоке Калимдора, покрытое яркой вечной осенней...",kw={"azshara","azuregos","bay of storms","coral sea","eldarath","highborne","spitelash","talrendis point","valormok","xylem","азшара","азурегос","залив бурь","коралловое море","эльдарат","высокорожденные","злобный хлыст","застава талрендис","храбростан","ксилем"},ang={["class:Mage"]="Разбитые камни Эльдарата все еще потрескивают забытым колдовством высокорожденных, а высоко над утесами нелюдимый верховный маг Ксилем испытывает тех, кто стремится овладеть тайной телепортацией и искусством заклинаний.",["profession:Herbalism"]="Вечный осенний климат Азшары питает редкие и мощные травы, среди которых Снолист, Золотой сансам, Горный серебряный шалфей и Лиловый лотос среди руин.",["profession:Mining"]="Крутые прибрежные утесы и зубчатые гряды Азшары богаты ценными рудными жилами с обильными залежами мифрила, истинного серебра и тория.",["race:NightElf"]="Каждая затонувшая колонна и стонущая тень высокорожденного в Азшаре — мрачное, преследующее свидетельство безрассудного высокомерия королевы Азшары и катастрофической гибели древней цивилизации кальдораев."},sec={{t="Затонувшая империя",b="Десять тысяч лет назад это побережье было сердцем цивилизации кальдораев и окружало королевскую столицу Зин-Азшари. Когда королева Азшара и ее двор высокорожденных привели Пылающий Легион в Азерот, Война Древних завершилась катастрофическим обрушением Источника Вечности. Море хлынуло внутрь, поглотив большую часть великолепного города и оставив расколотые утесы, коварные коралловые рифы и затопленные шпили. Выжившие назвали разрушенную землю в честь павшей правительницы, сделав ее проклятым памятником гордыне и страшному предательству."},{t="Осенняя краса и скрытые опасности",b="Азшара известна великолепным багряным, оранжевым и золотым пологом, создающим впечатление вечной осени без смены времен года. Но под этим тихим пологом лежит негостеприимная земля. Оскверненные сатиры творят темные ритуалы в лесных лощинах, остатки призраков высокорожденных бродят по затонувшим основаниям, а наги Злобного Хлыста рыщут на мелких рифах Коралового моря. Свирепые звери, гигантские гидры и горные великаны свободно бродят по нагорьям и белым пляжам."},{t="Край изгнанников и отверженных",b="Из-за уединенности и сурового рельефа Азшара привлекает отшельников, занятых забытыми ремеслами или стерегущих опасные силы. Загадочный верховный маг Ксилем обитает в уединенной башне высоко над утесами и испытывает как многообещающих заклинателей, так и ловких разбойников. Дальше по берегу охотник на демонов Лорамус Многоног наблюдает за волнами с пустынного острова, а огромный морской великан лорд Арккорос требует кровавых жертв в своем храме над бурлящими водами."}},faq={{q="Почему здесь все деревья красные и оранжевые?",a="Азшара покрыта вечной осенью. Яркий оранжевый, золотой и красный полог никогда не сбрасывает листву, придавая прибрежным лесам поразительно красивую и меланхоличную атмосферу, сохраняющуюся тысячи лет.",al={"why is azshara autumn","why are trees red","azshara fall foliage","почему в азшаре осень","почему деревья красные","осенняя листва азшара"}},{q="Как Азшара превратилась в руины?",a="Это побережье когда-то было окраиной столицы кальдораев, Зин-Азшари. Во время Войны Древних Источник Вечности сжался внутрь при Великом Расколе, расколов континент и отправив огромные части города в море.",al={"what happened to azshara","why is azshara broken","azshara history","что случилось с азшарой","почему азшара разрушена","история азшары"}},{q="Кто правит Азшарой сегодня?",a="Ни одна фракция не владеет этой территорией безраздельно. Альянс держит небольшой пост на Заставе Талрендис возле Ясеневого леса, а Орда действует из лагеря Храбростан. Окрестные земли заполонили опасные наги Злобного Хлыста, свирепые сатиры и дикие чудовища.",al={"who controls azshara","who runs azshara","is azshara alliance or horde","кто контролирует азшару","кто правит азшарой","азшара альянс или орда"}},{q="Кто такой верховный маг Ксилем?",a="Верховный маг Ксилем — эксцентричный человек-чародей, живущий в отдаленной башне на утесе над Азшарой. Не примыкая к региональной политике, он помогает приходящим магам и разбойникам раскрыть особый боевой и тайный потенциал с помощью трудных испытаний.",al={"xylem azshara","mage tower azshara","wizard in azshara","ксилем азшара","башня мага азшара","волшебник в азшаре"}},{q="Что делает синий дракон в руинах?",a="Великий синий дракон Азурегос и его род стерегут древние руины Эльдарата. Он яростно защищает могущественные магические артефакты высокорожденных, еще погребенные под обломками, от разграбления смертными.",al={"azuregos in azshara","blue dragon azshara","dragon in eldarath","азурегос в азшаре","синий дракон азшара","дракон в эльдарате"}},{q="Почему ночные эльфы считают эту землю проклятой?",a="Кальдораи считают Азшару проклятой, потому что она носит имя и архитектурное наследие их вероломной королевы Азшары, чей союз с Пылающим Легионом разрушил их империю и принес гибель миру.",al={"is azshara cursed","why do night elves hate azshara","night elf curse azshara","проклята ли азшара","почему ночные эльфы ненавидят азшару","проклятие азшары ночных эльфов"}}},fp="7,468,16.604.0,33.497.0,30.492.0,42.223.0,30.253.0,24.285.0,22.248.0,43.213.0,49.212.0"}
P.entries["zone:badlands"] = {n="Бесплодные земли",s="Бесплодные земли — засушливая, выжженная солнцем равнина из потрескавшейся земли, пыльных бурь и скалистых каньонов, расположенная между Лок Моданом и Тлеющим ущельем. Несмотря на то что они лежат в глубине дворфийского Каз Модана, это неспокойное приграничье, где господствуют дворфы Черного Железа, трогги, огры из клана Гнилобрюхов и гнездящиеся черные драконы. Здесь также находятся титанические руины Ульдамана и оплот Орды — Каргат, что делает эти земли важным стратегическим пунктом.",h="Бесплодные земли — засушливая, выжженная солнцем равнина из потрескавшейся земли, пыльных бурь и скалистых...",kw={"angor fortress","badlands","dustbelcher","earthen","goretooth","kargath","lethlor","troggs","uldaman","крепость ангор","бесплодные земли","гнилобрюхи","дустбельчер","земельники","клинозуб","каргат","летлор","трогги","ульдаман"},ang={["faction:Horde"]="Каргат — ваше единственное военное убежище в глубине Каз Модана, передовая линия против Темной Орды, занявшей Черную гору.",["profession:Mining"]="Засушливая местность богата железом, золотом, истинным серебром и мифрилом, включая редкие залежи индурия в Ульдамане и его окрестностях.",["race:Dwarf"]="В Бесплодных землях, в Ульдамане, хранятся ответы о вашем собственном происхождении: открытие созданных титанами земельных изменило понимание дворфами своей истории."},sec={{t="Унылое приграничье",b="Бесплодные земли лежат к югу от зеленых холмов Лок Модана и быстро превращаются в раскаленную котловину из голых равнин и неровных оврагов. Чтобы выжить здесь, приходится бороться с беспощадными койотами, пумами, стервятниками и яростными песчаными бурями, скрывающими горизонт. На плато разбросаны грубые стоянки огров клана Гнилобрюхов, а мрачный клан Черного Железа укрепил Крепость Ангор и вступает в схватку со всеми, кто вторгается на его земли."},{t="Тайны Ульдамана",b="На северных утесах находится Ульдаман — древний подземный комплекс, высеченный созданными титанами земельными. Недавно его обнаружили стальгорнские рудокопы, и раскопки открыли великие тайны о древнем происхождении дворфов. Однако раскопки подземных хранилищ пробудили полчища свирепых троггов Каменного Свода и оживших земельных стражей, которые истребляли команды археологов и превратили места раскопок снаружи в кровавые поля стычек."},{t="Тени Каргата и Летлора",b="Бесплодные земли — один из самых шатких плацдармов Орды на юге Восточных королевств. Крепость Каргат на северо-западе служит войскам вождя Тралла базой, откуда ведется наблюдение за мятежной Темной Ордой в соседней Черной горе. А далеко на востоке лежит Долина Летлор — коварная пропасть, где черные дракончики и опасные черные дракониды охраняют свои гнездовья в тени гор."}},faq={{q="Почему Орда расквартирована в Бесплодных землях?",a="Застава Каргат была основана экспедиционным корпусом Каргата по приказу вождя Тралла. Лагерь под командованием полководца Клинозуба дает Орде важный плацдарм для удара по Ренду Черноруку и его мятежному клану Черной горы, засевшему в Черной горе.",al={"why kargath","horde in badlands","what is kargath","почему каргат","орда в бесплодных землях","что такое каргат"}},{q="Как добраться до Бесплодных земель?",a="Путешественники из Альянса могут пройти прямо на юг от Лок Модана через проход Террасы Творца. Путникам из Орды предстоит более долгий путь пешком через южные холмы Лок Модана или через Тлеющее ущелье по западному горному перевалу, пока не откроется доступ к распорядителю полетов Каргата.",al={"getting to badlands","how to reach badlands","badlands entrance","как попасть в бесплодные земли","как добраться до бесплодных земель","вход в бесплодные земли"}},{q="Что такое Ульдаман?",a="Ульдаман — огромное подземное хранилище, построенное древними титанами и их земельными слугами. Недавно дворфы-рудокопы раскопали его в поисках тайн своего происхождения, но раскопки пробудили погребенных земельных големов и примитивных троггов Каменного Свода, превратив руины в смертельное поле битвы.",al={"what's uldaman","uldaman dungeon lore","who made uldaman","что такое ульдаман","ульдаман лор","кто построил ульдаман"}},{q="Что делают черные драконы в Долине Летлор?",a="Долина Летлор служит восточным каньоном для размножения и гнездования черного драконьего рода. Кладка, охраняемая драконами и дракончиками, сохраняет опасное присутствие возле гор, нападая на странников и не пуская чужаков в восточные земли.",al={"dragons in badlands","lethlor ravine dragons","black dragonflight badlands","драконы в бесплодных землях","драконы долины летлор","черный драконий род бесплодные земли"}},{q="Кто владеет Крепостью Ангор?",a="Крепость Ангор принадлежит враждебному клану Черного Железа. Крепость находится к югу от Ульдамана и служит региональной базой, откуда дворфы Черного Железа ведут разведку, оспаривают титанические места раскопок и сражаются с соседними ограми и исследователями с поверхности.",al={"angor fortress","badlands fortress","dark irons badlands","крепость ангор","крепость в бесплодных землях","дворфы черного железа бесплодные земли"}},{q="Есть ли здесь дружественные поселения для игроков Альянса?",a="Нет. В Бесплодных землях нет укрепленных поселений Альянса и распорядителей полетов. Стальгорнские рудокопы и отшельники-одиночки держат разрозненные хрупкие лагеря возле мест раскопок, но искателям приключений из Альянса за серьезными припасами придется обращаться к базам в Лок Модане или Тлеющем ущелье.",al={"alliance town badlands","alliance flight path badlands","friendly alliance badlands","город альянса бесплодные земли","полеты альянса бесплодные земли","дружественный альянс бесплодные земли"}}},fp="8,424,16.453.0,22.466.0,34.449.0,43.300.0,31.273.0,16.301.0,51.257.0,28.244.0,61.268.0"}
P.entries["zone:barrens"] = {n="Степи",s="Степи — обширная выжженная солнцем саванна, географическое и логистическое сердце Орды в центральном Калимдоре. Когда-то, до Великого Раскола, здесь рос зеленый лес, а теперь это засушливая равнина с красной пылью, жестким кустарником и бродячими животными. В центре земель находится стратегический узел — Перекресток, а край ведет непрерывную борьбу с племенами свинобразов, набегами кентавров и ползучей порчей.",h="Степи — обширная выжженная солнцем саванна, географическое и логистическое сердце Орды в центральном...",kw={"barrens","crossroads","gold road","kolkar","naralex","quilboar","ratchet","taurajo","wailing caverns","степи","перекресток","золотой путь","колкар","наралекс","свинобразы","кабестан","таурахо","пещеры стенаний"},ang={["class:Druid"]="Искаженные воды, текущие из Пещер Стенаний, — глубокая трагедия: благородная попытка Наралекса возродить Степи уступила кошмару.",["class:Shaman"]="Засушливые равнины проверяют вашу связь со стихиями — от иссушенных духов земли равнин до зачарованных, измененных вод, бьющих в уединенных оазисах.",["faction:Horde"]="Степи — логистическая опора вашего государства: защита Перекрестка и обозов на Золотом Пути обеспечивает выживание Оргриммара и Громового Утеса.",["race:Tauren"]="До высадки орков в Калимдоре ваши кочевые предки поколениями бродили по этим саваннам, охотясь на священную дичь и борясь за выживание против безжалостных кентавров Колкара."},sec={{t="Сердце Новой Орды",b="На протяжении бесчисленных поколений кочевые таурены охотились на кодо и жевр на этих равнинах, ведя оборонительную, цикличную войну с кентаврами Колкара. Когда во время Третьей войны Тралл привел орков в Калимдор, он помог Кэрну Кровавому Копыту отразить кентавров и пройти через саванну в Мулгор. Сегодня Степи соединяют Дуротар, Мулгор и Ясеневый лес. Форпосты вроде Перекрестка и Лагеря Таурахо защищают торговлю на Золотом Пути, а орочьи хутора стойко переносят засушливый климат, создавая прочный дом."},{t="Земля в осаде",b="Несмотря на господство Орды, власть над саванной ожесточенно оспаривается. Иглогривые свинобразы, похожие на дикобразов, яростно грабят фермы и линии снабжения из своих заросших терновником оплотов, опираясь на мрачные логова Лабиринтов Иглошкурых на юге. На восточном побережье силы Терамора удерживают Крепость Северной Стражи, а дворфийские старатели вгрызаются в комплекс титанов Бейл Модан. Тем временем гоблины Кабестана поддерживают шаткий торговый нейтралитет и привечают любого путника с монетой."},{t="Изумрудная порча",b="Несколько оазисов разбросаны по северным равнинам, и их воды неестественно полны животворной силы. Этот поток исходит из Пещер Стенаний, где ночной эльф-друид Наралекс пытался обратиться к Изумрудному Сну, чтобы вернуть Степям их древний лесной облик. Вместо этого кошмар исказил видение Наралекса. Теперь испорченная вода просачивается по Забытым прудам и Застывшему оазису, порождая странную извращенную флору, неестественных зверей и отколовшихся Друидов Клыка."}},faq={{q="Почему посреди пустыни есть пышные оазисы?",a="Внезапные водоемы, такие как Забытые пруды и Цветущий оазис, питаются подземными источниками, вытекающими из Пещер Стенаний. Ночной эльф-друид Наралекс обратился к Изумрудному Сну, чтобы направить воды источников и снова озеленить засушливую землю, но затея пошла не так и наполнила северные Степи мощной, неустойчивой магией природы.",al={"barrens oases","why is there water in barrens","wailing caverns water","оазисы степей","почему в степях есть вода","вода пещер стенаний"}},{q="Кто контролирует Перекресток?",a="Перекресток охраняет Орда, главным образом воины-орки и таурены, служащие вождю Траллу. Он расположен на пересечении главных торговых путей, соединяющих Дуротар, Мулгор и Ясеневый лес, и потому служит главным стратегическим военным и транзитным узлом Орды в центральном Калимдоре.",al={"who runs crossroads","crossroads horde","crossroads guards","кто управляет перекрестком","перекресток орда","стража перекрестка"}},{q="Почему свинобразы нападают на всех?",a="Свинобразы считают Степи своим исконным правом и верят, что гигантские колючие заросли проросли из крови их полубога Агамаггана во время Войны Древних. Они видят и прибывшую Орду, и местных тауренов захватчиками, крадущими их священные места сбора пищи и охотничьи угодья.",al={"quilboar lore","why quilboar aggressive","razormane motive","свинобразы","почему свинобразы агрессивны","мотивы иглогривых"}},{q="Почему в Степях есть солдаты Альянса?",a="Альянс сохраняет присутствие по краям саванны. Крепость Северной Стражи удерживают люди из Терамора, наблюдающие за передвижениями Орды, а дворфы Бейл Модана и Крепости Бейл'дан всецело поглощены раскопками древних титанических артефактов, погребенных в южных холмах.",al={"northwatch hold alliance","bael modan dwarves","alliance in barrens","крепость северной стражи альянс","дворфы бейл модана","альянс в степях"}},{q="Входит ли Кабестан в Орду?",a="Нет. Кабестан — независимый гоблинский порт под управлением Газлоу. Он строго нейтрален и служит воротами для морской торговли, контрабандистов и искателей приключений как из Орды, так и из Альянса, при условии что все уважают гоблинскую торговлю и не обнажают оружие в городе.",al={"is ratchet horde","ratchet faction","gazlowe ratchet","кабестан орда","фракция кабестана","газлоу кабестан"}},{q="Что происходит с силитидами на юге?",a="Насекомоподобные существа, называемые силитидами, выбрались из земляных ульев на юге Степей, особенно вокруг Полей Великанов. Их внезапное появление и быстрый рост колоний создают растущую угрозу для путников и местных застав, и Орда решила выяснить их происхождение.",al={"barrens bugs","field of giants bugs","silithid south barrens","жуки степей","жуки полей великанов","силитиды юг степей"}}},fp="11,432,22.521.0,18.482.0,22.482.1,51.341.0,28.293.0,40.311.0,41.300.0,29.271.0,48.290.0"}
P.entries["zone:blackfathom"] = {n="Непроглядная Пучина",s="Непроглядная Пучина — затопленный подземный храмовый комплекс на Зорамском взморье, на северо-западе Ясеневого леса. Когда-то это было святилище ночных эльфов, посвященное богине луны Элуне, но теперь затонувший храм захватили культ Сумеречного Молота, коварные наги и сатиры. В его темных водах они собираются, чтобы поклоняться Аку'май — изначальной питомице и вестнице Древних богов, и растить ее.",h="Непроглядная Пучина — затопленный подземный храмовый комплекс на Зорамском взморье, на северо-западе...",kw={"aku'mai","bfd","blackfathom","deeps","gelihast","ghamoo-ra","kelris","lathar'lazal","sarevess","zoram","аку'май","бфд","непроглядная пучина","пучина","гелихаст","гхаму-ра","келрис","латар'лазал","саревесс","зорам"},ang={["class:Shaman"]="Шаманы, откликнувшиеся на зов Дже'ну и Служителей Земли, должны погрузиться в водную тьму, чтобы остановить порчу стихий и изгнать хаотичную скверну Древних богов.",["faction:Alliance"]="Герои Альянса приходят сюда, чтобы спасти Разведчика Талрида, вернуть утраченные знания высокорожденных и помочь ночным эльфам очистить их священную родину от ужаса сектантов.",["faction:Horde"]="Действуя из Форта Зорам'гар, Орда стремится обезопасить северное побережье Ясеневого леса от натиска нагов и не дать темным ритуалам в Пучине угрожать ее аванпостам.",["race:NightElf"]="Для ночных эльфов Пучина — душераздирающее осквернение их наследия: древнее святилище Элуны и его священный лунный колодец осквернены сектантами Бездны и чудовищными порождениями."},sec={{t="Затонувшее святилище Элуны",b="Задолго до того, как Великий Раскол разрушил древний Калимдор, этот комплекс назывался Латар'Лазал и был великолепным храмом, посвященным Элуне. Каменщики-высокорожденные возводили мосты, усыпанные самоцветами, а королева Азшара повелевала окружающими водами, разделяя соленые моря и горные ручьи вокруг священного лунного колодца. Когда десять тысяч лет назад Раскол разорвал мир на части, храм погрузился в прибрежные глубины Сокрытого Моря. Тысячелетиями он лежал под волнами нетронутым — пока из подземной тьмы не начали подниматься зловещие шепоты."},{t="Логово древних ужасов",b="Привлеченные безумными снами и темными знамениями, сектанты Сумеречного Молота собрались у затонувших руин. Там они заключили нечестивый союз с прибрежными нагами во главе с леди Саревесс и рыскающими сатирами. Вместе они осквернили лунный колодец и поработили местных существ. Годами мучений они довели гигантскую морскую черепаху Гхаму-ра до безумия, позволили жестокому мурлоку Гелихасту возвести кровавое святилище и пополняли пещерные глубины свежими жертвами. Под предводительством Повелителя сумрака Келриса сектанты превратили руины в плацдарм для грядущего возвращения Древних богов."},{t="Спящий вестник",b="В самом сердце затонувшего храма лежит Аку'май — древняя трехглавая гидра, несущая искру изначальной силы Древних богов. Повелитель сумрака Келрис верит, что этот пожиратель — вестник его темных владык и его личный путь к бессмертию. Культ относится к Аку'май не как к дикому зверю, а как к драгоценной божественной питомице: чтобы взрастить ее силу, ей скармливают своих подчиненных и пленников. Если убить Келриса и погасить мерзкие жаровни культа, разрушатся чары, охраняющие ее логово, и герои смогут сразить чудовище, пока его ненасытный голод не обрушился на Калимдор."}},faq={{q="Чем была Непроглядная Пучина до того, как погрузилась во тьму?",a="Первоначально она называлась Латар'Лазал и была великолепным храмом ночных эльфов, посвященным богине луны Элуне. В нем были кристально чистые бассейны, мосты с самоцветами и благословенный лунный колодец, и всем этим управляла королева Азшара, пока Великий Раскол не разрушил храм и не погрузил его под воду.",al={"bfd history","who built bfd","original temple","история бфд","кто построил бфд","первоначальный храм"}},{q="Почему здесь находятся сектанты Сумеречного Молота?",a="Привлеченные кошмарными видениями и шепчущими голосами из-под Азерота, сектанты пришли поклоняться Древним богам. Под предводительством Повелителя сумрака Келриса они захватили затонувшие руины, чтобы растить Аку'май, принося живые жертвы в надежде приблизить возвращение своих хаотичных владык.",al={"cultists in bfd","why is twilight's hammer here","what do cultists want","сектанты в бфд","почему здесь сумеречный молот","чего хотят сектанты"}},{q="Кто такой Повелитель сумрака Келрис?",a="Повелитель сумрака Келрис — предводитель ячейки Сумеречного Молота в Непроглядной Пучине. Убежденный, что пробуждение Аку'май даст ему вечную жизнь и приведет к власти Древних богов, он организует жертвоприношения культа и руководит осквернением храма.",al={"who is kelris","kelris lore","leader of bfd","кто такой келрис","келрис история","главарь бфд"}},{q="Что делают наги и сатиры в руинах?",a="И нагов, и сатиров привлекли к затопленному храму сохранившиеся древние магические силы. Наги во главе с леди Саревесс заключили союз с Сумеречным Молотом: сектанты снабжают ее пленниками и темными знаниями, а ее морские ведьмы взамен обеспечивают магическую защиту от ужасов, таящихся в глубине.",al={"why are naga here","why satyrs in bfd","lady sarevess","почему здесь наги","почему сатиры в бфд","леди саревесс"}},{q="Почему Служители Земли и Серебряный Рассвет интересуются этим местом?",a="Серебряный Рассвет отправил Разведчика Талрида расследовать подозрительные союзы нагов и сектантов, и он обнаружил доказательства их кровавых ритуалов. Служители Земли же поспешили в Ясеневый лес, потому что призыв Древних богов угрожает равновесию стихий и безопасности всего мира.",al={"earthen ring ashenvale","argent dawn bfd","scout thaelrid","служители земли ясеневый лес","серебряный рассвет бфд","разведчик талрид"}},{q="Что происходит, когда Аку'май повержен?",a="Убийство Аку'май лишает Древних богов непосредственной физической опоры в Ясеневом лесу. Оно срывает замысел Повелителя сумрака Келриса выпустить на Калимдор древнего вестника, пожирающего плоть, наносит сильный удар по культу Сумеречного Молота и очищает частицу темной скверны, заразившей оскверненный лунный колодец.",al={"what happens when you kill aku'mai","aku'mai ending","after killing final boss","что будет если убить аку'май","концовка аку'май","после убийства последнего босса"}}},fp="17,390,23.554.0,24.574.0,21.586.1,56.283.0,44.279.0,28.283.0,47.319.0,62.294.0,38.319.1"}
P.entries["zone:blastedlands"] = {n="Выжженные земли",s="Выжженные земли — безжизненная равнина из красной глины и голых скал на юго-восточной оконечности Восточных королевств, разоренная хаотическими энергиями Темного портала. Когда-то эта земля была частью цветущей Черной топи, а теперь на потрескавшейся почве обитают демонические остатки Пылающего Легиона, свирепые огры Молота Ужаса и выносливые пустынные звери. Крепость Стражей Пустоты несет дозор над мертвой пустошью, защищая Азерот от любых ужасов, которые могут выйти из дремлющих врат.",h="Выжженные земли — безжизненная равнина из красной глины и голых скал на юго-восточной оконечности Восточных...",kw={"black morass","blasted lands","dark portal","drazial","dreadmaul","gromsblood","kum'isha","lord kazzak","lynnore","nethergarde keep","razelikh","tainted scar","черная топь","выжженные земли","темный портал","дразиал","молот ужаса","кровь грома","кум'иша","владыка каззак","линора","крепость стражей пустоты","разелих","гниющий шрам"},ang={["class:Mage"]="Маги Крепости Стражей Пустоты воплощают суровое, оборонительное применение магии тайны: они несут дозор против порчи Скверны и пространственных разрывов, оставленных падением Медива.",["class:Warlock"]="Поскольку Гниющий Шрам кишит высокопоставленными демонами, а среди скал обитает Дайо Дряхлый, эта безжизненная земля дает опытным чернокнижникам невиданные возможности подчинять опасных существ Скверны.",["faction:Alliance"]="Крепость Стражей Пустоты — ваш единственный укрепленный оплот в регионе: она охраняет южные рубежи королевства от ужасов, способных угрожать Сумеречному лесу и Штормграду.",["faction:Horde"]="Хотя у Орды здесь нет крепости, руины Темного портала служат мрачным памятником переходу Старой Орды и разрушениям, вызванным демонической порчей.",["profession:Herbalism"]="Сухая красная глина — одна из крайне редких природных сред, где растет Кровь Грома."},sec={{t="Израненная пустошь",b="До Первой войны эта область была продолжением густых болот, известных как Черная топь. Эта пышная трясина была полностью уничтожена, когда чернокнижник Гул'дан и одержимый Медив распахнули Темный портал, чтобы выпустить орочью Орду. Хаотичная энергия Скверны просочилась через пространственный разрыв, высушив всю влагу и обжегши землю до растрескавшейся красной глины. Когда в конце Второй войны Темный портал был разрушен, катастрофические ударные волны выжгли местность еще сильнее и придали местному камню неземной багровый оттенок."},{t="Одинокий дозор Крепости Стражей Пустоты",b="Крепость Стражей Пустоты, возвышающаяся на северных утесах, следит за единственной дорогой, ведущей в долину. Эта каменная цитадель, построенная по приказу верховного мага Кадгара и Кирин-Тора после Второй войны, укомплектована суровыми магами и стойкими солдатами, поклявшимися не допустить новых вторжений демонов и орков. Это негостеприимный и строго дисциплинированный пост: за проступки гарнизон наказывают ссылкой в Тюрьму Штормграда. Защитники терпят неослабевающий натиск огров Молота Ужаса, оставшихся после падения Дренора: те грабят дороги и нападают на ворота крепости по злой указке."},{t="Остатки Легиона",b="В юго-западной части лежит Гниющий Шрам — изрытый кратерами каньон, кишащий самой смертоносной демонической силой на континенте. Оказавшись в изоляции после поражения у горы Хиджал, командир стражей ужаса владыка Каззак собирает под свое знамя блуждающих демонов, стражей ужаса и гончих Скверны. Высоко над красными пустошами его лейтенант, повелитель ужаса Разелих Осквернитель, управляет смертными прислужниками — сектантами Теневой клятвы у Алтаря Бурь — и командует местными ограми Молота Ужаса."},{t="Сила крови",b="Несмотря на запустение, ученые и странники отваживаются на ужасы этих земель ради уникальных открытий. Сразу за северным перевалом Волшебник крови Дразиал и Волшебница крови Линора проводят странные алхимические опыты: извлекают органы из местных скорпидов, василисков и кабанов, чтобы сварить необычайно сильные укрепляющие зелья. Дальше в пустошах одинокий отшельник-дреней по имени Кум'иша ищет рассеянные осколки дренетиста и награждает путников, вернувших эти чужеродные остатки разбитого прошлого Дренора."}},faq={{q="Почему земля красная и бесплодная?",a="Выжженные земли когда-то были частью болотистой Черной топи. Когда открылся Темный портал, сырая демоническая магия высосала из региона жизнь и влагу. Когда позже Темный портал был разрушен, палящий жар и хаотичные энергии разрушения превратили глину в твердую багровую землю.",al={"why is blasted lands red","why is it dead","what happened to the swamp","почему выжженные земли красные","почему здесь все мертво","что случилось с болотом"}},{q="Что такое Темный портал?",a="Темный портал — огромные межпространственные врата, построенные, чтобы соединить Азерот с Дренором, разбитым родным миром орков, ныне известным как Запределье. Хотя портал разрушили, чтобы разорвать мост между мирами, его огромная каменная рама все еще стоит под неусыпным надзором Крепости Стражей Пустоты.",al={"where does dark portal go","is the portal open","what is the gateway","куда ведет темный портал","открыт ли портал","что за врата"}},{q="Кто управляет Крепостью Стражей Пустоты?",a="Крепость Стражей Пустоты — оплот Альянса, которым управляют маги Кирин-Тора и солдаты, верные Штормграду. Крепость построена после Второй войны по указанию верховного мага Кадгара, и ее гарнизон несет строго дисциплинированный, мрачный дозор у Темного портала и отражает нападения огров и демонов.",al={"who runs nethergarde","is nethergarde alliance","nethergarde mages","кто управляет крепостью стражей пустоты","крепость стражей пустоты альянс","маги крепости стражей пустоты"}},{q="Что такое Гниющий Шрам?",a="Гниющий Шрам — кишащий демонами каньон на юге Выжженных земель. Он служит убежищем для оставшихся в Восточных королевствах сил Пылающего Легиона, которые возглавляет могущественный страж ужаса владыка Каззак; там обитают стражи ужаса, демоны Скверны и гончие Скверны.",al={"tainted scar elite area","who is in tainted scar","demon valley blasted lands","гниющий шрам элитные мобы","кто в гниющем шраме","долина демонов выжженные земли"}},{q="Кто эти кровавые эльфы, разбившие лагерь у входа?",a="Волшебник крови Дразиал и Волшебница крови Линора — исследователи, изучающие, как искаженная фауна приспособилась к суровому ландшафту Скверны. В обмен на внутренности, мозги и легкие местных василисков, стервятников, скорпидов и кабанов они варят мощные особые эликсиры, усиливающие характеристики смертных.",al={"blood elf buff potions","drazial and lynnore","boar lung quest","зелья кровавых эльфов","дразиал и линора","задание легкое кабана"}},{q="Who is Kum'isha the Collector?",a="Кум'иша — загадочный мистик-дреней, живущий в центральных пустошах. Он собирает осколки и сферы дренетиста — кристаллические остатки, пришедшие с Дренора, — и отдает запечатанные наборы редкого снаряжения и товаров каждому, кто их ему принесет.",al={"draenei in blasted lands","kumisha","draenethyst quest","дреней в выжженных землях","кумиша","задание дренетист"}},{q="Как добраться до Выжженных земель пешком?",a="Идите через Перевал Мертвого Ветра на восток, в Болото Печали. Оттуда следуйте по главной дороге на юг мимо поселения Орды Каменор, пока не дойдете до узкого горного перевала, который ведет прямо на красную глину Выжженных земель.",al={"getting to blasted lands","how to get there","blasted lands entrance","как добраться до выжженных земель","как туда попасть","вход в выжженные земли"}},{q="Почему в пустыне живут огры?",a="Огры Молота Ужаса прошли через Темный портал во время Второй войны. Вместо того чтобы отступить через разрыв, они укрепились в Форте Молота Ужаса и попали под власть повелителя ужаса Разелиха и культа Теневой клятвы.",al={"dreadmaul ogres lore","why are ogres here","dreadmaul hold","огры молота ужаса история","почему здесь огры","форт молота ужаса"}}},fp="13,464,19.556.0,26.619.0,20.471.0,22.514.0,33.288.0,24.290.0,30.291.0,25.273.0,50.292.0,30.253.0,43.256.0,41.247.0"}
P.entries["zone:burningsteppes"] = {n="Пылающие степи",s="Пылающие степи — выжженная вулканическая пустошь у южного подножия Черной горы. Эта опасная земля образовалась столетия назад в результате катастрофического призыва Рагнароса и содержит главный наземный путь между Штормградом и Каз Моданом. Сегодня здесь кишат орки-изгои из клана Черной горы, огры Огненного Чрева, дворфы из клана Черного Железа и выводки черного драконьего рода.",h="Пылающие степи — выжженная вулканическая пустошь у южного подножия Черной горы.",kw={"anduin lothar","blackrock clan","blackrock mountain","blackrock spire","burning steppes","doomhammer","flame crest","morgan's vigil","ragnaros","thaurissan","андуин лотар","клан черной горы","черная гора","вершина черной горы","пылающие степи","молот рока","пламенеющий стяг","дозор моргана","рагнарос","тауриссан"},ang={["faction:Alliance"]="Пылающие степи — мрачный опасный рубеж, где пал верховный командующий Андуин Лотар; маршал Максвелл в Дозоре Моргана постоянно ищет отважных героев, чтобы противостоять угрозам, подступающим к Красногорью.",["faction:Horde"]="Новая Орда Тралла с глубокой тревогой следит за Пламенеющим Стягом, решив обуздать опасный и нераскаявшийся клан Черной горы, чья воинственность пятнает честь орков.",["profession:Mining"]="Вулканический ландшафт богат редкими минералами, и это один из немногих открытых регионов Азерота, где можно добывать ценные залежи черного железа наряду с жилами богатого тория.",["race:Dwarf"]="Каждый камень в степях свидетельствует о безрассудстве клана Черного Железа во время Войны трех молотов, завершившемся разрушением их столицы и призывом Рагнароса."},sec={{t="Катастрофическое происхождение",b="Давным-давно эти предгорья были просто северными окраинами Красногорья. Во время Войны трех молотов изгнанный клан Черного Железа основал здесь свое королевство и возвел столицу — город Тауриссан. Столкнувшись с полным разгромом от кланов Бронзобород и Громовой Молот, отчаявшийся тан-чародей Тауриссан попытался призвать стихийные силы. Вместо этого он расколол землю и призвал в Азерот Рагнароса Повелителя Огня. Яростный взрыв стер в порошок окрестные горы, разорвал землю реками лавы и породил громадный вулкан — Черную гору, оставив степи навеки выжженными и бесплодными."},{t="Отголоски Второй войны",b="Во время Второй войны Старая Орда сделала Вершину Черной горы главным оплотом своей власти. В кульминации конфликта Великий Альянс Лордерона углубился в Пылающие степи, чтобы осадить гору. Именно у подножия Черной горы вождь Оргрим Молот Рока сразился с лордом Андуином Лотаром и сразил человеческого героя. Смерть Лотара не сломила решимость Альянса, а воодушевила союзные армии разгромить орков, обеспечив победу во Второй войне и оставив после себя долину пепла и ржавой стали."},{t="Логово чудовищ и драконов",b="Хотя Тралл создал Новую Орду в далеком Калимдоре, клан Черной горы, оставшийся в степях, сохраняет кровожадную жестокость Старой Орды. Из Крепости Черной горы эти орки открыто заключают союз с черным драконьим родом и местными ограми Огненного Чрева вместо того, чтобы соблюдать перемирие. Тем временем дворфы Черного Железа и элементали таятся среди огненных руин, а черные драконы и дракониды охотятся на неосторожных путников, пытающихся пересечь степи по тракту между Штормградом и северными королевствами."}},faq={{q="Почему земля выжжена и покрыта лавой?",a="Столетия назад тан-чародей из клана Черного Железа Тауриссан попытался призвать элементаля-слугу, чтобы спасти свой клан от поражения в Войне трех молотов. Его заклинание по ошибке пробило брешь в Элементальный План и призвало Рагнароса Повелителя Огня, разорвав землю, создав огромный вулкан Черной горы и превратив северное Красногорье в выжженную пустошь.",al={"why is it burning","what happened to burning steppes","why is blackrock mountain a volcano","почему горит","что случилось с пылающими степями","почему черная гора вулкан"}},{q="Принадлежат ли здешние орки к Орде Тралла?",a="Нет. Орки Пылающих степей — остатки клана Черной горы, отказавшиеся присоединиться к Новой Орде Тралла. Они не соблюдают перемирие с Альянсом и верны жестоким воинственным традициям Первой и Второй войн, служа Вершине Черной горы и черному драконьему роду.",al={"are these thralls orcs","are blackrock orcs horde","why are orcs hostile here","орки тралла","орки черной горы орда","почему орки здесь враждебны"}},{q="Где погиб Андуин Лотар?",a="Андуина Лотара убил вождь Оргрим Молот Рока у подножия Черной горы в Пылающих степях ближе к концу Второй войны. Смерть Лотара побудила его заместителя Туралиона и силы Альянса яростно контратаковать и сокрушить ряды Орды.",al={"where was lothar killed","lothar death location","orgrim doomhammer and lothar duel","где убили лотара","место смерти лотара","дуэль оргрима и лотара"}},{q="Где Альянс может найти укрытие в степях?",a="Солдаты и путники Альянса располагаются в Дозоре Моргана — укрепленном форпосте в юго-восточных предгорьях зоны. Станцией командует маршал Максвелл, наблюдая за северным перевалом и передвижениями вражеских войск вокруг горы.",al={"alliance base burning steppes","where is alliance flight path","morgans vigil location","база альянса пылающие степи","где пункт полетов альянса","дозор моргана"}},{q="Где Орда базируется в этих землях?",a="Искатели приключений Орды являются в Пламенеющий Стяг — лагерь на возвышенности вдоль северо-восточного хребта. Отсюда эмиссары следят за соперничающим кланом Черной горы и поддерживают воздушное сообщение с Бесплодными землями, Болотом Печали и Тлеющим ущельем.",al={"horde base burning steppes","flame crest","where is horde town","база орды пылающие степи","пламенеющий стяг","где город орды"}},{q="Что такое Руины Тауриссана?",a="Руины Тауриссана — остатки величественного города, построенного кланом Черного Железа после изгнания из Стальгорна. Когда тан Тауриссан призвал Рагнароса, неукротимый стихийный взрыв разрушил его столицу и поработил уцелевших жителей по воле Повелителя огня.",al={"thaurissan ruins","what is the destroyed dwarf city","ruins in middle of map","руины тауриссана","что за разрушенный город дворфов","руины в центре карты"}}},fp="15,384,20.652.0,24.569.0,29.528.0,46.377.0,42.301.0,28.286.0,51.257.0,43.243.0,33.265.0"}
P.entries["zone:darkshore"] = {n="Темные берега",s="Темные берега — холодная окутанная туманом полоса побережья на северо-западе Калимдора, усеянная древними руинами кальдораев и неспокойной живностью. Главный город региона — портовый городок Альянса Аубердин, основные ворота для путников, прибывающих с Тельдрассила и из Восточных королевств. За пределами патрулируемой дороги демонические культы, наступающие наги и расползающаяся порча с возвышенностей угрожают хрупкому равновесию региона.",h="Темные берега — холодная окутанная туманом полоса побережья на северо-западе Калимдора, усеянная древними...",kw={"ameth'aran","auberdine","bashal'aran","blackwood den","cliffspring falls","darkshore","master's glaive","onu","tower of althalaxx","амет'аран","аубердин","башал'аран","берлога в чернолесье","водопад скалистый","темные берега","меч властителя","ону","башня алталакса"},ang={["class:Druid"]="Темные берега — передовая для посвященных Круга Кенария, откликнувшихся на призыв из Лунной поляны: они выявляют отравленные водоемы и готовят очищающие средства для больных лесных существ.",["faction:Alliance"]="Аубердин — главный торговый узел Альянса на севере Калимдора, поддерживающий прямое морское сообщение между Штормградом и Стальгорном и столицей ночных эльфов Дарнассом.",["faction:Horde"]="Темные берега — отдаленный, усиленно патрулируемый оплот Альянса, расположенный прямо к северу от лагерей Орды в Ясеневом лесу; здесь опасное побережье, где рыщут враждебные часовые и опасные культы.",["race:NightElf"]="Для молодых ночных эльфов, покидающих Тельдрассил, Темные берега — первый шаг на материковый Калимдор, где они сталкиваются с болезненными руинами своей древней цивилизации и распространяющейся порчей природы."},sec={{t="Земля тумана и воспоминаний",b="Темные берега лежат в западной тени Горы Хиджал и Оскверненного леса и отличаются сосновыми рощами, морским туманом и скалистыми пляжами, по которым бьют холодные волны. Тысячелетия назад здесь стояли процветающие города-близнецы кальдораев Амет'Аран и Башал'Аран. Разрушенные во время Великого Раскола, их скелетообразные колонны и мраморные арки теперь наполовину затоплены прибоем или заросли корнями; их населяют беспокойные духи высокорожденных, а также мурлоки-падальщики и вторгшиеся наги."},{t="Гавань Аубердин",b="После Третьей войны и посадки Тельдрассила ночные эльфы основали Аубердин как оживленную морскую гавань среди дикой природы. Деревянные причалы принимают регулярные корабли из Деревни Рут'теран и Гавани Менетилов в далекой Болотине, и Аубердин — это связующая нить между землями ночных эльфов и остальным Альянсом. Часовые усердно патрулируют торговый тракт на юг к Ясеневому лесу, хотя их малочисленный гарнизон не справляется с охраной глухих земель за дорогой."},{t="Отравленные воды и шепчущие глубины",b="Несмотря на защиту восточных гор, Темные берега страдают от медленного губительного гниения. Оскверненные стоки из Оскверненного леса отравляют источники вроде Водопада Скалистого, портят грунтовые воды и доводят местных медведей, оленей и фурболгов Берлоги в Чернолесье до яростного безумия. Хуже того, зловещие организации закрепились в тени: культисты Темной Нити и Сумеречного Молота совершают мерзкие ритуалы в Башне Алталакса и собираются у грозного древнего монумента — Меча Властителя."}},faq={{q="Как добраться до Темных берегов?",a="Игроки Альянса могут доплыть на корабле прямо до Аубердина из Деревни Рут'теран у подножия Тельдрассила или из Гавани Менетилов в Болотине. Путешественникам Орды, идущим на север, придется пройти через Ясеневый лес, следуя по главной дороге на северо-восток от Форта Зорам'гар через границу.",al={"getting to darkshore","how to reach auberdine","darkshore boat","как добраться до темных берегов","как попасть в аубердин","корабль в темные берега"}},{q="Что не так с местной живностью и фурболгами?",a="Реки, стекающие с оскверненных возвышенностей Оскверненного леса, такие как Река Скалистая, несут демоническую скверну прямо в грунтовые воды Темных берегов. Питье из этих гнилых потоков сделало местные племена фурболгов дикими и заразило оленей и хищников болезнью и агрессией.",al={"why are animals sick","furbolg corruption","darkshore taint","почему животные больны","порча фурболгов","скверна темных берегов"}},{q="Что случилось с Амет'Араном и Башал'Араном?",a="Это были процветающие города-близнецы кальдораев, разрушенные десять тысяч лет назад во время Великого Раскола. Их правитель Атрикус Нарассин заявил, что спасет свой народ от катаклизма, но вместо этого заточил их души в самоцветы, чтобы сохранить как вечные источники силы для себя, оставив руины полными плачущих призраков.",al={"ameth'aran history","bashal'aran lore","ruins in darkshore","история амет'арана","башал'аран предания","руины на темных берегах"}},{q="Что такое Меч Властителя?",a="Меч Властителя, расположенный на юге Темных берегов, — это огромный окаменевший череп, пронзенный громадным каменным оружием. Это древняя реликвия, связанная с изначальными Древними богами и их слугами; сейчас она привлекает опасных культистов Сумеречного Молота.",al={"what is the masters glaive","giant skull darkshore","masters glaive monster","что такое меч властителя","гигантский череп темные берега","чудовище меч властителя"}},{q="Кто такое гигантское дерево в Роще Древних?",a="Это Ону, почтенное Древо Мудрости. Отдыхая в своей тихой роще к югу от Аубердина, он размышляет о тревожном вторжении культа Сумеречного Молота и помогает путникам расследовать беспорядки в лесу.",al={"ancient of lore darkshore","who is onu","tree person darkshore","древо мудрости темные берега","кто такой ону","говорящее дерево темные берега"}},{q="Кто живет в Башне Алталакса?",a="Башню занимает Темная Нить — злобный культ, практикующий темное колдовство и призывающий демонических существ. Их шайка активно устраивает засады на неосторожных путников на севере прибрежных лесов.",al={"tower of althalaxx","darkshore tower cultists","althalaxx cult","башня алталакса","культисты башни темные берега","культ алталакса"}}},fp="9,443,25.491.0,22.499.0,37.549.0,26.293.0,51.298.0,44.329.1,28.273.0,51.244.0,36.208.0"}
P.entries["zone:darnassus"] = {n="Дарнасс",s="Дарнасс — безмятежная столица ночных эльфов под открытым небом, построенная среди ветвей недавно посаженного Мирового Древа, Тельдрассила. Городом правит верховная жрица Тиранда Шелест Ветра вместе с друидами Анклава Кенария; он служит тихим убежищем для древнего народа, привыкающего к смертности. Раскинувшись на обширных террасах вокруг кристального озера, он является сердцем общества ночных эльфов и их мостом к Альянсу.",h="Дарнасс — безмятежная столица ночных эльфов под открытым небом, построенная среди ветвей недавно посаженного...",kw={"cenarion enclave","darnassus","fandral","night elf capital","rut'theran","staghelm","teldrassil","temple of the moon","tyrande","whisperwind","анклав кенария","дарнасс","фэндрал","столица ночных эльфов","рут'теран","олений шлем","тельдрассил","храм луны","тиранда","шелест ветра"},ang={["class:Druid"]="Анклав Кенария — центр обучения друидов в Тельдрассиле, которым руководит требовательный и непреклонный верховный друид Фэндрал Олений Шлем.",["class:Priest"]="Величественный Храм Луны — святой центр Сестер Элуны, которым руководит сама верховная жрица Тиранда Шелест Ветра.",["faction:Alliance"]="Дарнасс служит самым западным оплотом Альянса, обеспечивая важное морское и стратегическое укрытие на континенте Калимдор.",["race:NightElf"]="Как сердце вашей суверенной цивилизации, Дарнасс — ваше убежище на пути через небывалые испытания смертного существования."},sec={{t="Корона высоко в ветвях",b="В отличие от плотной каменной кладки Штормграда или высеченных в камне туннелей Стальгорна, Дарнасс просторен, тих и тесно связан с дикой природой. Изящные деревянные постройки и извилистые тропы столицы, раскинувшейся в верхней кроне Тельдрассила у берегов северного Калимдора, окружают тихое центральное озеро. Изящные мосты соединяют террасы торговцев, ремесленников, часовых и друидов, создавая атмосферу, в которой гражданское управление сочетается с глубоким почтением к природе."},{t="Убежище смертного народа",b="Дарнасс удивительно молод для цивилизации возрастом в тысячи лет. После Третьей войны и жертвы Нордрассила на горе Хиджал кальдораи внезапно столкнулись с опасностями старения и болезней. Стремясь вернуть утраченную жизненную силу, верховный друид Фэндрал Олений Шлем и его последователи посадили Тельдрассил вопреки предостережениям пропавшего верховного друида Малфуриона Ярость Бури. Дарнасс основали среди его огромных ветвей как убежище и памятник их выживанию, хотя тени недуга уже шепчутся среди его корней."},{t="Разделенный очаг",b="Хотя на вид Дарнасс спокоен, он держится на хрупком политическом разделении. С высоких колоннад Храма Луны верховная жрица Тиранда Шелест Ветра направляет духовную жизнь и военную оборону своего народа через бдительных Часовых. По ту сторону водных путей, в Анклаве Кенария, верховный друид Фэндрал Олений Шлем командует друидами, пока Малфуриона нет. Хотя оба лидера демонстрируют единство новым союзникам из Альянса, в городе не утихает трение между жрицами и кругом друидов."}},faq={{q="Как добраться до Дарнасса с материка?",a="Поскольку Тельдрассил — остров у северо-западного побережья Калимдора, путникам нужно добраться до Деревни Рут'теран у подножия дерева на лодке или по воздуху. От причалов деревни светящийся магический портал переносит путников прямо в ветви города.",al={"how to get to darnassus","travel to darnassus","darnassus entrance","как попасть в дарнасс","путь в дарнасс","вход в дарнасс"}},{q="Кто правит Дарнассом?",a="Верховная жрица Тиранда Шелест Ветра правит Дарнассом и кальдораи из величественного Храма Луны. Верховный друид Фэндрал Олений Шлем возглавляет друидов Круга Кенария из Анклава Кенария и фактически выступает друидической властью, пока Малфурион Ярость Бури остается потерянным в Изумрудном Сне.",al={"darnassus leader","who is in charge","ruler of darnassus","правитель дарнасса","кто главный","лидер дарнасса"}},{q="Почему город был основан так недавно?",a="Дарнасс был основан вскоре после Третьей войны. Когда ночные эльфы пожертвовали бессмертием, чтобы победить Архимонда на горе Хиджал, Фэндрал Олений Шлем настоял на выращивании нового Мирового Древа, Тельдрассила, чтобы вернуть прежнее состояние. Дарнасс был создан в его ветвях как новое убежище.",al={"why is darnassus new","when was darnassus built","darnassus history","почему дарнасс новый","когда построен дарнасс","история дарнасса"}},{q="Где верховный друид Малфурион Ярость Бури?",a="Малфурион Ярость Бури пропал, его дух заточен в Изумрудном Сне. В его отсутствие верховный друид Фэндрал Олений Шлем управляет друидами Тельдрассила, а Тиранда Шелест Ветра неустанно ищет способ пробудить и вернуть своего возлюбленного.",al={"where is malfurion","is malfurion in darnassus","malfurion location","где малфурион","малфурион в дарнассе","местонахождение малфуриона"}},{q="Где находятся учителя профессий и магазины?",a="Город разделен на специализированные террасы. На Террасе Ремесленников находятся сбор ресурсов и портняжное дело, а также таверна, на Террасе Торговцев — торговые лавки и аукционный дом. Кузнечное дело и боевые учителя находятся на Террасе Воинов, а городской банк расположен на центральном острове Храмовых садов.",al={"darnassus professions","auction house darnassus","darnassus bank","профессии дарнасс","аукцион дарнасс","банк дарнасс"}},{q="Почему ночные эльфы вступили в Альянс?",a="После разрушений Третьей войны ночные эльфы столкнулись с растущим давлением Орды, особенно с вылазками орков-дровосеков в Ясеневый лес. Осознав необходимость союзников против этих вторжений и других растущих угроз по всему Калимдору, Дарнасс установил дипломатические связи и вступил в Великий Альянс.",al={"why are night elves alliance","night elf alliance ties","alliance darnassus","почему ночные эльфы в альянсе","союз ночных эльфов","альянс дарнасс"}}},fp="9,450,28.496.0,25.528.0,16.558.0,49.254.0,20.298.0,37.290.0,39.243.0,52.343.0,42.314.0"}
P.entries["zone:deadmines"] = {n="Мертвые копи",s="Глубоко под пыльным фермерским городком Луноречье лежат Мертвые копи — огромный подземный комплекс, когда-то дававший треть золотых запасов Штормграда. Эти запутанные туннели, брошенные во время Первой войны и долго считавшиеся проклятыми, тайно захвачены Братством Справедливости как главная опорная база. Здесь Эдвин ван Клиф и его насильно завербованные гоблины-инженеры трудятся вдали от глаз королевства, создавая орудие мести против него.",h="Глубоко под пыльным фермерским городком Луноречье лежат Мертвые копи — огромный подземный комплекс, когда-то...",kw={"cookie","deadmines","defias","edwin vancleef","ironclad cove","juggernaught","moonbrook","mr. smite","vancleef","westfall","пирожок","мертвые копи","братство справедливости","эдвин ван клиф","потайная бухта","джаггернаут","луноречье","мистер каюк","ван клиф","западный край"},ang={["class:Paladin"]="Эти оскверненные штольни — испытание доблести и веры, повторяющее исторические испытания сэра Андуина Лотара и погибших шахтеров, чьи неупокоенные мертвецы до сих пор бродят по внешним туннелям.",["faction:Alliance"]="Мертвые копи — самая серьезная внутренняя угроза королевству Штормград; победа над ван Клифом — решающий успех, возвращающий надежду осажденным фермерам Западного Края.",["profession:Engineering"]="Гоблинская литейная и механическая мастерская Снида дают взглянуть изнутри на новейшие паровые крошшеры, големов на дистанционном управлении и особые боеприпасы.",["profession:Mining"]="Когда-то дававшие треть богатств столицы, каменные туннели по-прежнему богаты жилами меди, олова и драгоценного серебра."},sec={{t="Наследие золота и разорения",b="До Первой войны Мертвые копи считались крупнейшим центром добычи золота в землях людей и питали процветание Штормграда. Когда Орочья Орда прошла по королевству и разрушила столицу, копи в спешке бросили во тьме. В те беспокойные годы в этих глубинах бывали легендарные личности: Сэр Андуин Лотар провел двадцать месяцев в плену у подземных огров, добывая священный Фолиант Божественности, а мятежная дочь вождя Чернорука Гризельда бежала в нижние проходы вместе с огром Туроком, и оба погибли. Считавшиеся проклятыми и населенные лишь бредущей нежитью и подземными тварями, глубины десятилетиями оставались нетронутыми."},{t="Святилище Братства",b="Когда Гильдию каменщиков выгнали из Штормграда, не заплатив за восстановление города, Эдвин ван Клиф объединил лишенных прав мастеров в Братство Справедливости. Ища надежную штаб-квартиру, недосягаемую для Народного ополчения Гриана Камнегрива, воры устроили главный оплот в заброшенных туннелях. Они изгнали законную Лигу шахтеров, оставив обреченных рабочих Штейгера Чертополоха погибнуть и восстать нежитью-вурдалаками, и превратили штольни в промышленный военный лагерь. Под охраной неповоротливых огров, опытных разбойников и механических созданий нижние шахты снова гремят кирками, огнем и незаконным производством."},{t="Тайна Потайной бухты",b="За знойной Гоблинской литейной и заваленной бревнами Мачтовой лежит Потайная бухта — обширный подземный грот, выдолбленный под Холмами Разбойничьих Кинжалов. В этой скрытой гавани ван Клиф нанял гоблинов-корабелов и изобретателей для постройки колоссального броненосного дредноута. Этим военным кораблем командуют капитан Зеленямс и первый помощник Мистер Каюк. Он рассчитан на проход через подводные морские врата к океану, где Братство Справедливости намерено грабить морскую торговлю, обогащающую Штормград."}},faq={{q="Где находится вход в Мертвые копи?",a="Вход скрыт в заброшенном амбаре в разрушенном городке Луноречье на юго-западе Западного Края. Извилистые туннели ведут через внешний комплекс землекопов Братства Справедливости и мертвых шахтеров к запертому входу в подземелье.",al={"deadmines entrance","how to get to deadmines","where is deadmines","вход в мертвые копи","как попасть в мертвые копи","где мертвые копи"}},{q="Почему все называют Мертвые копи «VC»?",a="Искатели приключений часто называют подземелье «VC» по имени его хозяина, Эдвина ван Клифа. Это сокращение помогает не путать Мертвые копи с Забытым Городом, древним эльфийским комплексом в Фераласе, у которого те же инициалы «DM».",al={"why vc","vc meaning","why call it vc","почему vc","что значит vc","почему называют vc"}},{q="Кто такой Эдвин ван Клиф?",a="Эдвин ван Клиф был талантливым главой гильдии каменщиков, руководившим величественным восстановлением Штормграда после Первой войны. Когда Дом знати отказался платить долги, ван Клиф создал Братство Справедливости, чтобы добиться возмещения мятежом и открытым разбоем.",al={"vancleef backstory","who is the final boss","defias leader","история ван клифа","кто финальный босс","лидер братства справедливости"}},{q="Что строят в Потайной бухте?",a="Братство Справедливости наняло гоблинов-инженеров для сборки огромного броненосного джаггернаута. Вооруженный тяжелыми орудиями и прочным деревом, корабль должен выйти через морские врата бухты и грабить торговлю, питающую столицу.",al={"what are they building","deadmines ship","juggernaught","что они строят","корабль мертвых копей","джаггернаут"}},{q="Что случилось с рабочими Лиги шахтеров снаружи подземелья?",a="Штейгера Чертополоха и его бригаду отправили законно вновь открыть копи для королевства. Когда Братство Справедливости захватило выработки, страшный обвал туннеля запер шахтеров во тьме, где они умерли от голода и в конце концов восстали бездумной неупокоенной нежитью.",al={"thistlenettle fate","why are there undead miners","collecting memories lore","судьба чертополоха","почему там мертвые шахтеры","собирая воспоминания"}},{q="Что значит победа над мурлоком Пирожком для корабля Братства Справедливости?",a="Пирожок — странный корабельный повар на дредноуте ван Клифа. Победа над ван Клифом отсекает голову мятежа, а убийство Пирожка очищает камбуз от оставшейся команды, полностью лишая Братство присутствия в Потайной бухте, прежде чем искатели приключений выберутся через прибрежный проход.",al={"cookie the murloc","why is cookie a boss","cookie deadmines","мурлок пирожок","почему пирожок босс","пирожок мертвые копи"}},{q="Куда ведет выходной туннель при выходе из подземелья?",a="Если пройти по природному туннелю за дредноутом, искатели приключений выйдут на прибрежных утесах Холмов Разбойничьих Кинжалов, откуда виден океан и Маяк в Западном Крае.",al={"deadmines exit","where does the exit go","выход из мертвых копей","куда ведет выход"}}},fp="13,480,25.717.0,26.666.0,27.519.1,47.241.0,42.224.0,22.296.0,37.235.0,65.255.0,63.314.0,57.189.0"}
P.entries["zone:desolace"] = {n="Пустоши",s="Пустоши — мрачная, продуваемая ветрами пустыня на западном побережье Калимдора с потрескавшейся серой землей, вечно штормовым небом и костями павших зверей. Это родина свирепой расы кентавров и спорная пустошь, изуродованная древними руинами высокорожденных, наступающими демоническими культами и жестокими племенными войнами. И Орда, и Альянс удерживают среди пыли шаткие позиции, стремясь расширить влияние и сдержать распространяющуюся порчу.",h="Пустоши — мрачная, продуваемая ветрами пустыня на западном побережье Калимдора с потрескавшейся серой землей...",kw={"burning blade","centaur","desolace","gelkis","magram","maraudon","nijel's point","shadowprey village","theradras","zaetar","пылающий клинок","кентавр","пустоши","гелкис","маграм","мародон","высота найджела","деревня ночных охотников","терадрас","заетар"},ang={["class:Druid"]="Друиды Круга Кенария считают Пустоши ужасным шрамом на природном порядке, где Заетар встретил трагическую смерть, а стихийный распад душит землю.",["class:Warlock"]="Засушливые равнины и демонические места вроде Поля Маннорок привлекают темных практиков, ищущих тайны коней Скверны — величественных диких лошадей, превращенных запретными обрядами Совета Теней в огнедышащих чудовищ.",["faction:Alliance"]="Действуя с Высоты Найджела, Альянс следит и за вероломными племенами кентавров, и за подозрительным распространением поселений Орды вроде Деревни Ночных Охотников, и за демоническими культами.",["faction:Horde"]="Орда стремится закрепить за собой побережье у Деревни Ночных Охотников и защитить стада кодо на Заставе Скитающихся Духов, непримиримо сражаясь с Пылающим Клинком и доказывая, что нынешняя Орда свободна от демонического влияния.",["race:Tauren"]="Для тауренов Пустоши — священная и трагическая земля. Когда-то известная как Машан'ше, она была кочевым домом ваших предков, пока пробуждение Терадрас и бедствие кентавров не привели ваш народ на грань вымирания."},sec={{t="Проклятая и разрушенная земля",b="Пустоши не всегда были бесплодной равниной из пепла и пожелтевших озер. Более тысячи лет назад здесь лежал Машан'ше — пышный луг, о котором заботились таурены-шаманы. Этот рай рухнул, когда из-под земли пробудилась элементаль земли принцесса Терадрас, высасывая окружающую жизненную силу, чтобы восстановить свое тело. Катастрофа призвала Заетара, сына Кенария, но вместо того чтобы усмирить ее, он взял принцессу в жены. От их противоестественного союза произошел первый кентавр. В стыде и кровожадной ярости новорожденная раса убила своего отца, захватила зеленые равнины и изгнала тауренов, оставив изуродованную пустошь, известную сегодня."},{t="Воюющие копыта",b="Внутренние земли Пустошей гремят топотом тысяч копыт: четыре раздробленных племени кентавров ведут нескончаемую войну против всех чужаков и друг с другом. Колкар кочуют по восточным утесам, Маграм держат грубые юрты у солоноватых провалов, Гелкис живут за веревочными мостами в глубоких южных ущельях, а фанатичные Мародин охраняют подступы к самому Мародону. Путники, пересекающие пустоши, часто оказываются втянуты в эту древнюю кровную вражду и вынуждены истреблять одно племя, чтобы получить безопасный проход и зыбкие переговоры с другим."},{t="Культы и тенистые берега",b="Помимо воюющих кентавров, на границах назревают более мрачные опасности. Культ Пылающего Клинка свободно действует из Крепости Громового Топора и Лощины Тьмы, призывая демонов и сатиров, грозящих утопить край в огне Скверны. На штормовом побережье наги выползают на берега Этель-Ретора, а тролли Черного Копья бьют рыбу копьями со свайных платформ Деревни Ночных Охотников. Высоко в северных скалах Альянс наблюдает с Высоты Найджела, с подозрением относясь к расширению Орды и опасаясь демонической порчи, расползающейся с Поля Маннорок."}},faq={{q="Почему Пустоши — такая мертвая пустошь?",a="Много веков назад эта земля была плодородным лугом под названием Машан'ше. Таурены-шаманы случайно разбудили дремавшую элементаль земли принцессу Терадрас, которая поглотила жизненную силу края, чтобы восстановить свое физическое тело. Рождение кентавров и их яростное расширение вскоре после этого уничтожили уцелевшие растения, оставив лишь серую пыль и пепел.",al={"why is desolace dead","what happened to mashan'she","desolace lore origin","почему пустоши мертвы","что случилось с машан'ше","история происхождения пустошей"}},{q="Откуда взялись кентавры?",a="Кентавры — потомки Заетара, сына полубога Кенария, и элементаля принцессы Терадрас. Испытав отвращение и ярость из-за своего уродливого облика, первые ханы убили отца сразу после рождения и расплодились по равнинам в исступлении жестокости.",al={"centaur origin","who made the centaur","zaetar theradras","происхождение кентавров","кто создал кентавров","заетар терадрас"}},{q="Могу ли я заключить союз с племенами кентавров?",a="Да. Искатели приключений могут заработать репутацию у племени Гелкис или Маграм, убивая членов вражеского клана. Достаточная репутация у одного открывает доступ в его деревню, племенные задания и мир на его земле, но делает противоположное племя навсегда враждебным.",al={"centaur reputation","gelkis or magram","how to befriend centaur","репутация кентавров","гелкис или маграм","как подружиться с кентаврами"}},{q="Что такое Мародон?",a="Мародон — священное родовое место погребения кентавров, скрытое в глубине извилистых западных утесов Пустошей. Это и гробница Заетара, и подземное логово принцессы Терадрас, которая продолжает направлять темную стихийную порчу через его пещерные залы.",al={"where is maraudon","maraudon dungeon","what lies under desolace","где мародон","подземелье мародон","что под пустошами"}},{q="Кто тот странник с медведем, бродящий по Пустошам?",a="Это Рексар, Герой Орды, в сопровождении своего верного спутника-медведя Миши. Странник из народа мок'нати патрулирует пыльные тракты Пустошей и Когтистых гор, внимательно следит за дикими землями и помогает тем, кто выполняет важные поручения Орды.",al={"rexxar desolace","beastmaster in desolace","who is the orc with a bear","рексар пустоши","повелитель зверей в пустошах","кто тот орк с медведем"}},{q="Почему Альянс и Орда сражаются здесь с Пылающим Клинком?",a="Культ Пылающего Клинка захватил такие твердыни, как Крепость Громового Топора, чтобы призывать демонов и подчинять коней Скверны. Призываемые им демоны и сатиры грозят заражением всего края, и эту опасность должны отразить и Орда, и Альянс.",al={"burning blade desolace","thunder axe fortress cultists","why are demons here","пылающий клинок пустоши","крепость громового топора культисты","почему здесь демоны"}}},fp="8,474,24.655.0,14.569.0,25.568.0,38.351.0,32.279.0,40.290.0,17.293.0,49.268.0,63.244.0"}
P.entries["zone:dunmorogh"] = {n="Дун Морог",s="Дун Морог — заснеженное горное нагорье в самом сердце Каз Модана. Это исконная земля и общая родина дворфов Стальгорна и изгнанных гномов Гномрегана. Несмотря на неприступные вершины и укрепленные перевалы, заснеженный край сталкивается с растущими внутренними угрозами: троггами, троллями Мерзлогривами и облученными лепрогномами.",h="Дун Морог — заснеженное горное нагорье в самом сердце Каз Модана.",kw={"anvilmar","brewnall village","coldridge valley","deeprun tram","dun morogh","frostmane","gnomeregan","gol'bolar","ironforge","kharanos","magni bronzebeard","troggs","старая наковальня","поселок пивоваров","холодная долина","подземный поезд","дун морог","мерзлогривы","гномреган","гол'болар","стальгорн","каранос","магни бронзобород","трогги"},ang={["profession:Cooking"]="Местные охотники и трактирщики в Караносе и Поселке Пивоваров охотно используют мясо кабана, медвежьи ребра и дворфийский стаут, чтобы защититься от пронизывающего горного мороза.",["profession:Mining"]="Горные утесы Дун Морога богаты поверхностными залежами медной жилы, особенно возле карьера Гол'Болар и на заснеженных скалах.",["race:Dwarf"]="Это ваша родина предков. От очагов Старой Наковальни до пылающего сердца Великой кузни в Стальгорне — защита этих вершин от троллей и троггов ваш долг перед королем Магни.",["race:Gnome"]="Ваш потерянный дом, Гномреган, лежит облученным в западной долине. Дун Морог служит вашей базой в изгнании рядом с кузенами-дворфами, пока вы сражаетесь с троггами и безумными лепрогномами."},sec={{t="Горная твердыня",b="Дун Морог занимает самые высокие вершины Восточных королевств — это альпийское нагорье, окруженное зубчатыми пиками, которые защищают его от Тлеющего ущелья на юге и Болотины на севере. Эти снежные горы питают реки, текущие через Каз Модан, и дают почти неисчерпаемые жилы меди и железа. Доступ сильно ограничен горными туннелями вроде Северных врат и Южных врат, за которыми пристально следят дворфы-горцы. В сердце региона находится Стальгорн, древнее подземное чудо и столица владений короля Магни Бронзоборода, напрямую связанная со Штормградом чудом техники — Подземным поездом."},{t="Разделенное убежище",b="Много веков назад дворфы изгнали коренных ледяных троллей Мерзлогривов в горные ущелья и освободили место для себя рядом со своими гениальными союзниками-гномами. Обе расы процветали в соседних горных залах, пока недавно, во время Третьей войны, в Гномрегане не случилась катастрофа. Ужасное вторжение троггов и губительный радиоактивный выброс разрушили это технологическое чудо, превратив его защитников в безмозглых лепрогномов и вынудив главного механика Гелбина Меггакрута и его уцелевший народ уйти в изгнание. Теперь гномы живут в Стальгорне на правах гостей, а лепрогномы и уцелевшие трогги выплескиваются в Долину Промозглого Ветра."},{t="Беда в сугробах",b="Жизнь в сугробах далеко не спокойна. Племя Мерзлогривов осмелело и устроило хорошо вооруженные лагеря от Мерцающего хребта до Холодной долины. Тем временем примитивные трогги выбрались из древних подземных трещин в Карьер Гол'Болар, угрожая добыче руды в крае. Из-за бродящих вендиго, диких кабанов, проникающих агентов дворфов Черного Железа и ядовитых осадков от руин Гномрегана дворфы-горцы с трудом поддерживают порядок от Караноса до пограничных врат."}},faq={{q="Какие расы начинают игру в Дун Мороге?",a="И дворфы, и гномы начинают свой путь здесь, в Холодной долине — укрытой котловине на юго-западе Дун Морога, а затем через Туннель Холодной долины отправляются в Каранос и дальше по всей зоне.",al={"dun morogh starting race","who starts here","dwarf start zone","gnome start zone","стартовая раса дун морог","кто начинает здесь","стартовая зона дворфов","стартовая зона гномов"}},{q="Что случилось с Гномреганом?",a="Во время Третьей войны подземная раса троггов заполонила Гномреган. Пытаясь уничтожить захватчиков, главный механик Гелбин Меггакрут выпустил радиоактивный газ на нижние уровни. План катастрофически провалился: погибли тысячи, а многие гномы под действием радиации превратились в безумных лепрогномов, и здоровым выжившим пришлось бежать в Стальгорн.",al={"why is gnomeregan ruined","what happened to the gnomes","why are leper gnomes here","почему гномреган разрушен","что случилось с гномами","почему здесь лепрогномы"}},{q="Как пешком выйти из Дун Морога?",a="Дун Морог окружен высокими горными хребтами. Чтобы пешком попасть на восток, в Лок Модан, идите по дорогам к Северным вратам или Южным вратам в северо-восточных горах. Также можно напрямую добраться до Штормграда на Подземном поезде в Стальгорне.",al={"exit dun morogh","dun morogh to loch modan","leave dun morogh","выход из дун морога","дун морог в лок модан","покинуть дун морог"}},{q="Где находится распорядитель полетов в Дун Мороге?",a="Единственный действующий распорядитель полетов Альянса в зоне находится в Великой кузне Стальгорна. Он связывает путников с местами по всему Каз Модану, Штормграду и северным аванпостам Альянса.",al={"dun morogh flight master","dun morogh flight path","where to fly dun morogh","распорядитель полетов дун морог","пути полета дун морог","куда лететь дун морог"}},{q="Кто такие тролли Мерзлогривы?",a="Мерзлогривы — племя ледяных троллей, правившее Дун Морогом задолго до того, как дворфы вышли из Ульдамана. Хотя их победили и загнали в горные расселины много поколений назад, они остаются заклятыми врагами Стальгорна и регулярно грабят фермы и дороги дворфов из таких убежищ, как Форт Мерзлогривов.",al={"why are there trolls in dun morogh","dun morogh trolls","frostmane tribe","почему в дун мороге тролли","тролли дун морога","племя мерзлогривов"}},{q="Что такое Каранос?",a="Каранос — главное поселение дворфов в центральной части Дун Морога. Здесь находятся Таверна «Громоварка», учителя и торговцы; он служит главной базой для юных искателей приключений и горцев, решающих проблемы с троллями и дикими зверями.",al={"town in dun morogh","kharanos hub","what is the main town","город в дун мороге","каранос","какой главный город"}}},fp="10,374,21.621.0,16.623.0,21.550.0,31.194.0,28.349.0,36.270.0,41.202.0,29.283.0,17.249.0"}
P.entries["zone:durotar"] = {n="Дуротар",s="Дуротар — засушливая родина из красных скал, основанная вождем Траллом после Третьей войны и названная в честь его отца, Дуротана. Ограниченный рекой Строптивой и Великим морем, он служит сердцем Новой Орды и испытательной площадкой для молодых орков и троллей Черного Копья. В его суровых каньонах лежат укрепленные поселения вроде Колючего Холма, огромный город воинов Оргриммар и укрепившиеся враждебные силы — от племен свинобразов до отрезанных войск Альянса.",h="Дуротар — засушливая родина из красных скал, основанная вождем Траллом после Третьей войны и названная в...",kw={"durotan","durotar","echo isles","orgrimmar","razor hill","sen'jin village","skull rock","southfury river","thrall","tiragarde keep","valley of trials","zalazane","дуротан","дуротар","острова эха","оргриммар","колючий холм","деревня сен'джин","скала черепа","река строптивая","тралл","крепость тирагард","долина испытаний","залазан"},ang={["class:Shaman"]="Засушливая местность пропитана необузданными духами стихий. Молодые шаманы посещают священные места, такие как Священный Камень и Святилище Дремлющего Пламени, чтобы настроиться на землю и огонь.",["class:Warlock"]="Тралл строго пресекает темную магию, и гроты Совета Теней прячутся в таких местах, как Скала Черепа, и под городом, в извилистых пещерах Огненной пропасти.",["faction:Alliance"]="Дуротар — бьющееся сердце военной мощи Орды. Любого путника из Альянса, забредшего в его выжженные солнцем каньоны, будут выслеживать и атаковать на месте как бдительные патрули, так и местные звери.",["race:Orc"]="Дуротар — новая земля обетованная вашего народа, завоеванная потом и кровью после лет демонического оцепенения и заточения. Доказать свою доблесть в Долине Испытаний — первый обряд посвящения для каждого нового защитника Орды.",["race:Troll"]="Спасшись от морской ведьмы на Великом море, тролли Черного Копья нашли убежище рядом с Траллом в Дуротаре, но предатель Залазан захватил Острова Эха изнутри. Вернуть острова и защитить Деревню Сен'джин — для вас личное дело."},sec={{t="Суровый новый дом",b="Когда Тралл переправил свой народ через Великое море в Калимдор, он намеренно искал неосвоенные земли, где орки смогут жить честным трудом и стойкостью, а не завоеваниями. Растрескавшаяся красная земля, выжженные овраги и высокие красные скалы напоминают оркам Дренор до его разрушения. Хотя климат суров, плодородной земли мало, а воды скудно, Орда приняла естественную защиту и суровое величие этой земли. Граничащий на западе через Реку Строптивую с открытыми Степями, а на севере — с разоренными землями Азшары, Дуротар служит живым доказательством того, что орки сами выковали свою судьбу."},{t="Враги на границе",b="Хотя Дуротар прочно находится под властью Орды, борьба за него еще не окончена. Иглогривые свинобразы, изгнанные при основании государства, неустанно грабят поселения и фермы с западных скал. Южнее остатки флота Кул Тираса верховного адмирала Даэлина Праудмура по-прежнему удерживают разрушающийся гарнизон Крепости Тирагард под началом лейтенанта Бенедикта и отказываются сдаваться. Хуже того, демонические остатки Грота Пылающего Клинка скрываются в потайных лощинах и глубоких морских пещерах и исподволь стараются вновь развратить молодых орков обещаниями силы Скверны."},{t="Испытания Черного Копья",b="На южном побережье лежит Деревня Сен'джин — опорный пункт изгнанных троллей Черного Копья. Под началом Мастера Гадрина тролли Черного Копья были вынуждены покинуть свой дом на соседних Островах Эха, когда колдун Залазан сошел с ума и темным вуду поработил своих сородичей. Не в силах вернуть острова самостоятельно, тролли Черного Копья полагаются на недавно обученных воинов-орков и троллей, выходящих из Долины Испытаний, чтобы сломить власть Залазана и защитить побережье."}},faq={{q="Почему Тралл поселил Орду в такой бесплодной пустыне?",a="Тралл намеренно выбрал эту суровую землю. Красная почва и изрезанные плато напоминали оркам их родной мир, Дренор, а тяжелые условия служили искуплением и закалкой дисциплины. Тралл считал, что его народу нужно заслужить выживание честными трудностями, а не захватом плодородных земель, чтобы орки не скатились обратно в кровожадное самодовольство.",al={"why settle here","why durotar","why durotar barren","почему поселились здесь","почему дуротар","почему дуротар бесплодный"}},{q="В честь кого назван Дуротар?",a="Земля названа в честь Дуротана, покойного отца Тралла и бывшего вождя клана Северного Волка. Дуротан выступал против демонической порчи орочьих кланов и был убит по приказу чернокнижника Гул'дана.",al={"who is durotar named for","durotan","origin of durotar name","в честь кого назван дуротар","дуротан","происхождение названия дуротар"}},{q="Почему внутри Крепости Тирагард находятся человеческие солдаты?",a="Солдаты в Крепости Тирагард — уцелевшие култирасские морпехи под командованием лейтенанта Бенедикта, оставшиеся от флота вторжения верховного адмирала Даэлина Праудмура. Даже после гибели Праудмура эти войска отказались сдаваться или отступать и удерживают укрепленный враждебный форпост прямо на южном побережье Дуротара.",al={"why humans in durotar","tiragarde keep humans","proudmoore troops durotar","почему люди в дуротаре","люди крепость тирагард","войска праудмура дуротар"}},{q="Что за конфликт на Островах Эха?",a="Тролли Черного Копья изначально обосновались в Калимдоре на Островах Эха. Однако могущественный колдун по имени Залазан поддался безумию и обратил свою темную магию против сородичей, поработив их разум. Выжившие бежали на материк и основали Деревню Сен'джин, откуда совершают вылазки, чтобы сломить его власть.",al={"what happened to echo isles","why sen'jin village","zalazane lore","что случилось с островами эха","почему деревня сен'джин","история залазана"}},{q="Что Пылающий Клинок делает в Дуротаре?",a="Пылающий Клинок — подрывной демонический культ, верный Совету Теней и Пылающему Легиону. Его приспешники скрываются в уединенных местах, таких как Скала Черепа и Грот Пылающего Клинка, и пытаются подорвать власть Тралла и вновь склонить легковерных орков к демонической кабале.",al={"burning blade durotar","skull rock cultists","demons in durotar","пылающий клинок дуротар","скала черепа культисты","демоны в дуротаре"}},{q="Что соединяет Дуротар с другими землями?",a="A bridge over the Southfury River leads west into the Barrens. Outside Orgrimmar, a zeppelin tower provides transcontinental air travel directly to Tirisfal Glades and Grom'gol Base Camp in Stranglethorn Vale.",al={"how to leave durotar","durotar travel","durotar exits","как выйти из дуротара","путешествие по дуротару","выходы из дуротара"}}},fp="7,482,16.679.0,23.557.0,27.459.0,56.408.0,28.226.0,51.311.0,39.335.0,43.280.0,39.209.0"}
P.entries["zone:duskwood"] = {n="Сумеречный лес",s="Некогда залитая солнцем равнина на юге Элвинна, известная как Светлая роща, Сумеречный лес теперь — проклятые лесные земли, погруженные в неестественный вечный мрак. Брошенные властями Штормграда, осажденные жители поселения Темнолесье цепляются за жизнь под бдительной защитой местного ополчения — Ночного Дозора. По темным рощам и призрачным курганам бродят плотоядные вурдалаки, гигантские ядовитые пауки, огры-налетчики и свирепые таинственные воргены.",h="Некогда залитая солнцем равнина на юге Элвинна, известная как Светлая роща, Сумеречный лес теперь — проклятые...",kw={"althea ebonlocke","brightwood","darkshire","duskwood","ello ebonlocke","jitters","morbent fel","night watch","raven hill","scythe of elune","sven yorgen","twilight grove","worgen","алтея чернодрев","светлая роща","темнолесье","сумеречный лес","элло чернодрев","трясунчик","морбент скверн","ночной дозор","вороний холм","коса элуны","свен йорген","мглистая роща","воргены"},ang={["class:Druid"]="В Мглистой роще растет древнее Великое Древо, тесно связанное с Изумрудным Сном, поэтому Сумеречный лес — центр внимания друидов, изучающих дремлющую магию мира.",["class:Paladin"]="Оскверненные курганы Вороньего Холма и зловещий некромант Морбент Скверн делают Сумеречный лес неотложным испытанием для священных воинов, владеющих Светом.",["faction:Alliance"]="Хотя формально Сумеречный лес принадлежит Альянсу, Штормград не оказывает ему никакой официальной военной поддержки, и край держится лишь на отважных искателях приключений и Ночном Дозоре.",["profession:Herbalism"]="Призрачные курганы и проклятая почва дают редкие растения, такие как могильный мох и королевская кровь, привлекая собирателей, готовых рискнуть встречей с неупокоенными на кладбищах."},sec={{t="От Светлой рощи к тени",b="До наступления тьмы эта провинция называлась Светлой рощей — богатым земледельческим краем Королевства Штормград с процветающими поселениями, такими как Большая деревня и Вороний Холм. Трагедия региона началась, когда Хранитель Медив пал в Каражане во время Первой войны, и волны оскверненной магии Скверны исказили безмятежный лес, превратив его в корявую, мрачную трясину. Пауки мутировали в жутких хищных тварей, а бегущие волки хлынули на север, в Элвиннский лес. Со временем Большую деревню переименовали в Темнолесье, и ее напуганные жители остались почти без помощи, когда королевский гарнизон отступил защищать столицу."},{t="Коса и волколюди",b="Современный кошмар этих земель усилился с прибытием жрицы ночных эльфов по имени Велинда Песнь Звезд, которая несла потусторонний артефакт — Косу Элуны. Когда она исчезла в заброшенной шахте Погибель Роланда, реликвию в конце концов откопал рабочий-старатель по имени Трясунчик. Неосторожное обращение с оружием выпустило в леса ненасытных двуногих волкозверей — воргенов. Окутанные вечным туманом и жаждой крови, эти хищники из иного измерения прокатились по западным рощам, усугубив бедствия края, и без того стонущего под проклятиями нежити."},{t="Осажденное приграничье",b="Сегодня Темнолесье держится лишь благодаря бдительности командира Алтеи Чернодрев и ее ополчения из добровольцев — Ночного Дозора, а лорд Элло Чернодрев пытается управлять разрушающимся поселением. За освещенной фонарями границей города таится смертельная опасность: огромное Кладбище Вороньего Холма кишит беспокойными мертвецами, поднятыми некромантом Морбентом Скверном, огры Вул'Гол переселились с Перевала Мертвого Ветра, чтобы захватить юг, а зловещие Темные всадники неустанно рыщут на перекрестках в поисках потерянной Косы."},{t="Мглистая роща",b="Почти в центре Сумеречного леса лежит глубокий древний кратер, не поддающийся окружающей порче: Мглистая роща. Задолго до того, как в этих землях появились человеческие королевства, верховный друид Фэндрал Олений Шлем посадил здесь ветвь Нордрассила, чтобы сдержать рост мерзкого саронита. Ветвь превратилась в Великое Древо, хранящее дремлющий портал в Изумрудный Сон. Роща, залитая мягким неземным сумеречным светом, остается потусторонним убежищем в умирающем краю под защитой спящих друидических энергий."}},faq={{q="Почему край называется Сумеречным лесом, а не Светлой рощей?",a="Эти земли некогда были Светлой рощей — цветущей южной провинцией Элвинна. Когда Хранитель Медив был убит неподалеку, в Каражане, во время Первой войны, нестабильные энергии Скверны захлестнули лес, заглушив солнечный свет и исказив растительность. Так появилось название Сумеречный лес.",al={"why duskwood dark","brightwood history","what happened to brightwood","почему сумеречный лес темный","светлая роща история","что случилось со светлой рощей"}},{q="Откуда взялись воргены?",a="Ночная эльфийка Велинда Песнь Звезд принесла в этот край волшебную Косу Элуны и погибла возле Погибели Роланда. Спустя годы напуганный рабочий по имени Трясунчик потревожил косу в шахте и невольно открыл разрывы, призвавшие в лес свирепых волколюдей.",al={"why are there worgen","worgen origin duskwood","scythe of elune worgen","откуда воргены","происхождение воргенов сумеречный лес","коса элуны воргены"}},{q="Почему на Вороньем Холме так много нежити?",a="Кладбище Вороньего Холма стало местом упокоения бесчисленных душ, погибших от голода, зверей и войны. Мерзкий некромант Морбент Скверн устроил логово в Покинутой усадьбе и с помощью темного колдовства оживляет могилы, создавая вурдалаков, скелетов и поганищ.",al={"raven hill undead","why ghosts in duskwood","morbent fel undead","нежить вороний холм","почему призраки в сумеречном лесу","морбент скверн нежить"}},{q="Почему Штормград не прислал солдат на помощь Темнолесью?",a="Король Вариан Ринн пропал, ресурсов не хватает, и регентство Штормграда отвело войска, чтобы защитить Элвинн и трон. Темнолесье оставлено на произвол судьбы, и его защищает лишь добровольческое ополчение — Ночной Дозор.",al={"why no stormwind guard","stormwind abandoned darkshire","where is the army","почему нет стражи штормграда","штормград бросил темнолесье","где армия"}},{q="Кто такие Темные всадники, рыщущие в лесу?",a="Темные всадники — таинственные всадники в капюшонах, прибывшие с Перевала Мертвого Ветра возле Каражана. Привлеченные высвобождением Косы Элуны, они ворвались в Сумеречный лес и безжалостно убили семью Свена Йоргена, разыскивая артефакт.",al={"black riders deadwind","riders at yorgen farm","who are dark riders","черные всадники мертвый ветер","всадники на ферме йоргена","кто такие темные всадники"}},{q="Что это за огромное дерево в центральном кратере?",a="Этот кратер — Мглистая роща, где растет Великое Древо, выращенное тысячи лет назад из ветви Нордрассила, посаженной Фэндралом Оленьим Шлемом. В нем есть портал в Изумрудный Сон, и там царят спокойные, волшебные сумерки, непохожие на проклятый мрак леса.",al={"twilight grove tree","green portal duskwood","crater tree","дерево мглистой рощи","зеленый портал сумеречный лес","дерево в кратере"}}},fp="8,457,25.660.0,27.595.1,24.510.0,18.501.0,48.274.0,31.274.1,43.254.0,53.257.0,43.240.1,46.267.0"}
P.entries["zone:dustwallow"] = {n="Пылевые топи",s="Пылевые топи — обширные знойные болота в центральном Калимдоре, зажатые между засушливыми равнинами Степей и Великим морем. Их коварные трясины, питаемые вечными подземными источниками, скрывают опасных хищников, тайные стычки фракций и притаившееся присутствие черного драконьего рода. Здесь находятся островная крепость Альянса Терамор на востоке и деревня огров Каменного Молота, союзных Орде, — Деревня Гиблотопь на северо-западе.",h="Пылевые топи — обширные знойные болота в центральном Калимдоре, зажатые между засушливыми равнинами Степей и...",kw={"alcaz","brackenwall","dustwallow","jaina","marsh","onyxia","quagmire","stonemaul","tabetha","theramore","wyrmbog","алькац","гиблотопь","пылевые топи","джайна","болото","ониксия","трясина","каменный молот","табета","терамор","драконьи топи"},ang={["class:Mage"]="Маги стекаются через трясины к Ферме Табеты в Трясине, ища уникальные знания отшельницы о чародейских каналах и древних источниках силы.",["faction:Alliance"]="В Пылевых топях находится Остров Терамор — сердце присутствия Альянса в Калимдоре. Искатели приключений, прибывающие через Гавань Менетилов, охраняют его дамбы и распутывают клубок дезертирства и пропавших посланников.",["faction:Horde"]="Посланники Орды приходят на помощь осажденным ограм Каменного Молота в Деревне Гиблотопь, отражают набеги драконов из Драконьих топей и настороженно следят за передвижениями людей с побережья."},sec={{t="Затопленный край",b="До Великого Раскола Пылевые топи были высокой травянистой равниной, кишевшей стадными животными. Катаклизм разрушил долину, уровень грунтовых вод поднялся и затопил землю бесконечными застойными лужами, мшистыми отмелями и вязкой грязью. Подземные источники поддерживают в болоте постоянную влажность, оно окутано густым туманом и кишит кроколисками, ящерами и пауками. Острые мели и блуждающие трясины делают путь опасным для любого искателя приключений, сошедшего с ветхих гатей."},{t="Старая вражда и шаткое перемирие",b="Пылевые топи оставались в основном дикими до окончания Третьей войны, когда леди Джайна Праудмур привела людей-беженцев через море и основала цитадель на острове Терамор у восточного побережья. Вскоре после этого силы Култирасцев под командованием верховного адмирала Даэлина Праудмура начали войну против молодой Орды Тралла, и она завершилась кровавыми битвами на болотах и поражением адмирала. Сегодня между Тераморе и Оргриммаром действует официальное перемирие, но напряжение тлеет под поверхностью. Терамор страдает от дезертирства и диверсий, а шпионы ведут тихую смертельную борьбу в трясинах."},{t="Тень Драконьих топей",b="Юг топей поднимается неровной скалистой трясиной, известной как Земля Драконов и Драконьи топи. Первоначально эту местность заселили огры Каменного Молота под предводительством могучего воина из Мок'Натал Рексара, но она превратилась в кладбище, когда черный драконий род жестоко изгнал клан из деревни Каменного Молота. Изгнанные огры бежали на север, в Деревню Гиблотопь, к Властителю Мок'Морокку, и поклялись отомстить. Среди этих зазубренных скал таится Ониксия, дочь Смертокрыла: она управляет своим выводком и плетет зловещие интриги далеко за пределами болота."}},faq={{q="Какое главное поселение Альянса здесь находится?",a="Присутствие Альянса сосредоточено на Острове Терамор — укрепленном городе-государстве на скалистом острове у восточного побережья. Он основан леди Джайной Праудмур после Третьей войны, соединен с Калимдором узкой дорогой и поддерживает важные морские пути до Гавани Менетилов в Восточных королевствах.",al={"alliance base dustwallow","where is theramore","human town dustwallow","база альянса в пылевых топях","где терамор","human town пылевые топи"}},{q="Где искателям приключений из Орды найти убежище на болоте?",a="Путники из Орды разбивают лагерь в Деревне Гиблотопь на северо-западе болот. Поселение основал клан огров Каменного Молота, которые присоединились к Орде под началом Рексара и открыли ворота для орков и таурен.",al={"horde base dustwallow","where is brackenwall","ogre village","база орды пылевые топи","где гиблотопь","деревня огров"}},{q="Почему на юге болот так много черных драконов?",a="Южная область, известная как Драконьи топи и Земля Драконов, — это выводковые земли и владения Ониксии, дочери Смертокрыла. Ее черное драконье отродье жестоко изгнало огров Каменного Молота и превратило скалистые выступы и глубокие пещеры в гнезда для драконов и их детенышей.",al={"wyrmbog dragons","why black dragons here","dragonmurk","драконьи топи драконы","почему здесь черные драконы","земля драконов"}},{q="Что случилось с прежним домом огров Каменного Молота?",a="Огры Каменного Молота жили мирно в деревне Каменного Молота на юге болот. Однако черный драконий род совершил сокрушительное нападение, убив многих и вынудив выживших бежать на северо-запад, в Деревню Гиблотопь.",al={"stonemaul ruins","what happened to stonemaul village","old ogre town","руины деревни каменного молота","что случилось с деревней каменного молота","старый город огров"}},{q="Кто живет в одинокой хижине в Трясине?",a="Хижина принадлежит Табете — эксцентричной и могущественной магессе-отшельнице, тихо живущей в глубине болот. Заклинатели тайной магии часто ищут ее ради обучения или помощи в очищении нестабильных магических реликвий.",al={"tabetha's farm","tabetha dustwallow","who is the witch in the swamp","ферма табеты","табета пылевые топи","кто ведьма на болоте"}},{q="Что такое Остров Алькац и кто им владеет?",a="Остров Алькац — сильно охраняемый остров у северо-восточного побережья болот. Он принадлежит нагам Страшаз, его патрулируют опасные элитные защитники, а в окружающих водах таятся гидры.",al={"alcaz island","island off coast dustwallow","what is on alcaz","остров алькац","остров у побережья пылевых топей","что на алькаце"}}},fp="16,455,19.504.0,29.597.0,25.524.2,42.305.0,53.235.0,58.268.2,52.241.0,52.222.0,41.193.2"}
P.entries["zone:easternplaguelands"] = {n="Восточные Чумные земли",s="Восточные Чумные земли — опустошенное сердце павшего королевства Лордерон, задыхающееся под гнетом порчи Плети, ядовитых туманов и оскверненных грибных зарослей. Стратхольм возвышается на севере как оплот нежити в регионе, а фанатичный Алый орден укрепился на востоке. Среди этого кошмара Часовня Последней Надежды остается стойким нейтральным убежищем для всех, у кого хватит смелости дать отпор.",h="Восточные Чумные земли — опустошенное сердце павшего королевства Лордерон, задыхающееся под гнетом порчи...",ang={["class:Paladin"]="Павшее королевство Лордерон хранит для Серебряной Длани глубокую трагедию — от места падения Артаса во тьму в Стратхольме до доблестной последней битвы у Часовни Последней Надежды.",["faction:Alliance"]="Для Альянса поход в Чумные земли — торжественное паломничество, чтобы вернуть и почтить разоренные остатки своих бывших северных союзников.",["profession:Herbalism"]="Этот зараженный край — одно из немногих исключительно редких мест, где можно собирать нестабильные высокоуровневые травы, такие как Слезы Артаса, Чумоцвет и Черный лотос.",["profession:Mining"]="Жилы истинного серебра, мифрила и богатого тория залегают на оскверненных холмах и в опасных долинах, кишащих Плетью.",["race:Undead"]="Восточные Чумные земли — одновременно колыбель угрозы Плети и важный фронт, где Отрекшиеся наносят ответный удар своим бывшим повелителям и фанатикам Алого ордена."},sec={{t="Земля в руинах",b="Некогда этот край назывался плодородным Восточным Пределом и был житницей северного Лордерона: его опорой были великий город Стратхольм и процветающие поселения вроде Дарроушира и Перекрестка Корина. Во время Третьей войны принц Артас учинил в Стратхольме чистку, узнав, что в запасы зерна подмешана Чума нежизни. После падения королевства темная магия Плети распространялась беспрепятственно. Почва стала бурой и гнилой, обычные растения превратились в гигантские грибы, а над долинами завис жуткий оранжевый туман."},{t="Война на три фронта",b="Стратхольм — южная резиденция власти Плети в Лордероне; им управляет барон Ривендер по указанию лича Кел'Тузада. Нежити с юго-востока противостоит фанатичный Алый орден, укрепивший Длань Тира и штурмующий алые бастионы Стратхольма. Их догматическая ненависть распространяется не только на мертвых, но и на любого живого путника, пересекающего их границы. На севере лесные тролли Мшистой Кожи из Зул'Машара ведут собственные отчаянные кампании в изоляции, оказавшись под огнем более крупного конфликта."},{t="Оплоты живых",b="Выжить в Восточных Чумных землях можно, лишь ступая осторожно. Нейтральный Серебряный Рассвет действует из Часовни Последней Надежды на дальнем востоке, предлагая безопасное убежище, необходимые припасы и маршруты полета для героев Альянса и Орды. За пределами часовни две фракции сражаются за четыре стратегические разрушенные башни — Королевской Стражи, Восточной Стены, Северного перевала и Проклятого леса, — борясь за тактическое преимущество на всей территории, которое усилит их бойцов против ужасов нежити."}},faq={{q="Что сделало небо и деревья такими больными?",a="Местность страдает от концентрированного действия Чумы нежизни Культа Проклятых. Оставленная без контроля после Третьей войны, мерзкая некромантическая магия отравила землю, превратила местных животных в мутантов, затянула воздух неестественным оранжевым смогом и обратила природные леса в уродливые грибные рощи вроде Проклятого леса.",al={"why is the sky orange","why giant mushrooms","eastern plaguelands corruption","почему небо оранжевое","почему гигантские грибы","порча восточных чумных земель"}},{q="Где здесь найти безопасное убежище или пункт полета?",a="Часовня Последней Надежды, расположенная на восточном краю зоны, — главное убежище. Она находится под опекой Серебряного Рассвета и предлагает маршруты полета в Подгород, Стальгорн, Лагерь Промозглого Ветра и Внутренние земли, принимая путников как из Альянса, так и из Орды.",al={"epl safe zone","where is flight path epl","friendly town eastern plaguelands","безопасная зона вчз","где пункт полета вчз","дружелюбный город восточные чумные земли"}},{q="Кто управляет городом Стратхольм?",a="Стратхольм разделен непрекращающейся войной. Большей частью горящих руин правит Плеть под началом барона Ривендера, служащего Кел'Тузаду. Однако Алый орден удерживает агрессивный гарнизон в западном районе, ведя беспощадную кровавую осаду против сил нежити.",al={"who leads stratholme","stratholme bosses lore","what is in stratholme","кто правит стратхольмом","боссы стратхольма история","что в стратхольме"}},{q="Почему Алый орден враждебен к чужим искателям приключений?",a="После падения Лордерона и раскола Серебряной Длани Алый орден поддался безудержному фанатизму и паранойе. Убежденные, что все чужаки несут на себе заразу чумы или водятся с нежитью, они нападают на любых посторонних, приближающихся к их твердыням, например к Длани Тира.",al={"why does scarlet crusade attack me","tyrs hand hostile","scarlet crusade red","почему алый орден атакует меня","длань тира враждебна","алый орден красный"}},{q="Что случилось с городом Дарроушир?",a="Во время Третьей войны силы Плети под предводительством рыцаря смерти Мардука Черного и вурдалака Хоргуса Опустошителя напали на город. Хотя паладин Дэвил Крокфорд и капитан Джозеф Редпат сражались доблестно, душа Редпата была осквернена некромантией, и он стал орудием резни против собственного народа. Теперь город лежит в призрачных руинах.",al={"darrowshire lore","fall of darrowshire","who destroyed darrowshire","история дарроушира","падение дарроушира","кто уничтожил дарроушир"}},{q="Почему Альянс и Орда сражаются за разрушенные башни?",a="По всей зоне разбросаны четыре разрушенные сторожевые башни Лордерона: Королевской Стражи, Восточной Стены, Северного перевала и Проклятого леса. Обе фракции борются за контроль над ними, чтобы получить стратегические оборонительные форпосты и тактические преимущества на всей территории, помогающие их силам против окружающей нежити.",al={"epl towers","a game of towers","plaguelands tower objectives","башни вчз","игра башен","цели башен чумных земель"}}},fp="19,413,14.545.0,21.553.0,22.472.0,46.338.0,50.261.0,36.298.0,58.302.0,41.355.0,59.275.0"}
P.entries["zone:elwynn"] = {n="Элвиннский лес",s="Элвиннский лес — зеленое сердце Королевства Штормград, снабжающее столицу древесиной, золотом, рыбой и урожаем. Укрытый под величественными лиственными деревьями, он служит испытательной площадкой для новых человеческих рекрутов, выходящих из Аббатства Североземья. Но под его идиллической сенью лес сильно страдает от наступающих вредителей, согнанных с мест животных и повсеместного разбоя.",h="Элвиннский лес — зеленое сердце Королевства Штормград, снабжающее столицу древесиной, золотом, рыбой и...",kw={"defias","eastvale","elwynn","elwynn forest","fargodeep","goldshire","hogger","jasperlode","nazferiti","northshire","northshire abbey","vancleef","братство справедливости","восточная долина","элвиннский лес","подземные глубины","златоземье","хоггер","яшмовая шахта","назферити","североземье","аббатство североземья","ван клиф"},ang={["class:Rogue"]="Вездесущая тень Братства Справедливости делает Элвиннский лес любопытным перекрестком воровства, контрабанды и подпольных сигналов повстанцев.",["faction:Alliance"]="Защита Элвиннского леса жизненно важна для выживания главного человеческого королевства Альянса: если маршруты древесины, руды и зерна рухнут, Штормград не сможет себя обеспечивать.",["profession:Mining"]="Горное Эхо, Подземные Глубины и Яшмовая шахта богаты медными жилами, что делает лес важной начальной площадкой для шахтеров, несмотря на нашествие кобольдов.",["race:Human"]="Это исконное сердце королевства. Люди-искатели приключений начинают здесь, обучаясь в Аббатстве Североземья, а затем отправляются защищать родину от бандитов, зверей и политического краха."},sec={{t="Житница королевства",b="Простираясь на юг от ворот Штормграда до реки Назферити, Элвиннский лес — плодородный край с обильными дождями и густыми лиственными лесами. Поселения вроде Златоземья и Лесопилки Восточной долины поставляют столице зерно, скот, древесину и медную руду. Край также славится разведением выносливых лошадей Эвендейла, любимых путниками и рыцарями по всему королевству."},{t="Хрупкий мир",b="Несмотря на внешнее спокойствие, лес на грани беспорядка. Армия Штормграда растянута дальними обязательствами, и местные маршалы и помощники полагаются на неопытных новобранцев. Кобольды заполонили Рудник Подземных Глубин и Яшмовую шахту, жизненно важные для края, гноллы Речной Лапы бродят у юго-западных границ, а свирепые мурлоки захватили берега Озера Каменных Столбов и Озера Хрустального. Из-за растущей порчи за рекой в Сумеречном лесу волки бежали на север через границу."},{t="Угроза красных банданов",b="Братство Справедливости, куда более организованное, чем простые мародеры, глубоко проникло в лес. Возникнув из недовольной Гильдии каменщиков Эдвина ван Клифа после горьких споров об оплате с Домом знати, эти люди в масках захватили владения по всему Элвиннскому лесу, включая Виноградники Североземья, Тыквенное поле Бреквеллов, Лагерь Джерода и Сад у Зеркального озера. Ходят слухи, что их согласованно действующие агенты тайно направляют соседних гноллов и кобольдов, чтобы еще сильнее расшатать королевство. Стражники Рольф и Малакай, посланные расследовать дела мурлоков у Озера Каменных Столбов, были убиты и оставлены на его берегах."}},faq={{q="Почему Стража Штормграда почти не охраняет лес?",a="Вооруженные силы Штормграда крайне перегружены. Королевство направило крупные военные силы на юг, в Тернистую долину, наделав глубоких долгов и истощив местные людские ресурсы. В результате такие форпосты, как Гарнизон у Западного ручья и Златоземье, полагаются на малочисленные команды и добровольцев в борьбе с бандитами, гноллами и мурлоками.",al={"where are the guards","why no stormwind army","why is elwynn undefended","где стража","почему нет армии штормграда","почему элвиннский лес не защищен"}},{q="Почему во всех рудниках кобольды?",a="Из-за нехватки стражи оборотистые кобольды хлынули в Рудник Подземных Глубин, Яшмовую шахту и Рудник Горного Эха в поисках золота и минералов. Они изгнали людей-старателей и шахтеров, яростно защищая свои подземные владения свечами, грубыми кирками и подобранными инструментами.",al={"why are kobolds in the mines","elwynn kobolds","fargodeep infested","почему кобольды в шахтах","кобольды элвиннского леса","рудник подземных глубин заражен"}},{q="Кто эти бандиты в красных масках?",a="Это члены Братства Справедливости во главе с Эдвином ван Клифом. Многие из них были ремесленниками Гильдии каменщиков, отстроивших Штормград после Первой войны. Когда знать отказалась платить им обещанное жалованье, начались бунты, за которыми последовали изгнание и скатывание к организованному разбою.",al={"red masks","red bandana bandits","who are the defias in elwynn","красные маски","бандиты в красных банданах","кто такие братство справедливости в элвиннском лесу"}},{q="Куда ведет дорога на юг?",a="Пересекая мост через реку Назферити, вы попадете в Сумеречный лес, исторически известный как Светлая роща. Эта некогда мирная земля погрузилась в неестественную тьму и теперь кишит нежитью, чудовищными пауками и голодными зверями.",al={"what is across the river","where does duskwood bridge go","bridge across the nazferiti","что за рекой","куда ведет мост в сумеречный лес","мост через назферити"}},{q="В чем состоит вражда Маклюров и Стоунфилдов?",a="Стоунфилды и Маклюры — соседние фермерские семьи на юге Элвиннского леса, давно питающие друг к другу ожесточенную неприязнь. Несмотря на бесконечные перебранки и обвинения, двое их младших родственников — Мейбелл Маклюр и Томми Джо Стоунфилд — тайно влюбились друг в друга, еще больше осложнив соперничество.",al={"maclure vs stonefield","elwynn farm rivalry","stonefield maclure feud","маклюры и стоунфилды","соперничество ферм элвиннского леса","вражда стоунфилдов и маклюров"}},{q="Что такое Башня Азоры?",a="Башня Азоры — волшебный шпиль у дороги между Златоземьем и Лесопилкой Восточной долины. В ней живут уединенные маги, в том числе Теокрит, которые наблюдают за энергетическими линиями региона и ведут магические исследования вне прямого надзора Святилища волшебника Штормграда.",al={"tower on the road to eastvale","wizard tower elwynn","who lives in the tower of azora","башня на дороге к восточной долине","башня мага элвиннский лес","кто живет в башне азоры"}}},fp="13,409,28.423.0,18.493.0,22.639.1,54.341.0,43.303.0,38.313.0,31.240.0,54.342.0,27.282.0"}
P.entries["zone:felwood"] = {n="Оскверненный лес",s="Оскверненный лес — зараженный лес между Ясеневым лесом и Горой Хиджал, глубоко отравленный демонической магией во время Третьей войны. Некогда пышный рай лугов и рощ, за которыми ухаживали ночные эльфы, теперь он кишит демоническими сатирами, пускающими слюни зверями и искаженными древними. Друиды Круга Кенария вместе с заставами Альянса и Орды отчаянно пытаются очистить землю и изгнать Совет Теней из ее глубин.",h="Оскверненный лес — зараженный лес между Ясеневым лесом и Горой Хиджал, глубоко отравленный демонической...",ang={["class:Druid"]="Оскверненный лес — глубокая трагедия для Круга Кенария: друиды посвящают жизнь очищению зараженных растений и усмирению обезумевших духов природы.",["class:Warlock"]="Темные туннели Джеденара и остаточные демонические силы делают Оскверненный лес центром охоты на соперников-культистов Совета Теней.",["profession:Herbalism"]="Пропитанная скверной земля дает редкие и нестабильные растения; это одно из немногих мест в Азероте, где можно собрать Кровь Грома и Слезы Артаса.",["race:NightElf"]="Осквернение этих древних лесов вызывает у кальдораев огромную скорбь и стыд: они не сумели защитить их от прикосновения Легиона."},sec={{t="Осквернение рая",b="До Третьей войны эта долина была мирным приютом с поющими птицами, чистыми ручьями и тихими рощами, которые охраняли древние защитники. Все изменилось, когда лорд ужаса Тихондрий и Пылающий Легион применили Череп Гул'дана, чтобы отравить север Калимдора перед нападением на гору Хиджал. Мерзкое колдовство черепа превратило лесную почву в черную трясину. Хотя Иллидан Ярость Бури в конце концов убил Тихондрия и поглотил сущность артефакта, земля осталась пропитана скверной Скверны. Могучие древни и древние гнили изнутри, реки превратились в кипящую желчь, а лесные звери впали в безумие и стали пожирать друг друга."},{t="Война за очищение",b="Исцеление Оскверненного леса оказалось мучительно медленным. В Изумрудном святилище на южной границе Круг Кенария ведет трудную борьбу с порчей. Друиды снабжают странников маяками Кенария и очищающими мазями, пытаясь исцелить отравленные растения, такие как песенный цвет и луковицы ночного дракона. Обе фракции удерживают опорные пункты в оскверненных землях: ночные эльфы — в Поляне Когтистых Ветвей на севере, а Орда — в Заставе Отравленной Крови. Эти поселения служат хрупкими оплотами в смертельно опасной глуши, где природа обратилась против всякой смертной плоти."},{t="Тень в Джеденаре",b="The lingering fel taint is actively nurtured by dark cultists. Within the subterranean labyrinth of Jaedenar and Shadow Hold, remnants of the Shadow Council conduct foul rituals under the direction of Lord Banehollow. Allied with deceitful satyrs who desecrate ancient moonwells, these warlocks harvest the forest's agony and summon forth demonic reinforcements. Any lasting hope of redeeming Felwood requires tearing this insidious council out by its roots."}},faq={{q="Почему Оскверненный лес испорчен?",a="Во время Третьей войны лорд ужаса Тихондрий использовал демонический артефакт, известный как Череп Гул'дана, чтобы осквернить лес. Это должно было ослабить оборону ночных эльфов во время похода Пылающего Легиона к горе Хиджал, отравив животных, воду и древних.",al={"how did felwood get corrupted","what happened to felwood","why are the trees dead","как оскверен оскверненный лес","что случилось с оскверненным лесом","почему деревья мертвы"}},{q="Можно ли очистить испорченные растения в лесу?",a="Да. Друиды Круга Кенария дают искателям приключений мази, сваренные из собранной скверны и минеральных остатков. Нанесение этих мазей на такие растения, как песенный цвет, хлесткие клубни и ночные драконы, очищает их от порчи и дает сильные целебные плоды и благословения.",al={"how to cleanse plants","cenarion plant salve","corrupted songflower","как очистить растения","мазь кенария для растений","испорченный песенный цвет"}},{q="Кто управляет Джеденаром?",a="Jaedenar is held by the Shadow Council, a clandestine sect of mortal warlocks and demon worshippers. From deep within the subterranean caverns of Shadow Hold, the dreadlord Lord Banehollow oversees their dark rituals and commands the satyrs inhabiting the region.",al={"what is jaedenar","who is in shadow hold","jaedenar boss","что такое джеденар","кто в оплоте теней","босс джеденара"}},{q="Враждебны ли фурболги в Оскверненном лесу?",a="Most are hostile. Tribes such as the Deadwood have completely succumbed to demonic corruption and fel madness. However, the Timbermaw tribe holding the northern tunnel network remains uncorrupted, though they are deeply distrustful of outsiders until proven friendly.",al={"felwood furbolgs","timbermaw furbolgs","deadwood village"}},{q="Как добраться до Лунной поляны или Зимних Ключей через Оскверненный лес?",a="Дорога ведет прямо на север, в Крепость Древобрюхов — укрепленный пещерный комплекс. Неоскверненные фурболги Древобрюхи контролируют туннели, соединяющие Оскверненный лес с Лунной поляной и Зимними Ключами. Путникам придется либо заслужить их доверие, либо пробиваться с боем.",al={"timbermaw tunnel","road to winterspring","pass to moonglade","туннель древобрюхов","дорога в зимние ключи","проход в лунную поляну"}},{q="Почему испорченные древние нападают на ночных эльфов?",a="Некогда благородные древние и древни были изуродованы и отравлены демонической магией. Связанные вечной мукой, их разбитые умы питают глубокую обиду на ночных эльфов, которые, по их мнению, бросили их на растерзание Пылающему Легиону.",al={"mad treants","corrupted ancients","why ancients hostile","безумные древни","испорченные древние","почему древние враждебны"}}},fp="7,424,19.653.0,21.569.0,22.458.1,25.279.0,51.281.0,22.263.0,36.267.0,60.250.0,49.238.0"}
P.entries["zone:feralas"] = {n="Фералас",s="Фералас — обширный тропический лес, окутанный туманом, между Пустошами, Тысячей Игл и Сокрытым Морем. Защищенный высокими горными стенами, он сохраняет древнюю экосистему с заросшими руинами кальдораев и первобытными зверями. Сегодня эти дебри — спорная территория: здесь остатки древних высокорожденных, вторгшиеся огры Гордунни и соперничающие поселения Альянса и Орды.",h="Фералас — обширный тропический лес, окутанный туманом, между Пустошами, Тысячей Игл и Сокрытым Морем.",kw={"camp mojache","dire maul","dream bough","eldre'thalas","feathermoon","feralas","gordunni","shandris","thalanaar","лагерь мохаче","забытый город","сонные ветви","эльдре'талас","оперенная луна","фералас","гордунни","шандрис","таланаар"},ang={["class:Druid"]="Сонные Ветви и их связь с Изумрудным Сном делают Фералас священной землей, требующей бдительности против наступающей порчи и осквернителей.",["faction:Alliance"]="Операции ведутся из Крепости Оперенной Луны под командованием Шандрисы Оперенной Луны: агентам поручено сдерживать прибрежных наг и защищать наследие эльфов.",["faction:Horde"]="Лагерь Мохаче служит важным приграничным бастионом, где нужны надежные воины, чтобы отражать агрессивные набеги Гордунни, отступников Зловещего Тотема и гноллов Лесной Лапы.",["profession:Herbalism"]="Влажная затененная почва под пологом леса дает ценные растения умеренного и тропического климата, включая Солнечник, Лиловый лотос и Кадгаров ус.",["race:NightElf"]="Фералас имеет глубокое культурное значение как колыбель древней цивилизации кальдораев, и вид священных руин вроде Эльдре'Таласа, оскверненных ограми, вызывает у ночных эльфов глубокую скорбь и гнев."},sec={{t="Лес, не тронутый пустошами",b="Пока соседние Пустоши и Тысяча Игл превратились в бесплодные земли и иссохшие каньоны, Фералас остается пышно зеленым. Горные хребты закрывают полог леса, поддерживая теплый микроклимат с густыми туманами, древними деревьями и высокими водопадами. До Великого Раскола большая часть Калимдора выглядела так. За тысячелетия глубокие джунгли поглотили памятники цивилизации кальдораев, некогда правивших здесь, скрыв забытые храмы и павильоны под удушающим мхом и густыми папоротниками."},{t="Руины Эльдре'Таласа",b="В центре Фераласа возвышается разрушенный город Эльдре'Талас, ныне называемый Забытым Городом. Построенный в расцвете империи кальдораев, он лежит в руинах, а его обширные каменные дворы осквернены свирепым кланом огров Гордунни. Эти огры расселились по долине, грабя священные места, оскверняя нетронутые рощи и доводя местных животных до исступления. В глубине запечатанных залов Забытого Города по-прежнему ходят слухи об остатках высокорожденных и заточенных силах десятитысячелетней давности."},{t="Борьба за опорные пункты",b="И Альянс, и Орда снаряжали в джунгли крупные экспедиции, хотя пробираться по ним по-прежнему опасно. Из Крепости Оперенной Луны на Острове Сардор генерал Шандриса Оперенная Луна направляет Часовых против расширения огров и наступающих наг. На востоке лежит Лагерь Мохаче, главный гарнизон Орды, борющийся с агрессивными гноллами Лесной Лапы, враждебными тауренами Зловещего Тотема и неутомимыми кланами огров. Ни одна из фракций не контролирует по-настоящему неукротимую глубь."}},faq={{q="Что такое Забытый Город?",a="Забытый Город — нынешнее название Эльдре'Таласа, великолепного эльфийского города, пережившего Раскол. За тысячелетия он пришел в упадок и был захвачен жестоким кланом Гордунни. Сейчас комплекс разделен на спорные крылья, где обитают огры, коварные духи и древние тайны высокорожденных.",al={"eldre'thalas","ogre city","ancient ruins center","эльдре'талас","город огров","центр древних руин"}},{q="Как путникам из Альянса безопасно добраться до Крепости Оперенной Луны?",a="Исследователи Альянса, идущие из Пустошей, могут пройти на юг через Два Колосса, хотя звери там опасны. Также можно войти в море у Побережья Сар'Терис в Пустошах и поплыть на юг вдоль Забытого берега прямо к Острову Сардор, полностью минуя опасную сухопутную дорогу и Лагерь Мохаче.",al={"getting to feathermoon","alliance entrance to feralas","how to get to feralas alliance","как добраться до оперенной луны","вход альянса в фералас","как попасть в фералас альянсу"}},{q="Почему Орда так агрессивно воюет с ограми Гордунни?",a="Огры Гордунни яростно расширяются из Забытого Города, грабят обозы со снабжением и нападают на путников в джунглях. Их разрушительные отряды прямо угрожают Лагерю Мохаче, и лидеры Орды, такие как Белгром Каменная Булава, призывают к быстрым и жестким ударам по поселениям клана.",al={"why kill gordunni","horde ogre war","camp mojache ogres","зачем убивать гордунни","война орды с ограми","огры лагеря мохаче"}},{q="Что такое Сонные Ветви?",a="Сонные Ветви — одно из четырех Великих Деревьев Азерота, в котором находится мистический природный портал, соединяющий физический мир с Изумрудным Сном. Как и их собратьев в Ясеневом лесу, Сумеречном лесу и Внутренних землях, их охраняют зеленый драконий род и древние стражи.",al={"green dragon portal","great tree feralas","emerald dream tree","портал зеленых драконов","великое дерево фераласа","дерево изумрудного сна"}},{q="Почему в Фераласе есть таурены Зловещего Тотема?",a="Отступническая секта тауренов Зловещего Тотема держит в глуши укрепление, действуя вне власти Громового Утеса. Они враждебны и Альянсу, и Орде; они захватили в ловушки местных волшебных драконов, и на них активно охотятся разведчики Орды.",al={"grimtotem feralas","grimtotem compound","hostile tauren","зловещий тотем фералас","поселение зловещего тотема","враждебные таурены"}},{q="Есть ли в Фераласе силитиды?",a="Да. К югу от главной дороги находится Гудящая Бездна — кишащий подземный улей насекомоподобных силитидов. Их появление в пышном тропическом лесу — тревожный знак того, что коллективный разум распространяется далеко за пределы пустынных границ южного Калимдора.",al={"writhing deep","bugs in feralas","silithid hive","гудящая бездна","жуки в фераласе","улей силитидов"}}},fp="7,414,32.516.0,25.502.0,26.486.0,18.309.0,62.340.0,61.302.0,24.275.0,44.273.0,30.249.0"}
P.entries["zone:gnomeregan"] = {n="Гномреган",s="Гномреган, высеченный в заснеженных предгорьях Дун Морога, когда-то был подземной столицей и величайшим техническим чудом гномов. Сегодня он лежит в руинах на карантине, отравленный радиоактивными осадками после отчаянной обороны от нашествия подземных троггов. Его уцелевшие жители теперь живут беженцами в соседнем Стальгорне, а облученные залы заполонили мутировавшие трогги, обезумевшие лепрогномы и взбесившиеся механические стражи.",h="Гномреган, высеченный в заснеженных предгорьях Дун Морога, когда-то был подземной столицей и величайшим...",kw={"dun morogh","gnomeregan","grubbis","leper gnome","mekkatorque","radiation","thermaplugg","tinkers court","trogg","viscous fallout","дун морог","гномреган","граббис","лепрогном","меггакрут","радиация","термоштепсель","двор механиков","трогг","вязкие осадки"},ang={["faction:Alliance"]="Гномы плечом к плечу сражались вместе с Альянсом во Второй войне, и освобождение их потерянной столицы от Термоштепселя жизненно важно для восстановления их влияния в этой фракции.",["profession:Engineering"]="Разрушенный город остается непревзойденным кладбищем сложных шедевров, чертежей и экспериментальных механизмов и предлагает бесценные схемы посреди смертоносного механического хаоса.",["race:Dwarf"]="Ваше родство с гномами восходит к тому времени, когда ваши предки помогли заложить основы Гномрегана, а ваши раскопки в Ульдамане невольно выпустили орды троггов, погубившие его.",["race:Gnome"]="Гномреган — сердце глубочайшей трагедии и неизбывного позора вашего народа; путешествие внутрь — тяжелое паломничество, чтобы отомстить за восемьдесят процентов павших соплеменников и свергнуть предателя Термоштепселя."},sec={{t="Чудо из железа и пара",b="Задолго до своего трагического падения Гномреган был свидетельством гномьего гения, честолюбия и промышленного размаха. Обширный механический комплекс, построенный при содействии дворфов соседнего Стальгорна, питали гигантские двигатели, вращающиеся шестерни и сложная система вентиляции, для обслуживания которой требовалось пятнадцать техников, работавших круглые сутки, лишь бы воздух оставался свежим. Это был процветающий центр изобретательства, состязаний мастеров и политики, сосредоточенной вокруг Двора Механиков. Из этой гордой столицы гномы поставляли Альянсу Лордерона во время Второй войны бесценные осадные орудия, летающие машины и вооружение."},{t="Вторжение троггов и отравление",b="Примерно тогда, когда Плеть прошла через Лордерон во время Третьей войны, под Дун Морогом зашевелился подземный кошмар. Неосторожные раскопки дворфов в древнем хранилище титанов Ульдамане пробудили орды первобытных троггов, которые прорылись в нижние основания Гномрегана. Не желая бросать Альянс в трудный час и просить о помощи, главный механик Гелбин Меггакрут и его войска пять мучительных лет вели против захватчиков войну на истощение. Когда оборона рухнула, Меггакрут последовал совету главного советника, мекжинера Сикко Термоштепселя, и разрешил выпустить радиоактивные отходы из городских резервуаров в нижние уровни, чтобы уничтожить троггов. Вместо этого ядовитый газ вызвал неудержимую катастрофу и за несколько дней убил почти восемьдесят процентов гномов."},{t="Предательство безумного мекжинера",b="Катастрофа не была технической случайностью. Сикко Термоштепсель, снедаемый завистью из-за избрания Меггакрута главным механиком, намеренно позволил вторжению разрастись и спланировал отравление: он собирался прийти на помощь, перебить троггов и захватить власть над уцелевшими. Но события вышли из-под его контроля. Радиация не убила троггов, а лишь привела их в неистовство, а сам Термоштепсель оказался в ловушке в зараженных нижних ярусах. Радиационная болезнь превратила его в безумного лепрогнома, и он провозгласил себя техноповелителем Гномрегана, командуя из своего трона во Дворе Механиков бездумными выжившими прокаженными и неисправными машинами."},{t="Хрупкая победа",b="Главный механик Меггакрут сейчас руководит возвращением Гномрегана из Города механиков в Стальгорне и отправляет авантюристов Альянса в ядовитые глубины, чтобы положить конец власти Термоштепселя. Убийство мекжинера в сердце Двора Механиков лишает его власти над взбесившейся обороной и прокаженными прислужниками и приносит давно желанную месть за чудовищное предательство. Однако окончательное возвращение города остается недостижимым: глубокие туннели по-прежнему забиты облученной жижей, мутировавшими тварями и троггами, и Меггакруту приходится собирать гиробуровые экскаваторы и разрабатывать более широкие военные планы, чтобы однажды вернуть родной дом своего народа."}},faq={{q="Почему Гномреган радиоактивен?",a="Когда трогги напали из-под земли, главный механик Гелбин Меггакрут по совету Сикко Термоштепселя попытался истребить их, открыв напорные клапаны городских резервуаров с радиоактивными отходами. План должен был затопить лишь нижние уровни, но смертельная ядовитая радиация просочилась по всему городу, убила восемьдесят процентов гномов и превратила уцелевших в мутантов.",al={"what happened to gnomeregan","why is gnomeregan green","radiation in gnomeregan","что случилось с гномреганом","почему гномреган зеленый","радиация в гномрегане"}},{q="Откуда взялись все эти трогги?",a="Трогги — древние существа, разбуженные от глубокого подземного сна раскопками дворфов в комплексе титанов Ульдаман. Привлеченные вибрацией и теплом тяжелых машин Гномрегана, они прорыли обширные сети туннелей прямо в нижние уровни и инженерные кварталы города.",al={"why are there troggs in gnomeregan","trogg origin","trogg invasion","почему в гномрегане трогги","происхождение троггов","вторжение троггов"}},{q="Почему гномы не попросили Альянс о помощи против троггов?",a="Вторжение троггов случилось в разгар Третьей войны, когда Королевство Лордерон пало под натиском Плети. Считая, что выживание всего Альянса важнее, главный механик Меггакрут решил не отвлекать силы людей, дворфов и эльфов с северных фронтов и пытался справиться с вторжением собственными силами, используя лишь гномьи технологии и солдат.",al={"why didn't alliance help gnomeregan","did alliance abandon gnomes","почему альянс не помог гномрегану","бросил ли альянс гномов"}},{q="Кто такие лепрогномы?",a="Лепрогномы — это гномы, пережившие радиоактивный выброс в Гномрегане, но получившие тяжелые телесные и душевные повреждения от долгого облучения. Их кожа приобрела болезненно-бледный зеленый оттенок, тела покрыты волдырями и язвами, а разум выродился в бешеное убийственное безумие под властью Мекжинера Термоштепселя.",al={"why are the gnomes green and crazy","irradiated gnomes","leper gnome lore","почему гномы зеленые и безумные","облученные гномы","лепрогномы"}},{q="Кто такой Сикко Термоштепсель?",a="Сикко Термоштепсель был ближайшим доверенным лицом и главным советником главного механика Меггакрута. Обезумев от зависти и жажды власти, он намеренно устроил радиоактивную чистку, чтобы погубить Меггакрута и захватить трон. Облученный вместе с городом, теперь он правит как безумный деспот-прокаженный из Двора Механиков.",al={"thermaplugg","who is the final boss","mekgineer thermaplugg","термоштепсель","кто последний босс","мекжинер термоштепсель"}},{q="Что изменится после поражения Мекжинера Термоштепселя?",a="Победа над Термоштепселем лишает лепрогномов и взбесившуюся оборону управления, дает важные технические данные и наносит сильный удар по боевому духу гномов. Однако город сразу не очищается. Смертельная радиация и густые полчища троггов по-прежнему наполняют нижние коридоры, и Меггакруту нужно подготовить более глубокие раскопки, прежде чем станет возможно полное возвращение города.",al={"do we retake gnomeregan","what happens when thermaplugg dies","is gnomeregan saved","вернем ли мы гномреган","что будет, когда умрет термоштепсель","спасен ли гномреган"}},{q="Почему дворфы Черного Железа находятся в Гномрегане?",a="Враждебный клан Черного Железа направил в Гномреган посланников, которых представляет Посол из клана Черного Железа. Стремясь при любой возможности навредить и Стальгорну, и Альянсу, дворфы Черного Железа ищут выгодного союза с Термоштепселем, надеясь использовать гномьи технологии и боевые машины в своих военных целях.",al={"dark iron ambassador","why are dark irons in gnomeregan","dwarves in gnomeregan","посол из клана черного железа","почему дворфы черного железа в гномрегане","дворфы в гномрегане"}},{q="Где сейчас живут уцелевшие гномы?",a="После радиоактивной катастрофы уцелевшие незараженные гномы бежали через горы в Стальгорн. Их родичи-дворфы предоставили им убежище в Городе механиков — инженерном квартале внутри горной крепости, где Гелбин Меггакрут управляет своим изгнанным народом и планирует его возвращение домой.",al={"where are gnomes living","gnome home city","refugees in ironforge","где живут гномы","родной город гномов","беженцы в стальгорне"}}},fp="10,464,26.669.0,36.818.0,27.701.1,17.647.1,29.409.0,35.313.0,67.382.0,22.335.0,25.321.0,53.396.1,48.315.0,42.319.0"}
P.entries["zone:hallofthanes"] = {n="Чертоги танов",s="Глубоко под шумным Стальгорном находятся Чертоги танов — древний подземный комплекс, пропитанный историей дворфов. Это уединенное подземелье предназначено для начинающих искателей приключений Альянса и хранит реликвии горного королевства, которым грозит опасность. Чтобы попасть внутрь, нужно отыскать забытые пути сквозь саму гору.",h="Глубоко под шумным Стальгорном находятся Чертоги танов — древний подземный комплекс, пропитанный историей...",kw={"attunement","dungeon","durgen dirgehammer","faldrim anvilmar","hall of thanes","ironforge","magmatus","plunder","underground map","допуск","подземелье","дургэн мрачный молот","фалдрим старой наковальни","чертоги танов","стальгорн","магматус","грабитель","подземная карта"},ang={["faction:Alliance"]="Стабильность Стальгорна напрямую укрепляет Альянс, поэтому очистка этих глубоких пещер жизненно важна для защиты Высокого трона.",["race:Dwarf"]="Для дворфов путь в Чертоги танов — это путешествие к родовой скальной основе Дун Морога, где нужно изгнать осквернителей из священных залов, носящих легендарные имена кланов.",["race:Gnome"]="Как близкие союзники, живущие в Стальгорне, гномы кровно заинтересованы в уничтожении механических созданий вроде Грабителя, которые угрожают их общему убежищу."},sec={{t="Тайны под горой",b="Пока Стальгорн звенит ударами молотов в Великой кузне, забытые залы уходят гораздо глубже под камень. Чертоги танов — одни из таких почтенных подземных пределов. Они издавна связаны с родовыми линиями дворфов и реликвиями каменного дела, и теперь туда требуются отважные защитники Альянса, которые спустятся в их сумрачные хранилища и обезопасят глубины."},{t="Поиск пути",b="Попасть в Чертоги танов непросто. Коридоры, ведущие к этим древним хранилищам, запечатаны или скрыты от обычных путников в Стальгорне. Искатели приключений должны расшифровать забытые карты, начав с поисков Подземной карты, прежде чем смогут пройти по глубоким туннелям и проникнуть в подземелье."},{t="Угроза Мрачного Молота",b="В сердце комплекса таится грозное скопление опасностей: от зачарованных стражей, таких как Грабитель, и огненного громилы Магматуса до отступников древнего дворфийского рода, например Фалдрима Старой Наковальни. Внутренним святилищем правит Дургэн Мрачный Молот; его поражение наконец унимает растущие волнения под городом и защищает священные дворфийские залы от подрывной деятельности."}},faq={{q="Где находятся Чертоги танов?",a="Чертоги танов находятся под столицей дворфов Стальгорном. Они скрыты в глубоких закрытых подземных частях горы, а не на главных улицах города.",al={"hall of thanes location","where is hall of thanes","ironforge dungeon location","где чертоги танов","расположение чертогов танов","подземелье стальгорна"}},{q="Как попасть в Чертоги танов?",a="Для входа нужно открыть подземелье с помощью цепочки заданий на допуск. Начать необходимо с задания «Подземная карта», чтобы проложить путь в нижние хранилища горы.",al={"how to get into hall of thanes","hall of thanes attunement","underground map quest","как попасть в чертоги танов","допуск в чертоги танов","задание подземная карта"}},{q="Какие боссы есть в Чертогах танов?",a="В походе вас ждут четыре главные угрозы: Фалдрим Старой Наковальни, вулканический исполин Магматус, зачарованный голем по имени Грабитель и последний противник — Дургэн Мрачный Молот.",al={"boss list","who are the bosses","hall of thanes bosses","список боссов","кто боссы","боссы чертогов танов"}},{q="Какой уровень рекомендуется для этого подземелья?",a="Подземелье рассчитано на искателей приключений Альянса с 13 по 18 уровень и служит ранним подземным испытанием наряду с глубокой сетью Стальгорна.",al={"what level is hall of thanes","hall of thanes level range","какой уровень в чертогах танов","уровни чертогов танов"}},{q="Могут ли игроки Орды войти в Чертоги танов?",a="Нет. Чертоги танов — подземелье только для Альянса, расположенное прямо под столицей Альянса Стальгорном.",al={"can horde do hall of thanes","is hall of thanes alliance only","может ли орда в чертоги танов","только ли для альянса чертоги танов"}},{q="Что дает победа над Дургэном Мрачным Молотом?",a="Победа над Дургэном Мрачным Молотом ломает хватку отступников-дворфов и их призванных созданий глубоко в основаниях Стальгорна. Его гибель возвращает безопасность древним родовым хранилищам под Великой кузней.",al={"why kill dirgehammer","final boss story","durgen dirgehammer lore","зачем убивать мрачного молота","история последнего босса","дургэн мрачный молот"}}},fp="14,344,28.365.0,19.340.0,25.399.1,36.188.0,43.182.0,42.174.0,49.153.0,43.116.0,47.227.1"}
P.entries["zone:hillsbrad"] = {n="Предгорья Хилсбрада",s="Предгорья Хилсбрада — зеленый плодородный край, последний пасторальный оплот павшего королевства Лордерон. Хотя земли почти не затронула чума Плети, их раздирает жестокая открытая война между людьми Южнобережья и Отрекшимися, закрепившимися в Мельнице Таррен. Это кровавый перекресток, где армии Альянса и Орды сражаются без пощады.",h="Предгорья Хилсбрада — зеленый плодородный край, последний пасторальный оплот павшего королевства Лордерон.",kw={"azurelode","dun garok","durnholde","hillsbrad","hillsbrad fields","purgation isle","southshore","syndicate","tarren mill","азурелод","дун гарок","дарнхольд","хилсбрад","хилсбрадские поля","остров очищения","южнобережье","синдикат","мельница таррен"},ang={["class:Rogue"]="Высоко в горах над предгорьями скрыто Поместье Черного Ворона — тайное место сбора и учебная площадка самой элитной гильдии воров и убийц Азерота.",["race:Dwarf"]="Солдаты Дун Гарока воплощают решительное намерение Стальгорна защищать союзников-людей и сдерживать угрозу нежити к северу от Болотины.",["race:Human"]="Южнобережье — одно из последних убежищ вашего народа в Лордероне; прогулка по этим пастбищам болезненно напоминает о великом королевстве, погибшем от предательства и нежизни.",["race:Orc"]="Эта земля бесконечно важна для вашего народа: на разрушенных стенах Крепости Дарнхольд вождь Тралл разорвал свои цепи и пробудил дух Орды.",["race:Undead"]="Мельница Таррен — южный оплот державы Отрекшихся, где аптекарь Лидон неустанно работает над созданием Новой чумы, чтобы обеспечить будущее вашего народа."},sec={{t="Сад рядом с руинами",b="Пока север Лордерона гниет под порчей Плети, Хилсбрад остается удивительно зеленым. Его холмистые пастбища, сосновые рощи и действующие фермы дают путникам редкую возможность увидеть, каким было королевство до Третьей войны. Но этот безмятежный вид обманчив. Мирные поля и сельские дороги постоянно патрулируют вооруженные отряды, а по ним бродят бандиты-наемники и звери-падальщики. То, что должно быть житницей Лордерона, стало его самым спорным пограничьем."},{t="Война Южнобережья и Мельницы Таррен",b="Политическое сердце Хилсбрада определяют два укрепленных оплота. На юге, на побережье, лежит Южнобережье — убежище Альянса, где живут беженцы-люди и солдаты, преданные Альянсу. На севере стоит Мельница Таррен — прежде тихая человеческая фермерская деревушка, уничтоженная Плетью, а позднее укрепленная как самый южный гарнизон Отрекшихся. Земля между двумя поселениями известна по всему Азероту как безжалостная зона убийств, где бойцы Альянса и Орды непрерывно сражаются за контроль над регионом."},{t="Старые шрамы и скрытые угрозы",b="История насилия в Хилсбраде уходит глубоко. Во время Второй войны на его побережье и холмах произошли первые крупные столкновения Великого Альянса и Старой Орды. Позднее крепость Дарнхольд служила лагерем для интернированных, где вырос Тралл, прежде чем поднять восстание орков. Сегодня Дарнхольд лежит в руинах, захваченный Синдикатом — изгнанными человеческими дворянами, ставшими бандитами и головорезами. Прибрежные мурлоки, враждебные гноллы и темные мертвецы на Острове Очищения не дают ни одному уголку холмов стать по-настоящему безопасным."}},faq={{q="Почему Хилсбрад не поражен чумой, как остальной Лордерон?",a="Плеть шла в основном по центральным путям к столице и северным королевствам, поэтому Хилсбрад в основном обошли чумные котлы, погубившие север. Благодаря этому почва осталась плодородной, а растительность здоровой, и это самый нетронутый осколок старого Лордерона.",al={"why is hillsbrad green","did hillsbrad get plagued","why no plague in hillsbrad","почему хилсбрад зеленый","была ли чума в хилсбраде","почему в хилсбраде нет чумы"}},{q="Кто сейчас контролирует Хилсбрад?",a="Ни одна из сторон не контролирует его полностью. Альянс удерживает Южнобережье и ближние фермы, такие как Хилсбрадские поля, а Отрекшиеся держат Мельницу Таррен на севере. Силы дворфов удерживают крепость Дун Гарок на востоке, а преступный Синдикат занимает руины крепости Дарнхольд.",al={"who owns hillsbrad","hillsbrad faction control","is hillsbrad alliance or horde","кому принадлежит хилсбрад","контроль фракций в хилсбраде","хилсбрад альянс или орда"}},{q="Что такое Крепость Дарнхольд?",a="Дарнхольд некогда был штаб-квартирой системы лагерей для интернированных Альянса после Второй войны; им управлял Эделас Блэкмур, воспитавший там Тралла как раба-гладиатора. Тралл бежал, собрал орков и разрушил крепость. После падения Лордерона руины заняли члены Синдиката.",al={"durnholde lore","what happened at durnholde","who runs durnholde","история дарнхольда","что случилось в дарнхольде","кто правит дарнхольдом"}},{q="Почему Отрекшиеся и люди так яростно сражаются здесь?",a="Мельница Таррен — южная граница владений Сильваны Ветрокрылой, а Южнобережье — главный плацдарм и порт Альянса в Лордероне. Отрекшиеся видят в Южнобережье смертельную угрозу своему южному флангу, а люди считают нежить ужасными узурпаторами, которых нужно изгнать с родной земли.",al={"why the southshore war","southshore vs tarren mill lore","hillsbrad conflict reason","почему война за южнобережье","южнобережье против мельницы таррен","причина конфликта в хилсбраде"}},{q="Что такое Остров Очищения?",a="Остров Очищения — уединенный скалистый остров у южного побережья Хилсбрада. В отличие от холмов на материке, остров кишит сильной нежитью — вурдалаками, скелетами и мстительными духами, — что делает его крайне опасным убежищем темной магии и неупокоенных мертвецов.",al={"purgation isle lore","island off southshore","why undead on purgation isle","остров очищения","остров у южнобережья","почему нежить на острове очищения"}},{q="Кто те бандиты, что занимают лагеря и башни?",a="Они принадлежат Синдикату — организованной сети бывшей знати и пехотинцев павшего человеческого королевства Альтерак. Изгнанные за предательство своего королевства во время Второй войны, теперь они действуют как безжалостные бандиты, стремясь вернуть свои земли шантажом, воровством и убийствами.",al={"hillsbrad bandits","who is the syndicate","syndicate in hillsbrad","бандиты хилсбрада","кто такой синдикат","синдикат в хилсбраде"}}},fp="19,398,25.489.0,37.558.0,28.528.0,56.305.0,33.287.0,23.316.0,54.333.0,23.275.0,51.299.0"}
P.entries["zone:ironforge"] = {n="Стальгорн",s="Стальгорн, высеченный в сердце горы Стальгорн в заснеженном Дун Мороге, — родовая столица дворфов Бронзобородов и неприступный оплот Альянса. В центре этого раскинувшегося подземного города — раскаленная Великая кузня; он служит оживленным центром торговли, промышленности и древних дворфийских преданий. Под твердой властью короля Магни Бронзоборода он также приютил изгнанных гномов из соседнего Гномрегана.",h="Стальгорн, высеченный в сердце горы Стальгорн в заснеженном Дун Мороге, — родовая столица дворфов...",kw={"bronzebeard","deeprun tram","dun morogh","great forge","high seat","ironforge","khaz modan","magni bronzebeard","tinker town","бронзобород","подземный поезд","дун морог","великая кузня","высокий трон","стальгорн","каз модан","магни бронзобород","город механиков"},ang={["faction:Alliance"]="Стальгорн, напрямую связанный со Штормградом Подземным поездом, — северный якорь Альянса и одна из самых надежных его военных крепостей.",["profession:Blacksmithing"]="Великая кузня почитается по всему Азероту как главный центр металлообработки: здесь находится Великая наковальня, на которой мастера-кузнецы и сам король Магни превращают металл в легенды.",["race:Dwarf"]="Стальгорн — исконный дом вашего народа, гордое свидетельство вашей стойкости, вашего мастерства в обработке камня и священного рода, восходящего к титанам.",["race:Gnome"]="Со времен катастрофы, поглотившей Гномреган, Город механиков служит вам временным домом и командным центром, пока главный механик Меггакрут планирует освобождение вашего города."},sec={{t="Город камня и огня",b="Стальгорн был основан две тысячи пятьсот лет назад, когда первое поколение дворфов пробудилось в Ульдамане и отправилось на запад, в зубчатые пики Дун Морога. Углубившись в самую высокую гору, они построили огромное святилище своему прародителю-титану Каз'гороту рядом с колоссальной Великой кузней. С тех пор город расширялся концентрическими кольцами вокруг этого огненного очага. В отличие от наземных столиц, Стальгорн целиком укрыт под каменными сводами, согретый жарко пылающими очагами и подземными реками расплавленной магмы. Укрепленные врата и пещерные глубины делали его почти неприступным на протяжении веков войн."},{t="Война трех молотов",b="Много поколений три дворфийских клана жили в Стальгорне бок о бок: Бронзобороды, Громовые Молоты и дворфы Черного Железа. Когда в 230 году до Темного портала умер верховный король Модимус Старая Наковальня, за власть над горой вспыхнула жестокая гражданская война. Клан Бронзобородов одержал верх и изгнал соперников. Позже чародей-тан Тауриссан повел мстительную осаду Черного Железа, которая дошла до самого сердца Стальгорна, но была отбита силами Бронзобородов. Тауриссан случайно призвал на юге Рагнароса Повелителя Огня, расколов Красногорье и погубив собственное войско. С тех пор Бронзобороды безраздельно владеют Стальгорном."},{t="Честь Альянсу",b="Во время Второй войны орки клана Кровавой Глазницы захватили большую часть Каз Модана, но Стальгорн устоял за запечатанными вратами, пока Альянс Лордерона не снял осаду. Связанный этим долгом чести, король Магни Бронзобород поклялся в вечной верности Стальгорна Альянсу и оставался непоколебим, даже когда такие королевства, как Гилнеас и Кель'Талас, отвернулись от него. В Третью войну Магни направил свою скорбь по брату Мурадину, потерянному в Нордсколе, на ковку знаменитого клинка Испепелитель на Великой Наковальне. Сегодня Стальгорн остается одним из самых стойких бастионов Альянса."},{t="Приют для изгнанников",b="После трагического падения Гномрегана от нашествия троггов и облучения король Магни открыл врата Стальгорна для тысяч гномов-беженцев. Под началом главного механика Гелбина Меггакрута изгнанники основали Город механиков, создав в каменном городе шумный технологический приют. Благодаря Подземному поезду, напрямую соединяющему Стальгорн со Штормградом, дворфийская твердыня превратилась в оживленный перекресток дворфийского стального мастерства и гномьей изобретательности."}},faq={{q="Кто правит Стальгорном?",a="Король Магни Бронзобород правит Стальгорном и королевством Каз Модан с Высокого трона. Искусный воин и мастер-кузнец, он управлял своим народом во время Второй и Третьей войн и остается глубоко преданной опорой Альянса.",al={"ironforge king","ruler of ironforge","who is the dwarf king","король стальгорна","правитель стальгорна","кто король дворфов"}},{q="Почему в Стальгорне так много гномов?",a="Когда соседняя гномья столица Гномреган пала от внезапного нашествия троггов и катастрофического облучения, уцелевшие гномы бежали в Дун Морог. Король Магни принял их в Стальгорне и отдал им целый квартал города, ныне известный как Город механиков.",al={"gnomes in ironforge","why are gnomes here","tinker town gnomes","гномы в стальгорне","почему здесь гномы","гномы города механиков"}},{q="Что такое Великая кузня?",a="Великая кузня — огненное промышленное сердце города, питаемое подземными водопадами расплавленной магмы. Она окружает Великую наковальню, где дворфийские оружейники создают легендарное оружие и доспехи. Именно на этой наковальне король Магни выковал знаменитый священный клинок Испепелитель.",al={"great forge","ironforge anvil","center of ironforge","великая кузня","наковальня стальгорна","центр стальгорна"}},{q="Как добраться из Стальгорна в Штормград?",a="Стальгорн напрямую соединен со Штормградом Подземным поездом — необыкновенной подземной железной дорогой гномьей работы, которая проходит прямо сквозь скальное основание Восточных королевств.",al={"ironforge to stormwind","deeprun tram","train to stormwind","из стальгорна в штормград","подземный поезд","поезд в штормград"}},{q="Падал ли Стальгорн когда-нибудь под натиском вражеской армии?",a="Стальгорн никогда не падал перед внешним захватчиком. Клан Кровавой Глазницы Килрогга Мертвого Глаза осаждал его месяцами во время Второй войны, а дворфы Черного Железа прорвались в город во время Войны трех молотов, но врата и защитники устояли.",al={"has ironforge been conquered","did ironforge fall","ironforge siege","был ли стальгорн завоеван","пал ли стальгорн","осада стальгорна"}},{q="Куда ушли остальные кланы дворфов?",a="После Войны трех молотов побежденный клан Громового Молота переселился на север, в Болотину и Внутренние земли, а враждебный клан Черного Железа обосновался в Красногорье и землях Черной Горы под властью Повелителя огня.",al={"where are wildhammers","where are dark irons","three hammer clans","где громовые молоты","где дворфы черного железа","кланы трех молотов"}}},fp="9,441,24.622.0,28.636.0,21.574.0,18.482.0,20.241.0,42.268.0,24.269.0,50.210.0,43.250.0,35.236.0"}
P.entries["zone:lochmodan"] = {n="Лок Модан",s="Лок Модан — умеренная горная долина к востоку от Дун Морога, известная огромным горным озером, удерживаемым монументальной Каменной Плотиной. Регион с дворфийским городком Телсамар в центре страдает от наступающих троггов, кобольдов в шахтах и агрессивных огров в северо-восточном нагорье.",h="Лок Модан — умеренная горная долина к востоку от Дун Морога, известная огромным горным озером, удерживаемым...",kw={"farstrider lodge","ironband","mo'grosh stronghold","stonesplinter","stonewrought dam","the loch","thelsamar","troggs","valley of kings","приют странников","сталекрут","оплот мо'грош","камнедробы","каменная плотина","озеро лок","телсамар","троггов","долина королей"},ang={["class:Hunter"]="Приют Странников на юго-восточных хребтах — известное место сбора следопытов, охотящихся в долине на медведей, кроколисков и горных канюков.",["faction:Alliance"]="Лок Модан, охраняя рубеж между Дун Морогом и северными путями к Болотине, — важнейший оплот территориальной обороны Стальгорна.",["profession:Mining"]="Холмы, карьеры и населенные троггами пещеры Лок Модана богаты доступными жилами меди, олова и серебра.",["race:Dwarf"]="Лок Модан воплощает и непревзойденный инженерный гений дворфийской кладки, и опасную древнюю историю, которую ваш народ раз за разом открывает под камнем."},sec={{t="Жемчужина нагорья",b="Лок Модан в восточной части Каз Модана — приятный контраст замерзшим снежным полям Дун Морога. Суровые горные пики окружают умеренную долину сосен и берез, в которой лежит само озеро. Эту огромную массу пресной воды удерживает Каменная Плотина — архитектурный триумф, возвышающийся вдоль северного края. Мирный Телсамар — гражданский центр края, где живут странствующие горцы, охотники и шахтеры, добывающие богатые жилы меди и олова в окрестных холмах."},{t="Раскопанные ужасы и вторжения",b="Безмятежные пейзажи Лок Модана скрывают постоянное насилие. На дне озера лежат сломанные катапульты и баллисты со времен Второй войны, когда орки Орды заняли долину, пока дворфы не выбили их. Позднее дворфийские раскопки случайно выпустили из-под земли полчища свирепых троггов. Под предводительством вождей племена троггов захватили южные каньоны Долины Камнедробов и Долины Королей, угрожая торговым путям и вынуждая горцев Стальгорна отчаянно обороняться."},{t="Заговоры в тени",b="Трогги и громадные огры Оплота Мо'грош — не единственные опасности, надвигающиеся на долину. Более глубокое расследование местных диверсий показало, что в Лок Модане действуют вероломные дворфы Черного Железа. Проникнув сюда из знойных перевалов на юге, лазутчики Черного Железа нацелились на дворфийские запасы взрывчатого порошка и вынашивают зловещие замыслы против самой Каменной Плотины."}},faq={{q="Что не дает озеру затопить Болотину?",a="Все озеро удерживает Каменная Плотина — огромное чудо дворфийского каменного зодчества и инженерии. Дворфийские инженеры тщательно следят за ней, ведь ее разрушение смыло бы низинные болота Болотины на севере.",al={"what is the dam","stonewrought dam purpose","why does loch modan have a dam","что за плотина","назначение каменной плотины","зачем плотина в лок модане"}},{q="Откуда взялись все эти трогги?",a="Дворфийские исследовательские экспедиции и шахтеры случайно вскрыли подземные пещеры глубоко в горах и выпустили орды свирепых троггов, которые быстро хлынули на поверхность и устроили лагеря в долинах.",al={"why are there troggs here","trogg invasion loch modan","trogg origin","почему здесь троггов","вторжение троггов лок модан","происхождение троггов"}},{q="Какое главное поселение Альянса в этой местности?",a="Телсамар, расположенный на западных утесах, — главный город Альянса и узел путешествий: здесь есть Таверна «Крепкое пойло», торговцы и укротители грифонов с полетами в Стальгорн и дальше.",al={"loch modan town","hub in loch modan","thelsamar","город лок модана","узел в лок модане","телсамар"}},{q="Кто владеет Оплотом Мо'грош?",a="Оплот в северо-восточных горах захвачен свирепыми ограми, спустившимися в долину и устроившими укрепленный форпост, который терроризирует окрестных охотников и путников.",al={"ogre camp loch modan","ogres northeast loch modan","mogrosh","лагерь огров лок модан","огры на северо-востоке лок модана","мо'грош"}},{q="Что случилось с Раскопками Сталекрута?",a="Археологические раскопки Геолога Сталекрута были захвачены троггами, хлынувшими из подземных пещер, и команде пришлось бросить свою работу и сражаться, чтобы защитить остатки припасов.",al={"ironbands dig","why was ironbands site abandoned","prospector ironband problem","раскопки сталекрута","почему раскопки сталекрута заброшены","проблема геолога сталекрута"}},{q="Можно ли пройти из Лок Модана в Бесплодные земли или Тлеющее ущелье?",a="Да. Тропы ведут на юг через горы в засушливую пустошь Бесплодных земель, а Подгорная тропа через Долину Королей ведет на юго-запад, в вулканические скалы Тлеющего ущелья.",al={"loch modan to badlands","loch modan south exit","path to badlands","из лок модана в бесплодные земли","южный выход из лок модана","путь в бесплодные земли"}}},fp="10,325,16.560.0,31.544.0,20.406.1,52.229.0,35.216.0,52.188.0,30.188.0,44.207.0,64.202.0"}
P.entries["zone:moonglade"] = {n="Лунная поляна",s="Лунная поляна — древняя уединенная лесная долина высоко на севере Калимдора, почитаемая как священная родина друидизма и дом Круга Кенария. Она укрыта вечными сумерками и не тронута скверной смертных; это нейтральное убежище, где ночные эльфы и таурены изучают природу бок о бок. Недруидам, чтобы добраться до этого высокогорного приюта, нужно пройти опасный горный туннель — Крепость Древобрюхов.",h="Лунная поляна — древняя уединенная лесная долина высоко на севере Калимдора, почитаемая как священная родина...",kw={"cenarion circle","dendrite starblaze","emerald dream","lake elune'ara","moonglade","nighthaven","remulos","stormrage barrow dens","круг кенария","дендрит блеск звезд","изумрудный сон","озеро элуне'ара","лунная поляна","ночная гавань","ремулос","кельи малфуриона"},ang={["class:Druid"]="Лунная поляна — ваш священный дом и убежище. Благодаря врожденной духовной связи вы можете телепортироваться сюда из любой точки Азерота, чтобы советоваться с наставниками, такими как Дендрит Блеск Звезд, общаться с великими духами и осваивать облики, например водный облик.",["race:NightElf"]="Десять тысячелетий Лунная поляна была духовной родиной вашего народа и местом покоя ваших спящих верховных друидов под непреходящим благословением Элуны.",["race:Tauren"]="Ваше принятие в Круг Кенария — историческое возрождение древней связи с Кенарием, за которое выступал Хамуул Рунический Тотем; его уважают на всей Лунной поляне, несмотря на давнюю замкнутость ночных эльфов."},sec={{t="Священные сумерки",b="Лунная поляна окружена отвесными горами к северу от Оскверненного леса и Зимних Ключей и пребывает в вечной безмятежной ночи под мягким светом луны Элуны. В ее центре лежит Озеро Элуне'ара — глубокое спокойное озеро, священное со времен зарождения цивилизации кальдораев. Пылающий Легион не осквернил поляну ни во время двух древних вторжений, ни в недавней Третьей войне: ее оберегали бдительный полубог Кенарий и его потомки. Сегодня под присмотром Хранителя Ремулоса долина служит мирным оплотом, где сохраняется равновесие природы вдали от розни фракций."},{t="Средоточие Круга",b="Лунная поляна — штаб-квартира Круга Кенария, основанного тысячелетия назад Малфурионом Ярость Бури во время войны сатиров. В прибрежной деревне Ночная Гавань древние традиции направляют обучение друидов. После Третьей войны Круг сделал исторический шаг и принял в свои ряды тауренов, следуя учению верховного друида Хамуула Рунического Тотема. На Лунной поляне политическая верность Альянсу или Орде откладывается в сторону: вооруженные стражи строго блюдут нейтралитет, и любое насилие между членами Круга встречает скорое возмездие."},{t="Кельи и Сон",b="К югу от озера Элуне'ара расположены древние Кельи Малфуриона. Тысячи лет эльфийские друиды спали в этих подземных полостях, путешествуя по миру духов Изумрудного Сна, пока их смертные тела покоились под неусыпной охраной. Именно здесь Тиранда Шелест Ветра протрубила в Рог Кенария, чтобы пробудить Малфуриона во время Третьей войны. Даже сейчас кельи тесно связаны со Сном, хотя из глубоких туннелей начала исходить странная тревожная рябь: темный шепот тревожит изумрудный мир."}},faq={{q="Как добраться до Лунной поляны тем, кто не друид?",a="Если вас не переносят ритуальной магией во время сезонных событий, пешим путникам придется пройти через Крепость Древобрюхов — комплекс туннелей, соединяющий верхний Оскверненный лес, Зимние Ключи и Лунную поляну. Фурболги-древобрюхи ревностно охраняют этот проход и требуют, чтобы чужаки доказали свое доброжелательство, прежде чем дать безопасный проход.",al={"how to get to moonglade","getting to moonglade","moonglade entrance","как попасть на лунную поляну","путь на лунную поляну","вход на лунную поляну"}},{q="Почему Орда и Альянс могут мирно ходить здесь вместе?",a="Лунной поляной управляет Круг Кенария — орден, всецело преданный природе, а не политике. Стражи Лунной поляны в Ночной Гавани строго поддерживают нейтралитет и немедленно нападают на всякого, кто начинает насилие против тех, кто в хороших отношениях с Кругом.",al={"why is moonglade neutral","pvp in moonglade","can horde and alliance fight here","почему лунная поляна нейтральна","пвп на лунной поляне","могут ли орда и альянс сражаться здесь"}},{q="Для чего нужна Ночная Гавань?",a="Ночная Гавань — главное поселение Лунной поляны, жилище и рабочий центр Круга Кенария. Здесь находятся учителя, смотрители и святилища, где друиды-кальдораи и таурены совещаются о состоянии диких земель Азерота.",al={"nighthaven purpose","what is nighthaven","town in moonglade","назначение ночной гавани","что такое ночная гавань","город на лунной поляне"}},{q="Кто правит Лунной поляной в отсутствие Малфуриона Ярость Бури?",a="Хранитель Ремулос, могущественный сын полубога Кенария, оберегает Лунную поляну из Святилища Ремулоса. Вместе со старшими членами круга, такими как Дендрит Блеск Звезд, он ухаживает за священной землей и направляет усилия по исцелению мира.",al={"leader of moonglade","who leads cenarion circle","who is remulos","правитель лунной поляны","кто возглавляет круг кенария","кто такой ремулос"}},{q="Что покоится под Кельями Малфуриона?",a="Кельи — глубокие подземные залы, где друиды издавна погружались в долгое общение с Изумрудным Сном. В глубинных частях этих залов сохранились мощные проводники в Сон, хотя недавние возмущения говорят о том, что внутри начинают пробуждаться тревожные кошмары.",al={"barrow dens lore","stormrage barrow dens purpose","where druids sleep","кельи малфуриона история","назначение келий малфуриона","где спят друиды"}},{q="Почему у друидов есть особые маршруты полета из Ночной Гавани?",a="Мастер гиппогрифов Сильва Фил'навет и хозяин наездников на ветрокрылах Бантен Простор Ветра предлагают перелеты прямо в Деревню Рут'теран и Громовой Утес исключительно для друидов, чтобы орден мог легко перемещаться между священной рощей и родными землями своих рас.",al={"nighthaven flight masters","druid flight master moonglade","free flights in moonglade","распорядители полетов ночной гавани","распорядитель полетов друидов лунная поляна","бесплатные полеты на лунной поляне"}}},fp="9,441,15.590.0,18.541.0,29.540.1,43.302.0,57.286.0,34.276.0,53.241.0,45.278.0,58.264.0"}
P.entries["zone:mulgore"] = {n="Мулгор",s="Мулгор — родина предков тауренов, пышная защищенная долина изумрудных лугов, высоких плато и холмистых равнин у подножия Когтистых гор. Окруженное высокими природными горными стенами, это место было отвоевано, когда Кэрн Кровавое Копыто заключил союз с Ордой Тралла и изгнал разбойничьих кентавров. Сегодня это духовное и земельное сердце объединенных племен тауренов, которыми правят из великого города на плато — Громового Утеса.",h="Мулгор — родина предков тауренов, пышная защищенная долина изумрудных лугов, высоких плато и холмистых равнин...",kw={"bael'dun","baine bloodhoof","bloodhoof village","cairne bloodhoof","camp narache","earthmother","kodo","mulgore","red cloud mesa","red rocks","thunder bluff","venture co","раскопки бейл'дана","бейн кровавое копыто","деревня кровавого копыта","кэрн кровавое копыто","лагерь нараче","мать-земля","кодо","мулгор","плато красного облака","красные скалы","громовой утес","торговая компания"},ang={["class:Druid"]="Холмистые равнины и нетронутые рощи — одно из самых чистых природных убежищ Калимдора, где таурены-друиды изучают равновесие и дары природы.",["class:Hunter"]="Традиция Великой охоты живет на этих равнинах, где пумы, волки и дикие кодо испытывают умение и терпение каждого следопыта.",["faction:Horde"]="Мулгор — сердце духовности и земледелия Орды в центральном Калимдоре, связанное с народом Тралла кровной клятвой взаимной защиты.",["race:Tauren"]="Эта долина — ваш дом предков, возвращенный ценой жертв и единства. Охранять ее колодцы и очищать священные земли — основной долг перед Матерью-Землей."},sec={{t="Возвращенная земля",b="Поколениями таурены жили кочевниками, и агрессивные кентаврские отряды постоянно гнали их по центральным равнинам. Все изменилось, когда верховный вождь Кэрн Кровавое Копыто встретил Тралла и его изгнанных орков. Признав общие идеалы чести, шаманизма и силы, таурены заключили союз с юной Ордой. При помощи орков Кэрн сломил власть кентавров над краем и привел свой народ в Мулгор. Здесь впервые за века они построили постоянные поселения, увенчав высочайшие северные плато своей столицей — Громовым Утесом."},{t="Испытания Матери-Земли",b="Чтобы достичь зрелости в Мулгоре, нужно откликнуться на зов Великой охоты и почтить Мать-Землю. Молодые таурены начинают обучение на южной оконечности Плато Красного Облака, в Лагере Нараче, под руководством вождя Соколиного Ветра. Спускаясь в Золотые равнины и Деревню Кровавого Копыта, они проходят Обряды Матери-Земли: учатся общаться с духами предков, собирать местные травы и уважать стада кодо и долгоногов, на которых держится их цивилизация."},{t="Надвигающиеся тени",b="Несмотря на безмятежный вид, Мулгор сталкивается с растущими угрозами со всех сторон. Изгнанные со своих земель свинобразы закрепились в Ежевичной лощине и осквернили священные места погребения в Красных скалах. В горах гарпии Ярости Ветра охотятся на дичь, а гноллы Бледногривы нападают из скрытых пещер. Еще тревожнее внешняя эксплуатация: торговые гоблины из Торговой Компании начали осквернять священные колодцы и разрабатывать восточные холмы, а дворфы-исследователи из Бейл Модана основали Раскопки Бейл'дана, чтобы добывать древние артефакты титанов вопреки протестам таурен."}},faq={{q="Почему таурены окончательно поселились в Мулгоре?",a="Исторически таурены были кочевым народом и странствовали по Калимдору, преследуемые кентаврами-разбойниками. Объединившись с Ордой Тралла, Кэрн Кровавое Копыто обрел военную силу, необходимую, чтобы прогнать кентавров и вернуть родовую долину Мулгор. Они построили постоянные поселения, включая Деревню Кровавого Копыта и Громовой Утес, чтобы создать единую родину, где все племена тауренов смогут мирно процветать.",al={"why do tauren live here","tauren homeland history","why settle thunder bluff","почему таурены живут здесь","история родины тауренов","почему поселились в громовом утесе"}},{q="Как покинуть Мулгор пешком?",a="Мулгор полностью окружен неприступными горными стенами, кроме единственного юго-восточного прохода. Если идти по главной грунтовой дороге на восток мимо Деревни Кровавого Копыта и поста Морина Ловца Облаков, она ведет через этот горный коридор прямо в засушливые равнины Степей.",al={"mulgore exit","how to get to barrens from mulgore","mulgore road out","выход из мулгора","как добраться до степей из мулгора","дорога из мулгора"}},{q="Кто такая Торговая Компания и почему она здесь?",a="Торговая Компания — беспринципный торговый картель под управлением гоблинов, охотящийся за природными богатствами Калимдора. В Мулгоре она ведет добычу руды в восточных горах и заняла важные колодцы Громового Рога, Буйногривых и Заиндевевшего Копыта, оскверняя землю и угрожая водоснабжению региона.",al={"venture co in mulgore","why are there goblins here","venture co mine","торговая компания в мулгоре","почему здесь гоблины","шахта торговой компании"}},{q="Почему дворфы копают на землях тауренов?",a="Dwarves from the Bael Modan expedition have established the Bael'dun Digsite in Mulgore's western foothills. Driven by the Explorers' League to unearth relics of their Titan creators, they excavate tauren land without permission, ignoring tauren protests that such operations scar the Earthmother.",al={"baeldun digsite","why are dwarves in mulgore","bael dun","раскопки бейл'дана","почему дворфы в мулгоре","бейл дан"}},{q="Что такое Обряды Матери-Земли?",a="Обряды Матери-Земли — священная череда испытаний, которую проходит каждый молодой таурен по достижении зрелости. Эти задания проверяют охоту, выслеживание, общение через видения и знание природного равновесия, подтверждая преданность юного посвященного земле и древним традициям его народа.",al={"rites of earthmother","tauren maturity quest","rite of the earthmother","обряды матери-земли","квест зрелости тауренов","обряд матери-земли"}},{q="Кто правит Мулгором?",a="Верховный вождь Кэрн Кровавое Копыто правит всеми землями тауренов из столицы — Громового Утеса на северных плато. Его сын Бейн Кровавое Копыто управляет Деревней Кровавого Копыта и занимается повседневными делами нижних равнин под мудрым руководством Кэрна.",al={"mulgore leader","who is the chief of mulgore","cairne bloodhoof leader","правитель мулгора","кто вождь мулгора","кэрн кровавое копыто вождь"}}},fp="7,468,16.598.0,29.471.0,19.619.0,49.434.0,33.269.0,50.321.0,44.297.0,38.306.0,18.246.0"}
P.entries["zone:orgrimmar"] = {n="Оргриммар",s="Оргриммар — крепость-столица орков и бьющееся сердце Новой Орды Тралла. Укрепленный город высечен прямо в высоких красных каньонах северного Дуротара и служит памятником стойкости орков и непоколебимым убежищем для их союзников — троллей, тауренов и Отрекшихся.",h="Оргриммар — крепость-столица орков и бьющееся сердце Новой Орды Тралла.",kw={"cleft of shadow","drag","durotar","grommash hold","orgrim doomhammer","orgrimmar","ragefire chasm","thrall","valley of spirits","valley of strength","valley of wisdom","warchief","расселина теней","тракт","дуротар","крепость громмаш","оргрим молот рока","оргриммар","огненная пропасть","тралл","аллея духов","аллея силы","аллея мудрости","вождь"},ang={["class:Shaman"]="Тралл вернул шаманизм в самую основу руководства Орды; шаманы собираются в безмятежной Аллее Мудрости, чтобы изучать стихии и общаться с духами предков.",["class:Warlock"]="Чернокнижники находят здесь шаткое убежище: изгнанные в уединенную Расселину Теней, они действуют под бдительным взором Тралла и оттачивают темные искусства вдали от открытого осуждения.",["faction:Horde"]="Будучи высшим военным и культурным центром Новой Орды, Оргриммар предоставляет всем героям Орды оружейных мастеров, наставников классов, торговые кварталы и личную встречу с вождем Траллом.",["race:Orc"]="Для орков Оргриммар — это трудом завоеванная свобода от демонического оцепенения и лагерей для интернированных, их гордая родовая крепость на земле Дуротара.",["race:Troll"]="Потеряв Острова Черного Копья, тролли Черного Копья обрели надежное убежище рядом с орками и сделали Аллею Духов своим безопасным духовным домом."},sec={{t="Дом, высеченный из камня",b="После Третьей войны вождь Тралл привел орков к засушливым берегам Калимдора, чтобы построить родину, свободную от демонической порчи и человеческого рабства. Назвав суровый край Дуротаром в честь отца, Тралл основал Оргриммар в память о павшем наставнике, Оргриме Молоте Рока. Постройка города потребовала крови и пота: с помощью тауренов, троллей Черного Копья, гоблинов-инженеров и Защитника Рексара Орда отбросила наступавших кентавров, гарпий и свирепых громовых ящеров и укрепила твердыню в каньоне."},{t="Долины Орды",b="Оргриммар естественным образом защищен неприступными горами, которые прикрывают его и от чужеземных захватчиков, и от яростных острых ветров, что несутся по Дуротару. Поселение разделено на отдельные природные низины. Аллея Силы служит шумными городскими воротами и ведет дальше, к торговому базару Тракта. Тауренские друиды и шаманы собираются у тихих прудов Аллеи Мудрости, а охотники за тенями и знахари Черного Копья живут среди домов на сваях в Аллее Духов."},{t="Тени в красных скалах",b="Под воинской гордостью Аллеи Чести и высотами Крепости Громмаш скрывается более мрачная реальность. В подземной пещере, известной как Расселина Теней, чернокнижники и разбойники практикуют искусства, за которыми Тралл строго следит, но которые неохотно терпит. Еще глубже уходит Огненная пропасть — пылающий лабиринт вулканических тоннелей под дном каньона, где гнездятся темные культисты и подземные твари, угрожая крепости изнутри, из самого ее основания."}},faq={{q="Кто правит Оргриммаром?",a="Вождь Тралл правит городом из своей резиденции в Крепости Громмаш. Он возглавляет Новую Орду, делая упор на честь, выживание и шаманское наследие; ему близкими соратниками служат вождь Черного Копья Вол'джин и ветеран-полководец Варок Саурфанг.",al={"orgrimmar leader","who is in charge of orgrimmar","current warchief","лидер оргриммара","кто правит оргриммаром","нынешний вождь"}},{q="Почему город называется Оргриммар?",a="Тралл назвал город в честь Оргрима Молота Рока, легендарного бывшего Вождя, который разорвал хватку Совета Теней над Старой Ордой и перед смертью в бою передал Траллу свои латы и Молот Рока.",al={"orgrimmar name origin","who is orgrimmar named after","происхождение названия оргриммар","в честь кого назван оргриммар"}},{q="Кто живет в Оргриммаре, кроме орков?",a="Хотя город основали орки, он служит убежищем для племени троллей Черного Копья, которое занимает Аллею Духов, и принимает в Аллее Мудрости приезжих тауренских послов. После недавнего вступления в Орду здесь обосновалось и посольство Отрекшихся.",al={"races in orgrimmar","who lives here","trolls in orgrimmar","расы в оргриммаре","кто здесь живет","тролли в оргриммаре"}},{q="Что такое Расселина Теней?",a="Расселина Теней — мрачная пещерная трещина под скалами каньона рядом с Трактом. В ней расположены гильдии разбойников и чернокнижников города, и их запретная торговля и опасные демонические призывы скрыты от жилых кварталов.",al={"cleft of shadow","underground orgrimmar","orgrimmar warlock area","расселина теней","подземный оргриммар","зона чернокнижников оргриммара"}},{q="Какие угрозы есть внутри города?",a="Прямо под Расселиной Теней лежит Огненная пропасть — опасная сеть подземных вулканических трещин, кишащая троггами, пылающими элементалями и коварными чернокнижниками, которые стремятся подорвать власть Тралла из глубин.",al={"dangers in orgrimmar","ragefire chasm threat","orgrimmar cultists","опасности оргриммара","угроза огненной пропасти","культисты оргриммара"}},{q="Как добраться из Оргриммара на другие континенты?",a="Дирижабли, построенные гоблинами, причаливают к башням за главными воротами и регулярно летают через Великое море в Тирисфальские леса возле Подгорода, а также на юг, в Лагерь Гром'гол в Тернистой долине.",al={"orgrimmar zeppelins","getting to tirisfal from orgrimmar","travel from orgrimmar","дирижабли оргриммара","как добраться в тирисфаль из оргриммара","путь из оргриммара"}}},fp="9,300,26.525.0,20.512.0,23.464.1,20.231.0,32.212.0,36.284.0,28.241.0,35.230.0,53.203.0"}
P.entries["zone:ragefire"] = {n="Огненная пропасть",s="Огненная пропасть — сеть извилистых вулканических тоннелей прямо под столицей орков Оргриммаром. Вход в нее лежит в темных пещерах Расселины Теней; пропасть захвачена свирепыми троггами и демонической сектой культистов, известной как Пламенеющий Клинок. Если не остановить их, темные силы и подземные полчища угрожают самим основам молодого государства Орды.",h="Огненная пропасть — сеть извилистых вулканических тоннелей прямо под столицей орков Оргриммаром.",kw={"bazzalan","chasm","cleft of shadow","jergosh","neeru fireblade","orgrimmar","ragefire","rfc","searing blade","taragaman","баззалан","пропасть","расселина теней","жергош","нииру огненный клинок","оргриммар","огненная пропасть","пламенеющий клинок","тарагаман"},ang={["class:Warlock"]="Темные обряды и демонические книги, которыми пользуются Жергош Призыватель Духов и Баззалан, дают начинающим чернокнижникам возможность из первых рук увидеть темную магию Пламенеющего Клинка.",["faction:Horde"]="Очистка пропасти под Оргриммаром — важное испытание для молодых героев: оно позволяет доказать свою силу и защитить уязвимую столицу Орды.",["race:Tauren"]="Трагическая гибель Маура Зловещего Тотема от рук троггов Огненной пропасти делает охоту на подземных тварей делом чести и возмездия для Громового Утеса."},sec={{t="Подземная опасность",b="Под пылью и красными скалами Оргриммара лежит раскаленный лабиринт вулканических коридоров и лавовых ям. Пока орки-строители возводили свой новый дом наверху, из глубин начали выбираться агрессивные трогги Огненной пропасти. Магата Зловещий Тотем пыталась наладить с этими громилами дипломатические отношения от имени Громового Утеса, но ее посланника Маура Зловещего Тотема убили, что доказало: трогги уступают только силе."},{t="Пламенеющий Клинок",b="Куда опаснее простых троггов присутствие Пламенеющего Клинка — фанатичной ячейки, верной Совету Теней. Действуя из темных пещер рядом с потоками магмы, этот демонический культ замышляет полное уничтожение молодой Орды. Его возглавляют чернокнижник Жергош Призыватель Духов, хитрый сатир по имени Баззалан и жестокий страж Скверны Тарагаман Ненасытный, который руководит алтарем в озере лавы."},{t="Игра Вождя",b="Нииру Огненный Клинок, мнимый учитель чернокнижников, живущий у входа в пропасть в Расселине Теней, втайне служит местным главой Пылающего Клинка. Нииру отправляет героев Орды в глубины под видом проверок на верность, надеясь истребить слабых культистов и уничтожить сторонников Тралла. Однако Тралл прекрасно знает об обмане Нииру. Вождь использует эти вылазки, чтобы убирать опасных вожаков культа, таких как Жергош и Баззалан, а Нииру оставляет на месте, чтобы следить за более широкими замыслами Совета Теней."}},faq={{q="Где находится вход в Огненную пропасть?",a="Портал со входом находится внутри Оргриммара, в подземном районе под названием Расселина Теней. Он расположен рядом с палаткой учителя чернокнижников Нииру Огненного Клинка.",al={"rfc location","where is rfc","ragefire entrance","где огненная пропасть","где находится огненная пропасть","вход в огненную пропасть"}},{q="Почему под Оргриммаром живут трогги?",a="Трогги Огненной пропасти пробились вверх из подземных пустот под Дуротаром. Их внезапное появление под столицей считается серьезной опасностью, которую дипломатия не смогла устранить.",al={"ragefire troggs origin","why are there troggs here","orgrimmar troggs","происхождение троггов огненной пропасти","почему здесь трогги","трогги оргриммара"}},{q="Кто возглавляет культистов в пропасти?",a="Пламенеющим Клинком в пропасти руководят чернокнижник Жергош Призыватель Духов и сатир Баззалан, а поддерживает их призванный страж Скверны Тарагаман Ненасытный.",al={"rfc bosses","searing blade leaders","who rules ragefire","боссы огненной пропасти","лидеры пламенеющего клинка","кто правит огненной пропастью"}},{q="Что дает сюжету убийство Баззалана и Жергоша?",a="Убийство Баззалана и Жергоша ломает действующее руководство культистов Пламенеющего Клинка, затаившихся под Оргриммаром. Их смерть показывает стойкость Орды и позволяет Траллу сорвать планы поклонников демонов прямо под своим троном.",al={"bazzalan lore meaning","why kill bazzalan","hidden enemies outcome","смысл баззалана в истории","зачем убивать баззалана","скрытые враги"}},{q="Могут ли искатели приключений Альянса войти в Огненную пропасть?",a="Физически любой искатель приключений может пройти через портал, но чтобы добраться до Расселины Теней в глубине Оргриммара, члену Альянса придется уклоняться от стражи Орды высокого уровня и враждебных защитников по всему городу.",al={"can alliance do rfc","alliance in ragefire","может ли альянс в огненную пропасть","альянс в огненной пропасти"}},{q="Почему Тралл просто не казнит Нииру Огненного Клинка?",a="Тралл терпит приверженцев темной магии, собирающихся в Расселине Теней: он предпочитает держать их рядом, под своим бдительным взором, а не прогонять с глаз долой.",al={"thrall neeru fireblade","why let neeru live","тралл нииру огненный клинок","почему нииру жив"}}},fp="14,396,18.413.0,17.420.0,19.540.1,40.172.0,31.184.0,40.169.0,64.237.1,46.216.0,50.177.1"}
P.entries["zone:razorfenkraul"] = {n="Лабиринты Иглошкурых",s="Лабиринты Иглошкурых, укрытые на крайнем юге Степей, — исконная родина свинобразов Калимдора. Эти свирепые племена почитают густой лабиринт из гигантского терновника как священное место упокоения своего прародителя, павшего полубога Агамаггана. Сегодня Лабиринты стали агрессивно враждебными под тиранией матриарха свинобразов Чарлги Остробок, чьи темные дела угрожают всему региону.",h="Лабиринты Иглошкурых, укрытые на крайнем юге Степей, — исконная родина свинобразов Калимдора.",kw={"agamaggan","barrens","charlga","halmgar","kraul","quilboar","ramtusk","razorfen","razorflank","scourge","агамагган","степи","чарлга","халмгар","лабиринты","свинобразы","рамтуск","иглошкурые","остробок","плеть"},ang={["class:Shaman"]="Геомантия свинобразов искажает землю и стихии вокруг крови Агамаггана, ярко показывая первобытные шаманские силы, используемые со свирепыми намерениями.",["faction:Horde"]="Подавление агрессии в Лабиринтах необходимо, чтобы защитить обозы со снабжением и молодые поселения на южных просторах Степей.",["race:Tauren"]="Свинобразы давно оспаривают границы Мулгора, а их осквернение земли темными союзами делает очищение Лабиринтов жизненно важным делом защиты племени.",["race:Undead"]="Аптекари Подгорода проявляют острый интерес к странным реагентам, гуано летучих мышей и слухам о вторжениях Плети, найденным в колючих зарослях."},sec={{t="Кровь Кабаньего бога",b="Десять тысяч лет назад, во время апокалиптической Войны Древних, огромный дикий бог Агамагган бросился в бой против Пылающего Легиона. Великий вепрь в конце концов пал в битве, но его жертва сохранила жизнь на Азероте. Предания гласят, что там, где его кровь впитывалась в землю, вырастали огромные покрытые шипами лозы, образуя густые оборонительные лабиринты на южных равнинах. Свинобразы, почитая Агамаггана как божественного предка, объявили эти исполинские заросли своими святыми землями, а величайшие из них назвали Иглошкурыми."},{t="Амбиции старой ведьмы",b="Лабиринтами Иглошкурых железной рукой правит старая ведьма Чарлга Остробок. Под ее деспотичным руководством шаманистические свинобразы оставили традиционные стычки за территории и ведут агрессивную согласованную войну против соперничающих племен, торговых путей региона и молодых поселений Орды. Что еще хуже, тревожные слухи и донесения разведчиков говорят о нежити, бродящей возле зарослей. Опасаются, что Чарлга начала переговоры с посланниками грозной Плети, желая с помощью запретного некромантства усилить свирепость своего племени."}},faq={{q="Что такое Лабиринты Иглошкурых?",a="Лабиринты Иглошкурых — древняя подземная сеть огромных колючих лоз на юге Степей. Это духовная родина и оплот свинобразов, считающих запутанный лабиринт своим исконным домом.",al={"what is rfk","explain razorfen kraul","razorfen overview","что такое лабиринты иглошкурых","описание лабиринтов иглошкурых","обзор иглошкурых"}},{q="Как появились гигантские шипы?",a="Огромные заросли проросли из земли десять тысяч лет назад, во время Войны Древних, прямо из крови павшего полубога-вепря Агамаггана.",al={"why are there giant thorns","where did the brambles come from","agamaggan thorns","почему гигантские шипы","откуда взялись заросли","шипы агамаггана"}},{q="Кто правит Лабиринтами Иглошкурых?",a="Лабиринтами правит Чарлга Остробок, безжалостная ведьма-свинобраз и шаманка, которая командует племенем Иглошкурых и организует нападения на соседние деревни и путников.",al={"who is the boss of rfk","charlga razorflank","crone of the kraul","кто босс лабиринтов иглошкурых","чарлга остробок","старая ведьма лабиринтов"}},{q="Почему Орда беспокоится о Лабиринтах Иглошкурых?",a="Помимо постоянных набегов свинобразов на молодые поселения в Степях, разведчики Орды заметили нежить, крадущуюся вокруг зарослей, что вызывает ужасные опасения: Чарлга заключает союз с Плетью.",al={"why does the horde care","horde rfk interest","barrens threat","почему орду это волнует","интерес орды к лабиринтам","угроза степям"}},{q="Почему силы Альянса интересуются Лабиринтами?",a="Агрессивная экспансия племени Чарлги угрожает форпостам возле Фераласа и Тысячи Игл, и командиры и разведчики Альянса в Таланааре стремятся убить старую ведьму, чтобы стабилизировать границу.",al={"alliance quests rfk","why alliance go here","thalanaar quest","задания альянса в лабиринтах иглошкурых","почему альянс идет сюда","задание таланаар"}},{q="Что означает для сюжета победа над заклинательницей земли Халмгар?",a="Победа над заклинательницей земли Халмгар, редкой и влиятельной геомантессой в глубине зарослей, наносит удар по жречеству свинобразов, изменяющему землю. Лишив Лабиринты столь могущественных призывателей стихий, вы нарушите оборонительные укрепления Чарлги Остробок и помешаете свинобразам управлять священным терновником Агамаггана.",al={"what happens after earthcaller halmgar dies","earthcaller halmgar lore","halmgar defeated","что будет после смерти халмгар","история заклинательницы земли халмгар","халмгар побежден"}}},fp="14,417,21.573.0,20.556.1,23.229.0,34.186.0,25.174.0,48.203.0,48.207.0,59.348.0"}
P.entries["zone:riverglades"] = {n="Лесоречье",s="Лесоречье — спорная речная долина к востоку от Пылающих степей и Бесплодных земель, исторически входившая в Королевство Штормград. Захваченное Старой Ордой в Первую войну и почти брошенное короной, оно остается полем боя: местные человеческие лоялисты сражаются с современными аванпостами Орды и дикой природой. На юго-западе оно граничит с Красногорьем, на юге — с Болотом Печали, а через море лежит напротив Танариса.",h="Лесоречье — спорная речная долина к востоку от Пылающих степей и Бесплодных земель, исторически входившая в...",kw={"blackrock pass","brotherhood of the horse","demar brant","farholde keep","krol'dok stronghold","powderfuse port","redridge pass","riverglades","rog'mar","sunnyglade","перевал черной горы","конное братство","демар брант","крепость фархолд","крепость крол'док","пороховой порт","перевал красногорья","лесоречье","рог'мар","светогладь"},ang={["faction:Alliance"]="Солдаты Альянса в Лесоречье видят старые раны открытыми: остатки Конного Братства ведут безвестный поход, чтобы вернуть земли, брошенные Штормградом в Первую войну.",["faction:Horde"]="Для Орды создание аванпостов вроде Рог'мара обеспечивает надежный плацдарм на побережье и не дает ослабить давление на старые людские твердыни к востоку от Красногорья.",["race:Human"]="В Светоглади люди видят трагическую главу собственной истории — напоминание о тяжелой цене, которую Первая война взяла с восточных рубежей их королевства."},sec={{t="Забытое пограничье",b="Лесоречье, исторически часть Королевства Штормград, обратилось в руины во время Первой войны, когда через него прошла Старая Орда. Главное поселение, Светогладь, было разграблено орками, которые пощадили лишь его башню магов, чтобы изучать человеческое колдовство, а уцелевших горожан обратили в рабство. Солдаты Штормграда попытались освободить пленных и отстроить поселение, но королевство в итоге сочло всю долину потерянной и направило силы на защиту коренных земель. Долгие годы регион оставался почти без официальной поддержки короны."},{t="Борьба за Фархолд",b="Хотя высшее командование Штормграда оставило их, защитники-люди так и не сдали родную землю. Под началом рыцаря-командора Демара Бранта из легендарного Конного Братства уцелевшие лоялисты удерживают Крепость Фархолд как оплот против дикой природы и враждебных захватчиков. Тем временем современная Орда держит неподалеку сильные аванпосты, такие как Рог'мар и Болдер'ок, и древний конфликт за эти земли продолжает тлеть."},{t="География и путешествия",b="Лесоречье тянется вдоль побережья Зловещего моря и окружено горами и извилистыми водными путями. Пешие путники могут пройти на запад через Перевал Черной горы в Пылающие степи, свернуть на юго-запад через Перевал Красногорья к Красногорью, отправиться на юг в Болото Печали или двинуться на северо-запад мимо Сумеречного покрова в Бесплодные земли. На побережье Пороховой порт обеспечивает морское сообщение, напрямую связывая его через океан с Портом Картеля в Танарисе."}},faq={{q="Что такое Лесоречье?",a="Лесоречье — спорная область к востоку от Бесплодных земель и Пылающих степей, выходящая к Зловещему морю. Когда-то это была процветающая территория Штормграда, а теперь это действующий передовой рубеж, за который борются Альянс в Крепости Фархолд и Орда в Рог'маре.",al={"riverglades overview","what is this zone","about riverglades","обзор лесоречья","что это за зона","о лесоречье"}},{q="Что случилось со Светогладью?",a="Светогладь была разграблена и уничтожена Старой Ордой в Первую войну. Орки захватили уцелевших жителей в рабство и сохранили местную башню магов, чтобы разгадать человеческую магию. Солдаты Штормграда освободили пленных и пытались отстроить поселение, но королевство в итоге оставило эти земли, сосредоточившись на западных границах.",al={"sunnyglade history","fall of sunnyglade","what happened to the town","история светоглади","падение светоглади","что случилось с городом"}},{q="Кто контролирует Крепость Фархолд?",a="Крепость Фархолд удерживают лоялисты Альянса под началом рыцаря-командора Демара Бранта из Конного Братства. Его люди годами борются за возвращение Лесоречья после того, как Штормград списал эти земли как потерянные.",al={"who leads farholde","alliance in riverglades","brotherhood of the horse","кто командует фархолдом","альянс в лесоречье","конное братство"}},{q="Как добраться до Танариса из Лесоречья?",a="Береговой корабль регулярно ходит между Пороховым портом на восточном берегу Лесоречья и Портом Картеля в Танарисе, обеспечивая прямое морское сообщение через море.",al={"boat to tanaris","powderfuse port boat","how to get to tanaris","корабль в танарис","корабль порохового порта","как добраться до танариса"}},{q="Какие перевалы ведут в другие зоны?",a="Вы можете отправиться на юго-запад через Перевал Красногорья в Красногорье или пройти на юг прямо к Болоту Печали. На западе Перевал Черной горы ведет мимо Щетинистых холмов в Пылающие степи, а тропы севернее Сумеречного покрова выводят прямо в Бесплодные земли.",al={"how to get to redridge","passes from riverglades","exits from riverglades","как добраться до красногорья","перевалы из лесоречья","выходы из лесоречья"}},{q="Что такое Крепость Крол'док?",a="Крепость Крол'док — укрепленный подземный комплекс в Лесоречье, главный оплот враждебной силы на спорной территории.",al={"kroldok stronghold","riverglades dungeon","what dungeon is here","крепость крол'док","подземелье лесоречья","какое здесь подземелье"}}},fp="11,442,22.570.0,25.482.0,20.493.0,24.255.0,28.330.0,27.236.0,46.172.0,34.289.0,28.141.0"}
P.entries["zone:ruinsoflordaeron"] = {n="Руины Лордерона",s="Руины Лордерона, расположенные прямо над подземным Подгородом, — опустевшие останки некогда могучего северного королевства людей. После падения перед Плетью и принцем Артасом во время Третьей войны уличные мостовые и разбитые площади теперь кишат бродячими чудовищами, мстительными призраками и мерзкими экспериментаторами. И Альянс, и Орда отправляют экспедиции в эту оскверненную цитадель, чтобы вернуть реликвии прошлого или истребить ужасы над столицей Отрекшихся.",h="Руины Лордерона, расположенные прямо над подземным Подгородом, — опустевшие останки некогда могучего...",kw={"bjork","lordaeron captain","new plague","rath'mael","ruins of lordaeron","the abandoned","the baron","tirisfal glades","undercity","viktor the vile","witherfang","бьорк","капитан лордерона","новая чума","рат'маэль","руины лордерона","брошенный","барон","тирисфальские леса","подгород","виктор мерзкий","иссохший клык"},ang={["class:Paladin"]="Лордерон был колыбелью Рыцарей Серебряной Длани; идти по его оскверненным залам, чтобы уничтожить ужасы и упокоить неспокойных капитанов, — торжественный долг Света.",["faction:Alliance"]="Поход в Лордерон позволяет Альянсу ударить у порога столицы Отрекшихся и принести справедливость и покой духам убитых северных братьев.",["race:Human"]="Искатели приключений из числа людей видят в разрушенной столице священную землю, похищенную предательством, и стремятся вернуть утраченные реликвии и почтить павших сородичей.",["race:Undead"]="Для Отрекшихся верхние руины — их прежний дом и вечное кладбище. Зачистка обеспечивает безопасность их парадного входа и снабжает аптекарей компонентами для создания Новой чумы."},sec={{t="Двор павшей империи",b="Столица когда-то была жемчужиной Восточных королевств, резиденцией короля Теренаса Менетила II и бьющимся сердцем человеческой цивилизации. Когда принц Артас вернулся из Нордскола, он убил своего отца в тронном зале и натравил нежить на горожан. Сегодня, пока Отрекшиеся обитают в катакомбах Подгорода внизу, поверхностные руины остаются забытой сумеречной зоной. Разрушенные арки и поросшая сорняками брусчатка укрывают диких зверей, таких как Иссохший Клык, и безумные остатки прошлого."},{t="Мучения и мор",b="Опасности в разрушенных землях не ограничиваются неупокоенными мертвецами. Аптекари и зловещие личности вроде Виктора Мерзкого испытывают новые чумы в тени, а искаженные эксперименты вроде Брошенного свободно бродят вокруг. Яростные духи, такие как Рат'маэль, и проклятые слуги, такие как Барон, бродят по обрушенным коридорам, обреченные на вечные муки, и нападают на любого живого или мертвого, кто встанет у них на пути."},{t="Призраки королевской стражи",b="Среди самых пронзительных опасностей верхних руин — призрачные остатки защитников города, кульминацией которых становится появление призрачного капитана Лордерона. Все еще держась за свои разбитые клятвы, эти привидения видят захватчиков в каждом, кто приближается к трону. Упокоение капитана и его солдат приносит горько-сладкое завершение непрерывному бдению, длящемуся со дня падения столицы."}},faq={{q="Где находится подземелье «Руины Лордерона»?",a="Подземелье расположено прямо на поверхностных уровнях Столицы в Тирисфальских лесах, над сетью входов, ведущих вниз в столицу Отрекшихся — Подгород.",al={"ruins of lordaeron location","where is lordaeron dungeon","undercity dungeon entrance","руины лордерона расположение","где подземелье лордерон","вход в подгород подземелье"}},{q="Почему и Орда, и Альянс интересуются этим местом?",a="Для Альянса поход в Лордерон — священное паломничество, чтобы вернуть утраченные семейные реликвии, собрать королевские гербы и даровать последний покой павшим предкам. Для Орды, и в особенности для Отрекшихся, зачистка верхних руин необходима, чтобы защитить окрестности Подгорода и получить образцы для исследований новой чумы Королевского фармацевтического общества.",al={"why go to lordaeron ruins","alliance quests lordaeron","horde quests lordaeron","зачем идти в руины лордерона","задания альянса лордерон","задания орды лордерон"}},{q="Кто такой Виктор Мерзкий?",a="Виктор Мерзкий — одна из злобных личностей, пользующихся беззаконием руин: он ставит мерзкие эксперименты и способствует гнойной порче, из-за которой верхняя столица кишит искаженными тварями.",al={"viktor the vile lore","who is viktor the vile","виктор мерзкий история","кто такой виктор мерзкий"}},{q="Что такое «Брошенный», которого встречают в руинах?",a="Брошенный — гротескное чудовище из нежити, оставленное в руинах. Как и многие сшитые из частей создания, появившиеся во время и после завоевания Плети, он бесцельно бродит по заброшенным залам и нападает на все, что встретит.",al={"the abandoned boss","who is the abandoned","брошенный босс","кто такой брошенный"}},{q="Что значит победа над капитаном Лордерона для истории?",a="Победа над призрачным капитаном Лордерона освобождает высокопоставленного королевского защитника от вечного, сводящего с ума долга. Связанный честью со времен первой резни Плети, капитан годами охранял разрушенное королевство от всех приближавшихся. Упокоение капитана разрывает мучительный круг призрачной службы и позволяет забрать его окровавленный знак отличия.",al={"defeating lordaeron captain","lordaeron captain significance","what happens when captain dies","победа над капитаном лордерона","значение капитана лордерона","что будет если капитан умрет"}},{q="Отделены ли Руины Лордерона от Подгорода?",a="Да. Пока Отрекшиеся живут в пещерах Подгорода внизу, поверхностные руины остаются активной зоной боев, захваченной беспокойными призраками, дикими хищниками и опасными экспериментами, которых Отрекшиеся не уничтожили полностью.",al={"is undercity in this dungeon","ruins vs undercity","подгород в этом подземелье","руины или подгород"}}},fp="18,495,27.507.0,22.431.0,25.419.1,48.191.0,61.370.0,23.229.0,49.228.0,61.375.1,54.232.0"}
P.entries["zone:scarlet"] = {n="Монастырь Алого ордена",s="Монастырь Алого ордена, расположенный в северо-восточных холмах Тирисфальских лесов, когда-то был мирным убежищем и центром знаний Церкви Священного Света. После падения Лордерона его захватил и сильно укрепил Алый орден как свою главную передовую базу на западе. Теперь это огромная крепость из четырех крыльев, где фанатичные приверженцы тренируются, пытают пленников и ведут непримиримую войну против всех чужаков.",h="Монастырь Алого ордена, расположенный в северо-восточных холмах Тирисфальских лесов, когда-то был мирным...",kw={"armory","cathedral","doan","graveyard","herod","library","mograine","scarlet crusade","scarlet monastery","tirisfal glades","whitemane","оружейная","собор","доан","кладбище","герод","библиотека","могрейн","алый орден","монастырь алого ордена","тирисфальские леса","вайтмейн"},ang={["class:Mage"]="В крыле Библиотеки хранятся редкие исторические и богословские фолианты, которые охраняет Чародей Доан, бывший ученый Даларана, перешедший на сторону Алого ордена.",["class:Paladin"]="Монастырь служил священной семинарией, где тренировались и молились первые паладины Серебряной Длани, поэтому его падение в алый фанатизм — печальное напоминание о том, как преданность может превратиться в безумие.",["class:Priest"]="Изначально посвященные архиепископу Алонсусу Фаолу и Церкви Священного Света, его величественные часовни показывают, что священная сила все еще может находиться в руках смертных, искаженных ненавистью и жаждой мести.",["race:Undead"]="Монастырь Алого ордена на границе Тирисфальских лесов представляет собой смертельную угрозу для Отрекшихся: он засылает шпионов в Могильник и пытает плененную нежить в своих темницах."},sec={{t="Павшее убежище",b="До Третьей войны монастырь был гордой обителью лордеронского духовенства и семинарией для начинающих паладинов Серебряной Длани, любимой самим архиепископом Алонсусом Фаолом. После опустошения Плетью уцелевшие воины ордена очистили залы от остатков нежити и пауков и превратили тихие архивы и дворы в укрепленный гарнизон. Охваченный паранойей и горем, Алый орден стал считать всех чужаков — живых или мертвых, людей или нет — разносчиками чумы, которых нужно очистить огнем."},{t="Четыре крыла",b="За Главным вестибюлем монастыря находятся четыре отдельных части. Кладбище — оскверненная открытая терраса, где павшие воины ордена восстают мерзкой нежитью, а палачи вырывают признания у пленников. Библиотека хранит драгоценные богословские тексты и исторические фолианты под охраной мага-отступника, Чародея Доана, и его гончих. Оружейная — тренировочная площадка, где мастера оружия Алого ордена, такие как Герод, превращают фанатичных новобранцев в несокрушимых воинов. Глубже всего стоит Собор — величественное сердце крепости, откуда руководство ордена направляет свой крестовый поход по оскверненному северу."},{t="Падение верховного инквизитора",b="Внутренним святилищем Собора командуют командир Могрейн из Алого ордена и истинная хозяйка монастыря, верховный инквизитор Салли Вайтмейн. Победа над Вайтмейн наносит решающий удар по оперативному командованию ордена в Тирисфальских лесах. Ее способность направлять ослепляющий Свет и воскрешать павших бойцов делала гарнизон непобедимым в глазах его приверженцев. Ее смерть разрушает ореол божественного мандата, питавший фанатизм монастыря, показывает смертность руководства ордена и сильно ослабляет его кампанию против Отрекшихся и соседних земель."}},faq={{q="Почему Алый орден враждебен к живым искателям приключений из Альянса?",a="Орден поддался крайнему безумию и паранойе. В их глазах любой, кто не носит их багряный табард, — потенциальный разносчик чумы Плети. Они больше не различают друзей и врагов и считают всех чужаков оскверненными существами, которых нужно очистить, прежде чем они распространят порчу.",al={"why do scarlets attack humans","scarlet crusade hostile alliance","why are they mad","почему алый орден атакует людей","алый орден враждебен альянсу","почему они безумны"}},{q="Что произойдет, если вы победите верховного инквизитора Вайтмейн?",a="Победа над верховным инквизитором Вайтмейн обезглавливает западное военное руководство Алого ордена. Как духовный лидер монастыря, она своими чудесными силами воскрешения поддерживала боевой дух войск и заставляла командира Могрейна из Алого ордена сражаться рядом с ней. Ее смерть лишает орден сильнейшей жрицы в Тирисфальских лесах, оставляет гарнизон в смятении и сильно снижает его угрозу для окрестностей.",al={"what does killing whitemane mean","whitemane defeated lore","cathedral ending","что значит убийство вайтмейн","победа над вайтмейн история","концовка собора"}},{q="Что такое Алый ключ и где его найти?",a="Алый ключ хранится в глубине крыла Библиотеки монастыря, в сундуке Чародея Доана за его личным кабинетом. Он необходим, чтобы открыть внешние врата крыльев Оружейной и Собора.",al={"where is scarlet key","how to unlock armory and cathedral","monastery key","где алый ключ","как открыть оружейную и собор","ключ монастыря"}},{q="Почему Чародей Доан находится в Монастыре Алого ордена?",a="Чародей Доан был одаренным человеком-волшебником из Даларана, оставившим собратьев из Кирин-Тора ради Алого ордена. Ища уединения, чтобы изучать редкие рукописи и овладеть мощной магией огня и тайной магией, он взял под контроль обширное крыло Библиотеки монастыря.",al={"who is arcanist doan","doan lore","mage in library","кто такой чародей доан","доан история","маг в библиотеке"}},{q="Кто был Александрос Могрейн и как он связан с этим местом?",a="Александрос Могрейн, знаменитый Испепелитель и бывший предводитель Серебряной Длани в Лордероне, молился и тренировался в монастыре в юности. После Третьей войны он сделал его передовой базой против нежити; его сын Рено теперь командует Собором вместе с верховным инквизитором Вайтмейн.",al={"mograine monastery history","ashbringer monastery","renault mograine father","могрейн история монастыря","испепелитель монастырь","рено могрейн отец"}},{q="Чем крыло Кладбища так отличается от остальной части монастыря?",a="Пока остальной монастырь сохраняет внешний вид безупречной набожности, на Кладбище фанатизм ордена гниет изнутри. Здесь находятся жестокие пыточные камеры Дознавателя Вишаса, а заброшенные склепы и неупокоенных мертвецов собирают или используют павшие заклинатели вроде Волшебника Крови Талноса.",al={"why is graveyard undead","thalnos lore","interrogator vishas","почему на кладбище нежить","талнос история","дознаватель вишас"}}},fp="17,466,18.553.0,14.615.0,31.585.1,66.315.0,55.420.1,46.238.0,46.273.0,57.303.1,74.330.0"}
P.entries["zone:searinggorge"] = {n="Тлеющее ущелье",s="Тлеющее ущелье — выжженный пустынный каньон на юге Каз Модана, граничащий на юге с Черной горой. Когда-то это была цветущая часть Красногорья, но более двух столетий назад ее опустошил апокалиптический призыв Рагнароса Повелителя Огня. Сегодня ущелье усиленно разрабатывает клан Черного Железа, чьи обширные рабские шахты в Котловане пристально отслеживает отколовшееся Братство Тория.",h="Тлеющее ущелье — выжженный пустынный каньон на юге Каз Модана, граничащий на юге с Черной горой.",kw={"blackrock mountain","cauldron","dark iron clan","ragnaros","searing gorge","slag pit","stonewrought pass","thorium brotherhood","thorium point","черная гора","котлован","клан черного железа","рагнарос","тлеющее ущелье","шлаковая яма","подгорная тропа","братство тория","лагерь братства тория"},ang={["class:Rogue"]="Разбойники с опытом взлома замков — желанные гости здесь: они могут обойти запертые ворота Подгорной тропы, соединяющие Лок Модан с ущельем напрямую.",["faction:Alliance"]="Альянс держит ворота Подгорной тропы запертыми, чтобы изолировать дворфов Черного Железа от мирных поселений дворфов в Лок Модане, хотя отважным искателям приключений разрешено проникать в ущелье.",["faction:Horde"]="Используя Каргат как опорную базу, Орда проложила сухопутный путь в ущелье, чтобы собирать сведения о Черной горе и срывать операции Черного Железа в Каз Модане.",["profession:Mining"]="Вулканический ландшафт и глубокие выработки Шлаковой Ямы делают Тлеющее ущелье одним из главных мест добычи богатых жил мифрила, истинного серебра и желанной руды Черного Железа.",["race:Dwarf"]="Для дворфов Стальгорна Тлеющее ущелье — горькое напоминание о Войне трех молотов и катастрофическом безрассудстве клана Черного Железа, чьи разработки теперь угрожают южным подступам Каз Модана."},sec={{t="Выжженная пустошь",b="До Войны трех молотов земля, где теперь находится Тлеющее ущелье, была зеленым холмистым горным краем, связанным с хребтом Красногорья. Этот цветущий пейзаж исчез более двухсот тридцати лет назад, когда заклинатель-тан Тауриссан, отчаянно пытаясь переломить ход поражения, призвал Рагнароса из глубин под миром. Катастрофическое появление Повелителя огня раскололо землю, подняло Черную гору, превратило величественный город Черного Железа Тауриссан в дымящиеся руины, а северную долину сожгло до растрескавшейся равнины из пепла, серы и вулканического стекла."},{t="Котлован и Шлаковая Яма",b="Лишившись старой столицы, дворфы Черного Железа захватили безлюдное ущелье в поисках сырья для своей военной машины. В центре долины лежит Котлован — колоссальный открытый карьер, уходящий глубоко в камень. В его нижних недрах расположена Шлаковая Яма — жестокий подземный рудничный комплекс. Здесь надсмотрщики Черного Железа и неповоротливые боевые големы гонят пленных врагов на изнурительный рабский труд: из раскаленной породы добывают железо, мифрил и редкие залежи руды Черного Железа, постоянно рискуя попасть под лавовые выбросы или нападение бродячих зверей."},{t="Братство Тория и спорные пути",b="На северных утесах над карьером стоит Лагерь Братства Тория — укрепленный форпост Братства Тория. Отделившись от своих сородичей в Черной горе, эти мастера-ремесленники предоставляют нейтральный приют путникам, готовым подрывать дела Черного Железа или снабжать братство редкими плавильными компонентами. Доступ в само ущелье строго ограничен: Альянс держит Подгорную тропу запертой за тяжелыми железными воротами со стороны Лок Модана, а экспедиции Орды из соседнего Каргата проложили узкую тропу через восточные Бесплодные земли, чтобы разведать местность."}},faq={{q="Почему Тлеющее ущелье выжжено и покрыто пеплом?",a="Более двухсот тридцати лет назад, во время Войны трех молотов, заклинатель-тан Черного Железа Тауриссан попытался призвать сверхъестественную силу, чтобы избежать поражения. Вместо этого он призвал Рагнароса Повелителя Огня. Катастрофическое извержение раскололо южный хребет Красногорья, создало вулкан Черной горы и испепелило окрестные долины, превратив их в Тлеющее ущелье и Пылающие степи.",al={"why is it burnt","searing gorge lore","how was searing gorge created","почему сожжено","история тлеющего ущелья","как появилось тлеющее ущелье"}},{q="Кто такие дворфы, живущие в Лагере Братства Тория?",a="Они принадлежат к Братству Тория — независимой фракции дворфов Черного Железа, разорвавших связи со своими имперскими сородичами под Черной горой. Из своего лагеря они работают мастерами-кузнецами и измыслителями, обмениваясь знаниями и секретами ремесла с любым путником, помогающим им против сил Черного Железа внизу.",al={"thorium point dwarves","who is thorium brotherhood","thorium brotherhood lore","дворфы лагеря братства тория","кто такое братство тория","история братства тория"}},{q="Что происходит в Котловане?",a="Котлован — огромный открытый карьер, подконтрольный клану Черного Железа; в нем находится подземная Шлаковая Яма. Надсмотрщики Черного Железа и боевые големы используют пленников как рабов для добычи ценных руд, в том числе залежей руды Черного Железа, для великих кузниц внутри Черной горы.",al={"what is the cauldron","the slag pit lore","what are dark irons mining","что такое котлован","шлаковая яма история","что добывают дворфы черного железа"}},{q="Как попасть в Тлеющее ущелье из Лок Модана?",a="Проход из Лок Модана через Подгорную тропу перекрыт тяжелыми запертыми воротами, которые охраняют горные пехотинцы Стальгорна. Путники должны либо получить Ключ от Тлеющего ущелья, выполнив официальное задание для куратора Ториуса, либо найти умелого разбойника, который взломает замок, либо обойти ворота, выбрав открытую тропу к югу от Каргата в Бесплодных землях.",al={"stonewrought pass gate","how to open searing gorge door","key to searing gorge","ворота подгорной тропы","как открыть дверь в тлеющее ущелье","ключ от тлеющего ущелья"}},{q="Почему Орда интересуется Тлеющим ущельем?",a="Из соседней крепости Каргат в Бесплодных землях командиры Орды проложили горный проход в ущелье, чтобы следить за передвижениями войск Черного Железа и обеспечить тактические пути к Черной горе, имеющей огромное стратегическое значение.",al={"why is horde here","kargath gorge connection","horde presence","почему здесь орда","каргат и ущелье","присутствие орды"}},{q="Есть ли в Тлеющем ущелье подземелья или входы в рейды?",a="Самих порталов в подземелья в ущелье нет, но южный вход ведет прямо в Черную гору. В ней находятся Глубины Черной горы, Вершина Черной горы и глубокие проходы в Огненные Недра.",al={"searing gorge instances","dungeons in searing gorge","where is molten core","подземелья тлеющего ущелья","данжи в тлеющем ущелье","где огненные недра"}}},fp="13,419,20.591.0,29.570.0,39.591.0,51.408.0,44.334.0,33.304.0,50.349.0,45.248.0,62.233.0"}
P.entries["zone:shadowfang"] = {n="Крепость Темного Клыка",s="Крепость Темного Клыка, мрачный оплот отступника из Кирин-Тора, верховного мага Аругала, возвышается на неприступных утесах над Деревней Погребальных Костров. Некогда это было родовое поместье барона Сребролена, а теперь цитадель кишит дикими воргенами и измученными призраками убитых защитников. Для искателей приключений в южном Серебряном бору крепость — темное средоточие звериной напасти, пожирающей край.",h="Крепость Темного Клыка, мрачный оплот отступника из Кирин-Тора, верховного мага Аругала, возвышается на...",kw={"arugal","fenrus","pyrewood","sfk","shadowfang","silverlaine","silverpine","springvale","worgen","аругал","фенрус","погребальные костры","крепость темного клыка","темный клык","сребролен","серебряный бор","ручьедол","воргены"},ang={["class:Mage"]="Трагедия Темного Клыка — мрачное предостережение о том, что бывает, когда маг Кирин-Тора вмешивается в призыв из иных измерений, выходящий из-под смертного контроля.",["class:Paladin"]="Неупокоенный дух командира Ручьедола — скорбное напоминание о павших защитниках Серебряной Длани, чьи священные клятвы были искажены смертью.",["class:Warlock"]="Темные энергии, демоны Бездны и злая волшба внутри крепости привлекают чернокнижников, желающих вернуть древние реликвии вроде Сферы Соран'рука.",["faction:Horde"]="Отрекшиеся видят в наступающих стаях Аругала непосредственную угрозу своей молодой территории в Серебряном бору, поэтому крепость — первоочередная цель для Стражей смерти и Королевского фармацевтического общества."},sec={{t="Падение рода Сребролен",b="До того как ее окутал кошмар, Темный Клык был известен как крепость Сребролен — дворянская резиденция, верная лордам Гилнеаса, с гарнизоном под началом набожного командира Ручьедола. Когда во время Третьей войны Плеть прокатилась по Лордерону, маги Даларана гибли толпами. Отчаянно пытаясь остановить восстающих мертвецов, верховный маг Аругал пренебрег руководством Кирин-Тора и углубился в исследования мага Ура, призвав воргенов из иного измерения, чтобы переломить ход войны. Призванные звери растерзали нежить, но быстро вышли из-под всякого смертного контроля, прорвались в южный Серебряный бор и захватили цитадель. Барон Сребролен и весь его двор были перебиты и обречены бродить по каменным залам рядом с дикими чудовищами, захватившими их дом."},{t="Дети Аругала",b="Сломленный виной и безумием, Аругал укрылся за обагренными кровью стенами, усыновил прожорливых волколюдей как любимых «детей» и нарек замок Крепостью Темного Клыка. В глубине каменных логовищ процветают волчьи стаи и теневые псы под присмотром таких наставников, как Мастер волков Нандос, а над ними надзирает огромный волкоподобный зверь Аругала — Фенрус Пожиратель. За стенами проклятие не остановилось: соседняя Деревня Погребальных Костров остается в плену жуткого ночного круговорота — ее жители днем ходят людьми, а под луной охотятся как свирепые воргены, неразрывно связанные с безумным верховным магом на высотах."},{t="Удар Отрекшихся",b="Осознав смертельную угрозу, которую Аругал представляет для их владений в Серебряном бору, леди Сильвана Ветрокрылая отправила Королевское фармацевтическое общество и элитных Стражей смерти искоренить источник проклятия воргенов. Отряды проникновения понесли тяжелые потери в подземельях, но герои Орды, откликнувшиеся на призыв из Гробницы, в конце концов прорываются в высочайшую башню. Победа над верховным магом положит конец владыке стаи, разорвав разум, управляющий распространением зверей по глуши, а его голова станет доказательством мести Лордерона."}},faq={{q="Что произойдет, если победить верховного мага Аругала?",a="Убийство Аругала обезглавливает силу, управляющую стаями воргенов в южном Серебряном бору. Искатели приключений из Орды доставляют его отрубленную голову Далару Ткачу Рассвета в Гробницу по приказу леди Сильваны Ветрокрылой. Хотя его гибель разрушает волю, направлявшую стаю Темного Клыка, дикие звери и призрачные останки в крепости и окрестных лесах остаются постоянной угрозой для путников.",al={"kill arugal outcome","arugal dead lore","what happens after arugal dies","последствия убийства аругала","смерть аругала","что будет после смерти аругала"}},{q="Зачем Аругал призвал воргенов?",a="Во время Третьей войны армии Даларана терпели катастрофические поражения от Плети. Павшие волшебники постоянно восставали нежитью на службе Короля-лича. Ища оружие, способное переломить ход войны, Аругал использовал арканные исследования волшебника Ура, чтобы призвать воргенов из иного измерения, полагая, что их свирепость остановит Плеть.",al={"why worgen summoned","arugal motive","dalaran worgen summon","зачем призвали воргенов","мотив аругала","даларан призыв воргенов"}},{q="Кто такой барон Сребролен?",a="Барон Сребролен был дворянином-человеком, правившим крепостью и управлявшим соседней деревушкой Погребальных Костров до Третьей войны. Когда призванные Аругалом звери вышли из-под контроля, они захватили цитадель и перебили барона, его семью и стражу. Призрак Сребролена, жаждущий мести, до сих пор бродит по большим обеденным залам, проклятый ходить рядом с чудовищами, убившими его.",al={"baron silverlaine lore","original lord of shadowfang","барон сребролен история","первый владелец темного клыка"}},{q="Почему жители Деревни Погребальных Костров днем дружелюбны?",a="Аругал подверг жителей соседней Деревни Погребальных Костров своей темной магии. Днем они сохраняют человеческий облик, разум и миролюбие по отношению к путникам из Альянса. На закате проклятие вступает в силу и превращает все население в диких воргенов, преданных безумному верховному магу в крепости.",al={"pyrewood humans","pyrewood curse","why pyrewood turns worgen","люди погребальных костров","проклятие погребальных костров","почему погребальные костры превращаются в воргенов"}},{q="Кто такой командир Ручьедол?",a="Командир Ручьедол был паладином Серебряной Длани и военным офицером, отвечавшим за оборону крепости Сребролен. Когда воргены захватили цитадель, он бился до смерти. Его неупокоенный дух до сих пор обходит верхние коридоры, цепляясь за воинский долг даже в нежизни.",al={"springvale lore","ghostly paladin boss","ручьедол история","призрачный паладин босс"}},{q="Что такое Книга Ура?",a="Книга Ура — фолиант с исследованиями Ура, верховного мага Даларана, изучавшего существ из иных измерений, в том числе воргенов. Аругал использовал записи Ура для своего гибельного призыва. Королевское фармацевтическое общество в Подгороде ищет книгу, чтобы понять природу волкоподобных существ и их странную магию.",al={"book of ur quest","ur lore","задание книга ура","история ура"}}},fp="15,425,31.728.0,17.630.0,19.576.1,46.419.1,33.338.0,26.378.0,59.299.0,28.282.0,23.334.0"}
P.entries["zone:shendralas"] = {n="Шен'дралас",s="Шен'дралас — суровая спорная глушь между Фераласом, Мулгором и юго-восточными Пустошами. Здесь преобладают древние руины ночных эльфов и неспокойные границы; это переменчивый перекресток, где сталкиваются наступающие кентавры, изгнанники и ощетинившиеся свинобразы.",h="Шен'дралас — суровая спорная глушь между Фераласом, Мулгором и юго-восточными Пустошами.",kw={"bristleback retreat","desolace","evenshade overlook","feralas","lake dumont","magram front","mulgore","outcast hideaway","shendralas","valley of bones","укрытие дыбогривов","пустоши","обзорная площадка предвечерней тени","фералас","озеро дюмон","передовая маграм","мулгор","убежище изгоев","шен'дралас","долина костей"},ang={["faction:Alliance"]="Отдаленная спорная глушь, дающая обходные пути между Фераласом и центральным Калимдором и полная опасностей, требующих неусыпной бдительности.",["faction:Horde"]="Расположенный сразу за южными пределами Мулгора, Шен'дралас важен для защиты границ Орды: здесь необходимо сдерживать Маграмов и свинобразов.",["race:NightElf"]="Название напоминает о древних преданиях высокорожденных Эльдре'Таласа и привлекает внимание часовых, опасающихся безрассудной магии на юге Калимдора.",["race:Tauren"]="Поскольку регион граничит с Мулгором и Пустошами, натиск свинобразов и кентавров на этих хребтах прямо угрожает близлежащим исконным охотничьим угодьям."},sec={{t="Неспокойное пограничье",b="Шен'дралас затерян в горах к юго-востоку от Пустошей и граничит с Мулгором и Фераласом. Это дикое пограничье, далекое от столиц основных фракций. В его скалистых проходах и тайных укрытиях живут отчаявшиеся группы, пытающиеся выжить на краю дикого Калимдора. От уединенных наблюдательных точек, таких как Обзорная площадка Предвечерней Тени, до беззаконных убежищ вроде Убежища изгоев — зона определяется теми, кто хочет наблюдать незамеченным или остаться забытым."},{t="Кентавры, свинобразы и древние руины",b="Земля несет явный отпечаток наследия высокорожденных, давшего ей имя, но спокойной ее не назвать. Конфликты кентавров выплескиваются через Передовую Маграм, поддерживая старую кровную вражду вдоль границ. Тем временем наступающие свинобразы удерживают укрепленные оплоты вроде Укрытия Дыбогривов, превращая каждое тенистое ущелье в спорную территорию для любого проходящего путника."},{t="Долина Костей",b="К северо-западу, в сторону Пустошей, лежит Долина Костей — мрачный коридор, главный сухопутный путь в Шен'дралас. Выбеленный солнцем и ветром, этот проход служит суровым напоминанием о жестоких схватках, постоянно сотрясающих эти скалы."}},faq={{q="Где находится Шен'дралас?",a="Шен'дралас лежит к юго-востоку от Пустошей, между границами Фераласа и Мулгора. Путники, идущие пешком, обычно попадают сюда из Пустошей через Долину Костей.",al={"where is shendralas","shendralas location","how to get to shendralas","где шен'дралас","расположение шен'драласа","как добраться до шен'драласа"}},{q="Шен'дралас принадлежит Альянсу или Орде?",a="Ни одна из фракций не владеет этими землями. Шен'дралас — спорное пограничье, где обитают кочующие кентавры, враждебные свинобразы, изгнанники и разрозненные лагеря.",al={"is shendralas horde","is shendralas alliance","who owns shendralas","шен'дралас орда","шен'дралас альянс","кому принадлежит шен'дралас"}},{q="Какие здесь есть крупные поселения и ориентиры?",a="Среди заметных ориентиров — Долина Костей, Укрытие Дыбогривов, Обзорная площадка Предвечерней Тени, Передовая Маграм, Убежище изгоев и сама центральная часть Шен'драласа.",al={"shendralas subzones","landmarks in shendralas","points of interest shendralas","подзоны шен'драласа","ориентиры шен'драласа","интересные места шен'драласа"}},{q="Почему здесь есть кентавры?",a="Территориальные войны кентавров тянутся от равнин Пустошей прямо в этот край вдоль Передовой Маграм, где клан сражается с местными защитниками и соперничающими фракциями.",al={"centaur in shendralas","magram front","why are magram here","кентавры в шен'драласе","передовая маграм","почему здесь маграм"}},{q="Что такое Укрытие Дыбогривов?",a="Укрытие Дыбогривов — укрепленный форпост свинобразов-Дыбогривов, которые прочно обосновались на окраинах зоны.",al={"bristleback retreat","quilboar in shendralas","укрытие дыбогривов","свинобразы в шен'драласе"}},{q="Как эта зона связана с озером Дюмон?",a="Географически дикий край Шен'драласа раскинулся на горной территории, где на старых картах съемки значится уединенное озеро Дюмон.",al={"lake dumont","shendralas map history","озеро дюмон","история карты шен'драласа"}}},fp="11,286,23.441.0,36.393.0,19.282.0,29.189.0,55.155.0,45.172.0,27.175.0,28.139.0,57.153.0"}
P.entries["zone:silithus"] = {n="Силитус",s="Силитус — безжизненная, выжигаемая ветрами пустыня в дальнем юго-западном углу Калимдора. Под ее сухими песками лежат огромные колонии насекомоподобных силитидов и древние руины Ан'Киража, запечатанные тысячелетие назад за грозной Стеной Скарабея. Сегодня друиды Круга Кенария несут трудную стражу против ползущих роев и культистов конца света.",h="Силитус — безжизненная, выжигаемая ветрами пустыня в дальнем юго-западном углу Калимдора.",kw={"ahn'qiraj","cenarion hold","hive'ashi","hive'regal","hive'zora","scarab dais","scarab wall","silithid","silithus","twilight's hammer","ан'кираж","крепость кенария","улей аши","улей регал","улей зора","помост скарабея","стена скарабея","силитид","силитус","сумеречный молот"},ang={["class:Druid"]="Будучи сердцем деятельности Круга Кенария на юге Калимдора, Силитус призывает друидов остановить порчу земли и противостоять неестественным выводкам, угрожающим равновесию природы.",["profession:Herbalism"]="Несмотря на суровую пустыню, здесь процветают редкие растения: Горный серебряный шалфей, Снолист, Солнечник и особенно ценный Черный лотос.",["profession:Mining"]="В сухих скалах и туннелях насекомых Силитуса находятся одни из богатейших в мире залежей тория, включая редкие жилы, покрытые слизью, скрытые в ульях силитидов.",["race:NightElf"]="Силитус — мрачное место упокоения, где пролили кровь ваши предки в Войне Зыбучих Песков, пожертвовав тысячами ради запечатывания врат Ан'Киража."},sec={{t="Пустынное пограничье",b="Чтобы попасть в Силитус, нужно пройти через первобытные джунгли кратера Ун'Горо и подняться по широкому каменистому проходу в его северо-западном углу. Переход разителен: пышная древняя растительность исчезает, уступая место бескрайним барханам, зазубренным скалам и неестественным высоким ульям. Воды почти нет, а ветер несет гул крыльев насекомых и шепот песков. Круг Кенария содержит Крепость Кенария близ центра пустыни — единственный оплот цивилизации и убежище для путников, исследователей и воинов, бросающих вызов враждебным пустошам."},{t="Отголоски Зыбучих Песков",b="Тысячу лет назад этот засушливый простор был полем боя Войны Зыбучих Песков. Союзная армия ночных эльфов и великих драконьих родов отчаянно сражалась, чтобы отбросить киражей — коварную насекомоподобную империю, возникшую из древней цивилизации акираев. Когда полная победа оказалась невозможной, защитники запечатали рои в их твердыне с помощью Стены Скарабея и зачарованного Помоста Скарабея. Пока исполинские врата держались, подземные туннели позволяли звероподобным силитидам выбираться наружу, и по всем пескам возникли обширные колонии, такие как Улей Аши, Улей Зора и Улей Регал."},{t="Надвигающаяся буря",b="Апокалиптический культ Сумеречного Молота закрепился в нескольких укрепленных форпостах, призывая стихийных чудовищ и поклоняясь темной силе, дремлющей под Ан'Киражем. Наблюдатели Круга Кенария следят за разрастающимися колониями силитидов в пустыне и древней угрозой за Стеной Скарабея."}},faq={{q="Как пешком добраться до Силитуса?",a="Отправляйтесь в северо-западный угол кратера Ун'Горо. Возле излучины извилистой реки, между двумя заметными каменными столбами, наклонная грунтовая дорога ведет вверх через горную стену кратера прямо в пустыню Силитус.",al={"silithus entrance","how to get to silithus","silithus path","вход в силитус","как добраться до силитуса","путь в силитус"}},{q="Что такое Стена Скарабея?",a="Стена Скарабея — огромный зачарованный барьер на юге Силитуса. Ее возвели тысячу лет назад ночные эльфы и драконьи роды во время Войны Зыбучих Песков, чтобы заточить злобную империю киражей в Ан'Кираже.",al={"ahn'qiraj gate","scarab wall","the big wall in silithus","врата ан'кираж","стена скарабея","большая стена в силитусе"}},{q="Кто управляет Крепостью Кенария?",a="Крепость Кенария — форпост, основанный и управляемый Кругом Кенария. Его друиды и союзные стражи наблюдают за наступающими роями силитидов, исследуют древние руины и принимают нейтральных путников как из Альянса, так и из Орды.",al={"who is in cenarion hold","cenarion hold faction","cenarion hold friendly","кто в крепости кенария","фракция крепости кенария","крепость кенария дружелюбие"}},{q="What are the giant insect mounds across the zone?",a="Это крупные подземные ульи силитидов: Улей Аши, Улей Зора и Улей Регал. Каждый улей — разветвленная сеть туннелей, где обитают отдельные касты насекомоподобных существ, служащих воле, запертой за Ан'Киражем.",al={"silithus hives","bug hives silithus","hive ashi hive zora","ульи силитуса","ульи насекомых силитус","улей аши улей зора"}},{q="Что здесь делает Сумеречный Молот?",a="Культ Сумеречного Молота держит в Силитусе несколько укрепленных баз, включая Сумеречный лагерь и Сумеречную заставу. Они проводят мерзкие ритуалы для призыва элементалей и поклоняются древним злобным существам, погребенным за Стеной Скарабея.",al={"twilight cultists silithus","twilight outpost silithus","why is twilight's hammer in silithus","сумеречные культисты силитус","сумеречный форт силитус","почему сумеречный молот в силитусе"}}},fp="8,366,19.594.0,28.622.0,18.305.0,33.234.0,24.246.0,23.233.0,49.227.0,41.250.0"}
P.entries["zone:silverpine"] = {n="Серебряный бор",s="Серебряный бор — жутковатый, окутанный туманом лес вдоль западного побережья Лордерона, между Тирисфальскими лесами и закрытой Стеной Седогрива. Отмеченный неизгладимыми шрамами чумы Плети, он служит спорным южным рубежом Отрекшихся. Путников здесь подстерегают дикие воргены, скрывающиеся в тенях, больные гноллы и враждебные людские поселения.",h="Серебряный бор — жутковатый, окутанный туманом лес вдоль западного побережья Лордерона, между Тирисфальскими...",kw={"ambermill","arugal","fenris isle","greymane wall","pyrewood","rot hide","sepulcher","shadowfang","silverpine","silverpine forest","янтарная мельница","аругал","остров фенриса","стена седогрива","деревня погребальных костров","гнилошкуры","гробница","темный клык","серебряный бор"},ang={["class:Mage"]="Присутствие Янтарной мельницы и падение верховного мага Аругала в волчье безумие делают Серебряный бор мрачным предостережением о магии Кирин-Тора, пошедшей роковым путем.",["faction:Alliance"]="Исследователи Альянса найдут глубоко враждебный лес, где лишь хрупкий гарнизон Даларана в Янтарной мельнице и несчастные проклятые жители Деревни Погребальных Костров нарушают картину.",["race:Undead"]="Серебряный бор — непосредственная передовая линия экспансии Отрекшихся к югу от Тирисфальских лесов, где Королевское фармацевтическое общество испытывает новые составы, а Стражи смерти сражаются с остатками агентов Плети."},sec={{t="Неспокойный рубеж",b="Когда-то Серебряный бор считался цветущим чудом Лордерона, через которое знатные путники ехали в Столицу, но Третья война иссушила его. Призрачные туманы вьются между умирающими соснами с серебристой корой, а разоренные фермы заброшены и поглощены дикой природой. На севере лежат Тирисфальские леса, а восточный берег граничит с Озером Лордамер. На юге высится грозная закрытая Стена Седогрива, отделяющая замкнутое королевство Гилнеас от окружающего хаоса. Отрекшиеся держат свой главный оплот в Гробнице, стремясь защитить лес от врагов со всех сторон."},{t="Ворген и Темный Клык",b="Самая печально известная опасность Серебряного бора — проклятие ворген. Высоко над юго-западными лесами стоит Крепость Темного Клыка, прежняя резиденция барона Сребролена, а ныне оплот безумного даларанского архимага Аругала. Пытаясь отразить Плеть во время Третьей войны, Аругал призвал волкоподобных существ из иного измерения. Твари обратились против призвавших их и распространили ликантропическое проклятие по южным лесам. В Деревне Погребальных Костров обычные на вид жители-люди днем занимаются хозяйством, а под ночным небом превращаются в диких ворген."},{t="Соперничающие поселения и Плеть",b="Притязания Отрекшихся на Серебряный бор жарко оспаривают как живые, так и мертвые. На востоке, на Острове Фенриса, Тул Коготь Ворона возглавляет отряд остатков Плети и командует одурманенными чумой гноллами Гнилошкурами, терзающими северные фермы. На юге люди-маги из Даларана удерживают укрепленное поселение Янтарная мельница, ведут магические исследования и противостоят экспансии Отрекшихся. Королевское фармацевтическое общество и Верховный палач Хадрик в Гробнице ведут жестокую многостороннюю кампанию, чтобы устранить эти угрозы и испытать новые смертоносные чумы."}},faq={{q="Что такое Стена Седогрива на южной границе?",a="Стена Седогрива — огромная каменная преграда, возведенная королем Генном Седогривом, чтобы полностью изолировать его королевство Гилнеас от остального Лордерона. Когда во время Третьей войны Плеть опустошала континент, Гилнеас запер ворота и отказался от внешней помощи, оставив земли к северу от стены, включая юг Серебряного бора, самим по себе.",al={"why is there a giant wall","greymane wall lore","gate to gilneas","зачем гигантская стена","стена седогрива история","ворота в гилнеас"}},{q="Почему жители Деревни Погребальных Костров нападают ночью?",a="Жители Деревни Погребальных Костров страдают от проклятия воргенов верховного мага Аругала. Днем они сохраняют человеческий облик, занимаются повседневными делами и дружелюбны к Альянсу. Когда восходит луна, проклятие вступает в силу и превращает все население в свирепых кровожадных воргенов, яростно нападающих на любого поблизости.",al={"pyrewood village mystery","pyrewood worgen","why are pyrewood humans hostile at night","тайна деревни погребальных костров","воргены погребальных костров","почему люди погребальных костров враждебны ночью"}},{q="Кто такой Тул Коготь Ворона?",a="Тул Коготь Ворона — могущественный некромант на службе Плети. Действуя из Крепости Фенриса на Острове Фенриса посреди Озера Лордамер, он командует легионами нежити и влияет на пораженных чумой гноллов Гнилошкуров в восточной части Серебряного бора, напрямую угрожая восточному флангу Отрекшихся.",al={"who leads fenris isle","thule ravenclaw lore","scourge on fenris isle","кто правит островом фенриса","тул коготь ворона история","плеть на острове фенриса"}},{q="Почему Даларан занимает Янтарную мельницу?",a="Янтарную мельницу удерживают чародеи Даларана под началом верховного мага Атаэрика. Действуя из деревни, эти маги-люди следят за передвижениями Отрекшихся, изучают магические недуги, поражающие лес, и стремятся сдержать вспышку ворген, исходящую от Крепости Темного Клыка.",al={"ambermill mages","why is the alliance in ambermill","dalaran in silverpine","маги янтарной мельницы","почему альянс в янтарной мельнице","даларан в серебряном бору"}},{q="Что такое Гробница?",a="Гробница — главный военный оплот и транспортный узел Отрекшихся в Серебряном бору. Под командованием Верховного палача Хадрика она служит базой для патрулей Стражей смерти, разведчиков-Стражей смерти и Королевского фармацевтического общества в их борьбе за безопасность леса.",al={"horde town in silverpine","where is the flight path","sepulcher lore","город орды в серебряном бору","где точка полета","гробница история"}},{q="Могут ли игроки Альянса выполнять задания в Серебряном бору?",a="В Серебряном бору нет центров заданий Альянса и дружественных городов; все местные задания предназначены только для Орды. Искатели приключений из Альянса обычно заходят в лес лишь по пути из Южнобережья в Крепость Темного Клыка или чтобы сразиться с враждебными силами Отрекшихся.",al={"is silverpine horde only","alliance quests in silverpine","can alliance go to silverpine","серебряный бор только для орды","задания альянса в серебряном бору","может ли альянс пойти в серебряный бор"}}},fp="17,362,18.611.0,25.536.0,30.560.1,49.350.0,57.329.0,23.292.0,35.268.0,22.284.0,48.260.0"}
P.entries["zone:stockade"] = {n="Тюрьма",s="Тюрьма — тюремный комплекс строгого режима в Штормграде, скрытый под районом каналов города возле Квартала магов. Построенная для самых опасных головорезов королевства, политических мятежников и захваченных врагов государства, она недавно погрузилась в жестокую анархию. Тюремщик Телвотер был оттеснен к входу и отчаянно набирает способных искателей приключений, чтобы подавить бунт изнутри, пока он не выплеснулся в столицу.",h="Тюрьма — тюремный комплекс строгого режима в Штормграде, скрытый под районом каналов города возле Квартала...",kw={"bazil thredd","bruegal ironknuckle","canals","defias","dextren ward","hamhock","kam deepfury","riot","stockade","stormwind","targorr","warden thelwater","базиль тредд","бругал железный кулак","каналы","братство справедливости","декстрен вард","хрупконог","кам гневливый","бунт","тюрьма","штормград","таргорр","тюремщик телвотер"},ang={["class:Mage"]="Тюрьма расположена на самом краю каналов Квартала магов; в ней содержатся рукопашные бойцы, уязвимые для замедляющих заклинаний, а огр-маг Хрупконог может применять Цепную молнию.",["class:Rogue"]="Планировка тюрьмы — сложная сеть запертых железных камер и связей с Братством Справедливости, что дает уникальную практику во взломе замков и понимание преступного синдиката Базиля Тредда.",["faction:Alliance"]="Мятеж угрожает самому сердцу столицы; подавление бунта сохраняет внутреннюю безопасность Штормграда и позволяет выполнить неофициальные заказы на головы от Красногорья, Сумеречного леса и Стальгорна.",["race:Dwarf"]="Присутствие Кама Гневливого в камерах Штормграда — оскорбление для Дун Модра; Королевство Стальгорн требует его головы, чтобы отомстить за жизни дворфов, погибших в Болотине."},sec={{t="Тюрьма в осаде",b="Под мирными каналами Штормграда Тюрьма превратилась в зону боевых действий. Когда регулярная армия ушла сражаться на далекие фронты, тюрьма, где не хватало персонала, стала полагаться на неопытную молодежь, в том числе четырнадцатилетних новобранцев. Порядок не удержался. Заключенные устроили кровавый организованный мятеж, разорвав шерстяные одеяла на бандитские банданы и перебив оставшихся стражников. Тюремщик Телвотер с трудом удержал вход, оставив камеры, коридоры и блоки содержания в безжалостных руках преступников."},{t="Знать и убийцы",b="Бунт обнажил неприглядную изнанку политической машины Штормграда. Внешние земли давно были недовольны тем, что Дом знати приостанавливает казни ради собственной выгоды. Страж Красногорья Бертон хотел казни захваченного орка Таргорра Ужасного за зверства, но видел, как знать заморозила приговор. Советник Темнолесья Миллстайп наблюдал, как расхитителя могил Декстрена Варда избавили от виселицы, несмотря на осквернение могил ради некроманта Морбента Скверна. Даже дворфы Дун Модра прислали требование казнить диверсанта из клана Черного Железа Кама Гневливого. Пока в Тюрьме царил хаос, местные власти тайно наняли искателей приключений, чтобы совершить казни, которые суды столицы отказывались исполнять."},{t="Зачинщик и бунтовщики",b="За слаженным крахом тюрьмы стоит Базиль Тредд, хитрый преступник, напрямую связанный с Братством Справедливости, организовавший мятеж из своей камеры. Среди бунтовщиков — Бругал Железный Кулак, опасный дворф-драчун. Он один из нескольких закаленных преступников, с которыми могут столкнуться искатели приключений, помогая Телвотеру вернуть тюрьму."}},faq={{q="Почему в Тюрьме открытый мятеж?",a="Братство Справедливости организовало бунт по всей тюрьме, когда в ней остро не хватало персонала. Поскольку Армия Штормграда была отправлена на далекие фронты, подростки-добровольцы охраняли закоренелых убийц. Заключенные устроили засаду персоналу, захватили оружие и вытеснили Тюремщика Телвотера из камерных блоков.",al={"why riot","what happened in stockades","stockades riot cause","почему бунт","что случилось в тюрьме","причина бунта в тюрьме"}},{q="Кто руководит мятежом внутри?",a="Зачинщик мятежа — Базиль Тредд, влиятельный преступник из Братства Справедливости, заключенный в восточном блоке камер. Среди других опасных заключенных — Бругал Железный Кулак, Хрупконог и Кам Гневливый.",al={"stockades boss","who leads the riot","who runs stockades","босс тюрьмы","кто возглавляет бунт","кто управляет тюрьмой"}},{q="Почему такие заключенные, как Таргорр и Декстрен Вард, все еще живы?",a="Оба были приговорены к смерти, но коррумпированные политики из Дома знати наложили бюрократические задержки на их казни, чтобы использовать их как политический рычаг. Это вмешательство возмутило союзников в Приозерье и Темнолесье, и они отправили искателей приключений устранить заключенных во время хаоса.",al={"why wasn't targorr executed","dextren ward court","house of nobles corruption","почему не казнили таргорра","суд декстрена варда","коррупция дома знати"}},{q="Что значит победа над Бругалом Железным Кулаком для тюрьмы?",a="Бругал Железный Кулак — опасный дворф-драчун среди бунтовщиков. Его поражение устраняет одну из угроз в тюрьме, пока искатели приключений работают над подавлением мятежа.",al={"bruegal ironknuckle lore","kill bruegal","who is bruegal","бругал железный кулак история","убить бругала","кто такой бругал"}},{q="Почему в человеческой тюрьме находятся дворфы Черного Железа и орки?",a="Тюрьма служит местом содержания строгого режима для особо важных военнопленных. Таргорр Ужасный возглавлял нападения орков Черной горы в Красногорье, а Кам Гневливый проводил диверсии для клана Черного Железа в Болотине, пока обоих не захватили и не перевели в столицу.",al={"why dark irons here","kam deepfury lore","targorr stockades","почему тут черное железо","кам гневливый история","таргорр тюрьма"}},{q="Могут ли игроки Орды попасть в Тюрьму?",a="Да, но это крайне опасно. Вход в подземелье находится прямо в Штормграде возле каналов Квартала магов. Лазутчикам Орды придется незаметно пройти мимо городской стражи и защитников столицы, чтобы добраться до портала.",al={"can horde do stockades","horde in stormwind prison","может ли орда в тюрьму","орда в тюрьме штормграда"}}},fp="12,455,20.556.0,20.705.1,30.341.1,38.314.0,35.198.0,60.303.0,60.167.0,61.278.0,37.226.0"}
P.entries["zone:stonetalon"] = {n="Когтистые горы",s="Когтистые горы — суровая горная цепь с изрезанными ветрами скалистыми пиками, граничащая с Ясеневым лесом, Степями и Пустошами. Ночные эльфы и таурены чтят ее как священное убежище, и священные вершины региона резко контрастируют с дымом и механизмами, душащими нижние каньоны. Сегодня горы истерзаны вырубкой лесов, разрушительными выходками стихий и тлеющей враждой на границах.",h="Когтистые горы — суровая горная цепь с изрезанными ветрами скалистыми пиками, граничащая с Ясеневым лесом...",kw={"charred vale","gerenzo wrenchwhistle","malaka'jin","stonetalon","stonetalon peak","sun rock retreat","talondeep pass","windshear","обугленная долина","геренцо терминатрикс","малака'джин","когтистые горы","пик каменного когтя","приют у солнечного камня","глубокий когтистый перевал","утес ветрорезов"},ang={["class:Druid"]="Осквернение Утеса Ветрорезов и выжженная порча Обугленной долины — суровый призыв для друидов, стремящихся успокоить разъяренных духов природы и защитить священные гнездовья.",["class:Shaman"]="Крик горных духов, страдающих от гоблинских буров, слышен даже в Оргриммаре; он призывает шаманов усмирить буйных элементалей земли и восстановить равновесие в горах.",["faction:Alliance"]="Расквартированный высоко на Пике Каменного Когтя и в скрытых лагерях вокруг Утеса Ветрорезов, Альянс защищает древние курганы кальдораев от гоблинских машин и посягающих территориальных соперников.",["faction:Horde"]="Приключенцы Орды опираются на уединенное убежище — Приют у Солнечного Камня — и южный тролльский форпост Малака'джин, чтобы сдерживать промышленное загрязнение от Торговой Компании и искоренять вероломных изгоев из племени Зловещего Тотема."},sec={{t="Злые ветры и пики",b="Когтистые горы круто поднимаются в центре Калимдора и ловят влагу, приносимую с западных морей, отчего здесь внезапно случаются ливни, а песчаниковые тропы становятся коварно скользкими. Главная особенность нижних долин — непрестанный иссекающий шквал, известный как Злые ветры: он способен ослепить путников песком или сбросить неосторожных с отвесных скал. Выше склоны вокруг Пика Каменного Когтя покрывают вечнозеленые леса, где ночные эльфы ухаживают за древними курганами и рощами и охраняют священные гнездовья виверн и гиппогрифов, обитающих у Мутного озера."},{t="Промышленность и вторжение",b="Мирное уединение гор было грубо нарушено появлением Торговой Компании. Устроив обширные лесозаготовки и глубокие карьеры на Утесе Ветрорезов, гоблины при помощи безумного лепрогнома Геренцо Терминатрикса вырубили вековые леса, затемнили небо дымом печей и сбросили промышленные отходы в горные стоки. Их жадность вызвала быстрый отпор: местные шаманы из Оргриммара откликнулись на мучительные крики горных духов, а небольшие лагеря Альянса неподалеку сражаются с осквернителями, защищая то, что осталось от нагорий."},{t="Шрамы прошлого",b="На юге лежит Обугленная долина — некогда цветущая глушь, а ныне покрытая пеплом пустошь, где буйствуют взбесившиеся огненные элементали, черные дракониды и гарпии. Хотя именно на этих пиках во время Третьей войны Орда и Альянс при посредничестве загадочного Оракула заключили непрочное перемирие, сегодня отношения рушатся. Мятежные таурены из племени Зловещего Тотема действуют из захваченных стоянок, а тролли Черного Копья в Малака'джине сталкиваются с вторжениями Альянса, продвигающегося из Степей и Ясеневого леса."}},faq={{q="Как добраться до Когтистых гор?",a="Большинство путников входит через Глубокий Когтистый перевал — горную тропу, врезающуюся в хребет с юго-запада Ясеневого леса. Есть и высокие тропы, ведущие на юг, в Пустоши, и дороги, спускающиеся на восток прямо в северные просторы Степей.",al={"stonetalon entrance","how to get to stonetalon","stonetalon road","вход в когтистые горы","как добраться до когтистых гор","дорога в когтистые горы"}},{q="Почему Обугленная долина сожжена и разорена?",a="Обугленная долина некогда была цветущим приютом, но катастрофическое бедствие охватило ее пламенем. Теперь это тлеющие руины, кишащие агрессивными огненными элементалями, драконами-отступниками и опасными гарпиями.",al={"charred vale fire","what happened to charred vale","why charred vale burnt","обугленная долина огонь","что случилось с обугленной долиной","почему сгорела обугленная долина"}},{q="Что делает Торговая Компания на Утесе Ветрорезов?",a="Торговая Компания безжалостно вырубает лес и бурит гору вглубь в поисках минеральных богатств. Ее работы загрязнили Скалистое озеро машинным маслом, оголили долины и разъярили местных духов и коренных обитателей.",al={"venture co stonetalon","windshear crag goblins","why are goblins cutting trees","торговая компания когтистые горы","гоблины утес ветрорезов","почему гоблины рубят деревья"}},{q="Где находятся главные распорядители полетов?",a="Герои Альянса пользуются распорядителем полетов, расположенным в высокой обители Пика Каменного Когтя на севере, а искатели приключений Орды базируются в горной деревне Приют у Солнечного Камня в центре региона.",al={"stonetalon flight path","where is flight point stonetalon","stonetalon fp","полеты когтистые горы","где пункт полета когтистые горы","гп когтистые горы"}},{q="Что произошло на Пике Каменного Когтя во время Третьей войны?",a="Следуя видениям Пророка Медива, Тралл и Джайна Праудмур поднялись по пещерам Пика Каменного Когтя в поисках Оракула. Там два предводителя фракций заключили исторический временный союз, объединившийся против Пылающего Легиона на горе Хиджал.",al={"stonetalon peak lore","the oracle stonetalon","third war stonetalon","история пика каменного когтя","оракул когтистые горы","третья война когтистые горы"}},{q="Что представляет собой Зловещий Тотем в Когтистых горах?",a="Зловещий Тотем — безжалостное мятежное племя тауренов, враждебное чужому влиянию. В Когтистых горах они заняли горный форпост у границы Степей, терроризируя местных путников и захватывая пленников.",al={"grimtotem post","grimtotem stonetalon","форпост зловещего тотема","зловещий тотем когтистые горы"}}},fp="20,410,27.610.0,22.630.0,17.537.0,41.251.0,42.215.0,52.258.0,42.193.0,54.257.0,36.219.0"}
P.entries["zone:stormwind"] = {n="Штормград",s="Штормград — шумная столица Королевства Штормград и главный оплот людей в мире после падения Лордерона. Отстроенный из пепла Гильдией каменщиков после разрушения в Первой войне, он своими великолепными районами из белого камня вмещает сердце Великого Альянса. Но под величественными каналами и соборами город переживает внезапное исчезновение короля Вариана Ринна и назревающие политические интриги.",h="Штормград — шумная столица Королевства Штормград и главный оплот людей в мире после падения Лордерона.",kw={"anduin","bolvar","cathedral","deeprun","prestor","stonemasons","stormwind","vancleef","wrynn","андуин","болвар","собор","подземный поезд","престор","каменщики","штормград","ван клиф","ринн"},ang={["class:Paladin"]="Собор Света — главная святыня вашей веры на юге: здесь обучают рыцарей Серебряной Длани и хранят справедливость.",["class:Rogue"]="Под безупречными каменными улицами находится штаб-квартира ШРУ в Старом городе, управляющая основной разведывательной и шпионской сетью Альянса.",["faction:Alliance"]="Как самый многолюдный город Великого Альянса, Штормград обеспечивает флотскую мощь, духовную опору и жизненно важное дипломатическое руководство.",["race:Dwarf"]="Через Подземный поезд ваши сородичи из Квартала Дворфов поддерживают тесные торговые связи и братские военные узы с человеческим королевством.",["race:Human"]="Штормград остается последним великим оплотом суверенной власти вашего народа после разрушения Лордерона, Альтерака и Даларана на севере."},sec={{t="Возрождение из пепла",b="Основанный более тысячи лет назад потомками Арати, Штормград множество поколений оставался процветающим самодостаточным государством. Золотой век закончился, когда Орочья Орда хлынула через Темный портал, опустошила южный континент и сравняла столицу с землей в Первой войне. Выжившие под предводительством сэра Андуина Лотара бежали на север через Великое море в Лордерон. После поражения Орды во Второй войне король Теренас Менетил II и Альянс финансировали полное восстановление. Гильдия каменщиков кропотливо отстроила столицу заново как Новый Штормград — сияющую цитадель из полированного белого камня с районами, пронизанными каналами."},{t="Расколотый двор",b="Несмотря на внешнее величие, столица охвачена внутренними смутами. Спор между Домом знати и Гильдией каменщиков из-за платы оставил королевство парализованным долгами. Последовавшие беспорядки унесли жизнь королевы Тиффин Ринн и толкнули изгнанных ремесленников на преступный путь — так появилось Братство Справедливости. Теперь король Вариан Ринн загадочно исчез по пути на дипломатическую встречу. Чтобы избежать паники, корону возложили на его юного сына, десятилетнего принца Андуина Ринна, а верховный лорд Болвар Фордрагон правит как регент и военачальник вместе с королевским советником леди Катраной Престор."},{t="Сердце Великого Альянса",b="После захвата Лордерона Плетью Штормград унаследовал звание величайшего приюта человечества и средоточия Альянса. Он напрямую связан с дворфийским королевством Стальгорн Подземным поездом главного механика Меггакрута. Посетителей на Аллее Героев встречают огромные статуи Сынов Лотара, исчезнувших за Темным порталом. От духовного маяка Собора Света до тайных наук в Святилище волшебника — Штормград является главным центром торговли, культуры и обороны южных морей."},{t="Тени в замке",b="Раздор, терзающий королевство, — не простая административная случайность. Леди Катрана Престор тайно направляла решения Дома знати, разжигая вражду с каменщиками и умышленно оставляя без внимания просьбы о военной помощи от дальних поселений, таких как Западный Край и Красногорье. Нашептывая яд на ухо верховному лорду Болвару и разделяя внимание королевства, она добивается, чтобы легионы Штормграда бездействовали и были разобщены, пока растущие за стенами города волнения угрожают самому трону."}},faq={{q="Кто сейчас правит Штормградом?",a="Корону носит десятилетний принц Андуин Ринн, но фактически государством управляет верховный лорд Болвар Фордрагон, регент Штормграда и верховный главнокомандующий его армии. Болвар во многом полагается на советы королевского советника леди Катраны Престор, пока король Вариан Ринн остается пропавшим.",al={"current king","who is the king","who leads stormwind","king of stormwind","нынешний король","кто король","кто правит штормградом","король штормграда"}},{q="Что случилось с королем Варианом Ринном?",a="Король Вариан исчез при подозрительных обстоятельствах, плывя на корабле на дипломатическую встречу в Терамор. Его исчезновение держали в тайне ради стабильности, но слухи ходят по улицам и деревням.",al={"where is varian","missing king","varian gone","varian wrynn missing","где вариан","пропавший король","вариан исчез","вариан ринн пропал"}},{q="Почему город отстроили заново и кто это сделал?",a="Прежний город был сожжен дотла Орочьей Ордой в Первой войне. После Второй войны Гильдия каменщиков под руководством мастера Эдвина ван Клифа кропотливо отстроила столицу из сияющего белого камня при финансовой поддержке Альянса Лордерона.",al={"who rebuilt stormwind","stonemasons guild","new stormwind","city rebuilding","кто отстроил штормград","гильдия каменщиков","новый штормград","восстановление города"}},{q="Почему каменщики восстали против короны?",a="Дом знати наделал больших долгов, расширяя армию Штормграда, и отказался выплатить Гильдии каменщиков обещанное жалованье. Когда Эдвин ван Клиф потребовал возмещения, знать распустила гильдию. Рабочие взбунтовались, королева Тиффин Ринн погибла от брошенного камня, а изгнанные каменщики образовали Братство Справедливости.",al={"defias origin","why defias mad","stonemasons riot","queen tiffin death","происхождение братства справедливости","почему братство справедливости злится","бунт каменщиков","смерть королевы тиффин"}},{q="Кто изображен на гигантских статуях на Аллее Героев?",a="Статуи почитают Сынов Лотара: генерала Туралиона, капитана рейнджеров Аллерию Ветрокрылую, верховного мага Кадгара, Курдрана Громового Молота и Даната Троллебоя. Их воздвигли в память о героях, которые прошли через Темный портал в Дренор, чтобы закрыть разлом и защитить Азерот.",al={"statues at the entrance","valley of heroes statues","sons of lothar statues","статуи у входа","статуи аллеи героев","статуи сынов лотара"}},{q="Как Штормград связан со Стальгорном?",a="Штормград соединен со Стальгорном Подземным поездом — подземной железной дорогой, построенной главным механиком Гелбином Меггакрутом по заказу короля Магни Бронзоборода для быстрой торговли и переброски войск между двумя столицами.",al={"deeprun tram","train to ironforge","how to get to ironforge","подземный поезд","поезд в стальгорн","как добраться до стальгорна"}},{q="Почему Штормград не посылает войска на помощь Западному Краю и Красногорью?",a="Королевский двор, на который сильно влияет леди Катрана Престор, настаивает, что город не может отвлекать войска от собственных стен и ближних границ. Из-за напряженных финансов королевства и политических дрязг, парализующих Дом знати, окрестные города брошены на произвол и вынуждены полагаться на местное ополчение.",al={"stormwind army missing","why no help for westfall","reinforcements refused","армия штормграда пропала","почему нет помощи западному краю","отказ в подкреплении"}}},fp="14,461,19.657.0,15.605.0,27.577.0,19.516.2,30.299.0,35.231.0,38.286.0,48.333.0,50.279.0,40.240.0,65.292.0"}
P.entries["zone:stranglethorn"] = {n="Тернистая долина",s="Тернистая долина — дикие, густые джунгли на южной оконечности Восточных королевств, к югу от Сумеречного леса. Когда-то здесь находился центр великой Империи Гурубаши, а теперь тропический лес усеян разрушающимися руинами троллей, свирепыми зверями и соперничающими лагерями гоблинов, пиратов и солдат. За контроль над краем яростно борются местные племена троллей, Торговая Компания и другие фракции, стремящиеся закрепиться в этом зное.",h="Тернистая долина — дикие, густые джунгли на южной оконечности Восточных королевств, к югу от Сумеречного леса.",kw={"bloodsail","booty bay","grom'gol","gurubashi","kurzen","nesingwary","revilgaz","stranglethorn","venture co","zul'gurub","кровавый парус","пиратская бухта","гром'гол","гурубаши","курцен","эрнестуэй","ревилгаз","тернистая долина","торговая компания","зул'гуруб"},ang={["class:Hunter"]="На северном берегу реки живет знаменитый охотник на крупную дичь Хеминг Эрнестуэй, который предлагает стрелкам проверить себя, выслеживая самых свирепых ящеров, пантер и кроколисков джунглей.",["faction:Alliance"]="Исторические попытки Штормграда покорить и усмирить джунгли обременили королевство тяжелыми долгами, и сегодня его интересы защищают лишь изнуренные мятежники в Лагере Повстанцев.",["faction:Horde"]="Лагерь Гром'гол дает Орде незаменимый стратегический оплот на южном континенте, снабжаемый напрямую дирижаблями из Дуротара и Подгорода.",["profession:Herbalism"]="Влажный лесной полог питает ценные растения, поэтому берега рек и побережья — идеальные места для сбора Дикого сталецвета, Бледнолиста, Златошипа и Лилового лотоса.",["race:Troll"]="Тернистая долина — родина троллей джунглей, чья древняя империя Гурубаши пала в гражданской войне после поклонения Хаккару Свежевателю Душ, что вынудило такие племена, как Черное Копье, уйти за моря."},sec={{t="Руины империи",b="На протяжении тысячелетий долиной правила могучая Империя Гурубаши из своей столицы Зул'Гуруб. Это владычество рухнуло, когда радикальные жрецы призвали Хаккара Свежевателя Душ, ввергнув область в катастрофическую гражданскую войну. Зандалары вмешались и подавили восстание кровавого бога, но империя распалась безвозвратно. Сегодня джунгли наводнены враждующими племенами-преемниками, самые известные из которых — Кровавые Скальпы на северо-западе и Дробители Черепов на востоке; те и другие рьяно истребляют чужаков, чтобы вернуть родной дом."},{t="Пираты и дельцы",b="Там, где древние руины умолкают, пустоту заполняет торговая алчность. На южной оконечности лежит Пиратская бухта — оживленная гавань, созданная Картелем Хитрая Шестеренка и управляемая Налетчиками Черноводья под началом барона Ревилгаза. Порт служит главным узлом южной торговли и морских перевозок, хотя его постоянно осаждают соперники — Пираты Кровавого Паруса, стоящие на якоре вдоль побережья. Дальше вглубь суши Торговая Компания беспощадно вырубает джунгли и добывает в холмах редкие поющие кристаллы."},{t="Спорные дебри",b="Тернистая долина — одно из самых неспокойных пограничий мира. Орда удерживает Лагерь Гром'гол на западном побережье, связанный гоблинскими дирижаблями с Дуротаром и Тирисфальскими лесами, а сторонники Альянса действуют из Лагеря Повстанцев, выслеживая мятежного Полковника Курцена. Среди густой листвы легендарный охотник Хеминг Эрнестуэй возглавляет отважные экспедиции за крупной дичью, вовлекая странников в опасные схватки с рыскающими пантерами, огромными обезьянами и вражескими солдатами."},{t="Безумие в джунглях",b="Не все опасности северной части Тернистой долины — дикие звери. Полковник Курцен, некогда заслуженный командир, посланный Штормградом, сошел с ума в чаще и устроил тираническую наемную цитадель. На деле разум Курцена был захвачен чарами Ока разума — артефакта, которым владел маг-огр Май'Зот из соседнего Холма Мош'Огг; это ввергло экспедицию в полное безумие и побудило его прежних людей создать отколовшийся Лагерь Повстанцев."}},faq={{q="Кто управляет Тернистой долиной?",a="Ни одна сила не правит долиной. Джунгли поделены между соперничающими племенами троллей джунглей, такими как Кровавые Скальпы и Дробители Черепов, разбойничьими лагерями вроде Лагеря Курцена, наемной Торговой Компанией и разрозненными военными постами Орды и Альянса. Крупнейшее городское поселение — нейтральный гоблинский порт Пиратская бухта, которым управляют барон Ревилгаз и Налетчики Черноводья.",al={"who owns stranglethorn","who rules stv","stranglethorn factions","кто владеет тернистой долиной","кто правит тернистой долиной","фракции тернистой долины"}},{q="Что такое Пиратская бухта?",a="Пиратская бухта — раскинувшийся портовый город на южных утесах Мыса Тернистой долины. Первоначально это было человеческое поселение под названием Бухта Черноводья; его захватили тролли, а затем закрепил за собой Картель Хитрая Шестеренка. Сегодня барон Ревилгаз и командир флота Морской Рог управляют им как нейтральным торговым портом, связывающим путешественников с Кабестаном через Великое море.",al={"what is booty bay","booty bay port","who runs booty bay","что такое пиратская бухта","порт пиратская бухта","кто управляет пиратской бухтой"}},{q="Почему Полковник Курцен стал мятежником?",a="Полковник Курцен возглавил экспедицию в джунгли от имени Штормграда, но его разум подпал под власть Май'Зота, мага-огра с могущественной реликвией — Оком разума. Курцен становился все более непредсказуемым и деспотичным, и верные солдаты, такие как лейтенант Дорен, были вынуждены отделиться и создать Лагерь Повстанцев, чтобы остановить его.",al={"why is kurzen evil","what happened to kurzen","kurzen backstory","почему курцен злой","что случилось с курценом","история курцена"}},{q="Что такое Зул'Гуруб?",a="Зул'Гуруб — древняя столица Империи Гурубаши с множеством храмов, расположенная на северо-востоке Тернистой долины. Он был центром гражданской войны, положившей конец империи пятнадцать веков назад, после того как радикальные жрецы призвали кровавого бога Хаккара Свежевателя Душ. Хотя он давно заброшен и зарос лианами, темные ритуалы по-прежнему угрожают его залам.",al={"what is zg","zul gurub history","capital of gurubashi","что такое зг","история зул'гуруба","столица гурубаши"}},{q="Чем был Камень Приливов?",a="Камень Приливов — легендарная реликвия из древней истории Гурубаши, найденная на побережье троллем-воином. Он давал владельцу власть над водой и способность призывать элементалей, подобно могущественному магу, и владелец получал титул «Повелитель приливов». Однако камень нес проклятие: владелец постепенно исчезал из физического мира, и каждый обладатель в итоге уходил в море и пропадал.",al={"stone of the tides","tidebearer legend","gurubashi water stone","камень приливов","легенда о повелителе приливов","водяной камень гурубаши"}},{q="Как добраться до Тернистой долины?",a="Путники могут пройти на юг через речную границу из Сумеречного леса в северную часть Тернистой долины. У Орды есть прямые дирижабельные башни, соединяющие Лагерь Гром'гол с Дуротаром и Тирисфальскими лесами. Путешественники из Калимдора также могут сесть на регулярное торговое судно, плывущее между Кабестаном в Степях и Пиратской бухтой.",al={"how to get to stv","getting to stranglethorn","stv travel","как добраться до тернистой долины","путь в тернистую долину","дорога в тернистую долину"}}},fp="18,435,18.552.0,22.509.0,22.494.0,25.463.1,32.373.0,18.360.0,32.325.1,18.354.0,32.393.0,38.317.0"}
P.entries["zone:swampofsorrows"] = {n="Болото Печали",s="Болото Печали — мрачные солоноватые топи между Перевалом Мертвого Ветра и засушливыми Выжженными землями. Некогда северная часть древней Черной трясины, его покрытые соляной коркой болота населены опасными животными, зелеными драконидами и руинами Храма Атал'Хаккара, затонувшего в Озере Слез. Орда держит укрепленный гарнизон Каменор, а у Альянса в трясине нет безопасного убежища, и край остается в основном нетронутым.",h="Болото Печали — мрачные солоноватые топи между Перевалом Мертвого Ветра и засушливыми Выжженными землями.",kw={"black morass","broken","harborage","lost ones","pool of tears","sorrowmurk","stonard","sunken temple","swamp of sorrows","temple of atal'hakkar","черная трясина","сломленные","убежище","заблудшие","озеро слез","горемрак","каменор","затонувший храм","болото печали","храм атал'хаккара"},ang={["faction:Alliance"]="Без форпоста, вокруг которого можно собраться, путешествие по болоту — одинокое и враждебное предприятие, требующее тщательной подготовки в Темнолесье или Крепости Стражей Пустоты.",["faction:Horde"]="Каменор служит вашим важным передовым оплотом на южном континенте, откуда идут прямые маршруты на ветрокрылах в Каргат, Пламенеющий Стяг и Лагерь Гром'гол.",["profession:Blacksmithing"]="Выносливые искатели приключений могут добывать железо, золото, мифрил и истинное серебро в гористых скалах, обрамляющих северную и южную границы болота.",["profession:Herbalism"]="Болото — одно из немногих мест Азерота, богатых слепырником, а также обильными зарослями жизнекорня, бледнолиста и удавника.",["race:Troll"]="Затонувшие руины Атал'Хаккара — мрачное напоминание о темной магии крови, расколовшей Империю Гурубаши и навлекшей гнев Аспектов драконов."},sec={{t="Затонувшая история",b="Задолго до прихода Орочьей Орды эти топи составляли северную половину огромных болот, известных как Черная трясина. После распада Империи Гурубаши фанатичные тролли Атал'ай бежали в трясину, чтобы возвести Храм Атал'Хаккара и призвать своего кровожадного лоа, Хаккара Свежевателя Душ. Почувствовав надвигающуюся катастрофу, Аспект Изера применила свои силы и погрузила проклятую пирамиду в воды Озера Слез. Стражи зеленого драконьего рода во главе с Эраникусом были поставлены бдительно охранять затопленное строение. Когда позднее катаклизм Темного портала выжег южную часть трясины, превратив ее в Выжженные земли, эта северная топь получила свое нынешнее печальное название."},{t="Форпосты и изгнанники",b="Каменор — главный цивилизованный оплот в болоте. Основанный в годы Первой войны вместе с ныне разрушенными поселениями Рокард и Кайросс, форпост был отстроен заново при Тралле как самая южная опорная база Орды в Восточных королевствах. За частоколом Каменора по топям бродят странные существа. Группа дренеев, оказавшихся на Азероте, поддалась тоске по дому и безумию и выродилась в диких Заблудших. Однако небольшое поселение разумных Сломленных изгнанников держится в Убежище: они осторожны, но готовы мирно торговать с путниками."},{t="Зыбкая трясина",b="Чтобы выжить в болоте, нужна постоянная бдительность перед хищной фауной. В глубоких трясинах скрываются кроколиски, готовые к броску, ядовитые пауки, рыскающие болотные ягуары и бродячие болотные твари, покрытые илом и мусором. Прибрежные пещеры и Тростниковый берег кишат свирепыми мурлоками, а соленый прилив постоянно ползет вглубь суши, покрывая гнилые бревна толстой соляной коркой. Дальше на восток лежит Горемрак, где агрессивные элитные дракониды яростно охраняют подступы к Затонувшему храму и нападают на любого, кто подойдет к их посту."}},faq={{q="Как добраться до Болота Печали?",a="Самый распространенный наземный путь ведет на восток от Темнолесья в Сумеречном лесу, через опасное призрачное ущелье Перевала Мертвого Ветра и прямо вниз, в болото. Кроме того, путники с юга могут пойти на север по главной дороге из Выжженных земель.",al={"how to get to swamp of sorrows","swamp of sorrows road","getting to stonard","как добраться до болота печали","дорога в болото печали","как попасть в каменор"}},{q="Почему Храм Атал'Хаккара находится под водой?",a="Много веков назад жречество Атал'ай пыталось призвать Хаккара Свежевателя Душ в Азерот. Изера, Аспект зеленого драконьего рода, обнаружила их демонические кровавые обряды и затопила весь храм в болоте, чтобы предотвратить беду, оставив зеленых драконидов охранять погруженные залы.",al={"why is sunken temple sunk","who sank the temple","sunken temple lore","почему затонувший храм затонул","кто затопил храм","история затонувшего храма"}},{q="Что такое Каменор?",a="Каменор был одним из первых поселений Орочьей Орды после прохода через Темный портал в годы Первой войны. Хотя он был разорен в боях, недавно его вернули и отстроили по приказу Тралла, чтобы обеспечить снабжение Орды вблизи Выжженных земель.",al={"stonard history","orc base in swamp","who built stonard","история каменора","орочья база в болоте","кто построил каменор"}},{q="Есть ли здесь поселения Альянса?",a="Нет. У Альянса в Болоте Печали нет ни городов, ни стражи, ни маршрутов полета. Искатели приключений Альянса должны базироваться в Темнолесье в Сумеречном лесу на западе или в Крепости Стражей Пустоты в Выжженных землях на юге.",al={"alliance base swamp of sorrows","alliance flight path swamp","where is alliance camp","база альянса болото печали","полеты альянса болото","где лагерь альянса"}},{q="Кто эти странные мутировавшие гуманоиды в болоте?",a="Это дренеи, оказавшиеся на Азероте после обрушения Темного портала. Отрезанные от своего мира, большинство обезумели от отчаяния и превратились во враждебных Заблудших. Небольшая горстка разумных Сломленных изгнанников нашла приют на северо-западе, в Убежище, выбрав нейтральное выживание вместо бездумной ярости.",al={"who are the lost ones","what is the harborage","draenei in swamp","кто такие заблудшие","что такое убежище","дренеи в болоте"}},{q="Что такое Горемрак?",a="Горемрак — плотная полоса болот непосредственно к востоку от Озера Слез. Это место патрулирования элитных зеленых драконидов и драконят, которые яростно прогоняют смертных, оберегая тайны Затонувшего храма.",al={"dragon area swamp of sorrows","sorrowmurk dragons","green dragonspawn swamp","драконы болота печали","драконы горемрака","зеленые драконы болото"}}},fp="16,454,17.720.0,26.592.0,16.542.0,36.265.0,44.301.0,16.273.0,40.245.0,51.306.0,19.225.0"}
P.entries["zone:teldrassil"] = {n="Тельдрассил",s="Тельдрассил, что означает «Венец Земли», — исполинское новое Мировое Древо, выросшее у северо-западного побережья Калимдора. Выращенное друидами после Третьей войны, оно колоссальными ветвями поддерживает целую сумеречную глушь и столицу ночных эльфов Дарнасс. Но под его безмятежным, залитым лунным светом пологом начала шевелиться ползучая порча.",h="Тельдрассил, что означает «Венец Земли», — исполинское новое Мировое Древо, выросшее у северо-западного...",kw={"circle of ancients","crown of the earth","darnassus","dolanaar","fandral staghelm","rut'theran","shadowglen","teldrassil","world tree","круг древних","венец земли","дарнасс","доланаар","фэндрал олений шлем","рут'теран","тенистая долина","тельдрассил","мировое древо"},ang={["class:Druid"]="Пока Малфурион заточен в Изумрудном Сне, верховный друид Фэндрал Олений Шлем возглавляет здесь Круг Кенария, хотя многие друиды опасаются, что Тельдрассил вырастили поспешно.",["faction:Alliance"]="Тельдрассил служит самым северным оплотом Альянса в Калимдоре, обеспечивая морскую связь и торговлю между Дарнассом и материковыми королевствами.",["profession:Herbalism"]="Хотя минералов и руды здесь нет совсем, зеленый полог дерева с лихвой возмещает это, становясь раем для собирателей мироцвета, сребролиста и землекорня.",["race:NightElf"]="Это огромное дерево — новое начало вашего народа после разрушений на Горе Хиджал, но отсутствие благословения Аспектов делает его защиту неотложным долгом."},sec={{t="Полог над морем",b="Тельдрассил — не просто дерево, а возвышенная экосистема, вздымающаяся над водами Сокрытого Моря. Его исполинские ветви несут холмы, реки, питаемые утренней росой, туманные озера и густые древние рощи. На западном краю стоит Дарнасс, величественная столица кальдорай. У подножия могучего ствола лежит Деревня Рут'теран, соединенная с кроной наверху волшебным переходом и служащая главной гаванью острова."},{t="Отказ Аспектов",b="После гибели Нордрассила во время Третьей войны и таинственного исчезновения Шан'до Малфуриона Ярость Бури в Изумрудном Сне верховный друид Фэндрал Олений Шлем убедил Круг Древних вырастить замену. Олений Шлем надеялся вернуть кальдорай утраченное бессмертие. Однако Ноздорму и Аспекты драконов сочли эту затею дерзкой и отказали в благословении. Без их жизненно важной защиты рост Тельдрассила омрачен неестественными изъянами."},{t="Ползучий недуг",b="Несмотря на внешнее величие, юное Мировое Древо таит темную болезнь. Местные животные стали агрессивными: мирные племена фурболгов впали в безумие, уродливые греллы множатся в курганах, а мерзкие сатиры творят темные обряды в тенях вроде Пещеры Бесов. На берегах Темных берегов морские великаны, молотильщики и черепахи выбрасываются на сушу, спасаясь от оскверненных вод вокруг дерева. Натуралисты и стражи теперь лихорадочно трудятся на ветвях, пытаясь найти тень, медленно душащую их новый дом."}},faq={{q="Почему был выращен Тельдрассил?",a="После того как Нордрассил был разрушен в конце Третьей войны, ночные эльфы утратили бессмертие. Верховный друид Фэндрал Олений Шлем убедил Круг Древних и друидов Круга Кенария посадить в море новое Мировое Древо, надеясь вернуть то, что потерял их народ.",al={"why made","who made teldrassil","teldrassil origin","зачем создан тельдрассил","кто создал тельдрассил","происхождение тельдрассила"}},{q="Почему Тельдрассил не вернул ночным эльфам бессмертие?",a="Нордрассил даровал бессмертие, потому что его благословил Ноздорму, Вневременный. Когда был взращен Тельдрассил, Ноздорму счел желание ночных эльфов высокомерным и отказался дать новому дереву свое благословение.",al={"immortality","why not immortal","nozdormu blessing","бессмертие","почему не бессмертны","благословение ноздорму"}},{q="Как покинуть Тельдрассил?",a="Путникам нужно пройти через Дарнасс к розовому порталу в Храмовых садах, который переносит вниз, в Деревню Рут'теран у подножия ствола. Из Рут'терана корабль отплывает через море в Аубердин на материковых Темных берегах; также есть маршруты на гиппогрифах.",al={"how to get out","leave tree","teldrassil boat","как выбраться","покинуть дерево","корабль тельдрассил"}},{q="Почему в Тельдрассиле нет рудных жил?",a="Вся зона расположена на живых ветвях и древесине колоссального Мирового Древа, а не на природной континентальной породе. Поскольку здесь нет каменных подземных слоев, металлические жилы и залежи руды не образуются, зато травы растут в изобилии.",al={"where is copper","no ore","teldrassil mining","где медь","нет руды","добыча руды в тельдрассиле"}},{q="Что сводит с ума фурболгов и зверей?",a="Зловещее присутствие начало просачиваться в неблагословленные корни Тельдрассила. Болезнь осквернила местную воду и растения, приведя мирных древесников и племя фурболгов Гнилой Сосны в неистовую агрессию, а остатки сатиров намеренно разжигают порчу.",al={"corrupted furbolgs","gnarlpine mad","what is the corruption","оскверненные фурболги","безумие гнилой сосны","что за порча"}},{q="Что такое Тенистая долина?",a="Тенистая долина — укрытая уединенная лощина на восточных ветвях Тельдрассила, окружающая великое дерево Альдрассил. Это мирное убежище, где молодые ночные эльфы начинают обучение, прежде чем отправиться в большой мир.",al={"shadowglen","starting area","aldrassil zone","тенистая долина","стартовая зона","альдрассил"}}},fp="10,340,21.456.0,26.478.0,17.517.1,25.261.0,52.223.0,28.276.0,44.256.0,52.264.0,19.232.0"}
P.entries["zone:thousandneedles"] = {n="Тысяча Игл",s="Тысяча Игл — обширный каньон с отвесными песчаниковыми столбами и выжженными солнцем солончаками на юге Калимдора. Племена тауренов обитают в поселениях на вершинах высоких мезов, спасаясь от агрессивных кентавров, а гномы и гоблины-изобретатели гоняют на ракетных машинах по высохшему морскому дну Мерцающей равнины.",h="Тысяча Игл — обширный каньон с отвесными песчаниковыми столбами и выжженными солнцем солончаками на юге...",kw={"cliffwatcher longhorn","darkcloud pinnacle","fizzle brassbolts","freewind post","great lift","grimtotem","kravel koalbeard","mirage raceway","pozzik","shimmering flats","thousand needles","дозорный утесов долгорог","пик темного облака","пшикс медноштиф","застава вольного ветра","великий подъемник","зловещий тотем","крейвел углебрад","виражи на миражах","поззик","мерцающая равнина","тысяча игл"},ang={["faction:Horde"]="Великий Подъемник связывает Степи с вашим оплотом — Заставой Вольного Ветра — и служит стратегической южной границей против кентавров и мятежных тауренов.",["profession:Engineering"]="Солончак — место паломничества для изобретателей, желающих изучить ракетное топливо, детали машин и скоростные двигатели на Виражах на Миражах.",["race:Gnome"]="Виражи на Миражах на Мерцающей равнине — лучший шанс вашей фракции показать точность и изящество гномьей инженерии в сравнении с дрянными гоблинскими поделками.",["race:Tauren"]="Застава Вольного Ветра напоминает, как высоко вашему народу пришлось взобраться, спасаясь от кентаврской резни, и служит плацдармом против вероломного Зловещего Тотема на Пике Темного Облака."},sec={{t="Каменный лес",b="До того как Великий Раскол разрушил древний Калимдор, эта земля была цветущим речным каньоном, питаемым внутренними водными путями, что текли к морю. Катаклизм разорвал континент, поднял русло реки над уровнем грунтовых вод и изменил ее путь, так что остались лишь сухой камень и песчаниковые шпили. Сегодня десятки тонких цилиндрических колонн поднимаются со дна каньона, как окаменевший лес. Таурены поселились на вершинах, перебросив между пиками хлипкие веревочные мосты, и основали деревни, недоступные для враждебных кентавров-мародеров, что бродят по затененному дну каньона внизу."},{t="Опасность на мезах",b="На вершинах игловидных шпилей жизнь далека от мирной. На Заставе Вольного Ветра тауренам, верным Орде, приходится противостоять не только хищным ветрозмеям и вивернам из Скального гнездовья, но и вероломным сородичам: воинственному племени Зловещего Тотема, укрепившемуся на Пике Темного Облака. Дозорный утесов Долгорог руководит обороной плато и ищет отважных бойцов, чтобы бить агитаторов Зловещего Тотема и защищать хрупкие мосты между пиками. На севере огромные механические лебедки Великого Подъемника спускают путников с юга Степей, но путь по дну каньона по-прежнему смертельно опасен."},{t="Виражи на Миражах",b="На юго-востоке стены каньона расступаются, открывая Мерцающую равнину — огромный высохший солончак, лежащий ниже уровня моря. На этом суровом ослепительно белом просторе гномы и гоблины сохраняют шаткий нейтралитет вокруг Виражей на Миражах. Соперничающие инженеры Поззик и Пшикс Медноштиф гоняют на опытных ракетных машинах по твердой соли, выясняя, какая раса превосходит другую в технике. Пит-стоп привлекает проходимцев, мошенников вроде Крейвела Углебрада и охотников на выносливых скорпионов, черепах и василисков, что бродят по раскаленной котловине."}},faq={{q="Откуда появилось название Тысяча Игл?",a="Название зоне дали десятки огромных цилиндрических песчаниковых шпилей, поднимающихся со дна каньона. Эти геологические башни, некогда вырезанные быстрыми речными течениями до Великого Раскола, теперь напоминают лес гигантских игл.",al={"why is it called thousand needles","needle pillars origin","spires lore","почему называется тысяча игл","происхождение каменных столбов","шпили история"}},{q="Как попасть в Тысячу Игл из Степей?",a="Путники пользуются Великим Подъемником — огромным лифтом с двумя кабинами, который обслуживают стражи Орды на южной границе Степей. Шагнуть с края — верная смерть, поэтому нужно дождаться платформы. Путники из Альянса могут также дойти с запада через Таланаар в Фераласе.",al={"how to get to thousand needles","great lift entrance","elevator to needles","как попасть в тысячу игл","великий подъемник вход","лифт в тысячу игл"}},{q="Почему таурены живут на вершинах мезов?",a="Отряды кентавров когда-то едва не истребили кочевых тауренов. Форпосты вроде Заставы Вольного Ветра на неприступных каменных столбах защищали их от наземных атак. Мезы соединили деревянными подвесными мостами, и передвигаться стало можно на высоте, над хищниками и налетчиками внизу.",al={"why are tauren on pillars","freewind post history","tauren high ground","почему таурены на столбах","история заставы вольного ветра","высота тауренов"}},{q="Что такое Виражи на Миражах?",a="Виражи на Миражах — инженерный полигон на солончаке Мерцающей равнины. Гномы и гоблины-изобретатели гоняют по ровному соляному дну на опытных ракетных гоночных машинах, решая давний спор о том, какая раса строит лучшие механизмы.",al={"salt flats track","gnome goblin race","rocket car track","соляная трасса","гномы гоблины гонки","трасса ракетных машин"}},{q="Что собой представляет присутствие Зловещего Тотема в каньоне?",a="Племя Зловещего Тотема занимает Пик Темного Облака — укрепленную группу шпилей прямо напротив Заставы Вольного Ветра. В отличие от остальных тауренских племен, присягнувших Орде, Зловещий Тотем нападает на других тауренов и замышляет захватить власть над мезами.",al={"grimtotem thousand needles","darkcloud pinnacle tauren","evil tauren needles","зловещий тотем тысяча игл","пик темного облака тауренов","злые тауренов иглы"}},{q="Что такое Мерцающая равнина?",a="Мерцающая равнина — обширное высохшее озеро к востоку от мезов каньона. Соляная корка образовалась, когда после Раскола испарилось древнее внутреннее море. Палящий зной, ослепительно белая соль и свирепые хищники делают ее негостеприимной пустыней, которую используют в основном для испытаний быстрых машин.",al={"salt pan","white desert needles","eastern desert","солончак","белая пустыня тысяча игл","восточная пустыня"}}},fp="16,315,17.605.0,18.606.0,18.558.0,38.246.0,59.275.0,43.301.0,27.259.0,45.264.0,30.290.0"}
P.entries["zone:thunderbluff"] = {n="Громовой Утес",s="Громовой Утес — великолепная столица тауренов, раскинувшаяся на вершинах продуваемых ветрами красных плато над равнинами Мулгора. Основанный верховным вождем Кэрном Кровавым Копытом после объединения кочевых племен при помощи Новой Орды, он служит культурным, духовным и торговым сердцем его народа. Соединенный качающимися веревочными мостами и деревянными подъемниками, город дает защиту от набегов кентавров и мирное убежище путникам со всего Калимдора.",h="Громовой Утес — великолепная столица тауренов, раскинувшаяся на вершинах продуваемых ветрами красных плато...",kw={"cairne bloodhoof","elder rise","elevators","hamuul runetotem","hunter rise","magatha grimtotem","mulgore","pools of vision","spirit rise","thunder bluff","кэрн кровавое копыто","вершина старейшин","подъемники","хамуул рунический тотем","вершина охотников","магата зловещий тотем","мулгор","пруды видений","вершина духов","громовой утес"},ang={["class:Druid"]="Вершина Старейшин — главное убежище магии природы Орды, которым руководит верховный друид Хамуул Рунический Тотем, первый за тысячи лет обученный таурен-друид.",["class:Shaman"]="Вершина Духов и подземные Пруды Видений — безмятежное средоточие, где почитают и слышат духов стихий и духов предков тауренов.",["faction:Horde"]="Гораздо более спокойный и духовный, чем суровые бастионы Оргриммара, Громовой Утес служит пасторальным оплотом влияния Новой Орды на юге Калимдора.",["race:Tauren"]="Громовой Утес олицетворяет с трудом завоеванное единство и возрождение вашего народа после многих поколений кочевых скитаний и притеснений со стороны кентавров под началом верховного вождя Кэрна Кровавого Копыта."},sec={{t="Постоянное убежище",b="На протяжении бесчисленных поколений таурены жили кочевниками по всему Калимдору, ведя жестокую борьбу за выживание с лютыми кентаврскими племенами. Эта отчаянная эпоха закончилась в Третью войну, когда Кэрн Кровавое Копыто объединил силы с вождем Траллом. Вместе орки и таурены отразили натиск кентавров и отстояли тучные пастбища Мулгора. Чтобы защитить будущее, Кэрн привел союзные племена в безопасность этих природных каменных бастионов и основал Громовой Утес — первый за века единый постоянный дом тауренов."},{t="Город в облаках",b="Громовой Утес раскинулся на нескольких высоких мезах, соединенных подвесными веревочными мостами, и гармонично сочетает природную архитектуру с практичностью тауренов. На центральных утесах расположены оживленные рынки, банк, таверна и высокий насест ветрокрылов, а три особые мезы отходят над пропастью. Вершина Охотников служит разведчикам и следопытам города; на Вершине Старейшин живут хранители преданий и Круг Кенария под началом верховного друида Хамуула Рунического Тотема; Вершина Духов посвящена духовному общению: там обитают шаманы, жрецы и таинственные подземные пещеры, известные как Пруды Видений."},{t="Шаткое единство",b="Хотя Кэрн Кровавое Копыто пользуется огромным уважением почти у всех племен, управлять недавно осевшим гордым народом нелегко без трений. В частности, Племя Зловещего Тотема, во главе которого стоит проницательная и острая на язык Мудрая старуха Магата Зловещий Тотем, мрачно присутствует на Вершине Старейшин. Магата открыто ставит под сомнение примирительные методы Кэрна и его верность чужеземным расам Орды. Хотя мир сохраняется под бдительным взором вождя, идеологические расколы тихо ропщут у костров совета над равнинами."}},faq={{q="Кто правит Громовым Утесом?",a="Громовым Утесом правит верховный вождь Кэрн Кровавое Копыто, предводитель объединенных тауренских племен. Почитаемый за мудрость, терпение и огромную силу, Кэрн основал город после союза с Ордой Тралла и изгнания кентавров из Мулгора.",al={"leader of thunder bluff","who is in charge","thunder bluff chieftain","cairne","правитель громового утеса","кто главный","вождь громового утеса","кэрн"}},{q="Как подняться в Громовой Утес?",a="Гости, пришедшие пешком или на кодо, поднимаются на огромных деревянных платформенных подъемниках на юго-западной и северо-восточной сторонах центрального меза. Кроме того, в городе есть насест ветрокрылов с маршрутами полетов по всему Калимдору.",al={"thunder bluff elevator","how to get in","thunder bluff entrance","getting up","лифт громовой утес","как попасть","вход в громовой утес","подъем"}},{q="Почему таурены построили город на высоких мезах, а не на земле?",a="Века кочевой жизни были отмечены непрерывными налетами агрессивных кентаврских кланов. Отвесные обрывы утесов Мулгора дают естественную защиту, оберегая жилища, кузни и священных старейшин тауренов от засад с земли и позволяя им мирно осесть навсегда.",al={"why mesas","why are they on cliffs","thunder bluff cliffs","tauren high ground","почему мезы","почему на утесах","утесы громового утеса","тауренов высота"}},{q="Какие вершины есть в городе?",a="Город раскинулся на центральном мезе (с нижним, средним и верхним ярусами), окруженном тремя внешними мезами. Вершина Охотников отведена воинам, охотникам и охотничьим домам. На Вершине Старейшин живут друиды, мудрецы и племя Зловещего Тотема. На Вершине Духов находятся святилища Матери-Земли, наставники шаманов, жрецов и магов и пещерные Пруды Видений.",al={"thunder bluff areas","what are the rises","districts of thunder bluff","районы громового утеса","какие вершины","части громового утеса"}},{q="Что такое Пруды Видений?",a="Пруды Видений — священные подземные пещеры под Вершиной Духов. Тауренские провидцы, ходящие по духам, и знатоки тайной магии собираются у этих тихих, окутанных туманом вод, чтобы говорить со стихиями и толковать знамения о будущем своего народа.",al={"pools of vision","spirit rise cave","thunder bluff cave","пруды видений","пещера вершины духов","пещера громового утеса"}},{q="Кто такая Магата Зловещий Тотем?",a="Магата Зловещий Тотем — матриарх и Мудрая старуха могущественного племени Зловещего Тотема. Хотя она живет на Вершине Старейшин и внешне участвует в совете Кэрна, она яростно привержена традициям, не доверяет чужакам и тихо оспаривает мягкую позицию племени Кровавого Копыта в отношении Орды.",al={"magatha","elder crone","who is the grimtotem leader","магата","мудрая старуха","кто вождь зловещего тотема"}}},fp="13,473,17.558.0,20.575.0,12.516.1,24.238.0,35.236.0,61.300.0,41.364.0,29.270.0,25.291.0"}
P.entries["zone:tirisfal"] = {n="Тирисфальские леса",s="Тирисфальские леса — мрачные северные земли Лордерона, ныне сердце владений леди Сильваны Ветрокрылой и Отрекшихся. Под отравленными небесами и гнилыми ветвями лежат разрушенные усадьбы, спящие склепы и огромная подземная столица — Подгород. В окружении безмозглой Плети и фанатичных рыцарей Алого ордена это опасный край, где свободная нежить борется за выживание.",h="Тирисфальские леса — мрачные северные земли Лордерона, ныне сердце владений леди Сильваны Ветрокрылой и...",kw={"agamand","balnir","brill","deathknell","forsaken","glades","lordaeron","scarlet crusade","sylvanas","tirisfal","tyr","undercity","агамонд","балнир","брилл","могильник","отрекшиеся","леса","лордерон","алый орден","сильвана","тирисфаль","тир","подгород"},ang={["class:Priest"]="Здесь лежат исторические святыни, например Могила Фаола — гробница архиепископа Алонсуса Фаола, основателя Серебряной Длани, — искаженные смертью и оспариваемые фанатиками и жрецами Тьмы.",["faction:Alliance"]="Для уцелевших государств Альянса Тирисфаль — трагический памятник падению Лордерона, полный оскверненных гробниц бывших братьев и сестер по вере.",["faction:Horde"]="Тирисфаль — важный оплот Орды на севере Восточных королевств: он поддерживает дипломатические связи с Отрекшимися и сдерживает человеческих экстремистов и Плеть.",["race:Undead"]="Это ваша родина предков вдвойне: королевство, которое вы построили при жизни, и хрупкое убежище, которое вы должны защищать в нежизни под началом леди Сильваны."},sec={{t="Земля в сумерках",b="Некогда плодородная колыбель человечества, Тирисфальские леса увяли под проклятием чумы Короля-лича. Солнце редко пробивается сквозь мутный мрак, заливая умирающие рощи, заброшенные тыквенные поля и холодные прибрежные холмы вечной болезненной бледностью. От старых ферм, таких как Мельницы Агамондов и Ферма Балнира, остались лишь следы, а их прежние хозяева в основном легли в братские могилы или восстали беспокойными мертвецами. Несмотря на разруху, по округе разлита мрачная стойкость: ее опорой служат такие поселения, как Брилл, и уединенный Могильник, где недавно пробудившиеся Отрекшиеся учатся переносить вторую жизнь."},{t="Война на два фронта",b="Хотя леди Сильвана Ветрокрылая правит этим краем из подземных Руин Лордерона, Отрекшиеся окружены врагами. Остатки рабов Плети по-прежнему кишат в лощинах, полях и полуразрушенных склепах, всецело подчиняясь ледяному трону Нордскола. На востоке фанатичный Алый орден превратил север Тирисфаля в свой главный оплот, действуя из Монастыря Алого ордена. Его последователи одержимы истреблением всякой нежити, живой и неживой, и их форпосты и патрули ведут постоянную партизанскую войну против разведчиков Отрекшихся и мирных путников."},{t="Отголоски древнего прошлого",b="Задолго до того, как у людских королевств появились первые монархи, эти леса хранили древнее наследие. На древнем языке врайкулов «Тирисфаль» означает «Падение Тира»: так назвали место в память о герое, хранителе титанов Тире, сражавшемся насмерть с исполинскими космическими ужасами. В последующие эпохи изгнанники-высшие эльфы ненадолго пытались поселиться в этих лесах, но темные силы глубоко под землей стали сводить их с ума, и они ушли на север. Спустя века тайный круг смертных, Совет Тирисфаля, избрал эти сумрачные рощи, чтобы наделять силой одиноких Стражей, защищавших Азерот от вторжения демонов."}},faq={{q="Почему небо зеленое, а земля гниет?",a="Во время Третьей войны принц Артас и Плеть обрушили Чуму нежизни на Королевство Лордерон. Магическая зараза отравила не только население, но и почву, деревья и воду, оставив леса в вечном жутком, болезненном упадке.",al={"why is tirisfal blighted","what happened to tirisfal","why is tirisfal dying","почему тирисфаль заражен","что случилось с тирисфалем","почему тирисфаль умирает"}},{q="Чем здесь Отрекшиеся отличаются от Плети?",a="Отрекшиеся — нежить, освободившаяся от телепатического господства Короля-лича после битвы на Горе Хиджал и по своей воле последовавшая за леди Сильваной Ветрокрылой. Плеть, бродящая по фермам и руинам, остается безвольными рабами, подчиненными приказам Короля-лича.",al={"forsaken vs scourge","why are zombies attacking undead","are all undead evil","отрекшиеся и плеть","почему зомби нападают на нежить","вся ли нежить зла"}},{q="Кто эти солдаты в красных доспехах, нападающие на путников?",a="Они принадлежат Алому ордену — непримиримому расколу бывших паладинов Серебряной Длани и выживших. Убежденные, что вся нежить — неисправимые мерзости, подлежащие очищению мечом и огнем, они с фанатичной ненавистью убивают и безвольных рабов, и свободных Отрекшихся.",al={"scarlet crusade","red humans","monastery humans","алый орден","красные люди","люди из монастыря"}},{q="Откуда взялось название Тирисфаль?",a="Край назван в честь хранителя титанов Тира. По легенде, Тир пал в бою с жуткими ужасами именно в этих лесах. На древнем языке врайкулов «Падение Тира» превратилось в название «Тирисфаль», а серебряная длань хранителя стала символом, глубоко вплетенным в ранние человеческие мифы.",al={"tirisfal meaning","tyrs fall","origin of tirisfal","значение тирисфаль","падение тира","происхождение названия тирисфаль"}},{q="Где начинают путь недавно пробудившиеся Отрекшиеся?",a="Недавно пробудившиеся Отрекшиеся выходят из склепов Мрачного склепа в Могильнике — уединенном поселении на юго-западе Тирисфаля. Там управители и исполнители оценивают, обладают ли восставшие мертвецы здравым рассудком и преданностью, нужными для службы Темной Госпоже.",al={"undead starting zone","where is deathknell","forsaken starting area","стартовая зона нежити","где могильник","стартовая зона отрекшихся"}},{q="Как путники покидают Тирисфаль и отправляются на другие континенты?",a="На склоне холма к югу от Брилла, рядом с Руинами Лордерона, расположена большая гоблинская дирижабельная башня. Эти дирижабли обеспечивают прямое регулярное сообщение через моря с Оргриммаром в Калимдоре и Лагерем Гром'гол в Тернистой долине.",al={"tirisfal zeppelins","how to get to orgrimmar","how to get to stranglethorn","дирижабли тирисфаля","как добраться до оргриммара","как добраться до тернистой долины"}}},fp="15,403,18.637.0,19.603.0,26.621.0,42.269.0,65.287.0,53.289.0,39.297.0,53.269.0,53.247.0"}
P.entries["zone:undercity"] = {n="Подгород",s="Глубоко под разрушенными руинами Столицы Лордерона лежит Подгород — темная твердыня Отрекшихся. Первоначально Плеть вырыла его из древних королевских склепов и темниц, но леди Сильвана Ветрокрылая захватила его и превратила в неприступное подземное убежище. Сегодня это средоточие власти Отрекшихся и важный оплот Орды на севере Восточных королевств.",h="Глубоко под разрушенными руинами Столицы Лордерона лежит Подгород — темная твердыня Отрекшихся.",kw={"apothecarium","arthas","forsaken","lordaeron","scourge","sylvanas","terenas","tirisfal","undercity","varimathras","апотекариум","артас","отрекшиеся","лордерон","плеть","сильвана","теренас","тирисфаль","подгород","вариматрас"},ang={["faction:Horde"]="Как главный плацдарм Орды в Восточных королевствах, Подгород обеспечивает прямое дирижабельное сообщение с Дуротаром и Лагерем Гром'гол.",["race:Human"]="Под землей вашего павшего королевства предков лежит мрачное извращение королевских склепов Лордерона, населенное ходячими трупами ваших бывших собратьев.",["race:Orc"]="Именно в этих темницах Альянс Лордерона когда-то держал в заключении легендарного вождя Оргрима Молота Рока, пока тот не совершил свой исторический побег.",["race:Undead"]="Подгород — ваше суверенное убежище и родина, созданная вашими собственными руками после того, как вы вырвались из железной хватки Короля-лича над вашим разумом."},sec={{t="От королевских склепов до оплота Плети",b="Задолго до того, как Лордерон поразила чума, катакомбы, темницы и канализация под дворцом были известны как Подгород. Там находились гробницы знати, самые глубокие тюрьмы королевства — где был заключен прежний вождь Оргрим Молот Рока до своего побега — и жили беднейшие обитатели державы. Когда Артас Менетил убил короля Теренаса и разорил столицу в 20 году после открытия Портала, принц приказал своим мертвым слугам расширить подземные ходы и превратить их в укрепленную обитель власти Плети."},{t="Восход Отрекшихся",b="Плеть так и не увидела свою темную столицу завершенной. Когда после битвы на Горе Хиджал силы Короля-лича ослабли, леди Сильвана Ветрокрылая вырвалась из коллективного разума и увела с собой тысячи нежити. Она заманила Артаса в засаду и прогнала его обратно в Нордскол. После жестокой гражданской войны на три стороны — против остатков Плети, повелителей ужаса и человеческого сопротивления — Сильвана завладела недостроенными катакомбами. Назвав свой народ Отрекшимися, она руководила многолетними работами по завершению обширного подземного города."},{t="Архитектура Проклятых",b="Подгород устроен как концентрические кольца, разделенные на функциональные кварталы. В его сердце лежит Торговый квартал, соединенный большими подъемниками с руинами дворца наверху. Вокруг него расположены Военный квартал, Квартал разбойников, Магический квартал и ядовитый Апотекариум, где Королевское фармацевтическое общество варит смертоносные чумы в каналах, залитых зеленой слизью. Еще глубже находится Королевский квартал, где Королева банши держит двор вместе со своим командиром-повелителем ужаса Вариматрасом под охраной легионов громадных чудовищ."}},faq={{q="Чем был Подгород до захвата нежитью?",a="Под дворцом Лордерона находились древние склепы человеческих королей, а также комплекс темниц и обширная сеть канализации. Там содержались военнопленные, в том числе Оргрим Молот Рока, и жили нищие горожане, обитавшие в подземной тени. Разграбив столицу, принц Артас начал превращать эти катакомбы в крепость Плети, пока их не захватила Сильвана.",al={"undercity origins","what was undercity originally","lordaeron sewers history","происхождение подгорода","чем был подгород раньше","история канализации лордерона"}},{q="Почему город построен под землей, а не на поверхности?",a="Наземный город Лордерон был полностью разрушен в Третью войну, и его было трудно защищать от Алого ордена, сил Плети и уцелевших из Альянса. Подземные туннели давали естественную защиту, узкие проходы и скрытность, позволив Отрекшимся завершить начатое Плетью строительство и процветать незаметно.",al={"why live underground","why not rebuild lordaeron","why undercity beneath ruins","почему жить под землей","почему не отстроить лордерон","почему подгород под руинами"}},{q="Кто правит Подгородом?",a="Городом правит леди Сильвана Ветрокрылая, Королева банши и королева Отрекшихся. Она управляет из Королевского квартала под охраной королевских стражей Отрекшихся и своего покоренного помощника-повелителя ужаса Вариматраса.",al={"who is leader of undercity","undercity ruler","who runs undercity","кто лидер подгорода","правитель подгорода","кто управляет подгородом"}},{q="Что за памятник королю Теренасу в руинах наверху?",a="Над главными подъемниками города стоит каменный памятник убитому королю Теренасу Менетилу II. Тела в нем нет: труп был сожжен, а прах развеян при воскрешении Кел'Тузада. Уцелевшие люди Альянса мужественно возвели монумент среди руин, чтобы память о последнем истинном короле Лордерона сохранилась.",al={"king terenas tomb","lordaeron throne room grave","who built the tomb above undercity","гробница короля теренаса","могила в тронном зале лордерона","кто построил гробницу над подгородом"}},{q="Что за странные звуки в тронном зале Лордерона?",a="В разрушенном тронном зале над подъемниками Подгорода все еще блуждают призрачные отголоски прошлого. Стоя в центре, посетители слышат слабые призрачные звуки: праздничный звон колоколов и лепестки роз в честь возвращения Артаса, предостерегающие слова пророка Медива и последний разговор короля Теренаса с сыном, ставшим его убийцей.",al={"ghost sounds throne room","throne room whispering","voices in lordaeron throne room","призрачные звуки тронного зала","шепот в тронном зале","голоса в тронном зале лордерона"}},{q="Почему Отрекшиеся пускают сюда других представителей Орды?",a="Отрекшиеся заключили с Ордой вождя Тралла союз по расчету ради выживания, будучи окружены враждебными фанатиками Алого ордена и легионами Плети. Хотя живым расам Орды ядовитые испарения и алхимические реки кажутся невыносимыми, послам и путникам позволяют входить ради дипломатических и военных связей.",al={"why are orcs in undercity","horde in undercity","why is undercity part of horde","почему орки в подгороде","орда в подгороде","почему подгород часть орды"}}},fp="9,400,36.527.0,20.525.0,26.518.0,54.383.0,60.340.0,24.216.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Кратер Ун'Горо",s="Кратер Ун'Горо — глубокие первобытные джунгли, затерянные между засушливыми пустошами Танариса и Силитуса. В этой пышной кальдере, где господствуют бродящие динозавры, живые элементали и центральный вулкан, множество древних реликвий Титанов и кристаллов силы, происхождение которых остается великой тайной.",h="Кратер Ун'Горо — глубокие первобытные джунгли, затерянные между засушливыми пустошами Танариса и Силитуса.",kw={"devilsaur","fire plume ridge","god lands","lakkari","marshal's refuge","power crystals","torwa pathfinder","ungoro","ungoro crater","дьявозавр","вулкан огненного венца","земли богов","лаккари","укрытие маршалла","кристаллы силы","ун'горо","кратер ун'горо"},ang={["class:Druid"]="Друиды Круга Кенария изучают обособленную экосистему Ун'Горо и собирают ее плодородную землю для выращивания зари-зерна, стремясь постичь чистую, неукрощенную жизненную силу, питающую кальдеру.",["faction:Alliance"]="Натуралисты Альянса собираются вокруг Виллидена Маршала и Дж. Д. Колли в Укрытии Маршалла, стараясь расшифровать пилоны Титанов и защищая исследователей из Дарнасса, собирающих образцы почвы.",["faction:Horde"]="Искатели приключений Орды часто прибывают через Танарис, чтобы испытать силы против легендарных дьявозавров и помочь травникам Громового Утеса выращивать зарю-зерно на первобытной земле Ун'Горо.",["profession:Herbalism"]="Богатая влага котловины питает редкую флору: это одно из немногих мест в Калимдоре, где вместе растут слепырник, снолист и золотой сансам, а на склонах вулкана — огнецвет.",["profession:Mining"]="Отвесные стены кратера и скалы Вулкана Огненного Венца изобилуют залежами мифрила и богатыми залежами тория, что делает зону лучшим местом для добычи высококачественной руды."},sec={{t="Земли богов",b="Зажатый между просторами пустынь, Кратер Ун'Горо противоречит географии южного Калимдора. В древних записях ночных эльфов о Войне Зыбучих Песков отмечено, что насекомоподобных киражей остановили на краях кратера: они не смогли проникнуть туда, что на их языке называлось «Землями Богов». Ученые полагают, что кальдера служила Титанам испытательной площадкой или древним обиталищем при создании Калимдора. Вдоль хребтов возвышаются каменные пилоны, гудящие от энергии, а сквозь первобытную землю пробиваются кристаллы синего, красного, зеленого и желтого цветов."},{t="Дикая экосистема",b="В Ун'Горо нет ни городов, ни поселков, ни коренных гуманоидных обществ. Вместо этого жизнь процветает в диком, первобытном состоянии. Свирепые дьявозавры бродят по равнинам Пути Ужаса, хищные кровавики хлещут в болотах, а слизни ползают по смоляным ямам Лаккари. В сердце кратера высится Вулкан Огненного Венца — действующий вулкан, кишащий враждебными элементалями огня под предводительством Пышущего Бегуна. Для исследователей и свежевателей эта котловина таит несравненные природные богатства, включая ценные шкуры дьявозавров, если только удастся пережить пищевую цепь."},{t="Укрытие Маршалла",b="Цивилизованное присутствие в кратере почти полностью ограничено Укрытием Маршалла — лагерем на возвышенности в северных скалах. Экспедиция ученых, натуралистов и искателей удачи под началом Виллидена Маршала пыталась описать сокровища котловины, но была разбита чудовищной живностью и вынуждена отступить на высоты. Сегодня укрытие служит осажденным оплотом для отважных путников, изучающих загадочные кристаллы силы кратера, наблюдающих за вулканической активностью и следящих за наступающими роями силитидов, проникающими через южные гряды."}},faq={{q="Как попасть в кратер Ун'Горо?",a="В кратер можно войти по естественным спускам вдоль его стен: один доступен из юго-западного угла Танариса возле Долины Кактусов, другой ведет с северо-востока Силитуса. Безрассудные искатели приключений иногда прыгают со скал, но без магической помощи падение смертельно. Из Укрытия Маршалла на севере есть воздушное сообщение с Прибамбасском и Крепостью Кенария.",al={"how to enter ungoro","ungoro entrance","how to reach ungoro crater","как попасть в ун'горо","вход в ун'горо","как добраться до кратера ун'горо"}},{q="Для чего нужны цветные кристаллы силы?",a="По дну джунглей разбросаны красные, синие, зеленые и желтые кристаллы силы. С помощью гнома-исследователя Дж. Д. Колли из Укрытия Маршалла исследователи могут расшифровать указания по использованию этих кристаллов у Северного, Восточного и Западного пилонов. Сочетая определенные цвета у нужных пилонов, можно использовать скрытую энергию Титанов и создавать защитные или целебные амулеты.",al={"ungoro crystals","red blue green yellow crystals ungoro","power pylons","кристаллы ун'горо","красные синие зеленые желтые кристаллы ун'горо","пилоны силы"}},{q="Почему Ун'Горо пышно зеленеет, хотя его окружают пустыни?",a="Ученые полагают, что необычайное буйство жизни в Ун'Горо искусственное и обязано Титанам, сформировавшим мир. Титанические каналы, теплая геотермальная активность Вулкана Огненного Венца и древняя энергия силовых линий питают обособленную, стремительно развивающуюся экосистему, которая противостоит засушливым условиям соседних Танариса и Силитуса.",al={"why is ungoro a jungle","ungoro desert connection","how does ungoro have plants","почему ун'горо джунгли","ун'горо и пустыня","почему в ун'горо растут растения"}},{q="Почему киражи называли это место «Землями Богов»?",a="Согласно табличкам, переведенным из записей о Войне Зыбучих Песков, рои насекомых остановили свое наступление на пороге кратера. Геолог Жаворонкова Погибель, переводившая этот рассказ, связывает название с теориями о том, что Титаны когда-то обитали в кратере, и задается вопросом, не сам ли Аман'Тул оберегал Земли богов.",al={"god lands meaning","qiraji ungoro","why couldn't silithid take ungoro","земли богов значение","киражи ун'горо","почему силитиды не смогли захватить ун'горо"}},{q="Для чего нужна Земля Ун'Горо?",a="По котловине кратера разбросаны кучи плодородной, насыщенной силой земли. Собранную землю можно вместе с семенами тарлендриса поместить в Суму вечного цветения и вырастить зарю-зерно — волшебную траву, которую усиленно ищут исследователи в Громовом Утесе, Дарнассе и Круге Кенария.",al={"ungoro soil sample","what does ungoro soil do","morrowgrain soil","земля ун'горо","для чего земля ун'горо","заря-зерно земля"}},{q="Есть ли здесь поселения гуманоидов или подземелья?",a="В кратере Ун'Горо нет ни подземелий, ни коренных гуманоидных обществ. Единственное постоянное поселение — Укрытие Маршалла, небольшой лагерь экспедиции на северном краю. Не считая отдельных охотников-отшельников или заблудившихся исследователей, остальная кальдера совершенно дика.",al={"ungoro dungeons","who lives in ungoro","humanoids in ungoro","подземелья ун'горо","кто живет в ун'горо","гуманоиды в ун'горо"}}},fp="14,289,13.564.0,18.559.0,16.579.0,35.395.0,45.390.0,56.325.0,51.316.0,30.275.0,52.274.0"}
P.entries["zone:westernplaguelands"] = {n="Западные Чумные земли",s="Некогда плодородная житница северного Лордерона, Западные Чумные земли теперь задыхаются под ядовитой дымкой и легионами нежити. Хотя котлы Кел'Тузада погубили фермы и города региона, земля все еще упорно цепляется за жизнь. Серебряный Рассвет, Альянс, Отрекшиеся и Алый орден ведут по его зараженным полям отчаянные кампании.",h="Некогда плодородная житница северного Лордерона, Западные Чумные земли теперь задыхаются под ядовитой дымкой...",kw={"andorhal","bulwark","caer darrow","cauldrons","chillwind camp","hearthglen","mardenholde keep","scholomance","uther's tomb","western plaguelands","андорал","бастион","каэр дарроу","котлы","лагерь промозглого ветра","дольный очаг","крепость марденхольд","некроситет","гробница утера","западные чумные земли"},ang={["class:Paladin"]="Оскверненные поля Лордерона — мрачное испытание для священных воинов: здесь можно совершить паломничество к Гробнице Утера и вести праведную войну против ужасов Некроситета и оскверненных фанатиков Дольного Очага.",["faction:Alliance"]="Лагерь Промозглого Ветра служит передовым гарнизоном Альянса, где командир Ашлам Смелонрав руководит кампаниями по уничтожению чумных котлов и мести за павшие города Лордерона.",["faction:Horde"]="Бастион отмечает границу владений Отрекшихся; отсюда Орда продвигается на восток, чтобы уничтожить командиров Плети и теснить фанатиков Алого ордена на их уязвимом фланге.",["profession:Herbalism"]="Остаточная порча делает этот регион одним из немногих мест, где редкие и опасные растения, такие как Чумоцвет и Слезы Артаса, могут укорениться среди зараженных сосновых рощ."},sec={{t="Житница Лордерона",b="До Третьей войны эта земля представляла собой зеленый пояс ферм, протянувшийся на восток от Тирисфальских лесов к Озеру Дарроумир. Дольный Очаг управлял северными областями из Крепости Марденхольд, а раскинувшийся город Андорал занимался хранением и вывозом зерна по всему королевству. Эта важнейшая роль сделала регион главной целью Кел'Тузада. Занеся Чуму нежизни прямо в партии зерна в Андорале, Культ Проклятых превратил пропитание Лордерона в его гибель."},{t="Земля в осаде",b="To permanently poison the soil, the Scourge raised four massive plague cauldrons across the largest agricultural estates: Felstone Field, Dalson's Tears, the Writhing Haunt, and Gahrron's Withering. Today, monstrous Cauldron Lords maintain these noxious vats, pumping venomous fog into the atmosphere. The surrounding trees twist with swollen, tumorous growths, and blighted wildlife rampages through the brush. Beneath Caer Darrow on Darrowmere Lake, Darkmaster Gandling trains necromancers within Scholomance, compounding the undead threat."},{t="Разделенные фракции",b="Несмотря на повсеместное присутствие Плети, несколько фракций удерживают осажденные оплоты. Алый орден контролирует крепость Дольный Очаг на севере, беспощадно очищая все, что сочтет оскверненным. На юге силы Альянса действуют из Лагеря Промозглого Ветра, а Отрекшиеся защищают свои границы у Бастиона. Борьбой с котлами нежити руководит нейтральный Серебряный Рассвет, помогающий героям обеих фракций и охраняющий Гробницу Утера — последнюю по-настоящему освященную землю региона."}},faq={{q="Почему Чума так сильно поразила эти земли?",a="Андорал был центром отправки сельскохозяйственной продукции северного Лордерона. Кел'Тузад намеренно ударил по снабжению региона: заразил зернохранилища и установил огромные чумные котлы на четырех крупных фермах, чтобы быстро распространить нежизнь с продовольствием по всему королевству.",al={"why is western plaguelands plagued","what happened to andorhal","why cauldrons here","почему западные чумные земли заражены","что случилось с андоралом","почему здесь котлы"}},{q="Кто управляет Дольным Очагом на севере?",a="Дольным Очагом и его крепостью, Крепостью Марденхольд, правит Алый орден. Хотя изначально это был областной административный центр Лордерона, фанатики теперь казнят всех чужаков, приближающихся к их границам, и подозревают каждого, кто не входит в орден.",al={"hearthglen faction","who lives in mardenholde keep","is hearthglen friendly","дольный очаг фракция","кто живет в крепости марденхольд","дружелюбен ли дольный очаг"}},{q="Где игроки Альянса и Орды могут найти безопасные лагеря?",a="Альянс держит Лагерь Промозглого Ветра у южной границы с Альтеракскими горами: там есть распорядитель полетов и союзники из Серебряного Рассвета. Орда действует из Бастиона на западной границе, откуда есть вход из Тирисфальских лесов.",al={"where are the flight paths","horde camp wpl","alliance camp wpl","где пути полета","лагерь орды западные чумные земли","лагерь альянса западные чумные земли"}},{q="Для чего нужны чумные котлы на полях?",a="Erected by the Cult of the Damned at Felstone Field, Dalson's Tears, the Writhing Haunt, and Gahrron's Withering, these cauldrons pump constant plague vapors into the air and soil. Argent Dawn agents recruit adventurers to slay the Cauldron Lords and counter-engineer the toxic brews.",al={"what are the cauldrons","cauldron purpose","felstone cauldron"}},{q="Что такое Некроситет и где он находится?",a="Некроситет — подземная академия некромантии, которой управляют Плеть и Культ Проклятых. Она скрыта под руинами Каэр Дарроу, крепости на острове в юго-восточных водах Озера Дарроумир.",al={"scholomance location","where is scholomance","caer darrow dungeon","где находится некроситет","расположение некроситета","подземелье каэр дарроу"}},{q="Есть ли в Западных Чумных землях незараженные места?",a="Гробница Утера на Холме Печали у южного края зоны остается полностью священной и не тронутой порчей. Это освященный памятник павшему верховному генералу Утеру Светоносному и погибшему Ордену Серебряной Длани.",al={"holy ground in wpl","is uther tomb clean","uther's tomb safe","святая земля в западных чумных землях","чиста ли гробница утера","безопасна ли гробница утера"}}},fp="19,377,28.525.0,18.542.0,16.525.0,41.284.0,37.251.0,56.229.0,58.284.0,44.220.0,51.244.0"}
P.entries["zone:westfall"] = {n="Западный Край",s="Некогда плодородная житница Королевства Штормград, Западный Край превратился в продуваемую ветрами заброшенную землю, захваченную разбойниками. Лишенные королевской поддержки и военных гарнизонов, уцелевшие поселенцы цепляются за свои фермы, а Братство Справедливости все крепче сжимает хватку из покинутого шахтерского города Луноречье.",h="Некогда плодородная житница Королевства Штормград, Западный Край превратился в продуваемую ветрами...",kw={"deadmines","defias","harvest golem","militia","moonbrook","saldean","sentinel hill","stoutmantle","vancleef","westfall","мертвые копи","братство справедливости","жнец-голем","ополчение","луноречье","сальден","сторожевой холм","камнегрив","ван клиф","западный край"},ang={["class:Rogue"]="Теневая война в Западном Крае напрямую сталкивает шпионов ШРУ с уличными разведчиками, ворами и убийцами Братства Справедливости.",["faction:Alliance"]="Если бы Народное ополчение не удерживало Сторожевой холм, Братство Справедливости контролировало бы южные подступы прямо к Элвиннскому лесу.",["profession:Cooking"]="Осажденные поселенцы на Ферме Сальдена перебиваются жесткой местной дичью и учат путников готовить сытное блюдо, известное как Похлебка Западного Края.",["race:Human"]="Западный Край — болезненное отражение политического упадка Штормграда: фермеры, голодающие в грязи, были брошены той самой знатью, которую они трудились кормить."},sec={{t="Забытая земля",b="На протяжении поколений Западный Край кормил Королевство Штормград. Его холмистые пастбища и пшеничные поля процветали, пока после Второй войны не наступили финансовое истощение и политическое пренебрежение. Когда королевство направило ресурсы в другие места и не смогло содержать гарнизоны, земля опустела. Сегодня бесплодные пастбища, воющие прибрежные ветра, взбунтовавшиеся жнецы-големы и набеги гноллов Речной Лапы превращают ежедневное выживание в постоянное испытание для упрямцев, отказывающихся покидать свои дома."},{t="Возвышение Братства",b="Крах Западного Края ускорился, когда Гильдия каменщиков, не получив оплату за восстановление Штормграда, перешла к открытому мятежу. Объявленные вне закона и изгнанные под предводительством Эдвина ван Клифа, каменщики переформировались в Братство Справедливости. Они сделали Западный Край своим оплотом: жгли поля упрямых фермеров, засаливали почву и захватывали заброшенные шахты. Действуя из города-призрака Луноречье, Братство теперь правит большей частью сельской местности, хотя и не по названию."},{t="Народное ополчение",b="Пока Дом знати игнорировал бедственное положение Западного Края, местные жители взялись за собственную оборону. Гриан Камнегрив, обосновавшись в укрепленном посту Сторожевой холм, организовал Народное ополчение — отряд добровольцев, пытающийся сдержать гноллов и бандитов. Не имея ни регулярных солдат, ни снабжения из Штормграда, ополчение полагается на странствующих искателей приключений, чтобы отбросить волну Братства Справедливости и защитить оставшиеся фермы."},{t="Заговор в Мертвых копях",b="Истинный масштаб угрозы Братства Справедливости скрыт под землей. Глубоко в заброшенных золотых штольнях Мертвых копей под Луноречьем Эдвин ван Клиф собрал армию головорезов, гоблинов и отступников. Братство занято не простым разбоем: оно строит огромный броненосный корабль, который должен подняться вдоль побережья и обстрелять Штормград напрямую."}},faq={{q="Почему в Западном Крае так много заброшенных ферм?",a="Штормград вывел военные гарнизоны, когда их содержание стало слишком дорогим, и оставил регион без защиты. Вскоре Братство Справедливости захватило сельскую местность: прогнало поселенцев, сожгло посевы и перепрограммировало механических жнецов-сторожей в смертоносных часовых.",al={"abandoned farms","why is westfall dead","why fallow","заброшенные фермы","почему западный край мертв","почему земли пустуют"}},{q="Почему Штормград не присылает войска на помощь Западному Краю?",a="Казна королевства истощена, а Дом знати считает угрозы в других землях более важными. Кроме того, придворные интриги тихо лишили Западный Край внимания и поставок, и местные жители вынуждены полностью полагаться на себя.",al={"why no stormwind army","where are the guards","stormwind aid","почему нет армии штормграда","где стража","помощь штормграда"}},{q="Что такое Народное ополчение?",a="Народное ополчение — отряд добровольцев, организованный Грианом Камнегривом на Сторожевом холме. Поскольку корона отказалась отправлять солдат в Западный Край, оставшиеся фермеры и поселенцы объединились, чтобы бороться с Братством Справедливости и гноллами Речной Лапы.",al={"peoples militia","sentinel hill militia","gryan stoutmantle army","народное ополчение","ополчение сторожевого холма","армия гриана камнегрива"}},{q="Кто возглавляет Братство Справедливости в Западном Крае?",a="Эдвин ван Клиф, бывший глава Гильдии каменщиков, руководивший восстановлением Штормграда. После жесткого спора об оплате, приведшего к беспорядкам и гибели королевы Тиффин, ван Клиф увел своих рабочих в Западный Край и встал на путь вооруженного мятежа.",al={"defias leader","who leads defias","vancleef","лидер братства справедливости","кто возглавляет братство справедливости","ван клиф"}},{q="Что скрыто в Луноречье?",a="Под неприметным амбаром в Луноречье находится вход в Мертвые копи — обширную заброшенную золотую шахту, которую Братство Справедливости превратило в подземную крепость и верфь для войны против Штормграда.",al={"moonbrook secret","what is in deadmines","moonbrook mine","тайна луноречья","что в мертвых копях","шахта луноречья"}},{q="Почему механические пугала нападают на людей?",a="Изначально эти механические жнецы-сторожа были созданы, чтобы ухаживать за посевами и отпугивать вредителей, но гоблины-механики, связанные с Братством Справедливости, захватили и переделали их, чтобы они патрулировали поля и убивали любых чужаков.",al={"harvest golems attacking","harvest watchers","evil scarecrows","жнецы-големы нападают","жнецы-сторожа","злые пугала"}}},fp="8,337,18.502.0,27.479.0,20.427.0,24.379.1,44.289.0,52.262.0,29.269.0,45.267.0,32.226.1,51.200.0"}
P.entries["zone:wetlands"] = {n="Болотина",s="Болотина — обширное окутанное туманом болото, расположенное между горами Каз Модан и берегами Бухты Барадин. Исторически опустошаемая войнами дворфов и вторжениями орков, она служит суровой буферной зоной между Стальгорном и северными землями Лордерона. Укрепленный порт Гавань Менетилов — главная жизненная артерия Альянса в промокшей глуши, наводненной орками клана Драконьей Пасти, мурлоками и гноллами.",h="Болотина — обширное окутанное туманом болото, расположенное между горами Каз Модан и берегами Бухты Барадин.",kw={"baradin bay","dragonmaw","dun algaz","dun modr","grim batol","menethil","menethil harbor","thandol span","wetlands","бухта барадин","драконья пасть","дун альгаз","дун модр","грим батол","менетил","гавань менетилов","мост тандола","болотина"},ang={["faction:Alliance"]="Гавань Менетилов — главные глубоководные ворота Альянса через Великое море, связывающие королевства востока с экспедиционными заставами в Калимдоре.",["profession:Mining"]="В холмах и пещерных глубинах Пещеры Тельгена есть богатые рудные жилы, включая редкие залежи зажигательной руды, которую ценят дворфы-шахтеры и инженеры.",["race:Dwarf"]="Для дворфов Болотина — горькое место, отмеченное потерей Дун Модра, древней трагедией Грим Батола и непрекращающимся трудом по защите торгового пути короля Магни на север."},sec={{t="Земля воды и руин",b="Раскинувшаяся под высоким обрывом Каменной Плотины, Болотина — холодная, пропитанная водой равнина, укрытая вечным туманом и однообразным серым небом. Когда-то здесь были процветающие поселения дворфов, а теперь болота усеяны затонувшими каменными руинами, топкими трясинами и коварными топями. Путникам приходится пробираться узкими проходами: либо на север через забаррикадированное ущелье Дун Альгаз из Лок Модана, либо по высоким аркам Моста Тандола из Нагорья Арати."},{t="Шрамы Грим Батола",b="Над восточными окраинами болота мрачно возвышается Грим Батол, бывшая твердыня Громовых Молотов. После его осквернения во время Войны трех молотов он стал укрепленным оплотом клана Драконьей Пасти во время Второй войны. Когда красный драконий род вырвался из орочьего плена, его огненная месть сокрушила силы орков и опустошила окрестные склоны. Сегодня красные дракониды охраняют Врата Драконьей Пасти от всех нарушителей, а одичавшие остатки клана Драконьей Пасти живут в разбросанных лагерях на холмах и продолжают нападать на путников на болоте."},{t="Порт западного побережья",b="Гавань Менетилов, стоящая на краю Бухты Барадин, — бьющееся сердце торговли и снабжения Альянса в Каз Модане. Этот стойкий порт назван в честь короля Теренаса Менетила II и связывает Восточные королевства с далеким Калимдором регулярными кораблями до Аубердина и Острова Терамор. Несмотря на стратегическое значение и прочную дворфийскую архитектуру, гавань постоянно находится под угрозой прибрежных мурлоков, болотных тварей и береговых налетчиков, нападающих на суда в скалистых проливах."},{t="Осажденные рубежи",b="Болотина — активная зона боевых действий на нескольких фронтах. На дальнем севере дворфы Черного Железа под предводительством чернокнижника Балгораса Нечистого взорвали Мост Тандола и захватили городок Дун Модр, отрезав сухопутные обозы со снабжением. Тем временем гноллы Мохошкуров бесчинствуют в центральных топях, угрожая даже древним защитникам, таким как Ретиль Страж Природы. Из-за отколовшихся орочьих отрядов, лазутчиков Черного Железа и проклятых кораблекрушений вдоль побережья удержание болота требует постоянной бдительности."}},faq={{q="Как добраться до Болотины пешком?",a="Герои Альянса обычно идут на север из Лок Модана через горный проход Дун Альгаз. Путники Орды, идущие с севера, могут пересечь Мост Тандола из Нагорья Арати. Будьте осторожны: оба прохода оспариваются враждебными силами, такими как орки Драконьей Пасти и дворфы Черного Железа.",al={"how to get to wetlands","path to wetlands","run to wetlands","как добраться до болотины","путь в болотину","дорога в болотину"}},{q="Куда идут корабли из Гавани Менетилов?",a="Причалы Гавани Менетилов обслуживают два основных морских маршрута в Калимдор: один корабль плывет через Великое море в Аубердин на Темных берегах, а другой идет на юг к Острову Терамор в Пылевых топях.",al={"menethil boats","menethil harbor ships","where does the boat go in wetlands","корабли менетил","корабли гавани менетилов","куда плывет корабль в болотине"}},{q="Что такое Грим Батол и почему его охраняют?",a="Грим Батол — древняя дворфийская крепость, покинутая после Войны трех молотов и позже занятая кланом Драконьей Пасти. После Второй войны освобожденный красный драконий род изгнал орков и запечатал гору. Могучие красные дракониды патрулируют Врата Драконьей Пасти, чтобы никто не проник в проклятые залы.",al={"why are there dragons at grim batol","grim batol red dragons","dragonmaw gates","почему драконы в грим батоле","красные драконы грим батол","врата драконьей пасти"}},{q="Что случилось с Дун Модром?",a="Дун Модр был северной дворфийской твердыней, охранявшей Мост Тандола. Недавно на него напали и захватили дворфы Черного Железа под предводительством Балгораса Нечистого. Выжившие под началом Рага Каменщика держат неподалеку осажденный лагерь и сражаются за возвращение своего города.",al={"who destroyed dun modr","dun modr ruins","dark irons in dun modr","кто разрушил дун модр","руины дун модр","черное железо в дун модр"}},{q="Кто такой Ретиль Страж Природы?",a="Rethiel is an ancient bog beast residing in the Green Belt of the Wetlands. He seeks help from travelers to stem the tide of aggressive Mosshide gnolls and put down diseased Fen Creepers so the marshes can recover.",al={"green belt","rethiel wetlands","who is the greenwarden"}},{q="Откуда на болоте столько орков?",a="Эти орки принадлежат клану Драконьей Пасти, который изначально укрепился в Грим Батоле во время Второй войны. После разгрома освобожденным красным драконьим родом выжившие орки бежали вниз, на болота и в холмы, где до сих пор нападают на дороги и путников.",al={"why are there orcs in wetlands","wetlands dragonmaw","dragonmaw clan wetlands","почему орки в болотине","драконья пасть болотина","клан драконьей пасти болотина"}}},fp="8,418,24.524.0,23.601.0,22.527.0,18.503.0,40.301.0,41.216.0,41.343.0,26.268.0,31.214.0,46.277.0"}
P.entries["zone:winterspring"] = {n="Зимние Ключи",s="Зимние Ключи — обширная заснеженная долина высоко на северо-восточных склонах Горы Хиджал, прямо над зачарованными лесами Лунной поляны и Оскверненного леса. Край известен лютым холодом, древними руинами высокорожденных и бродящими хищниками; его опорой служит нейтральный гоблинский поселок Круговзор. Это земля суровых природных опасностей, дающая приют остаткам синего драконьего рода и противостоящая демонической порче на своих южных высотах.",h="Зимние Ключи — обширная заснеженная долина высоко на северо-восточных склонах Горы Хиджал, прямо над...",kw={"blue dragons","darkwhisper gorge","donova snowden","everlook","frostsaber","icecap","kel'theril","mazthoril","timbermaw","winterspring","синие драконы","теснина зловещего шепота","донова снегонора","круговзор","ледопард","ледяной зев","кел'терил","маззорил","древобрюх","зимние ключи"},ang={["class:Druid"]="Зимние Ключи, расположенные высоко над Лунной поляной, имеют священное значение как место, где Малфурион Ярость Бури пробудил Друидов Когтя от древнего сна во время Третьей войны.",["faction:Alliance"]="Герои Альянса часто навещают Риверна Холодного Ветра на Уступе Ледопардов, неустанно трудясь на лютом холоде, чтобы заслужить верность престижных ездовых ледопардов Зимних Ключей.",["profession:Herbalism"]="Зимние Ключи — единственное известное место обитания Ледяного зева, незаменимой альпийской травы, пользующейся большим спросом в сложных алхимических составах, а также разбросанного Горного серебряного шалфея и редких цветков Черного лотоса.",["profession:Mining"]="Ледяные утесы и стены пещер по всей долине богаты ценными минералами: здесь часто попадаются малые и богатые залежи тория, а также редкие жилы истинного серебра.",["race:NightElf"]="Зимние Ключи тесно связаны с историей эльфов: здесь находятся берлоги-курганы, где тысячелетиями покоились Друиды Когтя, трагические руины Кел'Терила и обнаженные корни Нордрассила, поврежденные во время битвы на Горе Хиджал."},sec={{t="Царство вечного мороза",b="Зимние Ключи, расположенные на тысячи футов выше окружающей глуши, лежат под прозрачным горным воздухом и непрестанными метелями. Огромные обнаженные корни Мирового Древа, Нордрассила, прорезают сугробы подобно высоким деревянным аркам, искривленные и скрученные во время решающих сражений Третьей войны. Если большая часть северного Калимдора покрыта густыми лесами и теплым климатом, то Зимние Ключи — тихая земля альпийских лесов средней густоты, скалистых утесов и замерзших озер, где обитают грозные ледопарды, химеры, йети и густошерстные зимние медведи."},{t="Перекрестки и заставы",b="Чтобы попасть на это высокое плато, нужно пройти по древним высеченным проходам Крепости Древобрюхов, которую охраняют неоскверненные фурболги, пристально проверяющие всех путников из Оскверненного леса или Лунной поляны. В центре долины находится Круговзор, процветающий торговый город под управлением Картеля Хитрая Шестеренка. Гоблины приветствуют и героев Альянса, и Орды с открытыми кассами, и город служит незаменимым убежищем инженерии, торговли и теплых очагов от пронзительного горного мороза."},{t="Старые призраки и синие драконы",b="За века до появления современных поселений древние эльфы построили на берегу озера город Кел'Терил. После того как безрассудные чародеи высокорожденных разбили проклятый Кристалл Зин-Малора, их охватило безумие, и беспокойные призраки до сих пор бродят среди разрушенных колонн и замерзших вод. Южнее возвышаются пещерные вершины Маззорила, традиционной твердыни синего драконьего рода в Калимдоре. Здесь выводок Хранителя чар Малигоса под надзором матери-защитницы Хале следит за арканными потоками и отражает местные угрозы."},{t="Грозная тень теснины",b="Покой Зимних Ключей резко нарушается на самой южной границе, в Теснине Зловещего Шепота. Там элитные демонические силы, остатки легионов Третьей войны, ползают по зазубренным каньонам, преграждая высокие подступы к вершине Горы Хиджал. Тем временем местные фурболги Зимней Спячки поддались скверной порче, и независимые исследователи, такие как Донова Снегонора, изучают наступающую порчу, пока не погибла вся живность долины."}},faq={{q="Как добраться до Зимних Ключей?",a="Путникам нужно пройти через Крепость Древобрюхов — сеть подземных туннелей на северо-востоке Оскверненного леса. Чтобы пройти пещерами мирно, нужно заслужить доверие местных фурболгов Древобрюхов, которые нападут на любого нарушителя, которого сочтут враждебным. Сразу за восточным выходом открываются заснеженные склоны Зимних Ключей.",al={"getting to winterspring","how to enter winterspring","winterspring entrance","timbermaw tunnel winterspring","как попасть в зимние ключи","как войти в зимние ключи","вход в зимние ключи","туннель древобрюхов зимние ключи"}},{q="Кто управляет городом Круговзор?",a="Круговзором управляет Картель Хитрая Шестеренка, гоблинский торговый конгломерат. Благодаря строгому стремлению гоблинов к прибыли и их нейтралитету путники и Орды, и Альянса могут пользоваться услугами его распорядителей полетов, торговцев-ремонтников, банковских хранилищ и товарами, если посетители не нарушают мир в черте города.",al={"who controls everlook","everlook faction","is everlook neutral","кто управляет круговзором","фракция круговзора","нейтрален ли круговзор"}},{q="Что за призраки обитают у Озера Кел'Терил?",a="Это духи ночных эльфов-высокорожденных, когда-то населявших древний город Кел'Терил десять тысяч лет назад. Когда их чародеи вмешались в украденный Кристалл Зин-Малора, его разрушение навлекло катастрофическое проклятие. Последующие экспедиции высших эльфов спустя века также были доведены до безумия и обречены бродить по замерзшим руинам рядом со своими предками.",al={"lake kel'theril ghosts","ruins of kel'theril spirits","who is at kel'theril","призраки озера кел'терил","руины кел'терил духи","кто в кел'териле"}},{q="Почему фурболги Зимней Спячки агрессивны?",a="Фурболги Зимней Спячки поддались распространяющейся неестественной порче, которая довела их клан до безумной враждебности. Тогда как соседние Древобрюхи крепко держатся за рассудок, Зимняя Спячка попала под темное влияние, и исследователи, такие как Донова Снегонора, изучают их порчу и зачищают их лагеря.",al={"why are winterfall hostile","winterfall tribe corruption","donova snowden furbolgs","почему зимняя спячка враждебна","порча племени зимняя спячка","донова снегонора фурболги"}},{q="Что обитает в Маззориле?",a="Маззорил — главное гнездо и убежище синего драконьего рода в Калимдоре. В глубине его пещерных шпилей дракониды, элитные дракончики и древние драконы охраняют могучие драконьи реликвии и тайны магии под бдительным взором Хале, супруги Аспекта Малигоса.",al={"mazthoril dragons","what is mazthoril","blue dragons in winterspring","драконы маззорила","что такое маззорил","синие драконы в зимних ключах"}},{q="Что такое Теснина Зловещего Шепота?",a="Теснина Зловещего Шепота — коварный каньон на самом юге долины, занятый могучими элитными демонами, оставшимися после Третьей войны. Это сильно охраняемый рубеж на опасных тропах, ведущих к высотам Горы Хиджал.",al={"darkwhisper gorge demons","what is in darkwhisper gorge","hyjal gate winterspring","демоны теснины зловещего шепота","что в теснине зловещего шепота","врата хиджала зимние ключи"}},{q="Можно ли здесь обучиться верховой езде или приручить ледопардов?",a="На Уступе Ледопардов на дальнем севере долины ночной эльф Риверн Холодный Ветер ухаживает за местными белыми кошками. Герои, помогающие ему добывать припасы и защищать стаю, могут доказать, что достойны узнать секреты воспитания и верховой езды на ледопарде.",al={"frostsaber mount","rivern frostwind frostsaber","how to get frostsaber","ездовой ледопард","риверн холодный ветер ледопард","как получить ледопарда"}}},fp="12,467,26.561.0,23.475.0,26.540.0,31.471.0,29.342.0,30.316.0,45.381.0,43.326.0,28.272.0,26.260.0,39.291.0"}
P.entries["zone:zephras"] = {n="Остров Зефрис",s="Остров Зефрис — парящий остров в Небесной выси, Элементальном Плане воздуха. Это изначальный родной дом Небожителей, чье общество переживает экзистенциальный кризис: поддерживающая остров магия неуклонно слабеет. Из-за потери связи с соседними небесными мирами его обитатели борются с элементальным распадом и прибывающими беженцами.",h="Остров Зефрис — парящий остров в Небесной выси, Элементальном Плане воздуха.",kw={"airships","anvilas","elemental plane","siroccas","skyborne","skywall","valanaar","windstones","zephras","воздушные корабли","анвилас","элементальный план","сирокка","небожители","небесная высь","валанаар","камни ветра","зефрис"},ang={["class:Shaman"]="Остров Зефрис, находящийся прямо в Элементальном Плане воздуха, показывает, что происходит с элементальными землями, когда духи, поддерживающие их равновесие, внезапно исчезают.",["race:Skyborne"]="Остров Зефрис — ваш родной дом и место, где вы начинаете путь, хотя его сохранившаяся красота скрывает острый кризис: рушащуюся землю и угасающую силу стихий."},sec={{t="Мир в вышине",b="Остров Зефрис — уединенный участок суши, дрейфующий в бескрайних ветрах Небесной выси. На протяжении поколений Небожители жили здесь бок о бок с местными элементалями воздуха, помогавшими поддерживать магические потоки, удерживающие остров в небе. Однако несколько веков назад эти элементальные хранители бесследно исчезли. Лишившись их присутствия и защиты, скрытые чары, на которых держится земля, начали постепенно ослабевать, и Зефрис медленно раскалывается и теряет устойчивость."},{t="Оборванные горизонты",b="Зефрис был не единственным убежищем Небожителей в Элементальном Плане. По Небесной выси также дрейфовали родственные острова Анвилас и Сирокка, но после исчезновения элементалей связь между ними прервалась. В последнее время беженцы с этих разрушающихся соседних островов сумели добраться до Зефриса в поисках спасения и принесли мрачные вести: остальные острова буквально распадаются у них под ногами."},{t="Врата в Азерот",b="Поскольку их собственная земля медленно разрушается, Небожители Зефрис начали смотреть за пределы Небесной выси в сторону Азерота. С небесных доков Валанаара теперь отправляются дирижабли, чтобы проложить редкие связи со смертным миром. Эти рейсы напрямую соединяют воздушное владение с точками Азерота, включая окраины Даларана в Альтеракских горах и Плато звездочетов в Мулгоре."}},faq={{q="Где находится Остров Зефрис?",a="Остров Зефрис расположен в Небесной выси, Элементальном Плане воздуха, а не на поверхности Азерота. Он плывет среди вечных облаков и воздушных потоков этого эфирного мира.",al={"zephras isle location","where is zephras","what plane is zephras on","остров зефрис где находится","где зефрис","на каком плане зефрис"}},{q="Почему Остров Зефрис разрушается?",a="Остров зависел от присутствия местных элементалей воздуха, некогда живших рядом с Небожителями. Несколько веков назад эти элементали исчезли, и магические основы, удерживающие и сохраняющие парящую землю, со временем медленно слабеют и распадаются.",al={"why is zephras collapsing","zephras isle destruction","dying island","почему зефрис разрушается","разрушение острова зефрис","умирающий остров"}},{q="Что такое Анвилас и Сирокка?",a="Это соседние парящие острова в Небесной выси, также населенные Небожителями. Остров Зефрис потерял связь с обоими, когда элементали исчезли, а беженцы теперь сообщают, что и Анвилас, и Сирокка исчезают в небытии.",al={"anvilas","siroccas","other skyborne islands","анвилас","сирокка","другие острова небожителей"}},{q="Как добраться с Острова Зефрис в Азерот?",a="Небожители содержат небесные доки в поселении Валанаар. Дирижабли отправляются из этих доков через границу миров к Азероту и приземляются возле Даларана в Альтеракских горах и на Плато звездочетов в Мулгоре.",al={"how to leave zephras","zephras airships","travel to azeroth","как покинуть зефрис","воздушные корабли зефрис","путь в азерот"}},{q="Кто такие Небожители?",a="Небожители — обитатели, чей дом находится на Острове Зефрис и в соседних небесных мирах. Прожив в Небесной выси много поколений, они теперь сталкиваются с медленным разрушением своей парящей родины, поскольку скрепляющая ее магия угасает.",al={"skyborne race","who lives on zephras","небожители раса","кто живет на зефрисе"}},{q="Кто живет на Острове Зефрис, кроме Небожителей?",a="Помимо мирных деревень и прибывших беженцев, остров беспокоят местные бандиты, пещерные ночные когти и звери, обитающие в таких местах, как Пещера визгунов и Пещера Когтя Ночи.",al={"zephras inhabitants","enemies on zephras","жители зефриса","враги на зефрисе"}}},fp="12,364,13.457.0,16.440.0,20.405.0,30.189.0,34.257.0,30.248.0,54.216.0,21.226.0,47.194.0"}
